def _pick_env_file() -> str:
    argv = sys.argv
    if "--env" in argv:
        i = argv.index("--env")
        if i + 1 < len(argv):
            p = argv[i + 1]
            del argv[i:i + 2]
            if not os.path.isabs(p):
                p = str(BASE_DIR / p)
            return p
    p = (os.getenv("ENV_FILE") or os.getenv("ENV_PATH") or "").strip()
    if p:
        if not os.path.isabs(p):
            p = str(BASE_DIR / p)
        return p
    return str(BASE_DIR / ".env")


def _pick_manager_arg() -> str:
    argv = sys.argv
    if "--manager" in argv:
        i = argv.index("--manager")
        if i + 1 < len(argv):
            k = argv[i + 1]
            del argv[i:i + 2]
            return registry_normalize_manager_key(k)
    return ""


