# -------------------- small utils --------------------
def _now_utc_iso() -> str:
    return _tp_utc_now().replace(microsecond=0).isoformat()


def _future_iso(seconds: int) -> str:
    return (_tp_utc_now() + timedelta(seconds=int(seconds))).replace(microsecond=0).isoformat()


def _future_iso_max(seconds: int, minimum_seconds: int = 0) -> str:
    return _future_iso(max(int(seconds or 0), int(minimum_seconds or 0)))


