def _iso_to_local_hhmm(iso_value: str) -> str:
    try:
        dt = datetime.fromisoformat(str(iso_value or ""))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(TZ_KYIV).strftime("%H:%M")
    except Exception:
        return "_"


def _event_utc_iso(event: events.NewMessage.Event) -> str:
    try:
        dt = getattr(event.message, "date", None)
        if dt:
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return dt.astimezone(timezone.utc).replace(tzinfo=None, microsecond=0).isoformat()
    except Exception:
        pass
    return _now_utc_iso()


def _utc_iso_to_kyiv_dt(iso_value: str) -> datetime:
    try:
        dt = datetime.fromisoformat(str(iso_value or ""))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(TZ_KYIV)
    except Exception:
        return _kyiv_now()


