async def _table_exists(db: aiosqlite.Connection, table: str) -> bool:
    try:
        cur = await db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=? LIMIT 1", (table,))
        return bool(await cur.fetchone())
    except Exception:
        return False


async def _table_columns(db: aiosqlite.Connection, table: str) -> List[str]:
    try:
        cur = await db.execute(f"PRAGMA table_info({table});")
        rows = await cur.fetchall()
        return [str(r[1]) for r in rows]
    except Exception:
        return []


async def _ensure_daily_leads_table(db_path: str) -> None:
    p = str(db_path or "").strip()
    if not p:
        return
    parent = os.path.dirname(p)
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(p) as db:
        await db.execute("PRAGMA journal_mode=WAL;")
        await db.execute(DAILY_TABLE_SQL)
        cols = await _table_columns(db, "daily_leads")
        daily_migrations = [
            ("age", "ALTER TABLE daily_leads ADD COLUMN age INTEGER"),
            ("city", "ALTER TABLE daily_leads ADD COLUMN city TEXT DEFAULT ''"),
            ("region", "ALTER TABLE daily_leads ADD COLUMN region TEXT DEFAULT ''"),
            ("country", "ALTER TABLE daily_leads ADD COLUMN country TEXT DEFAULT ''"),
            ("city_raw", "ALTER TABLE daily_leads ADD COLUMN city_raw TEXT DEFAULT ''"),
            ("country_raw", "ALTER TABLE daily_leads ADD COLUMN country_raw TEXT DEFAULT ''"),
            ("geo_source", "ALTER TABLE daily_leads ADD COLUMN geo_source TEXT DEFAULT ''"),
            ("geo_confidence", "ALTER TABLE daily_leads ADD COLUMN geo_confidence TEXT DEFAULT ''"),
            ("geo_note", "ALTER TABLE daily_leads ADD COLUMN geo_note TEXT DEFAULT ''"),
            ("status", "ALTER TABLE daily_leads ADD COLUMN status TEXT DEFAULT ''"),
            ("nonliquid_reason", "ALTER TABLE daily_leads ADD COLUMN nonliquid_reason TEXT DEFAULT ''"),
            ("profile_done", "ALTER TABLE daily_leads ADD COLUMN profile_done INTEGER NOT NULL DEFAULT 0"),
            ("profile_question_sent", "ALTER TABLE daily_leads ADD COLUMN profile_question_sent INTEGER NOT NULL DEFAULT 0"),
            ("profile_question_at", "ALTER TABLE daily_leads ADD COLUMN profile_question_at TEXT DEFAULT ''"),
            ("profile_answered_at", "ALTER TABLE daily_leads ADD COLUMN profile_answered_at TEXT DEFAULT ''"),
            ("ua_text_sent", "ALTER TABLE daily_leads ADD COLUMN ua_text_sent INTEGER NOT NULL DEFAULT 0"),
            ("ua_text_sent_at", "ALTER TABLE daily_leads ADD COLUMN ua_text_sent_at TEXT DEFAULT ''"),
            ("manager_work_status", "ALTER TABLE daily_leads ADD COLUMN manager_work_status TEXT DEFAULT ''"),
            ("offline_notice_sent", "ALTER TABLE daily_leads ADD COLUMN offline_notice_sent INTEGER NOT NULL DEFAULT 0"),
            ("offline_notice_period_key", "ALTER TABLE daily_leads ADD COLUMN offline_notice_period_key TEXT DEFAULT ''"),
            ("manager_replied", "ALTER TABLE daily_leads ADD COLUMN manager_replied INTEGER NOT NULL DEFAULT 0"),
            ("manager_replied_at", "ALTER TABLE daily_leads ADD COLUMN manager_replied_at TEXT DEFAULT ''"),
            ("clarify_attempts", "ALTER TABLE daily_leads ADD COLUMN clarify_attempts INTEGER NOT NULL DEFAULT 0"),
            ("profile_final_sent", "ALTER TABLE daily_leads ADD COLUMN profile_final_sent INTEGER NOT NULL DEFAULT 0"),
            ("profile_final_sent_at", "ALTER TABLE daily_leads ADD COLUMN profile_final_sent_at TEXT DEFAULT ''"),
            ("geoage_sent", "ALTER TABLE daily_leads ADD COLUMN geoage_sent INTEGER NOT NULL DEFAULT 0"),
            ("geoage_sent_at", "ALTER TABLE daily_leads ADD COLUMN geoage_sent_at TEXT DEFAULT ''"),
        ]
        for col, ddl in daily_migrations:
            if col not in cols:
                try:
                    await db.execute(ddl)
                except Exception:
                    pass
        for ddl in [
            "CREATE INDEX IF NOT EXISTS daily_leads_date_idx ON daily_leads(lead_date, manager_key)",
            "CREATE INDEX IF NOT EXISTS daily_leads_unsent_idx ON daily_leads(ai_stat_sent, first_seen_utc)",
            "CREATE INDEX IF NOT EXISTS daily_leads_chat_idx ON daily_leads(chat_id, first_seen_utc)",
            "CREATE INDEX IF NOT EXISTS daily_leads_status_idx ON daily_leads(lead_date, status, country, age)",
        ]:
            try:
                await db.execute(ddl)
            except Exception:
                pass
        await db.commit()


async def _record_daily_lead_event(
    *,
    db_path: str,
    manager_key: str,
    manager_username: str,
    chat_id: int,
    username: str,
    full_name: str,
    phone: str,
    first_seen_utc: str,
) -> Tuple[bool, Dict[str, Any]]:
    await _ensure_daily_leads_table(db_path)
    dt_kyiv = _utc_iso_to_kyiv_dt(first_seen_utc)
    lead_date = dt_kyiv.date().isoformat()
    first_seen_kyiv = dt_kyiv.strftime("%Y-%m-%d %H:%M:%S")
    now = _now_utc_iso()
    async with aiosqlite.connect(db_path) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            """
            INSERT OR IGNORE INTO daily_leads(
                lead_date, manager_key, manager_username, chat_id, username, full_name, phone,
                first_seen_utc, first_seen_kyiv, created_at, updated_at
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                lead_date,
                registry_normalize_manager_key(manager_key),
                str(manager_username or ""),
                int(chat_id),
                str(username or ""),
                str(full_name or ""),
                str(phone or ""),
                str(first_seen_utc),
                first_seen_kyiv,
                now,
                now,
            ),
        )
        created = bool((cur.rowcount or 0) > 0)
        await db.execute(
            """
            UPDATE daily_leads
            SET username=CASE WHEN ?<>'' THEN ? ELSE username END,
                full_name=CASE WHEN ?<>'' THEN ? ELSE full_name END,
                phone=CASE WHEN ?<>'' THEN ? ELSE phone END,
                manager_username=CASE WHEN ?<>'' THEN ? ELSE manager_username END,
                updated_at=?
            WHERE lead_date=? AND manager_key=? AND chat_id=?
            """,
            (
                str(username or ""), str(username or ""),
                str(full_name or ""), str(full_name or ""),
                str(phone or ""), str(phone or ""),
                str(manager_username or ""), str(manager_username or ""),
                now,
                lead_date,
                registry_normalize_manager_key(manager_key),
                int(chat_id),
            ),
        )
        cur2 = await db.execute(
            "SELECT * FROM daily_leads WHERE lead_date=? AND manager_key=? AND chat_id=? LIMIT 1",
            (lead_date, registry_normalize_manager_key(manager_key), int(chat_id)),
        )
        row = await cur2.fetchone()
        await db.commit()
        return created, (dict(row) if row else {})


async def _update_daily_lead_fields(db_path: str, *, lead_date: str, manager_key: str, chat_id: int, **fields: Any) -> None:
    if not fields:
        return
    await _ensure_daily_leads_table(db_path)
    allowed = {
        "age", "city", "region", "country", "city_raw", "country_raw", "geo_source", "geo_confidence", "geo_note",
        "status", "nonliquid_reason", "profile_done", "profile_question_sent", "profile_question_at", "profile_answered_at",
        "ua_text_sent", "ua_text_sent_at", "manager_work_status", "offline_notice_sent", "offline_notice_period_key",
        "manager_replied", "manager_replied_at", "clarify_attempts", "profile_final_sent", "profile_final_sent_at", "geoage_sent", "geoage_sent_at", "updated_at",
    }
    data = {k: v for k, v in fields.items() if k in allowed}
    if not data:
        return
    data["updated_at"] = data.get("updated_at") or _now_utc_iso()
    keys = list(data.keys())
    vals = [data[k] for k in keys]
    sql = "UPDATE daily_leads SET " + ", ".join([f"{k}=?" for k in keys]) + " WHERE lead_date=? AND manager_key=? AND chat_id=?"
    vals.extend([str(lead_date), registry_normalize_manager_key(manager_key), int(chat_id)])
    async with aiosqlite.connect(db_path) as db:
        await db.execute(sql, tuple(vals))
        await db.commit()


async def _ensure_lead_auto_state_table(db_path: str) -> None:
    if not db_path:
        return
    parent = os.path.dirname(db_path)
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(db_path) as db:
        await db.execute("""
            CREATE TABLE IF NOT EXISTS lead_auto_state(
                chat_id INTEGER PRIMARY KEY,
                manager_replied INTEGER NOT NULL DEFAULT 0,
                manager_replied_at TEXT DEFAULT '',
                profile_question_sent INTEGER NOT NULL DEFAULT 0,
                profile_question_at TEXT DEFAULT '',
                ua_text_sent INTEGER NOT NULL DEFAULT 0,
                ua_text_sent_at TEXT DEFAULT '',
                offline_notice_period_key TEXT DEFAULT '',
                offline_notice_sent_at TEXT DEFAULT '',
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        # TPILOT CLOSER STOPWORD GATE 20260716: additive, idempotent -- a durable
        # per-lead automation stop that, once set, is never auto-cleared and is
        # never overwritten by a later duplicate trigger (see
        # _set_lead_automation_stopped). Existing rows/DBs get the columns lazily
        # on next open; ALTER failures (column already exists) are swallowed.
        for ddl in (
            "ALTER TABLE lead_auto_state ADD COLUMN automation_stopped INTEGER NOT NULL DEFAULT 0",
            "ALTER TABLE lead_auto_state ADD COLUMN automation_stopped_reason TEXT NOT NULL DEFAULT ''",
            "ALTER TABLE lead_auto_state ADD COLUMN automation_stopped_at TEXT",
        ):
            try:
                await db.execute(ddl)
            except Exception:
                pass
        await db.commit()


async def _get_auto_state(db_path: str, chat_id: int) -> Dict[str, Any]:
    await _ensure_lead_auto_state_table(db_path)
    now = _now_utc_iso()
    async with aiosqlite.connect(db_path) as db:
        db.row_factory = aiosqlite.Row
        await db.execute(
            "INSERT OR IGNORE INTO lead_auto_state(chat_id, created_at, updated_at) VALUES(?,?,?)",
            (int(chat_id), now, now),
        )
        cur = await db.execute("SELECT * FROM lead_auto_state WHERE chat_id=?", (int(chat_id),))
        row = await cur.fetchone()
        await db.commit()
        return dict(row) if row else {"chat_id": int(chat_id)}


async def _set_auto_state_fields(db_path: str, chat_id: int, **fields: Any) -> None:
    await _ensure_lead_auto_state_table(db_path)
    if not fields:
        return
    await _get_auto_state(db_path, chat_id)
    fields = dict(fields)
    fields["updated_at"] = _now_utc_iso()
    keys = list(fields.keys())
    vals = [fields[k] for k in keys]
    sql = "UPDATE lead_auto_state SET " + ", ".join([f"{k}=?" for k in keys]) + " WHERE chat_id=?"
    vals.append(int(chat_id))
    async with aiosqlite.connect(db_path) as db:
        await db.execute(sql, tuple(vals))
        await db.commit()


async def _set_lead_automation_stopped(db_path: str, chat_id: int, reason: str = "manual_stop_word") -> None:
    """Durable, permanent per-lead automation stop. Idempotent: if this lead is
    already stopped, this is a no-op -- the FIRST automation_stopped_at/reason is
    never overwritten by a later duplicate stop-word trigger. No code path clears
    this flag; it survives restart because it lives in lead_auto_state (the same
    per-manager db table already loaded on every inbound message)."""
    await _ensure_lead_auto_state_table(db_path)
    existing = await _get_auto_state(db_path, chat_id)
    if int((existing or {}).get("automation_stopped") or 0) == 1:
        return
    await _set_auto_state_fields(
        db_path, chat_id,
        automation_stopped=1,
        automation_stopped_reason=str(reason or "manual_stop_word")[:200],
        automation_stopped_at=_now_utc_iso(),
    )


async def _mark_manager_replied(db_path: str, chat_id: int) -> None:
    now = _now_utc_iso()
    await _set_auto_state_fields(db_path, chat_id, manager_replied=1, manager_replied_at=now)
    try:
        if MANAGER_RUNTIME_KEY:
            await _note_manager_manual_out(MANAGER_RUNTIME_KEY)
    except Exception:
        pass
    await _ensure_daily_leads_table(db_path)
    async with aiosqlite.connect(db_path) as db:
        await db.execute(
            "UPDATE daily_leads SET manager_replied=1, manager_replied_at=?, updated_at=? WHERE chat_id=?",
            (now, now, int(chat_id)),
        )
        await db.commit()


async def _ensure_work_status_table() -> None:
    parent = os.path.dirname(TPILOT_DB_PATH)
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute("""
            CREATE TABLE IF NOT EXISTS manager_work_status(
                manager_key TEXT PRIMARY KEY,
                status TEXT NOT NULL DEFAULT 'online',
                offline_period_key TEXT DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT '',
                updated_by_user_id INTEGER,
                last_manual_out_utc TEXT DEFAULT '',
                auto_offline_at TEXT DEFAULT '',
                last_status_source TEXT DEFAULT ''
            );
        """)
        cols = await _table_columns(db, "manager_work_status")
        migrations = [
            ("last_manual_out_utc", "ALTER TABLE manager_work_status ADD COLUMN last_manual_out_utc TEXT DEFAULT ''"),
            ("auto_offline_at", "ALTER TABLE manager_work_status ADD COLUMN auto_offline_at TEXT DEFAULT ''"),
            ("last_status_source", "ALTER TABLE manager_work_status ADD COLUMN last_status_source TEXT DEFAULT ''"),
        ]
        for col, ddl in migrations:
            if col not in cols:
                try:
                    await db.execute(ddl)
                except Exception:
                    pass
        await db.commit()


async def _get_manager_work_status(manager_key: str) -> Dict[str, Any]:
    key = registry_normalize_manager_key(manager_key or "")
    if not key:
        return {"status": "online", "offline_period_key": ""}
    await _ensure_work_status_table()
    await _tpilot_patch_init()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM manager_work_status WHERE manager_key=?", (key,))
        row = await cur.fetchone()
        if row:
            return dict(row)
        return {"manager_key": key, "status": "online", "offline_period_key": "", "updated_at": "", "updated_by_user_id": None, "last_manual_out_utc": "", "auto_offline_at": "", "last_status_source": ""}


async def _set_manager_work_status(manager_key: str, status: str, *, user_id: int = 0, source: str = "manual") -> Dict[str, Any]:
    key = registry_normalize_manager_key(manager_key or "")
    raw = str(status or "online").strip().lower()
    aliases = {
        "workday": "online",
        "work": "online",
        "on": "online",
        "worknow": "worknow",
        "daymode": "worknow",
        "now": "worknow",
        "force": "worknow",
        "off": "offline",
        "inactive": "auto_offline",
        "auto": "auto_offline",
    }
    st = aliases.get(raw, raw)
    if st not in {"online", "worknow", "offline", "dayoff", "no_show", "auto_offline"}:
        st = "online"
    if not key:
        return {}
    await _ensure_work_status_table()
    now = _now_utc_iso()
    old = await _get_manager_work_status(key)
    old_status = str((old or {}).get("status") or "online").strip().lower()
    offline_period_key = str((old or {}).get("offline_period_key") or "")
    if st == "online":
        offline_period_key = ""
    elif old_status != st or not offline_period_key:
        offline_period_key = f"{key}:{st}:{int(time.time())}"
    auto_offline_at = now if st == "auto_offline" else str((old or {}).get("auto_offline_at") or "")
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute(
            """
            INSERT INTO manager_work_status(manager_key, status, offline_period_key, updated_at, updated_by_user_id, auto_offline_at, last_status_source)
            VALUES(?,?,?,?,?,?,?)
            ON CONFLICT(manager_key) DO UPDATE SET
                status=excluded.status,
                offline_period_key=excluded.offline_period_key,
                updated_at=excluded.updated_at,
                updated_by_user_id=excluded.updated_by_user_id,
                auto_offline_at=excluded.auto_offline_at,
                last_status_source=excluded.last_status_source
            """,
            (key, st, offline_period_key, now, int(user_id or 0) or None, auto_offline_at, str(source or "manual")),
        )
        await db.commit()
    return {"manager_key": key, "status": st, "offline_period_key": offline_period_key, "updated_at": now, "auto_offline_at": auto_offline_at, "last_status_source": str(source or "manual")}


async def _note_manager_manual_out(manager_key: str) -> None:
    key = registry_normalize_manager_key(manager_key or "")
    if not key:
        return
    await _ensure_work_status_table()
    now = _now_utc_iso()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute(
            """
            INSERT INTO manager_work_status(manager_key, status, offline_period_key, updated_at, last_manual_out_utc, last_status_source)
            VALUES(?,?,?,?,?,?)
            ON CONFLICT(manager_key) DO UPDATE SET
                status='worknow',
                offline_period_key='',
                last_manual_out_utc=excluded.last_manual_out_utc,
                updated_at=excluded.updated_at,
                last_status_source=excluded.last_status_source
            """,
            (key, "worknow", "", now, now, "manual_activity"),
        )
        await db.commit()


async def _manager_key_from_status_sender(user_id: int) -> str:
    try:
        rows = await manager_list_rows(include_removed=False)
    except Exception:
        rows = []
    # TPILOT PREPARED ACCOUNTS PHASE 3: this resolves a WORK_STATUS_CHAT_ID
    # sender's Telegram identity to a manager_key so /online, /offline,
    # /dayoff, /workday, /worknow can mutate that key's work status (see the
    # caller at ~main.py:4438/4457). A prepared account's real Telegram
    # account CAN send messages independent of whether its runtime is
    # spawned -- excluded here so a prepared account's own tg_user_id/
    # owner_user_id can never resolve into a work-status mutation target.
    rows = [r for r in (rows or []) if str(r.get("status") or "").strip().lower() != "prepared"]
    uid = int(user_id or 0)
    for row in rows or []:
        if int(row.get("tg_user_id") or 0) == uid:
            return registry_normalize_manager_key(row.get("manager_key") or "")
    for row in rows or []:
        if int(row.get("owner_user_id") or 0) == uid:
            return registry_normalize_manager_key(row.get("manager_key") or "")
    return ""


async def _fetch_unsent_daily_leads(db_path: str, limit: int = 200) -> List[Dict[str, Any]]:
    if not db_path or not os.path.exists(db_path):
        return []
    await _ensure_daily_leads_table(db_path)
    async with aiosqlite.connect(db_path) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            "SELECT * FROM daily_leads WHERE COALESCE(ai_stat_sent,0)=0 ORDER BY first_seen_utc ASC, id ASC LIMIT ?",
            (int(limit),),
        )
        return [dict(r) for r in await cur.fetchall()]


async def _mark_daily_lead_sent(db_path: str, row_id: int, *, duplicate: bool) -> None:
    await _ensure_daily_leads_table(db_path)
    async with aiosqlite.connect(db_path) as db:
        await db.execute(
            "UPDATE daily_leads SET duplicate=?, duplicate_checked=1, ai_stat_sent=1, updated_at=? WHERE id=?",
            (1 if duplicate else 0, _now_utc_iso(), int(row_id)),
        )
        await db.commit()


async def _old_lead_exists(db_path: str, chat_id: int) -> bool:
    if not db_path or not os.path.exists(db_path):
        return False
    try:
        async with aiosqlite.connect(db_path) as db:
            if not await _table_exists(db, "leads"):
                return False
            cur = await db.execute("SELECT 1 FROM leads WHERE chat_id=? LIMIT 1", (int(chat_id),))
            return bool(await cur.fetchone())
    except Exception:
        return False


async def _prior_daily_exists(db_path: str, chat_id: int, current_id: int, current_first_seen_utc: str) -> bool:
    if not db_path or not os.path.exists(db_path):
        return False
    try:
        await _ensure_daily_leads_table(db_path)
        async with aiosqlite.connect(db_path) as db:
            cur = await db.execute(
                """
                SELECT 1 FROM daily_leads
                WHERE chat_id=?
                  AND id<>?
                  AND (
                        first_seen_utc < ?
                        OR COALESCE(ai_stat_sent,0)=1
                        OR COALESCE(duplicate_checked,0)=1
                  )
                LIMIT 1
                """,
                (int(chat_id), int(current_id), str(current_first_seen_utc or "")),
            )
            return bool(await cur.fetchone())
    except Exception:
        return False


async def _is_duplicate_systemwide(event_row: Dict[str, Any], manager_db_paths: List[str], batch_seen: set[int], current_db_path: str) -> bool:
    chat_id = int(event_row.get("chat_id") or 0)
    if chat_id <= 0:
        return False
    if chat_id in batch_seen:
        return True

    # Old base compatibility: if chat_id ever existed in legacy leads of any manager DB, it is a duplicate.
    for dbp in manager_db_paths:
        if await _old_lead_exists(dbp, chat_id):
            return True

    cur_id = int(event_row.get("id") or 0)
    cur_ts = str(event_row.get("first_seen_utc") or "")
    for dbp in manager_db_paths:
        if await _prior_daily_exists(dbp, chat_id, cur_id if os.path.abspath(dbp) == os.path.abspath(current_db_path) else -1, cur_ts):
            return True
    return False


async def _list_daily_leads_for_db(db_path: str, lead_date: str) -> List[Dict[str, Any]]:
    if not db_path or not os.path.exists(db_path):
        return []
    await _ensure_daily_leads_table(db_path)
    async with aiosqlite.connect(db_path) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            "SELECT * FROM daily_leads WHERE lead_date=? ORDER BY first_seen_utc ASC, id ASC",
            (str(lead_date),),
        )
        return [dict(r) for r in await cur.fetchall()]


async def _manager_rows_for_reporting() -> List[Dict[str, Any]]:
    # DELETED MANAGER STATS RETENTION 20260711 (period-filter correction): this is
    # once again LIVE-ONLY by default -- no tombstones. An earlier revision unioned
    # hard-deleted managers here unconditionally (gated only by the 60-day retention
    # window), which meant EVERY caller of this function -- including the ~35
    # non-report/operational callers (unanswered alerts, /lead repair, health/
    # quality/presence loops, bizlink helpers, etc.) -- started seeing deleted
    # managers too, and a deleted manager appeared in TODAY's stats even with zero
    # data for today, just because retention_until was still in the future. Fixed:
    # tombstones are now opt-in ONLY via _manager_rows_for_reporting_period(start,
    # end), which additionally requires the report period to be eligible (see
    # _tp_mgrret_tombstone_eligible_for_period). Every caller below that does NOT
    # pass a period intentionally stays fail-closed to live-only.
    rows = await manager_list_rows(include_removed=False)
    out = []
    for r in rows:
        key = registry_normalize_manager_key(r.get("manager_key") or "")
        if not key:
            continue
        # TPILOT PREPARED ACCOUNTS PHASE 3: a prepared account has no
        # runtime, so every consumer of this function that queues a
        # manager-process command and waits for it (e.g. /tghealth check
        # all -> _tp_hg_queue_check_for_manager, 45s timeout per manager)
        # would otherwise block for the full timeout and report a false
        # offline/error status. Excluded here, at the single reporting
        # choke point, rather than in each of the ~35 callers individually.
        # storage.manager_list_rows itself stays unfiltered -- only this
        # function's OUTPUT is narrowed.
        if str(r.get("status") or "").strip().lower() == "prepared":
            continue
        db_path = str(r.get("db_path") or build_manager_paths(str(BASE_DIR), key)["db_path"])
        if not os.path.isabs(db_path):
            db_path = str((BASE_DIR / db_path).resolve())
        rr = dict(r)
        rr["manager_key"] = key
        rr["db_path"] = db_path
        out.append(rr)
    return out


async def _tp_mgrret_tombstone_eligible_for_period(tombstone_row: Dict[str, Any], period_start: str, period_end: str) -> bool:
    """DELETED MANAGER STATS RETENTION 20260711 (period-filter correction): decide
    whether a tombstoned (hard-deleted) manager belongs in a report covering
    [period_start, period_end] (both 'YYYY-MM-DD', inclusive). Deletion date is
    always a HARD UPPER BOUND -- the check range is clamped to end at deleted_at's
    own calendar date, so a manager can never resurface for a date after their own
    deletion, no matter how far in the future retention_until still reaches:
      1. period fully after deleted_at's date -> excluded outright (no I/O at all).
      2. else: real historical daily_leads exist in the (deletion-clamped) period
         (backup per-manager DB, opened strictly read-only) -> included.
      3. else: the manager was scheduled/working on at least one day in the
         (deletion-clamped) period (manager_work_schedule_days survives a full
         delete -- it is not one of the tables _panel_manager_delete_full_command
         clears) -> included.
      4. else -> excluded.
    Never writes to the backup DB. Never raises -- any I/O failure along the way
    is treated as "no evidence found" for that source, falling through to the next
    check (fail-closed overall: no evidence anywhere -> excluded)."""
    deleted_at = str(tombstone_row.get("deleted_at") or "")
    deleted_date = deleted_at[:10]
    p_start = str(period_start or "")[:10]
    p_end = str(period_end or "")[:10]
    if not deleted_date or not p_start or not p_end:
        return False
    if p_start > deleted_date:
        return False  # report period is fully after the deletion date
    check_start = p_start
    check_end = min(p_end, deleted_date)
    if check_start > check_end:
        return False

    manager_key = registry_normalize_manager_key(tombstone_row.get("manager_key") or "")
    if not manager_key:
        return False

    db_path = str(tombstone_row.get("db_path") or "")
    if db_path and not os.path.isabs(db_path):
        db_path = str((BASE_DIR / db_path).resolve())
    if db_path and os.path.exists(db_path):
        try:
            async with aiosqlite.connect(f"file:{db_path}?mode=ro", uri=True) as db:
                cur = await db.execute(
                    "SELECT 1 FROM daily_leads WHERE lead_date BETWEEN ? AND ? LIMIT 1",
                    (check_start, check_end),
                )
                if await cur.fetchone():
                    return True
        except Exception:
            pass

    # Schedule/working fallback -- only reached when there is no historical data in
    # the clamped period. Bounded loop (hard safety cap) so a malformed/huge range
    # can never turn this into an unbounded scan; per-tombstone-manager only, and
    # tombstones are rare, so the worst case is cheap.
    try:
        from storage import manager_schedule_is_working as _sched_is_working
        cur_date = datetime.strptime(check_start, "%Y-%m-%d").date()
        end_date = datetime.strptime(check_end, "%Y-%m-%d").date()
        days_checked = 0
        while cur_date <= end_date and days_checked < 366:
            if _sched_is_working(manager_key, cur_date.isoformat(), db_path=TPILOT_DB_PATH):
                return True
            cur_date += timedelta(days=1)
            days_checked += 1
    except Exception:
        pass
    return False


async def _manager_rows_for_reporting_period(period_start_iso: str, period_end_iso: str) -> List[Dict[str, Any]]:
    """DELETED MANAGER STATS RETENTION 20260711 (period-filter correction):
    period-aware variant of _manager_rows_for_reporting. Same live-row enumeration,
    PLUS tombstoned (hard-deleted) managers whose retention window is still active
    AND whose [period_start_iso, period_end_iso] report period is eligible per
    _tp_mgrret_tombstone_eligible_for_period (real historical data or a scheduled/
    working day in the deletion-clamped period -- never a date after deletion). A
    live row always wins a manager_key collision. Only call this from a genuine
    stats/reporting path that has a determinate report period; every other caller
    must keep using the plain (live-only) _manager_rows_for_reporting()."""
    out = await _manager_rows_for_reporting()
    if not period_start_iso or not period_end_iso:
        return out
    seen_keys = {registry_normalize_manager_key(r.get("manager_key") or "") for r in out}
    try:
        from storage import manager_stats_tombstone_list_active as _tombstones_active
        tombstones = _tombstones_active(retention_days=60, db_path=TPILOT_DB_PATH)
    except Exception:
        tombstones = []
    for t in tombstones or []:
        key = registry_normalize_manager_key(t.get("manager_key") or "")
        if not key or key in seen_keys:
            continue
        if not await _tp_mgrret_tombstone_eligible_for_period(t, period_start_iso, period_end_iso):
            continue
        db_path = str(t.get("db_path") or "")
        if db_path and not os.path.isabs(db_path):
            db_path = str((BASE_DIR / db_path).resolve())
        out.append({
            "manager_key": key,
            "display_name": str(t.get("display_name") or key),
            "telegram_username": str(t.get("telegram_username") or ""),
            "db_path": db_path,
            "status": "deleted",  # renders " (удалён)"/" (аккаунт удалён)" via
                                   # _manager_label_from_row / stats_engine.se_manager_label
            "is_enabled": 0,
            "removed": 1,
        })
        seen_keys.add(key)
    return out


async def _collect_day_leads(lead_date: str, target_key: str = "all") -> List[Dict[str, Any]]:
    rows = await _manager_rows_for_reporting_period(lead_date, lead_date)
    target_key = registry_normalize_manager_key(target_key or "all")
    result: List[Dict[str, Any]] = []
    for mgr in rows:
        key = registry_normalize_manager_key(mgr.get("manager_key") or "")
        if target_key != "all" and key != target_key:
            continue
        for lead in await _list_daily_leads_for_db(str(mgr.get("db_path") or ""), lead_date):
            item = dict(lead)
            item["manager_key"] = key or item.get("manager_key") or ""
            item["manager_display_name"] = str(mgr.get("display_name") or key)
            item["manager_username"] = str(mgr.get("telegram_username") or item.get("manager_username") or "")
            result.append(item)
    result.sort(key=lambda x: (str(x.get("first_seen_utc") or ""), str(x.get("manager_key") or ""), int(x.get("id") or 0)))
    return result


async def _build_stat_text(target_key: str = "all", lead_date: Optional[str] = None) -> str:
    lead_date = lead_date or _kyiv_now().date().isoformat()
    rows = await _manager_rows_for_reporting()
    leads = await _collect_day_leads(lead_date, target_key=target_key)
    stats = _stats_from_leads(leads, rows, target_key=target_key)
    date_disp = datetime.strptime(lead_date, "%Y-%m-%d").strftime("%d.%m.%y")

    lines = [f"📊 Статистика за {date_disp}", ""]
    for b in stats["buckets"]:
        lines.append(str(b["label"]))
        lines.append(f"Всего написавших: {int(b['total'])}")
        lines.append(f"Новые: {int(b['new'])}")
        lines.append(f"Дубликаты: {int(b['duplicates'])}")
        lines.append(f"Ответили возраст/гео: {int(b['profile_done'])}")
        lines.append(f"Ликвид: {int(b['liquid'])}")
        lines.append(f"Неликвид: {int(b['nonliquid'])}")
        lines.append(f"Не определено: {int(b['unknown'])}")
        lines.append(f"Возраст не определено: {int(b['missing_age'])}")
        lines.append(f"Город не определено: {int(b['missing_city'])}")
        lines.append(f"Страна не определено: {int(b['missing_country'])}")
        _append_reason_lines(lines, b.get("reasons") or {})
        lines.append("")
    if not stats["buckets"]:
        lines.append("Менеджеры не найдены.")
        return chr(10).join(lines).rstrip()
    if registry_normalize_manager_key(target_key or "all") == "all":
        lines.append("Итого:")
        lines.append(f"Всего написавших: {int(stats['total'])}")
        lines.append(f"Новые: {int(stats['new'])}")
        lines.append(f"Дубликаты: {int(stats['duplicates'])}")
        lines.append(f"Ответили возраст/гео: {int(stats['profile_done'])}")
        lines.append(f"Ликвид: {int(stats['liquid'])}")
        lines.append(f"Неликвид: {int(stats['nonliquid'])}")
        lines.append(f"Не определено: {int(stats['unknown'])}")
        lines.append(f"Возраст не определено: {int(stats['missing_age'])}")
        lines.append(f"Город не определено: {int(stats['missing_city'])}")
        lines.append(f"Страна не определено: {int(stats['missing_country'])}")
        _append_reason_lines(lines, stats.get("reasons") or {})
    return chr(10).join(lines).rstrip()


async def _export_day_xlsx(target_key: str = "all", lead_date: Optional[str] = None) -> str:
    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font, Alignment
        from openpyxl.utils import get_column_letter
    except Exception as e:
        raise RuntimeError("openpyxl не установлен. Установите: pip install openpyxl") from e

    lead_date = lead_date or _kyiv_now().date().isoformat()
    target_key = registry_normalize_manager_key(target_key or "all")
    leads = await _collect_day_leads(lead_date, target_key=target_key)
    os.makedirs(EXPORT_DIR, exist_ok=True)
    suffix = "all" if target_key == "all" else target_key
    out_path = os.path.join(EXPORT_DIR, f"leads_{lead_date}_{suffix}.xlsx")

    wb = Workbook()
    ws = wb.active
    ws.title = "leads"
    headers = [
        "№", "Дата", "Время", "manager_key", "Аккаунт менеджера", "chat_id", "username", "Имя аккаунта", "Телефон", "Дубликат",
        "Возраст", "Город", "Регион", "Страна", "Статус", "Причина неликвида", "Источник гео", "Точность", "Пометка", "Режим менеджера", "Вопрос отправлен", "Offline-сообщение", "UA текст", "Менеджер ответил",
    ]
    ws.append(headers)
    for cell in ws[1]:
        cell.font = Font(bold=True)
        cell.alignment = Alignment(horizontal="center")

    for idx, r in enumerate(leads, 1):
        dt = _utc_iso_to_kyiv_dt(str(r.get("first_seen_utc") or ""))
        manager_username = str(r.get("manager_username") or "").strip()
        manager_display = str(r.get("manager_display_name") or r.get("manager_key") or "").strip()
        manager_account = f"{manager_display} | @{manager_username}" if manager_username else manager_display
        status_raw = str(r.get("status") or "").strip()
        status_disp = "ликвид" if status_raw == "liquid" else ("неликвид" if status_raw == "nonliquid" else "не определено")
        ws.append([
            idx,
            dt.strftime("%d.%m.%Y"),
            dt.strftime("%H:%M:%S"),
            str(r.get("manager_key") or ""),
            manager_account,
            int(r.get("chat_id") or 0),
            _display_username(str(r.get("username") or "")) if str(r.get("username") or "").strip() else "_",
            str(r.get("full_name") or "").strip() or "_",
            str(r.get("phone") or "").strip() or "_",
            "да" if int(r.get("duplicate") or 0) == 1 else "нет",
            _display_unknown(r.get("age")),
            _display_unknown(r.get("city")),
            _display_unknown(r.get("region")),
            _display_unknown(r.get("country")),
            status_disp,
            str(r.get("nonliquid_reason") or "").strip() or "_",
            str(r.get("geo_source") or "").strip() or "_",
            str(r.get("geo_confidence") or "").strip() or "_",
            str(r.get("geo_note") or "").strip() or "_",
            str(r.get("manager_work_status") or "").strip() or "_",
            "да" if int(r.get("profile_question_sent") or 0) == 1 else "нет",
            "да" if int(r.get("offline_notice_sent") or 0) == 1 else "нет",
            "да" if int(r.get("ua_text_sent") or 0) == 1 else "нет",
            "да" if int(r.get("manager_replied") or 0) == 1 else "нет",
        ])

    widths = [6, 14, 13, 18, 28, 18, 22, 28, 18, 12, 12, 22, 28, 18, 16, 22, 18, 14, 28, 18, 18, 18, 12, 18]
    for i, width in enumerate(widths, 1):
        ws.column_dimensions[get_column_letter(i)].width = width
    ws.freeze_panes = "A2"
    wb.save(out_path)
    return out_path


async def _send_geoage(text: str) -> bool:
    # GeoAge uses the same group as WORK_STATUS_CHAT_ID by project decision.
    if not WORK_STATUS_CHAT_ID:
        return False
    try:
        await client.send_message(int(WORK_STATUS_CHAT_ID), str(text or ""))
        return True
    except Exception as e:
        print(f"GEOAGE send error: {e!r}")
        return False


def _nonempty(value: Any) -> str:
    return str(value or "").strip()


def _append_field(lines: List[str], label: str, value: Any, *, show_unknown: bool = False) -> None:
    v = _nonempty(value)
    if v:
        lines.append(f"{label}: {v}")
    elif show_unknown:
        lines.append(f"{label}: не определено")


def _format_geoage_card(row: Dict[str, Any], manager_label: str = "") -> str:
    status = _nonempty(row.get("status")).lower()
    country = _nonempty(row.get("country"))
    reason = _nonempty(row.get("nonliquid_reason"))
    if status == "liquid":
        header = f"✅ Ликвид - {country or 'Россия'}"
    elif status == "nonliquid":
        header = f"🚫 Неликвид - {reason or country or 'не определено'}"
    else:
        header = "⚠️ Не определено"

    lines: List[str] = [header, "", "👤 Лид"]
    _append_field(lines, "ID", int(row.get("chat_id") or 0))
    username = _nonempty(row.get("username"))
    if username:
        lines.append("Telegram: " + (username if username.startswith("@") else "@" + username))
    _append_field(lines, "Имя", row.get("full_name"))
    _append_field(lines, "Телефон", row.get("phone"))
    if manager_label:
        _append_field(lines, "Менеджер", manager_label)

    lines += ["", "📋 Анкета"]
    unknown = status not in ("liquid", "nonliquid")
    _append_field(lines, "Возраст", row.get("age"), show_unknown=unknown and row.get("age") is None)
    _append_field(lines, "Страна", row.get("country"), show_unknown=unknown and not country)
    _append_field(lines, "Регион", row.get("region"))
    _append_field(lines, "Город", row.get("city"), show_unknown=unknown and not _nonempty(row.get("city")))
    if status == "nonliquid" and reason:
        _append_field(lines, "Причина", reason)
    note = _nonempty(row.get("geo_note"))
    if note:
        _append_field(lines, "Пометка", note)
    return chr(10).join(lines).rstrip()


async def _fetch_pending_geoage_leads(db_path: str, limit: int = 200) -> List[Dict[str, Any]]:
    if not db_path or not os.path.exists(db_path):
        return []
    await _ensure_daily_leads_table(db_path)
    async with aiosqlite.connect(db_path) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            """
            SELECT * FROM daily_leads
            WHERE COALESCE(geoage_sent,0)=0
              AND COALESCE(status,'')<>''
              AND (
                    COALESCE(profile_done,0)=1
                    OR COALESCE(profile_final_sent,0)=1
                    OR status IN ('liquid','nonliquid')
                  )
            ORDER BY first_seen_utc ASC, id ASC
            LIMIT ?
            """,
            (int(limit),),
        )
        return [dict(r) for r in await cur.fetchall()]


async def _mark_geoage_sent(db_path: str, row_id: int) -> None:
    await _ensure_daily_leads_table(db_path)
    now = _now_utc_iso()
    async with aiosqlite.connect(db_path) as db:
        await db.execute(
            "UPDATE daily_leads SET geoage_sent=1, geoage_sent_at=?, updated_at=? WHERE id=?",
            (now, now, int(row_id)),
        )
        await db.commit()


async def _process_pending_geoage_events() -> None:
    if not CONTROLLER_MODE:
        return
    if not WORK_STATUS_CHAT_ID:
        return
    rows = await _manager_rows_for_reporting()
    for mgr in rows:
        db_path = str(mgr.get("db_path") or "")
        manager_label = _manager_label_from_row(mgr) if mgr else ""
        for item in await _fetch_pending_geoage_leads(db_path, limit=200):
            msg = _format_geoage_card(item, manager_label)
            if await _send_geoage(msg):
                await _mark_geoage_sent(db_path, int(item.get("id") or 0))
                await asyncio.sleep(0.2)


