# 2026-08-22) -- pure stdlib datetime parser.
_parse_utc_naive_dt = text_format_helpers.parse_utc_naive_dt


def _is_profile_day_window(now_local: Optional[datetime] = None) -> bool:
    dt = now_local or _kyiv_now()
    return int(WORK_DAY_START_HOUR) <= int(dt.hour) < int(WORK_DAY_END_HOUR)


async def _notify_work_status_auto(text: str) -> None:
    if not WORK_STATUS_CHAT_ID:
        return
    try:
        await client.send_message(int(WORK_STATUS_CHAT_ID), str(text or ""))
    except Exception:
        pass


async def _process_auto_offline() -> None:
    if not CONTROLLER_MODE or not AUTO_OFFLINE_ENABLED:
        return
    now_local = _kyiv_now()
    day0 = now_local.replace(hour=0, minute=0, second=0, microsecond=0)
    work_start_local = day0.replace(hour=int(WORK_DAY_START_HOUR), minute=0, second=0, microsecond=0)
    work_end_local = day0.replace(hour=int(WORK_DAY_END_HOUR), minute=0, second=0, microsecond=0)
    no_show_local = day0.replace(hour=int(NO_SHOW_CHECK_HOUR), minute=int(NO_SHOW_CHECK_MINUTE), second=0, microsecond=0)
    work_start_utc = work_start_local.astimezone(timezone.utc).replace(tzinfo=None, microsecond=0)
    now_utc_naive = _tp_utc_now().replace(microsecond=0)

    rows = await manager_list_rows(include_removed=False)
    for row in rows or []:
        key = registry_normalize_manager_key(row.get("manager_key") or "")
        if not key:
            continue
        try:
            if str(row.get("status") or "") != "active" or int(row.get("is_enabled") or 0) != 1 or int(row.get("manual_stopped") or 0) == 1:
                continue
        except Exception:
            continue

        st = await _get_manager_work_status(key)
        current_status = str(st.get("status") or "online").strip().lower()
        if current_status not in {"online", "worknow"}:
            continue

        last_dt = _parse_utc_naive_dt(_nonempty(st.get("last_manual_out_utc")))
        updated_dt = _parse_utc_naive_dt(_nonempty(st.get("updated_at")))
        source = str(st.get("last_status_source") or "").strip().lower()
        manual_today = bool(last_dt and last_dt >= work_start_utc)
        manual_online_today = bool(source == "manual" and updated_dt and updated_dt >= work_start_utc)
        active_ref = last_dt if (last_dt and last_dt >= work_start_utc) else (updated_dt if (manual_online_today and updated_dt) else work_start_utc)

        # 08:30 no-show: active manager did not start working today.
        # Manual /online counts as start of work, but if there are no manual outgoing answers for 90 minutes,
        # the daytime inactivity rule below will move the account back to auto_offline.
        if current_status == "online" and now_local >= no_show_local and now_local < work_end_local and not manual_today and not manual_online_today:
            changed = await _set_manager_work_status(key, "no_show", user_id=0, source="no_show")
            if changed:
                await _notify_work_status_auto(f"🌙 {key}: no_show, ручных ответов с {WORK_DAY_START_HOUR:02d}:00 не было. Клиентам будет уходить сообщение нерабочего вре��ени.")
            continue

        # Inactivity: ordinary online is checked in the work window; forced worknow is checked even at night.
        if (work_start_local <= now_local < work_end_local) or current_status == "worknow":
            ref = active_ref
            if (now_utc_naive - ref) >= timedelta(minutes=int(AUTO_OFFLINE_INACTIVITY_MINUTES or 90)):
                changed = await _set_manager_work_status(key, "auto_offline", user_id=0, source="auto_inactive")
                if changed:
                    await _notify_work_status_auto(f"🌙 {key}: auto_offline, нет ручных ответов {AUTO_OFFLINE_INACTIVITY_MINUTES} минут. Клиентам будет уходить сообщение нерабочего времени.")


