async def _ensure_profile_reminder_table(db_path: str) -> None:
    if not db_path:
        return
    parent = os.path.dirname(db_path)
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(db_path) as db:
        await db.execute("""
            CREATE TABLE IF NOT EXISTS lead_profile_reminders(
                chat_id INTEGER PRIMARY KEY,
                first_lead_date TEXT DEFAULT '',
                first_question_at TEXT DEFAULT '',
                reminder_step INTEGER NOT NULL DEFAULT 0,
                last_sent_at_utc TEXT DEFAULT '',
                last_daily_sent_date TEXT DEFAULT '',
                last_text TEXT DEFAULT '',
                trash INTEGER NOT NULL DEFAULT 0,
                trash_reason TEXT DEFAULT '',
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        await db.commit()


async def _upsert_profile_reminder_state(db_path: str, lead: Dict[str, Any]) -> Dict[str, Any]:
    await _ensure_profile_reminder_table(db_path)
    now = _now_utc_iso()
    chat_id = int(lead.get("chat_id") or 0)
    if chat_id <= 0:
        return {}
    async with aiosqlite.connect(db_path) as db:
        db.row_factory = aiosqlite.Row
        await db.execute(
            """
            INSERT OR IGNORE INTO lead_profile_reminders(chat_id, first_lead_date, first_question_at, created_at, updated_at)
            VALUES(?,?,?,?,?)
            """,
            (
                chat_id,
                str(lead.get("lead_date") or ""),
                str(lead.get("profile_question_at") or ""),
                now,
                now,
            ),
        )
        await db.execute(
            """
            UPDATE lead_profile_reminders
            SET first_lead_date=CASE WHEN COALESCE(first_lead_date,'')='' THEN ? ELSE first_lead_date END,
                first_question_at=CASE WHEN COALESCE(first_question_at,'')='' THEN ? ELSE first_question_at END,
                updated_at=?
            WHERE chat_id=?
            """,
            (str(lead.get("lead_date") or ""), str(lead.get("profile_question_at") or ""), now, chat_id),
        )
        cur = await db.execute("SELECT * FROM lead_profile_reminders WHERE chat_id=?", (chat_id,))
        row = await cur.fetchone()
        await db.commit()
        return dict(row) if row else {}


async def _get_profile_reminder_state(db_path: str, chat_id: int) -> Dict[str, Any]:
    await _ensure_profile_reminder_table(db_path)
    async with aiosqlite.connect(db_path) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM lead_profile_reminders WHERE chat_id=?", (int(chat_id),))
        row = await cur.fetchone()
        return dict(row) if row else {}


async def _set_profile_reminder_state(db_path: str, chat_id: int, **fields: Any) -> None:
    await _ensure_profile_reminder_table(db_path)
    if not fields:
        return
    await _get_profile_reminder_state(db_path, chat_id)
    fields = dict(fields)
    fields["updated_at"] = _now_utc_iso()
    allowed = {
        "first_lead_date", "first_question_at", "reminder_step", "last_sent_at_utc",
        "last_daily_sent_date", "last_text", "trash", "trash_reason", "updated_at",
    }
    data = {k: v for k, v in fields.items() if k in allowed}
    if not data:
        return
    keys = list(data.keys())
    vals = [data[k] for k in keys]
    sql = "UPDATE lead_profile_reminders SET " + ", ".join([f"{k}=?" for k in keys]) + " WHERE chat_id=?"
    vals.append(int(chat_id))
    async with aiosqlite.connect(db_path) as db:
        await db.execute(sql, tuple(vals))
        await db.commit()


async def _mark_profile_reminder_trash(db_path: str, chat_id: int, reason: str = "trash") -> None:
    if int(chat_id or 0) <= 0:
        return
    now = _now_utc_iso()
    await _ensure_profile_reminder_table(db_path)
    async with aiosqlite.connect(db_path) as db:
        await db.execute(
            """
            INSERT OR IGNORE INTO lead_profile_reminders(chat_id, created_at, updated_at)
            VALUES(?,?,?)
            """,
            (int(chat_id), now, now),
        )
        await db.execute(
            "UPDATE lead_profile_reminders SET trash=1, trash_reason=?, updated_at=? WHERE chat_id=?",
            (str(reason or "trash"), now, int(chat_id)),
        )
        await db.commit()


async def _profile_reminder_trash_map(db_path: str) -> Dict[int, Dict[str, Any]]:
    out: Dict[int, Dict[str, Any]] = {}
    if not db_path or not os.path.exists(db_path):
        return out
    await _ensure_profile_reminder_table(db_path)
    async with aiosqlite.connect(db_path) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT chat_id, trash, trash_reason FROM lead_profile_reminders WHERE COALESCE(trash,0)=1")
        for row in await cur.fetchall():
            d = dict(row)
            try:
                out[int(d.get("chat_id") or 0)] = d
            except Exception:
                pass
    return out


def _local_to_utc_iso(dt_local: datetime) -> str:
    return dt_local.astimezone(timezone.utc).replace(tzinfo=None, microsecond=0).isoformat()


def _det_window_local(kind: str, ref: Optional[datetime] = None) -> Tuple[datetime, datetime, str, str]:
    """Return local project-time window for detailed day stats or flight stats.

    day:
      current calendar day, 08:00-17:00.
    flight:
      before 08:00 -> yesterday 17:00 - today 08:00;
      08:00-16:59 -> last completed night window, yesterday 17:00 - today 08:00;
      from 17:00 -> current night window, today 17:00 - tomorrow 08:00.
    """
    now = ref or _kyiv_now()
    if now.tzinfo is None:
        now = now.replace(tzinfo=TZ_KYIV)
    now = now.astimezone(TZ_KYIV)
    day0 = now.replace(hour=0, minute=0, second=0, microsecond=0)
    kind = str(kind or "day").lower()

    if kind == "flight":
        if now.hour >= 17:
            start_local = day0.replace(hour=17, minute=0, second=0, microsecond=0)
        else:
            start_local = (day0 - timedelta(days=1)).replace(hour=17, minute=0, second=0, microsecond=0)
        end_local = start_local + timedelta(hours=15)
        label = f"{start_local.strftime('%d.%m.%y')} - {end_local.strftime('%d.%m.%y')}"
        title = "🌙 Долёты"
        return start_local, end_local, label, title

    start_local = day0.replace(hour=8, minute=0, second=0, microsecond=0)
    end_local = day0.replace(hour=17, minute=0, second=0, microsecond=0)
    label = start_local.strftime("%d.%m.%y")
    title = "📊 Статистика"
    return start_local, end_local, label, title


def _det_window(kind: str, ref: Optional[datetime] = None) -> Tuple[str, str, str, str]:
    start_local, end_local, label, title = _det_window_local(kind, ref)
    return _local_to_utc_iso(start_local), _local_to_utc_iso(end_local), label, title


def _lead_first_seen_local_dt(lead: Dict[str, Any]) -> Optional[datetime]:
    raw_local = str((lead or {}).get("first_seen_kyiv") or "").strip()
    if raw_local:
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(raw_local[:19], fmt).replace(tzinfo=TZ_KYIV)
            except Exception:
                pass
    raw_utc = str((lead or {}).get("first_seen_utc") or "").strip()
    if raw_utc:
        try:
            return _utc_iso_to_kyiv_dt(raw_utc)
        except Exception:
            pass
    return None


async def _list_daily_leads_for_db_range(db_path: str, start_utc_iso: str, end_utc_iso: str) -> List[Dict[str, Any]]:
    """Return daily_leads inside the requested window.

    Fetch candidate rows by lead_date and then filter in Python by local first_seen time.
    This avoids false zeroes when a night window crosses midnight or when timestamps are stored
    in different string formats.
    """
    if not db_path or not os.path.exists(db_path):
        return []
    await _ensure_daily_leads_table(db_path)

    start_local = _utc_iso_to_kyiv_dt(str(start_utc_iso))
    end_local = _utc_iso_to_kyiv_dt(str(end_utc_iso))
    start_date = (start_local.date() - timedelta(days=1)).isoformat()
    end_date = (end_local.date() + timedelta(days=1)).isoformat()

    async with aiosqlite.connect(db_path) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            """
            SELECT * FROM daily_leads
            WHERE lead_date>=? AND lead_date<=?
            ORDER BY first_seen_utc ASC, first_seen_kyiv ASC, id ASC
            """,
            (start_date, end_date),
        )
        rows = [dict(r) for r in await cur.fetchall()]

    out: List[Dict[str, Any]] = []
    for row in rows:
        dt_local = _lead_first_seen_local_dt(row)
        if not dt_local:
            continue
        if start_local <= dt_local < end_local:
            out.append(row)
    return out

def _is_reminder_work_time(now: Optional[datetime] = None) -> bool:
    dt = now or _kyiv_now()
    return PROFILE_REMINDER_WORK_START_HOUR <= int(dt.hour) < PROFILE_REMINDER_WORK_END_HOUR


async def _profile_reminders_allowed_now() -> bool:
    if _is_reminder_work_time():
        return True
    if not MANAGER_RUNTIME_KEY:
        return False
    try:
        st = await _get_manager_work_status(MANAGER_RUNTIME_KEY)
        return str(st.get("status") or "").strip().lower() == "worknow"
    except Exception:
        return False


def _next_work_start_local(now: Optional[datetime] = None) -> datetime:
    dt = now or _kyiv_now()
    start = dt.replace(hour=PROFILE_REMINDER_WORK_START_HOUR, minute=0, second=0, microsecond=0)
    if dt.hour >= PROFILE_REMINDER_WORK_END_HOUR:
        start = (dt + timedelta(days=1)).replace(hour=PROFILE_REMINDER_WORK_START_HOUR, minute=0, second=0, microsecond=0)
    return start


# _parse_utc_naive moved to text_format_helpers.py (extraction pass #3,
# 2026-08-22) -- pure stdlib datetime parser (identical body to
# _parse_utc_naive_dt, kept as a separate alias since both names are used
# by different call sites).
_parse_utc_naive = text_format_helpers.parse_utc_naive


def _choose_daily_reminder_text(last_text: str = "") -> str:
    pool = [x for x in PROFILE_REMINDER_DAILY_TEXTS if str(x or "").strip()]
    if not pool:
        return PROFILE_REMINDER_SECOND_TEXT
    if last_text and len(pool) > 1:
        pool2 = [x for x in pool if x != last_text]
        if pool2:
            pool = pool2
    return random.choice(pool)


def _reminder_due_text(lead: Dict[str, Any], state: Dict[str, Any], now_utc: datetime, today_local: str) -> str:
    if int(state.get("trash") or 0) == 1:
        return ""
    if int(lead.get("manager_replied") or 0) == 1:
        return ""
    if int(lead.get("profile_question_sent") or 0) != 1:
        return ""
    if int(lead.get("profile_done") or 0) == 1 and str(lead.get("status") or "").strip().lower() in ("liquid", "nonliquid"):
        return ""
    if int(lead.get("profile_final_sent") or 0) == 1:
        return ""
    status = str(lead.get("status") or "").strip().lower()
    if status in ("liquid", "nonliquid"):
        return ""

    step = int(state.get("reminder_step") or 0)
    q_at = _parse_utc_naive(str(lead.get("profile_question_at") or state.get("first_question_at") or "")) or now_utc
    last_sent = _parse_utc_naive(str(state.get("last_sent_at_utc") or ""))

    if step <= 0:
        if now_utc >= q_at + timedelta(minutes=10):
            return PROFILE_REMINDER_FIRST_TEXT
        return ""
    if step == 1:
        base = last_sent or q_at
        if now_utc >= base + timedelta(hours=3):
            return PROFILE_REMINDER_SECOND_TEXT
        return ""
    if step == 2:
        base = last_sent or q_at
        if now_utc >= base + timedelta(hours=3):
            return PROFILE_REMINDER_THIRD_TEXT
        return ""

    # Following days: one random reminder per local day.
    lead_date = str(lead.get("lead_date") or state.get("first_lead_date") or "")
    if lead_date >= today_local:
        return ""
    if str(state.get("last_daily_sent_date") or "") == today_local:
        return ""
    return _choose_daily_reminder_text(str(state.get("last_text") or ""))


async def _fetch_reminder_candidates(db_path: str, limit: int = 200) -> List[Dict[str, Any]]:
    if not db_path or not os.path.exists(db_path):
        return []
    await _ensure_daily_leads_table(db_path)
    await _ensure_profile_reminder_table(db_path)
    async with aiosqlite.connect(db_path) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            """
            SELECT d.*
            FROM daily_leads d
            LEFT JOIN lead_profile_reminders r ON r.chat_id=d.chat_id
            WHERE COALESCE(d.profile_question_sent,0)=1
              AND COALESCE(d.manager_replied,0)=0
              AND COALESCE(r.trash,0)=0
              AND COALESCE(d.status,'') NOT IN ('liquid','nonliquid')
              AND COALESCE(d.profile_final_sent,0)=0
            ORDER BY d.profile_question_at ASC, d.first_seen_utc ASC, d.id ASC
            LIMIT ?
            """,
            (int(limit),),
        )
        return [dict(r) for r in await cur.fetchall()]


def _looks_like_trash_message(text: str) -> bool:
    t = str(text or "").strip().lower()
    if not t:
        return False
    trash_patterns = [
        r"\bхуй\w*\b", r"\bпизд\w*\b", r"\bеба\w*\b", r"\bёба\w*\b",
        r"\bнахуй\b", r"\bпош[её]л\b", r"\bсука\b", r"\bмраз\w*\b",
        r"\bотвали\b", r"\bиди\s+на\b",
    ]
    return any(re.search(p, t, flags=re.IGNORECASE) for p in trash_patterns)


async def _process_profile_reminders_once() -> int:
    if CONTROLLER_MODE or not MANAGER_RUNTIME_KEY:
        return 0
    if not await _profile_reminders_allowed_now():
        return 0
    # TPILOT HEALTH RECOVERY HYBRID-D 20260723: profile reminders only ever
    # reply within a dialog the manager account has already sent into before
    # (the lead was already greeted/asked earlier) -- central gate check
    # up front so a BLOCKED account skips the whole tick without doing any
    # candidate/text-building work first.
    try:
        gate_allowed_tick, _gr = await _tp_hg_send_allowed(MANAGER_RUNTIME_KEY, new_dialog=False)
    except Exception:
        gate_allowed_tick = False
    if not gate_allowed_tick:
        return 0
    now_utc = _tp_utc_now().replace(microsecond=0)
    today_local = _kyiv_now().date().isoformat()
    sent = 0
    for lead in await _fetch_reminder_candidates(DB_PATH, limit=200):
        chat_id = int(lead.get("chat_id") or 0)
        if chat_id <= 0:
            continue
        gate_allowed, _gate_reason = await _lead_automation_gate(MANAGER_RUNTIME_KEY, chat_id, "profile_reminder")
        if not gate_allowed:
            continue
        state = await _upsert_profile_reminder_state(DB_PATH, lead)
        text = _reminder_due_text(lead, state, now_utc, today_local)
        if not text:
            continue
        ok, fail_kind = await _send_manager_private_ex(chat_id, text, human_delay=True, after_first_delay=True, new_dialog=False)
        if not ok:
            if fail_kind in ("gate_denied", "restriction"):
                # PEERFLOOD RECOVERY 20260812: a health-gate denial (BLOCKED /
                # manual mark / unexpired FloodWait cooldown) or a classified
                # Telegram restriction from this very send (PeerFlood/
                # FloodWait/BLOCKED) is never an ordinary delivery failure --
                # never trash the lead for it. Leave this and remaining
                # reminders pending for a later tick instead (owner-approved
                # "one probe per tick": stop trying further sends this tick).
                print(f"profile_reminder send paused manager={MANAGER_RUNTIME_KEY} chat_id={chat_id} reason={fail_kind}")
                break
            await _mark_profile_reminder_trash(DB_PATH, chat_id, "send_failed")
            continue
        step = int(state.get("reminder_step") or 0) + 1
        fields = {
            "reminder_step": step,
            "last_sent_at_utc": _now_utc_iso(),
            "last_text": text,
        }
        if step >= 4:
            fields["last_daily_sent_date"] = today_local
        await _set_profile_reminder_state(DB_PATH, chat_id, **fields)
        sent += 1
        # Anti-ban spacing: after a reminder, wait 50-60 minutes before the next one.
        await asyncio.sleep(random.randint(PROFILE_REMINDER_BATCH_MIN_MINUTES * 60, PROFILE_REMINDER_BATCH_MAX_MINUTES * 60))
        break
    return sent


async def _profile_reminder_loop() -> None:
    if CONTROLLER_MODE or not MANAGER_RUNTIME_KEY:
        return
    while True:
        try:
            if not await _profile_reminders_allowed_now():
                nxt = _next_work_start_local()
                await asyncio.sleep(max(60, min(900, (nxt - _kyiv_now()).total_seconds())))
                continue
            sent = await _process_profile_reminders_once()
            if sent <= 0:
                await asyncio.sleep(60)
        except asyncio.CancelledError:
            return
        except Exception as e:
            print(f"profile_reminder_loop error: {e!r}")
            await asyncio.sleep(60)


async def _send_scheduled_det_reports_if_due() -> None:
    if not CONTROLLER_MODE:
        return
    now = _kyiv_now()
    today = now.date().isoformat()

    # 08:00: flights for the previous 17:00-08:00 window.
    if now.hour >= 8:
        flag = f"flight_report_sent_{today}"
        if (await get_setting(flag)) != "1":
            await _process_pending_lead_events()
            try:
                await _process_pending_geoage_events()
            except Exception:
                pass
            await _send_ai_stat(await _build_det_stat_text("all", "flight", now))
            await set_setting(flag, "1")

    # 17:00: final day detailed stats for 08:00-17:00.
    if now.hour >= 17:
        flag = f"day_det_report_sent_{today}"
        if (await get_setting(flag)) != "1":
            await _process_pending_lead_events()
            try:
                await _process_pending_geoage_events()
            except Exception:
                pass
            await _send_ai_stat(await _build_det_stat_text("all", "day", now))
            await set_setting(flag, "1")


