async def _ensure_partner_lead_events_table() -> None:
    parent = os.path.dirname(TPILOT_DB_PATH)
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute("""
            CREATE TABLE IF NOT EXISTS partner_lead_events(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                event_key TEXT UNIQUE NOT NULL DEFAULT '',
                source_key TEXT NOT NULL DEFAULT '',
                manager_key TEXT NOT NULL DEFAULT '',
                manager_display_name TEXT DEFAULT '',
                manager_username TEXT DEFAULT '',
                lead_id INTEGER NOT NULL DEFAULT 0,
                chat_id INTEGER NOT NULL DEFAULT 0,
                username TEXT DEFAULT '',
                full_name TEXT DEFAULT '',
                phone TEXT DEFAULT '',
                first_seen_utc TEXT NOT NULL DEFAULT '',
                duplicate INTEGER NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        await db.execute("""
            CREATE TABLE IF NOT EXISTS partner_sent_events(
                user_id INTEGER NOT NULL,
                event_id INTEGER NOT NULL,
                sent_at TEXT NOT NULL DEFAULT '',
                PRIMARY KEY(user_id, event_id)
            );
        """)
        await db.execute("CREATE INDEX IF NOT EXISTS partner_lead_events_source_idx ON partner_lead_events(source_key, id)")
        await db.execute("CREATE INDEX IF NOT EXISTS partner_sent_events_user_idx ON partner_sent_events(user_id, event_id)")
        await db.commit()


async def _partner_source_key_for_manager(manager_key: str) -> str:
    key = registry_normalize_manager_key(manager_key or "")
    if not key:
        return ""
    try:
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            cur = await db.execute(
                "SELECT source_key FROM manager_source_links WHERE manager_key=? AND COALESCE(source_key,'')<>'' LIMIT 1",
                (key,),
            )
            row = await cur.fetchone()
            return registry_normalize_manager_key(row[0]) if row and row[0] else ""
    except Exception as e:
        print(f"partner source lookup error manager={key}: {e!r}")
        return ""


async def _create_partner_lead_event_from_daily(
    item: Dict[str, Any],
    mgr: Dict[str, Any],
    duplicate: bool,
) -> None:
    """Create one Partner Stat Bot live event for each new daily_leads row."""
    try:
        await _ensure_partner_lead_events_table()
        manager_key = registry_normalize_manager_key(item.get("manager_key") or (mgr or {}).get("manager_key") or "")
        source_key = await _partner_source_key_for_manager(manager_key)
        if not source_key:
            return

        lead_id = int(item.get("id") or 0)
        chat_id = int(item.get("chat_id") or 0)
        first_seen_utc = str(item.get("first_seen_utc") or "")
        if lead_id <= 0 or chat_id <= 0 or not first_seen_utc:
            return

        event_key = f"{manager_key}:{lead_id}:{chat_id}:{first_seen_utc}"
        now = _now_utc_iso()
        manager_display_name = str((mgr or {}).get("display_name") or item.get("manager_display_name") or manager_key)
        manager_username = str((mgr or {}).get("telegram_username") or item.get("manager_username") or "").lstrip("@")
        username = str(item.get("username") or "").lstrip("@")
        full_name = str(item.get("full_name") or "")
        phone = str(item.get("phone") or "")

        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute(
                """
                INSERT OR IGNORE INTO partner_lead_events(
                    event_key, source_key, manager_key, manager_display_name, manager_username,
                    lead_id, chat_id, username, full_name, phone, first_seen_utc,
                    duplicate, created_at, updated_at
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    event_key,
                    source_key,
                    manager_key,
                    manager_display_name,
                    manager_username,
                    lead_id,
                    chat_id,
                    username,
                    full_name,
                    phone,
                    first_seen_utc,
                    1 if duplicate else 0,
                    now,
                    now,
                ),
            )
            await db.execute(
                """
                UPDATE partner_lead_events
                SET source_key=?,
                    manager_key=?,
                    manager_display_name=?,
                    manager_username=?,
                    username=?,
                    full_name=?,
                    phone=?,
                    duplicate=?,
                    updated_at=?
                WHERE event_key=?
                """,
                (
                    source_key,
                    manager_key,
                    manager_display_name,
                    manager_username,
                    username,
                    full_name,
                    phone,
                    1 if duplicate else 0,
                    now,
                    event_key,
                ),
            )
            await db.commit()
    except Exception as e:
        print(f"partner live event create error: {e!r}")
# --- PARTNER LIVE EVENTS FIX END ---

async def _process_pending_lead_events() -> None:
    if not CONTROLLER_MODE:
        return
    rows = await _manager_rows_for_reporting()
    db_paths = [str(r.get("db_path") or "") for r in rows if str(r.get("db_path") or "").strip()]
    pending: List[Dict[str, Any]] = []
    row_by_key: Dict[str, Dict[str, Any]] = {registry_normalize_manager_key(r.get("manager_key") or ""): r for r in rows}

    for mgr in rows:
        db_path = str(mgr.get("db_path") or "")
        for item in await _fetch_unsent_daily_leads(db_path, limit=300):
            item["_db_path"] = db_path
            item["_manager_row"] = mgr
            pending.append(item)

    pending.sort(key=lambda x: (str(x.get("first_seen_utc") or ""), str(x.get("manager_key") or ""), int(x.get("id") or 0)))
    batch_seen: set[int] = set()
    for item in pending:
        db_path = str(item.get("_db_path") or "")
        key = registry_normalize_manager_key(item.get("manager_key") or "")
        mgr = item.get("_manager_row") or row_by_key.get(key) or {}
        duplicate = await _is_duplicate_systemwide(item, db_paths, batch_seen, db_path)
        manager_label = _manager_label_from_row(mgr) if mgr else key
        text = _format_lead_event(item, duplicate, manager_label)

        # Partner Stat Bot live event must not depend on the STATISTICS send result.
        try:
            await _create_partner_lead_event_from_daily(item, mgr, duplicate)
        except Exception as e:
            print(f"partner live event dispatch error: {e!r}")

        ok = await _send_ai_stat(text)
        if ok:
            await _mark_daily_lead_sent(db_path, int(item.get("id") or 0), duplicate=duplicate)
            batch_seen.add(int(item.get("chat_id") or 0))
            await asyncio.sleep(0.2)


async def _lead_dispatch_loop() -> None:
    if not CONTROLLER_MODE:
        return
    while True:
        try:
            await _process_pending_lead_events()
            await _process_pending_geoage_events()
            await _process_auto_offline()
            await asyncio.sleep(5)
        except asyncio.CancelledError:
            return
        except Exception as e:
            print(f"lead_dispatch_loop error: {e!r}")
            await asyncio.sleep(10)


async def _daily_report_loop() -> None:
    # Replaces the old 23:59 Excel auto-report.
    # Now:
    # - 17:00 sends /stat det all for the day window 08:00-17:00;
    # - 08:00 sends /flight all for the night window 17:00-08:00.
    if not CONTROLLER_MODE:
        return
    while True:
        try:
            await _send_scheduled_det_reports_if_due()
            await asyncio.sleep(60)
        except asyncio.CancelledError:
            return
        except Exception as e:
            await _send_ai_stat(f"⚠️ scheduled report error: {e!r}")
            await asyncio.sleep(60)

# -------------------- manager registry / onboarding --------------------
_MANAGER_ONBOARD_RUNTIME: Dict[int, dict] = {}


def _manager_runtime_onboarding_get(user_id: int) -> dict:
    try:
        return dict(_MANAGER_ONBOARD_RUNTIME.get(int(user_id), {}) or {})
    except Exception:
        return {}


def _manager_runtime_onboarding_set(user_id: int, **kwargs) -> None:
    try:
        uid = int(user_id)
    except Exception:
        return
    cur = dict(_MANAGER_ONBOARD_RUNTIME.get(uid, {}) or {})
    for k, v in kwargs.items():
        if v is None:
            cur.pop(k, None)
        else:
            cur[k] = v
    _MANAGER_ONBOARD_RUNTIME[uid] = cur


def _manager_runtime_onboarding_clear(user_id: int) -> None:
    try:
        _MANAGER_ONBOARD_RUNTIME.pop(int(user_id), None)
    except Exception:
        pass


# QR login holds a live connected Telethon client + QRLogin object while waiting for the
# operator to scan, unlike the stateless phone/code/pass handlers. One pending QR per owner.
# Each entry's "context" ("add" | "relogin" | "replace") tells _manager_qr_wait_task which
# commit path to dispatch into on success -- see TPILOT AUTH SAFETY 20260809 (Ф3, D-QR).
_MANAGER_QR_SESSIONS: Dict[int, dict] = {}


def _manager_qr_guard_no_collision(target_path: str, live_path: str) -> Tuple[bool, str]:
    """TPILOT AUTH SAFETY 20260809 (Ф3, D-QR): fail-closed guard -- refuses to open a
    QR client at a path that resolves to the SAME file as the live/boevoy session.
    QR auth for relogin/replacement must NEVER touch a production session directly;
    only add-manager (which has no live session yet) is exempt, and does not call
    this guard at all. Returns (True, "") when the two paths are genuinely
    different files; (False, <user-facing message>) otherwise -- the caller must
    not open any Telegram client when this returns False."""
    try:
        t = os.path.realpath(str(target_path or ""))
        l = os.path.realpath(str(live_path or ""))
    except Exception:
        return False, "⚠️ Внутренняя ошибка: не удалось проверить путь сессии. QR не начат."
    if not t or not l:
        return False, "⚠️ Внутренняя ошибка: путь сессии не определён. QR не начат."
    if t == l:
        return False, "⚠️ Внутренняя ошибка: временная и боевая сессия совпадают. QR не начат."
    return True, ""


def _manager_qr_temp_cleanup_for_context(context: str, manager_key: str) -> None:
    """TPILOT AUTH SAFETY 20260809 (Ф3 checkpoint fix, D-QR cleanup): removes
    the TEMPORARY session file (never the live/boevoy one) a relogin/replace
    QR flow was using, on cancel/timeout/error -- reusing the SAME existing,
    already-tested helpers the phone-based relogin/replacement flows already
    use for the identical purpose (_manager_relogin_cleanup_temp_files /
    _replacement_cleanup_temp_files below). No new cleanup mechanism.

    Structurally collision-safe without any extra runtime check: both helpers
    compute their OWN temp path by appending a fixed suffix
    (".relogin.session" / ".replace.session") to the key -- lexically
    guaranteed to differ from the plain "<key>.session" live path, so this can
    never delete a live session file even if called with a manager_key that
    also happens to be live/active.

    context == "add" is a deliberate no-op here: the ADD flow's QR client
    connects directly on the manager's own eventual final session path (there
    is no separate temp file of this kind to remove), and its own onboarding-
    scratch cleanup is handled separately, unchanged."""
    key = registry_normalize_manager_key(manager_key or "")
    if not key:
        return
    if context == "relogin":
        _manager_relogin_cleanup_temp_files(key)
    elif context == "replace":
        _replacement_cleanup_temp_files(key)


async def _manager_qr_session_drop(owner_user_id: int) -> None:
    try:
        uid = int(owner_user_id or 0)
    except Exception:
        return
    entry = _MANAGER_QR_SESSIONS.pop(uid, None)
    if not entry:
        return
    task = entry.get("task")
    if task is not None and not task.done() and task is not asyncio.current_task():
        try:
            task.cancel()
        except Exception:
            pass
    client_obj = entry.get("client")
    if client_obj is not None:
        try:
            await client_obj.disconnect()
        except Exception:
            pass


def _manager_merge_onboarding_runtime(user_id: int, onboarding: Optional[dict]) -> dict:
    base = dict(onboarding or {})
    runtime = _manager_runtime_onboarding_get(user_id)
    for key in ("manager_key", "step", "phone", "phone_code_hash", "tmp_session_path", "expires_at", "next_code_allowed_at", "last_code_sent_at", "last_send_error"):
        if runtime.get(key):
            base[key] = runtime.get(key)
    return base


