async def _manager_exists(key: str) -> bool:
    row = await manager_get(registry_normalize_manager_key(key or ""))
    return bool(row and str(row.get("status") or "") != "archived")


def _manager_extract_wait_seconds(exc: Exception, default_seconds: int) -> int:
    try:
        sec = int(getattr(exc, "seconds", 0) or 0)
        if sec > 0:
            return sec
    except Exception:
        pass
    raw = f"{exc!r} {exc}"
    m = re.search(r"(\d+)\s*(?:seconds?|sec|s)", raw, flags=re.IGNORECASE)
    if m:
        try:
            sec = int(m.group(1))
            if sec > 0:
                return sec
        except Exception:
            pass
    return int(default_seconds or MANAGER_PHONE_COOLDOWN_SEC)


def _manager_is_rate_limit_error(exc: Exception) -> bool:
    name = exc.__class__.__name__.lower()
    raw = f"{exc!r} {exc}".lower()
    return "flood" in name or "flood" in raw or "too many" in raw or "retry after" in raw or "wait of" in raw


def _manager_phone_wait_message(onboarding: dict, manager_key: str) -> str:
    next_allowed = str((onboarding or {}).get("next_code_allowed_at") or "")
    hhmm = _iso_to_local_hhmm(next_allowed)
    if str((onboarding or {}).get("step") or "") == "await_code":
        return f"Код уже был запрошен. Повторно можно после {hhmm}.\nЕсли код пришёл - отправьте CODE 12345.\nЕсли нужно начать заново - MANAGER RESET {manager_key}."
    return f"Сейчас новый код запросить нельзя. Повторно можно после {hhmm}.\nЕсли нужно начать заново - MANAGER RESET {manager_key}."


# --- TPILOT AUTH VISIBILITY: send-code delivery mapping + error mapping + audit log ---
# Pure/testable helpers. No secrets are ever logged (phone is masked, API creds are
# represented only by a profile name).

_SENT_CODE_TYPE_RU: Dict[str, str] = {
    "SentCodeTypeApp": "приложение Telegram (на уже залогиненном устройстве этого номера)",
    "SentCodeTypeSms": "SMS",
    "SentCodeTypeCall": "звонок",
    "SentCodeTypeFlashCall": "флеш-звонок (код в номере звонка)",
    "SentCodeTypeMissedCall": "пропущенный звонок (код в номере звонка)",
    "SentCodeTypeFragmentSms": "SMS через Fragment",
    "SentCodeTypeSmsWord": "SMS (слово-код)",
    "SentCodeTypeSmsPhrase": "SMS (фраза-код)",
    "SentCodeTypeEmailCode": "email",
    "SentCodeTypeFirebaseSms": "SMS (проверка Firebase)",
    "SentCodeTypeSetUpEmailRequired": "требуется привязка email",
}


def _sent_code_class_name(value: Any) -> str:
    try:
        return value.__class__.__name__ if value is not None else ""
    except Exception:
        return ""


def _sent_code_channel_ru(sent: Any) -> str:
    """Human (RU) description of where Telegram sent the login code. 'Неизвестно' if Telethon
    didn't return a recognizable SentCodeType — operator should be warned in that case."""
    cls = _sent_code_class_name(getattr(sent, "type", None))
    if not cls:
        return "неизвестно (Telegram не указал способ доставки)"
    return _SENT_CODE_TYPE_RU.get(cls, f"неизвестно ({cls})")


def _sent_code_next_channel_ru(sent: Any) -> str:
    cls = _sent_code_class_name(getattr(sent, "next_type", None))
    if not cls:
        return ""
    return _SENT_CODE_TYPE_RU.get(cls, f"неизвестно ({cls})")


def _map_send_code_error(exc: Exception) -> str:
    """Friendly RU text for known Telethon send-code errors; generic repr otherwise."""
    name = exc.__class__.__name__
    mapping = {
        "AuthRestartError": "Telegram попросил перезапустить авторизацию. Введите номер телефона ещё раз.",
        "PhoneNumberInvalidError": "Номер телефона некорректен или не зарегистрирован в Telegram.",
        "PhoneNumberBannedError": "Этот номер телефона заблокирован в Telegram.",
        "PhoneNumberFloodError": "Telegram временно ограничил запросы кода для этого номера. Попробуйте позже.",
        "PhoneCodeHashEmptyError": "Telegram не вернул phone_code_hash. Запросите код ещё раз.",
    }
    return mapping.get(name, f"Не удалось отправить код: {exc!r}")


_MANAGER_AUTH_AUDIT_LOG = BASE_DIR / "runtime" / "manager_auth_audit.log"


def _manager_auth_audit_log(event: str, manager_key: str, **fields: Any) -> None:
    """Append-only structured line for manager auth attempts (mirrors the existing
    manager_telethon_proxy_audit.log style). Never raises. Never logs phone/password/api_hash
    raw values — callers must pass already-masked phone and profile-name-only API info."""
    ts = _tp_utc_now().replace(microsecond=0).isoformat()
    key = registry_normalize_manager_key(manager_key or "")
    parts = [f"time_utc={ts}", f"event={event}", f"manager_key={key}"]
    for name, value in fields.items():
        parts.append(f"{name}={value}")
    line = "\t".join(parts) + "\n"
    try:
        _MANAGER_AUTH_AUDIT_LOG.parent.mkdir(parents=True, exist_ok=True)
        with _MANAGER_AUTH_AUDIT_LOG.open("a", encoding="utf-8") as f:
            f.write(line)
    except Exception:
        pass


async def _manager_process_running(manager_key: str) -> bool:
    key = registry_normalize_manager_key(manager_key or "")
    if not key:
        return False
    if sys.platform.startswith("win"):
        script = (
            "$k='%s'; "
            "$p = Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -like ('*main.py*--manager*' + $k + '*') }; "
            "if ($p) { Write-Output '1' }"
        ) % key
        try:
            cp = subprocess.run(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", script], cwd=str(BASE_DIR), capture_output=True, text=True)
            return bool((cp.stdout or "").strip())
        except Exception:
            return False
    try:
        cp = subprocess.run(["pgrep", "-f", f"main.py --manager {key}"], cwd=str(BASE_DIR), capture_output=True, text=True)
        return cp.returncode == 0 and bool((cp.stdout or "").strip())
    except Exception:
        return False


async def _stop_manager_process(manager_key: str, *, silent: bool = False) -> Tuple[bool, str]:
    key = registry_normalize_manager_key(manager_key or "")
    if not key:
        return False, "Пустой ключ."
    if sys.platform.startswith("win"):
        script = (
            "$k='%s'; "
            "Get-CimInstance Win32_Process | "
            "Where-Object { $_.CommandLine -like ('*main.py*--manager*' + $k + '*') } | "
            "ForEach-Object { Invoke-CimMethod -InputObject $_ -MethodName Terminate | Out-Null }"
        ) % key
        try:
            subprocess.run(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", script], cwd=str(BASE_DIR), capture_output=True, text=True)
            return True, "OK"
        except Exception as e:
            return False, f"Ошибка остановки: {e!r}"
    try:
        subprocess.run(["pkill", "-f", f"main.py --manager {key}"], cwd=str(BASE_DIR), check=False)
        return True, "OK"
    except Exception as e:
        return False, f"Ошибка остановки: {e!r}"


async def _spawn_manager_process(manager_key: str) -> Tuple[bool, str]:
    key = registry_normalize_manager_key(manager_key or "")
    row = await manager_get(key)
    if not row:
        return False, "Менеджер не найден."
    paths = _manager_runtime_paths_for_key(key)
    os.makedirs(paths["root"], exist_ok=True)
    await _stop_manager_process(key, silent=True)
    if sys.platform.startswith("win"):
        bat = BASE_DIR / "start_manager.bat"
        if not bat.exists():
            return False, f"Не найден {bat}"
        try:
            kwargs: Dict[str, Any] = {"cwd": str(BASE_DIR)}
            if hasattr(subprocess, "CREATE_NEW_PROCESS_GROUP"):
                kwargs["creationflags"] = getattr(subprocess, "CREATE_NEW_PROCESS_GROUP")
            subprocess.Popen(["cmd", "/c", str(bat), key], **kwargs)
            return True, "OK"
        except Exception as e:
            return False, f"Ошибка запуска: {e!r}"
    try:
        logf = open(paths["log_path"], "a", encoding="utf-8")
        subprocess.Popen([sys.executable, str(BASE_DIR / "main.py"), "--env", ENV_FILE_USED, "--manager", key], cwd=str(BASE_DIR), stdout=logf, stderr=logf, start_new_session=True)
        return True, "OK"
    except Exception as e:
        return False, f"Ошибка запуска: {e!r}"


async def _onboarding_stop_running_for_key(manager_key: str) -> Tuple[bool, str]:
    """Before opening an onboarding client on a manager's .session, make sure no live
    `--manager <key>` process is holding that session. Two Telethon clients on the same
    SQLite session can collide / lock and break a fresh login. Returns (ok, error_msg):
    ok=False means do NOT proceed with auth (a process is running and could not be stopped).
    On a successful stop, waits briefly so the OS releases the session-file lock."""
    key = registry_normalize_manager_key(manager_key or "")
    if not key:
        return True, ""
    try:
        running = await _manager_process_running(key)
    except Exception:
        running = False
    if not running:
        return True, ""
    ok, _stop_msg = await _stop_manager_process(key)
    if not ok:
        _manager_auth_audit_log("stop_before_auth", key, ok=0)
        return False, (
            "Менеджер уже запущен, и его не удалось остановить перед входом.\n"
            f"Остановите его вручную и повторите: MANAGER STOP {key}"
        )
    try:
        await asyncio.sleep(2.0)  # let Windows release the .session file lock
    except Exception:
        pass
    _manager_auth_audit_log("stop_before_auth", key, ok=1)
    return True, ""


async def _refresh_manager_roster() -> None:
    # Kept as a compatibility hook. Registry is read live for reports.
    return None


