async def _tp_finalize_screenshots_on(manager_key: str) -> None:
    """ONBOARDING SOURCE PICK 20260711 (owner decision): force screenshot mode ON
    (instant) for THIS manager on every successful login/re-login. Targeted
    UPSERT only -- creates manager_screenshot_config additively if missing
    (same schema as panel_bot.py/manager_bot.py's _ensure_screenshot_tables),
    never touches any other manager's row, and preserves this manager's own
    reminder_enabled/reminder_time on an existing row (only require_screenshots
    and mode are forced). Never raises -- caller treats this as best-effort."""
    key = registry_normalize_manager_key(manager_key or "")
    if not key:
        return
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute(
            """
            CREATE TABLE IF NOT EXISTS manager_screenshot_config(
                manager_key TEXT PRIMARY KEY,
                require_screenshots INTEGER NOT NULL DEFAULT 0,
                mode TEXT NOT NULL DEFAULT 'off',
                reminder_enabled INTEGER NOT NULL DEFAULT 1,
                reminder_time TEXT NOT NULL DEFAULT '16:50',
                last_reminder_date TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            )
            """
        )
        await db.execute(
            "INSERT INTO manager_screenshot_config"
            "(manager_key, require_screenshots, mode, reminder_enabled, reminder_time, updated_at) "
            "VALUES(?,1,'instant',1,'16:50',?) "
            "ON CONFLICT(manager_key) DO UPDATE SET "
            "require_screenshots=1, mode='instant', updated_at=excluded.updated_at",
            (key, _now_utc_iso()),
        )
        await db.commit()


async def _manager_finalize_login(
    owner_user_id: int, manager_key: str, phone: str, me_obj,
    *,
    preserve_owner_user_id: bool = False,
    preserve_runtime_state: bool = False,
    spawn_after_login: bool = True,
    activate_prepared: bool = False,
    preserve_auth_profile: bool = False,
) -> str:
    """Finalizes a successful Telegram sign_in for manager_key: writes identity fields
    and (by default) activates + starts the manager -- the exact behavior every existing
    add-manager/QR/onboarding caller already relies on (all five new kwargs default to
    the old unconditional behavior, so no existing call site changes semantics).

    The first three kwargs exist ONLY for manager-relogin (re-auth of an ALREADY-EXISTING
    manager), which must never change who owns the manager or its enabled/stopped state
    just because an admin performed the re-auth:
      preserve_owner_user_id: keep the row's CURRENT owner_user_id instead of overwriting
        it with the admin who happened to perform this login (mirrors /manager_reset,
        which already preserves owner_user_id across a re-auth).
      preserve_runtime_state: keep the row's CURRENT status/is_enabled/manual_stopped
        instead of forcing status='active', is_enabled=1, manual_stopped=0.
      spawn_after_login: gate the runtime spawn -- if False, the manager stays stopped
        even though its session is now valid (the caller is responsible for deciding
        this based on whether the runtime was actually running before the operation).

    TPILOT PREPARED ACCOUNTS PHASE 4 (2026-08-10): two more kwargs, both still
    defaulting to the old unconditional behavior.
      activate_prepared: escape hatch reserved for the future activation flow
        (Phase 5). This function AUTO-DETECTS prepared-mode from the row's
        OWN CURRENT status -- never threaded as a flag into the phone/code/
        2FA/QR call sites (owner decision) -- so a manager that is currently
        status='prepared' takes the prepared branch below UNLESS the caller
        explicitly passes activate_prepared=True, in which case the normal
        active/1/0 + grant + spawn + source-pick path runs instead. Phase 5's
        activation call is the only intended caller of True.
      preserve_auth_profile: when True, this call does NOT overwrite
        managers.auth_profile back to 'project' -- needed by Phase 5's
        activation of a Session/TData-imported (auth_profile='tdesktop')
        prepared account, which authorized under a DIFFERENT Telegram API
        app and must keep using it after activation. False (default, every
        current call site) preserves the exact existing overwrite-to-
        'project' behavior described in the comment below.
    """
    key = registry_normalize_manager_key(manager_key or "")
    username = (getattr(me_obj, "username", None) or "") if me_obj else ""
    tg_user_id = int(getattr(me_obj, "id", 0) or 0) if me_obj else 0
    first_name = (getattr(me_obj, "first_name", None) or "") if me_obj else ""
    last_name = (getattr(me_obj, "last_name", None) or "") if me_obj else ""
    paths = _manager_runtime_paths_for_key(key)
    existing = await manager_get(key) or {}
    display_name = str(existing.get("display_name") or "").strip()
    if ((not display_name) or display_name == key) and first_name:
        display_name = first_name

    # TPILOT PREPARED ACCOUNTS PHASE 4: the row's OWN current status is the
    # single source of truth -- see activate_prepared's docstring above.
    is_prepared = (
        str(existing.get("status") or "").strip().lower() == "prepared"
        and not activate_prepared
    )
    if is_prepared:
        preserve_runtime_state = True
        spawn_after_login = False

    effective_owner_user_id = int(owner_user_id)
    if preserve_owner_user_id:
        prior_owner = existing.get("owner_user_id")
        if prior_owner:
            effective_owner_user_id = int(prior_owner)

    if preserve_runtime_state:
        status_value = str(existing.get("status") or "active").strip() or "active"
        is_enabled_value = int(existing.get("is_enabled") if existing.get("is_enabled") is not None else 1)
        manual_stopped_value = int(existing.get("manual_stopped") or 0)
    else:
        status_value = "active"
        is_enabled_value = 1
        manual_stopped_value = 0

    set_fields_kwargs = dict(
        display_name=display_name or key,
        phone=str(phone or ""),
        status=status_value,
        is_enabled=is_enabled_value,
        manual_stopped=manual_stopped_value,
        owner_user_id=effective_owner_user_id,
        session_path=paths["session_path"],
        db_path=paths["db_path"],
        workdir=paths["root"],
        log_path=paths["log_path"],
        tg_user_id=tg_user_id or None,
        telegram_username=username,
        first_name=first_name,
        last_name=last_name,
        last_login_at=_now_utc_iso(),
        last_error="",
    )
    if not preserve_auth_profile:
        # TPILOT TDATA/SESSION IMPORT AUTH PROFILE 20260719: a successful
        # phone/code/2FA/QR/relogin/replacement sign_in reaching this finalize just
        # created its auth_key under the project/onboard API app, so the manager's
        # runtime profile MUST return to 'project' -- even if it was previously
        # 'tdesktop' after a direct .session/tdata import (otherwise the runtime
        # would connect this project-authorized key under Telegram Desktop's
        # api_id=2040: the mirror image of the API-mismatch bug the tdesktop
        # profile exists to fix). The tdimport flow never calls this finalize, so
        # an imported manager's 'tdesktop' value is untouched by this line.
        set_fields_kwargs["auth_profile"] = "project"
    await manager_set_fields(key, **set_fields_kwargs)

    if not is_prepared:
        # TPILOT MANAGERBOT ACCESS AUTO-GRANT 20260727: this is a confirmed
        # successful sign_in (phone/code/2FA/QR/relogin, or the identity-match
        # branch of account replacement) for an already-active manager row --
        # grant ManagerBot base access now instead of waiting for the manager's
        # own next /start. Best-effort: a failure here must never fail the login
        # itself (mirrors the screenshot-config best-effort block just below).
        #
        # TPILOT PREPARED ACCOUNTS PHASE 4: NEVER reached for a prepared
        # account -- zero manager_bot_access rows (not disabled, not
        # revoked, simply absent) until a future Phase 5 activation call
        # passes activate_prepared=True and reaches this same block.
        try:
            _mbgrant_result = manager_bot_access_ensure_sync(
                tg_user_id=tg_user_id or None,
                manager_key=key,
                display_name=display_name or key,
                username=username,
                db_path=TPILOT_DB_PATH,
            )
            if _mbgrant_result.get("status") == "error":
                print(f"[onboarding] ManagerBot access grant error for {key}: {_mbgrant_result.get('error')}")
        except Exception as e:
            print(f"[onboarding] ManagerBot access grant failed for {key}: {e!r}")
    # manager_onboarding is keyed by the ADMIN performing this call (owner_user_id
    # parameter), never by the manager row's business owner_user_id field above --
    # this clears THIS admin's onboarding/relogin progress regardless of preserve_*.
    # Safe for prepared too: this function is only ever reached AFTER a successful
    # sign_in (get_me/qr.wait already succeeded) -- retry-able code/2FA/QR-timeout
    # states never reach finalize at all, so nothing this admin still needs is lost.
    _manager_runtime_onboarding_clear(int(owner_user_id))
    await manager_delete_onboarding(int(owner_user_id))
    # ONBOARDING SOURCE PICK 20260711 (owner decisions): every caller reaches this
    # point only after a successful sign_in/QR -- auth already succeeded. Force
    # screenshots ON (instant) for this manager on every successful login/re-login.
    # Best-effort: a write failure is logged, never raised, so it can never fail
    # the login itself.
    try:
        await _tp_finalize_screenshots_on(key)
    except Exception as e:
        print(f"[onboarding] screenshot config force-on failed for {key}: {e!r}")
    if spawn_after_login:
        ok, msg = await _spawn_manager_process(key)
    else:
        ok, msg = False, "not started (runtime was not running before this operation)"
    row = await manager_get(key)

    if is_prepared:
        # TPILOT PREPARED ACCOUNTS PHASE 4: distinct terminal branch -- never
        # the active/spawn wording above, never the source-pick marker below.
        # Records the verify outcome on the prepared_accounts side-row
        # created earlier by /prepared_method (best-effort: a missing
        # side-row, e.g. an admin who never called /prepared_method, simply
        # updates zero rows -- never raises, never fails the login).
        try:
            import storage as _prep_storage

            _prep_storage.prepared_account_mark_verify(key, True, "", db_path=TPILOT_DB_PATH)
        except Exception as e:
            print(f"[prepared] verify-metadata update failed for {key}: {e!r}")
        result = (
            f"✅ Аккаунт подготовлен: {key}\n{_manager_label_from_row(row or {})}\n"
            f"Менеджер остаётся подготовленным (не активен).\n{_PREPARED_READY_MARKER}"
        )
        return result

    if spawn_after_login and ok:
        result = f"✅ Менеджер активирован и запущен: {key}\n{_manager_label_from_row(row or {})}"
    elif spawn_after_login:
        result = f"Менеджер авторизован, но запуск не удался: {msg}"
    else:
        result = f"✅ Сессия обновлена: {key}\n{_manager_label_from_row(row or {})}\nМенеджер остался остановлен/выключен."
    # ONBOARDING SOURCE PICK 20260711: prompt for a traffic source right after a
    # successful login, unless this manager is already linked to one (prevents a
    # duplicate prompt on every re-login of an already-linked manager). Appended
    # regardless of the spawn outcome above -- login/auth itself already succeeded.
    try:
        already_linked = bool(await _partner_source_key_for_manager(key))
    except Exception:
        already_linked = True  # fail closed: never nag an already-working setup
    if not already_linked:
        result = f"{result}\nУспешно залогинен. {_ONBOARDING_SOURCE_PICK_MARKER}"
    return result



async def _handle_manager_proxy_command(chat_id: int, user_id: int, text: str) -> bool:
    if not await _manager_require_auth(chat_id, user_id):
        return True
    rest = text[len("MANAGER PROXY "):].strip()
    if not rest:
        await client.send_message(chat_id, "Формат: MANAGER PROXY <key> SOCKS5 <host> <port> [login] [password]\nИли: MANAGER PROXY INFO|ON|OFF <key>")
        return True

    parts = rest.split()
    action = str(parts[0] if parts else "").strip().upper()

    if action in ("INFO", "ON", "OFF"):
        key = registry_normalize_manager_key(parts[1] if len(parts) >= 2 else "")
        if not key:
            await client.send_message(chat_id, f"Формат: MANAGER PROXY {action} <manager_key>")
            return True
        row = await manager_get(key)
        if not row or str(row.get("status") or "") == "archived":
            await client.send_message(chat_id, f"Менеджер не найден: {key}")
            return True
        if action == "INFO":
            await client.send_message(chat_id, _manager_proxy_info_text(row))
            return True
        if action == "OFF":
            await manager_set_fields(key, proxy_enabled=0, proxy_updated_at=_now_utc_iso())
            await client.send_message(chat_id, f"✅ Proxy выключен для {key}.\nЧтобы применить к уже запущенному аккаунту, перезапуст��те менеджера: MANAGER STOP {key}, потом MANAGER START {key}.")
            return True
        if action == "ON":
            if not str(row.get("proxy_host") or "").strip() or not _proxy_port_int(row.get("proxy_port")):
                await client.send_message(chat_id, f"Для {key} ещё не задан proxy.\nФормат: MANAGER PROXY {key} SOCKS5 <host> <port> [login] [password]")
                return True
            await manager_set_fields(key, proxy_enabled=1, proxy_updated_at=_now_utc_iso())
            await client.send_message(chat_id, f"✅ Proxy включён для {key}.\nЧтобы применить к уже запущенному аккаунту, перезапустите менеджера: MANAGER STOP {key}, потом MANAGER START {key}.")
            return True

    key = registry_normalize_manager_key(parts[0] if len(parts) >= 1 else "")
    ptype_raw = str(parts[1] if len(parts) >= 2 else "").strip()
    ptype = _proxy_type_norm(ptype_raw)
    if not key or ptype != "socks5" or len(parts) < 4:
        await client.send_message(chat_id, "Формат: MANAGER PROXY <manager_key> SOCKS5 <host> <port> [login] [password]\nПример: MANAGER PROXY te SOCKS5 1.2.3.4 1080 user pass")
        return True
    row = await manager_get(key)
    if not row or str(row.get("status") or "") == "archived":
        await client.send_message(chat_id, f"Менеджер не найден: {key}")
        return True
    host = str(parts[2] or "").strip()
    port = _proxy_port_int(parts[3] if len(parts) >= 4 else "")
    username = str(parts[4] if len(parts) >= 5 else "").strip()
    password = str(parts[5] if len(parts) >= 6 else "").strip()
    if username == "-":
        username = ""
    if password == "-":
        password = ""
    if not host or not port:
        await client.send_message(chat_id, "Host или port указаны неверно. Port должен быть от 1 до 65535.")
        return True
    await manager_set_fields(
        key,
        proxy_type="socks5",
        proxy_host=host,
        proxy_port=int(port),
        proxy_username=username,
        proxy_password=password,
        proxy_enabled=1,
        proxy_updated_at=_now_utc_iso(),
    )
    await client.send_message(
        chat_id,
        "\n".join([
            f"✅ SOCKS5 proxy сохранён и включён для {key}",
            f"Host: {host}",
            f"Port: {int(port)}",
            f"Login: {_proxy_login_display(username)}",
            f"Password: {_mask_secret(password)}",
            "",
            "Если proxy заменили у уже запущенного менеджера, перезапустите его, чтобы применить.",
            f"MANAGER STOP {key}",
            f"MANAGER START {key}",
        ]).rstrip(),
    )
    return True


async def _handle_manager_plaintext(event: events.NewMessage.Event) -> bool:
    if not (CONTROLLER_MODE and event.raw_text and not event.out):
        return False
    text = (event.raw_text or "").strip()
    if not text:
        return False
    chat_id = int(event.chat_id)
    user_id = int(event.sender_id or 0)
    if not event.is_private:
        upper0 = text.upper()
        if upper0.startswith("MANAGER ") or upper0.startswith("PHONE ") or upper0.startswith("CODE ") or upper0.startswith("PASS "):
            await client.send_message(chat_id, "MANAGER-команды и PHONE/CODE/PASS доступны только в ЛС TPilot.")
            return True
        return False

    upper = text.upper()
    is_manager_cmd = upper.startswith("MANAGER ")
    is_sensitive_step = upper.startswith("PHONE ") or upper.startswith("CODE ") or upper.startswith("PASS ")
    if not (is_manager_cmd or is_sensitive_step):
        return False

    await manager_clear_expired_onboarding()

    if upper.startswith("MANAGER AUTH "):
        raw_pass = text[len("MANAGER AUTH "):].strip()
        if not MANAGER_ADMIN_PASSWORD:
            await client.send_message(chat_id, "В .env TPilot не задан MANAGER_ADMIN_PASSWORD.")
            return True
        if raw_pass != MANAGER_ADMIN_PASSWORD:
            await client.send_message(chat_id, "Неверный пароль manager-доступа.")
            return True
        await manager_create_auth_session(user_id, _future_iso(MANAGER_AUTH_TIMEOUT_SEC))
        await client.send_message(chat_id, "✅ Доступ к manager-командам открыт на 10 минут.\nДоступные действия: MANAGER ADD <key>, MANAGER LIST, MANAGER INFO <key>, MANAGER START <key>, MANAGER STOP <key>, MANAGER ENABLE <key>, MANAGER DISABLE <key>, MANAGER REMOVE <key>, MANAGER RESET <key>, MANAGER PENDING.")
        return True

    if upper == "MANAGER LIST":
        rows = await manager_list_rows(include_removed=False)
        if not rows:
            await client.send_message(chat_id, "Менеджеров пока нет.")
            return True
        lines = ["Менеджеры:"]
        for idx, row in enumerate(rows, 1):
            lines.append(f"{idx}) {row.get('manager_key')} | {_manager_label_from_row(row)} | {_manager_status_label(row)}")
        await client.send_message(chat_id, "\n".join(lines))
        return True

    if upper == "MANAGER PENDING":
        rows = await manager_list_pending()
        if not rows:
            await client.send_message(chat_id, "Зависших onboarding-сессий нет.")
            return True
        lines = ["Onboarding в ожидании:"]
        for idx, row in enumerate(rows, 1):
            lines.append(f"{idx}) {row.get('manager_key')} | step={row.get('step')} | expires_at={row.get('expires_at') or '_'} | owner={row.get('owner_user_id') or '_'}")
        await client.send_message(chat_id, "\n".join(lines))
        return True

    if upper.startswith("MANAGER PROXY "):
        return await _handle_manager_proxy_command(chat_id, user_id, text)

    if upper.startswith("MANAGER RESET "):
        if not await _manager_require_auth(chat_id, user_id):
            return True
        key = registry_normalize_manager_key(text[len("MANAGER RESET "):].strip())
        row = await manager_get(key)
        if not row or str(row.get("status") or "") == "archived":
            await client.send_message(chat_id, f"Менеджер не найден: {key}")
            return True
        await _stop_manager_process(key, silent=True)
        try:
            await manager_delete_onboarding_by_key(key)
        except Exception:
            pass
        # Reset Telegram authorization but keep the manager DB.
        # The old leads table is part of duplicate detection, so deleting the DB would break history.
        paths = ensure_manager_dirs(str(BASE_DIR), key)
        for fp in (paths.get("session_path"), paths.get("session_path", "") + "-journal"):
            try:
                if fp and os.path.exists(fp):
                    os.remove(fp)
            except Exception:
                pass
        await manager_set_fields(key, status="new", is_enabled=1, manual_stopped=0, owner_user_id=int(row.get("owner_user_id") or user_id or 0) or None, phone="", session_path=paths["session_path"], db_path=paths["db_path"], workdir=paths["root"], log_path=paths["log_path"], tg_user_id=None, telegram_username="", first_name="", last_name="", last_login_at="", last_error="")
        expires_at = _future_iso(MANAGER_ONBOARD_TIMEOUT_SEC)
        await manager_save_onboarding(user_id, manager_key=key, step="await_phone", phone="", phone_code_hash="", tmp_session_path=paths["session_path"], expires_at=expires_at, next_code_allowed_at="", last_code_sent_at="", last_send_error="")
        _manager_runtime_onboarding_set(user_id, manager_key=key, step="await_phone", phone="", phone_code_hash="", tmp_session_path=paths["session_path"], expires_at=expires_at, next_code_allowed_at="", last_code_sent_at="", last_send_error="")
        await client.send_message(chat_id, f"✅ RESET выполнен: {key}\nСледующий шаг: PHONE +79991234567")
        return True

    if upper.startswith("MANAGER INFO "):
        key = registry_normalize_manager_key(text[len("MANAGER INFO "):].strip())
        row = await manager_get(key)
        if not row or str(row.get("status") or "") == "archived":
            await client.send_message(chat_id, f"Менеджер не найден: {key}")
            return True
        lines = [
            f"Ключ: {row.get('manager_key')}",
            f"Отображение: {_manager_label_from_row(row)}",
            f"Статус: {_manager_status_label(row)}",
            f"Телефон: {mask_phone(str(row.get('phone') or ''))}",
            f"owner_user_id: {row.get('owner_user_id') or '_'}",
            f"tg_user_id: {row.get('tg_user_id') or '_'}",
            f"db: {row.get('db_path') or '_'}",
            f"session: {row.get('session_path') or '_'}",
            f"log: {row.get('log_path') or '_'}",
            f"proxy: {'on' if int(row.get('proxy_enabled') or 0) == 1 else 'off'} {str(row.get('proxy_type') or '').upper() or '_'} {row.get('proxy_host') or '_'}:{row.get('proxy_port') or '_'}",
        ]
        await client.send_message(chat_id, "\n".join(lines))
        return True

    if upper.startswith("MANAGER ADD "):
        if not await _manager_require_auth(chat_id, user_id):
            return True
        ok, err, key = validate_manager_key(text[len("MANAGER ADD "):].strip())
        if not ok:
            await client.send_message(chat_id, err)
            return True
        if await _manager_exists(key):
            await client.send_message(chat_id, f"Менеджер уже существует: {key}")
            return True
        paths = ensure_manager_dirs(str(BASE_DIR), key)
        await manager_add(manager_key=key, display_name=key, phone="", status="new", session_path=paths["session_path"], db_path=paths["db_path"], workdir=paths["root"], log_path=paths["log_path"], is_enabled=1, owner_user_id=user_id)
        expires_at = _future_iso(MANAGER_ONBOARD_TIMEOUT_SEC)
        await manager_save_onboarding(user_id, manager_key=key, step="await_phone", tmp_session_path=paths["session_path"], expires_at=expires_at)
        _manager_runtime_onboarding_set(user_id, manager_key=key, step="await_phone", phone="", phone_code_hash="", tmp_session_path=paths["session_path"], expires_at=expires_at, next_code_allowed_at="", last_code_sent_at="", last_send_error="")
        await client.send_message(chat_id, f"✅ Менеджер создан: {key}\nСледующий шаг: PHONE +79991234567")
        return True

    if upper.startswith("MANAGER RENAME "):
        if not await _manager_require_auth(chat_id, user_id):
            return True
        rest = text[len("MANAGER RENAME "):].strip()
        parts = rest.split(maxsplit=1)
        key = registry_normalize_manager_key(parts[0] if parts else "")
        display_name = (parts[1] if len(parts) > 1 else "").strip()
        if not key or not display_name:
            await client.send_message(chat_id, "Формат: MANAGER RENAME <key> <display_name>")
            return True
        row = await manager_get(key)
        if not row or str(row.get("status") or "") == "archived":
            await client.send_message(chat_id, f"Менеджер не найден: {key}")
            return True
        await manager_rename(key, display_name)
        await client.send_message(chat_id, f"✅ Имя обновлено: {key} -> {display_name}")
        return True

    if upper.startswith("MANAGER START "):
        if not await _manager_require_auth(chat_id, user_id):
            return True
        key = registry_normalize_manager_key(text[len("MANAGER START "):].strip())
        row = await manager_get(key)
        if not row or str(row.get("status") or "") == "archived":
            await client.send_message(chat_id, f"Менеджер не найден: {key}")
            return True
        await manager_set_fields(key, is_enabled=1, status="active", manual_stopped=0)
        ok, msg = await _spawn_manager_process(key)
        if ok:
            await client.send_message(chat_id, f"✅ Запуск выполнен: {key}")
        else:
            await manager_set_fields(key, last_error=msg)
            await client.send_message(chat_id, msg)
        return True

    if upper.startswith("MANAGER STOP "):
        if not await _manager_require_auth(chat_id, user_id):
            return True
        key = registry_normalize_manager_key(text[len("MANAGER STOP "):].strip())
        row = await manager_get(key)
        if not row or str(row.get("status") or "") == "archived":
            await client.send_message(chat_id, f"Менеджер не найден: {key}")
            return True
        ok, msg = await _stop_manager_process(key)
        await manager_set_fields(key, manual_stopped=1)
        await client.send_message(chat_id, f"✅ Остановка выполнена: {key}" if ok else msg)
        return True

    if upper.startswith("MANAGER ENABLE "):
        if not await _manager_require_auth(chat_id, user_id):
            return True
        key = registry_normalize_manager_key(text[len("MANAGER ENABLE "):].strip())
        row = await manager_get(key)
        if not row or str(row.get("status") or "") == "archived":
            await client.send_message(chat_id, f"Мен��джер не найден: {key}")
            return True
        await manager_set_fields(key, is_enabled=1, status="active")
        await client.send_message(chat_id, f"✅ ENABLE: {key}")
        return True

    if upper.startswith("MANAGER DISABLE "):
        if not await _manager_require_auth(chat_id, user_id):
            return True
        key = registry_normalize_manager_key(text[len("MANAGER DISABLE "):].strip())
        row = await manager_get(key)
        if not row or str(row.get("status") or "") == "archived":
            await client.send_message(chat_id, f"Менеджер не найден: {key}")
            return True
        await manager_set_fields(key, is_enabled=0, status="disabled", manual_stopped=1)
        await _stop_manager_process(key, silent=True)
        await client.send_message(chat_id, f"✅ DISABLE: {key}")
        return True

    if upper.startswith("MANAGER REMOVE "):
        if not await _manager_require_auth(chat_id, user_id):
            return True
        key = registry_normalize_manager_key(text[len("MANAGER REMOVE "):].strip())
        row = await manager_get(key)
        if not row or str(row.get("status") or "") == "archived":
            await client.send_message(chat_id, f"Менеджер не найден: {key}")
            return True
        await _stop_manager_process(key, silent=True)
        await manager_soft_remove(key)
        await client.send_message(chat_id, f"✅ Менеджер мягко архивирован: {key}")
        return True

    onboarding = _manager_merge_onboarding_runtime(user_id, await manager_get_onboarding(user_id))
    if not onboarding:
        if is_sensitive_step:
            await client.send_message(chat_id, "Нет активного onboarding. Сначала выполните MANAGER ADD <key>.")
            return True
        return False
    if str(onboarding.get("expires_at") or "") and str(onboarding.get("expires_at")) < _now_utc_iso():
        key_exp = registry_normalize_manager_key(onboarding.get("manager_key") or "")
        _manager_runtime_onboarding_clear(user_id)
        await manager_delete_onboarding(user_id)
        await client.send_message(chat_id, f"Onboarding истёк. Начните заново: MANAGER RESET {key_exp}")
        return True

    manager_key = registry_normalize_manager_key(onboarding.get("manager_key") or "")
    paths = _manager_runtime_paths_for_key(manager_key)

    if upper.startswith("PHONE "):
        phone = text[len("PHONE "):].strip()
        if not phone:
            await client.send_message(chat_id, "Формат: PHONE +79991234567")
            return True
        next_code_allowed_at = str(onboarding.get("next_code_allowed_at") or "")
        if next_code_allowed_at and next_code_allowed_at > _now_utc_iso():
            await client.send_message(chat_id, _manager_phone_wait_message(onboarding, manager_key))
            return True
        temp_client = await _build_manager_session_client(manager_key, paths["session_path"])
        try:
            await temp_client.connect()
            sent = await temp_client.send_code_request(phone)
            cooldown_sec = MANAGER_PHONE_COOLDOWN_SEC
            phone_code_hash = str(getattr(sent, "phone_code_hash", "") or "")
            expires_at = _future_iso_max(MANAGER_ONBOARD_TIMEOUT_SEC, cooldown_sec + 300)
            next_code_allowed_at = _future_iso(cooldown_sec)
            last_code_sent_at = _now_utc_iso()
            await manager_set_fields(manager_key, phone=phone, status="auth_pending", is_enabled=1, manual_stopped=0, owner_user_id=user_id, session_path=paths["session_path"], db_path=paths["db_path"], workdir=paths["root"], log_path=paths["log_path"], last_error="")
            await manager_save_onboarding(user_id, manager_key=manager_key, step="await_code", phone=phone, phone_code_hash=phone_code_hash, tmp_session_path=paths["session_path"], expires_at=expires_at, next_code_allowed_at=next_code_allowed_at, last_code_sent_at=last_code_sent_at, last_send_error="")
            _manager_runtime_onboarding_set(user_id, manager_key=manager_key, step="await_code", phone=phone, phone_code_hash=phone_code_hash, tmp_session_path=paths["session_path"], expires_at=expires_at, next_code_allowed_at=next_code_allowed_at, last_code_sent_at=last_code_sent_at, last_send_error="")
            await client.send_message(chat_id, "✅ Код отправлен.\nСледующий шаг: CODE 12345")
            return True
        except Exception as e:
            wait_sec = _manager_extract_wait_seconds(e, MANAGER_PHONE_COOLDOWN_SEC) if _manager_is_rate_limit_error(e) else 0
            if wait_sec > 0:
                expires_at = _future_iso_max(MANAGER_ONBOARD_TIMEOUT_SEC, wait_sec + 300)
                next_code_allowed_at = _future_iso(wait_sec)
                await manager_set_fields(manager_key, status="auth_pending", last_error=repr(e))
                await manager_save_onboarding(user_id, manager_key=manager_key, step="await_phone", phone=phone, phone_code_hash="", tmp_session_path=paths["session_path"], expires_at=expires_at, next_code_allowed_at=next_code_allowed_at, last_send_error=repr(e))
                _manager_runtime_onboarding_set(user_id, manager_key=manager_key, step="await_phone", phone=phone, phone_code_hash="", tmp_session_path=paths["session_path"], expires_at=expires_at, next_code_allowed_at=next_code_allowed_at, last_send_error=repr(e))
                await client.send_message(chat_id, f"Telegram временно ограничил запросы кода. Повторно можно после {_iso_to_local_hhmm(next_code_allowed_at)}.\nЕсли нужно очистить onboarding - MANAGER RESET {manager_key}.")
                return True
            expires_at = _future_iso(MANAGER_ONBOARD_TIMEOUT_SEC)
            await manager_set_fields(manager_key, status="error", last_error=repr(e))
            await manager_save_onboarding(user_id, manager_key=manager_key, step="await_phone", phone=phone, phone_code_hash="", tmp_session_path=paths["session_path"], expires_at=expires_at, last_send_error=repr(e))
            _manager_runtime_onboarding_set(user_id, manager_key=manager_key, step="await_phone", phone=phone, phone_code_hash="", tmp_session_path=paths["session_path"], expires_at=expires_at, next_code_allowed_at="", last_send_error=repr(e))
            await client.send_message(chat_id, f"Не удалось отправить код: {e!r}")
            return True
        finally:
            try:
                await temp_client.disconnect()
            except Exception:
                pass

    if upper.startswith("CODE "):
        code = re.sub(r"\D+", "", text[len("CODE "):].strip())
        if not code:
            await client.send_message(chat_id, "Формат: CODE 12345")
            return True
        phone_for_code = str(onboarding.get("phone") or "").strip()
        phone_code_hash = str(onboarding.get("phone_code_hash") or "").strip()
        runtime_onboarding = _manager_runtime_onboarding_get(user_id)
        if not phone_code_hash and runtime_onboarding.get("phone_code_hash"):
            phone_code_hash = str(runtime_onboarding.get("phone_code_hash") or "").strip()
        if not phone_for_code and runtime_onboarding.get("phone"):
            phone_for_code = str(runtime_onboarding.get("phone") or "").strip()
        if not phone_for_code or not phone_code_hash:
            expires_at = _future_iso(MANAGER_ONBOARD_TIMEOUT_SEC)
            await manager_save_onboarding(user_id, manager_key=manager_key, step="await_phone", phone=phone_for_code, phone_code_hash="", tmp_session_path=paths["session_path"], expires_at=expires_at, next_code_allowed_at="", last_send_error="missing_phone_or_hash")
            _manager_runtime_onboarding_set(user_id, manager_key=manager_key, step="await_phone", phone=phone_for_code, phone_code_hash="", tmp_session_path=paths["session_path"], expires_at=expires_at, next_code_allowed_at="", last_send_error="missing_phone_or_hash")
            await client.send_message(chat_id, "Не найден активный phone_code_hash. Повторите PHONE <номер>, чтобы запросить новый код.")
            return True
        temp_client = await _build_manager_session_client(manager_key, paths["session_path"])
        try:
            await temp_client.connect()
            await temp_client.sign_in(phone=phone_for_code, code=code, phone_code_hash=phone_code_hash)
            me = await temp_client.get_me()
            try:
                await temp_client.disconnect()
            except Exception:
                pass
            msg = await _manager_finalize_login(user_id, manager_key, phone_for_code, me)
            await client.send_message(chat_id, msg)
            return True
        except SessionPasswordNeededError:
            expires_at = _future_iso(MANAGER_ONBOARD_TIMEOUT_SEC)
            phone_keep = str(onboarding.get("phone") or phone_for_code or "")
            hash_keep = str(onboarding.get("phone_code_hash") or phone_code_hash or "")
            next_code_allowed_at = str(onboarding.get("next_code_allowed_at") or runtime_onboarding.get("next_code_allowed_at") or "")
            last_code_sent_at = str(onboarding.get("last_code_sent_at") or runtime_onboarding.get("last_code_sent_at") or "")
            await manager_save_onboarding(user_id, manager_key=manager_key, step="await_password", phone=phone_keep, phone_code_hash=hash_keep, tmp_session_path=paths["session_path"], expires_at=expires_at, next_code_allowed_at=next_code_allowed_at, last_code_sent_at=last_code_sent_at)
            _manager_runtime_onboarding_set(user_id, manager_key=manager_key, step="await_password", phone=phone_keep, phone_code_hash=hash_keep, tmp_session_path=paths["session_path"], expires_at=expires_at, next_code_allowed_at=next_code_allowed_at, last_code_sent_at=last_code_sent_at)
            await client.send_message(chat_id, "Нужен пароль 2FA.\nСледующий шаг: PASS ваш_пароль")
            return True
        except (PhoneCodeInvalidError, PhoneCodeExpiredError):
            phone_keep = str(onboarding.get("phone") or phone_for_code or "")
            expires_at = _future_iso(MANAGER_ONBOARD_TIMEOUT_SEC)
            await manager_save_onboarding(user_id, manager_key=manager_key, step="await_phone", phone=phone_keep, tmp_session_path=paths["session_path"], expires_at=expires_at, next_code_allowed_at="", last_send_error="phone_code_invalid")
            _manager_runtime_onboarding_set(user_id, manager_key=manager_key, step="await_phone", phone=phone_keep, phone_code_hash="", tmp_session_path=paths["session_path"], expires_at=expires_at, next_code_allowed_at="", last_send_error="phone_code_invalid")
            await client.send_message(chat_id, f"Код неверный или истёк. Повторите PHONE <номер>, чтобы запросить новый код. Если нужно очистить onboarding - MANAGER RESET {manager_key}.")
            return True
        except Exception as e:
            await manager_set_fields(manager_key, status="error", last_error=repr(e))
            await client.send_message(chat_id, f"Ошибка входа по коду: {e!r}")
            return True
        finally:
            try:
                await temp_client.disconnect()
            except Exception:
                pass

    if upper.startswith("PASS "):
        password = text[len("PASS "):].strip()
        if not password:
            await client.send_message(chat_id, "Формат: PASS ваш_пароль")
            return True
        temp_client = await _build_manager_session_client(manager_key, paths["session_path"])
        try:
            await temp_client.connect()
            await temp_client.sign_in(password=password)
            me = await temp_client.get_me()
            try:
                await temp_client.disconnect()
            except Exception:
                pass
            msg = await _manager_finalize_login(user_id, manager_key, str(onboarding.get("phone") or ""), me)
            await client.send_message(chat_id, msg)
            return True
        except PasswordHashInvalidError:
            await client.send_message(chat_id, "Неверный пароль 2FA. Повторите: PASS ваш_пароль")
            return True
        except Exception as e:
            await manager_set_fields(manager_key, status="error", last_error=repr(e))
            await client.send_message(chat_id, f"Ошибка входа по 2FA: {e!r}")
            return True
        finally:
            try:
                await temp_client.disconnect()
            except Exception:
                pass

    return False


# -------------------- profile / status automation --------------------
def _combine_profile(existing: Dict[str, Any], parsed: Dict[str, Any]) -> Dict[str, Any]:
    age = parsed.get("age") if parsed.get("age") is not None else existing.get("age")
    try:
        age = int(age) if age is not None and str(age).strip() != "" else None
    except Exception:
        age = None
    city = str(parsed.get("city") or existing.get("city") or "").strip()
    region = str(parsed.get("region") or existing.get("region") or "").strip()
    country = str(parsed.get("country") or existing.get("country") or "").strip()
    status, reason = classify_lead(age, country, city or country)
    profile_done = 1 if status in ("liquid", "nonliquid") else 0
    geo_note = str(parsed.get("geo_note") or existing.get("geo_note") or "").strip()
    if country == "Россия" and not city:
        geo_note = "город не определен"
    return {
        "age": age,
        "city": city,
        "region": region,
        "country": country,
        "city_raw": city,
        "country_raw": country,
        "geo_source": str(parsed.get("geo_source") or existing.get("geo_source") or "").strip(),
        "geo_confidence": str(parsed.get("geo_confidence") or existing.get("geo_confidence") or "").strip(),
        "geo_note": geo_note,
        "status": status,
        "nonliquid_reason": reason or "",
        "profile_done": profile_done,
        "profile_answered_at": _now_utc_iso() if (age is not None or country or city) else str(existing.get("profile_answered_at") or ""),
    }

