def _profile_has_any_data(lead: Dict[str, Any]) -> bool:
    return (
        lead.get("age") is not None
        or bool(str(lead.get("city") or "").strip())
        or bool(str(lead.get("country") or "").strip())
    )


def _profile_missing_fields(lead: Dict[str, Any]) -> Tuple[bool, bool]:
    missing_age = lead.get("age") is None or str(lead.get("age") or "").strip() == ""
    country = str(lead.get("country") or "").strip()
    city = str(lead.get("city") or "").strip()
    # Russia explicitly given is enough for qualification even if city is absent.
    missing_geo = not bool(country or city)
    return missing_age, missing_geo


def _clarify_text_for_lead(lead: Dict[str, Any]) -> str:
    missing_age, missing_geo = _profile_missing_fields(lead)
    if missing_age and missing_geo:
        return CLARIFY_BOTH_TEXT
    if missing_age:
        return CLARIFY_AGE_TEXT
    if missing_geo:
        return CLARIFY_GEO_TEXT
    return ""


def _nonliquid_country_client_text(lead: Dict[str, Any]) -> str:
    country = str(lead.get("country") or "").strip()
    reason = str(lead.get("nonliquid_reason") or "").strip()
    value = country if country and country != "Россия" else (reason if reason and reason not in {"-18", "не указано"} else "")
    if not value or value == "Украина":
        return ""
    return PROFILE_NON_RU_FINAL_TEXT


async def _set_daily_clarify_attempts(lead_row: Dict[str, Any], attempts: int) -> None:
    await _update_daily_lead_fields(
        DB_PATH,
        lead_date=str(lead_row.get("lead_date") or _kyiv_now().date().isoformat()),
        manager_key=str(lead_row.get("manager_key") or MANAGER_RUNTIME_KEY),
        chat_id=int(lead_row.get("chat_id") or 0),
        clarify_attempts=int(attempts or 0),
    )


