# Deploy-epoch guard for the randomized v2 scheduler (day-1x3 / day-Nx1 planned sends):
# rows whose cycle_started_at_utc predates the epoch are left on legacy/no-plan behavior,
# so deploying this patch cannot trigger a catch-up burst to pre-existing active leads.
# If POST_MANUAL_FOLLOWUP_V2_EPOCH_UTC is unset/invalid, the epoch defaults to this
# process's own start time (captured once below), so only cycles that begin after this
# manager process restarts ever get v2 planning - no .env edit required.
POST_MANUAL_FOLLOWUP_V2_EPOCH_UTC_RAW = os.getenv("POST_MANUAL_FOLLOWUP_V2_EPOCH_UTC") or ""
_POST_FOLLOWUP_V2_PROCESS_START_UTC = _tp_utc_now().replace(microsecond=0)
_POST_FOLLOWUP_V2_EPOCH_CACHE: Optional[datetime] = None
_POST_FOLLOWUP_V2_SKIPPED_LOG_DONE = False


async def _ensure_post_followup_table(db_path: str) -> None:
    if not db_path:
        return
    parent = os.path.dirname(db_path)
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(db_path) as db:
        await db.execute("""
            CREATE TABLE IF NOT EXISTS post_manual_followup_state(
                chat_id INTEGER PRIMARY KEY,
                manager_key TEXT DEFAULT '',
                username TEXT DEFAULT '',
                full_name TEXT DEFAULT '',
                active INTEGER NOT NULL DEFAULT 0,
                disabled INTEGER NOT NULL DEFAULT 0,
                disabled_reason TEXT DEFAULT '',
                disabled_at TEXT DEFAULT '',
                disabled_by TEXT DEFAULT '',
                trash INTEGER NOT NULL DEFAULT 0,
                trash_reason TEXT DEFAULT '',
                last_manager_out_utc TEXT DEFAULT '',
                last_client_in_utc TEXT DEFAULT '',
                cycle_started_at_utc TEXT DEFAULT '',
                first_followup_date TEXT DEFAULT '',
                morning_sent_date TEXT DEFAULT '',
                evening_sent_date TEXT DEFAULT '',
                sent_count INTEGER NOT NULL DEFAULT 0,
                sent_text_keys TEXT DEFAULT '',
                last_sent_at_utc TEXT DEFAULT '',
                last_sent_slot TEXT DEFAULT '',
                day_sent_date TEXT DEFAULT '',
                followup_plan_date TEXT DEFAULT '',
                planned_morning_at TEXT DEFAULT '',
                planned_day_at TEXT DEFAULT '',
                planned_evening_at TEXT DEFAULT '',
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        cols = await _table_columns(db, "post_manual_followup_state")
        migrations = [
            ("manager_key", "ALTER TABLE post_manual_followup_state ADD COLUMN manager_key TEXT DEFAULT ''"),
            ("username", "ALTER TABLE post_manual_followup_state ADD COLUMN username TEXT DEFAULT ''"),
            ("full_name", "ALTER TABLE post_manual_followup_state ADD COLUMN full_name TEXT DEFAULT ''"),
            ("active", "ALTER TABLE post_manual_followup_state ADD COLUMN active INTEGER NOT NULL DEFAULT 0"),
            ("disabled", "ALTER TABLE post_manual_followup_state ADD COLUMN disabled INTEGER NOT NULL DEFAULT 0"),
            ("disabled_reason", "ALTER TABLE post_manual_followup_state ADD COLUMN disabled_reason TEXT DEFAULT ''"),
            ("disabled_at", "ALTER TABLE post_manual_followup_state ADD COLUMN disabled_at TEXT DEFAULT ''"),
            ("disabled_by", "ALTER TABLE post_manual_followup_state ADD COLUMN disabled_by TEXT DEFAULT ''"),
            ("trash", "ALTER TABLE post_manual_followup_state ADD COLUMN trash INTEGER NOT NULL DEFAULT 0"),
            ("trash_reason", "ALTER TABLE post_manual_followup_state ADD COLUMN trash_reason TEXT DEFAULT ''"),
            ("last_manager_out_utc", "ALTER TABLE post_manual_followup_state ADD COLUMN last_manager_out_utc TEXT DEFAULT ''"),
            ("last_client_in_utc", "ALTER TABLE post_manual_followup_state ADD COLUMN last_client_in_utc TEXT DEFAULT ''"),
            ("cycle_started_at_utc", "ALTER TABLE post_manual_followup_state ADD COLUMN cycle_started_at_utc TEXT DEFAULT ''"),
            ("first_followup_date", "ALTER TABLE post_manual_followup_state ADD COLUMN first_followup_date TEXT DEFAULT ''"),
            ("morning_sent_date", "ALTER TABLE post_manual_followup_state ADD COLUMN morning_sent_date TEXT DEFAULT ''"),
            ("evening_sent_date", "ALTER TABLE post_manual_followup_state ADD COLUMN evening_sent_date TEXT DEFAULT ''"),
            ("sent_count", "ALTER TABLE post_manual_followup_state ADD COLUMN sent_count INTEGER NOT NULL DEFAULT 0"),
            ("sent_text_keys", "ALTER TABLE post_manual_followup_state ADD COLUMN sent_text_keys TEXT DEFAULT ''"),
            ("last_sent_at_utc", "ALTER TABLE post_manual_followup_state ADD COLUMN last_sent_at_utc TEXT DEFAULT ''"),
            ("last_sent_slot", "ALTER TABLE post_manual_followup_state ADD COLUMN last_sent_slot TEXT DEFAULT ''"),
            ("day_sent_date", "ALTER TABLE post_manual_followup_state ADD COLUMN day_sent_date TEXT DEFAULT ''"),
            ("followup_plan_date", "ALTER TABLE post_manual_followup_state ADD COLUMN followup_plan_date TEXT DEFAULT ''"),
            ("planned_morning_at", "ALTER TABLE post_manual_followup_state ADD COLUMN planned_morning_at TEXT DEFAULT ''"),
            ("planned_day_at", "ALTER TABLE post_manual_followup_state ADD COLUMN planned_day_at TEXT DEFAULT ''"),
            ("planned_evening_at", "ALTER TABLE post_manual_followup_state ADD COLUMN planned_evening_at TEXT DEFAULT ''"),
            ("created_at", "ALTER TABLE post_manual_followup_state ADD COLUMN created_at TEXT NOT NULL DEFAULT ''"),
            ("updated_at", "ALTER TABLE post_manual_followup_state ADD COLUMN updated_at TEXT NOT NULL DEFAULT ''"),
        ]
        for col, ddl in migrations:
            if col not in cols:
                try:
                    await db.execute(ddl)
                except Exception:
                    pass
        try:
            await db.execute("CREATE INDEX IF NOT EXISTS post_manual_followup_active_idx ON post_manual_followup_state(active, disabled, trash, last_manager_out_utc)")
        except Exception:
            pass
        try:
            await db.execute("CREATE INDEX IF NOT EXISTS post_manual_followup_username_idx ON post_manual_followup_state(username)")
        except Exception:
            pass
        await db.commit()


async def _post_followup_note_manager_out(db_path: str, chat_id: int, manager_key: str = "") -> None:
    if int(chat_id or 0) <= 0:
        return
    await _ensure_post_followup_table(db_path)
    now = _now_utc_iso()
    key = registry_normalize_manager_key(manager_key or MANAGER_RUNTIME_KEY)
    async with aiosqlite.connect(db_path) as db:
        await db.execute(
            """
            INSERT INTO post_manual_followup_state(chat_id, manager_key, active, last_manager_out_utc, cycle_started_at_utc, created_at, updated_at)
            VALUES(?,?,?,?,?,?,?)
            ON CONFLICT(chat_id) DO UPDATE SET
                manager_key=excluded.manager_key,
                active=CASE WHEN COALESCE(disabled,0)=1 OR COALESCE(trash,0)=1 THEN active ELSE 1 END,
                last_manager_out_utc=excluded.last_manager_out_utc,
                cycle_started_at_utc=excluded.cycle_started_at_utc,
                updated_at=excluded.updated_at
            """,
            (int(chat_id), key, 1, now, now, now, now),
        )
        await db.commit()


