def _post_followup_due_minute(chat_id: int, date_key: str, slot: str) -> int:
    raw = f"{int(chat_id or 0)}:{date_key}:{slot}:tpilot"
    return sum((i + 1) * ord(ch) for i, ch in enumerate(raw)) % 60


def _post_followup_days_since(first_date: str, today: str) -> int:
    try:
        d0 = datetime.strptime(str(first_date or today)[:10], "%Y-%m-%d").date()
        d1 = datetime.strptime(str(today or _kyiv_now().date().isoformat())[:10], "%Y-%m-%d").date()
        return max(0, (d1 - d0).days)
    except Exception:
        return 0


_POST_FOLLOWUP_SLOT_COLUMNS = {"morning": "morning_sent_date", "day": "day_sent_date", "evening": "evening_sent_date"}
_POST_FOLLOWUP_PLANNED_COLUMNS = {"morning": "planned_morning_at", "day": "planned_day_at", "evening": "planned_evening_at"}


async def _mark_post_followup_sent(db_path: str, chat_id: int, *, slot: str, today_local: str, template_key: str, text: str) -> None:
    await _ensure_post_followup_table(db_path)
    now = _now_utc_iso()
    slot_col = _POST_FOLLOWUP_SLOT_COLUMNS.get(str(slot or ""), "evening_sent_date")
    planned_col = _POST_FOLLOWUP_PLANNED_COLUMNS.get(str(slot or ""), "")
    state = await _get_post_followup_state(db_path, chat_id)
    sent_keys = [x.strip() for x in str(state.get("sent_text_keys") or "").split(",") if x.strip()]
    if template_key and template_key not in sent_keys:
        sent_keys.append(template_key)
    first_date = str(state.get("first_followup_date") or "").strip() or str(today_local)
    sent_count = int(state.get("sent_count") or 0) + 1
    active = 0 if sent_count >= int(POST_MANUAL_FOLLOWUP_MAX_TOTAL or 6) else 1
    planned_clear_sql = f", {planned_col}=''" if planned_col else ""
    async with aiosqlite.connect(db_path) as db:
        await db.execute(
            f"""
            UPDATE post_manual_followup_state
            SET {slot_col}=?,
                first_followup_date=CASE WHEN COALESCE(first_followup_date,'')='' THEN ? ELSE first_followup_date END,
                sent_count=?,
                sent_text_keys=?,
                last_sent_at_utc=?,
                last_sent_slot=?,
                active=?,
                updated_at=?{planned_clear_sql}
            WHERE chat_id=?
            """,
            (str(today_local), first_date, sent_count, ",".join(sent_keys), now, str(slot), active, now, int(chat_id)),
        )
        await db.commit()


async def _get_post_followup_state(db_path: str, chat_id: int) -> Dict[str, Any]:
    await _ensure_post_followup_table(db_path)
    async with aiosqlite.connect(db_path) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM post_manual_followup_state WHERE chat_id=?", (int(chat_id),))
        row = await cur.fetchone()
        return dict(row) if row else {}


async def _set_post_followup_disabled(db_path: str, chat_id: int, disabled: bool, *, user_id: int = 0, reason: str = "manual") -> None:
    await _ensure_post_followup_table(db_path)
    now = _now_utc_iso()
    clear_flag = 1 if disabled else 0
    async with aiosqlite.connect(db_path) as db:
        await db.execute(
            "INSERT OR IGNORE INTO post_manual_followup_state(chat_id, created_at, updated_at) VALUES(?,?,?)",
            (int(chat_id), now, now),
        )
        # Disabling also cancels any already-planned pending sends for this lead
        # (planned_*_at columns), so a randomized future send cannot fire after disable.
        await db.execute(
            """
            UPDATE post_manual_followup_state
            SET disabled=?, disabled_reason=?, disabled_at=?, disabled_by=?, active=CASE WHEN ?=1 THEN 0 ELSE active END,
                planned_morning_at=CASE WHEN ?=1 THEN '' ELSE planned_morning_at END,
                planned_day_at=CASE WHEN ?=1 THEN '' ELSE planned_day_at END,
                planned_evening_at=CASE WHEN ?=1 THEN '' ELSE planned_evening_at END,
                updated_at=?
            WHERE chat_id=?
            """,
            (1 if disabled else 0, str(reason or "manual"), now if disabled else "", str(user_id or ""), clear_flag, clear_flag, clear_flag, clear_flag, now, int(chat_id)),
        )
        await db.commit()


def _is_post_followup_enable_word(raw: str) -> bool:
    return str(raw or "").strip().lower() in {"on", "enable", "start", "вкл", "включить", "1"}


async def _find_post_followup_targets(identifier: str) -> Tuple[List[Dict[str, Any]], str]:
    ident = str(identifier or "").strip()
    if not ident:
        return [], "Укажите username или ID клиента."
    ident_clean = ident.lstrip("@").strip().lower()
    rows = await _manager_rows_for_reporting()
    found: List[Dict[str, Any]] = []
    numeric = False
    try:
        chat_id_value = int(ident_clean)
        numeric = True
    except Exception:
        chat_id_value = 0
    for mgr in rows or []:
        dbp = str(mgr.get("db_path") or "")
        key = registry_normalize_manager_key(mgr.get("manager_key") or "")
        if not dbp or not os.path.exists(dbp):
            continue
        await _ensure_daily_leads_table(dbp)
        try:
            async with aiosqlite.connect(dbp) as db:
                db.row_factory = aiosqlite.Row
                if numeric:
                    cur = await db.execute(
                        "SELECT * FROM daily_leads WHERE chat_id=? ORDER BY first_seen_utc DESC, id DESC LIMIT 1",
                        (int(chat_id_value),),
                    )
                else:
                    cur = await db.execute(
                        "SELECT * FROM daily_leads WHERE lower(replace(COALESCE(username,''),'@',''))=? ORDER BY first_seen_utc DESC, id DESC LIMIT 5",
                        (ident_clean,),
                    )
                for row in await cur.fetchall():
                    d = dict(row)
                    d["_db_path"] = dbp
                    d["_manager_key"] = key
                    d["_manager_label"] = _manager_label_from_row(mgr)
                    found.append(d)
        except Exception:
            continue
    if not found:
        return [], f"Клиент не найден: {ident}"
    # Deduplicate by db + chat_id.
    uniq: Dict[Tuple[str, int], Dict[str, Any]] = {}
    for item in found:
        try:
            uniq[(str(item.get("_db_path") or ""), int(item.get("chat_id") or 0))] = item
        except Exception:
            pass
    return list(uniq.values()), ""


def _post_followup_target_label(item: Dict[str, Any]) -> str:
    username = str(item.get("username") or "").strip()
    full_name = str(item.get("full_name") or "").strip()
    chat_id = int(item.get("chat_id") or 0)
    who = (username if username.startswith("@") else ("@" + username if username else "")) or full_name or f"ID {chat_id}"
    return f"{who} | ID {chat_id} | {item.get('_manager_label') or item.get('_manager_key') or ''}".strip()


async def _format_post_followup_state_for_item(item: Dict[str, Any]) -> str:
    dbp = str(item.get("_db_path") or "")
    chat_id = int(item.get("chat_id") or 0)
    st = await _get_post_followup_state(dbp, chat_id)
    disabled = int(st.get("disabled") or 0) == 1
    active = int(st.get("active") or 0) == 1
    trash = int(st.get("trash") or 0) == 1
    lines = ["🔁 Автодожимы клиента", "", _post_followup_target_label(item)]
    if trash:
        lines.append("Статус: не отправляются, клиент помечен как TRASH")
        if st.get("trash_reason"):
            lines.append(f"Причина: {st.get('trash_reason')}")
    elif disabled:
        lines.append("Статус: выключены вручную")
    elif active:
        lines.append("Статус: включены, ждём подходящее окно")
    else:
        lines.append("Статус: сейчас не активны")
    lines.append(f"Отправлено всего: {int(st.get('sent_count') or 0)}")
    if st.get("last_sent_at_utc"):
        lines.append(f"Последняя отправка: {_iso_to_local_hhmm(str(st.get('last_sent_at_utc') or ''))}")
    if st.get("last_manager_out_utc"):
        lines.append(f"Последний ответ менеджера: {_iso_to_local_hhmm(str(st.get('last_manager_out_utc') or ''))}")
    if st.get("last_client_in_utc"):
        lines.append(f"Последний ответ клиента: {_iso_to_local_hhmm(str(st.get('last_client_in_utc') or ''))}")
    return chr(10).join(lines).rstrip()


async def _handle_post_followup_command(args: str, *, user_id: int = 0) -> str:
    raw = str(args or "").strip()
    if not raw or raw.lower() in {"help", "?", "помощь"}:
        return "\n".join([
            "🔁 Автодожимы после ручного общения",
            "",
            "Команды:",
            "/followup off @username",
            "/followup off 123456789",
            "/followup on @username",
            "/followup on 123456789",
            "/followup status @username",
            "/followup status 123456789",
            "",
            "Лучше использовать ID клиента, потому что username может измениться.",
            "Автодожимы работают максимум 2 раза в день, утром и вечером, не больше 3 дней и 6 сообщений на клиента.",
        ]).rstrip()
    parts = raw.split(maxsplit=1)
    action = parts[0].strip().lower()
    ident = parts[1].strip() if len(parts) > 1 else ""
    if _is_post_followup_disable_word(action):
        mode = "off"
    elif _is_post_followup_enable_word(action):
        mode = "on"
    elif action in {"status", "статус"}:
        mode = "status"
    else:
        return "Формат: /followup off 123456789, /followup on 123456789 или /followup status 123456789"
    targets, err = await _find_post_followup_targets(ident)
    if err:
        return err
    if len(targets) > 1 and not ident.lstrip("@").strip().isdigit():
        lines = ["Найдено несколько клиентов. Используйте ID:", ""]
        for item in targets[:10]:
            lines.append(_post_followup_target_label(item))
        return chr(10).join(lines).rstrip()
    lines: List[str] = []
    for item in targets:
        dbp = str(item.get("_db_path") or "")
        chat_id = int(item.get("chat_id") or 0)
        if mode == "off":
            await _set_post_followup_disabled(dbp, chat_id, True, user_id=user_id, reason="manual_off")
            lines.append("🔕 Автодожимы выключены")
            lines.append(_post_followup_target_label(item))
        elif mode == "on":
            await _set_post_followup_disabled(dbp, chat_id, False, user_id=user_id, reason="manual_on")
            lines.append("🔔 Автодожимы включены")
            lines.append(_post_followup_target_label(item))
        else:
            lines.append(await _format_post_followup_state_for_item(item))
        lines.append("")
    return chr(10).join(lines).rstrip()


async def _process_post_manual_followups_once() -> int:
    if CONTROLLER_MODE or not MANAGER_RUNTIME_KEY or not POST_MANUAL_FOLLOWUP_ENABLED:
        return 0
    now_local = _kyiv_now()
    if not _tp_followup_allowed_now(now_local):
        return 0
    today_local = now_local.date().isoformat()
    now_utc_dt = _tp_utc_now().replace(microsecond=0)
    mgr_key = registry_normalize_manager_key(MANAGER_RUNTIME_KEY)

    # TPILOT HEALTH RECOVERY HYBRID-D 20260723: autodozhim only ever replies
    # within an existing conversation (new_dialog=False), so the central
    # health gate only stops this whole tick while BLOCKED -- an unresolved
    # LIMITED (e.g. PeerFlood on NEW peers) does not affect replies to leads
    # who already have a dialog with this manager.
    try:
        gate_allowed_tick, gate_reason_tick = await _tp_hg_send_allowed(mgr_key, new_dialog=False)
    except Exception as gate_error:
        gate_allowed_tick, gate_reason_tick = (
            False,
            f"gate_error_fail_closed:{type(gate_error).__name__}",
        )
    if not gate_allowed_tick:
        print(f"post_manual_followup send paused manager={mgr_key} reason={gate_reason_tick}")
        return 0

    try:
        hour_count, day_count = await _post_followup_window_counts(DB_PATH, mgr_key, now_utc_dt)
    except Exception:
        hour_count, day_count = 0, 0

    sent = 0
    v2_skipped_pre_epoch = 0
    for row in await _fetch_post_followup_candidates(DB_PATH, today_local=today_local, limit=100):
        if hour_count >= int(POST_MANUAL_FOLLOWUP_MAX_PER_HOUR or 20) or day_count >= int(POST_MANUAL_FOLLOWUP_MAX_PER_DAY or 80):
            break
        chat_id = int(row.get("chat_id") or 0)
        if chat_id <= 0:
            continue
        gate_allowed, _gate_reason = await _lead_automation_gate(mgr_key, chat_id, "autodozhim")
        if not gate_allowed:
            continue
        cycle_local = _post_followup_local_date_of(str(row.get("cycle_started_at_utc") or "")) or today_local
        if _post_followup_days_since(cycle_local, today_local) >= int(POST_MANUAL_FOLLOWUP_MAX_DAYS or 3):
            # Existing max_days aging-out applies regardless of the v2 epoch guard below,
            # so pre-epoch rows still get cleaned up over time instead of staying active forever.
            await _set_post_followup_disabled(DB_PATH, chat_id, True, user_id=0, reason="max_days")
            continue
        if not _post_followup_v2_allowed_for_row(row):
            # Pre-epoch / legacy cycle: never plan v2 slots for it (no catch-up burst).
            # Left on no-send behavior; it will still age out via the max_days check above.
            v2_skipped_pre_epoch += 1
            continue
        row = await _post_followup_ensure_daily_plan(DB_PATH, chat_id, row, today_local)
        slot = _post_followup_due_slot(row, now_utc_dt, today_local)
        if not slot:
            continue
        sent_keys = str(row.get("sent_text_keys") or "")
        template_key, text = choose_post_manual_followup_text(sent_keys, chat_id=chat_id, date_key=today_local, slot=slot)
        ok, fail_kind = await _send_manager_private_ex(chat_id, text, human_delay=True, after_first_delay=True, new_dialog=False)
        if not ok:
            if fail_kind in ("gate_denied", "restriction"):
                # PEERFLOOD RECOVERY 20260812: a health-gate denial (BLOCKED /
                # manual mark / unexpired FloodWait cooldown / newly BLOCKED
                # mid-tick) or a classified Telegram restriction from this
                # very send (PeerFlood/FloodWait/BLOCKED) is never an ordinary
                # delivery failure -- do not penalize this specific lead, and
                # stop trying further sends this tick (owner-approved "one
                # probe per tick").
                print(f"post_manual_followup send paused manager={mgr_key} reason={fail_kind}")
                break
            await _post_followup_mark_trash(DB_PATH, chat_id, "send_failed")
            continue
        await _mark_post_followup_sent(DB_PATH, chat_id, slot=slot, today_local=today_local, template_key=template_key, text=text)
        sent += 1
        hour_count += 1
        day_count += 1
        await asyncio.sleep(random.randint(max(1, POST_MANUAL_FOLLOWUP_BATCH_SLEEP_MIN_SEC), max(2, POST_MANUAL_FOLLOWUP_BATCH_SLEEP_MAX_SEC)))
    if v2_skipped_pre_epoch:
        global _POST_FOLLOWUP_V2_SKIPPED_LOG_DONE
        if not _POST_FOLLOWUP_V2_SKIPPED_LOG_DONE:
            print(f"post_manual_followup v2 epoch guard: skipped {v2_skipped_pre_epoch} pre-epoch row(s) manager={mgr_key} epoch={_post_followup_v2_epoch_utc().isoformat()}")
            _POST_FOLLOWUP_V2_SKIPPED_LOG_DONE = True
    return sent


async def _post_manual_followup_loop() -> None:
    if CONTROLLER_MODE or not MANAGER_RUNTIME_KEY:
        return
    while True:
        try:
            await _process_post_manual_followups_once()
            await asyncio.sleep(60)
        except asyncio.CancelledError:
            return
        except Exception as e:
            print(f"post_manual_followup_loop error: {e!r}")
            await asyncio.sleep(60)

# -------------------- command handlers --------------------
async def _handle_work_status_command(event: events.NewMessage.Event) -> bool:
    if not CONTROLLER_MODE:
        return False
    if not WORK_STATUS_CHAT_ID:
        return False
    if int(event.chat_id or 0) != int(WORK_STATUS_CHAT_ID or 0):
        return False
    text = (event.raw_text or "").strip()
    if not text:
        return False
    cmd, args = _parse_cmd(text)
    if cmd not in ("/online", "/offline", "/dayoff", "/workday", "/worknow", "/status"):
        return False

    sender_id = int(event.sender_id or 0)
    arg = registry_normalize_manager_key((args or "").split()[0]) if args else ""

    if cmd == "/status" and arg == "all":
        rows = await manager_list_rows(include_removed=False)
        lines = ["WORK STATUS:"]
        for row in rows or []:
            key = registry_normalize_manager_key(row.get("manager_key") or "")
            if not key:
                continue
            st = await _get_manager_work_status(key)
            lines.append(f"{key}: {str(st.get('status') or 'online')}")
        await client.send_message(event.chat_id, "\n".join(lines))
        return True

    key = arg or await _manager_key_from_status_sender(sender_id)
    if not key:
        await client.send_message(event.chat_id, "Не смог определить менеджера. Используйте: /online <manager_key>, /worknow <manager_key>, /offline <manager_key>, /dayoff <manager_key> или /status <manager_key>.")
        return True

    row = await manager_get(key)
    if not row or str(row.get("status") or "") == "archived":
        await client.send_message(event.chat_id, f"Менеджер не найден: {key}")
        return True

    if cmd in ("/online", "/workday", "/worknow", "/offline", "/dayoff"):
        if cmd in ("/online", "/workday"):
            st_value = "online"
        elif cmd == "/worknow":
            st_value = "worknow"
        elif cmd == "/dayoff":
            st_value = "dayoff"
        else:
            st_value = "offline"
        st = await _set_manager_work_status(key, st_value, user_id=sender_id, source='manual')
        icon = "☀️" if st_value == "worknow" else ("🟢" if st_value == "online" else ("🌙" if st_value == "dayoff" else "🔴"))
        note = "\nДневное приветствие и анкета включены прямо сейчас." if st_value == "worknow" else ""
        await client.send_message(event.chat_id, f"{icon} {key}: {st.get('status')}{note}")
        return True

    st = await _get_manager_work_status(key)
    await client.send_message(event.chat_id, f"{key}: {str(st.get('status') or 'online')}")
    return True

@client.on(events.NewMessage)
async def on_new_message(event: events.NewMessage.Event) -> None:
    try:
        if CONTROLLER_MODE:
            if await _handle_manager_plaintext(event):
                return
            if await _handle_work_status_command(event):
                return
            if await _handle_ai_stat_command(event):
                return
            return
        # TPILOT DEVICE-LOGIN 20260719: a 777000 (Telegram service) login-code
        # message must never become a "lead" -- intercept and consume it BEFORE
        # _record_incoming_from_manager. Defined later in this file (before the
        # __main__ guard); resolved via late name binding at call time, same
        # convention as every other helper referenced here.
        if await _devlogin_maybe_capture(event):
            return
        await _record_incoming_from_manager(event)
    except FloodWaitError as e:
        await asyncio.sleep(int(getattr(e, "seconds", 5) or 5))
    except Exception as e:
        print(f"on_new_message error: {e!r}")


async def _controller_autostart_registry_managers() -> None:
    if not CONTROLLER_MODE:
        return
    await asyncio.sleep(8)
    try:
        rows = await manager_list_rows(include_removed=False, only_enabled=True, only_active=True)
    except Exception:
        return
    for row in rows:
        key = registry_normalize_manager_key(row.get("manager_key") or "")
        if not key:
            continue
        if int(row.get("manual_stopped") or 0) == 1:
            continue
        try:
            if await _manager_process_running(key):
                continue
            await _spawn_manager_process(key)
            await asyncio.sleep(1)
        except Exception:
            continue


# -------------------- TPilot Panel bridge --------------------
async def _panel_format_status_all() -> str:
    rows = await manager_list_rows(include_removed=False)
    lines = ["👥 Статусы менеджеров"]
    for row in rows or []:
        # TPILOT PREPARED ACCOUNTS PHASE 3: this is a rendered AdminBot
        # working-list surface (each entry gets an online/offline-style
        # icon) -- a prepared account is neither online nor offline, it
        # simply isn't a working manager yet, so it is excluded rather than
        # shown with a misleading icon.
        if str(row.get("status") or "").strip().lower() == "prepared":
            continue
        key = registry_normalize_manager_key(row.get("manager_key") or "")
        if not key:
            continue
        st = await _get_manager_work_status(key)
        val = str(st.get("status") or "online").lower()
        icon = "☀️" if val == "worknow" else ("🟢" if val == "online" else ("🌙" if val in ("dayoff", "no_show", "auto_offline") else "🔴"))
        lines.append(f"{icon} {val} {key}")
    return chr(10).join(lines).rstrip()


# --- TPILOT EXPORT RANGE PATCH START ---

EXPORT_PERIOD_LIMIT_DAYS = int(os.getenv("EXPORT_PERIOD_LIMIT_DAYS") or str(globals().get("HISTORY_DAYS_LIMIT", 31) or 31))




# --- TPILOT PERIOD RANGE REPAIR V2 START ---
def _period_parse_date(raw: str):
    try:
        return _tp_parse_date_token(str(raw or ""))
    except Exception:
        return None


def _period_key(raw: Any) -> str:
    try:
        return _structure_key(raw)
    except Exception:
        return registry_normalize_manager_key(str(raw or ""))


def _period_display(start_d, end_d) -> str:
    if start_d == end_d:
        return start_d.strftime("%d.%m.%y")
    return f"{start_d.strftime('%d.%m.%y')} - {end_d.strftime('%d.%m.%y')}"


def _period_validate_dates(start_d, end_d):
    today = _kyiv_now().date()
    limit = max(1, int(globals().get("EXPORT_PERIOD_LIMIT_DAYS", globals().get("HISTORY_DAYS_LIMIT", 31)) or 31))
    if start_d > end_d:
        start_d, end_d = end_d, start_d
    if end_d > today:
        return None, None, "Будущие даты недоступны."
    min_day = today - timedelta(days=limit - 1)
    if start_d < min_day:
        return None, None, f"Дата вне доступного периода. Можно смотреть последние {limit} дней."
    if (end_d - start_d).days + 1 > limit:
        return None, None, f"Период слишком большой. Максимум {limit} дней."
    return start_d, end_d, ""


def _parse_period_command_parts(parts: List[str], *, default_scope: str = "manager") -> Tuple[Dict[str, Any], str]:
    raw_parts = [str(p or "").strip() for p in (parts or []) if str(p or "").strip()]
    if raw_parts and raw_parts[0].lower() in ("range", "period", "период", "с"):
        raw_parts = raw_parts[1:]

    date_items = []
    other = []
    for token in raw_parts:
        d = _period_parse_date(token)
        if d:
            date_items.append(d)
        else:
            other.append(token)

    if len(date_items) < 2:
        return {}, "Формат: range <all|manager_key|source source_key|group group_key> <дата_с> <дата_по>"

    start_d, end_d, err = _period_validate_dates(date_items[0], date_items[1])
    if err:
        return {}, err

    scope = "all"
    key = "all"
    if other:
        first = other[0].lower()
        if first in ("all", "все"):
            scope, key = "all", "all"
        elif first in ("source", "src", "источник"):
            if len(other) < 2:
                return {}, "Формат: range source <source_key> <дата_с> <дата_по>"
            scope, key = "source", _period_key(other[1])
        elif first in ("group", "mgroup", "группа"):
            if len(other) < 2:
                return {}, "Формат: range group <group_key> <дата_с> <дата_по>"
            scope, key = "group", _period_key(other[1])
        else:
            scope, key = "manager", registry_normalize_manager_key(other[0])

    if not key:
        return {}, "Не указан target для периода."
    return {
        "scope": scope,
        "key": key,
        "start": start_d.isoformat(),
        "end": end_d.isoformat(),
        "label": _period_display(start_d, end_d),
        "target_label": key if scope == "manager" else ("all" if scope == "all" else f"{scope}:{key}"),
    }, ""


async def _period_manager_keys_for_scope(scope: str, key: str) -> Tuple[set[str], str]:
    scope = str(scope or "all").lower()
    key = _period_key(key or "all")
    if scope == "all":
        return set(), "Все менеджеры"
    if scope == "manager":
        return {registry_normalize_manager_key(key)}, f"Менеджер: {registry_normalize_manager_key(key)}"
    if scope == "source":
        try:
            await _ensure_sources_groups_tables()
        except Exception:
            pass
        keys = set()
        name = key
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            try:
                cur = await db.execute("SELECT name FROM traffic_sources WHERE source_key=? LIMIT 1", (key,))
                row = await cur.fetchone()
                if row and row[0]:
                    name = str(row[0])
            except Exception:
                pass
            try:
                cur = await db.execute("SELECT manager_key FROM manager_source_links WHERE source_key=?", (key,))
                for r in await cur.fetchall():
                    mk = registry_normalize_manager_key(r[0])
                    if mk:
                        keys.add(mk)
            except Exception:
                pass
        return keys, f"Источник: {name}"
    if scope == "group":
        try:
            await _ensure_sources_groups_tables()
        except Exception:
            pass
        keys = set()
        name = key
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            try:
                cur = await db.execute("SELECT name FROM manager_groups WHERE group_key=? LIMIT 1", (key,))
                row = await cur.fetchone()
                if row and row[0]:
                    name = str(row[0])
            except Exception:
                pass
            try:
                cur = await db.execute("SELECT manager_key FROM manager_group_members WHERE group_key=?", (key,))
                for r in await cur.fetchall():
                    mk = registry_normalize_manager_key(r[0])
                    if mk:
                        keys.add(mk)
            except Exception:
                pass
        return keys, f"Группа: {name}"
    return set(), "Все менеджеры"


async def _collect_period_leads(scope: str, key: str, start_iso: str, end_iso: str) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]], str]:
    start_d = _date_obj_from_iso(start_iso)
    end_d = _date_obj_from_iso(end_iso)
    allowed_keys, scope_label = await _period_manager_keys_for_scope(scope, key)
    rows_all = await _manager_rows_for_reporting()
    rows = []
    for r in rows_all:
        mk = registry_normalize_manager_key(r.get("manager_key") or "")
        if not mk:
            continue
        if scope == "manager" and mk not in allowed_keys:
            continue
        if scope in ("source", "group") and mk not in allowed_keys:
            continue
        rows.append(r)

    leads: List[Dict[str, Any]] = []
    d = start_d
    while d <= end_d:
        for mgr in rows:
            mk = registry_normalize_manager_key(mgr.get("manager_key") or "")
            for lead in await _list_daily_leads_for_db(str(mgr.get("db_path") or ""), d.isoformat()):
                item = dict(lead)
                item["manager_key"] = mk or item.get("manager_key") or ""
                item["manager_display_name"] = str(mgr.get("display_name") or mk)
                item["manager_username"] = str(mgr.get("telegram_username") or item.get("manager_username") or "")
                leads.append(item)
        d += timedelta(days=1)
    leads.sort(key=lambda x: (str(x.get("first_seen_utc") or ""), str(x.get("manager_key") or ""), int(x.get("id") or 0)))
    return leads, rows, scope_label


async def _build_stat_period_text(spec: Dict[str, Any]) -> str:
    scope = str(spec.get("scope") or "all")
    key = str(spec.get("key") or "all")
    start_iso = str(spec.get("start") or "")
    end_iso = str(spec.get("end") or "")
    label = str(spec.get("label") or f"{start_iso} - {end_iso}")
    leads, rows, scope_label = await _collect_period_leads(scope, key, start_iso, end_iso)
    stats = _stats_from_leads(leads, rows, target_key="all")
    lines = [f"📊 Статистика за период {label}", scope_label, ""]
    if not rows:
        lines.append("Менеджеры для выбранного периода не найдены.")
        return chr(10).join(lines).rstrip()
    for b in stats["buckets"]:
        if int(b.get("total") or 0) == 0:
            continue
        lines.append(str(b.get("label") or b.get("key") or "_"))
        lines.append(f"Всего написавших: {int(b['total'])}")
        lines.append(f"Новые: {int(b['new'])}")
        lines.append(f"Дубликаты: {int(b['duplicates'])}")
        lines.append(f"Ответили возраст/гео: {int(b['profile_done'])}")
        lines.append(f"Ликвид: {int(b['liquid'])}")
        lines.append(f"Не��иквид: {int(b['nonliquid'])}")
        lines.append(f"Не определено: {int(b['unknown'])}")
        _append_reason_lines(lines, b.get("reasons") or {})
        lines.append("")
    lines.append("Итого:")
    lines.append(f"Всего написавших: {int(stats['total'])}")
    lines.append(f"Новые: {int(stats['new'])}")
    lines.append(f"Дубликаты: {int(stats['duplicates'])}")
    lines.append(f"Ответили возраст/гео: {int(stats['profile_done'])}")
    lines.append(f"Ликвид: {int(stats['liquid'])}")
    lines.append(f"Неликвид: {int(stats['nonliquid'])}")
    lines.append(f"Не определено: {int(stats['unknown'])}")
    _append_reason_lines(lines, stats.get("reasons") or {})
    return chr(10).join(lines).rstrip()


async def _export_period_xlsx(spec: Dict[str, Any]) -> str:
    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font, Alignment
        from openpyxl.utils import get_column_letter
    except Exception as e:
        raise RuntimeError("openpyxl не установлен. Установите: pip install openpyxl") from e

    scope = str(spec.get("scope") or "all")
    key = str(spec.get("key") or "all")
    start_iso = str(spec.get("start") or "")
    end_iso = str(spec.get("end") or "")
    leads, _rows, scope_label = await _collect_period_leads(scope, key, start_iso, end_iso)
    os.makedirs(EXPORT_DIR, exist_ok=True)
    safe_target = re.sub(r"[^a-zA-Z0-9_.-]+", "_", str(spec.get("target_label") or "all")).strip("_") or "all"
    out_path = os.path.join(EXPORT_DIR, f"leads_period_{start_iso}_{end_iso}_{safe_target}.xlsx")

    wb = Workbook()
    ws = wb.active
    ws.title = "leads"
    headers = [
        "№", "Дата", "Время", "Период", "Фильтр", "manager_key", "Аккаунт менеджера", "chat_id", "username", "Имя аккаунта", "Телефон", "Дубликат",
        "Возраст", "Город", "Регион", "Страна", "С��атус", "Причина неликвида", "Источник гео", "Точность", "Пометка", "Режим менеджера", "Вопрос отправлен", "Offline-сообщение", "UA текст", "Менеджер ответил",
    ]
    ws.append(headers)
    for cell in ws[1]:
        cell.font = Font(bold=True)
        cell.alignment = Alignment(horizontal="center")
    label = str(spec.get("label") or f"{start_iso} - {end_iso}")
    for idx, r in enumerate(leads, 1):
        dt = _utc_iso_to_kyiv_dt(str(r.get("first_seen_utc") or ""))
        manager_username = str(r.get("manager_username") or "").strip()
        manager_display = str(r.get("manager_display_name") or r.get("manager_key") or "").strip()
        manager_account = f"{manager_display} | @{manager_username}" if manager_username else manager_display
        status_raw = str(r.get("status") or "").strip()
        status_disp = "ликвид" if status_raw == "liquid" else ("неликвид" if status_raw == "nonliquid" else "не определено")
        ws.append([
            idx, dt.strftime("%d.%m.%Y"), dt.strftime("%H:%M:%S"), label, scope_label,
            str(r.get("manager_key") or ""), manager_account, int(r.get("chat_id") or 0),
            _display_username(str(r.get("username") or "")) if str(r.get("username") or "").strip() else "_",
            str(r.get("full_name") or "").strip() or "_", str(r.get("phone") or "").strip() or "_",
            "да" if int(r.get("duplicate") or 0) == 1 else "нет", _display_unknown(r.get("age")), _display_unknown(r.get("city")),
            _display_unknown(r.get("region")), _display_unknown(r.get("country")), status_disp,
            str(r.get("nonliquid_reason") or "").strip() or "_", str(r.get("geo_source") or "").strip() or "_",
            str(r.get("geo_confidence") or "").strip() or "_", str(r.get("geo_note") or "").strip() or "_",
            str(r.get("manager_work_status") or "").strip() or "_",
            "да" if int(r.get("profile_question_sent") or 0) == 1 else "нет",
            "да" if int(r.get("offline_notice_sent") or 0) == 1 else "нет",
            "да" if int(r.get("ua_text_sent") or 0) == 1 else "нет",
            "да" if int(r.get("manager_replied") or 0) == 1 else "нет",
        ])
    widths = [6, 14, 13, 22, 24, 18, 28, 18, 22, 28, 18, 12, 12, 22, 28, 18, 16, 22, 18, 14, 28, 18, 18, 18, 12, 18]
    for i, width in enumerate(widths, 1):
        ws.column_dimensions[get_column_letter(i)].width = width
    ws.freeze_panes = "A2"
    wb.save(out_path)
    return out_path
