def _parse_export_args(raw_args: str):
    # Return (target, mode, date_val, days). mode: day, range, period, bad_date, bad_period.
    parts = [p for p in str(raw_args or "").split() if p.strip()]
    target = ""
    date_val = None
    days = 0

    if parts and parts[0].lower() in ("range", "period", "период", "с"):
        spec, err = _parse_period_command_parts(parts, default_scope="manager")
        if err:
            return "", "bad_period", {"error": err}, 0
        return str(spec.get("target_label") or "all"), "period", spec, 0

    parsed_dates = []
    for p in parts:
        d = _tp_parse_date_token(p) if callable(globals().get("_tp_parse_date_token")) else None
        if d:
            parsed_dates.append(d)
    if len(parsed_dates) >= 2:
        spec, err = _parse_period_command_parts(["range"] + parts, default_scope="manager")
        if err:
            return "", "bad_period", {"error": err}, 0
        return str(spec.get("target_label") or "all"), "period", spec, 0

    for p in parts:
        token = str(p or "").strip()
        low = token.lower()
        d = None
        try:
            d = _tp_parse_date_token(token) if callable(globals().get("_tp_parse_date_token")) else None
        except Exception:
            d = None

        if d:
            date_val = d
            continue
        if low in ("7d", "7д", "week", "weeks", "неделя", "за_неделю"):
            days = 7
            continue
        if low in ("31d", "30d", "month", "месяц", "за_месяц"):
            days = 31
            continue
        if re.fullmatch(r"\d{1,2}d", low):
            try:
                days = int(low[:-1])
                continue
            except Exception:
                pass
        if low in ("all", "все"):
            target = "all"
            continue
        if not target:
            target = registry_normalize_manager_key(token)

    if not target:
        target = ""
    if days:
        days = max(1, min(int(days), int(EXPORT_PERIOD_LIMIT_DAYS or 31)))
        return target, "range", None, days
    if date_val:
        try:
            if callable(globals().get("_tp_date_within_history")) and not _tp_date_within_history(date_val):
                return target, "bad_date", date_val, 0
        except Exception:
            pass
        return target, "day", date_val, 0
    return target, "day", None, 0



def _date_obj_from_iso(value: str):
    return datetime.strptime(str(value), "%Y-%m-%d").date()


async def _export_range_xlsx(target_key: str = "all", start_date: str = "", end_date: str = "") -> str:
    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font, Alignment
        from openpyxl.utils import get_column_letter
    except Exception as e:
        raise RuntimeError("openpyxl не установлен. Установите: pip install openpyxl") from e

    target_key = registry_normalize_manager_key(target_key or "all") or "all"
    today = _kyiv_now().date()

    if not end_date:
        end_d = today
    else:
        end_d = _date_obj_from_iso(str(end_date))

    if not start_date:
        start_d = end_d
    else:
        start_d = _date_obj_from_iso(str(start_date))

    if start_d > end_d:
        start_d, end_d = end_d, start_d

    max_days = max(1, int(EXPORT_PERIOD_LIMIT_DAYS or 31))
    if (end_d - start_d).days + 1 > max_days:
        start_d = end_d - timedelta(days=max_days - 1)

    if end_d > today:
        end_d = today
    min_allowed = today - timedelta(days=max_days - 1)
    if start_d < min_allowed:
        start_d = min_allowed

    leads: List[Dict[str, Any]] = []
    d = start_d
    while d <= end_d:
        try:
            leads.extend(await _collect_day_leads(d.isoformat(), target_key=target_key))
        except Exception as e:
            print(f"export range collect error {d.isoformat()}: {e!r}")
        d += timedelta(days=1)

    os.makedirs(EXPORT_DIR, exist_ok=True)
    suffix = "all" if target_key == "all" else target_key
    out_path = os.path.join(EXPORT_DIR, f"leads_{start_d.isoformat()}_{end_d.isoformat()}_{suffix}.xlsx")

    wb = Workbook()
    ws = wb.active
    ws.title = "leads"
    headers = [
        "№", "Дата", "Время", "manager_key", "Аккаунт менеджера", "chat_id", "username", "Имя аккаунта", "Телефон", "Дубликат",
        "Возраст", "Город", "Регион", "Страна", "Статус", "Причина неликвида", "Источник гео", "Точность", "Пометка", "Режим менеджера", "Вопрос отправлен", "Offline-сообщение", "UA текст", "Менеджер ответил",
    ]
    ws.append(headers)
    for cell in ws[1]:
        cell.font = Font(bold=True)
        cell.alignment = Alignment(horizontal="center")

    for idx, r in enumerate(leads, 1):
        dt = _utc_iso_to_kyiv_dt(str(r.get("first_seen_utc") or ""))
        manager_username = str(r.get("manager_username") or "").strip()
        manager_display = str(r.get("manager_display_name") or r.get("manager_key") or "").strip()
        manager_account = f"{manager_display} | @{manager_username}" if manager_username else manager_display
        status_raw = str(r.get("status") or "").strip()
        status_disp = "ликвид" if status_raw == "liquid" else ("неликвид" if status_raw == "nonliquid" else "не определено")
        ws.append([
            idx,
            dt.strftime("%d.%m.%Y"),
            dt.strftime("%H:%M:%S"),
            str(r.get("manager_key") or ""),
            manager_account,
            int(r.get("chat_id") or 0),
            _display_username(str(r.get("username") or "")) if str(r.get("username") or "").strip() else "_",
            str(r.get("full_name") or "").strip() or "_",
            str(r.get("phone") or "").strip() or "_",
            "да" if int(r.get("duplicate") or 0) == 1 else "нет",
            _display_unknown(r.get("age")),
            _display_unknown(r.get("city")),
            _display_unknown(r.get("region")),
            _display_unknown(r.get("country")),
            status_disp,
            str(r.get("nonliquid_reason") or "").strip() or "_",
            str(r.get("geo_source") or "").strip() or "_",
            str(r.get("geo_confidence") or "").strip() or "_",
            str(r.get("geo_note") or "").strip() or "_",
            str(r.get("manager_work_status") or "").strip() or "_",
            "да" if int(r.get("profile_question_sent") or 0) == 1 else "нет",
            "да" if int(r.get("offline_notice_sent") or 0) == 1 else "нет",
            "да" if int(r.get("ua_text_sent") or 0) == 1 else "нет",
            "да" if int(r.get("manager_replied") or 0) == 1 else "нет",
        ])

    widths = [6, 14, 13, 18, 28, 18, 22, 28, 18, 12, 12, 22, 28, 18, 16, 22, 18, 14, 28, 18, 18, 18, 12, 18]
    for i, width in enumerate(widths, 1):
        ws.column_dimensions[get_column_letter(i)].width = width
    ws.freeze_panes = "A2"
    wb.save(out_path)
    return out_path


async def _run_export_command(target: str, mode: str, date_val=None, days: int = 0):
    target = registry_normalize_manager_key(target or "")
    if not target:
        return False, "", "Формат: /export all или /export <manager_key>", ""

    rows = await _manager_rows_for_reporting()
    keys = {registry_normalize_manager_key(r.get("manager_key") or "") for r in rows}
    if target != "all" and target not in keys:
        return False, "", f"Менеджер не найден: {target}", ""

    if mode == "bad_date":
        return False, "", f"Дата вне доступного периода. Можно смотреть последние {EXPORT_PERIOD_LIMIT_DAYS} дней.", ""

    if mode == "bad_period":
        err = ""
        try:
            err = str((date_val or {}).get("error") or "")
        except Exception:
            err = ""
        return False, "", err or "Неверный формат периода.", ""

    await _process_pending_lead_events()

    if mode == "period":
        spec = date_val if isinstance(date_val, dict) else {}
        if not spec:
            return False, "", "Неверный формат периода.", ""
        path = await _export_period_xlsx(spec)
        caption = f"📎 Выгрузка за период {spec.get('label') or ''} | {spec.get('target_label') or target}"
        return True, path, "", caption

    if mode == "range":
        days = max(1, min(int(days or 7), int(EXPORT_PERIOD_LIMIT_DAYS or 31)))
        end_d = _kyiv_now().date()
        start_d = end_d - timedelta(days=days - 1)
        path = await _export_range_xlsx(target, start_d.isoformat(), end_d.isoformat())
        caption = f"📎 Выгрузка за {days} дней | {target}"
        return True, path, "", caption

    lead_date = date_val.isoformat() if date_val else None
    path = await _export_day_xlsx(target, lead_date)
    caption_date = date_val.strftime("%d.%m.%y") if date_val else _kyiv_now().strftime("%d.%m.%y")
    caption = f"📎 Выгрузка за {caption_date} | {target}"
    return True, path, "", caption


# --- TPILOT EXPORT RANGE PATCH END ---

def _panel_command_timing_log(
    *,
    cmd_id: int = 0,
    elapsed: float = 0.0,
    status: str,
    requested_by: int = 0,
    command_text: str = "",
    error_text: str = "",
) -> None:
    """Append one TSV line to runtime/panel_command_timing.log.

    Fields (tab-separated):
      utc_iso_timestamp, command_id, duration_sec, status,
      requested_by, command_text, error_text

    Called for: done, error, and reaper events (reaped > 0).
    Never raises; all failures are silently swallowed.
    """
    try:
        ts = _now_utc_iso()
        cmd_clean = str(command_text or "").replace("\t", " ").replace("\n", " ")
        err_clean = str(error_text or "").replace("\t", " ").replace("\n", " ")
        line = "\t".join([
            ts,
            str(int(cmd_id or 0)),
            f"{float(elapsed or 0.0):.3f}",
            str(status or ""),
            str(int(requested_by or 0)),
            cmd_clean,
            err_clean,
        ])
        log_path = BASE_DIR / "runtime" / "panel_command_timing.log"
        log_path.parent.mkdir(parents=True, exist_ok=True)
        with log_path.open("a", encoding="utf-8") as _f:
            _f.write(line + "\n")
    except Exception:
        pass


async def _panel_command_loop() -> None:
    if not CONTROLLER_MODE:
        return
    try:
        from panel_bridge import (
            cleanup_panel_commands,
            ensure_panel_tables,
            finish_panel_command,
            reap_stale_running_panel_commands,
            take_next_panel_command,
        )
    except Exception as e:
        print(f"panel bridge import error: {e!r}")
        return
    try:
        ensure_panel_tables(TPILOT_DB_PATH)
    except Exception as e:
        print(f"panel table init error: {e!r}")
    _loop_iter = 0
    while True:
        try:
            _loop_iter += 1
            # Periodic maintenance: reap stale-running rows and clean up old done/error rows.
            # Run every 120 iterations (~60s at 0.5s poll). Independent of command execution.
            if _loop_iter % 120 == 1:
                try:
                    reaped = reap_stale_running_panel_commands(TPILOT_DB_PATH, stale_minutes=60)
                    if reaped:
                        print(f"[panel_cmd] reaped {reaped} stale-running panel_commands")
                        _panel_command_timing_log(
                            status="reaped",
                            command_text="[reaper]",
                            error_text=f"{reaped} rows reaped",
                        )
                except Exception:
                    pass
                try:
                    cleanup_panel_commands(TPILOT_DB_PATH, keep_hours=48)
                except Exception:
                    pass

            row = take_next_panel_command(TPILOT_DB_PATH)
            if not row:
                await asyncio.sleep(0.5)
                continue
            cmd_id = int(row.get("id") or 0)
            command_text = str(row.get("command_text") or "").strip()
            requested_by = int(row.get("requested_by") or 0)
            _t0 = time.monotonic()
            print(f"[panel_cmd] start id={cmd_id} by={requested_by} cmd={command_text!r:.80}")
            try:
                res = await _panel_execute_command_text(command_text, requested_by=requested_by)
                _elapsed = time.monotonic() - _t0
                _ok = bool(res.get("ok"))
                print(f"[panel_cmd] done  id={cmd_id} ok={_ok} elapsed={_elapsed:.1f}s")
                finish_panel_command(
                    TPILOT_DB_PATH,
                    cmd_id,
                    ok=_ok,
                    result_text=str(res.get("result_text") or ""),
                    result_file=str(res.get("result_file") or ""),
                    result_caption=str(res.get("result_caption") or ""),
                    error_text=str(res.get("error_text") or ""),
                )
                _panel_command_timing_log(
                    cmd_id=cmd_id,
                    elapsed=_elapsed,
                    status="done" if _ok else "error",
                    requested_by=requested_by,
                    command_text=command_text,
                    error_text=str(res.get("error_text") or ""),
                )
            except Exception as e:
                _elapsed = time.monotonic() - _t0
                print(f"[panel_cmd] error id={cmd_id} elapsed={_elapsed:.1f}s err={e!r}")
                finish_panel_command(TPILOT_DB_PATH, cmd_id, ok=False, error_text=repr(e))
                _panel_command_timing_log(
                    cmd_id=cmd_id,
                    elapsed=_elapsed,
                    status="error",
                    requested_by=requested_by,
                    command_text=command_text,
                    error_text=repr(e),
                )
        except asyncio.CancelledError:
            return
        except Exception as e:
            print(f"panel_command_loop error: {e!r}")
            await asyncio.sleep(1)


# --- TPILOT RECONNECT BACKFILL M2.6F START ---

async def _mb_backfill_daily_leads_from_events(manager_key: str) -> None:
    """Rebuild per-manager daily_leads from central events on startup.
    No-op if tables absent, events absent, or per-manager DB is same as central."""
    import json as _bf_json
    mk = str(manager_key or "").strip()
    if not mk or not DB_PATH or DB_PATH == TPILOT_DB_PATH:
        return
    try:
        async with aiosqlite.connect(str(DB_PATH)) as per_db:
            await per_db.execute("PRAGMA journal_mode=WAL;")
            await per_db.execute("PRAGMA busy_timeout=15000;")
            chk = await per_db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name='daily_leads' LIMIT 1"
            )
            if not await chk.fetchone():
                return
    except Exception as _e:
        print(f"[backfill] per-db check error: {_e!r}")
        return
    try:
        async with aiosqlite.connect(str(TPILOT_DB_PATH)) as src_db:
            await src_db.execute("PRAGMA journal_mode=WAL;")
            chk2 = await src_db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name='manager_bot_events' LIMIT 1"
            )
            if not await chk2.fetchone():
                return
            cur = await src_db.execute(
                "SELECT chat_id, lead_date, payload_json FROM manager_bot_events "
                "WHERE manager_key=? AND event_type='lead_card'",
                (mk,),
            )
            rows = await cur.fetchall()
    except Exception as _e:
        print(f"[backfill] central events read error: {_e!r}")
        return
    if not rows:
        return
    try:
        now = _now_utc_iso()
    except Exception:
        import datetime as _bf_dt
        now = _bf_dt._tp_utc_now().replace(microsecond=0).isoformat()
    inserted = 0
    try:
        async with aiosqlite.connect(str(DB_PATH)) as dst_db:
            await dst_db.execute("PRAGMA journal_mode=WAL;")
            await dst_db.execute("PRAGMA busy_timeout=15000;")
            for ev in rows:
                chat_id = int(ev[0] or 0) if ev[0] else 0
                lead_date = str(ev[1] or "").strip()
                if not chat_id or not lead_date:
                    continue
                try:
                    payload = _bf_json.loads(str(ev[2] or "{}") or "{}")
                except Exception:
                    payload = {}
                first_seen = str(payload.get("first_seen_utc") or now)
                try:
                    cur2 = await dst_db.execute(
                        "INSERT OR IGNORE INTO daily_leads"
                        "(manager_key, chat_id, lead_date, first_seen_utc, created_at, updated_at)"
                        " VALUES (?,?,?,?,?,?)",
                        (mk, chat_id, lead_date, first_seen, now, now),
                    )
                    inserted += cur2.rowcount
                except Exception:
                    pass
            await dst_db.commit()
        print(f"[backfill] manager={mk} events={len(rows)} inserted={inserted}")
    except Exception as _e:
        print(f"[backfill] per-db write error: {_e!r}")

# --- TPILOT RECONNECT BACKFILL M2.6F END ---


def _m212a_fail_startup(reason_class: str, error: str) -> None:
    """TPILOT RUNTIME AUTH SESSION-REUSE FIX 20260718: writes a precise
    start_status exit reason then raises SystemExit -- the entrypoint's own
    except-block (main.py, bottom of file) explicitly skips overwriting
    start_status for KeyboardInterrupt/SystemExit, so this reason_class is
    never clobbered by the generic 'process_exited' the normal-return path
    would otherwise write. Never logs the raw exception object -- only the
    bounded, pre-formatted `error` string."""
    print(f"[startup] auth failed ({reason_class}): {error}")
    if MANAGER_RUNTIME_KEY and not CONTROLLER_MODE:
        _m212a_write_start_status(MANAGER_RUNTIME_KEY, "exited", reason_class=reason_class, error=error[:500])
    raise SystemExit(1)


async def main() -> None:
    global SELF_USERNAME, SELF_USERNAME_DISPLAY, PUBLIC_MANAGER_NAME
    await init_db()
    await _ensure_daily_leads_table(DB_PATH)
    await _ensure_lead_auto_state_table(DB_PATH)
    await _ensure_profile_reminder_table(DB_PATH)
    await _ensure_work_status_table()

    # --- TPILOT RUNTIME AUTH SESSION-REUSE FIX 20260718 START ---
    # Previously: `await client.start(phone=PHONE if PHONE else None)` was called
    # unconditionally. Telethon's own client.start() raises "No phone number or
    # bot token provided." (telethon/client/auth.py, the `if not phone and not
    # bot_token` guard) BEFORE it ever attempts its own authorized-session reuse
    # (connect + is_user_authorized + get_me, same module, later in _start) --
    # so a manager with a fully authorized on-disk session but an empty PHONE
    # (e.g. a manager created via replacement, whose phone was never persisted)
    # could never start, even though Telethon itself would have reused the
    # session with zero login needed. Fix: connect and check
    # is_user_authorized() FIRST; only fall through to the interactive
    # phone-based client.start() when the on-disk session genuinely is not
    # authorized. Never opens a second client on this session.
    await client.connect()
    try:
        _runtime_already_authorized = bool(await client.is_user_authorized())
    except Exception:
        _runtime_already_authorized = False

    if not _runtime_already_authorized:
        # --- HNV2 D3 20260807: headless worker never logs in interactively ---
        # A manager runtime is spawned with no console of its own
        # (_spawn_manager_process -> Popen(["cmd","/c",start_manager.bat,key],
        # main.py:_spawn_manager_process; start_manager.ps1 Start-Process
        # -WindowStyle Hidden), and neither redirects stdin, so the child
        # inherits the parent's. Telethon's client.start() without
        # code_callback= falls back to
        # input('Please enter the code you received: ')
        # (telethon/client/auth.py, invoked from _start) -- but only AFTER
        # it has already issued a real SendCodeRequest (auth.py, earlier in
        # _start). With an inherited console the worker blocks there
        # forever at phase='starting'; with a closed stdin it raises
        # EOFError. Either way a login code was already burned, with no
        # FloodWait guard and without consulting
        # manager_onboarding.next_code_allowed_at -- the cooldown every
        # explicit onboarding/re-login path DOES honour. A worker therefore
        # refuses outright. Re-login is an operator action via the Panel:
        # relogin:start / wiz:qr_start / devlogin:start.
        if MANAGER_RUNTIME_KEY and not CONTROLLER_MODE:
            try:
                await client.disconnect()
            except Exception:
                pass
            _m212a_fail_startup(
                "session_unauthorized",
                "Сессия не авторизована. Автоматический вход из рабочего процесса запрещён — "
                "выполните вход через Панель: «Перезайти», «Войти по QR» или «Вход на устройстве».",
            )
        # CONTROLLER_MODE only (console-attached, operator present): the
        # historical interactive path is preserved unchanged.
        if not PHONE:
            _m212a_fail_startup("session_unauthorized", "Сессия не авторизована, номер телефона не задан -- нужен вход.")
        try:
            await client.start(phone=PHONE)
        except Exception as e:
            _m212a_fail_startup("session_unauthorized", f"Не удалось выполнить вход: {e!r}")
    # --- TPILOT RUNTIME AUTH SESSION-REUSE FIX 20260718 END ---

    # M2.12A: mark connected after successful auth (fresh login OR existing session reuse)
    if MANAGER_RUNTIME_KEY and not CONTROLLER_MODE:
        _m212a_write_start_status(MANAGER_RUNTIME_KEY, "connected",
                                   last_connected_at=_now_utc_iso())

    try:
        me = await client.get_me()
        if me is None:
            if MANAGER_RUNTIME_KEY and not CONTROLLER_MODE:
                _m212a_fail_startup("session_unauthorized", "get_me() вернул пусто после успешного входа.")
        else:
            SELF_USERNAME = getattr(me, "username", None) or ""
            SELF_USERNAME_DISPLAY = f"@{SELF_USERNAME}" if SELF_USERNAME else "_"
            try:
                await set_setting("self_username", SELF_USERNAME)
                await set_setting("self_user_id", str(getattr(me, "id", "")))
            except Exception:
                pass
            if MANAGER_RUNTIME_KEY:
                try:
                    row0 = get_manager_row_from_db_sync(TPILOT_DB_PATH, MANAGER_RUNTIME_KEY) or {}
                    # TPILOT RUNTIME AUTH SESSION-REUSE FIX 20260718: if the
                    # registry already has a durable tg_user_id for this
                    # manager, the live session's identity MUST match it --
                    # never silently overwrite a divergent identity (that
                    # would mask e.g. a stale/reused session file pointing at
                    # the wrong Telegram account). A never-yet-set tg_user_id
                    # (0/None -- first login) is written normally below.
                    stored_tgid = int(row0.get("tg_user_id") or 0)
                    live_tgid = int(getattr(me, "id", 0) or 0)
                    if stored_tgid and live_tgid and stored_tgid != live_tgid:
                        _m212a_fail_startup(
                            "telegram_identity_mismatch",
                            f"Telegram id не совпадает: в реестре {stored_tgid}, у сессии {live_tgid}.",
                        )
                    PUBLIC_MANAGER_NAME = str(row0.get("display_name") or PUBLIC_MANAGER_NAME or MANAGER_NAME or MANAGER_RUNTIME_KEY)
                    # TPILOT PHONE SELF-HEAL 20260719: runs ONLY after the identity-
                    # mismatch guard above already succeeded (a mismatch raises
                    # SystemExit and this line is never reached) -- so Telegram
                    # identity is already validated by this point. A TData/.session
                    # imported manager can have an empty registry PHONE even though
                    # the now-authorized session itself exposes me.phone (Telethon
                    # reports it digits-only, no leading '+'); prefer that live value
                    # -- normalized to the SAME '+<digits>' format phone-login already
                    # stores (admin-entered as "PHONE +79991234567", stored as-is) --
                    # over the registry PHONE, which only ever falls back to the OLD
                    # (possibly empty) value when Telegram itself doesn't expose one.
                    # Never logged in full anywhere in this block.
                    session_phone = _tp_normalize_phone_plus(getattr(me, "phone", None))
                    resolved_phone = session_phone or PHONE
                    # MANAGER_PROFILE_SYNC_20260711: was manager_update_profile_in_db, which
                    # refreshed telegram_username/first_name/last_name but never display_name
                    # -- the field every UI actually renders -- so a Telegram rename never
                    # showed up anywhere. This helper refreshes display_name too, but only
                    # when it is not a manual admin alias (display_name_source='manual' via
                    # /manager_rename), which it never touches. Registry DB (TPILOT_DB_PATH)
                    # only -- never the per-manager runtime DB.
                    await manager_sync_telegram_profile_in_db(
                        TPILOT_DB_PATH,
                        MANAGER_RUNTIME_KEY,
                        tg_user_id=live_tgid or None,
                        telegram_username=SELF_USERNAME,
                        first_name=(getattr(me, "first_name", None) or ""),
                        last_name=(getattr(me, "last_name", None) or ""),
                        phone=resolved_phone,
                        status="active",
                        last_login_at=_now_utc_iso(),
                        last_error="",
                    )
                except SystemExit:
                    raise
                except Exception as e:
                    # TPILOT IDENTITY RECONCILE 20260809: stable grep-able prefix so a
                    # startup profile-sync failure is actually findable in
                    # logs\manager_<key>.err.log -- was a bare unprefixed line. This is
                    # still a best-effort cosmetic write: never re-raised, startup
                    # continues exactly as before.
                    print(f"[identity-sync] startup profile update error manager={MANAGER_RUNTIME_KEY!r}: {e!r}")
                # TPILOT MANAGERBOT ACCESS AUTO-GRANT 20260727: covers the
                # tdata-import / ready-.session onboarding paths, where
                # tg_user_id is written HERE (in the spawned manager
                # runtime), not by the controller's own finalize -- that
                # call site's grant never fires for this path. Best-effort:
                # a failure here must never abort runtime startup.
                try:
                    _mbgrant_result = manager_bot_access_ensure_sync(
                        tg_user_id=live_tgid or None,
                        manager_key=MANAGER_RUNTIME_KEY,
                        display_name=PUBLIC_MANAGER_NAME,
                        username=SELF_USERNAME,
                        db_path=TPILOT_DB_PATH,
                    )
                    if _mbgrant_result.get("status") == "error":
                        print(f"[onboarding] ManagerBot access grant error for {MANAGER_RUNTIME_KEY}: {_mbgrant_result.get('error')}")
                except SystemExit:
                    raise
                except Exception as e:
                    print(f"[onboarding] ManagerBot access grant failed for {MANAGER_RUNTIME_KEY}: {e!r}")
                try:
                    await _mb_backfill_daily_leads_from_events(MANAGER_RUNTIME_KEY)
                except Exception as _bfe:
                    print(f"[backfill] startup error: {_bfe!r}")
    except SystemExit:
        raise
    except Exception:
        pass

    if CONTROLLER_MODE:
        client.loop.create_task(_lead_dispatch_loop())
        client.loop.create_task(_daily_report_loop())
        client.loop.create_task(_controller_autostart_registry_managers())
        client.loop.create_task(_tpilot_unanswered_loop())
        client.loop.create_task(_panel_command_loop())
        client.loop.create_task(_schedule_summary_loop())  # M2.13D-1
        client.loop.create_task(_bizlink_autocreate_loop())  # M2.13D-2
        client.loop.create_task(_reserve_activation_loop())  # STAGE D R2
        client.loop.create_task(_prenew_notify_expiring_loop())  # STAGE 5 proxy renewal warnings
        client.loop.create_task(_prenew_autorenew_loop())  # STAGE 6.1F guarded per-proxy auto-renew
        client.loop.create_task(_manager_command_sweep_loop())  # TPILOT F 20260718: expired-command + commit-deadline sweeper
        client.loop.create_task(_tdimport_stale_sweep_loop())  # TPILOT TDATA/SESSION IMPORT 20260719: abandoned-import scrub + lock release
        client.loop.create_task(_devlogin_sweep_loop())  # TPILOT DEVICE-LOGIN 20260719: expired device-login request scrub + lock release
        client.loop.create_task(_devlogin_rescan_loop())  # TPILOT DEVICE-LOGIN 20260719: periodic bounded devlogin_scan arm for active requests
        client.loop.create_task(_plc_reconcile_loop())  # PROXY LIFECYCLE SYNC 20260721: terminal-scan + bidirectional provider auto_renew reconcile
        client.loop.create_task(_renewal_loop())  # PROXY RENEWAL 20260721: TPilot-managed prolong scheduler (restart reconcile + guarded automatic tick; no-op while automation OFF)
        client.loop.create_task(_renewal_balance_alert_loop())  # PROXY RENEWAL 20260721: low-balance AdminBot alert (read-only, independent of automation on/off)
        if MANAGER_RECOVERY_ENABLED:
            client.loop.create_task(_manager_recovery_loop())  # M2.15
        if HEALTH_AGG_ENABLED:
            client.loop.create_task(_health_agg_loop())  # R1A
    elif MANAGER_RUNTIME_KEY:
        client.loop.create_task(_profile_reminder_loop())
        client.loop.create_task(_post_manual_followup_loop())

    print(f"ALM_TPilot lead tracker started | key={MANAGER_KEY} | controller={CONTROLLER_MODE} | db={DB_PATH}")
    # M2.12A: mark running immediately before blocking on run_until_disconnected()
    if MANAGER_RUNTIME_KEY and not CONTROLLER_MODE:
        _m212a_write_start_status(MANAGER_RUNTIME_KEY, "running")
    await client.run_until_disconnected()


# --- TPILOT MANUAL PROFILE / UNANSWERED / HISTORY PATCH START ---
# Added: per-manager AUTO profile ON/OFF, passive manual profile parsing,
# unanswered clients, 31-day historical det/flight commands, and safer Panel bridge.

PROFILE_AUTO_DEFAULT_ENABLED = (os.getenv("PROFILE_AUTO_DEFAULT_ENABLED") or "1").strip().lower() in ("1", "true", "yes", "on")
UNANSWERED_ALERT_MINUTES = int(os.getenv("UNANSWERED_ALERT_MINUTES") or "15")
UNANSWERED_REPEAT_MINUTES = int(os.getenv("UNANSWERED_REPEAT_MINUTES") or "30")
PROFILE_CAPTURE_MAX_MESSAGES = int(os.getenv("PROFILE_CAPTURE_MAX_MESSAGES") or "3")
HISTORY_DAYS_LIMIT = int(os.getenv("HISTORY_DAYS_LIMIT") or "31")

_TPILOT_ORIG_MAYBE_AUTO_REPLY_TO_LEAD = globals().get("_maybe_auto_reply_to_lead")
_TPILOT_ORIG_MARK_MANAGER_REPLIED = globals().get("_mark_manager_replied")
_TPILOT_ORIG_RECORD_DAILY_LEAD_EVENT = globals().get("_record_daily_lead_event")


def _tp_dt_utc_now() -> datetime:
    return _tp_utc_now().replace(microsecond=0)


def _tp_parse_utc(raw: str) -> Optional[datetime]:
    try:
        dt = datetime.fromisoformat(str(raw or ""))
        if dt.tzinfo is not None:
            dt = dt.astimezone(timezone.utc).replace(tzinfo=None)
        return dt.replace(microsecond=0)
    except Exception:
        return None


def _tp_local_to_utc_iso(dt_local: datetime) -> str:
    if dt_local.tzinfo is None:
        dt_local = dt_local.replace(tzinfo=TZ_KYIV)
    return dt_local.astimezone(timezone.utc).replace(tzinfo=None, microsecond=0).isoformat()


def _tp_parse_date_token(raw: str):
    s = str(raw or "").strip()
    if not s:
        return None
    for fmt in ("%d.%m.%y", "%d.%m.%Y", "%Y-%m-%d", "%d-%m-%y", "%d-%m-%Y"):
        try:
            return datetime.strptime(s, fmt).date()
        except Exception:
            pass
    return None


def _tp_date_within_history(d) -> bool:
    try:
        today = _kyiv_now().date()
        return (today - d).days >= 0 and (today - d).days <= HISTORY_DAYS_LIMIT
    except Exception:
        return True


def _tp_date_display(d) -> str:
    return d.strftime("%d.%m.%y")


async def _tpilot_patch_init() -> None:
    try:
        await _ensure_profile_auto_table()
        await _ensure_workday_table()
        if not CONTROLLER_MODE:
            await _ensure_manual_profile_tables(DB_PATH)
    except Exception as e:
        print(f"tpilot patch init error: {e!r}")


async def _ensure_profile_auto_table() -> None:
    parent = os.path.dirname(TPILOT_DB_PATH)
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute("PRAGMA journal_mode=WAL;")
        await db.execute("""
            CREATE TABLE IF NOT EXISTS manager_profile_auto(
                manager_key TEXT PRIMARY KEY,
                auto_enabled INTEGER NOT NULL DEFAULT 1,
                updated_at TEXT NOT NULL DEFAULT '',
                updated_by_user_id INTEGER
            );
        """)
        await db.commit()


async def _get_profile_auto_enabled(manager_key: str) -> bool:
    key = registry_normalize_manager_key(manager_key or "")
    if not key:
        return PROFILE_AUTO_DEFAULT_ENABLED
    await _ensure_profile_auto_table()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        cur = await db.execute("SELECT auto_enabled FROM manager_profile_auto WHERE manager_key=?", (key,))
        row = await cur.fetchone()
        if not row:
            return PROFILE_AUTO_DEFAULT_ENABLED
        return int(row[0] or 0) == 1


async def _set_profile_auto_enabled(manager_key: str, enabled: bool, *, user_id: int = 0) -> None:
    key = registry_normalize_manager_key(manager_key or "")
    if not key:
        return
    await _ensure_profile_auto_table()
    now = _now_utc_iso()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute(
            """
            INSERT INTO manager_profile_auto(manager_key, auto_enabled, updated_at, updated_by_user_id)
            VALUES(?,?,?,?)
            ON CONFLICT(manager_key) DO UPDATE SET
              auto_enabled=excluded.auto_enabled,
              updated_at=excluded.updated_at,
              updated_by_user_id=excluded.updated_by_user_id
            """,
            (key, 1 if enabled else 0, now, int(user_id or 0) or None),
        )
        await db.commit()


async def _ensure_workday_table() -> None:
    parent = os.path.dirname(TPILOT_DB_PATH)
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute("PRAGMA journal_mode=WAL;")
        await db.execute("""
            CREATE TABLE IF NOT EXISTS manager_work_days(
                manager_key TEXT NOT NULL,
                work_date TEXT NOT NULL,
                is_working INTEGER NOT NULL DEFAULT 1,
                first_manual_out_utc TEXT DEFAULT '',
                last_manual_out_utc TEXT DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT '',
                PRIMARY KEY(manager_key, work_date)
            );
        """)
        await db.commit()


async def _mark_manager_working_day(manager_key: str, when_utc_iso: str = "") -> None:
    key = registry_normalize_manager_key(manager_key or "")
    if not key:
        return
    await _ensure_workday_table()
    when = _tp_parse_utc(when_utc_iso) or _tp_dt_utc_now()
    local = when.replace(tzinfo=timezone.utc).astimezone(TZ_KYIV)
    work_date = local.date().isoformat()
    now = _now_utc_iso()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute(
            """
            INSERT INTO manager_work_days(manager_key, work_date, is_working, first_manual_out_utc, last_manual_out_utc, updated_at)
            VALUES(?,?,?,?,?,?)
            ON CONFLICT(manager_key, work_date) DO UPDATE SET
              is_working=1,
              first_manual_out_utc=CASE WHEN COALESCE(first_manual_out_utc,'')='' THEN excluded.first_manual_out_utc ELSE first_manual_out_utc END,
              last_manual_out_utc=excluded.last_manual_out_utc,
              updated_at=excluded.updated_at
            """,
            (key, work_date, 1, when.replace(microsecond=0).isoformat(), when.replace(microsecond=0).isoformat(), now),
        )
        await db.commit()


async def _manager_day_is_working(manager_key: str, date_iso: str) -> bool:
    key = registry_normalize_manager_key(manager_key or "")
    if not key or not date_iso:
        return True
    await _ensure_workday_table()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        cur = await db.execute("SELECT is_working FROM manager_work_days WHERE manager_key=? AND work_date=?", (key, str(date_iso)))
        row = await cur.fetchone()
        if row:
            return int(row[0] or 0) == 1
    try:
        d = datetime.strptime(str(date_iso), "%Y-%m-%d").date()
        today = _kyiv_now().date()
        if d < today:
            return True
        now = _kyiv_now()
        if d == today and (now.hour > 8 or (now.hour == 8 and now.minute >= 30)):
            return False
    except Exception:
        pass
    return True


async def _ensure_manual_profile_tables(db_path: str) -> None:
    if not db_path:
        return
    parent = os.path.dirname(str(db_path))
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(db_path) as db:
        await db.execute("PRAGMA journal_mode=WAL;")
        await db.execute("""
            CREATE TABLE IF NOT EXISTS profile_capture_state(
                chat_id INTEGER PRIMARY KEY,
                manager_key TEXT DEFAULT '',
                is_open INTEGER NOT NULL DEFAULT 0,
                messages_left INTEGER NOT NULL DEFAULT 0,
                opened_at_utc TEXT DEFAULT '',
                close_at_utc TEXT DEFAULT '',
                reason TEXT DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        await db.execute("""
            CREATE TABLE IF NOT EXISTS unanswered_tracking(
                chat_id INTEGER PRIMARY KEY,
                manager_key TEXT DEFAULT '',
                username TEXT DEFAULT '',
                full_name TEXT DEFAULT '',
                last_inbound_utc TEXT DEFAULT '',
                last_manager_reply_utc TEXT DEFAULT '',
                waiting INTEGER NOT NULL DEFAULT 0,
                last_alert_utc TEXT DEFAULT '',
                alert_sent_for_inbound_utc TEXT DEFAULT '',
                daily_summary_date TEXT DEFAULT '',
                daily_summary_sent_utc TEXT DEFAULT '',
                closed INTEGER NOT NULL DEFAULT 0,
                trash INTEGER NOT NULL DEFAULT 0,
                trash_reason TEXT DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        cols = await _table_columns(db, "unanswered_tracking")
        unanswered_migrations = [
            ("alert_sent_for_inbound_utc", "ALTER TABLE unanswered_tracking ADD COLUMN alert_sent_for_inbound_utc TEXT DEFAULT ''"),
            ("daily_summary_date", "ALTER TABLE unanswered_tracking ADD COLUMN daily_summary_date TEXT DEFAULT ''"),
            ("daily_summary_sent_utc", "ALTER TABLE unanswered_tracking ADD COLUMN daily_summary_sent_utc TEXT DEFAULT ''"),
        ]
        for col, ddl in unanswered_migrations:
            if col not in cols:
                try:
                    await db.execute(ddl)
                except Exception:
                    pass
        await db.commit()


def _profile_request_words(text: str) -> bool:
    t = str(text or "").lower().replace("ё", "е")
    patterns = [
        "город", "возраст", "сколько вам", "сколько тебе", "сколько лет", "полных лет",
        "из какого", "откуда", "где жив", "где прож", "страна", "регион",
    ]
    return any(p in t for p in patterns)


def _profile_close_at_utc_for_today() -> str:
    now = _kyiv_now()
    close_local = now.replace(hour=17, minute=0, second=0, microsecond=0)
    if now >= close_local:
        close_local = (now + timedelta(days=1)).replace(hour=17, minute=0, second=0, microsecond=0)
    return _tp_local_to_utc_iso(close_local)


async def _open_profile_capture(db_path: str, chat_id: int, manager_key: str, reason: str = "manual_question") -> None:
    await _ensure_manual_profile_tables(db_path)
    now = _now_utc_iso()
    async with aiosqlite.connect(db_path) as db:
        await db.execute(
            """
            INSERT INTO profile_capture_state(chat_id, manager_key, is_open, messages_left, opened_at_utc, close_at_utc, reason, updated_at)
            VALUES(?,?,?,?,?,?,?,?)
            ON CONFLICT(chat_id) DO UPDATE SET
              manager_key=excluded.manager_key,
              is_open=1,
              messages_left=excluded.messages_left,
              opened_at_utc=excluded.opened_at_utc,
              close_at_utc=excluded.close_at_utc,
              reason=excluded.reason,
              updated_at=excluded.updated_at
            """,
            (int(chat_id), registry_normalize_manager_key(manager_key or ""), 1, PROFILE_CAPTURE_MAX_MESSAGES, now, _profile_close_at_utc_for_today(), str(reason or "manual_question"), now),
        )
        await db.commit()


async def _capture_is_open(db_path: str, chat_id: int) -> bool:
    await _ensure_manual_profile_tables(db_path)
    now = _tp_dt_utc_now()
    async with aiosqlite.connect(db_path) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM profile_capture_state WHERE chat_id=?", (int(chat_id),))
        row = await cur.fetchone()
        if not row:
            return False
        d = dict(row)
        if int(d.get("is_open") or 0) != 1:
            return False
        if int(d.get("messages_left") or 0) <= 0:
            return False
        close_dt = _tp_parse_utc(str(d.get("close_at_utc") or ""))
        if close_dt and now > close_dt:
            return False
        return True


async def _decrement_capture(db_path: str, chat_id: int) -> None:
    await _ensure_manual_profile_tables(db_path)
    now = _now_utc_iso()
    async with aiosqlite.connect(db_path) as db:
        await db.execute(
            """
            UPDATE profile_capture_state
            SET messages_left=CASE WHEN messages_left>0 THEN messages_left-1 ELSE 0 END,
                is_open=CASE WHEN messages_left<=1 THEN 0 ELSE is_open END,
                updated_at=?
            WHERE chat_id=?
            """,
            (now, int(chat_id)),
        )
        await db.commit()


async def _close_capture_if_done(db_path: str, chat_id: int) -> None:
    await _ensure_manual_profile_tables(db_path)
    async with aiosqlite.connect(db_path) as db:
        await db.execute("UPDATE profile_capture_state SET is_open=0, updated_at=? WHERE chat_id=?", (_now_utc_iso(), int(chat_id)))
        await db.commit()




async def _unanswered_inbound(db_path: str, *, chat_id: int, manager_key: str, username: str = "", full_name: str = "") -> None:
    """Open one unanswered episode per chat until a manual manager reply closes it.

    While waiting=1, repeated client messages do not reset the timer and do not create
    new 15-minute alerts. A new timer starts only after the manager has replied and
    the client writes again.
    """
    await _ensure_manual_profile_tables(db_path)
    now = _now_utc_iso()
    async with aiosqlite.connect(db_path) as db:
        await db.execute(
            """
            INSERT INTO unanswered_tracking(
                chat_id, manager_key, username, full_name, last_inbound_utc,
                waiting, last_alert_utc, alert_sent_for_inbound_utc,
                daily_summary_date, daily_summary_sent_utc, closed, trash, updated_at
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)
            ON CONFLICT(chat_id) DO UPDATE SET
              manager_key=excluded.manager_key,
              username=CASE WHEN excluded.username<>'' THEN excluded.username ELSE username END,
              full_name=CASE WHEN excluded.full_name<>'' THEN excluded.full_name ELSE full_name END,
              last_inbound_utc=CASE
                  WHEN COALESCE(unanswered_tracking.waiting,0)=1
                       AND COALESCE(unanswered_tracking.closed,0)=0
                       AND COALESCE(unanswered_tracking.trash,0)=0
                       AND COALESCE(unanswered_tracking.last_inbound_utc,'')<>''
                  THEN unanswered_tracking.last_inbound_utc
                  ELSE excluded.last_inbound_utc
              END,
              waiting=CASE WHEN COALESCE(unanswered_tracking.trash,0)=1 THEN unanswered_tracking.waiting ELSE 1 END,
              closed=CASE WHEN COALESCE(unanswered_tracking.trash,0)=1 THEN unanswered_tracking.closed ELSE 0 END,
              last_alert_utc=CASE WHEN COALESCE(unanswered_tracking.waiting,0)=1 AND COALESCE(unanswered_tracking.trash,0)=0 THEN unanswered_tracking.last_alert_utc ELSE '' END,
              alert_sent_for_inbound_utc=CASE WHEN COALESCE(unanswered_tracking.waiting,0)=1 AND COALESCE(unanswered_tracking.trash,0)=0 THEN unanswered_tracking.alert_sent_for_inbound_utc ELSE '' END,
              daily_summary_date=CASE WHEN COALESCE(unanswered_tracking.waiting,0)=1 AND COALESCE(unanswered_tracking.trash,0)=0 THEN unanswered_tracking.daily_summary_date ELSE '' END,
              daily_summary_sent_utc=CASE WHEN COALESCE(unanswered_tracking.waiting,0)=1 AND COALESCE(unanswered_tracking.trash,0)=0 THEN unanswered_tracking.daily_summary_sent_utc ELSE '' END,
              updated_at=excluded.updated_at
            """,
            (
                int(chat_id), registry_normalize_manager_key(manager_key or ""), str(username or ""), str(full_name or ""), now,
                1, "", "", "", "", 0, 0, now,
            ),
        )
        await db.commit()




async def _unanswered_manager_replied(db_path: str, chat_id: int, manager_key: str = "") -> None:
    await _ensure_manual_profile_tables(db_path)
    now = _now_utc_iso()
    async with aiosqlite.connect(db_path) as db:
        await db.execute("INSERT OR IGNORE INTO unanswered_tracking(chat_id, manager_key, updated_at) VALUES(?,?,?)", (int(chat_id), registry_normalize_manager_key(manager_key or ""), now))
        await db.execute("UPDATE unanswered_tracking SET waiting=0, last_manager_reply_utc=?, updated_at=? WHERE chat_id=?", (now, now, int(chat_id)))
        await db.commit()


async def _unanswered_mark_trash(db_path: str, chat_id: int, reason: str = "trash") -> None:
    await _ensure_manual_profile_tables(db_path)
    now = _now_utc_iso()
    async with aiosqlite.connect(db_path) as db:
        await db.execute("INSERT OR IGNORE INTO unanswered_tracking(chat_id, updated_at) VALUES(?,?)", (int(chat_id), now))
        await db.execute("UPDATE unanswered_tracking SET waiting=0, trash=1, trash_reason=?, updated_at=? WHERE chat_id=?", (str(reason or "trash"), now, int(chat_id)))
        await db.commit()
    try:
        await _mark_profile_reminder_trash(db_path, chat_id, reason)
    except Exception:
        pass
    try:
        await _post_followup_mark_trash(db_path, chat_id, reason)
    except Exception:
        pass
    try:
        if await _autostatus_runtime_enabled():
            await _ensure_daily_leads_table(db_path)
            async with aiosqlite.connect(db_path) as db:
                await db.execute("UPDATE daily_leads SET status='trash', updated_at=? WHERE chat_id=?", (now, int(chat_id)))
                await db.commit()
    except Exception:
        pass



async def _fetch_unanswered_for_db(db_path: str, *, due_only: bool = False, limit: int = 200) -> List[Dict[str, Any]]:
    if not db_path or not os.path.exists(db_path):
        return []
    await _ensure_manual_profile_tables(db_path)
    cutoff = (_tp_dt_utc_now() - timedelta(minutes=UNANSWERED_ALERT_MINUTES)).isoformat()
    async with aiosqlite.connect(db_path) as db:
        db.row_factory = aiosqlite.Row
        if due_only:
            cur = await db.execute("""
                SELECT * FROM unanswered_tracking
                WHERE COALESCE(waiting,0)=1 AND COALESCE(trash,0)=0 AND COALESCE(closed,0)=0
                  AND COALESCE(last_inbound_utc,'')<>'' AND last_inbound_utc<=?
                  AND COALESCE(last_alert_utc,'')=''
                ORDER BY last_inbound_utc ASC LIMIT ?
            """, (cutoff, int(limit)))
        else:
            cur = await db.execute("""
                SELECT * FROM unanswered_tracking
                WHERE COALESCE(waiting,0)=1 AND COALESCE(trash,0)=0 AND COALESCE(closed,0)=0
                ORDER BY last_inbound_utc ASC LIMIT ?
            """, (int(limit),))
        return [dict(r) for r in await cur.fetchall()]



def _wait_minutes(row: Dict[str, Any]) -> int:
    dt = _tp_parse_utc(str(row.get("last_inbound_utc") or ""))
    if not dt:
        return 0
    return max(0, int((_tp_dt_utc_now() - dt).total_seconds() // 60))


def _unanswered_line(row: Dict[str, Any]) -> str:
    username = str(row.get("username") or "").strip()
    full_name = str(row.get("full_name") or "").strip()
    chat_id = int(row.get("chat_id") or 0)
    who = (username if username.startswith("@") else ("@" + username if username else "")) or full_name or f"ID {chat_id}"
    return f"{who} | ждёт {_wait_minutes(row)} мин"


async def _format_unanswered_text(target_key: str = "all", *, due_only: bool = False) -> str:
    rows = await _manager_rows_for_reporting()
    target = registry_normalize_manager_key(target_key or "all")
    lines = ["🔔 Неотвеченные клиенты", ""]
    total = 0
    any_block = False
    for mgr in rows:
        key = registry_normalize_manager_key(mgr.get("manager_key") or "")
        if target != "all" and key != target:
            continue
        items = await _fetch_unanswered_for_db(str(mgr.get("db_path") or ""), due_only=due_only, limit=100)
        if not items and target == "all":
            continue
        any_block = True
        total += len(items)
        lines.append(_manager_label_from_row(mgr))
        lines.append(f"Всего: {len(items)}")
        if items:
            lines.append("")
            for idx, it in enumerate(items[:30], 1):
                lines.append(f"{idx}) {_unanswered_line(it)}")
        lines.append("")
    if not any_block:
        lines.append("Неотвеченных сейчас нет.")
    elif target == "all":
        lines.append(f"Итого: {total}")
    return chr(10).join(lines).rstrip()



async def _set_unanswered_alerted(db_path: str, chat_ids: List[int]) -> None:
    if not chat_ids:
        return
    await _ensure_manual_profile_tables(db_path)
    now = _now_utc_iso()
    async with aiosqlite.connect(db_path) as db:
        for cid in chat_ids:
            await db.execute(
                """
                UPDATE unanswered_tracking
                SET last_alert_utc=?,
                    alert_sent_for_inbound_utc=COALESCE(NULLIF(last_inbound_utc,''), ?),
                    updated_at=?
                WHERE chat_id=? AND COALESCE(waiting,0)=1
                """,
                (now, now, now, int(cid)),
            )
        await db.commit()




async def _ensure_panel_notifications_table() -> None:
    parent = os.path.dirname(TPILOT_DB_PATH)
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute("""
            CREATE TABLE IF NOT EXISTS panel_notifications(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                kind TEXT NOT NULL DEFAULT '',
                title TEXT NOT NULL DEFAULT '',
                body TEXT NOT NULL DEFAULT '',
                status TEXT NOT NULL DEFAULT 'new',
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        await db.execute("CREATE INDEX IF NOT EXISTS panel_notifications_status_idx ON panel_notifications(status, id)")
        await db.commit()



async def _create_panel_notification(kind: str, title: str, body: str) -> None:
    try:
        await _ensure_panel_notifications_table()
        now = _now_utc_iso()
        kind_s = str(kind or '')
        title_s = str(title or '')
        body_s = str(body or '')
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            try:
                cur = await db.execute(
                    "SELECT 1 FROM panel_notifications WHERE kind=? AND body=? AND status IN ('new','running') LIMIT 1",
                    (kind_s, body_s),
                )
                if await cur.fetchone():
                    return
            except Exception:
                pass
            await db.execute(
                "INSERT INTO panel_notifications(kind, title, body, status, created_at, updated_at) VALUES(?,?,?,?,?,?)",
                (kind_s, title_s, body_s, 'new', now, now),
            )
            await db.commit()
    except Exception as e:
        print(f"panel notification create error: {e!r}")




