async def _handle_unanswered_notify_command(args: str = "") -> str:
    raw = str(args or "").strip().lower()
    action = raw.split()[0] if raw else "status"

    if action in ("on", "enable", "enabled", "вкл", "включить"):
        await set_setting(UNANSWERED_PANEL_NOTIFY_SETTING, "1")
        return "\n".join([
            "🔔 Уведомления по неотвеченным включены",
            "",
            "PanelBot снова будет получать автоматические уведомления через 15 минут.",
            "Команда /unanswered all и карточки по менеджерам работают всегда.",
        ]).rstrip()

    if action in ("off", "disable", "disabled", "выкл", "выключить"):
        await set_setting(UNANSWERED_PANEL_NOTIFY_SETTING, "0")
        await _clear_pending_unanswered_panel_notifications()
        return "\n".join([
            "🔕 Уведомления по неотвеченным выключены",
            "",
            "PanelBot больше не будет получать автоматические уведомления.",
            "Проверка вручную остаётся доступной:",
            "/unanswered all",
            "/unanswered <manager_key>",
        ]).rstrip()

    enabled = await _unanswered_panel_notifications_enabled()
    return "\n".join([
        "🔔 Неотвеченные уведомления",
        "",
        "Статус: " + ("включены" if enabled else "выключены"),
        "",
        "/unanswered_notify on - включить автоуведомления в PanelBot",
        "/unanswered_notify off - выключить автоуведомления в PanelBot",
        "/unanswered all - показать всех вручную",
        "/unanswered <manager_key> - показать по менед��еру",
    ]).rstrip()
