async def _tpilot_unanswered_loop() -> None:
    if not CONTROLLER_MODE:
        return
    while True:
        try:
            if not WORK_STATUS_CHAT_ID:
                await asyncio.sleep(60)
                continue
            rows = await _manager_rows_for_reporting()
            blocks = []
            mark_map: Dict[str, List[int]] = {}
            now = _tp_dt_utc_now()
            for mgr in rows:
                dbp = str(mgr.get("db_path") or "")
                items_all = await _fetch_unanswered_for_db(dbp, due_only=True, limit=100)
                due_items = []
                for it in items_all:
                    last_alert = _tp_parse_utc(str(it.get("last_alert_utc") or ""))
                    if last_alert and (now - last_alert) < timedelta(minutes=UNANSWERED_REPEAT_MINUTES):
                        continue
                    due_items.append(it)
                if not due_items:
                    continue
                blocks.append((_manager_label_from_row(mgr), due_items[:30]))
                mark_map[dbp] = [int(x.get("chat_id") or 0) for x in due_items]
            if blocks:
                lines = ["🔔 Неотвеченные клиенты", ""]
                for label, items in blocks:
                    lines.append(label)
                    lines.append(f"Всего: {len(items)}")
                    lines.append("")
                    for idx, it in enumerate(items, 1):
                        lines.append(f"{idx}) {_unanswered_line(it)}")
                    lines.append("")
                alert_text = chr(10).join(lines).rstrip()
                await client.send_message(int(WORK_STATUS_CHAT_ID), alert_text)
                if await _unanswered_panel_notifications_enabled():
                    await _create_panel_notification("unanswered", "🔔 Неотвеченные клиенты", alert_text)
                for dbp, ids in mark_map.items():
                    await _set_unanswered_alerted(dbp, ids)
            await asyncio.sleep(60)
        except asyncio.CancelledError:
            return
        except Exception as e:
            print(f"unanswered_loop error: {e!r}")
            await asyncio.sleep(60)


async def _mark_manager_replied(db_path: str, chat_id: int) -> None:
    if callable(_TPILOT_ORIG_MARK_MANAGER_REPLIED):
        await _TPILOT_ORIG_MARK_MANAGER_REPLIED(db_path, chat_id)
    else:
        now = _now_utc_iso()
        await _set_auto_state_fields(db_path, chat_id, manager_replied=1, manager_replied_at=now)
    try:
        await _unanswered_manager_replied(db_path, chat_id, MANAGER_RUNTIME_KEY)
        await _mark_manager_working_day(MANAGER_RUNTIME_KEY)
        await _set_manager_work_status(MANAGER_RUNTIME_KEY, "online", user_id=0, source="manual_activity")
    except Exception:
        pass


async def _apply_profile_from_text(db_path: str, lead_row: Dict[str, Any], text: str) -> Dict[str, Any]:
    chat_id = int((lead_row or {}).get("chat_id") or 0)
    gate_auto = int((lead_row or {}).get("profile_question_sent") or 0) == 1
    gate_manual = await _capture_is_open(db_path, chat_id)
    if not (gate_auto or gate_manual):
        return dict(lead_row or {})
    parsed = parse_profile_reply(text or "")
    combined = _combine_profile(lead_row, parsed)
    if combined.get("age") is None or not str(combined.get("country") or "").strip():
        combined["status"] = "unknown"
        combined["nonliquid_reason"] = ""
        combined["profile_done"] = 0
    await _update_daily_lead_fields(db_path, lead_date=str(lead_row.get("lead_date") or _kyiv_now().date().isoformat()), manager_key=str(lead_row.get("manager_key") or MANAGER_RUNTIME_KEY), chat_id=chat_id, **combined)
    if gate_manual:
        await _decrement_capture(db_path, chat_id)
    if int(combined.get("profile_done") or 0) == 1:
        await _close_capture_if_done(db_path, chat_id)
    out = dict(lead_row or {})
    out.update(combined)
    return out


async def _maybe_auto_reply_to_lead(lead_row: Dict[str, Any], state: Dict[str, Any], work: Dict[str, Any]) -> None:
    auto_on = await _get_profile_auto_enabled(str(lead_row.get("manager_key") or MANAGER_RUNTIME_KEY))
    chat_id = int(lead_row.get("chat_id") or 0)
    status = str((work or {}).get("status") or "online").strip().lower()
    try:
        await _update_daily_lead_fields(DB_PATH, lead_date=str(lead_row.get("lead_date") or _kyiv_now().date().isoformat()), manager_key=str(lead_row.get("manager_key") or MANAGER_RUNTIME_KEY), chat_id=chat_id, manager_work_status=status)
    except Exception:
        pass
    if not auto_on:
        return
    if callable(_TPILOT_ORIG_MAYBE_AUTO_REPLY_TO_LEAD):
        await _TPILOT_ORIG_MAYBE_AUTO_REPLY_TO_LEAD(lead_row, state, work)


async def _record_incoming_from_manager(event: events.NewMessage.Event) -> None:
    if CONTROLLER_MODE or not MANAGER_RUNTIME_KEY or not event.is_private:
        return
    chat_id = int(event.chat_id or 0)
    if chat_id <= 0:
        return
    text = str(getattr(event, "raw_text", None) or "").strip()

    if event.out:
        msg_id = int(getattr(event.message, "id", 0) or 0)
        if not _is_program_sent(chat_id, msg_id):
            if text and _profile_request_words(text):
                await _open_profile_capture(DB_PATH, chat_id, MANAGER_RUNTIME_KEY, "manual_question")
            await _mark_manager_replied(DB_PATH, chat_id)
            try:
                await _post_followup_note_manager_out(DB_PATH, chat_id, MANAGER_RUNTIME_KEY)
            except Exception:
                pass
        return

    try:
        sender = await event.get_sender()
    except Exception:
        sender = None
    username = str(getattr(sender, "username", None) or "").strip()
    first_name = str(getattr(sender, "first_name", None) or "").strip()
    last_name = str(getattr(sender, "last_name", None) or "").strip()
    full_name = _full_name(first_name, last_name)
    phone = _phone_clean(str(getattr(sender, "phone", None) or ""))
    try:
        contact = getattr(event.message, "contact", None)
        if contact and getattr(contact, "phone_number", None):
            phone = _phone_clean(str(getattr(contact, "phone_number") or "")) or phone
    except Exception:
        pass

    _created, lead_row = await _TPILOT_ORIG_RECORD_DAILY_LEAD_EVENT(db_path=DB_PATH, manager_key=MANAGER_RUNTIME_KEY, manager_username=SELF_USERNAME, chat_id=chat_id, username=username, full_name=full_name, phone=phone, first_seen_utc=_event_utc_iso(event))
    try:
        if not str((lead_row or {}).get("status") or "").strip() and await _autostatus_runtime_enabled():
            await _update_daily_lead_fields(DB_PATH, lead_date=str(lead_row.get("lead_date") or _kyiv_now().date().isoformat()), manager_key=str(lead_row.get("manager_key") or MANAGER_RUNTIME_KEY), chat_id=chat_id, status="unknown", profile_done=0)
            lead_row = dict(lead_row or {})
            lead_row["status"] = "unknown"
    except Exception:
        pass

    await _unanswered_inbound(DB_PATH, chat_id=chat_id, manager_key=MANAGER_RUNTIME_KEY, username=username, full_name=full_name)
    try:
        await _post_followup_note_client_in(DB_PATH, chat_id, MANAGER_RUNTIME_KEY, username=username, full_name=full_name)
    except Exception:
        pass

    if text and globals().get("_looks_like_trash_message") and _looks_like_trash_message(text):
        await _unanswered_mark_trash(DB_PATH, chat_id, "trash_text")
        return

    if text:
        lead_row = await _apply_profile_from_text(DB_PATH, lead_row, text)
    lead_row = dict(lead_row or {})
    lead_row["_last_incoming_text"] = text

    state = await _get_auto_state(DB_PATH, chat_id)
    work = await _get_manager_work_status(MANAGER_RUNTIME_KEY)
    await _maybe_auto_reply_to_lead(lead_row, state, work)


async def _format_profile_auto_status(target: str = "all") -> str:
    rows = await manager_list_rows(include_removed=False)
    target = registry_normalize_manager_key(target or "all")
    lines = ["⚙️ Режим анкеты", ""]
    any_row = False
    for r in rows or []:
        key = registry_normalize_manager_key(r.get("manager_key") or "")
        if not key or (target != "all" and key != target):
            continue
        any_row = True
        enabled = await _get_profile_auto_enabled(key)
        label = _manager_label_from_row(r)
        lines.append(f"{'🟢 Автоанкета' if enabled else '🔴 Ручной режим'} - {label}")
    if not any_row:
        lines.append("Менеджеры не найдены.")
    return chr(10).join(lines).rstrip()


async def _handle_profile_auto_command(args: str, *, user_id: int = 0) -> str:
    parts = str(args or "").split()
    if not parts or parts[0].lower() not in ("auto", "анкета"):
        return "Формат: /profile auto status|on|off <manager|all>"
    action = (parts[1].lower() if len(parts) > 1 else "status")
    target = registry_normalize_manager_key(parts[2] if len(parts) > 2 else "all") or "all"
    rows = await manager_list_rows(include_removed=False)
    keys = [registry_normalize_manager_key(r.get("manager_key") or "") for r in rows if registry_normalize_manager_key(r.get("manager_key") or "")]
    if target != "all" and target not in keys:
        return f"Менеджер не найден: {target}"
    if action in ("status", "st", "state"):
        return await _format_profile_auto_status(target)
    if action not in ("on", "off"):
        return "Формат: /profile auto status|on|off <manager|all>"
    enabled = action == "on"
    for k in keys:
        if target == "all" or k == target:
            await _set_profile_auto_enabled(k, enabled, user_id=user_id)
    return await _format_profile_auto_status(target)


def _parse_target_date_args(raw_args: str, *, default_target: str = "all"):
    parts = [p for p in str(raw_args or "").split() if p.strip()]
    target = default_target
    date_val = None
    for p in parts:
        d = _tp_parse_date_token(p)
        if d:
            date_val = d
        elif p.lower() not in ("all", "det") or target == default_target:
            target = registry_normalize_manager_key(p) or target
    return target or default_target, date_val


def _window_for_kind_date(kind: str, date_val):
    if date_val is None:
        start_iso, end_iso, label, title = _det_window(kind)
        return _utc_iso_to_kyiv_dt(start_iso), _utc_iso_to_kyiv_dt(end_iso), label, title
    kind = str(kind or "day").lower()
    day0 = datetime.combine(date_val, datetime.min.time()).replace(tzinfo=TZ_KYIV)
    if kind == "flight":
        start_local = day0.replace(hour=17, minute=0, second=0, microsecond=0)
        end_local = start_local + timedelta(hours=15)
        return start_local, end_local, _tp_date_display(date_val), "🌙 Долёты"
    start_local = day0.replace(hour=8, minute=0, second=0, microsecond=0)
    end_local = day0.replace(hour=17, minute=0, second=0, microsecond=0)
    return start_local, end_local, _tp_date_display(date_val), "📊 Статистика"


async def _lead_belongs_to_window(lead: Dict[str, Any], *, manager_key: str, kind: str, target_date, start_local: datetime, end_local: datetime) -> bool:
    dt = _lead_first_seen_local_dt(lead) if "_lead_first_seen_local_dt" in globals() else _utc_iso_to_kyiv_dt(str(lead.get("first_seen_utc") or ""))
    if not dt:
        return False
    kind = str(kind or "day").lower()
    if kind == "day":
        return start_local <= dt < end_local
    if start_local <= dt < end_local:
        return True
    if dt <= end_local or dt.date() <= target_date:
        return False
    if (dt.date() - target_date).days > HISTORY_DAYS_LIMIT:
        return False
    if await _manager_day_is_working(manager_key, dt.date().isoformat()):
        return False
    return True


async def _collect_window_leads_extended(start_local: datetime, end_local: datetime, target_key: str, kind: str, target_date) -> List[Dict[str, Any]]:
    # DELETED MANAGER STATS RETENTION 20260711 (period-filter correction): target_date
    # is this window's own semantic calendar date -- use it as both period bounds so
    # a tombstoned manager surfaces only for the exact date this window represents.
    _period_date = target_date.isoformat() if hasattr(target_date, "isoformat") else str(target_date or "")
    rows = await _manager_rows_for_reporting_period(_period_date, _period_date)
    target_key = registry_normalize_manager_key(target_key or "all")
    result: List[Dict[str, Any]] = []
    scan_end = end_local
    if str(kind).lower() == "flight":
        scan_end = max(scan_end, start_local + timedelta(days=min(HISTORY_DAYS_LIMIT, 7)))
    start_iso = _tp_local_to_utc_iso(start_local - timedelta(days=1))
    end_iso = _tp_local_to_utc_iso(scan_end + timedelta(days=1))
    for mgr in rows:
        key = registry_normalize_manager_key(mgr.get("manager_key") or "")
        if target_key != "all" and key != target_key:
            continue
        db_path = str(mgr.get("db_path") or "")
        trash_map = await _profile_reminder_trash_map(db_path) if "_profile_reminder_trash_map" in globals() else {}
        try:
            candidates = await _list_daily_leads_for_db_range(db_path, start_iso, end_iso)
        except Exception:
            candidates = []
        for lead in candidates:
            if await _lead_belongs_to_window(lead, manager_key=key, kind=kind, target_date=target_date, start_local=start_local, end_local=end_local):
                item = dict(lead)
                item["manager_key"] = key or item.get("manager_key") or ""
                item["manager_display_name"] = str(mgr.get("display_name") or key)
                item["manager_username"] = str(mgr.get("telegram_username") or item.get("manager_username") or "")
                tr = trash_map.get(int(item.get("chat_id") or 0)) or {}
                item["trash"] = int(tr.get("trash") or 0)
                item["trash_reason"] = str(tr.get("trash_reason") or "")
                result.append(item)
    result.sort(key=lambda x: (str(x.get("first_seen_utc") or ""), str(x.get("first_seen_kyiv") or ""), str(x.get("manager_key") or ""), int(x.get("id") or 0)))
    return result


async def _build_det_stat_text(target_key: str = "all", kind: str = "day", ref: Optional[Any] = None) -> str:
    date_val = None
    if isinstance(ref, str):
        date_val = _tp_parse_date_token(ref)
    elif hasattr(ref, "date"):
        try:
            date_val = ref.astimezone(TZ_KYIV).date() if getattr(ref, "tzinfo", None) else ref.date()
        except Exception:
            date_val = None
    if date_val and not _tp_date_within_history(date_val):
        return f"Дата вне доступного периода. Можно смотреть последние {HISTORY_DAYS_LIMIT} дней."
    start_local, end_local, label, title = _window_for_kind_date(kind, date_val)
    target_date = start_local.date()
    target = registry_normalize_manager_key(target_key or "all")
    # DELETED MANAGER STATS RETENTION 20260711 (period-filter correction): same
    # single-date period as _collect_window_leads_extended below, so a target-key
    # lookup ("Менеджер не найден") and the actual leads collection agree on
    # whether a tombstoned manager is valid for this specific report date.
    rows = await _manager_rows_for_reporting_period(target_date.isoformat(), target_date.isoformat())
    valid_keys = {registry_normalize_manager_key(r.get("manager_key") or "") for r in rows}
    if target != "all" and target not in valid_keys:
        return f"Менеджер не найден: {target}"
    leads = await _collect_window_leads_extended(start_local, end_local, target, kind, target_date)
    mgr_labels = {registry_normalize_manager_key(r.get("manager_key") or ""): _manager_label_from_row(r) for r in rows}
    buckets: Dict[str, Dict[str, Any]] = {}
    for lead in leads:
        key = registry_normalize_manager_key(lead.get("manager_key") or "")
        if not key:
            continue
        if key not in buckets:
            buckets[key] = _empty_det_bucket(mgr_labels.get(key) or key)
        _det_bucket_add(buckets[key], lead)
    window_line = "Окно: 17:00-08:00" if str(kind).lower() == "flight" else "Окно: 08:00-17:00"
    lines: List[str] = [f"{title} за {label}", window_line, ""]
    keys_order = [registry_normalize_manager_key(r.get("manager_key") or "") for r in rows]
    if target != "all":
        keys_order = [target]
    total_bucket = _empty_det_bucket("ИТОГО")
    any_block = False
    for key in keys_order:
        if not key:
            continue
        b = buckets.get(key) or _empty_det_bucket(mgr_labels.get(key) or key)
        if target == "all" and int(b.get("otpisok") or 0) == 0:
            continue
        any_block = True
        lines.append(str(b.get("label") or key))
        lines.extend(_format_det_bucket(b))
        lines.append("")
        for k in ("otpisok", "geo", "under18", "na", "trash", "liquid", "nonliquid"):
            total_bucket[k] += int(b.get(k) or 0)
    if target == "all":
        if any_block:
            lines.append("ИТОГО")
            lines.extend(_format_det_bucket(total_bucket))
        else:
            lines.append("Лидов за это окно пока нет.")
    elif not any_block:
        lines.append(str(mgr_labels.get(target) or target))
        lines.extend(_format_det_bucket(_empty_det_bucket(mgr_labels.get(target) or target)))
    return chr(10).join(lines).rstrip()



# -------------------- guarded manager admin helpers --------------------
SYSTEM_MANAGER_KEYS = {"tpilot", "panelbot", "panel_bot", "watchdog", "soft_watchdog", "partnerbot", "partner_stat_bot", "lead_stat_bot"}


def _manager_danger_allowed_key(key: str) -> Tuple[bool, str]:
    k = registry_normalize_manager_key(key or "")
    if not k:
        return False, "Пустой ключ менеджера."
    if k in SYSTEM_MANAGER_KEYS:
        return False, f"Нельзя выполнять опасные действия для системного процесса: {k}"
    if not re.fullmatch(r"[a-z0-9_-]+", k):
        return False, "Некорректный ключ менеджера."
    return True, ""


def _manager_admin_password_ok(raw: str) -> bool:
    expected = str(MANAGER_ADMIN_PASSWORD or "").strip()
    if not expected:
        return False
    return str(raw or "").strip() == expected


def _danger_parse_args(args: str, usage: str) -> Tuple[str, str, bool, str]:
    parts = str(args or "").strip().split()
    key = registry_normalize_manager_key(parts[0] if len(parts) >= 1 else "")
    # Password may itself contain spaces (e.g. MANAGER_ADMIN_PASSWORD with a space).
    # "confirm" is always the trailing token, so take it off the end first, then
    # treat everything between key and that trailing "confirm" as the password.
    if len(parts) >= 3 and parts[-1].lower() == "confirm":
        confirm = True
        password = " ".join(parts[1:-1])
    else:
        confirm = False
        password = " ".join(parts[1:]) if len(parts) >= 2 else ""
    if not key or not password or not confirm:
        return key, password, confirm, f"Формат: {usage}"
    ok_key, err = _manager_danger_allowed_key(key)
    if not ok_key:
        return key, password, confirm, err
    if not _manager_admin_password_ok(password):
        return key, password, confirm, "⛔ Неверный пароль. Действие не выполнено."
    return key, password, confirm, ""


async def _ensure_manager_admin_log_table() -> None:
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute("""
            CREATE TABLE IF NOT EXISTS manager_admin_danger_log(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                action TEXT NOT NULL DEFAULT '',
                manager_key TEXT NOT NULL DEFAULT '',
                requested_by INTEGER DEFAULT 0,
                backup_path TEXT DEFAULT '',
                result TEXT NOT NULL DEFAULT '',
                error_text TEXT DEFAULT '',
                created_at TEXT NOT NULL DEFAULT ''
            );
        """)
        await db.execute("CREATE INDEX IF NOT EXISTS manager_admin_danger_log_idx ON manager_admin_danger_log(created_at, manager_key, action)")
        await db.commit()


async def _log_manager_danger_action(action: str, manager_key: str, requested_by: int, *, backup_path: str = "", result: str = "", error_text: str = "") -> None:
    try:
        await _ensure_manager_admin_log_table()
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute(
                "INSERT INTO manager_admin_danger_log(action, manager_key, requested_by, backup_path, result, error_text, created_at) VALUES(?,?,?,?,?,?,?)",
                (str(action or ""), registry_normalize_manager_key(manager_key or ""), int(requested_by or 0), str(backup_path or ""), str(result or ""), str(error_text or ""), _now_utc_iso()),
            )
            await db.commit()
    except Exception as e:
        print(f"danger log error: {e!r}")


def _manager_db_files(key: str) -> List[Path]:
    paths = build_manager_paths(str(BASE_DIR), registry_normalize_manager_key(key or ""))
    db_path = Path(paths.get("db_path") or "")
    return [db_path, Path(str(db_path) + "-wal"), Path(str(db_path) + "-shm")]


def _copy_existing_files(files: List[Path], dest: Path) -> int:
    dest.mkdir(parents=True, exist_ok=True)
    copied = 0
    for fp in files:
        try:
            if fp.exists():
                shutil.copy2(str(fp), str(dest / fp.name))
                copied += 1
        except Exception as e:
            raise RuntimeError(f"Не удалось скопировать {fp}: {e!r}")
    return copied


async def _backup_manager_db_files(key: str, action: str) -> str:
    k = registry_normalize_manager_key(key or "")
    ts = _kyiv_now().strftime("%Y%m%d_%H%M%S")
    dest = BASE_DIR / "_manager_db_backups" / k / f"{ts}_{action}"
    copied = _copy_existing_files(_manager_db_files(k), dest)
    marker = dest / "BACKUP_INFO.txt"
    marker.write_text(f"manager_key={k}\naction={action}\ncreated_at={_now_utc_iso()}\nfiles_copied={copied}\n", encoding="utf-8")
    return str(dest)


def _latest_manager_db_backup(key: str) -> Optional[Path]:
    root = BASE_DIR / "_manager_db_backups" / registry_normalize_manager_key(key or "")
    if not root.exists():
        return None
    dirs = [p for p in root.iterdir() if p.is_dir()]
    if not dirs:
        return None
    dirs.sort(key=lambda p: p.name, reverse=True)
    return dirs[0]


async def _backup_manager_session_files(key: str, action: str) -> str:
    k = registry_normalize_manager_key(key or "")
    ts = _kyiv_now().strftime("%Y%m%d_%H%M%S")
    paths = build_manager_paths(str(BASE_DIR), k)
    session = Path(paths.get("session_path") or "")
    files = [session, Path(str(session) + "-journal")]
    dest = BASE_DIR / "_manager_session_backups" / k / f"{ts}_{action}"
    copied = _copy_existing_files(files, dest)
    (dest / "BACKUP_INFO.txt").write_text(f"manager_key={k}\naction={action}\ncreated_at={_now_utc_iso()}\nfiles_copied={copied}\n", encoding="utf-8")
    return str(dest)


async def _panel_manager_db_clear_command(args: str, *, requested_by: int = 0) -> str:
    key, password, confirm, err = _danger_parse_args(args, "/manager_db_clear <manager_key> <password> confirm")
    if err:
        return err
    row = await manager_get(key)
    if not row or str(row.get("status") or "") == "archived":
        return _panel_manager_missing_text(key)
    was_running = await _manager_process_running(key)
    should_restart = bool(was_running and int(row.get("is_enabled") or 0) == 1 and str(row.get("status") or "") == "active")
    await _stop_manager_process(key, silent=True)
    try:
        backup_path = await _backup_manager_db_files(key, "clear_db")
        # Если backup-папка не создана, не продолжаем.
        if not backup_path or not Path(backup_path).exists():
            raise RuntimeError("backup не создан")
        removed = []
        for fp in _manager_db_files(key):
            try:
                if fp.exists():
                    fp.unlink()
                    removed.append(fp.name)
            except Exception as e:
                raise RuntimeError(f"Не удалось удалить {fp}: {e!r}")
        if should_restart:
            await manager_set_fields(key, manual_stopped=0, is_enabled=1, status="active", last_error="")
            ok, msg = await _spawn_manager_process(key)
            restart_text = "Менеджер перезапущен." if ok else f"Перезапуск не удался: {msg}"
        else:
            await manager_set_fields(key, manual_stopped=1)
            restart_text = "Менеджер был остановлен до очистки, поэтому оставлен stopped."
        await _log_manager_danger_action("clear_db", key, requested_by, backup_path=backup_path, result="ok")
        return "\n".join([
            "✅ База менеджера очищена",
            "",
            f"Менеджер: {key}",
            f"Backup: {backup_path}",
            f"Удалено: {', '.join(removed) if removed else 'файлов базы не было'}",
            restart_text,
            "",
            "Session не трогали. data_tpilot.db не трогали.",
        ]).rstrip()
    except Exception as e:
        await _log_manager_danger_action("clear_db", key, requested_by, result="error", error_text=repr(e))
        return f"⚠️ Очистка базы не выполнена: {e!r}"


async def _panel_manager_db_restore_command(args: str, *, requested_by: int = 0) -> str:
    key, password, confirm, err = _danger_parse_args(args, "/manager_db_restore <manager_key> <password> confirm")
    if err:
        return err
    row = await manager_get(key)
    if not row or str(row.get("status") or "") == "archived":
        return _panel_manager_missing_text(key)
    latest = _latest_manager_db_backup(key)
    if not latest:
        return f"Backup базы для {key} не найден."
    was_running = await _manager_process_running(key)
    await _stop_manager_process(key, silent=True)
    try:
        current_backup = await _backup_manager_db_files(key, "before_restore")
        for fp in _manager_db_files(key):
            try:
                if fp.exists():
                    fp.unlink()
            except Exception:
                pass
        restored = []
        for src in latest.iterdir():
            if src.name == "BACKUP_INFO.txt":
                continue
            dest = Path(build_manager_paths(str(BASE_DIR), key)["db_path"]).parent / src.name
            shutil.copy2(str(src), str(dest))
            restored.append(src.name)
        restart_text = ""
        if was_running:
            ok, msg = await _spawn_manager_process(key)
            restart_text = "Менеджер перезапущен." if ok else f"Перезапуск не удался: {msg}"
        await _log_manager_danger_action("restore_db", key, requested_by, backup_path=str(latest), result="ok")
        return "\n".join([
            "✅ Backup базы восстановлен",
            "",
            f"Менеджер: {key}",
            f"Восстановлен backup: {latest}",
            f"Backup текущего состояния перед восстановлением: {current_backup}",
            f"Файлы: {', '.join(restored) if restored else '_'}",
            restart_text,
        ]).rstrip()
    except Exception as e:
        await _log_manager_danger_action("restore_db", key, requested_by, backup_path=str(latest), result="error", error_text=repr(e))
        return f"⚠️ Восстановление не выполнено: {e!r}"


async def _panel_manager_danger_log_command(args: str = "", *, requested_by: int = 0) -> str:
    await _ensure_manager_admin_log_table()
    limit = 20
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM manager_admin_danger_log ORDER BY id DESC LIMIT ?", (limit,))
        rows = [dict(r) for r in await cur.fetchall()]
    if not rows:
        return "🧾 Журнал опасных действий пока пуст."
    lines = ["🧾 Журнал опасных действий", ""]
    for r in rows:
        lines.append(f"#{r.get('id')} | {r.get('created_at')}")
        lines.append(f"Действие: {r.get('action')} | Менеджер: {r.get('manager_key')} | user_id: {r.get('requested_by') or '_'}")
        if str(r.get('backup_path') or '').strip():
            lines.append(f"Backup: {r.get('backup_path')}")
        if str(r.get('result') or '').strip():
            lines.append(f"Результат: {r.get('result')}")
        if str(r.get('error_text') or '').strip():
            lines.append(f"Ошибка: {str(r.get('error_text'))[:500]}")
        lines.append("")
    return "\n".join(lines).rstrip()


# -------------------- PanelBot manager admin commands --------------------
def _panel_manager_missing_text(key: str) -> str:
    return f"Менеджер не найден: {registry_normalize_manager_key(key or '')}"


async def _panel_manager_list_command(args: str = "", *, requested_by: int = 0) -> str:
    rows = await manager_list_rows(include_removed=False)
    if not rows:
        return "👥 Менеджеров пока нет.\n\nНажмите ➕ Добавить менеджера, чтобы подключить первый аккаунт."
    lines = ["👥 Менеджеры", ""]
    for idx, row in enumerate(rows, 1):
        key = registry_normalize_manager_key(row.get("manager_key") or "")
        label = _manager_label_from_row(row)
        state = _manager_status_label(row)
        proxy = "proxy on" if int(row.get("proxy_enabled") or 0) == 1 else "proxy off"
        lines.append(f"{idx}) {label}")
        lines.append(f"   Ключ: {key}")
        lines.append(f"   Состояние: {state}")
        lines.append(f"   Proxy: {proxy}")
        lines.append("")
    return chr(10).join(lines).rstrip()


async def _panel_manager_info_command(args: str, *, requested_by: int = 0) -> str:
    key = registry_normalize_manager_key(str(args or "").strip())
    if not key:
        return "Формат: /manager_info <manager_key>"
    row = await manager_get(key)
    if not row or str(row.get("status") or "") == "archived":
        return _panel_manager_missing_text(key)
    lines = [
        f"👤 Карточка менеджера: {_manager_label_from_row(row)}",
        "",
        f"Ключ: {row.get('manager_key') or '_'}",
        f"Статус: {_manager_status_label(row)}",
        f"Телефон: {mask_phone(str(row.get('phone') or ''))}",
        f"Telegram ID: {row.get('tg_user_id') or '_'}",
        f"Username: @{row.get('telegram_username')}" if str(row.get('telegram_username') or '').strip() else "Username: _",
        f"Имя: {_full_name(str(row.get('first_name') or ''), str(row.get('last_name') or '')) or '_'}",
        f"DB: {row.get('db_path') or '_'}",
        f"Session: {row.get('session_path') or '_'}",
        f"Log: {row.get('log_path') or '_'}",
        f"Proxy: {'включён' if int(row.get('proxy_enabled') or 0) == 1 else 'выключен'} {str(row.get('proxy_type') or '').upper() or '_'} {row.get('proxy_host') or '_'}:{row.get('proxy_port') or '_'}",
    ]
    last_error = str(row.get('last_error') or '').strip()
    if last_error:
        lines.extend(["", "Последняя ошибка:", last_error[:800]])
    return chr(10).join(lines).rstrip()


async def _panel_manager_lifecycle_command(action: str, args: str, *, requested_by: int = 0) -> str:
    action = str(action or "").strip().lower()
    key = registry_normalize_manager_key(str(args or "").strip())
    if not key:
        return f"Формат: /manager_{action} <manager_key>"
    row = await manager_get(key)
    if not row or str(row.get("status") or "") == "archived":
        return _panel_manager_missing_text(key)

    if action == "start":
        await manager_set_fields(key, is_enabled=1, status="active", manual_stopped=0, last_error="")
        ok, msg = await _spawn_manager_process(key)
        if ok:
            return f"✅ Менеджер запущен: {key}"
        await manager_set_fields(key, last_error=msg)
        return f"⚠️ Не удалось запустить {key}\n{msg}"

    if action == "stop":
        ok, msg = await _stop_manager_process(key)
        await manager_set_fields(key, manual_stopped=1)
        return f"✅ Менеджер остановлен: {key}" if ok else f"⚠️ {msg}"

    if action == "enable":
        await manager_set_fields(key, is_enabled=1, status="active", manual_stopped=0, last_error="")
        return f"✅ Менеджер включён в реестре: {key}\nЧтобы процесс точно был запущен, нажмите ▶️ Запустить."

    if action in ("disable", "pause"):
        await _stop_manager_process(key, silent=True)
        await manager_set_fields(key, is_enabled=0, status="disabled", manual_stopped=1)
        return f"⏸ Менеджер приостановлен: {key}\nОн не будет запускаться в общем старте, пока вы снова его не включите."

    if action == "remove":
        await _stop_manager_process(key, silent=True)
        await manager_soft_remove(key)
        return f"🗃 Менеджер архивирован: {key}\nЭто мягкое удаление из активного списка. Для окончательного удаления используйте отдельную опасную кнопку с подтверждением."

    return "Команда управления менеджером не распознана."


async def _panel_manager_rename_command(args: str, *, requested_by: int = 0) -> str:
    parts = str(args or "").strip().split(maxsplit=1)
    key = registry_normalize_manager_key(parts[0] if parts else "")
    display_name = (parts[1] if len(parts) > 1 else "").strip()
    if not key or not display_name:
        return "Формат: /manager_rename <manager_key> <новое_имя>"
    row = await manager_get(key)
    if not row or str(row.get("status") or "") == "archived":
        return _panel_manager_missing_text(key)
    await manager_rename(key, display_name)
    return f"✅ Имя менеджера обновлено\n{key} -> {display_name}"


async def _panel_manager_reset_command(args: str, *, requested_by: int = 0) -> str:
    key, password, confirm, err = _danger_parse_args(args, "/manager_reset <manager_key> <password> confirm")
    if err:
        return err
    row = await manager_get(key)
    if not row or str(row.get("status") or "") == "archived":
        return _panel_manager_missing_text(key)
    await _stop_manager_process(key, silent=True)
    try:
        backup_path = await _backup_manager_session_files(key, "reset_auth")
        await manager_delete_onboarding_by_key(key)
    except Exception:
        backup_path = ""
    paths = ensure_manager_dirs(str(BASE_DIR), key)
    for fp in (paths.get("session_path"), paths.get("session_path", "") + "-journal"):
        try:
            if fp and os.path.exists(fp):
                os.remove(fp)
        except Exception:
            pass
    owner = int(row.get("owner_user_id") or requested_by or 0) or None
    await manager_set_fields(
        key,
        status="new",
        is_enabled=1,
        manual_stopped=0,
        owner_user_id=owner,
        phone="",
        session_path=paths["session_path"],
        db_path=paths["db_path"],
        workdir=paths["root"],
        log_path=paths["log_path"],
        tg_user_id=None,
        telegram_username="",
        first_name="",
        last_name="",
        last_login_at="",
        last_error="",
    )
    expires_at = _future_iso(MANAGER_ONBOARD_TIMEOUT_SEC)
    await manager_save_onboarding(
        int(requested_by or 0),
        manager_key=key,
        step="await_phone",
        phone="",
        phone_code_hash="",
        tmp_session_path=paths["session_path"],
        expires_at=expires_at,
        next_code_allowed_at="",
        last_code_sent_at="",
        last_send_error="",
    )
    _manager_runtime_onboarding_set(
        int(requested_by or 0),
        manager_key=key,
        step="await_phone",
        phone="",
        phone_code_hash="",
        tmp_session_path=paths["session_path"],
        expires_at=expires_at,
        next_code_allowed_at="",
        last_code_sent_at="",
        last_send_error="",
    )
    await _log_manager_danger_action("reset_auth", key, requested_by, backup_path=backup_path, result="ok")
    return "\n".join([
        f"🔄 Авторизация сброшена: {key}",
        f"Backup session: {backup_path or '_'}",
        "Старая Telegram session удалена.",
        "База лидов менеджера не тронута.",
        "Теперь введите новый номер телефона менеджера одним сообщением.",
        "Пример +79991234567",
    ])


async def _panel_manager_delete_full_command(args: str, *, requested_by: int = 0) -> str:
    key, password, confirm, err = _danger_parse_args(args, "/manager_delete_full <manager_key> <password> confirm")
    if err:
        return err
    return await _manager_delete_full_core(key, requested_by=requested_by)


async def _manager_delete_full_core(key: str, *, requested_by: int = 0) -> str:
    """The actual full-delete implementation (runtime-folder move + tombstone
    + registry-row/scratch-table cleanup + reserve release), extracted out of
    _panel_manager_delete_full_command so a non-interactive caller (Stage 4's
    replacement commit/cutover engine) can reuse the EXACT same logic without
    needing an admin's plaintext danger-password -- that password check is a
    UI/authorization concern of the interactive command below, not part of
    the deletion logic itself. key is assumed already validated/normalized by
    the caller (mirrors _danger_parse_args' own key normalization)."""
    row = await manager_get(key)
    if not row:
        return _panel_manager_missing_text(key)

    await _stop_manager_process(key, silent=True)
    try:
        await manager_delete_onboarding_by_key(key)
    except Exception:
        pass

    backup_root = BASE_DIR / "_deleted_managers_backup"
    backup_root.mkdir(parents=True, exist_ok=True)
    ts = _kyiv_now().strftime("%Y%m%d_%H%M%S")
    moved_to = ""
    paths = build_manager_paths(str(BASE_DIR), key)
    root = Path(paths.get("root") or "")
    dest = backup_root / f"{key}_{ts}"
    # DELETED MANAGER STATS RETENTION 20260711: deterministic future backup DB path,
    # computed regardless of whether the move below actually runs/succeeds (matches
    # build_manager_paths' own db_path naming: <root>/<key>.db). Readers that later
    # resolve this path (stats_engine.se_manager_db_path / _psf3_manager_db_path /
    # _manager_rows_for_reporting) already guard on os.path.exists, so a path that
    # never materializes (e.g. the manager never had a runtime folder) is harmless.
    tombstone_db_path = str(dest / f"{key}.db")
    if root.exists():
        try:
            shutil.move(str(root), str(dest))
            moved_to = str(dest)
        except Exception as e:
            await _log_manager_danger_action("delete_full", key, requested_by, result="error", error_text=repr(e))
            return f"⚠️ Не удалось перенести runtime-папку менеджера {key}: {e!r}\nУдаление из реестра не выполнено."

    # DELETED MANAGER STATS RETENTION 20260711: snapshot identity + source_key + the
    # backup DB path into a tombstone BEFORE the hard-delete below, so AdminBot/
    # PartnerBot stats can still render this manager's historical data for 60 days
    # after deletion. Read source_key from manager_source_links BEFORE that row is
    # deleted a few lines down. Fail-before-delete: if the tombstone write itself
    # fails, abort WITHOUT performing the destructive DELETE -- a missing tombstone
    # with a live manager row is always safely re-triable, whereas a hard-deleted
    # manager with no tombstone would silently lose stats retention forever.
    tombstone_source_key = ""
    try:
        async with aiosqlite.connect(TPILOT_DB_PATH) as _src_db:
            _src_cur = await _src_db.execute(
                "SELECT source_key FROM manager_source_links WHERE manager_key=? LIMIT 1", (key,)
            )
            _src_row = await _src_cur.fetchone()
            tombstone_source_key = str(_src_row[0] or "") if _src_row else ""
    except Exception:
        tombstone_source_key = ""

    tombstone_ok = False
    tombstone_error = ""
    try:
        from storage import manager_stats_tombstone_upsert as _tombstone_upsert
        tombstone_ok = bool(_tombstone_upsert(
            key,
            display_name=str(row.get("display_name") or ""),
            telegram_username=str(row.get("telegram_username") or ""),
            manager_db_path=tombstone_db_path,
            source_key=tombstone_source_key,
            deleted_at=_now_utc_iso(),
            retention_days=60,
            db_path=TPILOT_DB_PATH,
        ))
    except Exception as e:
        tombstone_ok = False
        tombstone_error = repr(e)

    if not tombstone_ok:
        await _log_manager_danger_action(
            "delete_full", key, requested_by, backup_path=moved_to, result="error",
            error_text=f"tombstone upsert failed: {tombstone_error}",
        )
        return (
            f"⚠️ Не удалось сохранить снимок статистики менеджера {key}: {tombstone_error}\n"
            "Удаление из реестра не выполнено, чтобы удалённый менеджер не пропал из статистики. Повторите команду."
        )

    # PROXY LIFECYCLE SYNC 20260721: hard-delete is an auto-terminal event --
    # the admin explicitly deleted this manager, no separate confirm needed.
    # Detach its proxy lease BEFORE the row disappears (the managers row is
    # about to be deleted below, so proxy_lease_id would otherwise become
    # unreachable and the lease would stay orphaned -- pointing at a dead
    # manager_key forever, per the audited gap). Never deletes the lease row
    # itself (history/credentials retained); the NEXT sync reconcile
    # naturally recomputes desired=N for this proxy once no other healthy
    # manager uses it (or leaves it desired=Y if a shared proxy still has one).
    try:
        import storage as _plc_storage_early
        _plc_lease = await _plc_storage_early.proxy_lease_get_for_manager(key, db_path=TPILOT_DB_PATH)
        if _plc_lease:
            await _plc_storage_early.proxy_lease_unassign(int(_plc_lease["id"]), db_path=TPILOT_DB_PATH)
            await _plc_storage_early.proxy_lifecycle_event_add(
                int(_plc_lease["id"]), "manager_deleted", provider_proxy_id=_plc_lease.get("provider_proxy_id"),
                actor=f"admin:{requested_by}" if requested_by else "system",
                detail=f"manager_key={key}", db_path=TPILOT_DB_PATH,
            )
    except Exception:
        pass

    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        for sql, params in [
            ("DELETE FROM manager_onboarding WHERE manager_key=?", (key,)),
            ("DELETE FROM manager_commands WHERE target_key=?", (key,)),
            ("DELETE FROM access_targets WHERE manager_key=?", (key,)),
            ("DELETE FROM manager_work_status WHERE manager_key=?", (key,)),
            ("DELETE FROM manager_source_links WHERE manager_key=?", (key,)),
            ("DELETE FROM manager_group_members WHERE manager_key=?", (key,)),
            # TPILOT PREPARED ACCOUNTS PHASE 4: side-row only -- storage.
            # prepared_account_delete's own DELETE is narrowly scoped to
            # manager_key too; inlined here (not called as a function) only
            # to stay inside this loop's single try/except-per-statement
            # shape, same as every other row in this list.
            ("DELETE FROM prepared_accounts WHERE manager_key=?", (key,)),
            ("DELETE FROM managers WHERE manager_key=?", (key,)),
        ]:
            try:
                await db.execute(sql, params)
            except Exception:
                pass
        await db.commit()

    # RESERVE RELEASE 2026-07-11 (post-review atomicity fix): the prior implementation
    # released this manager's reserve pairs BEFORE the DELETE/commit block above. Final
    # review flagged that as blocking: every DELETE in the loop is wrapped in
    # try/except: pass, and aiosqlite.connect itself could fail, so the managers row
    # could survive while its reserve was already retired -- making the reserve visible
    # and reassignable to another primary while the original primary was still alive.
    # Corrected order: delete/commit first, then explicitly confirm absence via a fresh
    # read of the authoritative managers table (own sequential connection, opened only
    # after the block above has fully closed -- no nested/overlapping connections), and
    # release the reserve ONLY once that absence is positively confirmed. Any failure to
    # confirm (row still present OR the verify query itself errors) fails CLOSED: no
    # release, no false "success" reported.
    still_exists = True  # fail-closed default: only False once positively confirmed absent
    verify_error = ""
    try:
        async with aiosqlite.connect(TPILOT_DB_PATH) as verify_db:
            verify_cur = await verify_db.execute("SELECT 1 FROM managers WHERE manager_key=? LIMIT 1", (key,))
            still_exists = bool(await verify_cur.fetchone())
    except Exception as e:
        still_exists = True
        verify_error = repr(e)

    if still_exists:
        detail = f" ({verify_error})" if verify_error else ""
        await _log_manager_danger_action(
            "delete_full", key, requested_by, backup_path=moved_to, result="error",
            error_text=f"managers row still present after delete/commit{detail}",
        )
        return (
            f"⚠️ Удаление менеджера {key} не подтверждено: строка в реестре managers всё ещё существует{detail}.\n"
            "Резервные привязки НЕ освобождались, чтобы резерв не стал доступен, пока этот менеджер ещё жив. Повторите команду."
        )

    released_reserves = 0
    reserve_release_error = ""
    try:
        from storage import reserve_pair_release_for_primary as _rsv_release_for_primary
        released_reserves = int(_rsv_release_for_primary(key, db_path=TPILOT_DB_PATH) or 0)
    except Exception as e:
        reserve_release_error = repr(e)

    await _log_manager_danger_action("delete_full", key, requested_by, backup_path=moved_to, result="ok")
    lines = [
        f"🗑 Менеджер полностью удалён из программы: {key}",
        "Он удалён из manager registry и больше не будет отображаться в панели или запускаться.",
    ]
    if moved_to:
        lines.append(f"Файлы session/db/log перенесены в безопасный backup: {moved_to}")
    if released_reserves:
        lines.append(f"Освобождено резервных привязок: {released_reserves} (резерв снова доступен в пикере).")
    if reserve_release_error:
        lines.append(
            f"⚠️ Менеджер удалён, но не удалось очистить резервные метаданные: {reserve_release_error}\n"
            "Осиротевший резерв всё равно останется доступен в пикере (привязка ссылается на уже несуществующего менеджера)."
        )
    return chr(10).join(lines).rstrip()


# -------------------- test leads and baseline service commands --------------------
def _service_parse_chat_id(raw: str) -> Optional[int]:
    token = str(raw or "").strip()
    if not token:
        return None
    token = token.replace("@", "").strip()
    if re.fullmatch(r"-?\d+", token):
        try:
            return int(token)
        except Exception:
            return None
    return None


async def _safe_table_exists(db: aiosqlite.Connection, table: str) -> bool:
    try:
        cur = await db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=? LIMIT 1", (str(table),))
        return bool(await cur.fetchone())
    except Exception:
        return False


async def _resolve_chat_refs(ref: str, rows: Optional[List[Dict[str, Any]]] = None) -> List[int]:
    """Resolve numeric chat_id or best-effort @username from manager DBs."""
    chat_id = _service_parse_chat_id(ref)
    if chat_id is not None:
        return [int(chat_id)]
    username = str(ref or "").strip().lstrip("@").lower()
    if not username:
        return []
    rows = rows if rows is not None else await _manager_rows_for_reporting()
    found: set[int] = set()
    for mgr in rows or []:
        db_path = str(mgr.get("db_path") or "")
        if not db_path or not os.path.exists(db_path):
            continue
        try:
            async with aiosqlite.connect(db_path) as db:
                checks = [
                    ("daily_leads", "username"),
                    ("leads", "username"),
                    ("post_manual_followup_state", "username"),
                    ("unanswered_tracking", "username"),
                    ("baseline_old_chats", "username"),
                ]
                for table, col in checks:
                    if not await _safe_table_exists(db, table):
                        continue
                    try:
                        cur = await db.execute(
                            f"SELECT chat_id FROM {table} WHERE lower(replace(COALESCE({col},''),'@',''))=? LIMIT 20",
                            (username,),
                        )
                        for r in await cur.fetchall():
                            try:
                                found.add(int(r[0]))
                            except Exception:
                                pass
                    except Exception:
                        pass
        except Exception:
            continue
    return sorted(found)


async def _reset_test_lead_in_db(db_path: str, chat_id: int) -> Dict[str, int]:
    """Delete every service/profile/stat row for one chat_id inside one manager DB."""
    out: Dict[str, int] = {}
    if not db_path or not os.path.exists(str(db_path)) or int(chat_id or 0) <= 0:
        return out
    delete_tables = [
        "daily_leads",
        "lead_auto_state",
        "lead_profile_reminders",
        "lead_dialog_state",
        "post_manual_followup_state",
        "profile_capture_state",
        "unanswered_tracking",
        "baseline_old_chats",
        "leads",
        "messages",
        "followups",
    ]
    async with aiosqlite.connect(db_path) as db:
        for table in delete_tables:
            if not await _safe_table_exists(db, table):
                continue
            try:
                cur = await db.execute(f"DELETE FROM {table} WHERE chat_id=?", (int(chat_id),))
                try:
                    out[table] = int(cur.rowcount or 0)
                except Exception:
                    out[table] = 0
            except Exception:
                pass
        await db.commit()
    return out


async def _testlead_status_for_db(db_path: str, chat_id: int) -> Dict[str, int]:
    out: Dict[str, int] = {}
    if not db_path or not os.path.exists(str(db_path)) or int(chat_id or 0) <= 0:
        return out
    tables = [
        "daily_leads",
        "lead_auto_state",
        "lead_profile_reminders",
        "lead_dialog_state",
        "post_manual_followup_state",
        "profile_capture_state",
        "unanswered_tracking",
        "baseline_old_chats",
        "leads",
        "messages",
        "followups",
    ]
    async with aiosqlite.connect(db_path) as db:
        for table in tables:
            if not await _safe_table_exists(db, table):
                continue
            try:
                cur = await db.execute(f"SELECT COUNT(*) FROM {table} WHERE chat_id=?", (int(chat_id),))
                row = await cur.fetchone()
                cnt = int(row[0] or 0) if row else 0
                if cnt:
                    out[table] = cnt
            except Exception:
                pass
    return out


async def _handle_testlead_command(args: str, *, user_id: int = 0) -> str:
    parts = str(args or "").split()
    if not parts or parts[0].lower() in ("help", "?", "h"):
        return "\n".join([
            "🧪 Тестовые лиды",
            "",
            "Сбросить тестовый Telegram-аккаунт, чтобы он снова прошёл как новый лид:",
            "/testlead reset 123456789",
            "",
            "Проверить, где этот chat_id ещё есть в базах:",
            "/testlead status 123456789",
            "",
            "Лучше использовать ID, потому что username может измениться.",
        ]).rstrip()
    action = parts[0].lower()
    ref = parts[1] if len(parts) >= 2 else ""
    if action not in ("reset", "status") or not ref:
        return "Формат: /testlead reset 123456789 или /testlead status 123456789"
    rows = await _manager_rows_for_reporting()
    ids = await _resolve_chat_refs(ref, rows)
    if not ids:
        return f"Не нашёл chat_id по значению: {ref}"
    if len(ids) > 10:
        return "Найдено слишком много совпадений. Для безопасности используйте точный chat_id."

    if action == "status":
        lines = ["🧪 Статус тестового лида", ""]
        for chat_id in ids:
            lines.append(f"ID: {chat_id}")
            any_hit = False
            for mgr in rows:
                key = registry_normalize_manager_key(mgr.get("manager_key") or "")
                st = await _testlead_status_for_db(str(mgr.get("db_path") or ""), int(chat_id))
                if st:
                    any_hit = True
                    lines.append(f"{key}: " + ", ".join([f"{k}={v}" for k, v in sorted(st.items())]))
            if not any_hit:
                lines.append("Следов в базах менеджеров не найдено.")
            lines.append("")
        return chr(10).join(lines).rstrip()

    lines = ["♻️ Сброс тестового лида", ""]
    for chat_id in ids:
        lines.append(f"ID: {chat_id}")
        total_deleted = 0
        for mgr in rows:
            key = registry_normalize_manager_key(mgr.get("manager_key") or "")
            deleted = await _reset_test_lead_in_db(str(mgr.get("db_path") or ""), int(chat_id))
            cnt = sum(int(v or 0) for v in deleted.values())
            total_deleted += cnt
            if cnt:
                lines.append(f"{key}: удалено {cnt} строк")
        if total_deleted <= 0:
            lines.append("Следов не было. Следующее входящее всё равно будет считаться новым, если chat_id не есть в других старых источниках.")
        else:
            lines.append("Следующее входящее сообщение будет считаться новым тестовым лидом.")
        lines.append("")
    return chr(10).join(lines).rstrip()



# ---- baseline old chats helper hotfix 2026-05-06 ----
async def _ensure_baseline_old_chats_table(db_path: str) -> None:
    """Service table: chats that existed before baseline and must be treated as old."""
    if not db_path:
        return
    parent = os.path.dirname(str(db_path))
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(db_path) as db:
        await db.execute("PRAGMA journal_mode=WAL;")
        await db.execute("""
            CREATE TABLE IF NOT EXISTS baseline_old_chats(
                chat_id INTEGER PRIMARY KEY,
                manager_key TEXT DEFAULT '',
                username TEXT DEFAULT '',
                full_name TEXT DEFAULT '',
                source TEXT DEFAULT 'dialog_snapshot',
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        try:
            await db.execute("CREATE INDEX IF NOT EXISTS baseline_old_chats_manager_idx ON baseline_old_chats(manager_key, created_at);")
        except Exception:
            pass
        await db.commit()


async def _baseline_status_for_db(db_path: str) -> Dict[str, Any]:
    if not db_path or not os.path.exists(str(db_path)):
        return {"count": 0, "latest": ""}
    await _ensure_baseline_old_chats_table(db_path)
    async with aiosqlite.connect(db_path) as db:
        cur = await db.execute("SELECT COUNT(*), MAX(created_at) FROM baseline_old_chats")
        row = await cur.fetchone()
        return {"count": int(row[0] or 0) if row else 0, "latest": str(row[1] or "") if row else ""}


async def _baseline_clear_for_db(db_path: str) -> int:
    if not db_path or not os.path.exists(str(db_path)):
        return 0
    await _ensure_baseline_old_chats_table(db_path)
    async with aiosqlite.connect(db_path) as db:
        cur = await db.execute("DELETE FROM baseline_old_chats")
        await db.commit()
        try:
            return int(cur.rowcount or 0)
        except Exception:
            return 0


async def _manager_create_baseline_snapshot() -> Dict[str, Any]:
    """Executed only inside manager process because only manager sessions see private dialogs."""
    if CONTROLLER_MODE or not MANAGER_RUNTIME_KEY:
        return {"ok": False, "count": 0, "error": "not_manager_process"}
    await _ensure_baseline_old_chats_table(DB_PATH)
    now = _now_utc_iso()
    count = 0
    skipped = 0
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute("PRAGMA journal_mode=WAL;")
        async for d in client.iter_dialogs():
            try:
                if not getattr(d, "is_user", False):
                    skipped += 1
                    continue
                ent = getattr(d, "entity", None)
                if getattr(ent, "bot", False):
                    skipped += 1
                    continue
                chat_id = int(getattr(d, "id", 0) or getattr(ent, "id", 0) or 0)
                if chat_id <= 0:
                    skipped += 1
                    continue
                username = str(getattr(ent, "username", None) or "").strip()
                full_name = _full_name(str(getattr(ent, "first_name", None) or ""), str(getattr(ent, "last_name", None) or ""))
                await db.execute(
                    """
                    INSERT INTO baseline_old_chats(chat_id, manager_key, username, full_name, source, created_at, updated_at)
                    VALUES(?,?,?,?,?,?,?)
                    ON CONFLICT(chat_id) DO UPDATE SET
                        manager_key=excluded.manager_key,
                        username=CASE WHEN excluded.username<>'' THEN excluded.username ELSE username END,
                        full_name=CASE WHEN excluded.full_name<>'' THEN excluded.full_name ELSE full_name END,
                        updated_at=excluded.updated_at
                    """,
                    (chat_id, MANAGER_RUNTIME_KEY, username, full_name, "dialog_snapshot", now, now),
                )
                count += 1
            except Exception:
                skipped += 1
                continue
        await db.commit()
    return {"ok": True, "count": count, "skipped": skipped, "manager_key": MANAGER_RUNTIME_KEY}


async def _manager_command_loop() -> None:
    if CONTROLLER_MODE or not MANAGER_RUNTIME_KEY:
        return
    try:
        from storage import manager_queue_finish, manager_queue_take_next
    except Exception as e:
        print(f"manager command queue import error: {e!r}")
        return
    while True:
        try:
            row = await manager_queue_take_next(MANAGER_RUNTIME_KEY, stale_after_sec=120, db_path=TPILOT_DB_PATH)
            if not row:
                await asyncio.sleep(1.0)
                continue
            nonce = str(row.get("nonce") or "")
            command = str(row.get("command") or "").strip().lower()
            try:
                if command == "baseline_create":
                    res = await _manager_create_baseline_snapshot()
                    ok = bool(res.get("ok"))
                    text = f"✅ {MANAGER_RUNTIME_KEY}: текущих чатов помечено старыми: {int(res.get('count') or 0)}" if ok else f"⚠️ {MANAGER_RUNTIME_KEY}: не удалось зафиксировать старые чаты: {res.get('error') or 'error'}"
                    await manager_queue_finish(nonce, worker_key=MANAGER_RUNTIME_KEY, ok=ok, result_text=text, result_json=str(res), db_path=TPILOT_DB_PATH)
                else:
                    await manager_queue_finish(nonce, worker_key=MANAGER_RUNTIME_KEY, ok=False, error_text=f"unknown manager command: {command}", db_path=TPILOT_DB_PATH)
            except Exception as e:
                await manager_queue_finish(nonce, worker_key=MANAGER_RUNTIME_KEY, ok=False, error_text=repr(e), db_path=TPILOT_DB_PATH)
        except asyncio.CancelledError:
            return
        except Exception as e:
            print(f"manager_command_loop error: {e!r}")
            await asyncio.sleep(2.0)


async def _queue_baseline_create_for_manager(key: str, *, user_id: int = 0, timeout_sec: int = 180) -> Tuple[bool, str]:
    try:
        from storage import manager_queue_get, manager_queue_put
    except Exception as e:
        return False, f"Ошибка очереди менеджера: {e!r}"
    nonce = await manager_queue_put(
        target_key=registry_normalize_manager_key(key),
        command="baseline_create",
        created_by=str(user_id or "panel"),
        expires_at=_future_iso(int(timeout_sec) + 60),
        db_path=TPILOT_DB_PATH,
    )
    deadline = time.monotonic() + max(20, int(timeout_sec or 180))
    while time.monotonic() < deadline:
        row = await manager_queue_get(nonce, db_path=TPILOT_DB_PATH)
        status = str((row or {}).get("status") or "")
        if status in ("done", "error", "timeout"):
            if status == "done" and int((row or {}).get("result_ok") or 0) == 1:
                return True, str((row or {}).get("result_text") or f"✅ {key}: старые чаты зафиксированы")
            return False, str((row or {}).get("error_text") or (row or {}).get("result_text") or f"{key}: ошибка фиксации старых чатов")
        await asyncio.sleep(1.0)
    return False, f"{key}: менеджер не ответил за {timeout_sec} сек. Проверьте, что manager-процесс запущен."


async def _handle_baseline_command(args: str, *, user_id: int = 0) -> str:
    parts = str(args or "").split()
    if not parts or parts[0].lower() in ("help", "?", "h"):
        return "\n".join([
            "📌 Старые чаты",
            "",
            "Зафиксировать текущие личные чаты менеджера как старые, чтобы они не получали анкету и не считались новыми лидами:",
            "/baseline create te",
            "/baseline create all",
            "",
            "Проверить, сколько чатов уже помечено старыми:",
            "/baseline status all",
            "",
            "Очистить список старых чатов, только с подтверждением:",
            "/baseline clear te confirm",
            "",
            "Важно: эта функция не удаляет переписки в Telegram. Она только записывает текущие chat_id в список старых чатов для TPilot.",
        ]).rstrip()
    action = parts[0].lower()
    target = registry_normalize_manager_key(parts[1] if len(parts) >= 2 else "all") or "all"
    confirm = len(parts) >= 3 and parts[2].lower() == "confirm"
    rows = await _manager_rows_for_reporting()
    keys = [registry_normalize_manager_key(r.get("manager_key") or "") for r in rows if registry_normalize_manager_key(r.get("manager_key") or "")]
    if target != "all" and target not in keys:
        return f"Менеджер не найден: {target}"

    selected = [r for r in rows if target == "all" or registry_normalize_manager_key(r.get("manager_key") or "") == target]
    if action in ("status", "st", "info"):
        lines = ["📊 Статус старых чатов", ""]
        for r in selected:
            key = registry_normalize_manager_key(r.get("manager_key") or "")
            st = await _baseline_status_for_db(str(r.get("db_path") or ""))
            latest = str(st.get("latest") or "")
            latest_disp = _iso_to_local_hhmm(latest) if latest else "_"
            lines.append(f"{key}: {int(st.get('count') or 0)} старых чатов | обновлено {latest_disp}")
        return chr(10).join(lines).rstrip()

    if action == "clear":
        if not confirm:
            return "Для очистки списка старых чатов добавьте confirm. Пример: /baseline clear te confirm"
        lines = ["🧹 Очистка списка старых чатов", ""]
        for r in selected:
            key = registry_normalize_manager_key(r.get("manager_key") or "")
            cnt = await _baseline_clear_for_db(str(r.get("db_path") or ""))
            lines.append(f"{key}: удалено {cnt}")
        return chr(10).join(lines).rstrip()

    if action == "create":
        lines = ["📌 Фиксация старых чатов", ""]
        for r in selected:
            key = registry_normalize_manager_key(r.get("manager_key") or "")
            ok, text = await _queue_baseline_create_for_manager(key, user_id=user_id, timeout_sec=180)
            lines.append(("✅ " if ok else "⚠️ ") + text)
        lines.append("")
        lines.append("Готово. Текущие личные диалоги выбранных менеджеров теперь считаются старыми. Они не будут получать анкету и не будут считаться новыми лидами.")
        return chr(10).join(lines).rstrip()

    return "Формат: /baseline create|status|clear <manager|all>"





# -------------------- traffic sources and manager groups --------------------
def _structure_key(raw: Any) -> str:
    key = registry_normalize_manager_key(str(raw or ""))
    key = re.sub(r"[^a-z0-9_-]+", "", key)
    return key


def _nice_status(raw: Any) -> str:
    st = str(raw or "active").strip().lower()
    if st in ("active", "on", "enabled", "1", "true"):
        return "active"
    if st in ("disabled", "off", "paused", "0", "false"):
        return "disabled"
    return "active"


async def _ensure_sources_groups_tables() -> None:
    parent = os.path.dirname(TPILOT_DB_PATH)
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute("PRAGMA journal_mode=WAL;")
        await db.execute("""
            CREATE TABLE IF NOT EXISTS traffic_sources(
                source_key TEXT PRIMARY KEY,
                name TEXT NOT NULL DEFAULT '',
                description TEXT NOT NULL DEFAULT '',
                status TEXT NOT NULL DEFAULT 'active',
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        await db.execute("""
            CREATE TABLE IF NOT EXISTS manager_source_links(
                manager_key TEXT PRIMARY KEY,
                source_key TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        await db.execute("""
            CREATE TABLE IF NOT EXISTS manager_groups(
                group_key TEXT PRIMARY KEY,
                name TEXT NOT NULL DEFAULT '',
                description TEXT NOT NULL DEFAULT '',
                status TEXT NOT NULL DEFAULT 'active',
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        await db.execute("""
            CREATE TABLE IF NOT EXISTS manager_group_members(
                group_key TEXT NOT NULL DEFAULT '',
                manager_key TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL DEFAULT '',
                PRIMARY KEY(group_key, manager_key)
            );
        """)
        await db.execute("CREATE INDEX IF NOT EXISTS manager_source_links_source_idx ON manager_source_links(source_key);")
        await db.execute("CREATE INDEX IF NOT EXISTS manager_group_members_manager_idx ON manager_group_members(manager_key);")
        await db.commit()


async def _source_rows() -> List[Dict[str, Any]]:
    await _ensure_sources_groups_tables()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM traffic_sources ORDER BY status ASC, name COLLATE NOCASE ASC, source_key ASC")
        return [dict(r) for r in await cur.fetchall()]


async def _source_get(source_key: str) -> Optional[Dict[str, Any]]:
    key = _structure_key(source_key)
    if not key:
        return None
    await _ensure_sources_groups_tables()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM traffic_sources WHERE source_key=?", (key,))
        row = await cur.fetchone()
        return dict(row) if row else None


async def _source_links_map() -> Dict[str, str]:
    await _ensure_sources_groups_tables()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        cur = await db.execute("SELECT manager_key, source_key FROM manager_source_links WHERE COALESCE(source_key,'')<>''")
        out: Dict[str, str] = {}
        for row in await cur.fetchall():
            out[registry_normalize_manager_key(row[0] or "")] = _structure_key(row[1] or "")
        return out


async def _source_managers(source_key: str) -> List[str]:
    key = _structure_key(source_key)
    links = await _source_links_map()
    return sorted([m for m, s in links.items() if s == key])


async def _group_rows() -> List[Dict[str, Any]]:
    await _ensure_sources_groups_tables()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM manager_groups ORDER BY status ASC, name COLLATE NOCASE ASC, group_key ASC")
        return [dict(r) for r in await cur.fetchall()]


async def _group_get(group_key: str) -> Optional[Dict[str, Any]]:
    key = _structure_key(group_key)
    if not key:
        return None
    await _ensure_sources_groups_tables()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM manager_groups WHERE group_key=?", (key,))
        row = await cur.fetchone()
        return dict(row) if row else None


async def _group_members(group_key: str) -> List[str]:
    key = _structure_key(group_key)
    await _ensure_sources_groups_tables()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        cur = await db.execute("SELECT manager_key FROM manager_group_members WHERE group_key=? ORDER BY manager_key ASC", (key,))
        return [registry_normalize_manager_key(r[0] or "") for r in await cur.fetchall() if registry_normalize_manager_key(r[0] or "")]


async def _manager_key_exists(key: str) -> bool:
    k = registry_normalize_manager_key(key or "")
    if not k:
        return False
    try:
        row = await manager_get(k)
        return bool(row and str(row.get("status") or "") != "archived")
    except Exception:
        return False


async def _manager_label_map() -> Dict[str, str]:
    rows = await manager_list_rows(include_removed=False)
    out: Dict[str, str] = {}
    for r in rows or []:
        k = registry_normalize_manager_key(r.get("manager_key") or "")
        if k:
            out[k] = _manager_label_from_row(r)
    return out


def _source_status_icon(status: Any) -> str:
    return "🟢" if _nice_status(status) == "active" else "⚪"


def _stats_for_leads_subset(leads: List[Dict[str, Any]]) -> Dict[str, int]:
    out = {"total": 0, "new": 0, "duplicates": 0, "profile_done": 0, "liquid": 0, "nonliquid": 0, "unknown": 0, "na": 0, "trash": 0}
    for lead in leads or []:
        out["total"] += 1
        if int(lead.get("duplicate") or 0) == 1:
            out["duplicates"] += 1
        else:
            out["new"] += 1
        if int(lead.get("profile_done") or 0) == 1:
            out["profile_done"] += 1
        status = str(lead.get("status") or "").strip().lower()
        if status == "liquid":
            out["liquid"] += 1
        elif status == "nonliquid":
            out["nonliquid"] += 1
        else:
            out["unknown"] += 1
        reason = str(lead.get("nonliquid_reason") or "").strip().lower()
        if status not in ("liquid", "nonliquid") or reason == "na":
            out["na"] += 1
        if reason in ("trash", "send_failed") or int(lead.get("trash") or 0) == 1:
            out["trash"] += 1
    return out


def _append_compact_stats(lines: List[str], stats: Dict[str, int]) -> None:
    lines.append(f"Лидов: {int(stats.get('total') or 0)}")
    lines.append(f"Новые: {int(stats.get('new') or 0)}")
    lines.append(f"Дубликаты: {int(stats.get('duplicates') or 0)}")
    lines.append(f"Ответили город/возраст: {int(stats.get('profile_done') or 0)}")
    lines.append(f"Ликвид: {int(stats.get('liquid') or 0)}")
    lines.append(f"Неликвид: {int(stats.get('nonliquid') or 0)}")
    lines.append(f"Не определено: {int(stats.get('unknown') or 0)}")


async def _structure_leads_for_managers(manager_keys: List[str], lead_date: Optional[str] = None) -> List[Dict[str, Any]]:
    wanted = {registry_normalize_manager_key(k or "") for k in manager_keys if registry_normalize_manager_key(k or "")}
    if not wanted:
        return []
    date_key = lead_date or _kyiv_now().date().isoformat()
    leads = await _collect_day_leads(date_key, target_key="all")
    return [dict(x) for x in leads if registry_normalize_manager_key(x.get("manager_key") or "") in wanted]


async def _source_stats_text(source_key: str = "all") -> str:
    await _ensure_sources_groups_tables()
    date_disp = _kyiv_now().strftime("%d.%m.%y")
    labels = await _manager_label_map()
    sources = await _source_rows()
    links = await _source_links_map()
    if _structure_key(source_key) and _structure_key(source_key) != "all":
        src = await _source_get(source_key)
        if not src:
            return f"Источник не найден: {_structure_key(source_key)}"
        managers = [m for m, s in links.items() if s == _structure_key(source_key)]
        leads = await _structure_leads_for_managers(managers)
        stats = _stats_for_leads_subset(leads)
        lines = [f"📦 Источник трафика: {src.get('name') or src.get('source_key')}", f"Дата: {date_disp}", "", f"Статус: {'активен' if _nice_status(src.get('status')) == 'active' else 'выключен'}"]
        lines.append("Менеджеры: " + (", ".join(labels.get(m, m) for m in managers) if managers else "не привязаны"))
        lines.append("")
        _append_compact_stats(lines, stats)
        return chr(10).join(lines).rstrip()

    lines = [f"📦 Источники трафика за {date_disp}", ""]
    if not sources:
        return "📦 Источники трафика\n\nИсточники ещё не созданы. Добавьте их через PanelBot или командой /source add <key> <название>."
    for src in sources:
        key = _structure_key(src.get("source_key"))
        managers = [m for m, s in links.items() if s == key]
        stats = _stats_for_leads_subset(await _structure_leads_for_managers(managers))
        lines.append(f"{_source_status_icon(src.get('status'))} {src.get('name') or key}")
        lines.append(f"Менеджеры: {len(managers)}")
        lines.append(f"Лидов: {stats['total']} | Ликвид: {stats['liquid']} | NA: {stats['unknown']}")
        lines.append("")
    return chr(10).join(lines).rstrip()


async def _group_stats_text(group_key: str = "all") -> str:
    await _ensure_sources_groups_tables()
    date_disp = _kyiv_now().strftime("%d.%m.%y")
    labels = await _manager_label_map()
    groups = await _group_rows()
    if _structure_key(group_key) and _structure_key(group_key) != "all":
        grp = await _group_get(group_key)
        if not grp:
            return f"Группа не найдена: {_structure_key(group_key)}"
        members = await _group_members(group_key)
        leads = await _structure_leads_for_managers(members)
        stats = _stats_for_leads_subset(leads)
        lines = [f"👥 Группа менеджеров: {grp.get('name') or grp.get('group_key')}", f"Дата: {date_disp}", "", f"Статус: {'а��тивна' if _nice_status(grp.get('status')) == 'active' else 'выключена'}"]
        lines.append("Менеджеры: " + (", ".join(labels.get(m, m) for m in members) if members else "не добавлены"))
        lines.append("")
        _append_compact_stats(lines, stats)
        return chr(10).join(lines).rstrip()

    lines = [f"👥 Группы менеджеров за {date_disp}", ""]
    if not groups:
        return "👥 Группы менеджеров\n\nГруппы ещё не созданы. Добавьте их через PanelBot или командой /mgroup add <key> <название>."
    for grp in groups:
        key = _structure_key(grp.get("group_key"))
        members = await _group_members(key)
        stats = _stats_for_leads_subset(await _structure_leads_for_managers(members))
        icon = "🟢" if _nice_status(grp.get("status")) == "active" else "⚪"
        lines.append(f"{icon} {grp.get('name') or key}")
        lines.append(f"Менеджеры: {len(members)}")
        lines.append(f"Лидов: {stats['total']} | Ликвид: {stats['liquid']} | NA: {stats['unknown']}")
        lines.append("")
    return chr(10).join(lines).rstrip()


async def _handle_source_command(args: str, *, user_id: int = 0) -> str:
    await _ensure_sources_groups_tables()
    raw = str(args or "").strip()
    parts = raw.split(maxsplit=2)
    action = (parts[0].lower() if parts else "help")
    now = _now_utc_iso()
    if action in ("help", ""):
        return "\n".join([
            "📦 Источники трафика",
            "",
            "Один менеджер закрепляется за одним источником трафика.",
            "Источник нужен, чтобы видеть качество лидов по SEO, Женя, Яндекс и другим направлениям.",
            "",
            "Команды:",
            "/source add seo SEO",
            "/source list",
            "/source info seo",
            "/source rename seo SEO новое имя",
            "/source link seo te",
            "/source unlink te",
            "/source stats all",
            "/source stats seo",
            "/source off seo",
            "/source on seo",
            "/source delete seo confirm",
        ]).rstrip()
    if action == "add":
        if len(parts) < 3:
            return "Формат: /source add <key> <название>. Например: /source add seo SEO"
        key = _structure_key(parts[1])
        name = parts[2].strip()
        if not key or not name:
            return "Источник не создан: пустой key или название."
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute("""
                INSERT INTO traffic_sources(source_key, name, status, created_at, updated_at)
                VALUES(?,?,?,?,?)
                ON CONFLICT(source_key) DO UPDATE SET name=excluded.name, updated_at=excluded.updated_at
            """, (key, name, "active", now, now))
            await db.commit()
        return f"✅ Источник создан или обновлён\nКлюч: {key}\nНазвание: {name}"
    if action in ("list", "all"):
        rows = await _source_rows()
        if not rows:
            return "📦 Источники трафика пока не созданы."
        links = await _source_links_map()
        lines = ["📦 Источники трафика", ""]
        for r in rows:
            key = _structure_key(r.get("source_key"))
            cnt = sum(1 for s in links.values() if s == key)
            lines.append(f"{_source_status_icon(r.get('status'))} {r.get('name') or key} | key: {key} | менеджеров: {cnt}")
        return chr(10).join(lines).rstrip()
    if action == "info":
        key = _structure_key(parts[1] if len(parts) >= 2 else "")
        src = await _source_get(key)
        if not src:
            return f"Источник не найден: {key}"
        labels = await _manager_label_map()
        managers = await _source_managers(key)
        return "\n".join([
            f"📦 Источник: {src.get('name') or key}",
            "",
            f"Ключ: {key}",
            f"Статус: {'активен' if _nice_status(src.get('status')) == 'active' else 'выключен'}",
            "Менеджеры: " + (", ".join(labels.get(m, m) for m in managers) if managers else "не привязаны"),
        ]).rstrip()
    if action == "rename":
        if len(parts) < 3:
            return "Формат: /source rename <key> <новое название>"
        key = _structure_key(parts[1])
        name = parts[2].strip()
        if not await _source_get(key):
            return f"Источник не найден: {key}"
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute("UPDATE traffic_sources SET name=?, updated_at=? WHERE source_key=?", (name, now, key))
            await db.commit()
        return f"✅ Источник переименован\n{key}: {name}"
    if action in ("on", "off"):
        key = _structure_key(parts[1] if len(parts) >= 2 else "")
        if not await _source_get(key):
            return f"Источник не найден: {key}"
        status = "active" if action == "on" else "disabled"
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute("UPDATE traffic_sources SET status=?, updated_at=? WHERE source_key=?", (status, now, key))
            await db.commit()
        return f"{'🟢' if status == 'active' else '⚪'} Источник {'включён' if status == 'active' else 'выключен'}: {key}"
    if action == "link":
        if len(parts) < 3:
            return "Формат: /source link <source_key> <manager_key>"
        source_key = _structure_key(parts[1])
        manager_key = registry_normalize_manager_key(parts[2])
        if not await _source_get(source_key):
            return f"Источник не найден: {source_key}"
        if not await _manager_key_exists(manager_key):
            return f"Менеджер не найден: {manager_key}"
        # --- TPILOT TRANSFERS STAGE1 M2.7A START ---
        # Fail closed: closers must never receive a source link (PartnerBot privacy fence
        # depends entirely on manager_source_links). A missing role column safely implies
        # "not a closer" (closers can only exist after the column is created).
        try:
            async with aiosqlite.connect(TPILOT_DB_PATH) as _role_db:
                _role_db.row_factory = aiosqlite.Row
                _role_cur = await _role_db.execute("SELECT role FROM managers WHERE manager_key=?", (manager_key,))
                _role_row = await _role_cur.fetchone()
            if _role_row and str(_role_row["role"] or "").strip().lower() == "closer":
                return "Клоузеры не привязываются к источникам."
        except Exception:
            pass
        # --- TPILOT TRANSFERS STAGE1 M2.7A END ---
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute("""
                INSERT INTO manager_source_links(manager_key, source_key, created_at, updated_at)
                VALUES(?,?,?,?)
                ON CONFLICT(manager_key) DO UPDATE SET source_key=excluded.source_key, updated_at=excluded.updated_at
            """, (manager_key, source_key, now, now))
            await db.commit()
        # ONBOARDING SOURCE PICK 20260711: additive status line only -- schedule
        # inheritance itself already exists (manager_effective_is_working reads the
        # linked source's source_work_schedule when the manager has no explicit
        # override row), this just reports whether that inheritance has anything
        # to inherit. No manager schedule rows are created here, no 08:00-17:00
        # hardcoding -- read-only via the existing source_work_schedule_get helper.
        try:
            from storage import source_work_schedule_get as _swsg
            sched = _swsg(source_key, db_path=TPILOT_DB_PATH)
        except Exception:
            sched = None
        if sched and int(sched.get("enabled") or 0) == 1:
            schedule_line = "📅 График источника применён: менеджер наследует график источника."
        else:
            schedule_line = "⚠️ У источника не настроен график дней. Настройте график источника или дни менеджера."
        return f"✅ Менеджер закреплён за источником\nМенеджер: {manager_key}\nИсточник: {source_key}\n{schedule_line}"
    if action == "unlink":
        manager_key = registry_normalize_manager_key(parts[1] if len(parts) >= 2 else "")
        if not manager_key:
            return "Формат: /source unlink <manager_key>"
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute("DELETE FROM manager_source_links WHERE manager_key=?", (manager_key,))
            await db.commit()
        return f"✅ Менеджер отвязан от источника: {manager_key}"
    if action == "stats":
        key = _structure_key(parts[1] if len(parts) >= 2 else "all") or "all"
        return await _source_stats_text(key)
    if action == "delete":
        key = _structure_key(parts[1] if len(parts) >= 2 else "")
        confirm = (len(parts) >= 3 and parts[2].strip().lower() == "confirm")
        if not key:
            return "Формат: /source delete <key> confirm"
        if not confirm:
            return f"ОПАСНО: для удаления источника добавьте confirm. Пример: /source delete {key} confirm"
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute("DELETE FROM manager_source_links WHERE source_key=?", (key,))
            await db.execute("DELETE FROM traffic_sources WHERE source_key=?", (key,))
            await db.commit()
        return f"🗑 Источник удалён: {key}"
    return "Формат: /source help"


async def _handle_mgroup_command(args: str, *, user_id: int = 0) -> str:
    await _ensure_sources_groups_tables()
    raw = str(args or "").strip()
    parts = raw.split(maxsplit=2)
    action = (parts[0].lower() if parts else "help")
    now = _now_utc_iso()
    if action in ("help", ""):
        return "\n".join([
            "👥 Группы менеджеров",
            "",
            "Группа объединяет менеджеров для отдельной аналитики по команде.",
            "Расписаний нет: группы управляются вручную через панель.",
            "",
            "Команды:",
            "/mgroup add group1 Группа 1",
            "/mgroup list",
            "/mgroup info group1",
            "/mgroup rename group1 Новое название",
            "/mgroup add_manager group1 te",
            "/mgroup remove_manager group1 te",
            "/mgroup stats all",
            "/mgroup stats group1",
            "/mgroup off group1",
            "/mgroup on group1",
            "/mgroup delete group1 confirm",
        ]).rstrip()
    if action == "add":
        if len(parts) < 3:
            return "Формат: /mgroup add <key> <название>. Например: /mgroup add group1 Группа 1"
        key = _structure_key(parts[1])
        name = parts[2].strip()
        if not key or not name:
            return "Группа не создана: пустой key или название."
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute("""
                INSERT INTO manager_groups(group_key, name, status, created_at, updated_at)
                VALUES(?,?,?,?,?)
                ON CONFLICT(group_key) DO UPDATE SET name=excluded.name, updated_at=excluded.updated_at
            """, (key, name, "active", now, now))
            await db.commit()
        return f"✅ Группа создана или обновлена\nКлюч: {key}\nНазвание: {name}"
    if action in ("list", "all"):
        rows = await _group_rows()
        if not rows:
            return "👥 Группы менеджеров пока не созданы."
        lines = ["👥 Группы менеджеров", ""]
        for r in rows:
            key = _structure_key(r.get("group_key"))
            cnt = len(await _group_members(key))
            icon = "🟢" if _nice_status(r.get("status")) == "active" else "⚪"
            lines.append(f"{icon} {r.get('name') or key} | key: {key} | менеджеров: {cnt}")
        return chr(10).join(lines).rstrip()
    if action == "info":
        key = _structure_key(parts[1] if len(parts) >= 2 else "")
        grp = await _group_get(key)
        if not grp:
            return f"Группа не найдена: {key}"
        labels = await _manager_label_map()
        members = await _group_members(key)
        return "\n".join([
            f"👥 Группа: {grp.get('name') or key}",
            "",
            f"Ключ: {key}",
            f"Статус: {'активна' if _nice_status(grp.get('status')) == 'active' else 'выключена'}",
            "Менеджеры: " + (", ".join(labels.get(m, m) for m in members) if members else "не добавлены"),
        ]).rstrip()
    if action == "rename":
        if len(parts) < 3:
            return "Формат: /mgroup rename <key> <новое название>"
        key = _structure_key(parts[1])
        name = parts[2].strip()
        if not await _group_get(key):
            return f"Группа не найдена: {key}"
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute("UPDATE manager_groups SET name=?, updated_at=? WHERE group_key=?", (name, now, key))
            await db.commit()
        return f"✅ Группа переименована\n{key}: {name}"
    if action in ("on", "off"):
        key = _structure_key(parts[1] if len(parts) >= 2 else "")
        if not await _group_get(key):
            return f"Группа не найдена: {key}"
        status = "active" if action == "on" else "disabled"
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute("UPDATE manager_groups SET status=?, updated_at=? WHERE group_key=?", (status, now, key))
            await db.commit()
        return f"{'🟢' if status == 'active' else '⚪'} Группа {'включена' if status == 'active' else 'выключена'}: {key}"
    if action == "add_manager":
        if len(parts) < 3:
            return "Формат: /mgroup add_manager <group_key> <manager_key>"
        group_key = _structure_key(parts[1])
        manager_key = registry_normalize_manager_key(parts[2])
        if not await _group_get(group_key):
            return f"Группа не найдена: {group_key}"
        if not await _manager_key_exists(manager_key):
            return f"Менеджер не найден: {manager_key}"
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute("INSERT OR IGNORE INTO manager_group_members(group_key, manager_key, created_at) VALUES(?,?,?)", (group_key, manager_key, now))
            await db.commit()
        return f"✅ Менеджер добавлен в группу\nГруппа: {group_key}\nМенеджер: {manager_key}"
    if action == "remove_manager":
        if len(parts) < 3:
            return "Формат: /mgroup remove_manager <group_key> <manager_key>"
        group_key = _structure_key(parts[1])
        manager_key = registry_normalize_manager_key(parts[2])
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute("DELETE FROM manager_group_members WHERE group_key=? AND manager_key=?", (group_key, manager_key))
            await db.commit()
        return f"✅ Менеджер удалён из группы\nГруппа: {group_key}\nМенеджер: {manager_key}"
    if action == "stats":
        key = _structure_key(parts[1] if len(parts) >= 2 else "all") or "all"
        return await _group_stats_text(key)
    if action == "delete":
        key = _structure_key(parts[1] if len(parts) >= 2 else "")
        confirm = (len(parts) >= 3 and parts[2].strip().lower() == "confirm")
        if not key:
            return "Формат: /mgroup delete <key> confirm"
        if not confirm:
            return f"ОПАСНО: для удаления группы добавьте confirm. Пример: /mgroup delete {key} confirm"
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute("DELETE FROM manager_group_members WHERE group_key=?", (key,))
            await db.execute("DELETE FROM manager_groups WHERE group_key=?", (key,))
            await db.commit()
        return f"🗑 Группа удалена: {key}"
    return "Формат: /mgroup help"


# -------------------- quality / discipline / funnel --------------------
def _quality_date_from_token(raw: str = ""):
    token = str(raw or "").strip().lower()
    today = _kyiv_now().date()
    if not token or token in ("today", "сегодня"):
        return today
    if token in ("yesterday", "вчера"):
        return today - timedelta(days=1)
    try:
        d = _tp_parse_date_token(token)
        if d:
            return d
    except Exception:
        pass
    return today


def _quality_date_from_parts(parts: List[str], default_index: int = 1):
    if len(parts) > default_index:
        return _quality_date_from_token(parts[default_index])
    return _quality_date_from_token("")


def _quality_date_header(d) -> str:
    try:
        today = _kyiv_now().date()
        if d == today:
            return f"сегодня, {d.strftime('%d.%m.%y')}"
        if d == today - timedelta(days=1):
            return f"вчера, {d.strftime('%d.%m.%y')}"
        return d.strftime('%d.%m.%y')
    except Exception:
        return str(d or "")


async def _quality_collect_day_leads(date_iso: str) -> List[Dict[str, Any]]:
    rows = await _manager_rows_for_reporting()
    result: List[Dict[str, Any]] = []
    for mgr in rows:
        key = registry_normalize_manager_key(mgr.get("manager_key") or "")
        db_path = str(mgr.get("db_path") or "")
        if not key or not db_path:
            continue
        try:
            trash_map = await _profile_reminder_trash_map(db_path) if "_profile_reminder_trash_map" in globals() else {}
        except Exception:
            trash_map = {}
        for lead in await _list_daily_leads_for_db(db_path, str(date_iso)):
            item = dict(lead)
            item["manager_key"] = key or item.get("manager_key") or ""
            item["manager_display_name"] = str(mgr.get("display_name") or key)
            item["manager_username"] = str(mgr.get("telegram_username") or item.get("manager_username") or "")
            tr = trash_map.get(int(item.get("chat_id") or 0)) or {}
            item["trash"] = int(tr.get("trash") or 0)
            item["trash_reason"] = str(tr.get("trash_reason") or "")
            result.append(item)
    result.sort(key=lambda x: (str(x.get("first_seen_utc") or ""), str(x.get("manager_key") or ""), int(x.get("id") or 0)))
    return result


def _lead_response_minutes(lead: Dict[str, Any]) -> Optional[int]:
    if int(lead.get("manager_replied") or 0) != 1:
        return None
    first = _tp_parse_utc(str(lead.get("first_seen_utc") or ""))
    replied = _tp_parse_utc(str(lead.get("manager_replied_at") or ""))
    if not first or not replied:
        return None
    return max(0, int((replied - first).total_seconds() // 60))


def _quality_bucket_empty(label: str = "") -> Dict[str, Any]:
    return {
        "label": label,
        "total": 0,
        "answered": 0,
        "not_answered": 0,
        "sla_ok": 0,
        "sla_late": 0,
        "response_minutes": [],
        "new": 0,
        "duplicates": 0,
        "profile_done": 0,
        "liquid": 0,
        "nonliquid": 0,
        "na": 0,
        "trash": 0,
        "geo": 0,
        "under18": 0,
    }


def _avg_int(values: List[int]) -> int:
    vals = [int(x) for x in values if x is not None]
    return int(round(sum(vals) / len(vals))) if vals else 0


def _median_int(values: List[int]) -> int:
    vals = sorted(int(x) for x in values if x is not None)
    if not vals:
        return 0
    mid = len(vals) // 2
    if len(vals) % 2:
        return vals[mid]
    return int(round((vals[mid - 1] + vals[mid]) / 2))


def _percent(part: int, total: int) -> int:
    try:
        return int(round((int(part or 0) / max(1, int(total or 0))) * 100))
    except Exception:
        return 0


def _manager_quality_score(bucket: Dict[str, Any]) -> int:
    total = int(bucket.get("total") or 0)
    if total <= 0:
        return 0
    score = 0
    score += min(40, _percent(int(bucket.get("sla_ok") or 0), max(1, int(bucket.get("answered") or 0))) * 40 // 100)
    score += min(25, _percent(int(bucket.get("answered") or 0), total) * 25 // 100)
    score += min(25, _percent(int(bucket.get("liquid") or 0), total) * 25 // 100)
    score -= min(20, _percent(int(bucket.get("na") or 0), total) * 20 // 100)
    score -= min(15, _percent(int(bucket.get("trash") or 0), total) * 15 // 100)
    return max(0, min(100, int(score)))


def _score_label(score: int) -> str:
    s = int(score or 0)
    if s >= 75:
        return "🟢 сильно"
    if s >= 50:
        return "🟡 средне"
    if s > 0:
        return "🔴 слабо"
    return "⚪ нет да��ных"


def _manager_quality_buckets(leads: List[Dict[str, Any]], manager_rows: List[Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
    buckets: Dict[str, Dict[str, Any]] = {}
    for mgr in manager_rows or []:
        key = registry_normalize_manager_key(mgr.get("manager_key") or "")
        if not key:
            continue
        buckets[key] = _quality_bucket_empty(_manager_label_from_row(mgr))
    for lead in leads or []:
        key = registry_normalize_manager_key(lead.get("manager_key") or "")
        if not key:
            continue
        if key not in buckets:
            buckets[key] = _quality_bucket_empty(key)
        _quality_bucket_add(buckets[key], lead)
    return buckets


def _append_quality_bucket(lines: List[str], bucket: Dict[str, Any], *, include_score: bool = True) -> None:
    total = int(bucket.get("total") or 0)
    answered = int(bucket.get("answered") or 0)
    resp = list(bucket.get("response_minutes") or [])
    lines.append(f"Лидов: {total}")
    lines.append(f"Ответил менеджер: {answered}")
    lines.append(f"Не ответил: {int(bucket.get('not_answered') or 0)}")
    lines.append(f"Ответ до 15 мин: {int(bucket.get('sla_ok') or 0)}")
    lines.append(f"Просрочено 15+: {int(bucket.get('sla_late') or 0)}")
    lines.append(f"Среднее время ответа: {_format_wait_duration(_avg_int(resp)) if resp else 'нет данных'}")
    lines.append(f"Медиана ответа: {_format_wait_duration(_median_int(resp)) if resp else 'нет данных'}")
    lines.append(f"Ликвид: {int(bucket.get('liquid') or 0)}")
    lines.append(f"Неликвид: {int(bucket.get('nonliquid') or 0)}")
    lines.append(f"NA: {int(bucket.get('na') or 0)}")
    lines.append(f"TRASH: {int(bucket.get('trash') or 0)}")
    if include_score:
        score = _manager_quality_score(bucket)
        lines.append(f"Оценка: {_score_label(score)} | {score}/100")


async def _quality_response_text(date_token: str = "") -> str:
    d = _quality_date_from_token(date_token)
    rows = await _manager_rows_for_reporting()
    leads = await _quality_collect_day_leads(d.isoformat())
    buckets = _manager_quality_buckets(leads, rows)
    lines = [f"⏱ Время ответа | {_quality_date_header(d)}", ""]
    if not buckets:
        return "⏱ Время ответа\n\nМенеджеры не найдены."
    for key, b in buckets.items():
        if int(b.get("total") or 0) <= 0:
            continue
        lines.append(str(b.get("label") or key))
        lines.append(f"Лидов: {int(b.get('total') or 0)}")
        lines.append(f"Ответил: {int(b.get('answered') or 0)}")
        lines.append(f"Не ответил: {int(b.get('not_answered') or 0)}")
        lines.append(f"До 15 мин: {int(b.get('sla_ok') or 0)}")
        lines.append(f"Просрочено: {int(b.get('sla_late') or 0)}")
        resp = list(b.get("response_minutes") or [])
        lines.append(f"Среднее: {_format_wait_duration(_avg_int(resp)) if resp else 'нет данных'}")
        lines.append(f"Медиана: {_format_wait_duration(_median_int(resp)) if resp else 'нет данных'}")
        lines.append("")
    if len(lines) <= 2:
        lines.append("Лидов за период пока нет.")
    return chr(10).join(lines).rstrip()


async def _quality_ranking_text(date_token: str = "") -> str:
    d = _quality_date_from_token(date_token)
    rows = await _manager_rows_for_reporting()
    leads = await _quality_collect_day_leads(d.isoformat())
    buckets = _manager_quality_buckets(leads, rows)
    ranked = []
    for key, b in buckets.items():
        if int(b.get("total") or 0) <= 0:
            continue
        ranked.append(( _manager_quality_score(b), key, b ))
    ranked.sort(key=lambda x: (-x[0], -int(x[2].get("liquid") or 0), str(x[1])))
    lines = [f"🏆 Рейтинг менеджеров | {_quality_date_header(d)}", ""]
    if not ranked:
        return chr(10).join(lines + ["Лидов за период пока нет."]).rstrip()
    for idx, (score, key, b) in enumerate(ranked, 1):
        lines.append(f"{idx}. {b.get('label') or key}")
        lines.append(f"Оценка: {_score_label(score)} | {score}/100")
        lines.append(f"Лидов: {int(b.get('total') or 0)} | Ликвид: {int(b.get('liquid') or 0)} | NA: {int(b.get('na') or 0)}")
        lines.append(f"Ответ до 15 мин: {int(b.get('sla_ok') or 0)} из {int(b.get('answered') or 0)}")
        lines.append("")
    return chr(10).join(lines).rstrip()


async def _quality_losses_text(date_token: str = "") -> str:
    d = _quality_date_from_token(date_token)
    leads = await _quality_collect_day_leads(d.isoformat())
    b = _quality_bucket_empty("all")
    for lead in leads:
        _quality_bucket_add(b, lead)
    lines = [f"📉 Потери лидов | {_quality_date_header(d)}", ""]
    lines.append(f"Всего лидов: {int(b.get('total') or 0)}")
    lines.append(f"Не ответил менеджер: {int(b.get('not_answered') or 0)}")
    lines.append(f"Не дали город/возраст: {int(b.get('na') or 0)}")
    lines.append(f"Неликвид по гео: {int(b.get('geo') or 0)}")
    lines.append(f"-18: {int(b.get('under18') or 0)}")
    lines.append(f"TRASH: {int(b.get('trash') or 0)}")
    lines.append(f"Ликвид: {int(b.get('liquid') or 0)}")
    return chr(10).join(lines).rstrip()


async def _quality_sla_text(date_token: str = "") -> str:
    d = _quality_date_from_token(date_token)
    rows = await _manager_rows_for_reporting()
    leads = await _quality_collect_day_leads(d.isoformat())
    manager_labels = {registry_normalize_manager_key(r.get("manager_key") or ""): _manager_label_from_row(r) for r in rows}
    late = []
    for lead in leads:
        rm = _lead_response_minutes(lead)
        if rm is None:
            # If lead is old enough and no manual reply, it is SLA-problem too.
            first = _tp_parse_utc(str(lead.get("first_seen_utc") or ""))
            if first:
                age_min = max(0, int((_tp_dt_utc_now() - first).total_seconds() // 60))
                if age_min >= 15:
                    late.append((age_min, lead, "ждёт"))
        elif rm > 15:
            late.append((rm, lead, "ответ через"))
    late.sort(key=lambda x: (-int(x[0]), str(x[1].get("manager_key") or "")))
    lines = [f"🚨 Просроченные SLA 15+ | {_quality_date_header(d)}", ""]
    if not late:
        return chr(10).join(lines + ["Просроченных SLA нет."]).rstrip()
    grouped: Dict[str, List[Tuple[int, Dict[str, Any], str]]] = {}
    for item in late:
        key = registry_normalize_manager_key(item[1].get("manager_key") or "")
        grouped.setdefault(key, []).append(item)
    for key, items in grouped.items():
        lines.append(manager_labels.get(key, key))
        for idx, (mins, lead, prefix) in enumerate(items[:15], 1):
            username = str(lead.get("username") or "").strip()
            full_name = str(lead.get("full_name") or "").strip()
            chat_id = int(lead.get("chat_id") or 0)
            who = (username if username.startswith("@") else ("@" + username if username else "")) or full_name or f"ID {chat_id}"
            lines.append(f"{idx}) {who} | {prefix} {_format_wait_duration(int(mins))}")
        if len(items) > 15:
            lines.append(f"...ещё {len(items) - 15}")
        lines.append("")
    return chr(10).join(lines).rstrip()


async def _quality_all_text(date_token: str = "") -> str:
    d = _quality_date_from_token(date_token)
    rows = await _manager_rows_for_reporting()
    leads = await _quality_collect_day_leads(d.isoformat())
    buckets = _manager_quality_buckets(leads, rows)
    lines = [f"📈 Качество и дисциплина | {_quality_date_header(d)}", ""]
    if not leads:
        return chr(10).join(lines + ["Лидов за период пока нет."]).rstrip()
    total = _quality_bucket_empty("all")
    for lead in leads:
        _quality_bucket_add(total, lead)
    lines.append("Итого")
    _append_quality_bucket(lines, total, include_score=False)
    lines.append("")
    ranked = sorted([( _manager_quality_score(b), key, b ) for key, b in buckets.items() if int(b.get("total") or 0) > 0], key=lambda x: (-x[0], str(x[1])))
    lines.append("Менеджеры")
    for idx, (score, key, b) in enumerate(ranked[:10], 1):
        lines.append(f"{idx}. {b.get('label') or key} | {_score_label(score)} | {score}/100 | лидов {int(b.get('total') or 0)} | ликвид {int(b.get('liquid') or 0)} | NA {int(b.get('na') or 0)}")
    return chr(10).join(lines).rstrip()


async def _handle_quality_command(args: str, *, user_id: int = 0) -> str:
    parts = str(args or "").split()
    action = (parts[0].lower() if parts else "all")
    if action in ("help", "?", "h"):
        return "\n".join([
            "📈 Качество и дисциплина",
            "",
            "Команды:",
            "/quality all - общий отчёт за сегодня",
            "/quality response - время ответа менеджеров",
            "/quality sla - просроченные SLA 15+",
            "/quality ranking - рейтинг менеджеров",
            "/quality losses - потери лидов",
            "",
            "Можно добавить дату:",
            "/quality all yesterday",
            "/quality response 04.05.26",
        ]).rstrip()
    date_token = parts[1] if len(parts) >= 2 else ""
    if action in ("all", "today", "сегодня", "summary"):
        if action in ("today", "сегодня"):
            date_token = "today"
        return await _quality_all_text(date_token)
    if action in ("response", "time", "ответ", "время"):
        return await _quality_response_text(date_token)
    if action in ("sla", "late", "просрочки"):
        return await _quality_sla_text(date_token)
    if action in ("ranking", "rank", "rating", "рейтинг"):
        return await _quality_ranking_text(date_token)
    if action in ("losses", "loss", "потери"):
        return await _quality_losses_text(date_token)
    return "Формат: /quality help"


def _funnel_quality_ratio(stats: Dict[str, Any]) -> int:
    total = int(stats.get("total") or 0)
    if total <= 0:
        return 0
    return _percent(int(stats.get("liquid") or 0), total)


def _source_name_map_from_rows(rows: List[Dict[str, Any]]) -> Dict[str, str]:
    out = {}
    for r in rows or []:
        key = _structure_key(r.get("source_key"))
        if key:
            out[key] = str(r.get("name") or key)
    return out


def _group_name_map_from_rows(rows: List[Dict[str, Any]]) -> Dict[str, str]:
    out = {}
    for r in rows or []:
        key = _structure_key(r.get("group_key"))
        if key:
            out[key] = str(r.get("name") or key)
    return out


async def _funnel_sources_text(date_token: str = "") -> str:
    d = _quality_date_from_token(date_token)
    leads = await _quality_collect_day_leads(d.isoformat())
    sources = await _source_rows()
    links = await _source_links_map()
    source_names = _source_name_map_from_rows(sources)
    by_source: Dict[str, Dict[str, Any]] = {}
    for src in sources:
        key = _structure_key(src.get("source_key"))
        if key:
            by_source[key] = _quality_bucket_empty(source_names.get(key, key))
    by_source.setdefault("_none", _quality_bucket_empty("Без источника"))
    for lead in leads:
        mk = registry_normalize_manager_key(lead.get("manager_key") or "")
        sk = links.get(mk) or "_none"
        by_source.setdefault(sk, _quality_bucket_empty(source_names.get(sk, sk)))
        _quality_bucket_add(by_source[sk], lead)
    lines = [f"📦 Качество источников | {_quality_date_header(d)}", ""]
    visible = [(k, b) for k, b in by_source.items() if int(b.get("total") or 0) > 0 or k != "_none"]
    if not visible:
        return chr(10).join(lines + ["Источники ещё не созданы или лидов за период нет."]).rstrip()
    visible.sort(key=lambda x: (-int(x[1].get("total") or 0), str(x[1].get("label") or x[0])))
    for key, b in visible:
        if key == "_none" and int(b.get("total") or 0) <= 0:
            continue
        lines.append(str(b.get("label") or key))
        lines.append(f"Лидов: {int(b.get('total') or 0)}")
        lines.append(f"Новые: {int(b.get('new') or 0)} | Дуб��и: {int(b.get('duplicates') or 0)}")
        lines.append(f"Анкету дали: {int(b.get('profile_done') or 0)}")
        lines.append(f"Ликвид: {int(b.get('liquid') or 0)} | Неликвид: {int(b.get('nonliquid') or 0)} | NA: {int(b.get('na') or 0)} | TRASH: {int(b.get('trash') or 0)}")
        lines.append(f"Качество источника: {_funnel_quality_ratio(b)}%")
        lines.append("")
    return chr(10).join(lines).rstrip()


async def _funnel_groups_text(date_token: str = "") -> str:
    d = _quality_date_from_token(date_token)
    leads = await _quality_collect_day_leads(d.isoformat())
    groups = await _group_rows()
    group_names = _group_name_map_from_rows(groups)
    by_group: Dict[str, Dict[str, Any]] = {}
    for grp in groups:
        key = _structure_key(grp.get("group_key"))
        members = set(await _group_members(key))
        b = _quality_bucket_empty(group_names.get(key, key))
        for lead in leads:
            if registry_normalize_manager_key(lead.get("manager_key") or "") in members:
                _quality_bucket_add(b, lead)
        by_group[key] = b
    lines = [f"👥 Качество групп | {_quality_date_header(d)}", ""]
    if not by_group:
        return chr(10).join(lines + ["Группы ещё не созданы."]).rstrip()
    for key, b in sorted(by_group.items(), key=lambda x: (-int(x[1].get("total") or 0), str(x[1].get("label") or x[0]))):
        lines.append(str(b.get("label") or key))
        lines.append(f"Лидов: {int(b.get('total') or 0)}")
        lines.append(f"Ликвид: {int(b.get('liquid') or 0)} | NA: {int(b.get('na') or 0)} | TRASH: {int(b.get('trash') or 0)}")
        lines.append(f"Ответ до 15 мин: {int(b.get('sla_ok') or 0)}")
        lines.append("")
    return chr(10).join(lines).rstrip()


async def _funnel_links_text(date_token: str = "") -> str:
    d = _quality_date_from_token(date_token)
    leads = await _quality_collect_day_leads(d.isoformat())
    labels = await _manager_label_map()
    sources = await _source_rows()
    source_names = _source_name_map_from_rows(sources)
    links = await _source_links_map()
    by_pair: Dict[Tuple[str, str], Dict[str, Any]] = {}
    for lead in leads:
        mk = registry_normalize_manager_key(lead.get("manager_key") or "")
        sk = links.get(mk) or "_none"
        label = f"{source_names.get(sk, 'Без источника')} -> {labels.get(mk, mk)}"
        key = (sk, mk)
        by_pair.setdefault(key, _quality_bucket_empty(label))
        _quality_bucket_add(by_pair[key], lead)
    lines = [f"🔗 Связки источник + менеджер | {_quality_date_header(d)}", ""]
    if not by_pair:
        return chr(10).join(lines + ["Лидов за период пока нет."]).rstrip()
    for (_sk, _mk), b in sorted(by_pair.items(), key=lambda x: (-int(x[1].get("total") or 0), str(x[1].get("label") or "")))[:30]:
        lines.append(str(b.get("label") or ""))
        lines.append(f"Лидов: {int(b.get('total') or 0)} | Ликвид: {int(b.get('liquid') or 0)} | NA: {int(b.get('na') or 0)} | Ответ до 15 мин: {int(b.get('sla_ok') or 0)}")
        lines.append("")
    return chr(10).join(lines).rstrip()


async def _funnel_best_text(date_token: str = "") -> str:
    d = _quality_date_from_token(date_token)
    leads = await _quality_collect_day_leads(d.isoformat())
    sources = await _source_rows()
    source_names = _source_name_map_from_rows(sources)
    links = await _source_links_map()
    by_source: Dict[str, Dict[str, Any]] = {}
    for lead in leads:
        mk = registry_normalize_manager_key(lead.get("manager_key") or "")
        sk = links.get(mk) or "_none"
        by_source.setdefault(sk, _quality_bucket_empty(source_names.get(sk, "Без источника")))
        _quality_bucket_add(by_source[sk], lead)
    ranked = [( _funnel_quality_ratio(b), key, b ) for key, b in by_source.items() if int(b.get("total") or 0) > 0]
    ranked.sort(key=lambda x: (-x[0], -int(x[2].get("liquid") or 0), str(x[1])))
    lines = [f"🏆 Лучшие источники | {_quality_date_header(d)}", ""]
    if not ranked:
        return chr(10).join(lines + ["Лидов за период пока нет."]).rstrip()
    for idx, (ratio, key, b) in enumerate(ranked[:15], 1):
        lines.append(f"{idx}. {b.get('label') or key}")
        lines.append(f"Качество: {ratio}% | Лидов: {int(b.get('total') or 0)} | Ликвид: {int(b.get('liquid') or 0)} | NA: {int(b.get('na') or 0)}")
        lines.append("")
    return chr(10).join(lines).rstrip()


async def _handle_funnel_command(args: str, *, user_id: int = 0) -> str:
    parts = str(args or "").split()
    action = (parts[0].lower() if parts else "all")
    if action in ("help", "?", "h"):
        return "\n".join([
            "📊 Воронка и качество источников",
            "",
            "Команды:",
            "/funnel all - источники + потери за сегодня",
            "/funnel sources - качество источников",
            "/funnel groups - качество групп",
            "/funnel links - связки источник + менеджер",
            "/funnel losses - где теряем лидов",
            "/funnel best - лучшие источники",
            "",
            "Можно добавить дату:",
            "/funnel sources yesterday",
            "/funnel links 04.05.26",
        ]).rstrip()
    date_token = parts[1] if len(parts) >= 2 else ""
    if action in ("all", "summary"):
        return (await _funnel_sources_text(date_token)) + "\n\n" + (await _quality_losses_text(date_token))
    if action in ("sources", "source", "источники"):
        return await _funnel_sources_text(date_token)
    if action in ("groups", "group", "группы"):
        return await _funnel_groups_text(date_token)
    if action in ("links", "pairs", "связки"):
        return await _funnel_links_text(date_token)
    if action in ("losses", "loss", "потери"):
        return await _quality_losses_text(date_token)
    if action in ("best", "top", "лучшие"):
        return await _funnel_best_text(date_token)
    return "Формат: /funnel help"



# -------------------- Partner / Buyer access control --------------------
async def _ensure_partner_tables() -> None:
    parent = os.path.dirname(TPILOT_DB_PATH)
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute("PRAGMA journal_mode=WAL;")
        await db.execute("""
            CREATE TABLE IF NOT EXISTS partner_buyers(
                user_id INTEGER PRIMARY KEY,
                username TEXT DEFAULT '',
                first_name TEXT DEFAULT '',
                last_name TEXT DEFAULT '',
                source_key TEXT DEFAULT '',
                is_enabled INTEGER NOT NULL DEFAULT 1,
                can_view_stats INTEGER NOT NULL DEFAULT 1,
                can_live_leads INTEGER NOT NULL DEFAULT 0,
                can_view_contacts INTEGER NOT NULL DEFAULT 0,
                can_excel INTEGER NOT NULL DEFAULT 0,
                stat_format TEXT NOT NULL DEFAULT 'pro',
                live_enabled_at TEXT DEFAULT '',
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT '',
                last_seen_at TEXT DEFAULT ''
            );
        """)
        try:
            cols = await _table_columns(db, "partner_buyers")
            if "stat_format" not in cols:
                await db.execute("ALTER TABLE partner_buyers ADD COLUMN stat_format TEXT NOT NULL DEFAULT 'pro'")
        except Exception:
            pass
        await db.execute("""
            CREATE TABLE IF NOT EXISTS partner_lead_events(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                event_key TEXT UNIQUE NOT NULL DEFAULT '',
                source_key TEXT NOT NULL DEFAULT '',
                manager_key TEXT NOT NULL DEFAULT '',
                manager_display_name TEXT DEFAULT '',
                manager_username TEXT DEFAULT '',
                lead_id INTEGER NOT NULL DEFAULT 0,
                chat_id INTEGER NOT NULL DEFAULT 0,
                username TEXT DEFAULT '',
                full_name TEXT DEFAULT '',
                phone TEXT DEFAULT '',
                first_seen_utc TEXT NOT NULL DEFAULT '',
                duplicate INTEGER NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        try:
            await db.execute("CREATE INDEX IF NOT EXISTS partner_lead_events_source_idx ON partner_lead_events(source_key, id);")
            await db.execute("CREATE INDEX IF NOT EXISTS partner_lead_events_created_idx ON partner_lead_events(created_at);")
            # perf (patch perf_idx): chat_id was scanned (no index) on a table that
            # grows with every lead event. Verified against PRAGMA index_list.
            await db.execute("CREATE INDEX IF NOT EXISTS partner_lead_events_chat_idx ON partner_lead_events(chat_id);")
        except Exception:
            pass
        await db.execute("""
            CREATE TABLE IF NOT EXISTS partner_access_requests(
                user_id INTEGER PRIMARY KEY,
                username TEXT DEFAULT '',
                first_name TEXT DEFAULT '',
                last_name TEXT DEFAULT '',
                status TEXT NOT NULL DEFAULT 'new',
                requested_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        try:
            await db.execute("CREATE INDEX IF NOT EXISTS partner_buyers_source_idx ON partner_buyers(source_key, is_enabled);")
        except Exception:
            pass
        try:
            await db.execute("CREATE INDEX IF NOT EXISTS partner_requests_status_idx ON partner_access_requests(status, requested_at);")
        except Exception:
            pass
        await db.commit()


def _partner_user_label(row: Dict[str, Any]) -> str:
    username = str((row or {}).get("username") or "").strip()
    first = str((row or {}).get("first_name") or "").strip()
    last = str((row or {}).get("last_name") or "").strip()
    name = " ".join([x for x in (first, last) if x]).strip()
    uid = str((row or {}).get("user_id") or "").strip()
    if username:
        return f"@{username.lstrip('@')}" + (f" | {name}" if name else "")
    if name:
        return f"{name} | ID {uid}"
    return f"ID {uid}"


async def _partner_source_name_map() -> Dict[str, str]:
    try:
        rows = await _source_rows()
    except Exception:
        rows = []
    out: Dict[str, str] = {}
    for r in rows or []:
        key = _structure_key(r.get("source_key") or "")
        if key:
            out[key] = str(r.get("name") or key)
    return out


async def _partner_get_buyer(user_id: int) -> Dict[str, Any]:
    await _ensure_partner_tables()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM partner_buyers WHERE user_id=?", (int(user_id),))
        row = await cur.fetchone()
        return dict(row) if row else {}


async def _partner_list_buyers() -> List[Dict[str, Any]]:
    await _ensure_partner_tables()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM partner_buyers ORDER BY is_enabled DESC, updated_at DESC, user_id ASC")
        return [dict(r) for r in await cur.fetchall()]


async def _partner_list_requests(status: str = "new") -> List[Dict[str, Any]]:
    await _ensure_partner_tables()
    status = str(status or "new").strip().lower()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM partner_access_requests WHERE status=? ORDER BY requested_at ASC", (status,))
        return [dict(r) for r in await cur.fetchall()]


async def _partner_info_text(user_id: int) -> str:
    await _ensure_partner_tables()
    row = await _partner_get_buyer(int(user_id))
    source_names = await _partner_source_name_map()
    if not row:
        return f"Байер не найден: {int(user_id)}"
    sk = _structure_key(row.get("source_key") or "")
    return "\n".join([
        "🤝 Байер",
        "",
        f"Пользователь: {_partner_user_label(row)}",
        f"user_id: {int(row.get('user_id') or 0)}",
        f"Источник: {source_names.get(sk, sk or 'не задан')}",
        f"Доступ: {'включён' if int(row.get('is_enabled') or 0) == 1 else 'выключен'}",
        f"Статистика: {'да' if int(row.get('can_view_stats') or 0) == 1 else 'нет'}",
        f"Уведомления о лидах: {'да' if int(row.get('can_live_leads') or 0) == 1 else 'нет'}",
        f"Данные лида: {'да' if int(row.get('can_view_contacts') or 0) == 1 else 'нет'}",
        f"Excel: {'да' if int(row.get('can_excel') or 0) == 1 else 'нет'}",
        f"Формат статистики: {str(row.get('stat_format') or 'pro').upper()}",
    ]).rstrip()


async def _handle_partner_command(args: str, *, user_id: int = 0) -> str:
    await _ensure_partner_tables()
    raw = str(args or "").strip()
    parts = raw.split(maxsplit=3)
    action = (parts[0].lower() if parts else "help")
    now = _now_utc_iso()

    if action in ("help", "", "?"):
        return "\n".join([
            "🤝 Байеры и доступы",
            "",
            "Байер пишет Partner Stat Bot команду /start. После этого заявка появляется в этом разделе.",
            "У каждого байера строго один источник. Байер видит только статистику и лиды своего источника.",
            "",
            "Команды:",
            "/partner requests - новые заявки",
            "/partner list - список байеров",
            "/partner info <user_id> - карточка байера",
            "/partner approve <user_id> <source_key> - выдать доступ к источнику",
            "/partner reject <user_id> - отклонить заявку",
            "/partner source <user_id> <source_key> - сменить источник",
            "/partner live on <user_id> - включить уведомления о новых лидах",
            "/partner live off <user_id> - выключить уведомления",
            "/partner contacts on <user_id> - показывать chat_id, username, имя, телефон",
            "/partner contacts off <user_id> - скрывать данные лида",
            "/partner excel on <user_id> - разрешить Excel",
            "/partner excel off <user_id> - запретить Excel",
            "/partner format light|pro|both <user_id> - выбрать формат статистики",
            "/partner enable <user_id> - включить доступ",
            "/partner disable <user_id> - выключить доступ",
            "/partner delete <user_id> confirm - удалить байера",
        ]).rstrip()

    if action in ("requests", "request", "заявки"):
        rows = await _partner_list_requests("new")
        if not rows:
            return "🤝 Заявок от байеров пока нет."
        lines = ["📥 Новые заявки байеров", ""]
        for r in rows:
            lines.append(f"{_partner_user_label(r)}")
            lines.append(f"user_id: {int(r.get('user_id') or 0)}")
            lines.append(f"Запрошено: {str(r.get('requested_at') or '_')}")
            lines.append("")
        lines.append("Чтобы выдать доступ: /partner approve <user_id> <source_key>")
        return chr(10).join(lines).rstrip()

    if action in ("list", "all", "список"):
        rows = await _partner_list_buyers()
        if not rows:
            return "🤝 Байеры ещё не добавлены."
        source_names = await _partner_source_name_map()
        lines = ["🤝 Байеры и доступы", ""]
        for r in rows:
            sk = _structure_key(r.get("source_key") or "")
            icon = "🟢" if int(r.get("is_enabled") or 0) == 1 else "⚪"
            rights = []
            if int(r.get("can_live_leads") or 0) == 1:
                rights.append("лиды")
            if int(r.get("can_view_contacts") or 0) == 1:
                rights.append("данные")
            if int(r.get("can_excel") or 0) == 1:
                rights.append("Excel")
            lines.append(f"{icon} {_partner_user_label(r)}")
            lines.append(f"Источник: {source_names.get(sk, sk or 'не задан')}")
            lines.append("Права: " + (", ".join(rights) if rights else "только статистика"))
            lines.append(f"ID: {int(r.get('user_id') or 0)}")
            lines.append("")
        return chr(10).join(lines).rstrip()

    if action == "info":
        if len(parts) < 2:
            return "Формат: /partner info <user_id>"
        try:
            return await _partner_info_text(int(parts[1]))
        except Exception:
            return "user_id должен быть числом."

    if action == "approve":
        if len(parts) < 3:
            return "Формат: /partner approve <user_id> <source_key>"
        try:
            buyer_id = int(parts[1])
        except Exception:
            return "user_id должен быть числом."
        source_key = _structure_key(parts[2])
        src = await _source_get(source_key)
        if not src:
            return f"Источник не найден: {source_key}. Сначала создайте источник в разделе 📦 Источники трафика."
        req = {}
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute("SELECT * FROM partner_access_requests WHERE user_id=?", (buyer_id,))
            row = await cur.fetchone()
            req = dict(row) if row else {}
            await db.execute(
                """
                INSERT INTO partner_buyers(user_id, username, first_name, last_name, source_key, is_enabled, can_view_stats, can_live_leads, can_view_contacts, can_excel, stat_format, created_at, updated_at)
                VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)
                ON CONFLICT(user_id) DO UPDATE SET
                    username=excluded.username,
                    first_name=excluded.first_name,
                    last_name=excluded.last_name,
                    source_key=excluded.source_key,
                    is_enabled=1,
                    can_view_stats=1,
                    stat_format=CASE WHEN COALESCE(partner_buyers.stat_format,'')='' THEN excluded.stat_format ELSE partner_buyers.stat_format END,
                    updated_at=excluded.updated_at
                """,
                (
                    buyer_id,
                    str(req.get("username") or ""),
                    str(req.get("first_name") or ""),
                    str(req.get("last_name") or ""),
                    source_key,
                    1, 1, 0, 0, 0, 'pro',
                    now, now,
                ),
            )
            await db.execute("UPDATE partner_access_requests SET status='approved', updated_at=? WHERE user_id=?", (now, buyer_id))
            await db.commit()
        return f"✅ Доступ выдан\nБайер: {buyer_id}\nИсточник: {src.get('name') or source_key}\n\nПо умолчанию доступна только статистика. Уведомления, данные лида и Excel включаются отдельно."

    if action == "reject":
        if len(parts) < 2:
            return "Формат: /partner reject <user_id>"
        try:
            buyer_id = int(parts[1])
        except Exception:
            return "user_id должен быть числом."
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute("UPDATE partner_access_requests SET status='rejected', updated_at=? WHERE user_id=?", (now, buyer_id))
            await db.commit()
        return f"🚫 Заявка отклонена: {buyer_id}"

    if action == "source":
        if len(parts) < 3:
            return "Формат: /partner source <user_id> <source_key>"
        try:
            buyer_id = int(parts[1])
        except Exception:
            return "user_id должен быть числом."
        source_key = _structure_key(parts[2])
        src = await _source_get(source_key)
        if not src:
            return f"Источник не найден: {source_key}"
        if not await _partner_get_buyer(buyer_id):
            return f"Байер не найден: {buyer_id}"
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute("UPDATE partner_buyers SET source_key=?, updated_at=? WHERE user_id=?", (source_key, now, buyer_id))
            await db.commit()
        return f"✅ Источник байера обновлён\nБайер: {buyer_id}\nИсточник: {src.get('name') or source_key}"

    if action in ("live", "contacts", "excel", "stats", "screenshots", "duplicates"):
        if len(parts) < 3:
            return f"Формат: /partner {action} on|off <user_id>"
        mode = str(parts[1]).lower()
        try:
            buyer_id = int(parts[2])
        except Exception:
            return "user_id должен быть числом."
        if mode not in ("on", "off"):
            return f"Формат: /partner {action} on|off <user_id>"
        col_map = {
            "live": "can_live_leads",
            "contacts": "can_view_contacts",
            "excel": "can_excel",
            "stats": "can_view_stats",
            "screenshots": "can_view_screenshots",
            "duplicates": "show_duplicates",
        }
        col = col_map[action]
        if not await _partner_get_buyer(buyer_id):
            return f"Байер не найден: {buyer_id}"
        value = 1 if mode == "on" else 0
        extra_sql = ", live_enabled_at=?" if (action == "live" and value == 1) else ""
        params: Tuple[Any, ...]
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            if extra_sql:
                await db.execute(f"UPDATE partner_buyers SET {col}=?, updated_at=?{extra_sql} WHERE user_id=?", (value, now, now, buyer_id))
            else:
                await db.execute(f"UPDATE partner_buyers SET {col}=?, updated_at=? WHERE user_id=?", (value, now, buyer_id))
            await db.commit()
        names = {"live": "уведомления о лидах", "contacts": "данные лида", "excel": "Excel", "stats": "статистика", "screenshots": "скрины", "duplicates": "показ дублей"}
        return f"✅ {names[action]}: {'включено' if value else 'выключено'}\nБайер: {buyer_id}"

    if action in ("format", "stats_format", "statformat"):
        if len(parts) < 3:
            return "Формат: /partner format light|pro|both <user_id>"
        mode = str(parts[1]).strip().lower()
        aliases = {"лайт": "light", "легкий": "light", "про": "pro", "оба": "both", "all": "both", "lightpro": "both"}
        mode = aliases.get(mode, mode)
        if mode not in ("light", "pro", "both"):
            return "Формат статистики должен быть: light, pro или both."
        try:
            buyer_id = int(parts[2])
        except Exception:
            return "user_id должен быть числом."
        if not await _partner_get_buyer(buyer_id):
            return f"Байер не найден: {buyer_id}"
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute("UPDATE partner_buyers SET stat_format=?, updated_at=? WHERE user_id=?", (mode, now, buyer_id))
            await db.commit()
        labels = {"light": "LIGHT", "pro": "PRO", "both": "LIGHT + PRO"}
        return f"✅ Формат статистики: {labels[mode]}\nБайер: {buyer_id}"

    if action in ("enable", "disable"):
        if len(parts) < 2:
            return f"Формат: /partner {action} <user_id>"
        try:
            buyer_id = int(parts[1])
        except Exception:
            return "user_id должен быть числом."
        if not await _partner_get_buyer(buyer_id):
            return f"Байер не найден: {buyer_id}"
        value = 1 if action == "enable" else 0
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute("UPDATE partner_buyers SET is_enabled=?, updated_at=? WHERE user_id=?", (value, now, buyer_id))
            await db.commit()
        return f"✅ Доступ {'включён' if value else 'выключен'}\nБайер: {buyer_id}"

    if action == "delete":
        if len(parts) < 3 or str(parts[2]).lower() != "confirm":
            return "Опасное действие. Формат: /partner delete <user_id> confirm"
        try:
            buyer_id = int(parts[1])
        except Exception:
            return "user_id должен быть числом."
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute("DELETE FROM partner_buyers WHERE user_id=?", (buyer_id,))
            await db.execute("UPDATE partner_access_requests SET status='deleted', updated_at=? WHERE user_id=?", (now, buyer_id))
            await db.commit()
        return f"🗑 Байер удалён из доступов: {buyer_id}"

    return "Формат: /partner help"
