# -------------------- PanelBot manager/proxy wizard commands --------------------
async def _panel_manager_add_command(args: str, *, requested_by: int = 0) -> str:
    key_raw = str(args or "").strip()
    ok, err, key = validate_manager_key(key_raw)
    if not ok:
        return err or "Ключ менеджера указан неверно."
    if await _manager_exists(key):
        return f"Менеджер уже существует: {key}"
    paths = ensure_manager_dirs(str(BASE_DIR), key)
    await manager_add(
        manager_key=key,
        display_name=key,
        phone="",
        status="new",
        session_path=paths["session_path"],
        db_path=paths["db_path"],
        workdir=paths["root"],
        log_path=paths["log_path"],
        is_enabled=1,
        owner_user_id=int(requested_by or 0) or None,
    )
    expires_at = _future_iso(MANAGER_ONBOARD_TIMEOUT_SEC)
    await manager_save_onboarding(
        int(requested_by or 0),
        manager_key=key,
        step="await_phone",
        phone="",
        phone_code_hash="",
        tmp_session_path=paths["session_path"],
        expires_at=expires_at,
        next_code_allowed_at="",
        last_code_sent_at="",
        last_send_error="",
    )
    _manager_runtime_onboarding_set(
        int(requested_by or 0),
        manager_key=key,
        step="await_phone",
        phone="",
        phone_code_hash="",
        tmp_session_path=paths["session_path"],
        expires_at=expires_at,
        next_code_allowed_at="",
        last_code_sent_at="",
        last_send_error="",
    )
    return "\n".join([
        f"✅ Менеджер создан: {key}",
        "Теперь введите номер телефона менеджера одним сообщением.",
        "Пример +79991234567",
    ])


async def _panel_manager_onboarding(int_user_id: int) -> Tuple[Optional[dict], str]:
    user_id = int(int_user_id or 0)
    await manager_clear_expired_onboarding()
    onboarding = _manager_merge_onboarding_runtime(user_id, await manager_get_onboarding(user_id))
    if not onboarding:
        return None, "Нет активного добавления менеджера. Сначала нажмите Добавить менеджера."
    if str(onboarding.get("expires_at") or "") and str(onboarding.get("expires_at")) < _now_utc_iso():
        key_exp = registry_normalize_manager_key(onboarding.get("manager_key") or "")
        _manager_runtime_onboarding_clear(user_id)
        await manager_delete_onboarding(user_id)
        return None, f"Время добавления истекло. Начните заново для {key_exp or 'менеджера'}."
    return onboarding, ""


async def _panel_manager_phone_command(args: str, *, requested_by: int = 0) -> str:
    phone = str(args or "").strip()
    if not phone:
        return "Введите номер телефона менеджера. Пример +79991234567"
    onboarding, err = await _panel_manager_onboarding(int(requested_by or 0))
    if not onboarding:
        return err
    manager_key = registry_normalize_manager_key(onboarding.get("manager_key") or "")
    paths = _manager_runtime_paths_for_key(manager_key)
    next_code_allowed_at = str(onboarding.get("next_code_allowed_at") or "")
    if next_code_allowed_at and next_code_allowed_at > _now_utc_iso():
        return _manager_phone_wait_message(onboarding, manager_key)

    # Release the manager's .session from any running process before opening an onboarding
    # client on it (a second client on the same SQLite session can lock/collide).
    stop_ok, stop_err = await _onboarding_stop_running_for_key(manager_key)
    if not stop_ok:
        return stop_err

    temp_client = None
    _, _, api_profile_name = _api_profile_for("onboarding")
    _manager_auth_audit_log(
        "send_code_start", manager_key,
        phone_masked=mask_phone(phone),
        api_profile=api_profile_name,
    )
    try:
        temp_client = await _build_manager_session_client(manager_key, paths["session_path"])
        await temp_client.connect()
        sent = await temp_client.send_code_request(phone)
        cooldown_sec = MANAGER_PHONE_COOLDOWN_SEC
        phone_code_hash = str(getattr(sent, "phone_code_hash", "") or "")
        sent_type_cls = _sent_code_class_name(getattr(sent, "type", None))
        sent_next_type_cls = _sent_code_class_name(getattr(sent, "next_type", None))

        if not phone_code_hash:
            # Telegram returned no phone_code_hash - treat this as a failure, not success,
            # so the operator isn't told "code sent" when sign_in would be impossible.
            expires_at = _future_iso(MANAGER_ONBOARD_TIMEOUT_SEC)
            await manager_set_fields(manager_key, status="error", last_error="empty_phone_code_hash")
            await manager_save_onboarding(
                int(requested_by or 0),
                manager_key=manager_key,
                step="await_phone",
                phone=phone,
                phone_code_hash="",
                tmp_session_path=paths["session_path"],
                expires_at=expires_at,
                next_code_allowed_at="",
                last_send_error="empty_phone_code_hash",
            )
            _manager_runtime_onboarding_set(
                int(requested_by or 0),
                manager_key=manager_key,
                step="await_phone",
                phone=phone,
                phone_code_hash="",
                tmp_session_path=paths["session_path"],
                expires_at=expires_at,
                next_code_allowed_at="",
                last_send_error="empty_phone_code_hash",
            )
            _manager_auth_audit_log(
                "send_code_finish", manager_key,
                phone_masked=mask_phone(phone),
                api_profile=api_profile_name,
                ok=0,
                sent_type=sent_type_cls or "_",
                sent_next_type=sent_next_type_cls or "_",
                hash_present=0,
                error_class="empty_phone_code_hash",
            )
            return "❌ Telegram не вернул код подтверждения (phone_code_hash пуст). Это не успех — нажмите «Повторить код» или введите номер ещё раз."

        expires_at = _future_iso_max(MANAGER_ONBOARD_TIMEOUT_SEC, cooldown_sec + 300)
        next_code_allowed_at = _future_iso(cooldown_sec)
        last_code_sent_at = _now_utc_iso()
        await manager_set_fields(
            manager_key,
            phone=phone,
            status="auth_pending",
            is_enabled=1,
            manual_stopped=0,
            owner_user_id=int(requested_by or 0) or None,
            session_path=paths["session_path"],
            db_path=paths["db_path"],
            workdir=paths["root"],
            log_path=paths["log_path"],
            last_error="",
        )
        await manager_save_onboarding(
            int(requested_by or 0),
            manager_key=manager_key,
            step="await_code",
            phone=phone,
            phone_code_hash=phone_code_hash,
            tmp_session_path=paths["session_path"],
            expires_at=expires_at,
            next_code_allowed_at=next_code_allowed_at,
            last_code_sent_at=last_code_sent_at,
            last_send_error="",
        )
        _manager_runtime_onboarding_set(
            int(requested_by or 0),
            manager_key=manager_key,
            step="await_code",
            phone=phone,
            phone_code_hash=phone_code_hash,
            tmp_session_path=paths["session_path"],
            expires_at=expires_at,
            next_code_allowed_at=next_code_allowed_at,
            last_code_sent_at=last_code_sent_at,
            last_send_error="",
        )
        _manager_auth_audit_log(
            "send_code_finish", manager_key,
            phone_masked=mask_phone(phone),
            api_profile=api_profile_name,
            ok=1,
            sent_type=sent_type_cls or "_",
            sent_next_type=sent_next_type_cls or "_",
            hash_present=1,
            expires_at=expires_at,
            next_code_allowed_at=next_code_allowed_at,
        )
        channel_ru = _sent_code_channel_ru(sent)
        next_channel_ru = _sent_code_next_channel_ru(sent)
        lines = [
            "✅ Код отправлен. Теперь введите код Telegram одним сообщением.",
            f"Куда Telegram отправил код: {channel_ru}",
            f"Код действителен до: {_iso_to_local_hhmm(expires_at)}",
            f"Повторная отправка после: {_iso_to_local_hhmm(next_code_allowed_at)}",
        ]
        if not sent_type_cls:
            lines.append("⚠️ Telegram не указал способ доставки кода. Если код не пришёл, проверьте уже залогиненные устройства этого номера.")
        elif sent_type_cls == "SentCodeTypeApp":
            lines.append("Это значит код придёт в само приложение Telegram на уже залогиненном устройстве этого номера, а не по SMS.")
        if next_channel_ru:
            lines.append(f"Если код не придёт, следующий способ доставки у Telegram: {next_channel_ru}.")
        return "\n".join(lines)
    except Exception as e:
        wait_sec = _manager_extract_wait_seconds(e, MANAGER_PHONE_COOLDOWN_SEC) if _manager_is_rate_limit_error(e) else 0
        if wait_sec > 0:
            expires_at = _future_iso_max(MANAGER_ONBOARD_TIMEOUT_SEC, wait_sec + 300)
            next_code_allowed_at = _future_iso(wait_sec)
            await manager_set_fields(manager_key, status="auth_pending", last_error=repr(e))
            await manager_save_onboarding(
                int(requested_by or 0),
                manager_key=manager_key,
                step="await_phone",
                phone=phone,
                phone_code_hash="",
                tmp_session_path=paths["session_path"],
                expires_at=expires_at,
                next_code_allowed_at=next_code_allowed_at,
                last_send_error=repr(e),
            )
            _manager_runtime_onboarding_set(
                int(requested_by or 0),
                manager_key=manager_key,
                step="await_phone",
                phone=phone,
                phone_code_hash="",
                tmp_session_path=paths["session_path"],
                expires_at=expires_at,
                next_code_allowed_at=next_code_allowed_at,
                last_send_error=repr(e),
            )
            _manager_auth_audit_log(
                "send_code_finish", manager_key,
                phone_masked=mask_phone(phone),
                api_profile=api_profile_name,
                ok=0,
                error_class=e.__class__.__name__,
                rate_limited=1,
                next_code_allowed_at=next_code_allowed_at,
            )
            return f"Telegram временно ограничил запросы кода. Повторно можно после {_iso_to_local_hhmm(next_code_allowed_at)}."
        expires_at = _future_iso(MANAGER_ONBOARD_TIMEOUT_SEC)
        await manager_set_fields(manager_key, status="error", last_error=repr(e))
        await manager_save_onboarding(
            int(requested_by or 0),
            manager_key=manager_key,
            step="await_phone",
            phone=phone,
            phone_code_hash="",
            tmp_session_path=paths["session_path"],
            expires_at=expires_at,
            last_send_error=repr(e),
        )
        _manager_runtime_onboarding_set(
            int(requested_by or 0),
            manager_key=manager_key,
            step="await_phone",
            phone=phone,
            phone_code_hash="",
            tmp_session_path=paths["session_path"],
            expires_at=expires_at,
            next_code_allowed_at="",
            last_send_error=repr(e),
        )
        _manager_auth_audit_log(
            "send_code_finish", manager_key,
            phone_masked=mask_phone(phone),
            api_profile=api_profile_name,
            ok=0,
            error_class=e.__class__.__name__,
            error_repr=repr(e)[:300],
        )
        return _map_send_code_error(e)
    finally:
        if temp_client is not None:
            try:
                await temp_client.disconnect()
            except Exception:
                pass


async def _panel_manager_code_command(args: str, *, requested_by: int = 0) -> str:
    code = re.sub(r"\D+", "", str(args or "").strip())
    if not code:
        return "Введите код Telegram цифрами."
    onboarding, err = await _panel_manager_onboarding(int(requested_by or 0))
    if not onboarding:
        return err
    manager_key = registry_normalize_manager_key(onboarding.get("manager_key") or "")
    paths = _manager_runtime_paths_for_key(manager_key)
    phone_for_code = str(onboarding.get("phone") or "").strip()
    phone_code_hash = str(onboarding.get("phone_code_hash") or "").strip()
    runtime_onboarding = _manager_runtime_onboarding_get(int(requested_by or 0))
    if not phone_code_hash and runtime_onboarding.get("phone_code_hash"):
        phone_code_hash = str(runtime_onboarding.get("phone_code_hash") or "").strip()
    if not phone_for_code and runtime_onboarding.get("phone"):
        phone_for_code = str(runtime_onboarding.get("phone") or "").strip()
    if not phone_for_code or not phone_code_hash:
        expires_at = _future_iso(MANAGER_ONBOARD_TIMEOUT_SEC)
        await manager_save_onboarding(
            int(requested_by or 0),
            manager_key=manager_key,
            step="await_phone",
            phone=phone_for_code,
            phone_code_hash="",
            tmp_session_path=paths["session_path"],
            expires_at=expires_at,
            next_code_allowed_at="",
            last_send_error="missing_phone_or_hash",
        )
        _manager_runtime_onboarding_set(
            int(requested_by or 0),
            manager_key=manager_key,
            step="await_phone",
            phone=phone_for_code,
            phone_code_hash="",
            tmp_session_path=paths["session_path"],
            expires_at=expires_at,
            next_code_allowed_at="",
            last_send_error="missing_phone_or_hash",
        )
        return "Не найден активный запрос кода. Введите номер телефона ещё раз."

    temp_client = None
    try:
        temp_client = await _build_manager_session_client(manager_key, paths["session_path"])
        await temp_client.connect()
        await temp_client.sign_in(phone=phone_for_code, code=code, phone_code_hash=phone_code_hash)
        me = await temp_client.get_me()
        try:
            await temp_client.disconnect()
        except Exception:
            pass
        _manager_auth_audit_log("sign_in_code", manager_key, phone_masked=mask_phone(phone_for_code), ok=1)
        return await _manager_finalize_login(int(requested_by or 0), manager_key, phone_for_code, me)
    except SessionPasswordNeededError:
        expires_at = _future_iso(MANAGER_ONBOARD_TIMEOUT_SEC)
        phone_keep = str(onboarding.get("phone") or phone_for_code or "")
        hash_keep = str(onboarding.get("phone_code_hash") or phone_code_hash or "")
        next_code_allowed_at = str(onboarding.get("next_code_allowed_at") or runtime_onboarding.get("next_code_allowed_at") or "")
        last_code_sent_at = str(onboarding.get("last_code_sent_at") or runtime_onboarding.get("last_code_sent_at") or "")
        await manager_save_onboarding(
            int(requested_by or 0),
            manager_key=manager_key,
            step="await_password",
            phone=phone_keep,
            phone_code_hash=hash_keep,
            tmp_session_path=paths["session_path"],
            expires_at=expires_at,
            next_code_allowed_at=next_code_allowed_at,
            last_code_sent_at=last_code_sent_at,
        )
        _manager_runtime_onboarding_set(
            int(requested_by or 0),
            manager_key=manager_key,
            step="await_password",
            phone=phone_keep,
            phone_code_hash=hash_keep,
            tmp_session_path=paths["session_path"],
            expires_at=expires_at,
            next_code_allowed_at=next_code_allowed_at,
            last_code_sent_at=last_code_sent_at,
        )
        _manager_auth_audit_log("sign_in_code", manager_key, phone_masked=mask_phone(phone_for_code), ok=0, error_class="SessionPasswordNeededError")
        return "Нужен пароль 2FA. Введите пароль одним сообщением."
    except (PhoneCodeInvalidError, PhoneCodeExpiredError) as e:
        phone_keep = str(onboarding.get("phone") or phone_for_code or "")
        expires_at = _future_iso(MANAGER_ONBOARD_TIMEOUT_SEC)
        await manager_save_onboarding(
            int(requested_by or 0),
            manager_key=manager_key,
            step="await_phone",
            phone=phone_keep,
            tmp_session_path=paths["session_path"],
            expires_at=expires_at,
            next_code_allowed_at="",
            last_send_error="phone_code_invalid",
        )
        _manager_runtime_onboarding_set(
            int(requested_by or 0),
            manager_key=manager_key,
            step="await_phone",
            phone=phone_keep,
            phone_code_hash="",
            tmp_session_path=paths["session_path"],
            expires_at=expires_at,
            next_code_allowed_at="",
            last_send_error="phone_code_invalid",
        )
        _manager_auth_audit_log("sign_in_code", manager_key, phone_masked=mask_phone(phone_for_code), ok=0, error_class=e.__class__.__name__)
        return "Код неверный или истёк. Введите номер телефона ещё раз, чтобы запросить новый код."
    except Exception as e:
        await manager_set_fields(manager_key, status="error", last_error=repr(e))
        _manager_auth_audit_log("sign_in_code", manager_key, phone_masked=mask_phone(phone_for_code), ok=0, error_class=e.__class__.__name__, error_repr=repr(e)[:300])
        return f"Ошибка входа по коду: {e!r}"
    finally:
        if temp_client is not None:
            try:
                await temp_client.disconnect()
            except Exception:
                pass


async def _panel_manager_pass_command(args: str, *, requested_by: int = 0) -> str:
    password = str(args or "").strip()
    if not password:
        return "Введите пароль 2FA одним сообщением."
    owner = int(requested_by or 0)
    qr_entry = _MANAGER_QR_SESSIONS.get(owner)
    if qr_entry and qr_entry.get("needs_2fa"):
        manager_key = str(qr_entry.get("manager_key") or "")
        qr_client = qr_entry.get("client")
        context = str(qr_entry.get("context") or "add")
        try:
            await qr_client.sign_in(password=password)
            me = await qr_client.get_me()
            phone = str(getattr(me, "phone", "") or qr_entry.get("phone") or "")
        except PasswordHashInvalidError:
            _manager_auth_audit_log("qr_2fa_error", manager_key, ok=0, error_class="PasswordHashInvalidError", context=context)
            return "Неверный пароль 2FA. Введите пароль ещё раз."
        except Exception as e:
            await _manager_qr_session_drop(owner)
            _manager_auth_audit_log("qr_2fa_error", manager_key, ok=0, error_class=e.__class__.__name__, error_repr=repr(e)[:300], context=context)
            return f"Ошибка входа по 2FA (QR): {e!r}"

        # TPILOT AUTH SAFETY 20260809 (Ф3 checkpoint fix, D-QR 2FA): context-aware
        # dispatch, symmetric to _manager_qr_wait_task's own success-path dispatch
        # above. Without this, a relogin/replace QR flow that hit
        # SessionPasswordNeededError would (before this fix) unconditionally fall
        # through to _manager_finalize_login (the ADD path) once the 2FA password
        # was accepted here -- mis-finalizing an EXISTING (relogin) or reserved-
        # but-not-yet-committed (replace) manager_key through the wrong commit
        # mechanism, bypassing _manager_relogin_commit's/_replacement_after_
        # signin's own safety checks entirely. No new commit mechanism is
        # introduced -- this reuses the exact same two existing, already-safe
        # commit functions the non-2FA success path already hands off to.
        if context == "relogin":
            await _manager_qr_session_drop(owner)
            _manager_auth_audit_log("qr_2fa_ok", manager_key, ok=1, context="relogin")
            return await _manager_relogin_commit(manager_key, owner, phone_hint=phone)

        if context == "replace":
            operation_id = str(qr_entry.get("operation_id") or "")
            result = await _replacement_after_signin(operation_id, qr_client)
            qr_entry["client"] = None  # already disconnected inside the call above
            await _manager_qr_session_drop(owner)
            ok = bool(result.get("ok"))
            _manager_auth_audit_log("qr_2fa_ok", manager_key, ok=1 if ok else 0, context="replace")
            return str(result.get("message") or ("Личность подтверждена." if ok else "Замена аккаунта не завершена."))

        # context == "add" -- ORIGINAL behavior, unchanged.
        await _manager_qr_session_drop(owner)
        _manager_auth_audit_log("qr_2fa_ok", manager_key, ok=1)
        return await _manager_finalize_login(owner, manager_key, phone, me)
    onboarding, err = await _panel_manager_onboarding(int(requested_by or 0))
    if not onboarding:
        return err
    manager_key = registry_normalize_manager_key(onboarding.get("manager_key") or "")
    paths = _manager_runtime_paths_for_key(manager_key)
    temp_client = None
    try:
        temp_client = await _build_manager_session_client(manager_key, paths["session_path"])
        await temp_client.connect()
        await temp_client.sign_in(password=password)
        me = await temp_client.get_me()
        try:
            await temp_client.disconnect()
        except Exception:
            pass
        _manager_auth_audit_log("sign_in_pass", manager_key, ok=1)
        return await _manager_finalize_login(int(requested_by or 0), manager_key, str(onboarding.get("phone") or ""), me)
    except PasswordHashInvalidError:
        _manager_auth_audit_log("sign_in_pass", manager_key, ok=0, error_class="PasswordHashInvalidError")
        return "Неверный пароль 2FA. Введите пароль ещё раз."
    except Exception as e:
        await manager_set_fields(manager_key, status="error", last_error=repr(e))
        _manager_auth_audit_log("sign_in_pass", manager_key, ok=0, error_class=e.__class__.__name__, error_repr=repr(e)[:300])
        return f"Ошибка входа по 2FA: {e!r}"
    finally:
        if temp_client is not None:
            try:
                await temp_client.disconnect()
            except Exception:
                pass


def _qr_expires_iso(qr_login_obj: Any) -> str:
    try:
        dt = qr_login_obj.expires
        if dt.tzinfo is not None:
            dt = dt.astimezone(timezone.utc).replace(tzinfo=None)
        return dt.replace(microsecond=0).isoformat()
    except Exception:
        return ""


async def _manager_qr_wait_task(owner_user_id: int, manager_key: str) -> None:
    uid = int(owner_user_id or 0)
    entry = _MANAGER_QR_SESSIONS.get(uid)
    if not entry or entry.get("manager_key") != manager_key:
        return
    qr = entry.get("qr_login")
    timeout = None
    expires_dt = entry.get("expires_at_dt")
    if expires_dt is not None:
        try:
            timeout = max(1.0, (expires_dt - datetime.now(timezone.utc)).total_seconds())
        except Exception:
            timeout = None
    try:
        me = await qr.wait(timeout=timeout)
    except SessionPasswordNeededError:
        entry["needs_2fa"] = True
        try:
            paths = _manager_runtime_paths_for_key(manager_key)
            await manager_save_onboarding(
                uid,
                manager_key=manager_key,
                step="await_password",
                phone=str(entry.get("phone") or ""),
                phone_code_hash=str(entry.get("phone_code_hash") or ""),
                tmp_session_path=paths["session_path"],
                expires_at=_future_iso(MANAGER_ONBOARD_TIMEOUT_SEC),
            )
            _manager_runtime_onboarding_set(uid, manager_key=manager_key, step="await_password")
        except Exception:
            pass
        _manager_auth_audit_log("qr_2fa", manager_key, ok=1)
        await _tpag_insert_notification(
            "🔐 Требуется пароль 2FA",
            f"QR подтверждён для {manager_key}. Просто отправьте пароль 2FA одним сообщением в этот чат.",
        )
        return
    except asyncio.TimeoutError:
        timeout_context = str(entry.get("context") or "add")
        await _manager_qr_session_drop(uid)
        _manager_qr_temp_cleanup_for_context(timeout_context, manager_key)
        _manager_auth_audit_log("qr_expired", manager_key, ok=0, context=timeout_context)
        await _tpag_insert_notification(
            "⏳ QR истёк",
            f"QR-код для {manager_key} истёк. Нажмите «Обновить QR», чтобы получить новый.",
        )
        return
    except asyncio.CancelledError:
        return
    except Exception as e:
        error_context = str(entry.get("context") or "add")
        await _manager_qr_session_drop(uid)
        _manager_qr_temp_cleanup_for_context(error_context, manager_key)
        _manager_auth_audit_log("qr_error", manager_key, ok=0, error_class=e.__class__.__name__, error_repr=repr(e)[:300], context=error_context)
        await _tpag_insert_notification(
            "⚠️ Ошибка QR-входа",
            f"Не удалось войти по QR для {manager_key}: {e.__class__.__name__}.",
        )
        return
    # Normalize a thin User from qr.wait() into a full one while the live client is still
    # connected, so finalize reliably persists id/username/first_name.
    if (not getattr(me, "id", 0)) or (getattr(me, "username", None) is None):
        client_obj = entry.get("client")
        if client_obj is not None:
            try:
                full = await client_obj.get_me()
                if full:
                    me = full
            except Exception:
                pass
    phone = str(getattr(me, "phone", "") or "")

    # TPILOT AUTH SAFETY 20260809 (Ф3, D-QR): context-aware dispatch. Default
    # ("add", or any entry that never set a context -- e.g. an in-flight QR
    # session that started before this patch) falls through unchanged to the
    # ORIGINAL add-manager finalize path below -- byte-identical to prior
    # behavior, zero risk to onboarding. "relogin"/"replace" are new branches;
    # nothing in production sets these yet (Ф4's UI is what will), so they
    # are exercised only by direct calls (selftests) until then.
    context = str(entry.get("context") or "add")

    if context == "relogin":
        # The QR client already authorized the session file sitting at
        # _manager_relogin_temp_session_path(manager_key) (never the live
        # session -- see _manager_relogin_qr_start's collision guard).
        # Disconnect it so the file is flushed/unlocked, then hand off to the
        # EXISTING, already-safe _manager_relogin_commit -- it re-verifies the
        # temp session itself, backs up the live session, atomically replaces
        # it, and rolls back on any failure. No new commit mechanism.
        await _manager_qr_session_drop(uid)
        _manager_auth_audit_log("qr_ok", manager_key, ok=1, context="relogin")
        result_text = await _manager_relogin_commit(manager_key, uid, phone_hint=phone)
        ok = result_text.startswith(_RELOGIN_COMMIT_OK_MARKER)
        await _tpag_insert_notification(
            "✅ QR: повторный вход выполнен" if ok else "⚠️ QR: повторный вход не завершён",
            result_text,
        )
        return

    if context == "replace":
        operation_id = str(entry.get("operation_id") or "")
        client_obj = entry.get("client")
        # _replacement_after_signin owns disconnecting temp_client itself (and
        # does its own fresh is_user_authorized()/get_me() + every existing
        # uniqueness/conflict guard) -- call it BEFORE _manager_qr_session_drop
        # would otherwise double-disconnect the same client.
        result = await _replacement_after_signin(operation_id, client_obj)
        entry["client"] = None  # already disconnected inside the call above
        await _manager_qr_session_drop(uid)
        ok = bool(result.get("ok"))
        _manager_auth_audit_log("qr_ok", manager_key, ok=1 if ok else 0, context="replace")
        await _tpag_insert_notification(
            "✅ QR: личность подтверждена (замена аккаунта)" if ok else "⚠️ QR: замена аккаунта не завершена",
            str(result.get("message") or ""),
        )
        return

    # context == "add" -- ORIGINAL behavior, unchanged.
    await _manager_qr_session_drop(uid)
    _manager_auth_audit_log("qr_ok", manager_key, ok=1)
    result_text = await _manager_finalize_login(uid, manager_key, phone, me)
    uname = str(getattr(me, "username", "") or "").strip()
    tg_id = int(getattr(me, "id", 0) or 0)
    account_line = f"@{uname}" if uname else f"username: не задан (id {tg_id})"
    # ONBOARDING SOURCE PICK 20260711: when finalize appended the source-pick
    # marker (manager not yet linked to a source), route this notification through
    # kind="manager_source_pick" so panel_bot.py's loop renders source buttons
    # instead of the generic back-to-panel ones. Already-linked managers keep the
    # exact original body/kind (proxy_guard) -- byte-identical to prior behavior.
    notify_body = f"{result_text}\nАккаунт: {account_line}"
    # TPILOT PREPARED ACCOUNTS PHASE 4: checked FIRST -- a prepared finalize
    # never reaches the source-pick branch inside _manager_finalize_login
    # (see is_prepared there), so the two markers are mutually exclusive,
    # but ordering this check first keeps that invariant explicit rather
    # than relied upon. Phase 6's panel notification loop is the intended
    # consumer of kind="prepared_ready"; nothing panel-side reads it yet.
    if _PREPARED_READY_MARKER in result_text:
        notify_body += f"\nmanager_key:{manager_key}"
        await _tpag_insert_notification("💾 Аккаунт подготовлен по QR", notify_body, kind="prepared_ready")
    elif _ONBOARDING_SOURCE_PICK_MARKER in result_text:
        notify_body += f"\nmanager_key:{manager_key}"
        await _tpag_insert_notification("✅ Менеджер вошёл по QR", notify_body, kind="manager_source_pick")
    else:
        await _tpag_insert_notification("✅ Менеджер вошёл по QR", notify_body)


async def _panel_manager_qr_start_command(args: str, *, requested_by: int = 0) -> str:
    owner = int(requested_by or 0)
    onboarding, err = await _panel_manager_onboarding(owner)
    if not onboarding:
        return err
    manager_key = registry_normalize_manager_key(onboarding.get("manager_key") or "")
    if not manager_key:
        return "Не найден manager_key для добавления. Начните заново."
    requested_key = registry_normalize_manager_key(str(args or "").strip())
    if requested_key and requested_key != manager_key:
        return f"Менеджер {requested_key} не соответствует текущему добавлению ({manager_key}). Начните заново."
    paths = _manager_runtime_paths_for_key(manager_key)
    # Release the manager's .session from any running process before opening the QR client.
    stop_ok, stop_err = await _onboarding_stop_running_for_key(manager_key)
    if not stop_ok:
        return stop_err
    await _manager_qr_session_drop(owner)
    temp_client = None
    _, _, api_profile_name = _api_profile_for("onboarding")
    try:
        temp_client = await _build_manager_session_client(manager_key, paths["session_path"])
        await temp_client.connect()
        qr = await temp_client.qr_login()
    except Exception as e:
        if temp_client is not None:
            try:
                await temp_client.disconnect()
            except Exception:
                pass
        _manager_auth_audit_log("qr_start", manager_key, ok=0, api_profile=api_profile_name, error_class=e.__class__.__name__, error_repr=repr(e)[:300])
        return f"Не удалось начать вход по QR: {e.__class__.__name__}"
    entry = {
        "manager_key": manager_key,
        "client": temp_client,
        "qr_login": qr,
        "task": None,
        "expires_at_dt": qr.expires,
        "needs_2fa": False,
        "session_path": paths["session_path"],
        "phone": str(onboarding.get("phone") or ""),
        "phone_code_hash": str(onboarding.get("phone_code_hash") or ""),
    }
    _MANAGER_QR_SESSIONS[owner] = entry
    entry["task"] = asyncio.create_task(_manager_qr_wait_task(owner, manager_key))
    try:
        await manager_save_onboarding(
            owner,
            manager_key=manager_key,
            step="await_qr",
            phone=entry["phone"],
            phone_code_hash=entry["phone_code_hash"],
            tmp_session_path=paths["session_path"],
            expires_at=_future_iso_max(MANAGER_ONBOARD_TIMEOUT_SEC, 300),
            next_code_allowed_at=str(onboarding.get("next_code_allowed_at") or ""),
            last_code_sent_at=str(onboarding.get("last_code_sent_at") or ""),
        )
        _manager_runtime_onboarding_set(owner, manager_key=manager_key, step="await_qr", tmp_session_path=paths["session_path"])
    except Exception:
        pass
    expires_iso = _qr_expires_iso(qr)
    _manager_auth_audit_log("qr_start", manager_key, ok=1, api_profile=api_profile_name, hash_present=0)
    return (
        "🔳 Вход по QR\n"
        f"QR_URL={qr.url}\n"
        f"EXPIRES={expires_iso or '_'}\n"
        f"Код действителен до: {_iso_to_local_hhmm(expires_iso) if expires_iso else '_'}\n"
        "Откройте Telegram (там, где уже выполнен вход для нужного номера) -> Настройки -> Устройства -> "
        "Подключить устройство, и отсканируйте QR. Если сканер недоступен, откройте ссылку выше прямо на "
        "устройстве с залогиненным Telegram.\n"
        "⚠️ Открывайте эту ссылку только на устройстве, где залогинен нужный Telegram аккаунт."
    )


# ---------------------------------------------------------------------------
# TPILOT AUTH SAFETY 20260809 (Ф3, D-QR): relogin/replacement QR entry points.
# NOT wired to any panel_bot.py callback yet (that is Ф4's job, deliberately
# deferred until this backend is proven safe) -- callable directly today by a
# selftest or a future controller command. Both open the QR client on a TEMP
# session path (never the live/boevoy or replacement-permanent path -- guarded
# fail-closed by _manager_qr_guard_no_collision), and store context="relogin"/
# "replace" in _MANAGER_QR_SESSIONS so _manager_qr_wait_task dispatches into
# the EXISTING _manager_relogin_commit / _replacement_after_signin on success
# -- no new commit/rollback mechanism.
# ---------------------------------------------------------------------------

async def _manager_relogin_qr_start(owner_user_id: int, manager_key: str) -> str:
    """QR counterpart of the phone-based relogin flow (_panel_manager_relogin_
    phone_command). Opens QR on _manager_relogin_temp_session_path(key) --
    never the live session. On success, _manager_qr_wait_task hands off to the
    existing _manager_relogin_commit, which re-verifies the temp session
    itself, backs up the live session, atomically replaces it, and rolls back
    on any failure -- the SAME safety phone-based relogin already has."""
    owner = int(owner_user_id or 0)
    key = registry_normalize_manager_key(manager_key or "")
    if not key:
        return "Не указан manager_key."
    row = await manager_get(key)
    if not row:
        return f"Менеджер не найден: {key}."
    status = str(row.get("status") or "").strip().lower()
    if status in ("archived", "deleted"):
        return f"Менеджер архивирован/удалён: {key}."

    temp_path = _manager_relogin_temp_session_path(key)
    live_path = _manager_runtime_paths_for_key(key)["session_path"]
    ok_guard, guard_err = _manager_qr_guard_no_collision(temp_path, live_path)
    if not ok_guard:
        _manager_auth_audit_log("relogin_qr_start", key, ok=0, admin_user_id=owner, reason="path_collision")
        return guard_err

    await _manager_qr_session_drop(owner)
    _, _, api_profile_name = _api_profile_for("onboarding")
    temp_client = None
    try:
        temp_client = _build_manager_telegram_client_from_row(dict(row), temp_path, source="onboarding")
        await temp_client.connect()
        qr = await temp_client.qr_login()
    except Exception as e:
        if temp_client is not None:
            try:
                await temp_client.disconnect()
            except Exception:
                pass
        _manager_auth_audit_log("relogin_qr_start", key, ok=0, admin_user_id=owner, api_profile=api_profile_name, error_class=e.__class__.__name__)
        return f"Не удалось начать вход по QR: {e.__class__.__name__}"

    entry = {
        "manager_key": key, "client": temp_client, "qr_login": qr, "task": None,
        "expires_at_dt": qr.expires, "needs_2fa": False, "session_path": temp_path,
        "context": "relogin", "live_session_path": live_path,
        "phone": "", "phone_code_hash": "",
    }
    _MANAGER_QR_SESSIONS[owner] = entry
    entry["task"] = asyncio.create_task(_manager_qr_wait_task(owner, key))
    expires_iso = _qr_expires_iso(qr)
    _manager_auth_audit_log("relogin_qr_start", key, ok=1, admin_user_id=owner, api_profile=api_profile_name)
    return (
        "🔳 Вход по QR (перезайти)\n"
        f"QR_URL={qr.url}\n"
        f"EXPIRES={expires_iso or '_'}\n"
        f"Код действителен до: {_iso_to_local_hhmm(expires_iso) if expires_iso else '_'}\n"
        "⚠️ Отсканируйте на устройстве с залогиненным нужным Telegram-аккаунтом."
    )


async def _manager_replace_qr_start(
    owner_user_id: int, operation_id: str, new_display_name: str, new_manager_key: str,
    proxy_config: Optional[Dict[str, Any]], *, proxy_source: str = "",
) -> str:
    """QR counterpart of the phone-based replacement flow
    (replacement_send_phone_code). Performs the durable draft -> auth_phone
    CAS via replacement_send_qr_start (key reservation, display name, proxy
    route -- no phone number, no send_code_request), then opens QR on the
    returned replacement TEMP session path -- never the (not-yet-existing)
    permanent path. On success, _manager_qr_wait_task hands off to the
    EXISTING _replacement_after_signin, which performs every identity/
    conflict guard the phone flow already has before advancing the operation
    to identity_ok; the rest of the replacement state machine (ready_commit
    -> ... -> done, including _repl4_promote_session) is untouched and fully
    reused."""
    owner = int(owner_user_id or 0)
    reserved = await replacement_send_qr_start(
        operation_id, new_display_name, new_manager_key, proxy_config, proxy_source=proxy_source,
    )
    if not reserved.get("ok"):
        return str(reserved.get("message") or "Не удалось подготовить операцию замены.")
    key = str(reserved.get("new_manager_key") or "")
    temp_path = str(reserved.get("temp_session_path") or "")

    live_path = _replacement_permanent_session_path(key)
    ok_guard, guard_err = _manager_qr_guard_no_collision(temp_path, live_path)
    if not ok_guard:
        _manager_auth_audit_log("replace_qr_start", key, ok=0, admin_user_id=owner, reason="path_collision")
        return guard_err

    await _manager_qr_session_drop(owner)
    temp_client = None
    try:
        temp_client = _replacement_build_client(temp_path, proxy_config)
        await temp_client.connect()
        qr = await temp_client.qr_login()
    except Exception as e:
        if temp_client is not None:
            try:
                await temp_client.disconnect()
            except Exception:
                pass
        _manager_auth_audit_log("replace_qr_start", key, ok=0, admin_user_id=owner, error_class=e.__class__.__name__)
        return f"Не удалось начать вход по QR: {e.__class__.__name__}"

    entry = {
        "manager_key": key, "client": temp_client, "qr_login": qr, "task": None,
        "expires_at_dt": qr.expires, "needs_2fa": False, "session_path": temp_path,
        "context": "replace", "operation_id": str(operation_id or ""), "live_session_path": live_path,
        "phone": "", "phone_code_hash": "",
    }
    _MANAGER_QR_SESSIONS[owner] = entry
    entry["task"] = asyncio.create_task(_manager_qr_wait_task(owner, key))
    expires_iso = _qr_expires_iso(qr)
    _manager_auth_audit_log("replace_qr_start", key, ok=1, admin_user_id=owner)
    return (
        "🔳 Вход по QR (замена аккаунта)\n"
        f"QR_URL={qr.url}\n"
        f"EXPIRES={expires_iso or '_'}\n"
        f"Код действителен до: {_iso_to_local_hhmm(expires_iso) if expires_iso else '_'}\n"
        "⚠️ Отсканируйте на устройстве с залогиненным НОВЫМ Telegram-аккаунтом."
    )


async def _panel_manager_qr_refresh_command(args: str, *, requested_by: int = 0) -> str:
    owner = int(requested_by or 0)
    entry = _MANAGER_QR_SESSIONS.get(owner)
    if not entry or entry.get("needs_2fa"):
        return await _panel_manager_qr_start_command(args, requested_by=requested_by)
    manager_key = str(entry.get("manager_key") or "")
    qr = entry.get("qr_login")
    try:
        await qr.recreate()
    except Exception as e:
        await _manager_qr_session_drop(owner)
        _manager_auth_audit_log("qr_refresh", manager_key, ok=0, error_class=e.__class__.__name__)
        return f"Не удалось обновить QR: {e.__class__.__name__}. Нажмите «Войти по QR» ещё раз."
    entry["expires_at_dt"] = qr.expires
    old_task = entry.get("task")
    if old_task is not None and not old_task.done():
        try:
            old_task.cancel()
        except Exception:
            pass
    entry["task"] = asyncio.create_task(_manager_qr_wait_task(owner, manager_key))
    expires_iso = _qr_expires_iso(qr)
    _manager_auth_audit_log("qr_refresh", manager_key, ok=1)
    return (
        "🔳 QR обновлён\n"
        f"QR_URL={qr.url}\n"
        f"EXPIRES={expires_iso or '_'}\n"
        f"Код действителен до: {_iso_to_local_hhmm(expires_iso) if expires_iso else '_'}\n"
        "⚠️ Открывайте эту ссылку только на устройстве, где залогинен нужный Telegram аккаунт."
    )


async def _panel_manager_qr_cancel_command(args: str, *, requested_by: int = 0) -> str:
    owner = int(requested_by or 0)
    entry = _MANAGER_QR_SESSIONS.get(owner)
    manager_key = registry_normalize_manager_key(str((entry or {}).get("manager_key") or args or ""))
    phone_keep = str((entry or {}).get("phone") or "")
    context = str((entry or {}).get("context") or "add")
    await _manager_qr_session_drop(owner)

    # TPILOT AUTH SAFETY 20260809 (Ф3 checkpoint fix, D-QR cleanup):
    # relogin/replace QR sessions must have their TEMPORARY session file
    # removed on cancel -- reusing the SAME existing helpers the phone-based
    # relogin/replacement cancel commands already use for the identical
    # purpose (see _manager_qr_temp_cleanup_for_context's docstring for why
    # this can never touch the live/boevoy session). Local cleanup only --
    # deliberately does NOT call Telegram log_out() on the temp session
    # (unlike the phone-based relogin cancel command's own, separate,
    # unmodified behavior): this command's job is releasing the local
    # temp client/file, not invalidating a Telegram authorization
    # server-side.
    if context == "relogin" and manager_key:
        _manager_qr_temp_cleanup_for_context(context, manager_key)
        _manager_auth_audit_log("qr_cancel", manager_key, ok=1, context="relogin")
        return "❌ Вход по QR (повторный вход) отменён. Временная сессия удалена, боевая сессия не затронута."

    if context == "replace" and manager_key:
        _manager_qr_temp_cleanup_for_context(context, manager_key)
        _manager_auth_audit_log("qr_cancel", manager_key, ok=1, context="replace")
        return "❌ Вход по QR (замена аккаунта) отменён. Временная сессия удалена."

    # context == "add" -- ORIGINAL behavior, unchanged.
    if manager_key:
        try:
            paths = _manager_runtime_paths_for_key(manager_key)
            await manager_save_onboarding(
                owner,
                manager_key=manager_key,
                step="await_phone",
                phone=phone_keep,
                phone_code_hash="",
                tmp_session_path=paths["session_path"],
                expires_at=_future_iso(MANAGER_ONBOARD_TIMEOUT_SEC),
                next_code_allowed_at="",
            )
            _manager_runtime_onboarding_set(owner, manager_key=manager_key, step="await_phone", phone_code_hash="")
        except Exception:
            pass
        _manager_auth_audit_log("qr_cancel", manager_key, ok=1)
    return "❌ Вход по QR отменён. Можете запросить код по номеру телефона ещё раз или начать QR заново."


async def _panel_manager_proxy_command(action: str, args: str, *, requested_by: int = 0) -> str:
    action = str(action or "").strip().lower()
    parts = str(args or "").strip().split()
    if action in ("info", "on", "off"):
        key = registry_normalize_manager_key(parts[0] if parts else "")
        if not key:
            return f"Формат: /manager_proxy_{action} <manager_key>"
        row = await manager_get(key)
        if not row or str(row.get("status") or "") == "archived":
            return f"Менеджер не найден: {key}"
        if action == "info":
            return _manager_proxy_info_text(row)
        if action == "off":
            await manager_set_fields(key, proxy_enabled=0, proxy_updated_at=_now_utc_iso())
            return f"✅ Proxy выключен для {key}. Чтобы применить, перезапустите менеджера."
        if action == "on":
            if not str(row.get("proxy_host") or "").strip() or not _proxy_port_int(row.get("proxy_port")):
                return f"Для {key} ещё не задан proxy. Сначала задайте SOCKS5 host и port."
            await manager_set_fields(key, proxy_enabled=1, proxy_updated_at=_now_utc_iso())
            return f"✅ Proxy включён для {key}. Чтобы применить, перезапустите менеджера."
    if action == "set":
        key = registry_normalize_manager_key(parts[0] if len(parts) >= 1 else "")
        ptype = _proxy_type_norm(parts[1] if len(parts) >= 2 else "")
        host = str(parts[2] if len(parts) >= 3 else "").strip()
        port = _proxy_port_int(parts[3] if len(parts) >= 4 else "")
        username = str(parts[4] if len(parts) >= 5 else "").strip()
        password = str(parts[5] if len(parts) >= 6 else "").strip()
        if username == "-":
            username = ""
        if password == "-":
            password = ""
        if not key or ptype != "socks5" or not host or not port:
            return "Формат: /manager_proxy_set <key> SOCKS5 <host> <port> [login] [password]"
        row = await manager_get(key)
        if not row or str(row.get("status") or "") == "archived":
            return f"Менеджер не найден: {key}"
        await manager_set_fields(
            key,
            proxy_type="socks5",
            proxy_host=host,
            proxy_port=int(port),
            proxy_username=username,
            proxy_password=password,
            proxy_enabled=1,
            proxy_updated_at=_now_utc_iso(),
        )
        return "\n".join([
            f"✅ SOCKS5 proxy сохранён и включён для {key}",
            f"Host: {host}",
            f"Port: {int(port)}",
            f"Login: {_proxy_login_display(username)}",
            f"Password: {_mask_secret(password)}",
            "Чтобы применить, перезапустите менеджера.",
        ])
    return "Команда proxy не распознана."


# -------------------- PanelBot autoreply mode command --------------------
def _autoreply_status_label(status: str, auto_enabled: bool) -> tuple[str, str]:
    st = str(status or "online").strip().lower()
    if not auto_enabled:
        return "🔇 Не писать клиентам", "программа не отправляет клиентские автоответы"
    if st == "worknow":
        return "⚡ Анкета сейчас", "дневная анкета включена принудительно"
    if st == "online":
        return "🤖 Авто по графику", "днём анкета, вне графика ночное сообщение"
    if st in ("offline", "dayoff", "no_show", "auto_offline"):
        return "🌙 Ночное сообщение", "сейчас клиенту уходит сообщение нерабочего времени"
    return f"🟡 {st}", "нестандартный режим"


async def _format_autoreply_panel_status(target: str = "all") -> str:
    rows = await manager_list_rows(include_removed=False)
    target = registry_normalize_manager_key(target or "all") or "all"
    lines = [
        "💬 Автоответы клиентам",
        "",
        "🤖 Авто по графику: днём анкета, вне графика ночное сообщение.",
        "⚡ Анкета сейчас: принудительно включает дневную анкету прямо сейчас.",
        "🔇 Не писать клиентам: программа молчит, пока вручную не включить обратно.",
        "",
    ]
    any_row = False
    for r in rows or []:
        key = registry_normalize_manager_key(r.get("manager_key") or "")
        if not key or (target != "all" and key != target):
            continue
        any_row = True
        auto_enabled = await _get_profile_auto_enabled(key)
        work = await _get_manager_work_status(key)
        raw_status = str((work or {}).get("status") or "online").strip().lower()
        label, note = _autoreply_status_label(raw_status, auto_enabled)
        manager_label = _manager_label_from_row(r)
        lines.append(f"👤 {manager_label}")
        lines.append(f"Ключ: {key}")
        lines.append(f"Режим: {label}")
        lines.append(f"Сейчас: {note}")
        lines.append("")
    if not any_row:
        lines.append("Менеджеры не найдены.")
    return "\n".join(lines).rstrip()
# -------------------- PanelBot autoreply mode command end --------------------

async def _panel_execute_command_text(command_text: str, *, requested_by: int = 0) -> Dict[str, Any]:
    text = str(command_text or "").strip()
    cmd, args = _parse_cmd(text)
    if not cmd:
        return {"ok": False, "error_text": "Пустая команда."}
    if cmd == "/manager_add":
        return {"ok": True, "result_text": await _panel_manager_add_command(args, requested_by=requested_by)}
    if cmd == "/manager_phone":
        return {"ok": True, "result_text": await _panel_manager_phone_command(args, requested_by=requested_by)}
    if cmd == "/manager_code":
        return {"ok": True, "result_text": await _panel_manager_code_command(args, requested_by=requested_by)}
    if cmd == "/manager_pass":
        return {"ok": True, "result_text": await _panel_manager_pass_command(args, requested_by=requested_by)}
    if cmd == "/manager_proxy_info":
        return {"ok": True, "result_text": await _panel_manager_proxy_command("info", args, requested_by=requested_by)}
    if cmd == "/manager_proxy_on":
        return {"ok": True, "result_text": await _panel_manager_proxy_command("on", args, requested_by=requested_by)}
    if cmd == "/manager_proxy_off":
        return {"ok": True, "result_text": await _panel_manager_proxy_command("off", args, requested_by=requested_by)}
    if cmd == "/manager_proxy_set":
        return {"ok": True, "result_text": await _panel_manager_proxy_command("set", args, requested_by=requested_by)}
    if cmd in ("/help", "/help_adm"):
        return {"ok": True, "result_text": build_admin_help_text()}
    if cmd == "/instructions":
        return {"ok": True, "result_text": build_instructions_text()}
    if cmd == "/autoreply":
        return {"ok": True, "result_text": await _handle_autoreply_panel_command(args, user_id=requested_by)}

    if cmd == "/unanswered":
        return {"ok": True, "result_text": await _format_unanswered_text(registry_normalize_manager_key(args or "all") or "all")}
    if cmd == "/unanswered_notify":
        return {"ok": True, "result_text": await _handle_unanswered_notify_command(args)}
    if cmd == "/profile":
        return {"ok": True, "result_text": await _handle_profile_auto_command(args, user_id=requested_by)}
    if cmd == "/followup":
        return {"ok": True, "result_text": await _handle_post_followup_command(args, user_id=requested_by)}
    if cmd == "/stat":
        raw_args = (args or "").strip()
        parts = raw_args.split()
        if parts and parts[0].lower() in ("range", "period", "период", "с"):
            spec, err = _parse_period_command_parts(parts, default_scope="manager")
            if err:
                return {"ok": False, "error_text": err}
            await _process_pending_lead_events()
            return {"ok": True, "result_text": await _build_stat_period_text(spec)}
        if parts and parts[0].lower() == "det":
            target, date_val = _parse_target_date_args(" ".join(parts[1:]), default_target="all")
            await _process_pending_lead_events()
            try:
                await _process_pending_geoage_events()
            except Exception:
                pass
            return {"ok": True, "result_text": await _build_det_stat_text(target, "day", date_val.strftime("%d.%m.%y") if date_val else None)}
        target, date_val = _parse_target_date_args(raw_args, default_target="all")
        await _process_pending_lead_events()
        return {"ok": True, "result_text": await _build_stat_text(target, date_val.isoformat() if date_val else None)}
    if cmd in ("/flight", "/flights"):
        target, date_val = _parse_target_date_args(args or "all", default_target="all")
        await _process_pending_lead_events()
        try:
            await _process_pending_geoage_events()
        except Exception:
            pass
        return {"ok": True, "result_text": await _build_det_stat_text(target, "flight", date_val.strftime("%d.%m.%y") if date_val else None)}
    if cmd == "/export":
        target, mode, date_val, days = _parse_export_args(args or "")
        ok, path, err, caption = await _run_export_command(target, mode, date_val, days)
        if not ok:
            return {"ok": False, "error_text": err or "Ошибка экспорта."}
        return {"ok": True, "result_text": f"📦 Экспорт готов: {target}", "result_file": str(path), "result_caption": caption or f"📎 Выгрузка | {target}"}
    if cmd == "/status":
        arg = registry_normalize_manager_key((args or "").split()[0]) if args else "all"
        if not arg or arg == "all":
            return {"ok": True, "result_text": await _panel_format_status_all()}
        st = await _get_manager_work_status(arg)
        val = str(st.get("status") or "online").lower()
        icon = "☀️" if val == "worknow" else ("🟢" if val == "online" else ("🌙" if val in ("dayoff", "no_show", "auto_offline") else "🔴"))
        return {"ok": True, "result_text": f"{icon} {val} {arg}"}
    if cmd in ("/online", "/workday", "/worknow", "/offline", "/dayoff"):
        target = registry_normalize_manager_key(args or "")
        if not target:
            return {"ok": False, "error_text": f"Формат: {cmd} <manager_key>"}
        if cmd in ("/online", "/workday"):
            st_value = "online"
        elif cmd == "/worknow":
            st_value = "worknow"
        elif cmd == "/dayoff":
            st_value = "dayoff"
        else:
            st_value = "offline"
        await _set_manager_work_status(target, st_value, user_id=requested_by)
        icon = "☀️" if st_value == "worknow" else ("🟢" if st_value == "online" else ("🌙" if st_value == "dayoff" else "🔴"))
        extra = "\nДневное приветствие и анкета включены прямо сейчас." if st_value == "worknow" else ""
        return {"ok": True, "result_text": f"{icon} {st_value} {target}{extra}"}

    # --- TPILOT PANEL ROUTER FINAL FIX START ---
    # Single safety net for PanelBot command routing.
    # Keep this block immediately before the generic "unsupported command" fallback.
    # It prevents restored handlers from being invisible to the active panel router.
    def _panel_missing_handler(handler_name: str) -> Dict[str, Any]:
        return {
            "ok": False,
            "error_text": (
                f"Panel-router найден, но обработчик {handler_name} отсутствует в активном main.py.\n"
                "Проверьте, что применён полный admin/core restore и перезапущен TPilot."
            ),
        }

    if cmd == "/paneldiag":
        check_names = [
            "_panel_execute_command_text",
            "_handle_source_command",
            "_handle_mgroup_command",
            "_handle_partner_command",
            "_handle_quality_command",
            "_handle_funnel_command",
            "_handle_silent_command",
            "_handle_profile_auto_command",
            "_handle_post_followup_command",
            "_handle_testlead_command",
            "_handle_baseline_command",
            "_run_export_command",
        ]
        lines = [
            "🧪 Panel router diag",
            "",
            f"File: {globals().get('__file__', '_')}",
            "Router fix: final_panel_router_fix_v1",
            "",
            "Handlers:",
        ]
        for name in check_names:
            lines.append(f"{'✅' if callable(globals().get(name)) else '❌'} {name}")
        return {"ok": True, "result_text": "\n".join(lines).rstrip()}

    if cmd == "/source":
        fn = globals().get("_handle_source_command")
        if not callable(fn):
            return _panel_missing_handler("_handle_source_command")
        return {"ok": True, "result_text": await fn(args, user_id=requested_by)}

    if cmd == "/mgroup":
        fn = globals().get("_handle_mgroup_command")
        if not callable(fn):
            return _panel_missing_handler("_handle_mgroup_command")
        return {"ok": True, "result_text": await fn(args, user_id=requested_by)}

    if cmd == "/partner":
        fn = globals().get("_handle_partner_command")
        if not callable(fn):
            return _panel_missing_handler("_handle_partner_command")
        return {"ok": True, "result_text": await fn(args, user_id=requested_by)}

    if cmd == "/quality":
        fn = globals().get("_handle_quality_command")
        if not callable(fn):
            return _panel_missing_handler("_handle_quality_command")
        return {"ok": True, "result_text": await fn(args, user_id=requested_by)}

    if cmd == "/funnel":
        fn = globals().get("_handle_funnel_command")
        if not callable(fn):
            return _panel_missing_handler("_handle_funnel_command")
        return {"ok": True, "result_text": await fn(args, user_id=requested_by)}

    if cmd == "/silent":
        fn = globals().get("_handle_silent_command")
        if not callable(fn):
            return _panel_missing_handler("_handle_silent_command")
        return {"ok": True, "result_text": await fn(args, user_id=requested_by)}

    if cmd == "/profile":
        fn = globals().get("_handle_profile_auto_command")
        if not callable(fn):
            return _panel_missing_handler("_handle_profile_auto_command")
        return {"ok": True, "result_text": await fn(args, user_id=requested_by)}

    if cmd == "/followup":
        fn = globals().get("_handle_post_followup_command")
        if not callable(fn):
            return _panel_missing_handler("_handle_post_followup_command")
        return {"ok": True, "result_text": await fn(args, user_id=requested_by)}

    if cmd == "/unanswered":
        fn = globals().get("_format_unanswered_text")
        if not callable(fn):
            return _panel_missing_handler("_format_unanswered_text")
        target = registry_normalize_manager_key(args or "all") or "all"
        return {"ok": True, "result_text": await fn(target)}

    if cmd == "/unanswered_notify":
        fn = globals().get("_handle_unanswered_notify_command")
        if not callable(fn):
            return _panel_missing_handler("_handle_unanswered_notify_command")
        return {"ok": True, "result_text": await fn(args)}

    if cmd == "/testlead":
        fn = globals().get("_handle_testlead_command")
        if not callable(fn):
            return _panel_missing_handler("_handle_testlead_command")
        return {"ok": True, "result_text": await fn(args, user_id=requested_by)}

    if cmd == "/baseline":
        fn = globals().get("_handle_baseline_command")
        if not callable(fn):
            return _panel_missing_handler("_handle_baseline_command")
        return {"ok": True, "result_text": await fn(args, user_id=requested_by)}

    if cmd == "/stat":
        parser = globals().get("_parse_target_date_args")
        build_stat = globals().get("_build_stat_text")
        build_det = globals().get("_build_det_stat_text")
        process_pending = globals().get("_process_pending_lead_events")
        if not callable(parser) or not callable(build_stat) or not callable(build_det):
            return _panel_missing_handler("_parse_target_date_args/_build_stat_text/_build_det_stat_text")
        raw_args = args or ""
        parts = raw_args.split()
        if callable(process_pending):
            await process_pending()
        if parts and parts[0].lower() == "det":
            target, date_val = parser(" ".join(parts[1:]), default_target="all")
            label = date_val.strftime("%d.%m.%y") if date_val else None
            return {"ok": True, "result_text": await build_det(target, "day", label)}
        target, date_val = parser(raw_args or "all", default_target="all")
        return {"ok": True, "result_text": await build_stat(target, date_val.isoformat() if date_val else None)}

    if cmd in ("/flight", "/flights"):
        parser = globals().get("_parse_target_date_args")
        build_det = globals().get("_build_det_stat_text")
        process_pending = globals().get("_process_pending_lead_events")
        if not callable(parser) or not callable(build_det):
            return _panel_missing_handler("_parse_target_date_args/_build_det_stat_text")
        if callable(process_pending):
            await process_pending()
        target, date_val = parser(args or "all", default_target="all")
        label = date_val.strftime("%d.%m.%y") if date_val else None
        return {"ok": True, "result_text": await build_det(target, "flight", label)}

    if cmd == "/export":
        parser = globals().get("_parse_export_args")
        runner = globals().get("_run_export_command")
        if not callable(parser) or not callable(runner):
            return _panel_missing_handler("_parse_export_args/_run_export_command")
        target, mode, date_val, days = parser(args or "")
        ok, path, err, caption = await runner(target, mode, date_val, days)
        if not ok:
            return {"ok": False, "error_text": err or "Ошибка экспорта."}
        return {
            "ok": True,
            "result_text": f"📦 Экспорт готов: {target}",
            "result_file": str(path),
            "result_caption": caption or f"📎 Выгрузка | {target}",
        }
    # --- TPILOT PANEL ROUTER FINAL FIX END ---

    return {"ok": False, "error_text": f"Команда не поддерживается в панели: {cmd}"}

async def _handle_ai_stat_command(event: events.NewMessage.Event) -> bool:
    if not CONTROLLER_MODE:
        return False
    if int(event.chat_id or 0) != int(AI_STAT_CHAT_ID or 0):
        return False
    text = (event.raw_text or "").strip()
    if not text:
        return False
    if text.upper().startswith("MANAGER ") or text.upper().startswith("PHONE ") or text.upper().startswith("CODE ") or text.upper().startswith("PASS "):
        await client.send_message(event.chat_id, "MANAGER-команды доступны только в ЛС TPilot.")
        return True
    cmd, args = _parse_cmd(text)
    if not cmd:
        return False
    if cmd in ("/help", "/help_adm"):
        await client.send_message(event.chat_id, build_admin_help_text())
        return True
    if cmd == "/instructions":
        await client.send_message(event.chat_id, build_instructions_text())
        return True
    if cmd == "/unanswered":
        await client.send_message(event.chat_id, await _format_unanswered_text(registry_normalize_manager_key(args or "all") or "all"))
        return True
    if cmd == "/unanswered_notify":
        await client.send_message(event.chat_id, await _handle_unanswered_notify_command(args))
        return True
    if cmd == "/profile":
        await client.send_message(event.chat_id, await _handle_profile_auto_command(args, user_id=int(event.sender_id or 0)))
        return True
    if cmd == "/followup":
        await client.send_message(event.chat_id, await _handle_post_followup_command(args, user_id=int(event.sender_id or 0)))
        return True
    if cmd == "/stat":
        parts = (args or "").split()
        if parts and parts[0].lower() in ("range", "period", "период", "с"):
            spec, err = _parse_period_command_parts(parts, default_scope="manager")
            if err:
                await client.send_message(event.chat_id, err)
                return True
            await _process_pending_lead_events()
            await client.send_message(event.chat_id, await _build_stat_period_text(spec))
            return True
        if parts and parts[0].lower() == "det":
            target, date_val = _parse_target_date_args(" ".join(parts[1:]), default_target="all")
            await _process_pending_lead_events()
            await client.send_message(event.chat_id, await _build_det_stat_text(target, "day", date_val.strftime("%d.%m.%y") if date_val else None))
            return True
        target, date_val = _parse_target_date_args(args or "all", default_target="all")
        await _process_pending_lead_events()
        await client.send_message(event.chat_id, await _build_stat_text(target, date_val.isoformat() if date_val else None))
        return True
    if cmd in ("/flight", "/flights"):
        target, date_val = _parse_target_date_args(args or "all", default_target="all")
        await _process_pending_lead_events()
        await client.send_message(event.chat_id, await _build_det_stat_text(target, "flight", date_val.strftime("%d.%m.%y") if date_val else None))
        return True
    if cmd == "/export":
        target, mode, date_val, days = _parse_export_args(args or "")
        ok, path, err, caption = await _run_export_command(target, mode, date_val, days)
        if not ok:
            await client.send_message(event.chat_id, err or "Ошибка экспорта.")
            return True
        await _send_ai_file(path, caption=caption or f"📎 Выгрузка | {target}")
        return True
    return False

