_TPILOT_202605_ORIG_BUILD_DET_STAT_TEXT = globals().get("_build_det_stat_text")

TP_CLIENT_SILENCE_START_HOUR = 21
TP_CLIENT_SILENCE_END_HOUR = 7
TP_PROFILE_START_HOUR = 8
TP_PROFILE_END_HOUR = 17
TP_FOLLOWUP_START_HOUR = 7
TP_FOLLOWUP_END_HOUR = 21


# _format_wait_duration, _tp_utc_parse moved to text_format_helpers.py
# (extraction pass #3, 2026-08-22) -- pure stdlib duration/datetime helpers.
_format_wait_duration = text_format_helpers.format_wait_duration
_tp_utc_parse = text_format_helpers.tp_utc_parse


def _tp_is_between_hours(local_dt: datetime, start_hour: int, end_hour: int) -> bool:
    h = int(local_dt.hour)
    if start_hour < end_hour:
        return start_hour <= h < end_hour
    return h >= start_hour or h < end_hour


def _tp_client_auto_silent_now(local_dt: Optional[datetime] = None) -> bool:
    return _tp_is_between_hours(local_dt or _kyiv_now(), TP_CLIENT_SILENCE_START_HOUR, TP_CLIENT_SILENCE_END_HOUR)


def _tp_profile_auto_allowed_now(local_dt: Optional[datetime] = None) -> bool:
    return _tp_is_between_hours(local_dt or _kyiv_now(), TP_PROFILE_START_HOUR, TP_PROFILE_END_HOUR)


def _tp_followup_allowed_now(local_dt: Optional[datetime] = None) -> bool:
    return _tp_is_between_hours(local_dt or _kyiv_now(), TP_FOLLOWUP_START_HOUR, TP_FOLLOWUP_END_HOUR)


def _tp_business_elapsed_minutes(start_utc_raw: Any, end_utc_raw: Any = None, *, start_hour: int = TP_FOLLOWUP_START_HOUR, end_hour: int = TP_FOLLOWUP_END_HOUR) -> int:
    start_utc = _tp_utc_parse(start_utc_raw)
    if not start_utc:
        return 0
    end_utc = _tp_utc_parse(end_utc_raw) if end_utc_raw else _tp_utc_now().replace(microsecond=0)
    if not end_utc or end_utc <= start_utc:
        return 0
    start_local = start_utc.replace(tzinfo=timezone.utc).astimezone(TZ_KYIV)
    end_local = end_utc.replace(tzinfo=timezone.utc).astimezone(TZ_KYIV)
    total = 0
    cur_day = start_local.date()
    while cur_day <= end_local.date():
        win_start = datetime(cur_day.year, cur_day.month, cur_day.day, int(start_hour), 0, 0, tzinfo=TZ_KYIV)
        win_end = datetime(cur_day.year, cur_day.month, cur_day.day, int(end_hour), 0, 0, tzinfo=TZ_KYIV)
        a = max(start_local, win_start)
        b = min(end_local, win_end)
        if b > a:
            total += int((b - a).total_seconds() // 60)
        cur_day = cur_day + timedelta(days=1)
    return max(0, int(total))


def _tp_strip_duplicate_lines(text: str) -> str:
    out = []
    for line in str(text or "").splitlines():
        s = line.strip()
        if s.startswith("Дубликаты:") or s.startswith("Дубли:"):
            continue
        if " | Дубли:" in line:
            line = re.sub(r"\s*\|\s*Дубли:\s*\d+", "", line)
        out.append(line)
    return chr(10).join(out).rstrip()


async def _build_stat_text(target_key: str = "all", lead_date: Optional[str] = None) -> str:
    if callable(_TPILOT_202605_ORIG_BUILD_STAT_TEXT):
        return _tp_strip_duplicate_lines(await _TPILOT_202605_ORIG_BUILD_STAT_TEXT(target_key, lead_date))
    return "Статистика недоступна."


