async def _tp_same_manager_chat_seen_before(db_path: str, chat_id: int) -> Dict[str, Any]:
    if not db_path or not os.path.exists(db_path) or int(chat_id or 0) <= 0:
        return {}
    try:
        await _ensure_daily_leads_table(db_path)
        async with aiosqlite.connect(db_path) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute("SELECT * FROM daily_leads WHERE chat_id=? ORDER BY first_seen_utc ASC, id ASC LIMIT 1", (int(chat_id),))
            row = await cur.fetchone()
            return dict(row) if row else {}
    except Exception:
        return {}


async def _record_daily_lead_event(*, db_path: str, manager_key: str, manager_username: str, chat_id: int, username: str, full_name: str, phone: str, first_seen_utc: str) -> Tuple[bool, Dict[str, Any]]:
    existing = await _tp_same_manager_chat_seen_before(db_path, int(chat_id or 0))
    if existing:
        out = dict(existing)
        out["_existing_same_manager_chat"] = 1
        return False, out
    if callable(_TPILOT_202605_ORIG_RECORD_DAILY_LEAD_EVENT):
        return await _TPILOT_202605_ORIG_RECORD_DAILY_LEAD_EVENT(db_path=db_path, manager_key=manager_key, manager_username=manager_username, chat_id=chat_id, username=username, full_name=full_name, phone=phone, first_seen_utc=first_seen_utc)
    return False, {}


async def _tp_duplicate_history(chat_id: int, *, source_key: str = "") -> List[Dict[str, Any]]:
    chat_id = int(chat_id or 0)
    if chat_id <= 0:
        return []
    rows = await _manager_rows_for_reporting()
    try:
        source_map = await _source_links_map()
    except Exception:
        source_map = {}
    wanted_source = registry_normalize_manager_key(source_key or "")
    result: List[Dict[str, Any]] = []
    for mgr in rows:
        mk = registry_normalize_manager_key(mgr.get("manager_key") or "")
        if not mk:
            continue
        src = registry_normalize_manager_key(source_map.get(mk) or "")
        if wanted_source and src != wanted_source:
            continue
        db_path = str(mgr.get("db_path") or "")
        if not db_path or not os.path.exists(db_path):
            continue
        try:
            await _ensure_daily_leads_table(db_path)
            async with aiosqlite.connect(db_path) as db:
                db.row_factory = aiosqlite.Row
                cur = await db.execute("SELECT * FROM daily_leads WHERE chat_id=? ORDER BY first_seen_utc ASC, id ASC", (chat_id,))
                for r in await cur.fetchall():
                    item = dict(r)
                    item["manager_key"] = mk or item.get("manager_key") or ""
                    item["manager_display_name"] = str(mgr.get("display_name") or mk)
                    item["manager_username"] = str(mgr.get("telegram_username") or item.get("manager_username") or "")
                    item["source_key"] = src
                    result.append(item)
        except Exception:
            continue
    result.sort(key=lambda x: (str(x.get("first_seen_utc") or ""), str(x.get("manager_key") or ""), int(x.get("id") or 0)))
    return result


async def _is_duplicate_systemwide(event_row: Dict[str, Any], manager_db_paths: List[str], batch_seen: set[int], current_db_path: str) -> bool:
    chat_id = int((event_row or {}).get("chat_id") or 0)
    if chat_id <= 0 or int((event_row or {}).get("_existing_same_manager_chat") or 0) == 1:
        return False
    if chat_id in batch_seen:
        return True
    history = await _tp_duplicate_history(chat_id)
    current_mgr = registry_normalize_manager_key((event_row or {}).get("manager_key") or "")
    if any(registry_normalize_manager_key(x.get("manager_key") or "") and registry_normalize_manager_key(x.get("manager_key") or "") != current_mgr for x in history):
        return True
    for dbp in manager_db_paths or []:
        try:
            if os.path.abspath(str(dbp)) == os.path.abspath(str(current_db_path)):
                continue
            if await _old_lead_exists(str(dbp), chat_id):
                return True
        except Exception:
            pass
    return False


async def _collect_day_leads(lead_date: str, target_key: str = "all") -> List[Dict[str, Any]]:
    rows = await _TPILOT_202605_ORIG_COLLECT_DAY_LEADS(lead_date, target_key=target_key) if callable(_TPILOT_202605_ORIG_COLLECT_DAY_LEADS) else []
    return [r for r in rows if int((r or {}).get("duplicate") or 0) != 1]


async def _collect_period_leads(scope: str, key: str, start_iso: str, end_iso: str) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]], str]:
    leads, rows, scope_label = await _TPILOT_202605_ORIG_COLLECT_PERIOD_LEADS(scope, key, start_iso, end_iso) if callable(_TPILOT_202605_ORIG_COLLECT_PERIOD_LEADS) else ([], [], "")
    return [r for r in leads if int((r or {}).get("duplicate") or 0) != 1], rows, scope_label


def _format_lead_event(row: Dict[str, Any], duplicate: bool, manager_label: str) -> str:
    icon = "🔁 Дубликат" if duplicate else "🆕 Новый лид"
    dt = _utc_iso_to_kyiv_dt(str(row.get("first_seen_utc") or ""))
    lines = [icon, ""]
    if manager_label:
        lines.append(f"Аккаунт: {manager_label}")
    lines.append(f"Время: {dt.strftime('%d.%m.%y %H:%M')}")
    lines.append(f"chat_id: {int(row.get('chat_id') or 0)}")
    username = str(row.get("username") or "").strip().lstrip("@")
    if username:
        lines.append(f"username: @{username}")
    full_name = str(row.get("full_name") or "").strip()
    if full_name:
        lines.append(f"Имя: {full_name}")
    phone = str(row.get("phone") or "").strip()
    if phone:
        lines.append(f"Телефон: {phone}")
    lines.append(f"Дубликат: {'да' if duplicate else 'нет'}")
    profile_lines = []
    if row.get("age") is not None and str(row.get("age") or "").strip() != "":
        profile_lines.append(f"Возраст: {row.get('age')}")
    for label, key in (("Страна", "country"), ("Регион", "region"), ("Город", "city")):
        value = str(row.get(key) or "").strip()
        if value:
            profile_lines.append(f"{label}: {value}")
    status_raw = str(row.get("status") or "").strip().lower()
    if status_raw:
        profile_lines.append("Статус: " + ("ликвид" if status_raw == "liquid" else "неликвид" if status_raw == "nonliquid" else status_raw))
    reason = str(row.get("nonliquid_reason") or "").strip()
    if reason:
        profile_lines.append(f"Причина: {reason}")
    if profile_lines:
        lines.extend(["", "📋 Анкета"])
        lines.extend(profile_lines)
    return chr(10).join(lines).rstrip()


def _tp_format_history_item(row: Dict[str, Any], idx: int) -> List[str]:
    dt = _utc_iso_to_kyiv_dt(str(row.get("first_seen_utc") or ""))
    manager_name = str(row.get("manager_display_name") or row.get("manager_key") or "").strip()
    manager_username = str(row.get("manager_username") or "").strip().lstrip("@")
    account = f"{manager_name} | @{manager_username}" if manager_username else manager_name
    lines = [f"{idx}) Обращение", f"Аккаунт: {account}", f"Время: {dt.strftime('%d.%m.%y %H:%M')}", f"chat_id: {int(row.get('chat_id') or 0)}"]
    username = str(row.get("username") or "").strip().lstrip("@")
    if username:
        lines.append(f"username: @{username}")
    full_name = str(row.get("full_name") or "").strip()
    if full_name:
        lines.append(f"Имя: {full_name}")
    phone = str(row.get("phone") or "").strip()
    if phone:
        lines.append(f"Телефон: {phone}")
    for label, key in (("Возраст", "age"), ("Страна", "country"), ("Город", "city")):
        v = str(row.get(key) or "").strip()
        if v:
            lines.append(f"{label}: {v}")
    return lines


async def _format_duplicate_live_event(row: Dict[str, Any], mgr: Dict[str, Any], history: List[Dict[str, Any]]) -> str:
    manager_label = _manager_label_from_row(mgr) if mgr else str(row.get("manager_key") or "")
    lines = [_format_lead_event(row, True, manager_label), "", "С чем дублируется:"]
    for i, item in enumerate(history[:5], 1):
        lines.append("")
        lines.extend(_tp_format_history_item(item, i))
    if len(history) > 5:
        lines.append("")
        lines.append(f"Показано 5 из {len(history)} повторов")
    return chr(10).join(lines).rstrip()


async def _process_pending_lead_events() -> None:
    if not CONTROLLER_MODE:
        return
    rows = await _manager_rows_for_reporting()
    db_paths = [str(r.get("db_path") or "") for r in rows if str(r.get("db_path") or "").strip()]
    pending: List[Dict[str, Any]] = []
    row_by_key = {registry_normalize_manager_key(r.get("manager_key") or ""): r for r in rows}
    for mgr in rows:
        db_path = str(mgr.get("db_path") or "")
        for item in await _fetch_unsent_daily_leads(db_path, limit=300):
            item["_db_path"] = db_path
            item["_manager_row"] = mgr
            pending.append(item)
    pending.sort(key=lambda x: (str(x.get("first_seen_utc") or ""), str(x.get("manager_key") or ""), int(x.get("id") or 0)))
    batch_seen: set[int] = set()
    for item in pending:
        db_path = str(item.get("_db_path") or "")
        key = registry_normalize_manager_key(item.get("manager_key") or "")
        mgr = item.get("_manager_row") or row_by_key.get(key) or {}
        duplicate = await _is_duplicate_systemwide(item, db_paths, batch_seen, db_path)
        history = await _tp_duplicate_history(int(item.get("chat_id") or 0)) if duplicate else []
        manager_label = _manager_label_from_row(mgr) if mgr else key
        text = await _format_duplicate_live_event(item, mgr, history) if duplicate else _format_lead_event(item, False, manager_label)
        try:
            await _create_partner_lead_event_from_daily(item, mgr, duplicate)
        except Exception as e:
            print(f"partner live event dispatch error: {e!r}")
        ok = await _send_ai_stat(text)
        if ok:
            await _mark_daily_lead_sent(db_path, int(item.get("id") or 0), duplicate=duplicate)
            if duplicate:
                batch_seen.add(int(item.get("chat_id") or 0))
            await asyncio.sleep(0.2)


async def _maybe_auto_reply_to_lead(lead_row: Dict[str, Any], state: Dict[str, Any], work: Dict[str, Any]) -> None:
    if int((lead_row or {}).get("_existing_same_manager_chat") or 0) == 1:
        return
    now_local = _kyiv_now()
    if _tp_client_auto_silent_now(now_local):
        return
    status = str((work or {}).get("status") or "online").strip().lower()
    if status in ("offline", "dayoff", "auto_offline", "no_show"):
        if not (TP_PROFILE_END_HOUR <= now_local.hour < TP_CLIENT_SILENCE_START_HOUR):
            return
    elif not _tp_profile_auto_allowed_now(now_local):
        return
    if callable(_TPILOT_202605_ORIG_MAYBE_AUTO_REPLY):
        await _TPILOT_202605_ORIG_MAYBE_AUTO_REPLY(lead_row, state, work)


def _is_post_followup_disable_word(text: str) -> bool:
    return str(text or "").strip().casefold() == "ссууппеерр"


async def _ensure_manager_followup_settings_table() -> None:
    parent = os.path.dirname(TPILOT_DB_PATH)
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute("CREATE TABLE IF NOT EXISTS manager_followup_settings(manager_key TEXT PRIMARY KEY, enabled INTEGER NOT NULL DEFAULT 1, updated_by INTEGER DEFAULT 0, updated_at TEXT NOT NULL DEFAULT '')")
        await db.commit()


async def _get_manager_followup_enabled(manager_key: str) -> bool:
    key = registry_normalize_manager_key(manager_key or "")
    if not key:
        return True
    await _ensure_manager_followup_settings_table()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        cur = await db.execute("SELECT enabled FROM manager_followup_settings WHERE manager_key=?", (key,))
        row = await cur.fetchone()
        return True if not row else int(row[0] or 0) == 1


async def _set_manager_followup_enabled(manager_key: str, enabled: bool, user_id: int = 0) -> None:
    key = registry_normalize_manager_key(manager_key or "")
    if not key:
        return
    await _ensure_manager_followup_settings_table()
    now = _now_utc_iso()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute("INSERT INTO manager_followup_settings(manager_key, enabled, updated_by, updated_at) VALUES(?,?,?,?) ON CONFLICT(manager_key) DO UPDATE SET enabled=excluded.enabled, updated_by=excluded.updated_by, updated_at=excluded.updated_at", (key, 1 if enabled else 0, int(user_id or 0), now))
        await db.commit()


async def _format_manager_followup_status(target: str = "all") -> str:
    rows = await manager_list_rows(include_removed=False)
    target = registry_normalize_manager_key(target or "all") or "all"
    lines = ["🔁 Автодожимы", ""]
    any_row = False
    for r in rows or []:
        key = registry_normalize_manager_key(r.get("manager_key") or "")
        if not key or (target != "all" and key != target):
            continue
        any_row = True
        enabled = await _get_manager_followup_enabled(key)
        lines.append(f"{'🟢 включены' if enabled else '🔴 выключены'} - {_manager_label_from_row(r)}")
    if not any_row:
        lines.append("Менеджеры не найдены.")
    lines.append("")
    lines.append("Точное сообщение менеджера ссууппеерр НАВСЕГДА останавливает всю автоматику (приветствия, анкету, дожимы, напоминания) по конкретному лиду. Действие необратимо и не сбрасывается перезапуском.")
    return chr(10).join(lines).rstrip()


async def _handle_post_followup_command(args: str, user_id: int = 0) -> str:
    raw = str(args or "").strip()
    parts = raw.split()
    if parts:
        action = parts[0].lower()
        if action in ("status", "статус"):
            target = registry_normalize_manager_key(parts[1]) if len(parts) >= 2 else "all"
            return await _format_manager_followup_status(target or "all")
        if action in ("on", "off") and len(parts) >= 2:
            key = registry_normalize_manager_key(parts[1])
            await _set_manager_followup_enabled(key, action == "on", user_id=user_id)
            return f"🔁 Автодожимы для {key}: {'включены' if action == 'on' else 'выключены'}"
    if callable(_TPILOT_202605_ORIG_HANDLE_FOLLOWUP):
        return await _TPILOT_202605_ORIG_HANDLE_FOLLOWUP(args, user_id=user_id)
    return "Команды: /followup status all, /followup on <manager>, /followup off <manager>, /followup off <chat_id>"


def _post_followup_slot_now(now_local: Optional[datetime] = None) -> str:
    dt = now_local or _kyiv_now()
    if not _tp_followup_allowed_now(dt):
        return ""
    h = int(dt.hour)
    if h < int(POST_MANUAL_FOLLOWUP_DAY_START_HOUR or 12):
        return "morning"
    if h < int(POST_MANUAL_FOLLOWUP_DAY_END_HOUR or 16):
        return "day"
    return "evening"


async def _fetch_post_followup_candidates(db_path: str, *, slot: str = "", today_local: str = "", limit: int = 100) -> List[Dict[str, Any]]:
    if not db_path or not os.path.exists(db_path) or not _tp_followup_allowed_now():
        return []
    await _ensure_post_followup_table(db_path)
    await _ensure_daily_leads_table(db_path)
    # A row may now have up to 3 distinct planned slots per day (day-1) or 1 (day-N),
    # so slot eligibility is no longer filtered here in SQL - it is evaluated per-row
    # against planned_*_at / *_sent_date by the caller (see _post_followup_due_slot).
    sql = """
        SELECT s.*, d.status AS lead_status, d.profile_done AS lead_profile_done, d.profile_final_sent AS lead_profile_final_sent, d.username AS lead_username, d.full_name AS lead_full_name
        FROM post_manual_followup_state s
        LEFT JOIN daily_leads d ON d.id = (SELECT id FROM daily_leads dd WHERE dd.chat_id=s.chat_id ORDER BY dd.first_seen_utc DESC, dd.id DESC LIMIT 1)
        WHERE COALESCE(s.active,0)=1 AND COALESCE(s.disabled,0)=0 AND COALESCE(s.trash,0)=0
          AND COALESCE(s.sent_count,0) < ? AND COALESCE(s.last_manager_out_utc,'') <> ''
          AND (COALESCE(s.last_client_in_utc,'')='' OR s.last_client_in_utc < s.last_manager_out_utc)
          AND COALESCE(d.status,'') <> 'trash'
          AND (COALESCE(d.profile_done,0)=1 OR COALESCE(d.profile_final_sent,0)=1 OR COALESCE(d.status,'') IN ('liquid','nonliquid'))
        ORDER BY s.last_manager_out_utc ASC LIMIT ?
    """
    async with aiosqlite.connect(db_path) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(sql, (int(POST_MANUAL_FOLLOWUP_MAX_TOTAL or 6), int(limit) * 3))
        rows = [dict(r) for r in await cur.fetchall()]
    out = []
    now = _now_utc_iso()
    for row in rows:
        mk = registry_normalize_manager_key(row.get("manager_key") or MANAGER_RUNTIME_KEY)
        if not await _get_manager_followup_enabled(mk):
            continue
        if _tp_business_elapsed_minutes(row.get("last_manager_out_utc"), now) < int(POST_MANUAL_FOLLOWUP_MIN_SILENCE_MINUTES or 60):
            continue
        out.append(row)
        if len(out) >= int(limit):
            break
    return out


def _post_followup_window_bounds(slot: str) -> Tuple[int, int]:
    if slot == "morning":
        return int(TP_FOLLOWUP_START_HOUR or 7), int(POST_MANUAL_FOLLOWUP_DAY_START_HOUR or 12)
    if slot == "day":
        return int(POST_MANUAL_FOLLOWUP_DAY_START_HOUR or 12), int(POST_MANUAL_FOLLOWUP_DAY_END_HOUR or 16)
    return int(POST_MANUAL_FOLLOWUP_DAY_END_HOUR or 16), int(TP_FOLLOWUP_END_HOUR or 21)


def _post_followup_local_date_of(utc_iso: str) -> str:
    dt = _tp_utc_parse(utc_iso)
    if not dt:
        return ""
    try:
        return dt.replace(tzinfo=timezone.utc).astimezone(TZ_KYIV).date().isoformat()
    except Exception:
        return ""


def _post_followup_random_planned_utc(chat_id: int, date_key: str, slot: str) -> str:
    """Seeded per (chat, date, slot) so the planned time is stable across restarts."""
    start_h, end_h = _post_followup_window_bounds(slot)
    if end_h <= start_h:
        start_h, end_h = int(TP_FOLLOWUP_START_HOUR or 7), int(TP_FOLLOWUP_END_HOUR or 21)
    rng = random.Random(f"post_followup_plan:{int(chat_id or 0)}:{date_key}:{slot}")
    total_minutes = max(1, (end_h - start_h) * 60 - 1)
    offset_minutes = rng.randint(0, total_minutes)
    try:
        y, m, d = (int(x) for x in str(date_key)[:10].split("-"))
        local_dt = datetime(y, m, d, start_h, 0, 0, tzinfo=TZ_KYIV) + timedelta(minutes=offset_minutes)
        return local_dt.astimezone(timezone.utc).replace(tzinfo=None).isoformat()
    except Exception:
        return ""


def _post_followup_v2_epoch_utc() -> datetime:
    """Resolve and cache the v2 scheduler deploy epoch (naive UTC, same convention as
    _tp_utc_parse/_now_utc_iso). Resolved lazily so it can use _tp_utc_parse, which is
    defined later in the file than this constant block."""
    global _POST_FOLLOWUP_V2_EPOCH_CACHE
    if _POST_FOLLOWUP_V2_EPOCH_CACHE is not None:
        return _POST_FOLLOWUP_V2_EPOCH_CACHE
    raw = str(POST_MANUAL_FOLLOWUP_V2_EPOCH_UTC_RAW or "").strip()
    parsed = _tp_utc_parse(raw) if raw else None
    _POST_FOLLOWUP_V2_EPOCH_CACHE = parsed or _POST_FOLLOWUP_V2_PROCESS_START_UTC
    return _POST_FOLLOWUP_V2_EPOCH_CACHE


def _post_followup_v2_allowed_for_row(row: Dict[str, Any]) -> bool:
    """Safe-by-default: rows with a missing/unparseable cycle_started_at_utc, or one
    that predates the deploy epoch, are excluded from v2 planning entirely (no
    planned_*_at ever gets populated for them) - they only age out via the existing
    MAX_DAYS/MAX_TOTAL rules, never via a randomized catch-up send."""
    cycle_dt = _tp_utc_parse(str(row.get("cycle_started_at_utc") or ""))
    if not cycle_dt:
        return False
    return cycle_dt >= _post_followup_v2_epoch_utc()


async def _post_followup_ensure_daily_plan(db_path: str, chat_id: int, row: Dict[str, Any], today_local: str) -> Dict[str, Any]:
    """Idempotent: only (re)computes planned_*_at when no plan exists yet for today_local.
    Day-1 (day_idx<=0) plans up to 3 slots; later days plan exactly 1 random slot."""
    if not _post_followup_v2_allowed_for_row(row):
        return row
    if str(row.get("followup_plan_date") or "") == str(today_local):
        return row
    cycle_local = _post_followup_local_date_of(str(row.get("cycle_started_at_utc") or "")) or today_local
    day_idx = _post_followup_days_since(cycle_local, today_local)
    if day_idx <= 0:
        candidate_slots = ["morning", "day", "evening"]
    else:
        already_sent_today = any(str(row.get(col) or "") == today_local for col in _POST_FOLLOWUP_SLOT_COLUMNS.values())
        if already_sent_today:
            candidate_slots = []
        else:
            rng = random.Random(f"post_followup_window:{int(chat_id or 0)}:{today_local}")
            candidate_slots = [rng.choice(["morning", "day", "evening"])]
    updates: Dict[str, str] = {}
    for slot in candidate_slots:
        sent_col = _POST_FOLLOWUP_SLOT_COLUMNS[slot]
        if str(row.get(sent_col) or "") == today_local:
            continue
        planned = _post_followup_random_planned_utc(chat_id, today_local, slot)
        if planned:
            updates[_POST_FOLLOWUP_PLANNED_COLUMNS[slot]] = planned
    now = _now_utc_iso()
    set_parts = ["followup_plan_date=?"]
    params: List[Any] = [today_local]
    for col, val in updates.items():
        set_parts.append(f"{col}=?")
        params.append(val)
    set_parts.append("updated_at=?")
    params.append(now)
    params.append(int(chat_id))
    async with aiosqlite.connect(db_path) as db:
        await db.execute(f"UPDATE post_manual_followup_state SET {', '.join(set_parts)} WHERE chat_id=?", params)
        await db.commit()
    row = dict(row)
    row["followup_plan_date"] = today_local
    row.update(updates)
    return row


def _post_followup_due_slot(row: Dict[str, Any], now_utc_dt: datetime, today_local: str) -> Optional[str]:
    for slot, planned_col in _POST_FOLLOWUP_PLANNED_COLUMNS.items():
        sent_col = _POST_FOLLOWUP_SLOT_COLUMNS[slot]
        if str(row.get(sent_col) or "") == today_local:
            continue
        planned_raw = str(row.get(planned_col) or "").strip()
        if not planned_raw:
            continue
        planned_dt = _tp_utc_parse(planned_raw)
        if planned_dt and now_utc_dt >= planned_dt:
            return slot
    return None


async def _post_followup_window_counts(db_path: str, manager_key: str, now_utc_dt: datetime) -> Tuple[int, int]:
    """Approximate per-manager hourly/daily send caps using last_sent_at_utc across leads."""
    hour_cutoff = (now_utc_dt - timedelta(hours=1)).isoformat()
    day_cutoff = (now_utc_dt - timedelta(hours=24)).isoformat()
    async with aiosqlite.connect(db_path) as db:
        cur = await db.execute("SELECT COUNT(*) FROM post_manual_followup_state WHERE manager_key=? AND last_sent_at_utc>=?", (manager_key, hour_cutoff))
        hour_count = int((await cur.fetchone())[0] or 0)
        cur = await db.execute("SELECT COUNT(*) FROM post_manual_followup_state WHERE manager_key=? AND last_sent_at_utc>=?", (manager_key, day_cutoff))
        day_count = int((await cur.fetchone())[0] or 0)
    return hour_count, day_count


async def _record_incoming_from_manager(event: events.NewMessage.Event) -> None:
    if CONTROLLER_MODE or not MANAGER_RUNTIME_KEY or not event.is_private:
        return
    chat_id = int(event.chat_id or 0)
    if chat_id <= 0:
        return
    text = str(getattr(event, "raw_text", None) or "").strip()
    if event.out:
        msg_id = int(getattr(event.message, "id", 0) or 0)
        if not _is_program_sent(chat_id, msg_id):
            if text and _profile_request_words(text):
                await _open_profile_capture(DB_PATH, chat_id, MANAGER_RUNTIME_KEY, "manual_question")
            await _mark_manager_replied(DB_PATH, chat_id)
            if _is_post_followup_disable_word(text):
                try:
                    await _set_post_followup_disabled(DB_PATH, chat_id, True, user_id=0, reason="manual_stop_keyword")
                    print(f"followup keyword-stop chat_id={chat_id} manager={MANAGER_RUNTIME_KEY}")
                except Exception:
                    pass
            else:
                try:
                    await _post_followup_note_manager_out(DB_PATH, chat_id, MANAGER_RUNTIME_KEY)
                except Exception:
                    pass
        return
    if callable(_TPILOT_202605_ORIG_RECORD_INCOMING):
        await _TPILOT_202605_ORIG_RECORD_INCOMING(event)


async def _tp_tcp_proxy_check(host: str, port: int, timeout: float = 8.0) -> Tuple[bool, str]:
    try:
        with _tp_socket.create_connection((str(host), int(port)), timeout=float(timeout)):
            return True, "tcp ok"
    except Exception as e:
        return False, f"tcp error: {type(e).__name__}: {e}"


async def _tp_telethon_proxy_check(host: str, port: int, login: str = "", password: str = "") -> Tuple[bool, str]:
    if socks is None:
        return False, "PySocks не установлен"
    if _TP_StringSession is None:
        return False, "Telethon StringSession недоступен"
    proxy = (socks.SOCKS5, str(host), int(port), True, str(login or "") or None, str(password or "") or None)
    tmp = TelegramClient(_TP_StringSession(), API_ID, API_HASH, proxy=proxy)
    try:
        await tmp.connect()
        return (True, "telethon ok") if await tmp.is_connected() else (False, "telethon не подключился")
    except Exception as e:
        return False, f"telethon error: {type(e).__name__}: {e}"
    finally:
        try:
            await tmp.disconnect()
        except Exception:
            pass


def _tp_parse_proxy_one_line(raw: str) -> Tuple[str, int, str, str]:
    """Thin wrapper around the central proxy_parser.parse_proxy_line.
    Preserves the historical ("", 0, "", "") failure return and now accepts
    every format proxy_parser supports (previously only strict
    host:port:login:password)."""
    parsed = proxy_parser.parse_proxy_line(raw, default_scheme="socks5")
    if not parsed:
        return "", 0, "", ""
    return (
        parsed["host"],
        int(parsed["port"]),
        parsed.get("login") or "",
        parsed.get("password") or "",
    )


async def _panel_manager_proxy_command(action: str, args: str, *, requested_by: int = 0) -> str:
    action = str(action or "").strip().lower()
    raw = str(args or "").strip()
    if action == "set":
        parts = raw.split(maxsplit=1)
        if len(parts) >= 2 and ":" in parts[1] and "SOCKS5" not in raw.upper():
            key = registry_normalize_manager_key(parts[0])
            host, port, login, password = _tp_parse_proxy_one_line(parts[1])
            if not key or not host or not port:
                return "Формат: /manager_proxy_set <manager_key> host:port:login:password"
            if not await manager_get(key):
                return f"Менеджер не найден: {key}"
            ok_tcp, tcp_msg = await _tp_tcp_proxy_check(host, port)
            ok_tel, tel_msg = (False, "telethon check skipped")
            if ok_tcp:
                ok_tel, tel_msg = await _tp_telethon_proxy_check(host, port, login, password)
            test_ok = 1 if (ok_tcp and ok_tel) else 0
            now = _now_utc_iso()
            await manager_set_fields(key, proxy_type="socks5", proxy_host=host, proxy_port=int(port), proxy_username=login, proxy_password=password, proxy_enabled=1 if test_ok else 0, proxy_updated_at=now, proxy_test_ok=test_ok, proxy_test_at=now, proxy_last_error="" if test_ok else f"{tcp_msg}; {tel_msg}", proxy_bypass_allowed=0, proxy_bypass_by=0, proxy_bypass_at="", proxy_bypass_reason="")
            row2 = await manager_get(key) or {}
            status_line = "✅ прокси подключён" if test_ok else "⚠️ прокси не подключён"
            reason = "" if test_ok else f"\nПричина: {tcp_msg}; {tel_msg}"
            return status_line + "\n" + _manager_proxy_info_text(row2) + reason
    if callable(_TPILOT_202605_ORIG_PANEL_PROXY):
        return await _TPILOT_202605_ORIG_PANEL_PROXY(action, args, requested_by=requested_by)
    return "Proxy handler missing."


async def _tp_build_duplicates_text(args: str = "31d") -> str:
    token = str(args or "31d").strip().lower()
    now = _kyiv_now().date()
    chat_filter = 0
    if token.startswith("chat"):
        ps = token.split()
        if len(ps) >= 2:
            try:
                chat_filter = int(ps[1])
            except Exception:
                chat_filter = 0
        start_d = now - timedelta(days=3650)
        end_d = now
    elif token in ("today", "сегодня", ""):
        start_d = end_d = now
    elif token in ("yesterday", "вчера"):
        start_d = end_d = now - timedelta(days=1)
    else:
        start_d = now - timedelta(days=30)
        end_d = now
    seen = set()
    for mgr in await _manager_rows_for_reporting():
        db_path = str(mgr.get("db_path") or "")
        if not db_path or not os.path.exists(db_path):
            continue
        try:
            await _ensure_daily_leads_table(db_path)
            async with aiosqlite.connect(db_path) as db:
                if chat_filter:
                    cur = await db.execute("SELECT DISTINCT chat_id FROM daily_leads WHERE chat_id=?", (chat_filter,))
                else:
                    cur = await db.execute("SELECT DISTINCT chat_id FROM daily_leads WHERE duplicate=1 AND lead_date BETWEEN ? AND ?", (start_d.isoformat(), end_d.isoformat()))
                for r in await cur.fetchall():
                    cid = int(r[0] or 0)
                    if cid:
                        seen.add(cid)
        except Exception:
            pass
    blocks = []
    for cid in sorted(seen):
        hist = await _tp_duplicate_history(cid)
        managers = {registry_normalize_manager_key(x.get("manager_key") or "") for x in hist if registry_normalize_manager_key(x.get("manager_key") or "")}
        if len(hist) >= 2 and len(managers) >= 2:
            blocks.append((cid, hist))
    if not blocks:
        return "🔁 Дубликаты\n\nДубликаты не найдены."
    lines = ["🔁 Дубликаты", f"Период: {start_d.strftime('%d.%m.%y')} - {end_d.strftime('%d.%m.%y')}", f"Найдено chat_id: {len(blocks)}"]
    for cid, hist in blocks[:20]:
        lines.extend(["", f"chat_id: {cid}"])
        for i, item in enumerate(hist[:5], 1):
            lines.extend(_tp_format_history_item(item, i))
            lines.append("")
        if len(hist) > 5:
            lines.append(f"Показано 5 из {len(hist)} повторов")
    if len(blocks) > 20:
        lines.append(f"Показано 20 из {len(blocks)} chat_id. Для полного списка используйте Excel.")
    return chr(10).join(lines).rstrip()


async def _tp_export_duplicates_excel(args: str = "31d") -> Tuple[bool, str, str, str]:
    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font, Alignment
        from openpyxl.utils import get_column_letter
    except Exception:
        return False, "", "openpyxl не установлен", ""
    now = _kyiv_now().date()
    token = str(args or "31d").strip().lower()
    start_d = now if token in ("today", "сегодня") else (now - timedelta(days=1) if token in ("yesterday", "вчера") else now - timedelta(days=30))
    end_d = start_d if token in ("today", "сегодня", "yesterday", "вчера") else now
    ids = set()
    for mgr in await _manager_rows_for_reporting():
        db_path = str(mgr.get("db_path") or "")
        if not db_path or not os.path.exists(db_path):
            continue
        try:
            await _ensure_daily_leads_table(db_path)
            async with aiosqlite.connect(db_path) as db:
                cur = await db.execute("SELECT DISTINCT chat_id FROM daily_leads WHERE duplicate=1 AND lead_date BETWEEN ? AND ?", (start_d.isoformat(), end_d.isoformat()))
                for r in await cur.fetchall():
                    if int(r[0] or 0):
                        ids.add(int(r[0]))
        except Exception:
            pass
    os.makedirs(EXPORT_DIR, exist_ok=True)
    out_path = os.path.join(EXPORT_DIR, f"duplicates_{start_d.isoformat()}_{end_d.isoformat()}.xlsx")
    wb = Workbook()
    ws = wb.active
    ws.title = "duplicates"
    headers = ["chat_id блока", "№ обращения", "Дата", "Время", "manager_key", "Аккаунт менеджера", "username клиента", "Имя клиента", "Телефон", "Источник", "Статус", "Возраст", "Город", "Страна"]
    ws.append(headers)
    for c in ws[1]:
        c.font = Font(bold=True)
        c.alignment = Alignment(horizontal="center")
    row_idx = 2
    for cid in sorted(ids):
        hist = await _tp_duplicate_history(cid)
        managers = {registry_normalize_manager_key(x.get("manager_key") or "") for x in hist if registry_normalize_manager_key(x.get("manager_key") or "")}
        if len(hist) < 2 or len(managers) < 2:
            continue
        ws.append([f"chat_id {cid}"] + [""] * (len(headers)-1))
        ws[row_idx][0].font = Font(bold=True)
        row_idx += 1
        for i, r in enumerate(hist, 1):
            dt = _utc_iso_to_kyiv_dt(str(r.get("first_seen_utc") or ""))
            mu = str(r.get("manager_username") or "").strip().lstrip("@")
            md = str(r.get("manager_display_name") or r.get("manager_key") or "").strip()
            account = f"{md} | @{mu}" if mu else md
            cu = str(r.get("username") or "").strip().lstrip("@")
            ws.append([cid, i, dt.strftime("%d.%m.%Y"), dt.strftime("%H:%M:%S"), str(r.get("manager_key") or ""), account, f"@{cu}" if cu else "", str(r.get("full_name") or ""), str(r.get("phone") or ""), str(r.get("source_key") or ""), str(r.get("status") or ""), str(r.get("age") or ""), str(r.get("city") or ""), str(r.get("country") or "")])
            row_idx += 1
    for i, w in enumerate([18, 12, 14, 12, 18, 30, 24, 28, 18, 18, 16, 10, 22, 18], 1):
        ws.column_dimensions[get_column_letter(i)].width = w
    ws.freeze_panes = "A2"
    wb.save(out_path)
    return True, out_path, "", f"🔁 Дубликаты Excel | {start_d.strftime('%d.%m.%y')} - {end_d.strftime('%d.%m.%y')}"


async def _panel_execute_command_text(command_text: str, *, requested_by: int = 0) -> Dict[str, Any]:
    cmd, args = _parse_cmd(str(command_text or "").strip())
    if cmd == "/duplicates":
        parts = (args or "31d").split()
        if parts and parts[0].lower() in ("excel", "export", "xlsx"):
            ok, path, err, caption = await _tp_export_duplicates_excel(" ".join(parts[1:]) or "31d")
            if not ok:
                return {"ok": False, "error_text": err or "Ошибка Excel по дублям."}
            return {"ok": True, "result_text": "🔁 Excel по дублям готов.", "result_file": path, "result_caption": caption}
        return {"ok": True, "result_text": await _tp_build_duplicates_text(args or "31d")}
    if cmd == "/manager_delete_full":
        return {"ok": True, "result_text": await _panel_manager_delete_full_command(args, requested_by=requested_by)}
    if cmd == "/manager_danger_log":
        return {"ok": True, "result_text": await _panel_manager_danger_log_command(args, requested_by=requested_by)}
    if cmd == "/manager_db_clear":
        return {"ok": True, "result_text": await _panel_manager_db_clear_command(args, requested_by=requested_by)}
    if cmd == "/manager_db_restore":
        return {"ok": True, "result_text": await _panel_manager_db_restore_command(args, requested_by=requested_by)}
    if cmd == "/manager_proxy_check":
        return {"ok": True, "result_text": await _panel_manager_proxy_command("check", args, requested_by=requested_by)}
    if cmd == "/followup":
        return {"ok": True, "result_text": await _handle_post_followup_command(args, user_id=requested_by)}
    if cmd == "/silent" and not callable(globals().get("_handle_silent_command")):
        return {"ok": True, "result_text": "🔇 Тихий режим сейчас управляется через раздел 💬 Автоответы к��иентам и ⚙️ Анкета."}
    if callable(_TPILOT_202605_ORIG_PANEL_EXEC):
        return await _TPILOT_202605_ORIG_PANEL_EXEC(command_text, requested_by=requested_by)
    return {"ok": False, "error_text": f"Команда не поддерживается в панели: {cmd}"}


async def _handle_ai_stat_command(event: events.NewMessage.Event) -> bool:
    if CONTROLLER_MODE and int(event.chat_id or 0) == int(AI_STAT_CHAT_ID or 0):
        cmd, args = _parse_cmd((event.raw_text or "").strip())
        if cmd == "/duplicates":
            parts = (args or "31d").split()
            if parts and parts[0].lower() in ("excel", "export", "xlsx"):
                ok, path, err, caption = await _tp_export_duplicates_excel(" ".join(parts[1:]) or "31d")
                if ok:
                    await _send_ai_file(path, caption=caption)
                else:
                    await client.send_message(event.chat_id, err or "Ошибка Excel по дублям.")
                return True
            await client.send_message(event.chat_id, await _tp_build_duplicates_text(args or "31d"))
            return True
    if callable(_TPILOT_202605_ORIG_HANDLE_AI):
        return await _TPILOT_202605_ORIG_HANDLE_AI(event)
    return False


async def main() -> None:
    if MANAGER_RUNTIME_KEY and callable(globals().get("_manager_command_loop")):
        try:
            client.loop.create_task(_manager_command_loop())
        except Exception as e:
            print(f"manager_command_loop task start error: {e!r}")
    if callable(_TPILOT_202605_ORIG_MAIN):
        await _TPILOT_202605_ORIG_MAIN()

