def _content_now_iso() -> str:
    try:
        return _tp_utc_now().replace(microsecond=0).isoformat()
    except Exception:
        return ""


def _content_db_path() -> str:
    return str(globals().get("TPILOT_DB_PATH") or os.getenv("TPILOT_DB_PATH") or os.getenv("QUEUE_DB_PATH") or os.getenv("DB_PATH") or "")


def _content_connect():
    path = _content_db_path()
    if not path:
        raise RuntimeError("TPILOT_DB_PATH is empty")
    parent = os.path.dirname(os.path.abspath(path))
    if parent:
        os.makedirs(parent, exist_ok=True)
    con = _tp_content_sqlite3.connect(path, timeout=30)
    con.row_factory = _tp_content_sqlite3.Row
    try:
        con.execute("PRAGMA journal_mode=WAL;")
    except Exception:
        pass
    return con


def _content_ensure_tables() -> None:
    con = _content_connect()
    try:
        con.execute("CREATE TABLE IF NOT EXISTS content_texts(key TEXT PRIMARY KEY, value TEXT NOT NULL DEFAULT '', updated_by TEXT DEFAULT '', updated_at TEXT NOT NULL DEFAULT '')")
        con.execute("CREATE TABLE IF NOT EXISTS content_delays(key TEXT PRIMARY KEY, min_value REAL NOT NULL DEFAULT 0, max_value REAL NOT NULL DEFAULT 0, updated_by TEXT DEFAULT '', updated_at TEXT NOT NULL DEFAULT '')")
        con.execute("CREATE TABLE IF NOT EXISTS content_template_variants(id INTEGER PRIMARY KEY AUTOINCREMENT, category TEXT NOT NULL DEFAULT '', text TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, created_by TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT '')")
        con.execute("CREATE INDEX IF NOT EXISTS content_template_variants_cat_idx ON content_template_variants(category, enabled, id)")
        con.execute("CREATE TABLE IF NOT EXISTS content_change_log(id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL DEFAULT '', key TEXT NOT NULL DEFAULT '', old_value TEXT DEFAULT '', new_value TEXT DEFAULT '', changed_by TEXT DEFAULT '', changed_at TEXT NOT NULL DEFAULT '')")
        con.commit()
    finally:
        con.close()


