async def _handle_content_command(args: str, *, user_id: int = 0) -> dict:
    raw = str(args or "").strip()
    if not raw or raw.lower() in {"status", "help", "?"}:
        return {"ok": True, "result_text": "📝 Тексты и задержки\n\n" + _content_format_delays()}
    parts = raw.split()
    if not parts:
        return {"ok": True, "result_text": "📝 Тексты и задержки"}
    section = parts[0].lower()
    try:
        if section == "reset" and len(parts) >= 3 and parts[1].lower() == "all" and parts[2].lower() == "confirm":
            t = _content_reset_text("all", user_id=user_id)
            d = _content_reset_delay("all", user_id=user_id)
            con = _content_connect()
            try:
                con.execute("DELETE FROM content_template_variants")
                _content_log(con, "variant", "all", "custom", "default", user_id)
                con.commit()
            finally:
                con.close()
            return {"ok": True, "result_text": t + "\n" + d + "\n✅ Все шаблоны сброшены."}
        if section in {"texts", "text"}:
            if len(parts) == 1 or (len(parts) >= 2 and parts[1].lower() == "list"):
                return {"ok": True, "result_text": _content_format_texts()}
            if len(parts) >= 3 and parts[1].lower() == "get":
                key = parts[2]
                return {"ok": True, "result_text": f"📝 {_CONTENT_TEXT_LABELS.get(key, key)}\nКлюч: {key}\n\n{_content_get_text(key)}"}
            if len(parts) >= 4 and parts[1].lower() == "set":
                return {"ok": True, "result_text": _content_set_text(parts[2], raw.split(None, 3)[3], user_id=user_id)}
            if len(parts) >= 3 and parts[1].lower() == "reset":
                return {"ok": True, "result_text": _content_reset_text(parts[2], user_id=user_id)}
        if section in {"delays", "delay"}:
            if len(parts) == 1 or (len(parts) >= 2 and parts[1].lower() == "list"):
                return {"ok": True, "result_text": _content_format_delays()}
            if len(parts) >= 5 and parts[1].lower() == "set":
                return {"ok": True, "result_text": _content_set_delay(parts[2], parts[3], parts[4], user_id=user_id)}
            if len(parts) >= 3 and parts[1].lower() == "reset":
                return {"ok": True, "result_text": _content_reset_delay(parts[2], user_id=user_id)}
        if section in {"variant", "variants"}:
            if len(parts) >= 3 and parts[1].lower() == "list":
                return {"ok": True, "result_text": _content_format_variants(parts[2])}
            if len(parts) >= 4 and parts[1].lower() == "add":
                return {"ok": True, "result_text": _content_variant_add(parts[2], raw.split(None, 3)[3], user_id=user_id)}
            if len(parts) >= 5 and parts[1].lower() == "set":
                return {"ok": True, "result_text": _content_variant_set(parts[2], int(parts[3]), raw.split(None, 4)[4], user_id=user_id)}
            if len(parts) >= 4 and parts[1].lower() == "delete":
                return {"ok": True, "result_text": _content_variant_delete(parts[2], int(parts[3]), user_id=user_id)}
            if len(parts) >= 4 and parts[1].lower() == "toggle":
                return {"ok": True, "result_text": _content_variant_toggle(parts[2], int(parts[3]), user_id=user_id)}
            if len(parts) >= 3 and parts[1].lower() == "reset_category":
                return {"ok": True, "result_text": _content_variant_reset_category(parts[2], user_id=user_id)}
    except Exception as e:
        return {"ok": False, "error_text": repr(e)}
    return {"ok": False, "error_text": "Команда content не распознана."}


_CONTENT_ORIG_PANEL_EXECUTE_COMMAND_TEXT = globals().get("_panel_execute_command_text")
async def _panel_execute_command_text(command_text: str, *, requested_by: int = 0, source_chat_id: int = 0) -> dict:  # type: ignore[override]
    cmd, args = _parse_cmd(str(command_text or "")) if callable(globals().get("_parse_cmd")) else ("", "")
    if cmd == "/content":
        return await _handle_content_command(args, user_id=int(requested_by or 0))
    fn = _CONTENT_ORIG_PANEL_EXECUTE_COMMAND_TEXT
    if not callable(fn):
        return {"ok": False, "error_text": "Panel command handler missing."}
    try:
        return await fn(command_text, requested_by=requested_by, source_chat_id=source_chat_id)
    except TypeError as e:
        if "unexpected keyword argument 'source_chat_id'" in str(e):
            return await fn(command_text, requested_by=requested_by)
        raise


_CONTENT_ORIG_MAIN = globals().get("main")
async def main() -> None:  # type: ignore[override]
    try:
        _content_ensure_tables()
        _content_refresh_runtime_globals()
    except Exception as e:
        print(f"content editor init error: {e!r}")
    fn = _CONTENT_ORIG_MAIN
    return await fn() if callable(fn) else None
# --- TPILOT CONTENT EDITOR PATCH END ---

# -------------------- core admin safety guard --------------------
def _tpilot_core_required_symbols_check() -> None:
    """Fail fast if a future patch removes a handler used by PanelBot/admin commands."""
    required = [
        "_ensure_sources_groups_tables",
        "_manager_command_loop",
        "_panel_manager_lifecycle_command",
        "_panel_manager_proxy_command",
        "_handle_source_command",
        "_handle_mgroup_command",
        "_handle_partner_command",
        "_handle_quality_command",
        "_handle_funnel_command",
        "_panel_execute_command_text",
    ]
    missing = [name for name in required if not callable(globals().get(name))]
    if missing:
        raise RuntimeError(
            "TPilot core integrity check failed. Missing required handler(s): "
            + ", ".join(missing)
        )



