async def _tpilot_proxy_check_v2_tcp(host: str, port: int, timeout: float = 8.0):
    try:
        import socket as _socket
        with _socket.create_connection((str(host), int(port)), timeout=float(timeout)):
            return True, "tcp ok"
    except Exception as e:
        return False, f"tcp error: {type(e).__name__}: {e}"


async def _tpilot_proxy_check_v2_telegram(host: str, port: int, login: str = "", password: str = ""):
    if socks is None:
        return False, "PySocks не установлен"
    try:
        from telethon.sessions import StringSession as _StringSession
        proxy = (socks.SOCKS5, str(host), int(port), True, str(login or "") or None, str(password or "") or None)
        tmp_client = TelegramClient(_StringSession(), API_ID, API_HASH, proxy=proxy)
        try:
            await tmp_client.connect()
            if tmp_client.is_connected():
                return True, "telegram ok"
            return False, "telegram не подключился"
        finally:
            try:
                await tmp_client.disconnect()
            except Exception:
                pass
    except Exception as e:
        return False, f"telegram error: {type(e).__name__}: {e}"


async def _tpilot_proxy_check_v2_command(args: str, *, requested_by: int = 0) -> str:
    parts = str(args or "").strip().split()
    key = registry_normalize_manager_key(parts[0] if parts else "")
    if not key:
        return "Формат: /manager_proxy_check <manager_key>"

    row = await manager_get(key)
    if not row or str(row.get("status") or "") == "archived":
        return f"Менеджер не найден: {key}"

    host = str(row.get("proxy_host") or "").strip()
    port = _proxy_port_int(row.get("proxy_port"))
    login = str(row.get("proxy_username") or "").strip()
    password = str(row.get("proxy_password") or "").strip()

    if not host or not port:
        now = _now_utc_iso()
        try:
            await manager_set_fields(key, proxy_test_ok=0, proxy_test_at=now, proxy_last_error="proxy не задан")
        except Exception:
            pass
        return f"❌ Прокси не подключён для {key}\nПричина: proxy не задан."

    tcp_fn = globals().get("_tp_tcp_proxy_check")
    tg_fn = globals().get("_tp_telethon_proxy_check")
    if not callable(tcp_fn):
        tcp_fn = _tpilot_proxy_check_v2_tcp
    if not callable(tg_fn):
        tg_fn = _tpilot_proxy_check_v2_telegram

    ok_tcp, tcp_msg = await tcp_fn(host, int(port))
    ok_tg, tg_msg = False, "telegram check skipped"
    if ok_tcp:
        ok_tg, tg_msg = await tg_fn(host, int(port), login, password)

    test_ok = bool(ok_tcp and ok_tg)
    reason = "" if test_ok else f"{tcp_msg}; {tg_msg}"
    now = _now_utc_iso()
    try:
        await manager_set_fields(
            key,
            proxy_test_ok=1 if test_ok else 0,
            proxy_test_at=now,
            proxy_last_error=reason,
        )
    except Exception:
        pass

    row2 = await manager_get(key) or row
    head = "✅ Прокси подключён" if test_ok else "❌ Прокси не подключён"
    lines = [
        f"{head} для {key}",
        "",
        _manager_proxy_info_text(row2),
        "",
        f"TCP: {tcp_msg}",
        f"Telegram: {tg_msg}",
    ]
    if not test_ok and reason:
        lines.extend(["", f"Причина: {reason}"])
    return "\n".join(str(x).rstrip() for x in lines if str(x).strip()).rstrip()


async def _panel_manager_proxy_command(action: str, args: str, *, requested_by: int = 0) -> str:
    action = str(action or "").strip().lower()
    if action == "check":
        return await _tpilot_proxy_check_v2_command(args, requested_by=requested_by)
    if callable(_TPILOT_PROXY_CHECK_V2_ORIG_PANEL_PROXY):
        return await _TPILOT_PROXY_CHECK_V2_ORIG_PANEL_PROXY(action, args, requested_by=requested_by)
    return "Команда proxy не распознана."


