def _tpilot_proxy_parse_set_args_v5(args: str):
    """Active parser for /manager_proxy_set <key> SOCKS5 <...>. The leading
    <key> and the literal SOCKS5 token are TPilot-specific and stay parsed
    here; everything after them is handed to the central proxy_parser,
    which now understands every supported proxy string format (not just
    the old strict host:port / host:port:login:password)."""
    parts = str(args or "").strip().split()
    key = registry_normalize_manager_key(parts[0] if len(parts) >= 1 else "")
    ptype = _proxy_type_norm(parts[1] if len(parts) >= 2 else "")
    if not key or ptype != "socks5":
        return None
    rest = parts[2:]
    if not rest:
        return None
    if len(rest) == 1:
        proxy_text = rest[0]
    else:
        host_tok = rest[0]
        port_tok = rest[1]
        login_tok = rest[2] if len(rest) >= 3 else ""
        password_tok = rest[3] if len(rest) >= 4 else ""
        proxy_text = f"{host_tok}:{port_tok}"
        if login_tok or password_tok:
            proxy_text += f":{login_tok or '-'}:{password_tok or '-'}"
    parsed = proxy_parser.parse_proxy_line(proxy_text, default_scheme="socks5")
    if not parsed or parsed.get("scheme") != "socks5":
        return None
    host = parsed["host"]
    port_i = parsed["port"]
    username = parsed.get("login") or ""
    password = parsed.get("password") or ""
    if not host or not port_i:
        return None
    return key, "socks5", host, int(port_i), username, password


