_TPILOT_PANEL_MANAGER_ROUTER_ORIG_EXEC = globals().get("_panel_execute_command_text")


def _tpilot_panel_manager_router_missing(handler_name: str) -> Dict[str, Any]:
    return {
        "ok": False,
        "error_text": (
            f"Panel-router найден, но обработчик {handler_name} отсутствует в активном main.py.\n"
            "Проверьте, что применён полный manager-router hotfix и перезапущен TPilot."
        ),
    }


async def _tpilot_panel_manager_router_call(handler_name: str, *args, requested_by: int = 0):
    fn = globals().get(handler_name)
    if not callable(fn):
        return _tpilot_panel_manager_router_missing(handler_name)
    return {"ok": True, "result_text": await fn(*args, requested_by=requested_by)}


async def _tpilot_panel_manager_proxy_check_router(args: str, *, requested_by: int = 0):
    # Prefer the newest proxy check implementation when it exists.
    for handler_name in (
        "_tpilot_proxy_check_v5_command",
        "_tpilot_proxy_check_v4_command",
        "_tpilot_proxy_check_v3_command",
        "_tp_proxy_check_command",
    ):
        fn = globals().get(handler_name)
        if callable(fn):
            return {"ok": True, "result_text": await fn(args, requested_by=requested_by)}
    fn = globals().get("_panel_manager_proxy_command")
    if callable(fn):
        return {"ok": True, "result_text": await fn("check", args, requested_by=requested_by)}
    return _tpilot_panel_manager_router_missing("_tpilot_proxy_check_v5_command/_panel_manager_proxy_command")


async def _tpilot_panel_manager_proxy_bypass_command(args: str, *, requested_by: int = 0) -> str:
    parts = str(args or "").strip().split()
    key = registry_normalize_manager_key(parts[0] if parts else "")
    confirmed = len(parts) >= 2 and str(parts[1]).strip().lower() in {"__panel_confirmed__", "confirm", "yes", "да"}
    if not key or not confirmed:
        return "Формат: /manager_proxy_bypass <manager_key> __panel_confirmed__"
    row = await manager_get(key)
    if not row or str(row.get("status") or "") == "archived":
        missing_fn = globals().get("_panel_manager_missing_text")
        return missing_fn(key) if callable(missing_fn) else f"Менеджер не найден: {key}"
    await manager_set_fields(
        key,
        proxy_enabled=0,
        proxy_bypass_allowed=1,
        proxy_bypass_by=int(requested_by or 0),
        proxy_bypass_at=_now_utc_iso(),
        proxy_bypass_reason="panel_confirmed",
        proxy_last_error="",
    )
    return "\n".join([
        f"🔓 Подключение без proxy разрешено для {key}",
        "",
        "Теперь PHONE/CODE/PASS можно вводить без проверки proxy.",
        "Если позже понадобится proxy, добавьте SOCKS5 одной строкой и проверьте подключение.",
    ]).rstrip()


async def _panel_execute_command_text(command_text: str, *, requested_by: int = 0, source_chat_id: int = 0, response_chat_id: int = 0) -> Dict[str, Any]:
    text = str(command_text or "").strip()
    cmd, args = _parse_cmd(text)

    if cmd == "/manager_add":
        return await _tpilot_panel_manager_router_call("_panel_manager_add_command", args, requested_by=requested_by)
    if cmd == "/manager_phone":
        return await _tpilot_panel_manager_router_call("_panel_manager_phone_command", args, requested_by=requested_by)
    if cmd == "/manager_code":
        return await _tpilot_panel_manager_router_call("_panel_manager_code_command", args, requested_by=requested_by)
    if cmd == "/manager_pass":
        return await _tpilot_panel_manager_router_call("_panel_manager_pass_command", args, requested_by=requested_by)

    if cmd == "/manager_list":
        return await _tpilot_panel_manager_router_call("_panel_manager_list_command", args, requested_by=requested_by)
    if cmd == "/manager_info":
        return await _tpilot_panel_manager_router_call("_panel_manager_info_command", args, requested_by=requested_by)

    lifecycle_map = {
        "/manager_start": "start",
        "/manager_stop": "stop",
        "/manager_enable": "enable",
        "/manager_disable": "disable",
        "/manager_pause": "pause",
        "/manager_remove": "remove",
    }
    if cmd in lifecycle_map:
        fn = globals().get("_panel_manager_lifecycle_command")
        if not callable(fn):
            return _tpilot_panel_manager_router_missing("_panel_manager_lifecycle_command")
        return {"ok": True, "result_text": await fn(lifecycle_map[cmd], args, requested_by=requested_by)}

    if cmd == "/manager_rename":
        return await _tpilot_panel_manager_router_call("_panel_manager_rename_command", args, requested_by=requested_by)
    if cmd == "/manager_reset":
        return await _tpilot_panel_manager_router_call("_panel_manager_reset_command", args, requested_by=requested_by)
    if cmd == "/manager_delete_full":
        return await _tpilot_panel_manager_router_call("_panel_manager_delete_full_command", args, requested_by=requested_by)
    if cmd == "/manager_db_clear":
        return await _tpilot_panel_manager_router_call("_panel_manager_db_clear_command", args, requested_by=requested_by)
    if cmd == "/manager_db_restore":
        return await _tpilot_panel_manager_router_call("_panel_manager_db_restore_command", args, requested_by=requested_by)
    if cmd == "/manager_danger_log":
        return await _tpilot_panel_manager_router_call("_panel_manager_danger_log_command", args, requested_by=requested_by)

    if cmd in ("/manager_proxy_info", "/manager_proxy_on", "/manager_proxy_off", "/manager_proxy_set"):
        action = cmd.replace("/manager_proxy_", "", 1)
        fn = globals().get("_panel_manager_proxy_command")
        if not callable(fn):
            return _tpilot_panel_manager_router_missing("_panel_manager_proxy_command")
        return {"ok": True, "result_text": await fn(action, args, requested_by=requested_by)}
    if cmd == "/manager_proxy_check":
        return await _tpilot_panel_manager_proxy_check_router(args, requested_by=requested_by)
    if cmd == "/manager_proxy_bypass":
        return {"ok": True, "result_text": await _tpilot_panel_manager_proxy_bypass_command(args, requested_by=requested_by)}

    if callable(_TPILOT_PANEL_MANAGER_ROUTER_ORIG_EXEC):
        try:
            return await _TPILOT_PANEL_MANAGER_ROUTER_ORIG_EXEC(
                command_text,
                requested_by=requested_by,
                source_chat_id=source_chat_id,
                response_chat_id=response_chat_id,
            )
        except TypeError:
            try:
                return await _TPILOT_PANEL_MANAGER_ROUTER_ORIG_EXEC(command_text, requested_by=requested_by)
            except TypeError:
                return await _TPILOT_PANEL_MANAGER_ROUTER_ORIG_EXEC(command_text)
    return {"ok": False, "error_text": f"Команда не поддерживается в панели: {cmd or text}"}
