def _tpag_safe_print(value: object = "") -> None:
    text = str(value or "")
    try:
        print(text)
    except Exception:
        try:
            sys.stdout.buffer.write((text + "\n").encode("utf-8", errors="backslashreplace"))
            sys.stdout.flush()
        except Exception:
            pass


