# V2 fix: always read/write manager registry from TPILOT_DB_PATH, not from per-manager DB_PATH.
async def _tpag_registry_get(key: str) -> Optional[Dict[str, Any]]:
    await _tpag_ensure_schema()
    key = registry_normalize_manager_key(key or "")
    if not key:
        return None
    try:
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute("SELECT * FROM managers WHERE manager_key=? LIMIT 1", (key,))
            row = await cur.fetchone()
            return dict(row) if row else None
    except Exception:
        return None


async def _tpag_registry_set_fields(key: str, **fields: Any) -> None:
    await _tpag_ensure_schema()
    key = registry_normalize_manager_key(key or "")
    if not key or not fields:
        return
    clean: Dict[str, Any] = {}
    try:
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            cur = await db.execute("PRAGMA table_info(managers)")
            cols = {str(r[1]) for r in await cur.fetchall()}
            for k, v in fields.items():
                if str(k) in cols:
                    clean[str(k)] = v
            if not clean:
                return
            clean["updated_at"] = _now_utc_iso()
            sets = ", ".join([f"{k}=?" for k in clean])
            vals = list(clean.values()) + [key]
            await db.execute(f"UPDATE managers SET {sets} WHERE manager_key=?", vals)
            await db.commit()
    except Exception:
        return
# --- TPILOT PROXY AUTH GUARD V3 REGISTRY DB FIX 20260509 END ---


async def _tpag_ensure_schema() -> None:
    try:
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            ddls = [
                "ALTER TABLE managers ADD COLUMN proxy_mode TEXT DEFAULT ''",
                "ALTER TABLE managers ADD COLUMN auth_guard_ok INTEGER NOT NULL DEFAULT 0",
                "ALTER TABLE managers ADD COLUMN auth_guard_checked_at TEXT DEFAULT ''",
                "ALTER TABLE managers ADD COLUMN auth_proxy_ip TEXT DEFAULT ''",
                "ALTER TABLE managers ADD COLUMN auth_proxy_country TEXT DEFAULT ''",
                "ALTER TABLE managers ADD COLUMN auth_proxy_city TEXT DEFAULT ''",
                "ALTER TABLE managers ADD COLUMN auth_proxy_region TEXT DEFAULT ''",
                "ALTER TABLE managers ADD COLUMN auth_direct_ip TEXT DEFAULT ''",
                "ALTER TABLE managers ADD COLUMN auth_direct_country TEXT DEFAULT ''",
                "ALTER TABLE managers ADD COLUMN auth_direct_city TEXT DEFAULT ''",
                "ALTER TABLE managers ADD COLUMN auth_direct_region TEXT DEFAULT ''",
                "ALTER TABLE managers ADD COLUMN auth_guard_error TEXT DEFAULT ''",
                "ALTER TABLE managers ADD COLUMN auth_guard_source TEXT DEFAULT ''",
                "ALTER TABLE managers ADD COLUMN auth_guard_last_bad_at TEXT DEFAULT ''",
                "ALTER TABLE managers ADD COLUMN auth_guard_last_ok_at TEXT DEFAULT ''",
                "ALTER TABLE managers ADD COLUMN auth_guard_notified_bad INTEGER NOT NULL DEFAULT 0",
            ]
            for ddl in ddls:
                try:
                    await db.execute(ddl)
                except Exception:
                    pass
            await db.execute("CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT)")
            await db.execute("CREATE TABLE IF NOT EXISTS panel_notifications(id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL DEFAULT '', title TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'new', created_at TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT '')")
            cur = await db.execute("SELECT value FROM settings WHERE key='tpag_v2_mode_migration_done'")
            row = await cur.fetchone()
            if not row:
                now = _now_utc_iso()
                await db.execute("UPDATE managers SET proxy_mode='proxy' WHERE COALESCE(proxy_mode,'')='' AND COALESCE(proxy_host,'')<>'' AND COALESCE(proxy_port,0)>0")
                await db.execute("""
                    UPDATE managers
                    SET proxy_mode='direct', proxy_enabled=0, proxy_bypass_allowed=1,
                        proxy_bypass_at=CASE WHEN COALESCE(proxy_bypass_at,'')='' THEN ? ELSE proxy_bypass_at END,
                        proxy_bypass_reason=CASE WHEN COALESCE(proxy_bypass_reason,'')='' THEN 'migration_existing_no_proxy' ELSE proxy_bypass_reason END,
                        auth_guard_ok=1,
                        auth_guard_checked_at=CASE WHEN COALESCE(auth_guard_checked_at,'')='' THEN ? ELSE auth_guard_checked_at END
                    WHERE COALESCE(proxy_mode,'')=''
                """, (now, now))
                await db.execute("INSERT OR REPLACE INTO settings(key,value) VALUES('tpag_v2_mode_migration_done','1')")
            await db.commit()
    except Exception:
        pass


def _tpag_mode(row: Dict[str, Any]) -> str:
    return _manager_auth_proxy_mode(row)


def _tpag_parse_dt(raw: Any) -> Optional[datetime]:
    txt = str(raw or "").strip()
    if not txt:
        return None
    try:
        dt = datetime.fromisoformat(txt.replace("Z", "+00:00"))
        if dt.tzinfo is not None:
            dt = dt.astimezone(timezone.utc).replace(tzinfo=None)
        return dt.replace(microsecond=0)
    except Exception:
        return None


def _tpag_fresh(row: Dict[str, Any]) -> bool:
    if int((row or {}).get("auth_guard_ok") or 0) != 1:
        return False
    checked = _tpag_parse_dt((row or {}).get("auth_guard_checked_at"))
    if not checked:
        return False
    age = (_tp_utc_now().replace(microsecond=0) - checked).total_seconds()
    return 0 <= age <= TPAG_V2_GUARD_TTL_SEC


def _tpag_http_direct_json(url: str, timeout: float = 8.0) -> Dict[str, Any]:
    req = _tpag_urllib_request.Request(url, headers={"User-Agent": "TPilotProxyGuard/2"})
    with _tpag_urllib_request.urlopen(req, timeout=timeout) as resp:
        raw = resp.read(200000).decode("utf-8", errors="replace")
    return _tpag_json.loads(raw)


def _tpag_geo_from_data(data: Dict[str, Any]) -> Dict[str, str]:
    return {
        "ip": str(data.get("query") or data.get("ip") or "").strip(),
        "country": str(data.get("country") or data.get("country_name") or "").strip(),
        "city": str(data.get("city") or "").strip(),
        "region": str(data.get("regionName") or data.get("region") or "").strip(),
    }


def _tpag_direct_geo() -> Dict[str, str]:
    data = _tpag_http_direct_json("http://ip-api.com/json/?fields=status,message,query,country,regionName,city", timeout=8)
    geo = _tpag_geo_from_data(data)
    if not geo.get("ip"):
        raise RuntimeError("direct external IP not detected")
    return geo


def _tpag_proxy_geo_via_socks(host: str, port: int, username: str = "", password: str = "", *, rdns: bool = True) -> Dict[str, str]:
    # LOCAL PROXY CHECK 20260711: rdns is now an explicit, backward-compatible
    # kwarg (default True, byte-identical to the previous hardcoded True) --
    # every existing caller (auth guard, stability probe) is unaffected. The
    # new AdminBot Proxy Pool check (_handle_proxy_pool_check_command) is the
    # only caller that ever passes rdns=False, as a socks5 fallback attempt
    # after a socks5h (rdns=True) attempt fails.
    if socks is None:
        raise RuntimeError("PySocks не установлен")
    s = socks.socksocket()
    s.set_proxy(socks.SOCKS5, str(host), int(port), bool(rdns), str(username or "") or None, str(password or "") or None)
    s.settimeout(10)
    try:
        s.connect(("ip-api.com", 80))
        request = (
            "GET /json/?fields=status,message,query,country,regionName,city HTTP/1.1\r\n"
            "Host: ip-api.com\r\n"
            "Connection: close\r\n"
            "User-Agent: TPilotProxyGuard/2\r\n\r\n"
        ).encode("ascii")
        s.sendall(request)
        chunks = []
        while True:
            part = s.recv(65536)
            if not part:
                break
            chunks.append(part)
        raw = b"".join(chunks).decode("utf-8", errors="replace")
    finally:
        try:
            s.close()
        except Exception:
            pass
    body = raw.split("\r\n\r\n", 1)[-1].strip()
    data = _tpag_json.loads(body)
    geo = _tpag_geo_from_data(data)
    if not geo.get("ip"):
        raise RuntimeError("proxy external IP not detected")
    return geo


def _tpag_tcp_check(host: str, port: int) -> str:
    try:
        with _tpag_socket.create_connection((str(host), int(port)), timeout=8):
            return "TCP OK"
    except Exception as e:
        raise RuntimeError(f"TCP FAIL: {e!r}")


async def _tpag_telethon_check(row: Dict[str, Any]) -> str:
    if _tpag_StringSession is None:
        raise RuntimeError("Telethon StringSession недоступен")
    _audit_manager_telethon_proxy("auth_guard", row, "(string_session)")
    proxy = _resolve_manager_telethon_proxy(row)
    if not proxy:
        raise RuntimeError("Telethon proxy dict не собран")
    tmp = TelegramClient(_tpag_StringSession(), API_ID, API_HASH, proxy=proxy)
    try:
        await asyncio.wait_for(tmp.connect(), timeout=15)
        return "Telethon OK"
    except Exception as e:
        raise RuntimeError(f"Telethon FAIL: {e!r}")
    finally:
        try:
            await tmp.disconnect()
        except Exception:
            pass


async def _tpag_save_guard(key: str, ok: bool, source: str, direct: Dict[str, str] | None = None, proxy: Dict[str, str] | None = None, error: str = "") -> None:
    await _tpag_ensure_schema()
    now = _now_utc_iso()
    fields = {
        "auth_guard_ok": 1 if ok else 0,
        "auth_guard_checked_at": now,
        "auth_guard_source": str(source or ""),
        "auth_guard_error": "" if ok else str(error or "")[:800],
    }
    direct = direct or {}
    proxy = proxy or {}
    for name, data, prefix in (("direct", direct, "auth_direct"), ("proxy", proxy, "auth_proxy")):
        fields[f"{prefix}_ip"] = str(data.get("ip") or "")
        fields[f"{prefix}_country"] = str(data.get("country") or "")
        fields[f"{prefix}_city"] = str(data.get("city") or "")
        fields[f"{prefix}_region"] = str(data.get("region") or "")
    if ok:
        fields["auth_guard_last_ok_at"] = now
        fields["auth_guard_notified_bad"] = 0
    else:
        fields["auth_guard_last_bad_at"] = now
    try:
        await _tpag_registry_set_fields(key, **fields)
    except Exception:
        # Fallback if storage.py was not migrated before this call.
        try:
            async with aiosqlite.connect(TPILOT_DB_PATH) as db:
                sets = ", ".join([f"{k}=?" for k in fields])
                vals = list(fields.values()) + [key]
                await db.execute(f"UPDATE managers SET {sets} WHERE manager_key=?", vals)
                await db.commit()
        except Exception:
            pass


async def _tpag_insert_notification(title: str, body: str, *, kind: str = "proxy_guard") -> None:
    # ONBOARDING SOURCE PICK 20260711: added the optional `kind` kwarg (default
    # unchanged: "proxy_guard", same as every existing call site) so the QR-login
    # path can route through kind="manager_source_pick" for source-pick buttons
    # in panel_bot.py's notification loop, without touching any other caller.
    try:
        await _tpag_ensure_schema()
        now = _now_utc_iso()
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute(
                "INSERT INTO panel_notifications(kind,title,body,status,created_at,updated_at) VALUES(?,?,?,?,?,?)",
                (str(kind or "proxy_guard"), str(title or ""), str(body or ""), "new", now, now),
            )
            await db.commit()
    except Exception:
        pass


def _tpag_geo_line(prefix: str, geo: Dict[str, str]) -> str:
    bits = [x for x in [geo.get("country"), geo.get("region"), geo.get("city")] if str(x or "").strip()]
    return f"{prefix}: " + (", ".join(bits) if bits else "не определено")


def _manager_proxy_info_text(row: Dict[str, Any]) -> str:  # type: ignore[override]
    row = dict(row or {})
    key = registry_normalize_manager_key(row.get("manager_key") or "")
    mode = _tpag_mode(row)
    host = str(row.get("proxy_host") or "").strip()
    port = str(row.get("proxy_port") or "").strip()
    login = _proxy_login_display(row.get("proxy_username"))
    password = _mask_secret(row.get("proxy_password"))
    checked = str(row.get("auth_guard_checked_at") or row.get("proxy_test_at") or "").strip() or "_"
    ok = int(row.get("auth_guard_ok") or 0) == 1
    fresh = _tpag_fresh(row)
    err = str(row.get("auth_guard_error") or row.get("proxy_last_error") or "").strip()
    if mode == "direct":
        lines = [
            f"🔓 Proxy {key}",
            "Режим: без proxy",
            "Telegram будет видеть IP сервера.",
            f"Server IP: {row.get('auth_direct_ip') or 'не определено'}",
        ]
        return "\n".join(lines).rstrip()
    guard = "🟢 готов" if ok and fresh else ("🟡 устарел" if ok else "🔴 не готов")
    lines = [
        f"🌐 Proxy {key}",
        "Режим: через proxy",
        f"SOCKS5: {host + ':' + port if host and port else 'не задан'}",
        f"Login: {login}",
        f"Password: {password}",
        "",
        f"Proxy IP: {row.get('auth_proxy_ip') or 'не определено'}",
        f"Proxy Geo: {', '.join([x for x in [row.get('auth_proxy_country'), row.get('auth_proxy_region'), row.get('auth_proxy_city')] if str(x or '').strip()]) or 'не определено'}",
        f"Server IP: {row.get('auth_direct_ip') or 'не опреде��ено'}",
        f"Server Geo: {', '.join([x for x in [row.get('auth_direct_country'), row.get('auth_direct_region'), row.get('auth_direct_city')] if str(x or '').strip()]) or 'не определено'}",
        "",
        f"Auth Guard: {guard}",
        f"Проверено: {checked}",
    ]
    if err and not (ok and fresh):
        lines.append(f"Причина: {err[:500]}")
    return "\n".join(lines).rstrip()


async def _tpag_proxy_command(action: str, args: str, *, requested_by: int = 0) -> str:
    await _tpag_ensure_schema()
    action = str(action or "").strip().lower()
    parts = str(args or "").strip().split()
    key = registry_normalize_manager_key(parts[0] if parts else "")
    if not key:
        return f"Формат: /manager_proxy_{action} <manager_key>"
    row = await _tpag_registry_get(key)
    if not row or str(row.get("status") or "") == "archived":
        return f"Менеджер не найден: {key}"
    if action == "info":
        return _manager_proxy_info_text(row)
    if action == "check":
        ok, text = await _tpag_run_guard(key, source="panel_check", force=True)
        return text
    if action == "set":
        parsed_fn = globals().get("_tpilot_proxy_parse_set_args_v5")
        parsed = parsed_fn(args) if callable(parsed_fn) else None
        if not parsed:
            return "Формат: /manager_proxy_set <key> SOCKS5 <host> <port> [login] [password]"
        key2, ptype, host, port, username, password = parsed
        await _tpag_registry_set_fields(
            key2,
            proxy_mode="proxy",
            proxy_type="socks5",
            proxy_host=host,
            proxy_port=int(port),
            proxy_username=username,
            proxy_password=password,
            proxy_enabled=1,
            proxy_bypass_allowed=0,
            proxy_updated_at=_now_utc_iso(),
            proxy_last_error="",
        )
        ok, text = await _tpag_run_guard(key2, source="panel_set", force=True)
        return text + ("\n\nProxy сохранён. Можно продолжать авторизацию." if ok else "")
    if action in ("on", "require"):
        await _tpag_registry_set_fields(key, proxy_mode="proxy", proxy_enabled=1, proxy_bypass_allowed=0, proxy_updated_at=_now_utc_iso(), proxy_last_error="")
        ok, text = await _tpag_run_guard(key, source="panel_on", force=True)
        return text
    if action in ("off", "direct", "bypass"):
        # TPILOT PREPARED ACCOUNTS PHASE 7B BLOCKER-2 FIX (2026-08-11): this
        # is the ONE runtime-effective transition into proxyless/direct mode
        # reachable from /manager_proxy_bypass -- _panel_execute_command_text
        # (main.py ~13551, the last override that matches this cmd group)
        # routes straight here, never through _tpilot_panel_manager_proxy_
        # bypass_command (~12916), which is dead code for this command. A
        # prepared QR/Phone account's first Telegram network use must never
        # happen without a bound proxy (see _manager_auth_proxy_mode/
        # _tpag_run_guard's direct-mode fallback) -- fail closed here,
        # BEFORE any field write, regardless of which caller/panel screen/
        # stale callback reached this command.
        if str(row.get("status") or "").strip().lower() == "prepared":
            return (
                f"⛔ Подключение без proxy недоступно для подготовленного аккаунта {key}.\n"
                "Для 💾Подготовленных аккаунтов (◻️ QR / 📱 Номер телефона) proxy обязателен "
                "до первого подключения к Telegram."
            )
        await _tpag_registry_set_fields(
            key,
            proxy_mode="direct",
            proxy_enabled=0,
            proxy_bypass_allowed=1,
            proxy_bypass_by=int(requested_by or 0) or None,
            proxy_bypass_at=_now_utc_iso(),
            proxy_bypass_reason="panel_confirmed_direct_mode",
            proxy_last_error="",
        )
        ok, text = await _tpag_run_guard(key, source="panel_direct", force=True)
        return text
    if callable(_TPAG_V2_ORIG_MANAGER_PROXY_COMMAND):
        return await _TPAG_V2_ORIG_MANAGER_PROXY_COMMAND(action, args, requested_by=requested_by)
    return "Команда proxy не распознана."


async def _panel_manager_proxy_command(action: str, args: str, *, requested_by: int = 0) -> str:  # type: ignore[override]
    return await _tpag_proxy_command(action, args, requested_by=requested_by)


async def _tpag_guard_for_onboarding_user(requested_by: int, source: str) -> Tuple[bool, str]:
    onboarding, err = await _panel_manager_onboarding(int(requested_by or 0))
    if not onboarding:
        return False, err
    key = registry_normalize_manager_key(onboarding.get("manager_key") or "")
    # Onboarding auth flow requires 3/3 consecutive small MTProto-connect samples,
    # tighter than the normal runtime-startup guard (min_consecutive_ok default 1).
    min_ok = 3 if str(source or "") in ("phone", "code", "pass") else 1
    return await _tpag_run_guard(key, source=source, force=True, min_consecutive_ok=min_ok)


async def _panel_manager_phone_command(args: str, *, requested_by: int = 0) -> str:  # type: ignore[override]
    ok, msg = await _tpag_guard_for_onboarding_user(int(requested_by or 0), "phone")
    if not ok:
        return msg
    onboarding, err = await _panel_manager_onboarding(int(requested_by or 0))
    if not onboarding:
        return err
    manager_key = registry_normalize_manager_key(onboarding.get("manager_key") or "")
    paths = _manager_runtime_paths_for_key(manager_key)
    row = await manager_get(manager_key) or {}
    session_err = _manager_proxy_onboarding_contaminated_session_error(dict(row), paths["session_path"])
    if session_err:
        return session_err
    if callable(_TPAG_V2_ORIG_PHONE):
        return await _TPAG_V2_ORIG_PHONE(args, requested_by=requested_by)
    return "PHONE handler не найден."


async def _panel_manager_code_command(args: str, *, requested_by: int = 0) -> str:  # type: ignore[override]
    ok, msg = await _tpag_guard_for_onboarding_user(int(requested_by or 0), "code")
    if not ok:
        return msg
    if callable(_TPAG_V2_ORIG_CODE):
        return await _TPAG_V2_ORIG_CODE(args, requested_by=requested_by)
    return "CODE handler не найден."


async def _panel_manager_pass_command(args: str, *, requested_by: int = 0) -> str:  # type: ignore[override]
    ok, msg = await _tpag_guard_for_onboarding_user(int(requested_by or 0), "pass")
    if not ok:
        return msg
    if callable(_TPAG_V2_ORIG_PASS):
        return await _TPAG_V2_ORIG_PASS(args, requested_by=requested_by)
    return "PASS handler не найден."


async def _panel_manager_lifecycle_command(action: str, args: str, *, requested_by: int = 0) -> str:  # type: ignore[override]
    if str(action or "").strip().lower() == "start":
        key = registry_normalize_manager_key(str(args or "").strip().split()[0] if str(args or "").strip().split() else "")
        if key:
            ok, msg = await _tpag_run_guard(key, source="manager_start", force=True)
            if not ok:
                return msg
    if callable(_TPAG_V2_ORIG_LIFECYCLE):
        return await _TPAG_V2_ORIG_LIFECYCLE(action, args, requested_by=requested_by)
    return "Lifecycle handler не найден."


async def _panel_execute_command_text(command_text: str, *, requested_by: int = 0, source_chat_id: int = 0, response_chat_id: int = 0) -> Dict[str, Any]:  # type: ignore[override]
    text = str(command_text or "").strip()
    cmd, args = _parse_cmd(text)
    if cmd in ("/manager_proxy_info", "/manager_proxy_check", "/manager_proxy_set", "/manager_proxy_on", "/manager_proxy_off", "/manager_proxy_bypass", "/manager_proxy_require"):
        action = cmd.replace("/manager_proxy_", "", 1)
        if action == "bypass":
            action = "direct"
        return {"ok": True, "result_text": await _tpag_proxy_command(action, args, requested_by=requested_by)}
    if cmd == "/manager_phone":
        return {"ok": True, "result_text": await _panel_manager_phone_command(args, requested_by=requested_by)}
    if cmd == "/manager_code":
        return {"ok": True, "result_text": await _panel_manager_code_command(args, requested_by=requested_by)}
    if cmd == "/manager_pass":
        return {"ok": True, "result_text": await _panel_manager_pass_command(args, requested_by=requested_by)}
    if cmd == "/manager_start":
        return {"ok": True, "result_text": await _panel_manager_lifecycle_command("start", args, requested_by=requested_by)}
    if callable(_TPAG_V2_ORIG_EXECUTE_COMMAND):
        try:
            return await _TPAG_V2_ORIG_EXECUTE_COMMAND(command_text, requested_by=requested_by, source_chat_id=source_chat_id, response_chat_id=response_chat_id)
        except TypeError:
            try:
                return await _TPAG_V2_ORIG_EXECUTE_COMMAND(command_text, requested_by=requested_by)
            except TypeError:
                return await _TPAG_V2_ORIG_EXECUTE_COMMAND(command_text)
    return {"ok": False, "error_text": f"Команда не поддерживается в панели: {cmd or text}"}


async def _tpag_monitor_loop() -> None:
    while True:
        try:
            await asyncio.sleep(TPAG_V2_MONITOR_INTERVAL_SEC)
            if not MANAGER_ARG_USED:
                await _tpag_monitor_once()
        except asyncio.CancelledError:
            return
        except Exception:
            await asyncio.sleep(30)


async def main() -> None:  # type: ignore[override]
    await _tpag_ensure_schema()
    if MANAGER_ARG_USED:
        key = registry_normalize_manager_key(MANAGER_RUNTIME_KEY or MANAGER_ARG_USED)
        ok, msg = await _tpag_run_guard(key, source="runtime_start", force=True)
        if not ok:
            try:
                await _tpag_registry_set_fields(key, last_error=str(msg or "proxy guard failed"))
            except Exception:
                pass
            await _tpag_insert_notification("⛔ Старт менеджера заблокирован", msg)
            _tpag_safe_print(msg)
            return
    else:
        try:
            asyncio.create_task(_tpag_monitor_loop())
        except Exception:
            pass
    if callable(_TPAG_V2_ORIG_MAIN):
        await _TPAG_V2_ORIG_MAIN()
    else:
        raise RuntimeError("Original main() not found")
# --- TPILOT PROXY AUTH GUARD V2 20260509 END ---


# --- TPILOT PROXY GUARD UI LATENCY V4 20260509 START ---
# Adds latency metrics without changing the core Telegram session flow.
import time as _tpag_v4_time  # noqa: E402

_TPAG_V4_ORIG_ENSURE_SCHEMA = globals().get("_tpag_ensure_schema")
_TPAG_V4_ORIG_MANAGER_PROXY_INFO_TEXT = globals().get("_manager_proxy_info_text")


def _tpag_v4_ms(start: float) -> int:
    try:
        return max(0, int(round((_tpag_v4_time.monotonic() - start) * 1000)))
    except Exception:
        return 0


async def _tpag_ensure_schema() -> None:  # type: ignore[override]
    if callable(_TPAG_V4_ORIG_ENSURE_SCHEMA):
        try:
            await _TPAG_V4_ORIG_ENSURE_SCHEMA()
        except Exception:
            pass
    try:
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            for ddl in [
                "ALTER TABLE managers ADD COLUMN auth_tcp_ms INTEGER NOT NULL DEFAULT 0",
                "ALTER TABLE managers ADD COLUMN auth_proxy_http_ms INTEGER NOT NULL DEFAULT 0",
                "ALTER TABLE managers ADD COLUMN auth_telethon_ms INTEGER NOT NULL DEFAULT 0",
            ]:
                try:
                    await db.execute(ddl)
                except Exception:
                    pass
            await db.commit()
    except Exception:
        pass


async def _tpag_v4_registry_get(key: str) -> Optional[Dict[str, Any]]:
    fn = globals().get("_tpag_registry_get")
    if callable(fn):
        return await fn(key)
    key = registry_normalize_manager_key(key or "")
    try:
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute("SELECT * FROM managers WHERE manager_key=? LIMIT 1", (key,))
            row = await cur.fetchone()
            return dict(row) if row else None
    except Exception:
        return None


async def _tpag_v4_registry_set_fields(key: str, **fields: Any) -> None:
    fn = globals().get("_tpag_registry_set_fields")
    if callable(fn):
        await fn(key, **fields)
        return
    key = registry_normalize_manager_key(key or "")
    if not key or not fields:
        return
    try:
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            cur = await db.execute("PRAGMA table_info(managers)")
            cols = {str(r[1]) for r in await cur.fetchall()}
            clean = {str(k): v for k, v in fields.items() if str(k) in cols}
            if not clean:
                return
            clean["updated_at"] = _now_utc_iso()
            sets = ", ".join([f"{k}=?" for k in clean])
            vals = list(clean.values()) + [key]
            await db.execute(f"UPDATE managers SET {sets} WHERE manager_key=?", vals)
            await db.commit()
    except Exception:
        pass


async def _tpag_v4_save_guard(
    key: str,
    ok: bool,
    source: str,
    direct: Optional[Dict[str, str]] = None,
    proxy: Optional[Dict[str, str]] = None,
    error: str = "",
    tcp_ms: int = 0,
    proxy_http_ms: int = 0,
    telethon_ms: int = 0,
) -> None:
    await _tpag_ensure_schema()
    now = _now_utc_iso()
    direct = direct or {}
    proxy = proxy or {}
    fields: Dict[str, Any] = {
        "auth_guard_ok": 1 if ok else 0,
        "auth_guard_checked_at": now,
        "auth_guard_source": str(source or ""),
        "auth_guard_error": "" if ok else str(error or "")[:800],
        "auth_direct_ip": str(direct.get("ip") or ""),
        "auth_direct_country": str(direct.get("country") or ""),
        "auth_direct_city": str(direct.get("city") or ""),
        "auth_direct_region": str(direct.get("region") or ""),
        "auth_proxy_ip": str(proxy.get("ip") or ""),
        "auth_proxy_country": str(proxy.get("country") or ""),
        "auth_proxy_city": str(proxy.get("city") or ""),
        "auth_proxy_region": str(proxy.get("region") or ""),
        "auth_tcp_ms": int(tcp_ms or 0),
        "auth_proxy_http_ms": int(proxy_http_ms or 0),
        "auth_telethon_ms": int(telethon_ms or 0),
    }
    if ok:
        fields["auth_guard_last_ok_at"] = now
        fields["auth_guard_notified_bad"] = 0
    else:
        fields["auth_guard_last_bad_at"] = now
    await _tpag_v4_registry_set_fields(key, **fields)


def _tpag_v4_tcp_check(host: str, port: int) -> Tuple[str, int]:
    started = _tpag_v4_time.monotonic()
    try:
        with _tpag_socket.create_connection((str(host), int(port)), timeout=8):
            ms = _tpag_v4_ms(started)
            return f"TCP OK, {ms} ms", ms
    except Exception as e:
        ms = _tpag_v4_ms(started)
        raise RuntimeError(f"TCP FAIL after {ms} ms: {e!r}")


def _tpag_v4_proxy_geo_via_socks(host: str, port: int, username: str = "", password: str = "", *, rdns: bool = True) -> Tuple[Dict[str, str], int]:
    started = _tpag_v4_time.monotonic()
    geo = _tpag_proxy_geo_via_socks(host, port, username, password, rdns=rdns)
    return geo, _tpag_v4_ms(started)


async def _tpag_v4_telethon_check(row: Dict[str, Any]) -> Tuple[str, int]:
    started = _tpag_v4_time.monotonic()
    msg = await _tpag_telethon_check(row)
    ms = _tpag_v4_ms(started)
    return f"Telethon OK, {ms} ms", ms


def _tpag_v4_latency_lines(row: Dict[str, Any]) -> list[str]:
    tcp_ms = int((row or {}).get("auth_tcp_ms") or 0)
    http_ms = int((row or {}).get("auth_proxy_http_ms") or 0)
    tg_ms = int((row or {}).get("auth_telethon_ms") or 0)
    if tcp_ms <= 0 and http_ms <= 0 and tg_ms <= 0:
        return []
    return [
        "",
        "Скорость proxy:",
        f"TCP: {tcp_ms} ms" if tcp_ms > 0 else "TCP: не определено",
        f"IP-check через proxy: {http_ms} ms" if http_ms > 0 else "IP-check через proxy: не определено",
        f"Telegram/Telethon: {tg_ms} ms" if tg_ms > 0 else "Telegram/Telethon: не определено",
    ]
# --- TPILOT PROXY GUARD UI LATENCY V4 20260509 END ---


# --- TPILOT MAIN BULK FOLLOWUPS V5 20260509 START ---
# Adds /followup on all and /followup off all for PanelBot bulk automation.
_TP_MAIN_V5_ORIG_HANDLE_POST_FOLLOWUP_COMMAND = globals().get("_handle_post_followup_command")


async def _tp_main_v5_active_manager_keys() -> list[str]:
    try:
        rows = await manager_list_rows(include_removed=False)
    except Exception:
        rows = []
    keys: list[str] = []
    for r in rows or []:
        try:
            key = registry_normalize_manager_key((r or {}).get("manager_key") or "")
            if not key:
                continue
            status = str((r or {}).get("status") or "").strip().lower()
            enabled = int((r or {}).get("is_enabled") or 0) == 1
            if status and status not in ("active", "enabled"):
                continue
            if not enabled:
                continue
            keys.append(key)
        except Exception:
            pass
    return keys


async def _handle_post_followup_command(args: str, user_id: int = 0) -> str:  # type: ignore[override]
    raw = str(args or "").strip()
    parts = raw.split()
    if parts:
        action = parts[0].lower()
        target_raw = parts[1] if len(parts) >= 2 else ""
        target = registry_normalize_manager_key(target_raw) if target_raw else ""
        if action in ("status", "статус"):
            if target == "all" or not target:
                return await _format_manager_followup_status("all")
        if action in ("on", "off") and target == "all":
            keys = await _tp_main_v5_active_manager_keys()
            for key in keys:
                await _set_manager_followup_enabled(key, action == "on", user_id=user_id)
            title = "✅ Автодожимы включены всем активным менеджерам" if action == "on" else "⛔ Автодожимы выключены всем активным менеджерам"
            lines = [title, f"Изменено: {len(keys)}", ""]
            lines.append(await _format_manager_followup_status("all"))
            return "\n".join(lines).rstrip()
        if action in ("on", "off") and target:
            keys = await _tp_main_v5_active_manager_keys()
            if target in keys:
                await _set_manager_followup_enabled(target, action == "on", user_id=user_id)
                return f"🔁 Автодожимы для {target}: {'включены' if action == 'on' else 'выключены'}"
    if callable(_TP_MAIN_V5_ORIG_HANDLE_POST_FOLLOWUP_COMMAND):
        return await _TP_MAIN_V5_ORIG_HANDLE_POST_FOLLOWUP_COMMAND(args, user_id=user_id)
    return "Команды: /followup status all, /followup on all, /followup off all, /followup on <manager>, /followup off <manager>"
# --- TPILOT MAIN BULK FOLLOWUPS V5 20260509 END ---

# --- TPILOT CONTACT IDENTITY COUNTING PATCH V1 20260510 START ---
# Professional lead identity layer:
# inbound_events = idempotency for each incoming Telegram message
# known_contacts/contact_identifiers = central system-wide contact memory
# daily_leads.contact_kind + lead_countable = honest lead counting

import sqlite3 as _tp_ci_sqlite3
import uuid as _tp_ci_uuid

_TP_CI_PATCH_VERSION = "contact_identity_v1_20260510"
_TP_CI_ORIG_MAIN = globals().get("main")
_TP_CI_ORIG_ENSURE_DAILY_LEADS_TABLE = globals().get("_ensure_daily_leads_table")
_TP_CI_ORIG_RECORD_INCOMING = globals().get("_record_incoming_from_manager")
_TP_CI_ORIG_RECORD_DAILY_LEAD_EVENT_DIRECT = globals().get("_TPILOT_202605_ORIG_RECORD_DAILY_LEAD_EVENT") or globals().get("_TPILOT_ORIG_RECORD_DAILY_LEAD_EVENT") or globals().get("_record_daily_lead_event")
_TP_CI_ORIG_FETCH_UNSENT_DAILY_LEADS = globals().get("_fetch_unsent_daily_leads")
_TP_CI_ORIG_CREATE_PARTNER_EVENT = globals().get("_create_partner_lead_event_from_daily")
_TP_CI_ORIG_COLLECT_DAY_LEADS = globals().get("_collect_day_leads")
_TP_CI_ORIG_COLLECT_PERIOD_LEADS = globals().get("_collect_period_leads")
_TP_CI_ORIG_COLLECT_WINDOW_LEADS_EXTENDED = globals().get("_collect_window_leads_extended")
_TP_CI_ORIG_EXPORT_DAY_XLSX = globals().get("_export_day_xlsx")


def _tp_ci_now_iso() -> str:
    try:
        return _now_utc_iso()
    except Exception:
        return _tp_utc_now().replace(microsecond=0).isoformat()


def _tp_ci_norm_key(raw: Any) -> str:
    try:
        return registry_normalize_manager_key(str(raw or ""))
    except Exception:
        return re.sub(r"[^a-z0-9_-]+", "", str(raw or "").strip().lower())


def _tp_ci_int(raw: Any, default: int = 0) -> int:
    try:
        return int(raw)
    except Exception:
        return int(default)


def _tp_ci_phone(raw: Any) -> str:
    try:
        return _phone_clean(str(raw or ""))
    except Exception:
        s = re.sub(r"\D+", "", str(raw or ""))
        return ("+" + s) if len(s) >= 10 else s


def _tp_ci_username(raw: Any) -> str:
    u = str(raw or "").strip().lstrip("@").lower()
    return u


def _tp_ci_connect(path: str) -> _tp_ci_sqlite3.Connection:
    parent = os.path.dirname(os.path.abspath(str(path)))
    if parent:
        os.makedirs(parent, exist_ok=True)
    con = _tp_ci_sqlite3.connect(str(path), timeout=30)
    con.row_factory = _tp_ci_sqlite3.Row
    try:
        con.execute("PRAGMA journal_mode=WAL;")
    except Exception:
        pass
    try:
        con.execute("PRAGMA busy_timeout=30000;")
    except Exception:
        pass
    return con


def _tp_ci_table_cols_sync(con: _tp_ci_sqlite3.Connection, table: str) -> set[str]:
    try:
        return {str(r[1]) for r in con.execute(f"PRAGMA table_info({table})").fetchall()}
    except Exception:
        return set()


def _tp_ci_table_exists_sync(con: _tp_ci_sqlite3.Connection, table: str) -> bool:
    try:
        return bool(con.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=? LIMIT 1", (table,)).fetchone())
    except Exception:
        return False


async def _tp_ci_ensure_contact_identity_tables() -> None:
    parent = os.path.dirname(TPILOT_DB_PATH)
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        # R1A1-D (F-21): busy_timeout must be active BEFORE any statement that can
        # itself hit contention, or the aiosqlite/sqlite3 driver default (5s) governs
        # the first statement instead of our intended 30s wait policy.
        await db.execute("PRAGMA busy_timeout=30000;")
        await db.execute("PRAGMA journal_mode=WAL;")
        await db.execute("""
            CREATE TABLE IF NOT EXISTS known_contacts(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                canonical_contact_id TEXT UNIQUE NOT NULL DEFAULT '',
                first_seen_at TEXT NOT NULL DEFAULT '',
                first_seen_date TEXT NOT NULL DEFAULT '',
                first_manager_key TEXT NOT NULL DEFAULT '',
                first_source_key TEXT NOT NULL DEFAULT '',
                first_buyer_key TEXT NOT NULL DEFAULT '',
                last_seen_at TEXT NOT NULL DEFAULT '',
                last_manager_key TEXT NOT NULL DEFAULT '',
                last_source_key TEXT NOT NULL DEFAULT '',
                seen_count INTEGER NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        await db.execute("""
            CREATE TABLE IF NOT EXISTS contact_identifiers(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                known_contact_id INTEGER NOT NULL,
                identifier_type TEXT NOT NULL DEFAULT '',
                identifier_value TEXT NOT NULL DEFAULT '',
                confidence TEXT NOT NULL DEFAULT '',
                first_seen_at TEXT NOT NULL DEFAULT '',
                last_seen_at TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT '',
                UNIQUE(identifier_type, identifier_value)
            );
        """)
        await db.execute("CREATE INDEX IF NOT EXISTS known_contacts_first_seen_idx ON known_contacts(first_seen_at);")
        await db.execute("CREATE INDEX IF NOT EXISTS known_contacts_last_seen_idx ON known_contacts(last_seen_at);")
        await db.execute("CREATE INDEX IF NOT EXISTS known_contacts_first_manager_idx ON known_contacts(first_manager_key);")
        await db.execute("CREATE INDEX IF NOT EXISTS contact_identifiers_contact_idx ON contact_identifiers(known_contact_id);")
        await db.execute("CREATE INDEX IF NOT EXISTS contact_identifiers_lookup_idx ON contact_identifiers(identifier_type, identifier_value);")
        await db.execute("""
            CREATE TABLE IF NOT EXISTS settings(
                key TEXT PRIMARY KEY,
                value TEXT
            );
        """)
        await db.commit()


async def _tp_ci_ensure_partner_event_identity_columns() -> None:
    parent = os.path.dirname(TPILOT_DB_PATH)
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        # R1A1-D (F-21): busy_timeout before journal_mode -- see rationale in
        # _tp_ci_ensure_contact_identity_tables above.
        await db.execute("PRAGMA busy_timeout=30000;")
        await db.execute("PRAGMA journal_mode=WAL;")
        await db.execute("""
            CREATE TABLE IF NOT EXISTS partner_lead_events(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                event_key TEXT UNIQUE NOT NULL DEFAULT '',
                source_key TEXT NOT NULL DEFAULT '',
                manager_key TEXT NOT NULL DEFAULT '',
                manager_display_name TEXT DEFAULT '',
                manager_username TEXT DEFAULT '',
                lead_id INTEGER NOT NULL DEFAULT 0,
                chat_id INTEGER NOT NULL DEFAULT 0,
                username TEXT DEFAULT '',
                full_name TEXT DEFAULT '',
                phone TEXT DEFAULT '',
                first_seen_utc TEXT NOT NULL DEFAULT '',
                duplicate INTEGER NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        cols = await _table_columns(db, "partner_lead_events")
        migrations = [
            ("known_contact_id", "ALTER TABLE partner_lead_events ADD COLUMN known_contact_id INTEGER NOT NULL DEFAULT 0"),
            ("contact_kind", "ALTER TABLE partner_lead_events ADD COLUMN contact_kind TEXT NOT NULL DEFAULT 'new'"),
            ("lead_countable", "ALTER TABLE partner_lead_events ADD COLUMN lead_countable INTEGER NOT NULL DEFAULT 1"),
            ("dedupe_reason", "ALTER TABLE partner_lead_events ADD COLUMN dedupe_reason TEXT NOT NULL DEFAULT ''"),
            ("first_seen_global_at", "ALTER TABLE partner_lead_events ADD COLUMN first_seen_global_at TEXT NOT NULL DEFAULT ''"),
            ("first_seen_global_manager_key", "ALTER TABLE partner_lead_events ADD COLUMN first_seen_global_manager_key TEXT NOT NULL DEFAULT ''"),
        ]
        for col, ddl in migrations:
            if col not in cols:
                try:
                    await db.execute(ddl)
                except Exception:
                    pass
        await db.execute("CREATE INDEX IF NOT EXISTS partner_lead_events_countable_idx ON partner_lead_events(source_key, lead_countable, id);")
        await db.execute("CREATE INDEX IF NOT EXISTS partner_lead_events_kind_idx ON partner_lead_events(source_key, contact_kind, id);")
        await db.commit()


async def _tp_ci_ensure_inbound_events_table(db_path: str) -> None:
    if not db_path:
        return
    parent = os.path.dirname(str(db_path))
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(str(db_path)) as db:
        # R1A1-D (F-21): busy_timeout before journal_mode -- see rationale in
        # _tp_ci_ensure_contact_identity_tables above.
        await db.execute("PRAGMA busy_timeout=30000;")
        await db.execute("PRAGMA journal_mode=WAL;")
        await db.execute("""
            CREATE TABLE IF NOT EXISTS inbound_events(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                event_key TEXT UNIQUE NOT NULL DEFAULT '',
                manager_key TEXT NOT NULL DEFAULT '',
                chat_id INTEGER NOT NULL DEFAULT 0,
                message_id INTEGER NOT NULL DEFAULT 0,
                message_date_utc TEXT NOT NULL DEFAULT '',
                received_at_utc TEXT NOT NULL DEFAULT '',
                username TEXT DEFAULT '',
                phone TEXT DEFAULT '',
                full_name TEXT DEFAULT '',
                text TEXT DEFAULT '',
                source_key TEXT DEFAULT '',
                buyer_key TEXT DEFAULT '',
                processed INTEGER NOT NULL DEFAULT 0,
                process_note TEXT DEFAULT '',
                created_at TEXT NOT NULL DEFAULT ''
            );
        """)
        await db.execute("CREATE UNIQUE INDEX IF NOT EXISTS inbound_events_event_key_idx ON inbound_events(event_key);")
        await db.execute("CREATE INDEX IF NOT EXISTS inbound_events_chat_idx ON inbound_events(chat_id, message_date_utc);")
        await db.execute("CREATE INDEX IF NOT EXISTS inbound_events_processed_idx ON inbound_events(processed, id);")
        await db.commit()


async def _ensure_daily_leads_table(db_path: str) -> None:  # type: ignore[override]
    await _tp_ci_ensure_daily_identity_columns(db_path)


def _tp_ci_source_key_for_manager_sync(manager_key: str) -> str:
    key = _tp_ci_norm_key(manager_key)
    if not key:
        return ""
    try:
        con = _tp_ci_connect(TPILOT_DB_PATH)
        try:
            row = con.execute("SELECT source_key FROM manager_source_links WHERE manager_key=? AND COALESCE(source_key,'')<>'' LIMIT 1", (key,)).fetchone()
            return _tp_ci_norm_key(row[0]) if row and row[0] else ""
        finally:
            con.close()
    except Exception:
        return ""


def _tp_ci_manager_display_name_sync(manager_key: str) -> str:
    """M2.11A helper: read-only display-name lookup for the duplicate-event mirror.
    Mirrors the (mgr or {}).get("display_name") fallback used by the countable
    partner-event writer, but resolves it directly from `managers` since the
    mirror runs at the recorder hook (no `mgr` row from _manager_rows_for_reporting)."""
    key = _tp_ci_norm_key(manager_key)
    if not key:
        return ""
    try:
        con = _tp_ci_connect(TPILOT_DB_PATH)
        try:
            row = con.execute("SELECT display_name FROM managers WHERE manager_key=? LIMIT 1", (key,)).fetchone()
            return str(row[0] or "") if row else ""
        finally:
            con.close()
    except Exception:
        return ""


def _tp_ci_find_contact_locked(con: _tp_ci_sqlite3.Connection, identifiers: list[tuple[str, str, str]]) -> dict:
    # Only strong identifiers can decide that a contact already exists.
    strong = [(t, v) for t, v, c in identifiers if c == "strong" and v]
    for ident_type, ident_value in strong:
        row = con.execute(
            """
            SELECT kc.*
            FROM contact_identifiers ci
            JOIN known_contacts kc ON kc.id=ci.known_contact_id
            WHERE ci.identifier_type=? AND ci.identifier_value=?
            LIMIT 1
            """,
            (ident_type, ident_value),
        ).fetchone()
        if row:
            return dict(row)
    return {}


def _tp_ci_upsert_contact_sync(*, chat_id: int, username: str = "", phone: str = "", full_name: str = "", first_seen_at: str = "", manager_key: str = "", source_key: str = "", buyer_key: str = "", allow_create: bool = True) -> tuple[int, bool, dict]:
    chat_id = int(chat_id or 0)
    manager_key = _tp_ci_norm_key(manager_key)
    source_key = _tp_ci_norm_key(source_key)
    now = _tp_ci_now_iso()
    first_seen_at = str(first_seen_at or now)
    first_seen_date = ""
    try:
        first_seen_date = _utc_iso_to_kyiv_dt(first_seen_at).date().isoformat()
    except Exception:
        first_seen_date = first_seen_at[:10] if first_seen_at else ""
    identifiers: list[tuple[str, str, str]] = []
    if chat_id > 0:
        identifiers.append(("telegram_chat_id", str(chat_id), "strong"))
    ph = _tp_ci_phone(phone)
    if ph:
        identifiers.append(("phone", ph, "strong"))
    un = _tp_ci_username(username)
    if un:
        identifiers.append(("username", un, "weak"))

    con = _tp_ci_connect(TPILOT_DB_PATH)
    tx = None
    try:
        tx = _p5_begin_immediate_sync(
            con, source="main.py", function="_tp_ci_upsert_contact_sync",
            db_path=TPILOT_DB_PATH, manager_key=manager_key,
        )
        existing = _tp_ci_find_contact_locked(con, identifiers)
        created = False
        if existing:
            cid = int(existing.get("id") or 0)
        elif allow_create:
            canonical = f"tg:{chat_id}" if chat_id > 0 else f"contact:{_tp_ci_uuid.uuid4().hex}"
            cur = con.execute(
                """
                INSERT INTO known_contacts(
                    canonical_contact_id, first_seen_at, first_seen_date, first_manager_key,
                    first_source_key, first_buyer_key, last_seen_at, last_manager_key,
                    last_source_key, seen_count, created_at, updated_at
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)
                """,
                (canonical, first_seen_at, first_seen_date, manager_key, source_key, str(buyer_key or ""), first_seen_at, manager_key, source_key, 0, now, now),
            )
            cid = int(cur.lastrowid or 0)
            existing = dict(con.execute("SELECT * FROM known_contacts WHERE id=?", (cid,)).fetchone() or {})
            created = True
        else:
            _p5_commit_sync(tx, con)
            return 0, False, {}
        if existing:
            try:
                old_first = str(existing.get("first_seen_at") or "")
                if first_seen_at and (not old_first or first_seen_at < old_first):
                    con.execute(
                        """
                        UPDATE known_contacts
                        SET first_seen_at=?,
                            first_seen_date=?,
                            first_manager_key=?,
                            first_source_key=?,
                            first_buyer_key=?,
                            updated_at=?
                        WHERE id=?
                        """,
                        (first_seen_at, first_seen_date, manager_key, source_key, str(buyer_key or ""), now, cid),
                    )
                    existing["first_seen_at"] = first_seen_at
                    existing["first_seen_date"] = first_seen_date
                    existing["first_manager_key"] = manager_key
                    existing["first_source_key"] = source_key
                    existing["first_buyer_key"] = str(buyer_key or "")
            except Exception:
                pass
        for ident_type, ident_value, confidence in identifiers:
            if not ident_value or cid <= 0:
                continue
            con.execute(
                """
                INSERT OR IGNORE INTO contact_identifiers(
                    known_contact_id, identifier_type, identifier_value, confidence,
                    first_seen_at, last_seen_at, created_at, updated_at
                ) VALUES(?,?,?,?,?,?,?,?)
                """,
                (cid, ident_type, ident_value, confidence, first_seen_at, first_seen_at, now, now),
            )
            con.execute(
                """
                UPDATE contact_identifiers
                SET last_seen_at=?, updated_at=?
                WHERE identifier_type=? AND identifier_value=?
                """,
                (first_seen_at, now, ident_type, ident_value),
            )
        con.execute(
            """
            UPDATE known_contacts
            SET last_seen_at=?,
                last_manager_key=?,
                last_source_key=?,
                seen_count=COALESCE(seen_count,0)+1,
                updated_at=?
            WHERE id=?
            """,
            (first_seen_at, manager_key, source_key, now, cid),
        )
        row = con.execute("SELECT * FROM known_contacts WHERE id=?", (cid,)).fetchone()
        _p5_commit_sync(tx, con)
        return cid, created, (dict(row) if row else existing)
    except Exception as _p5_exc:
        try:
            _p5_rollback_sync(tx, con, error=_p5_exc)
        except Exception:
            pass
        raise
    finally:
        con.close()


def _tp_ci_contact_by_chat_sync(chat_id: int) -> dict:
    chat_id = int(chat_id or 0)
    if chat_id <= 0:
        return {}
    con = _tp_ci_connect(TPILOT_DB_PATH)
    try:
        row = con.execute(
            """
            SELECT kc.*
            FROM contact_identifiers ci
            JOIN known_contacts kc ON kc.id=ci.known_contact_id
            WHERE ci.identifier_type='telegram_chat_id' AND ci.identifier_value=?
            LIMIT 1
            """,
            (str(chat_id),),
        ).fetchone()
        return dict(row) if row else {}
    finally:
        con.close()


async def _tp_ci_try_insert_inbound_event(db_path: str, *, event_key: str, manager_key: str, chat_id: int, message_id: int, message_date_utc: str, username: str = "", phone: str = "", full_name: str = "", text: str = "") -> bool:
    await _tp_ci_ensure_inbound_events_table(db_path)
    source_key = _tp_ci_source_key_for_manager_sync(manager_key)
    now = _tp_ci_now_iso()
    async with aiosqlite.connect(str(db_path)) as db:
        await db.execute("PRAGMA busy_timeout=30000;")
        tx = None
        try:
            tx = await _p5_begin_immediate_async(
                db, source="main.py", function="_tp_ci_try_insert_inbound_event",
                db_path=db_path, manager_key=manager_key, event_key=str(event_key or ""),
            )
        except Exception:
            tx = None
        cur = await db.execute(
            """
            INSERT OR IGNORE INTO inbound_events(
                event_key, manager_key, chat_id, message_id, message_date_utc,
                received_at_utc, username, phone, full_name, text, source_key,
                buyer_key, processed, process_note, created_at
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                str(event_key),
                _tp_ci_norm_key(manager_key),
                int(chat_id or 0),
                int(message_id or 0),
                str(message_date_utc or ""),
                now,
                str(username or ""),
                str(phone or ""),
                str(full_name or ""),
                str(text or "")[:4000],
                source_key,
                "",
                0,
                "",
                now,
            ),
        )
        inserted = bool((cur.rowcount or 0) > 0)
        await _p5_commit_async(tx, db)
        return inserted


