async def _tp_ci_system_history_first(chat_id: int) -> dict:
    chat_id = int(chat_id or 0)
    if chat_id <= 0:
        return {}
    try:
        rows = await _manager_rows_for_reporting()
    except Exception:
        rows = []
    best: dict = {}
    for mgr in rows or []:
        mk = _tp_ci_norm_key((mgr or {}).get("manager_key") or "")
        dbp = str((mgr or {}).get("db_path") or "")
        if not dbp or not os.path.exists(dbp):
            continue
        try:
            con = _tp_ci_connect(dbp)
            try:
                if _tp_ci_table_exists_sync(con, "daily_leads"):
                    row = con.execute("SELECT * FROM daily_leads WHERE chat_id=? ORDER BY first_seen_utc ASC, id ASC LIMIT 1", (chat_id,)).fetchone()
                    if row:
                        d = dict(row)
                        d["manager_key"] = mk or d.get("manager_key") or ""
                        ts = str(d.get("first_seen_utc") or d.get("created_at") or "")
                        if not best or ts < str(best.get("first_seen_utc") or best.get("created_at") or "~~~~"):
                            best = d
                if _tp_ci_table_exists_sync(con, "leads"):
                    row = con.execute("SELECT * FROM leads WHERE chat_id=? LIMIT 1", (chat_id,)).fetchone()
                    if row:
                        d = dict(row)
                        d["manager_key"] = mk
                        d["first_seen_utc"] = str(d.get("first_seen") or d.get("last_seen") or "")
                        ts = str(d.get("first_seen_utc") or "")
                        if ts and (not best or ts < str(best.get("first_seen_utc") or "~~~~")):
                            best = d
            finally:
                con.close()
        except Exception:
            pass
    return best


def _tp_ci_build_pseudo_lead(*, manager_key: str, chat_id: int, username: str, full_name: str, phone: str, first_seen_utc: str, contact_kind: str, known_contact_id: int = 0, dedupe_reason: str = "", first_seen_global_at: str = "", first_seen_global_manager_key: str = "", baseline_old: int = 0) -> dict:
    dt_local = _utc_iso_to_kyiv_dt(str(first_seen_utc or _tp_ci_now_iso()))
    return {
        "id": 0,
        "lead_date": dt_local.date().isoformat(),
        "manager_key": _tp_ci_norm_key(manager_key),
        "manager_username": SELF_USERNAME,
        "chat_id": int(chat_id or 0),
        "username": str(username or ""),
        "full_name": str(full_name or ""),
        "phone": str(phone or ""),
        "first_seen_utc": str(first_seen_utc or _tp_ci_now_iso()),
        "first_seen_kyiv": dt_local.strftime("%Y-%m-%d %H:%M:%S"),
        "duplicate": 1 if contact_kind == "duplicate" else 0,
        "duplicate_checked": 1,
        "ai_stat_sent": 1,
        "status": "unknown",
        "contact_kind": str(contact_kind or "unknown"),
        "lead_countable": 0,
        "known_contact_id": int(known_contact_id or 0),
        "dedupe_reason": str(dedupe_reason or ""),
        "baseline_old": int(baseline_old or 0),
        "returning": 1 if contact_kind in ("returning", "duplicate", "old_baseline") else 0,
        "first_seen_global_at": str(first_seen_global_at or ""),
        "first_seen_global_manager_key": _tp_ci_norm_key(first_seen_global_manager_key or ""),
        "_existing_same_manager_chat": 1,
        "_contact_identity_skip_stat": 1,
    }


async def _mirror_noncountable_partner_event(pseudo_lead: Dict[str, Any]) -> None:
    """M2.11A: future-only identity mirror of non-countable contact occurrences
    (contact_kind in duplicate/returning/old_baseline) into partner_lead_events,
    so PartnerBot can later display duplicates without affecting paid stats.

    Safety invariants (must hold for every row this writes):
      - lead_countable is always written as 0.
      - duplicate is always written as 0 (the legacy `duplicate` column must
        never become canonical truth; mirrored rows are identified purely via
        contact_kind/lead_countable/dedupe_reason).
      - rows are NEVER routed through _fetch_unsent_daily_leads /
        _create_partner_lead_event_from_daily / _mark_daily_lead_sent /
        partner_sent_events, so paid stats and live "new lead" notifications
        (which both gate on lead_countable=1) cannot see or count them.
      - idempotent per manager+chat+day via a dedicated `dup:` event_key
        namespace (disjoint from the countable `{mk}:{lead_id}:{chat_id}:{ts}`
        namespace), using INSERT OR IGNORE so repeat inbound messages from the
        same duplicate contact on the same day never create extra rows.
    """
    try:
        contact_kind = str(pseudo_lead.get("contact_kind") or "").strip().lower()
        dedupe_reason = str(pseudo_lead.get("dedupe_reason") or "").strip().lower()
        try:
            lead_countable_val = int(pseudo_lead.get("lead_countable") if pseudo_lead.get("lead_countable") is not None else 1)
        except Exception:
            lead_countable_val = 1
        is_noncountable_kind = contact_kind in ("duplicate", "returning", "old_baseline")
        is_noncountable_reason = (
            lead_countable_val == 0
            and dedupe_reason in ("seen_before_same_manager", "seen_before_other_manager", "baseline_old_chats")
        )
        if not (is_noncountable_kind or is_noncountable_reason):
            return

        manager_key = _tp_ci_norm_key(pseudo_lead.get("manager_key") or "")
        chat_id = int(pseudo_lead.get("chat_id") or 0)
        if not manager_key or chat_id <= 0:
            return

        source_key = await _partner_source_key_for_manager(manager_key)
        if not source_key:
            return

        first_seen_utc = str(pseudo_lead.get("first_seen_utc") or "")
        lead_date = str(pseudo_lead.get("lead_date") or "").strip()
        if not lead_date and first_seen_utc:
            try:
                lead_date = _utc_iso_to_kyiv_dt(first_seen_utc).date().isoformat()
            except Exception:
                lead_date = ""
        if not lead_date or not first_seen_utc:
            return

        await _ensure_partner_lead_events_table()
        await _tp_ci_ensure_partner_event_identity_columns()

        # Day-scoped idempotency key in its own `dup:` namespace — guarantees at
        # most one mirror row per (manager, chat, day) regardless of how many
        # times the duplicate contact messages in or the recorder re-runs.
        event_key = f"dup:{manager_key}:{chat_id}:{lead_date}"
        now = _tp_ci_now_iso()

        manager_display_name = str(pseudo_lead.get("manager_display_name") or "").strip()
        if not manager_display_name:
            manager_display_name = _tp_ci_manager_display_name_sync(manager_key) or manager_key
        manager_username = str(pseudo_lead.get("manager_username") or "").lstrip("@")

        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute(
                """
                INSERT OR IGNORE INTO partner_lead_events(
                    event_key, source_key, manager_key, manager_display_name, manager_username,
                    lead_id, chat_id, username, full_name, phone, first_seen_utc,
                    duplicate, known_contact_id, contact_kind, lead_countable, dedupe_reason,
                    first_seen_global_at, first_seen_global_manager_key, created_at, updated_at
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    event_key,
                    source_key,
                    manager_key,
                    manager_display_name,
                    manager_username,
                    0,
                    chat_id,
                    str(pseudo_lead.get("username") or "").lstrip("@"),
                    str(pseudo_lead.get("full_name") or ""),
                    str(pseudo_lead.get("phone") or ""),
                    first_seen_utc,
                    0,
                    int(pseudo_lead.get("known_contact_id") or 0),
                    contact_kind or "duplicate",
                    0,
                    str(pseudo_lead.get("dedupe_reason") or ""),
                    str(pseudo_lead.get("first_seen_global_at") or ""),
                    str(pseudo_lead.get("first_seen_global_manager_key") or ""),
                    now,
                    now,
                ),
            )
            await db.commit()
    except Exception as e:
        print(f"partner duplicate mirror error: {e!r}")


async def _tp_ci_record_daily_lead_event(*, db_path: str, manager_key: str, manager_username: str, chat_id: int, username: str, full_name: str, phone: str, first_seen_utc: str) -> Tuple[bool, Dict[str, Any]]:
    await _tp_ci_ensure_contact_identity_tables()
    await _tp_ci_ensure_partner_event_identity_columns()
    await _tp_ci_ensure_daily_identity_columns(db_path)

    manager_key = _tp_ci_norm_key(manager_key)
    chat_id = int(chat_id or 0)
    dt_local = _utc_iso_to_kyiv_dt(str(first_seen_utc or _tp_ci_now_iso()))
    lead_date = dt_local.date().isoformat()
    source_key = _tp_ci_source_key_for_manager_sync(manager_key)

    today_row = await _tp_ci_local_daily_today_row(db_path, chat_id, lead_date, manager_key)
    if today_row:
        return False, dict(today_row)

    first_local_row = await _tp_ci_local_daily_first_row(db_path, chat_id)
    if first_local_row:
        row_date = str(first_local_row.get("lead_date") or "")
        if row_date and row_date != lead_date:
            cid, _created, contact = _tp_ci_upsert_contact_sync(chat_id=chat_id, username=username, phone=phone, full_name=full_name, first_seen_at=str(first_local_row.get("first_seen_utc") or first_seen_utc), manager_key=str(first_local_row.get("manager_key") or manager_key), source_key=source_key)
            out = dict(first_local_row)
            out.update({
                "contact_kind": "returning",
                "lead_countable": 0,
                "known_contact_id": cid,
                "dedupe_reason": "seen_before_same_manager",
                "returning": 1,
                "first_seen_global_at": str((contact or {}).get("first_seen_at") or first_local_row.get("first_seen_utc") or ""),
                "first_seen_global_manager_key": str((contact or {}).get("first_manager_key") or first_local_row.get("manager_key") or manager_key),
                "_existing_same_manager_chat": 1,
                "_contact_identity_skip_stat": 1,
            })
            # M2.11A: mirror the CURRENT occurrence (not the stale first-day row
            # carried in `out`/`first_local_row`) — use this call's own
            # manager_key/chat_id/first_seen_utc/lead_date/contact fields and
            # only borrow the identity classification from `out`.
            await _mirror_noncountable_partner_event({
                "manager_key": manager_key,
                "manager_username": manager_username,
                "chat_id": chat_id,
                "username": username,
                "full_name": full_name,
                "phone": phone,
                "first_seen_utc": first_seen_utc,
                "lead_date": lead_date,
                "contact_kind": out.get("contact_kind"),
                "lead_countable": out.get("lead_countable"),
                "known_contact_id": out.get("known_contact_id"),
                "dedupe_reason": out.get("dedupe_reason"),
                "first_seen_global_at": out.get("first_seen_global_at"),
                "first_seen_global_manager_key": out.get("first_seen_global_manager_key"),
            })
            return False, out

    baseline = await _tp_ci_baseline_info(db_path, chat_id)
    if baseline:
        base_seen = str(baseline.get("created_at") or first_seen_utc or _tp_ci_now_iso())
        cid, _created, contact = _tp_ci_upsert_contact_sync(chat_id=chat_id, username=username or str(baseline.get("username") or ""), phone=phone, full_name=full_name or str(baseline.get("full_name") or ""), first_seen_at=base_seen, manager_key=manager_key, source_key=source_key)
        pseudo_old_baseline = _tp_ci_build_pseudo_lead(
            manager_key=manager_key, chat_id=chat_id, username=username, full_name=full_name, phone=phone, first_seen_utc=first_seen_utc,
            contact_kind="old_baseline", known_contact_id=cid, dedupe_reason="baseline_old_chats", baseline_old=1,
            first_seen_global_at=str((contact or {}).get("first_seen_at") or base_seen),
            first_seen_global_manager_key=str((contact or {}).get("first_manager_key") or manager_key),
        )
        mirror_src = dict(pseudo_old_baseline)
        mirror_src["manager_username"] = manager_username
        await _mirror_noncountable_partner_event(mirror_src)
        return False, pseudo_old_baseline

    existing_contact = _tp_ci_contact_by_chat_sync(chat_id)
    if existing_contact:
        first_mgr = _tp_ci_norm_key(existing_contact.get("first_manager_key") or "")
        kind = "returning" if first_mgr == manager_key else "duplicate"
        reason = "seen_before_same_manager" if kind == "returning" else "seen_before_other_manager"
        _tp_ci_upsert_contact_sync(chat_id=chat_id, username=username, phone=phone, full_name=full_name, first_seen_at=first_seen_utc, manager_key=manager_key, source_key=source_key, allow_create=True)
        pseudo_existing = _tp_ci_build_pseudo_lead(
            manager_key=manager_key, chat_id=chat_id, username=username, full_name=full_name, phone=phone, first_seen_utc=first_seen_utc,
            contact_kind=kind, known_contact_id=int(existing_contact.get("id") or 0), dedupe_reason=reason, baseline_old=0,
            first_seen_global_at=str(existing_contact.get("first_seen_at") or ""),
            first_seen_global_manager_key=first_mgr,
        )
        mirror_src = dict(pseudo_existing)
        mirror_src["manager_username"] = manager_username
        await _mirror_noncountable_partner_event(mirror_src)
        return False, pseudo_existing

    history = await _tp_ci_system_history_first(chat_id)
    if history:
        hist_mgr = _tp_ci_norm_key(history.get("manager_key") or "")
        hist_seen = str(history.get("first_seen_utc") or history.get("first_seen") or first_seen_utc)
        cid, _created, contact = _tp_ci_upsert_contact_sync(chat_id=chat_id, username=username or str(history.get("username") or ""), phone=phone or str(history.get("phone") or ""), full_name=full_name or str(history.get("full_name") or ""), first_seen_at=hist_seen, manager_key=hist_mgr or manager_key, source_key=_tp_ci_source_key_for_manager_sync(hist_mgr or manager_key))
        kind = "returning" if (hist_mgr == manager_key or not hist_mgr) else "duplicate"
        reason = "seen_before_same_manager" if kind == "returning" else "seen_before_other_manager"
        pseudo_history = _tp_ci_build_pseudo_lead(
            manager_key=manager_key, chat_id=chat_id, username=username, full_name=full_name, phone=phone, first_seen_utc=first_seen_utc,
            contact_kind=kind, known_contact_id=cid, dedupe_reason=reason,
            first_seen_global_at=str((contact or {}).get("first_seen_at") or hist_seen),
            first_seen_global_manager_key=str((contact or {}).get("first_manager_key") or hist_mgr or manager_key),
        )
        mirror_src = dict(pseudo_history)
        mirror_src["manager_username"] = manager_username
        await _mirror_noncountable_partner_event(mirror_src)
        return False, pseudo_history

    cid, _created, contact = _tp_ci_upsert_contact_sync(chat_id=chat_id, username=username, phone=phone, full_name=full_name, first_seen_at=first_seen_utc, manager_key=manager_key, source_key=source_key)
    if callable(_TP_CI_ORIG_RECORD_DAILY_LEAD_EVENT_DIRECT):
        created, row = await _TP_CI_ORIG_RECORD_DAILY_LEAD_EVENT_DIRECT(db_path=db_path, manager_key=manager_key, manager_username=manager_username, chat_id=chat_id, username=username, full_name=full_name, phone=phone, first_seen_utc=first_seen_utc)
    else:
        created, row = False, {}
    row = dict(row or {})
    if row.get("id"):
        await _tp_ci_set_daily_identity(
            db_path,
            int(row.get("id") or 0),
            contact_kind="new",
            lead_countable=1,
            known_contact_id=cid,
            event_key=str(row.get("event_key") or ""),
            dedupe_reason="new_contact",
            baseline_old=0,
            returning=0,
            first_seen_global_at=str((contact or {}).get("first_seen_at") or first_seen_utc),
            first_seen_global_manager_key=str((contact or {}).get("first_manager_key") or manager_key),
            duplicate=0,
            ai_stat_sent=None,
        )
        row.update({
            "contact_kind": "new",
            "lead_countable": 1,
            "known_contact_id": cid,
            "dedupe_reason": "new_contact",
            "first_seen_global_at": str((contact or {}).get("first_seen_at") or first_seen_utc),
            "first_seen_global_manager_key": str((contact or {}).get("first_manager_key") or manager_key),
        })
    return created, row


# The old manual-profile handler calls this captured global directly.
# Re-point it to the contact-identity aware recorder.
_TPILOT_ORIG_RECORD_DAILY_LEAD_EVENT = _tp_ci_record_daily_lead_event
_TPILOT_202605_ORIG_RECORD_DAILY_LEAD_EVENT = _tp_ci_record_daily_lead_event
_record_daily_lead_event = _tp_ci_record_daily_lead_event  # type: ignore[assignment]


async def _record_incoming_from_manager(event: events.NewMessage.Event) -> None:  # type: ignore[override]
    if CONTROLLER_MODE or not MANAGER_RUNTIME_KEY or not event.is_private:
        return
    chat_id = int(event.chat_id or 0)
    if chat_id <= 0:
        return
    text = str(getattr(event, "raw_text", None) or "").strip()
    if event.out:
        msg_id = int(getattr(event.message, "id", 0) or 0)
        if not _is_program_sent(chat_id, msg_id):
            if text and globals().get("_profile_request_words") and _profile_request_words(text):
                await _open_profile_capture(DB_PATH, chat_id, MANAGER_RUNTIME_KEY, "manual_question")
            await _mark_manager_replied(DB_PATH, chat_id)
            if globals().get("_is_post_followup_disable_word") and _is_post_followup_disable_word(text):
                try:
                    await _set_post_followup_disabled(DB_PATH, chat_id, True, user_id=0, reason="manual_stop_keyword")
                    print(f"followup keyword-stop chat_id={chat_id} manager={MANAGER_RUNTIME_KEY}")
                except Exception:
                    pass
                try:
                    await _set_lead_automation_stopped(DB_PATH, chat_id, reason="manual_stop_word")
                    print(f"automation permanently stopped chat_id={chat_id} manager={MANAGER_RUNTIME_KEY}")
                except Exception:
                    pass
            else:
                try:
                    await _post_followup_note_manager_out(DB_PATH, chat_id, MANAGER_RUNTIME_KEY)
                except Exception:
                    pass
        return

    try:
        sender = await event.get_sender()
    except Exception:
        sender = None
    username = str(getattr(sender, "username", None) or "").strip()
    first_name = str(getattr(sender, "first_name", None) or "").strip()
    last_name = str(getattr(sender, "last_name", None) or "").strip()
    full_name = _full_name(first_name, last_name)
    phone = _tp_ci_phone(str(getattr(sender, "phone", None) or ""))
    try:
        contact = getattr(event.message, "contact", None)
        if contact and getattr(contact, "phone_number", None):
            phone = _tp_ci_phone(str(getattr(contact, "phone_number") or "")) or phone
    except Exception:
        pass
    msg_id = int(getattr(event.message, "id", 0) or 0)
    msg_dt = _event_utc_iso(event)
    event_key = f"{_tp_ci_norm_key(MANAGER_RUNTIME_KEY)}:{chat_id}:{msg_id}"
    try:
        inserted = await _tp_ci_try_insert_inbound_event(
            DB_PATH,
            event_key=event_key,
            manager_key=MANAGER_RUNTIME_KEY,
            chat_id=chat_id,
            message_id=msg_id,
            message_date_utc=msg_dt,
            username=username,
            phone=phone,
            full_name=full_name,
            text=text,
        )
        if not inserted:
            return
    except Exception as e:
        print(f"contact_identity inbound_events error: {e!r}")

    if callable(_TP_CI_ORIG_RECORD_INCOMING):
        await _TP_CI_ORIG_RECORD_INCOMING(event)
    try:
        await _tp_ci_mark_inbound_processed(DB_PATH, event_key, "processed")
    except Exception:
        pass


def _tp_ci_is_countable_lead(row: Dict[str, Any]) -> bool:
    try:
        if "lead_countable" in (row or {}):
            return int((row or {}).get("lead_countable") or 0) == 1
    except Exception:
        pass
    try:
        if int((row or {}).get("duplicate") or 0) == 1:
            return False
    except Exception:
        pass
    kind = str((row or {}).get("contact_kind") or "new").strip().lower()
    return kind in ("", "new")


def _tp_ci_filter_countable(leads: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    return [x for x in list(leads or []) if _tp_ci_is_countable_lead(x)]


async def _fetch_unsent_daily_leads(db_path: str, limit: int = 200) -> List[Dict[str, Any]]:  # type: ignore[override]
    if not db_path or not os.path.exists(db_path):
        return []
    await _tp_ci_ensure_daily_identity_columns(db_path)
    async with aiosqlite.connect(str(db_path)) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            """
            SELECT * FROM daily_leads
            WHERE COALESCE(ai_stat_sent,0)=0
              AND COALESCE(lead_countable, CASE WHEN COALESCE(duplicate,0)=1 THEN 0 ELSE 1 END)=1
            ORDER BY first_seen_utc ASC, id ASC
            LIMIT ?
            """,
            (int(limit),),
        )
        return [dict(r) for r in await cur.fetchall()]


def _tp_ci_new_partner_event_countability(item: Dict[str, Any], duplicate: bool) -> Tuple[int, str]:
    """R1A1-C (F-30, new-write only): single canonical countability rule for
    NEWLY written partner_lead_events rows.

    `item` has already passed `_tp_ci_is_countable_lead` (the contact-identity
    engine's own verdict) by the time this is called. `duplicate` is the
    INDEPENDENT legacy engine's verdict (`_is_duplicate_systemwide`), passed in
    by the caller. Fail-closed across both engines: if EITHER says duplicate,
    the new row is non-countable. Never writes `duplicate=1 AND lead_countable=1`.
    Historical rows are untouched -- this only decides what a NEW row gets."""
    contact_kind = str(item.get("contact_kind") or "new")
    if duplicate:
        return 0, ("duplicate" if contact_kind == "new" else contact_kind)
    return 1, contact_kind


async def _create_partner_lead_event_from_daily(item: Dict[str, Any], mgr: Dict[str, Any], duplicate: bool) -> None:  # type: ignore[override]
    try:
        if not _tp_ci_is_countable_lead(item):
            return
        await _ensure_partner_lead_events_table()
        await _tp_ci_ensure_partner_event_identity_columns()
        manager_key = _tp_ci_norm_key(item.get("manager_key") or (mgr or {}).get("manager_key") or "")
        source_key = await _partner_source_key_for_manager(manager_key)
        if not source_key:
            return
        lead_id = int(item.get("id") or 0)
        chat_id = int(item.get("chat_id") or 0)
        first_seen_utc = str(item.get("first_seen_utc") or "")
        if lead_id <= 0 or chat_id <= 0 or not first_seen_utc:
            return
        event_key = f"{manager_key}:{lead_id}:{chat_id}:{first_seen_utc}"
        now = _tp_ci_now_iso()
        manager_display_name = str((mgr or {}).get("display_name") or item.get("manager_display_name") or manager_key)
        manager_username = str((mgr or {}).get("telegram_username") or item.get("manager_username") or "").lstrip("@")
        # R1A1-C (F-30, new-write only): single canonical writer for lead_countable
        # on NEW rows -- never a hardcoded literal. Makes `duplicate=1 AND
        # lead_countable=1` impossible by construction for anything written here.
        new_countable, new_contact_kind = _tp_ci_new_partner_event_countability(item, duplicate)
        # B-1 correction (2026-08-12 independent review): this used to be
        # INSERT OR IGNORE followed by an UNCONDITIONAL UPDATE ... WHERE event_key=?,
        # which silently reclassified an ALREADY-EXISTING historical row's identity/
        # countability fields every time this event_key was reprocessed (e.g. after
        # a failed Telegram send left ai_stat_sent=0, or after
        # _tp_ci_reclassify_existing_daily_rows_once flips lead_countable on
        # restart) -- an unapproved, unlogged R1A3-shaped historical mutation.
        # A single atomic INSERT ... ON CONFLICT(event_key) DO UPDATE now sets
        # identity/countability columns (duplicate, contact_kind, lead_countable,
        # known_contact_id, dedupe_reason, first_seen_global_*, source_key,
        # manager_key, lead_id, chat_id, first_seen_utc, created_at) ONLY on first
        # insert. On conflict (event_key already exists), ONLY volatile/display
        # metadata is refreshed: manager_display_name, manager_username, username,
        # full_name, phone, updated_at. Historical identity/countability is never
        # touched by reprocessing -- R1A3 (historical reconciliation) stays a
        # separate, NO-GO-until-approved release per plan §23 A.3/C.
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute(
                """
                INSERT INTO partner_lead_events(
                    event_key, source_key, manager_key, manager_display_name, manager_username,
                    lead_id, chat_id, username, full_name, phone, first_seen_utc,
                    duplicate, known_contact_id, contact_kind, lead_countable, dedupe_reason,
                    first_seen_global_at, first_seen_global_manager_key, created_at, updated_at
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                ON CONFLICT(event_key) DO UPDATE SET
                    manager_display_name=excluded.manager_display_name,
                    manager_username=excluded.manager_username,
                    username=excluded.username,
                    full_name=excluded.full_name,
                    phone=excluded.phone,
                    updated_at=excluded.updated_at
                """,
                (
                    event_key,
                    source_key,
                    manager_key,
                    manager_display_name,
                    manager_username,
                    lead_id,
                    chat_id,
                    str(item.get("username") or "").lstrip("@"),
                    str(item.get("full_name") or ""),
                    str(item.get("phone") or ""),
                    first_seen_utc,
                    1 if duplicate else 0,
                    int(item.get("known_contact_id") or 0),
                    new_contact_kind,
                    new_countable,
                    str(item.get("dedupe_reason") or "new_contact"),
                    str(item.get("first_seen_global_at") or ""),
                    str(item.get("first_seen_global_manager_key") or ""),
                    now,
                    now,
                ),
            )
            await db.commit()
    except Exception as e:
        print(f"partner live event create identity error: {e!r}")


async def _collect_day_leads(lead_date: str, target_key: str = "all") -> List[Dict[str, Any]]:  # type: ignore[override]
    leads = await _TP_CI_ORIG_COLLECT_DAY_LEADS(lead_date, target_key=target_key) if callable(_TP_CI_ORIG_COLLECT_DAY_LEADS) else []
    return _tp_ci_filter_countable(leads)


async def _collect_period_leads(scope: str, key: str, start_iso: str, end_iso: str) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]], str]:  # type: ignore[override]
    if callable(_TP_CI_ORIG_COLLECT_PERIOD_LEADS):
        leads, rows, scope_label = await _TP_CI_ORIG_COLLECT_PERIOD_LEADS(scope, key, start_iso, end_iso)
