async def _tp_ci_backfill_contact_memory_once() -> None:
    # Idempotent. It can safely run on every controller startup and picks up newly added managers.
    await _tp_ci_ensure_contact_identity_tables()
    await _tp_ci_ensure_partner_event_identity_columns()
    try:
        rows = await _manager_rows_for_reporting()
    except Exception:
        rows = []
    for mgr in rows or []:
        mk = _tp_ci_norm_key((mgr or {}).get("manager_key") or "")
        dbp = str((mgr or {}).get("db_path") or "")
        if not mk or not dbp or not os.path.exists(dbp):
            continue
        await _tp_ci_ensure_daily_identity_columns(dbp)
        source_key = _tp_ci_source_key_for_manager_sync(mk)
        try:
            con = _tp_ci_connect(dbp)
            con.row_factory = _tp_ci_sqlite3.Row
            items: list[dict] = []
            try:
                if _tp_ci_table_exists_sync(con, "daily_leads"):
                    for r in con.execute("SELECT chat_id, username, full_name, phone, first_seen_utc, created_at FROM daily_leads WHERE COALESCE(chat_id,0)>0").fetchall():
                        d = dict(r); d["_source"] = "daily_leads"; items.append(d)
                if _tp_ci_table_exists_sync(con, "baseline_old_chats"):
                    for r in con.execute("SELECT chat_id, username, full_name, '' AS phone, created_at AS first_seen_utc, created_at FROM baseline_old_chats WHERE COALESCE(chat_id,0)>0").fetchall():
                        d = dict(r); d["_source"] = "baseline_old_chats"; items.append(d)
                if _tp_ci_table_exists_sync(con, "leads"):
                    for r in con.execute("SELECT chat_id, username, full_name, '' AS phone, COALESCE(first_seen,last_seen,'') AS first_seen_utc, COALESCE(first_seen,last_seen,'') AS created_at FROM leads WHERE COALESCE(chat_id,0)>0").fetchall():
                        d = dict(r); d["_source"] = "leads"; items.append(d)
                if _tp_ci_table_exists_sync(con, "messages"):
                    for r in con.execute("SELECT chat_id, '' AS username, '' AS full_name, '' AS phone, MIN(ts) AS first_seen_utc, MIN(ts) AS created_at FROM messages WHERE COALESCE(direction,'')='in' AND COALESCE(chat_id,0)>0 GROUP BY chat_id").fetchall():
                        d = dict(r); d["_source"] = "messages"; items.append(d)
            finally:
                con.close()
            for item in items:
                try:
                    chat_id = int(item.get("chat_id") or 0)
                    if chat_id <= 0:
                        continue
                    seen = str(item.get("first_seen_utc") or item.get("created_at") or _tp_ci_now_iso())
                    _tp_ci_upsert_contact_sync(
                        chat_id=chat_id,
                        username=str(item.get("username") or ""),
                        phone=str(item.get("phone") or ""),
                        full_name=str(item.get("full_name") or ""),
                        first_seen_at=seen,
                        manager_key=mk,
                        source_key=source_key,
                        allow_create=True,
                    )
                except Exception:
                    pass
        except Exception as e:
            print(f"contact_identity backfill manager={mk} error: {e!r}")


async def _tp_ci_reclassify_existing_daily_rows_once() -> None:
    try:
        rows = await _manager_rows_for_reporting()
    except Exception:
        rows = []
    all_rows: list[dict] = []
    baseline_pairs: set[tuple[str, int]] = set()
    for mgr in rows or []:
        mk = _tp_ci_norm_key((mgr or {}).get("manager_key") or "")
        dbp = str((mgr or {}).get("db_path") or "")
        if not mk or not dbp or not os.path.exists(dbp):
            continue
        await _tp_ci_ensure_daily_identity_columns(dbp)
        try:
            con = _tp_ci_connect(dbp)
            try:
                if _tp_ci_table_exists_sync(con, "baseline_old_chats"):
                    for r in con.execute("SELECT chat_id FROM baseline_old_chats WHERE COALESCE(chat_id,0)>0").fetchall():
                        baseline_pairs.add((mk, int(r[0] or 0)))
                if _tp_ci_table_exists_sync(con, "daily_leads"):
                    for r in con.execute("SELECT * FROM daily_leads WHERE COALESCE(chat_id,0)>0 ORDER BY first_seen_utc ASC, id ASC").fetchall():
                        d = dict(r)
                        d["_db_path"] = dbp
                        d["_manager_key"] = mk
                        all_rows.append(d)
            finally:
                con.close()
        except Exception as e:
            print(f"contact_identity reclass read manager={mk} error: {e!r}")
    all_rows.sort(key=lambda x: (str(x.get("first_seen_utc") or ""), str(x.get("_manager_key") or ""), int(x.get("id") or 0)))
    first_by_chat: dict[int, dict] = {}
    for r in all_rows:
        try:
            chat_id = int(r.get("chat_id") or 0)
            if chat_id <= 0:
                continue
            mk = _tp_ci_norm_key(r.get("_manager_key") or r.get("manager_key") or "")
            dbp = str(r.get("_db_path") or "")
            row_id = int(r.get("id") or 0)
            contact = _tp_ci_contact_by_chat_sync(chat_id)
            cid = int(contact.get("id") or 0)
            first_seen_global_at = str(contact.get("first_seen_at") or r.get("first_seen_utc") or "")
            first_mgr = _tp_ci_norm_key(contact.get("first_manager_key") or "")
            if (mk, chat_id) in baseline_pairs:
                kind, countable, reason, base_old, returning, dup = "old_baseline", 0, "baseline_old_chats", 1, 1, 0
            elif chat_id not in first_by_chat:
                first_by_chat[chat_id] = {"manager_key": mk, "first_seen_utc": str(r.get("first_seen_utc") or ""), "row_id": row_id}
                kind, countable, reason, base_old, returning, dup = "new", 1, "new_contact", 0, 0, 0
                if not first_mgr:
                    first_mgr = mk
            else:
                first = first_by_chat.get(chat_id) or {}
                same_mgr = _tp_ci_norm_key(first.get("manager_key") or "") == mk
                kind = "returning" if same_mgr else "duplicate"
                countable = 0
                reason = "seen_before_same_manager" if same_mgr else "seen_before_other_manager"
                base_old, returning, dup = 0, 1, (0 if same_mgr else 1)
                first_mgr = _tp_ci_norm_key(first.get("manager_key") or first_mgr or "")
            await _tp_ci_set_daily_identity(
                dbp,
                row_id,
                contact_kind=kind,
                lead_countable=countable,
                known_contact_id=cid,
                event_key=str(r.get("event_key") or f"legacy:{mk}:{row_id}:{chat_id}"),
                dedupe_reason=reason,
                baseline_old=base_old,
                returning=returning,
                first_seen_global_at=first_seen_global_at,
                first_seen_global_manager_key=first_mgr,
                duplicate=dup,
                ai_stat_sent=None,
            )
        except Exception as e:
            print(f"contact_identity reclass row error: {e!r}")


async def _tp_ci_startup_init() -> None:
    try:
        await _tp_ci_ensure_contact_identity_tables()
        await _tp_ci_ensure_partner_event_identity_columns()
        await _tp_ci_ensure_daily_identity_columns(DB_PATH)
        if CONTROLLER_MODE:
            await _tp_ci_backfill_contact_memory_once()
            await _tp_ci_reclassify_existing_daily_rows_once()
    except Exception as e:
        print(f"contact_identity startup init error: {e!r}")


async def main() -> None:  # type: ignore[override]
    await _tp_ci_startup_init()
    if callable(_TP_CI_ORIG_MAIN):
        await _TP_CI_ORIG_MAIN()
    else:
        raise RuntimeError("Original main() is not available after contact identity patch")
