# --- TPILOT QUALITY STATUS ENGINE V1 20260510 START ---
# Deterministic status engine for lead quality:
# TRASH -> -18 -> GEO -> LIQUID -> NA.
# Unclear cases are not guessed: they stay NA with confidence/reason.

import sqlite3 as _tp_qs_sqlite3

_TP_QS_VERSION = "quality_status_v1_20260510"
_TP_QS_ORIG_MAIN = globals().get("main")
_TP_QS_ORIG_ENSURE_DAILY_LEADS_TABLE = globals().get("_ensure_daily_leads_table")
_TP_QS_ORIG_UPDATE_DAILY_LEAD_FIELDS = globals().get("_update_daily_lead_fields")
_TP_QS_ORIG_COMBINE_PROFILE = globals().get("_combine_profile")
_TP_QS_ORIG_RECORD_INCOMING = globals().get("_record_incoming_from_manager")
_TP_QS_ORIG_HANDLE_AI_STAT_COMMAND = globals().get("_handle_ai_stat_command")
_TP_QS_ORIG_PANEL_EXEC = globals().get("_panel_execute_command_text")

_TP_QS_RECALC_GUARD = False


# --- TPILOT AUTO STATUS DISABLE SWITCH (Patch A) START ---
# AdminBot button writes settings['auto_status_enabled'] = '0'/'1' to the central DB.
# This is the master gate for AUTOMATIC lead-status / quality-bucket writes ONLY.
# Manual manager status (lead_status_overrides, ManagerBot mb:s: callbacks, /lead fix) is
# never gated by this switch -- manual status remains the single source of truth in every
# case, same as before this patch. Missing key -> enabled ("1"), same behavior as today.
_AUTOSTATUS_RTGATE_CACHE: Optional[bool] = None
_AUTOSTATUS_RTGATE_CACHE_AT: float = 0.0
_AUTOSTATUS_RTGATE_TTL: float = 20.0  # seconds


async def _autostatus_runtime_enabled() -> bool:
    """Return True if automatic lead-status detection/writes are enabled (DB toggle
    master). Missing key or DB read error -> preserve current behavior (enabled),
    same fail-safe pattern as _llm_runtime_enabled()."""
    global _AUTOSTATUS_RTGATE_CACHE, _AUTOSTATUS_RTGATE_CACHE_AT
    import time as _t
    now = _t.monotonic()
    if _AUTOSTATUS_RTGATE_CACHE is not None and now - _AUTOSTATUS_RTGATE_CACHE_AT < _AUTOSTATUS_RTGATE_TTL:
        return _AUTOSTATUS_RTGATE_CACHE
    try:
        val = await get_setting_from_db(TPILOT_DB_PATH, "auto_status_enabled")
        result = val != "0"
        _AUTOSTATUS_RTGATE_CACHE = result
        _AUTOSTATUS_RTGATE_CACHE_AT = now
        return result
    except Exception:
        return _AUTOSTATUS_RTGATE_CACHE if _AUTOSTATUS_RTGATE_CACHE is not None else True


def _autostatus_enabled_sync() -> bool:
    """Sync-context snapshot of the auto-status gate for the few call sites that cannot
    await (e.g. _tp_pss_decide_from_facts). Reads the cache populated by the async gate;
    defaults to enabled (True) until the async gate has run at least once in this process,
    preserving current behavior."""
    return True if _AUTOSTATUS_RTGATE_CACHE is None else _AUTOSTATUS_RTGATE_CACHE
# --- TPILOT AUTO STATUS DISABLE SWITCH (Patch A) END ---


def _tp_qs_now_iso() -> str:
    try:
        return _now_utc_iso()
    except Exception:
        return _tp_utc_now().replace(microsecond=0).isoformat()


def _tp_qs_norm_key(raw: Any) -> str:
    try:
        return registry_normalize_manager_key(str(raw or ""))
    except Exception:
        return re.sub(r"[^a-z0-9_-]+", "", str(raw or "").strip().lower())


def _tp_qs_text(raw: Any) -> str:
    return str(raw or "").strip()


def _tp_qs_low(raw: Any) -> str:
    return _tp_qs_text(raw).lower().replace("ё", "е")


def _tp_qs_int_or_none(raw: Any) -> Optional[int]:
    # --- TPILOT AGE0 FIX M2.6I START ---
    # age=0 is a technical placeholder for "unknown", never a real age — normalize to None.
    # NOTE: this helper is also used for non-age numeric fields; callers that need age
    # specifically rely on the caller-level age<18 checks below, which treat None as unknown.
    try:
        if raw is None:
            return None
        s = str(raw).strip()
        if not s:
            return None
        v = int(float(s))
        return v if v != 0 else None
    except Exception:
        return None
    # --- TPILOT AGE0 FIX M2.6I END ---


def _tp_qs_connect(path: str) -> _tp_qs_sqlite3.Connection:
    parent = os.path.dirname(os.path.abspath(str(path)))
    if parent:
        os.makedirs(parent, exist_ok=True)
    con = _tp_qs_sqlite3.connect(str(path), timeout=30)
    con.row_factory = _tp_qs_sqlite3.Row
    try:
        con.execute("PRAGMA journal_mode=WAL;")
    except Exception:
        pass
    try:
        con.execute("PRAGMA busy_timeout=30000;")
    except Exception:
        pass
    return con


def _tp_qs_table_exists_sync(con: _tp_qs_sqlite3.Connection, table: str) -> bool:
    try:
        return bool(con.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=? LIMIT 1", (table,)).fetchone())
    except Exception:
        return False


def _tp_qs_cols_sync(con: _tp_qs_sqlite3.Connection, table: str) -> set[str]:
    try:
        return {str(r[1]) for r in con.execute(f"PRAGMA table_info({table})").fetchall()}
    except Exception:
        return set()


async def _tp_qs_ensure_status_tables(db_path: str) -> None:
    if not db_path:
        return
    parent = os.path.dirname(str(db_path))
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(str(db_path)) as db:
        await db.execute("PRAGMA journal_mode=WAL;")
        await db.execute("PRAGMA busy_timeout=30000;")
        await db.execute("""
            CREATE TABLE IF NOT EXISTS daily_leads(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                lead_date TEXT NOT NULL,
                manager_key TEXT NOT NULL DEFAULT '',
                chat_id INTEGER NOT NULL,
                first_seen_utc TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT '',
                UNIQUE(lead_date, manager_key, chat_id)
            );
        """)
        cols = await _table_columns(db, "daily_leads") if callable(globals().get("_table_columns")) else []
        migrations = [
            ("quality_status", "ALTER TABLE daily_leads ADD COLUMN quality_status TEXT NOT NULL DEFAULT ''"),
            ("quality_bucket", "ALTER TABLE daily_leads ADD COLUMN quality_bucket TEXT NOT NULL DEFAULT ''"),
            ("quality_reason", "ALTER TABLE daily_leads ADD COLUMN quality_reason TEXT NOT NULL DEFAULT ''"),
            ("quality_confidence", "ALTER TABLE daily_leads ADD COLUMN quality_confidence TEXT NOT NULL DEFAULT ''"),
            ("quality_source", "ALTER TABLE daily_leads ADD COLUMN quality_source TEXT NOT NULL DEFAULT ''"),
            ("quality_checked_at", "ALTER TABLE daily_leads ADD COLUMN quality_checked_at TEXT NOT NULL DEFAULT ''"),
            ("quality_version", "ALTER TABLE daily_leads ADD COLUMN quality_version TEXT NOT NULL DEFAULT ''"),
            ("profile_raw_text", "ALTER TABLE daily_leads ADD COLUMN profile_raw_text TEXT NOT NULL DEFAULT ''"),
            ("age_confidence", "ALTER TABLE daily_leads ADD COLUMN age_confidence TEXT NOT NULL DEFAULT ''"),
            ("country_confidence", "ALTER TABLE daily_leads ADD COLUMN country_confidence TEXT NOT NULL DEFAULT ''"),
            ("city_confidence", "ALTER TABLE daily_leads ADD COLUMN city_confidence TEXT NOT NULL DEFAULT ''"),
            ("manual_status_override", "ALTER TABLE daily_leads ADD COLUMN manual_status_override INTEGER NOT NULL DEFAULT 0"),
            ("manual_status_reason", "ALTER TABLE daily_leads ADD COLUMN manual_status_reason TEXT NOT NULL DEFAULT ''"),
            ("manual_status_by", "ALTER TABLE daily_leads ADD COLUMN manual_status_by TEXT NOT NULL DEFAULT ''"),
            ("manual_status_at", "ALTER TABLE daily_leads ADD COLUMN manual_status_at TEXT NOT NULL DEFAULT ''"),
            ("trash", "ALTER TABLE daily_leads ADD COLUMN trash INTEGER NOT NULL DEFAULT 0"),
            ("trash_reason", "ALTER TABLE daily_leads ADD COLUMN trash_reason TEXT NOT NULL DEFAULT ''"),
        ]
        for col, ddl in migrations:
            if col not in cols:
                try:
                    await db.execute(ddl)
                except Exception:
                    pass
        await db.execute("CREATE INDEX IF NOT EXISTS daily_leads_quality_idx ON daily_leads(lead_date, quality_bucket, manager_key);")
        await db.execute("CREATE INDEX IF NOT EXISTS daily_leads_quality_countable_idx ON daily_leads(lead_date, lead_countable, quality_bucket, manager_key);")
        await db.execute("""
            CREATE TABLE IF NOT EXISTS lead_status_audit(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                manager_key TEXT NOT NULL DEFAULT '',
                chat_id INTEGER NOT NULL DEFAULT 0,
                lead_date TEXT NOT NULL DEFAULT '',
                old_status TEXT NOT NULL DEFAULT '',
                new_status TEXT NOT NULL DEFAULT '',
                old_bucket TEXT NOT NULL DEFAULT '',
                new_bucket TEXT NOT NULL DEFAULT '',
                old_reason TEXT NOT NULL DEFAULT '',
                new_reason TEXT NOT NULL DEFAULT '',
                source TEXT NOT NULL DEFAULT '',
                confidence TEXT NOT NULL DEFAULT '',
                raw_text TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL DEFAULT ''
            );
        """)
        await db.execute("CREATE INDEX IF NOT EXISTS lead_status_audit_chat_idx ON lead_status_audit(chat_id, id);")
        await db.execute("CREATE INDEX IF NOT EXISTS lead_status_audit_date_idx ON lead_status_audit(lead_date, manager_key);")
        await db.execute("""
            CREATE TABLE IF NOT EXISTS lead_status_overrides(
                chat_id INTEGER NOT NULL,
                manager_key TEXT NOT NULL DEFAULT '',
                status TEXT NOT NULL DEFAULT '',
                bucket TEXT NOT NULL DEFAULT '',
                reason TEXT NOT NULL DEFAULT '',
                comment TEXT NOT NULL DEFAULT '',
                updated_by TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT '',
                PRIMARY KEY(chat_id, manager_key)
            );
        """)
        await db.execute("""
            CREATE TABLE IF NOT EXISTS llm_auto_status(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                manager_key TEXT NOT NULL DEFAULT '',
                chat_id TEXT NOT NULL DEFAULT '',
                lead_date TEXT NOT NULL DEFAULT '',
                final_status_used TEXT NOT NULL DEFAULT '',
                manual_status TEXT NOT NULL DEFAULT '',
                llm_auto_status TEXT NOT NULL DEFAULT '',
                deterministic_auto_status TEXT NOT NULL DEFAULT '',
                llm_reason TEXT NOT NULL DEFAULT '',
                llm_detail TEXT NOT NULL DEFAULT '',
                city TEXT NOT NULL DEFAULT '',
                country TEXT NOT NULL DEFAULT '',
                region TEXT NOT NULL DEFAULT '',
                age TEXT NOT NULL DEFAULT '',
                current_location TEXT NOT NULL DEFAULT '',
                confidence TEXT NOT NULL DEFAULT '',
                safety_flags TEXT NOT NULL DEFAULT '',
                source_hash TEXT NOT NULL DEFAULT '',
                source_window TEXT NOT NULL DEFAULT '',
                agrees_with_manager INTEGER,
                mismatch_reason TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT '',
                UNIQUE(lead_date, manager_key, chat_id)
            );
        """)
        await db.execute(
            "CREATE INDEX IF NOT EXISTS llm_auto_status_date_idx"
            " ON llm_auto_status(lead_date, manager_key);"
        )
        await db.commit()


async def _ensure_daily_leads_table(db_path: str) -> None:  # type: ignore[override]
    if callable(_TP_QS_ORIG_ENSURE_DAILY_LEADS_TABLE):
        await _TP_QS_ORIG_ENSURE_DAILY_LEADS_TABLE(db_path)
    await _tp_qs_ensure_status_tables(db_path)


def _tp_qs_trash_detect(row: Dict[str, Any]) -> Tuple[bool, str]:
    status = _tp_qs_low(row.get("status"))
    reason = _tp_qs_low(row.get("nonliquid_reason"))
    trash_reason = _tp_qs_text(row.get("trash_reason"))
    raw = _tp_qs_low(row.get("profile_raw_text") or row.get("text") or "")
    if int(row.get("trash") or 0) == 1:
        return True, trash_reason or "trash"
    if status == "trash" or "trash" in reason or "send_failed" in reason or "недоступ" in reason:
        return True, _tp_qs_text(row.get("nonliquid_reason")) or trash_reason or "trash"
    patterns = [
        r"\bхуй\w*\b", r"\bпизд\w*\b", r"\bеба\w*\b", r"\bебан\w*\b", r"\bнахуй\b",
        r"\bпош[её]л\b", r"\bсука\b", r"\bмраз\w*\b", r"\bотвали\b", r"\bиди\s+на\b",
        r"\bспам\b", r"\bскам\b",
    ]
    try:
        if raw and any(re.search(p, raw, flags=re.I) for p in patterns):
            return True, "trash_text"
    except Exception:
        pass
    return False, ""


def _tp_qs_decide(row: Dict[str, Any], *, source: str = "rules") -> Dict[str, Any]:
    age = _tp_qs_int_or_none(row.get("age"))
    country = _tp_qs_text(row.get("country"))
    city = _tp_qs_text(row.get("city"))
    region = _tp_qs_text(row.get("region"))
    status_old = _tp_qs_low(row.get("status"))
    reason_old = _tp_qs_text(row.get("nonliquid_reason"))
    geo_conf = _tp_qs_low(row.get("geo_confidence"))
    now = _tp_qs_now_iso()

    is_trash, trash_reason = _tp_qs_trash_detect(row)
    if is_trash:
        return {
            "status": "trash",
            "bucket": "trash",
            "reason": trash_reason or "trash",
            "confidence": "high",
            "source": source,
            "checked_at": now,
            "version": _TP_QS_VERSION,
            "legacy_status": "trash",
            "legacy_reason": trash_reason or "trash",
            "profile_done": 1,
        }

    if age is not None and age < 18:
        return {
            "status": "nonliquid",
            "bucket": "under18",
            "reason": "under18",
            "confidence": "high",
            "source": source,
            "checked_at": now,
            "version": _TP_QS_VERSION,
            "legacy_status": "nonliquid",
            "legacy_reason": "-18",
            "profile_done": 1,
        }

    if country and country != "Россия":
        reason = "country_" + country.lower().replace(" ", "_")
        return {
            "status": "nonliquid",
            "bucket": "geo",
            "reason": reason,
            "confidence": "high" if geo_conf in ("", "high", "exact", "strong") else "medium",
            "source": source,
            "checked_at": now,
            "version": _TP_QS_VERSION,
            "legacy_status": "nonliquid",
            "legacy_reason": country,
            "profile_done": 1,
        }

    if country == "Россия" and age is not None and age >= 18:
        return {
            "status": "liquid",
            "bucket": "liquid",
            "reason": "ru_18_plus" if city or region else "ru_18_plus_city_unknown",
            "confidence": "high",
            "source": source,
            "checked_at": now,
            "version": _TP_QS_VERSION,
            "legacy_status": "liquid",
            "legacy_reason": "",
            "profile_done": 1,
        }

    # Strict NA: do not guess from old status if required facts are missing.
    if age is None and not country and not city:
        reason = "age_and_geo_missing"
        bucket = "na"
    elif age is None:
        reason = "age_missing"
        bucket = "age_missing"
    elif not country and not city:
        reason = "geo_missing"
        bucket = "geo_missing"
    elif country == "Россия" and age is None:
        reason = "age_missing"
        bucket = "age_missing"
    else:
        reason = "unclear"
        bucket = "na"

    # Preserve old explicit unknown/NA language but never upgrade to liquid/nonliquid without facts.
    if status_old in ("unknown", "na") or _tp_qs_low(reason_old) in ("na", "не определено", "unknown"):
        reason = reason if reason != "unclear" else "unclear_profile"

    return {
        "status": "na",
        "bucket": bucket,
        "reason": reason,
        "confidence": "high" if reason in ("age_missing", "geo_missing", "age_and_geo_missing") else "low",
        "source": source,
        "checked_at": now,
        "version": _TP_QS_VERSION,
        "legacy_status": "unknown",
        "legacy_reason": "",
        "profile_done": int(row.get("profile_done") or 0),
    }


def _tp_qs_decision_fields(decision: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "quality_status": decision.get("status") or "na",
        "quality_bucket": decision.get("bucket") or "na",
        "quality_reason": decision.get("reason") or "",
        "quality_confidence": decision.get("confidence") or "low",
        "quality_source": decision.get("source") or "rules",
        "quality_checked_at": decision.get("checked_at") or _tp_qs_now_iso(),
        "quality_version": decision.get("version") or _TP_QS_VERSION,
    }


def _tp_qs_legacy_fields(decision: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "status": decision.get("legacy_status") or ("liquid" if decision.get("bucket") == "liquid" else ("nonliquid" if decision.get("bucket") in ("geo", "under18", "trash") else "unknown")),
        "nonliquid_reason": decision.get("legacy_reason") or "",
        "profile_done": int(decision.get("profile_done") or 0),
    }


async def _tp_qs_insert_audit(db_path: str, old: Dict[str, Any], new_decision: Dict[str, Any], *, raw_text: str = "") -> None:
    try:
        await _tp_qs_ensure_status_tables(db_path)
        old_status = _tp_qs_text(old.get("quality_status") or old.get("status"))
        old_bucket = _tp_qs_text(old.get("quality_bucket"))
        old_reason = _tp_qs_text(old.get("quality_reason") or old.get("nonliquid_reason"))
        new_status = _tp_qs_text(new_decision.get("status"))
        new_bucket = _tp_qs_text(new_decision.get("bucket"))
        new_reason = _tp_qs_text(new_decision.get("reason"))
        if old_status == new_status and old_bucket == new_bucket and old_reason == new_reason:
            return
        async with aiosqlite.connect(db_path) as db:
            await db.execute(
                """
                INSERT INTO lead_status_audit(
                    manager_key, chat_id, lead_date, old_status, new_status,
                    old_bucket, new_bucket, old_reason, new_reason,
                    source, confidence, raw_text, created_at
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    _tp_qs_norm_key(old.get("manager_key") or MANAGER_RUNTIME_KEY),
                    int(old.get("chat_id") or 0),
                    str(old.get("lead_date") or ""),
                    old_status,
                    new_status,
                    old_bucket,
                    new_bucket,
                    old_reason,
                    new_reason,
                    _tp_qs_text(new_decision.get("source")),
                    _tp_qs_text(new_decision.get("confidence")),
                    raw_text or _tp_qs_text(old.get("profile_raw_text")),
                    _tp_qs_now_iso(),
                ),
            )
            await db.commit()
    except Exception as e:
        print(f"quality status audit error: {e!r}")


async def _tp_qs_fetch_daily_row(db_path: str, lead_date: str, manager_key: str, chat_id: int) -> Dict[str, Any]:
    try:
        await _tp_qs_ensure_status_tables(db_path)
        async with aiosqlite.connect(db_path) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute(
                "SELECT * FROM daily_leads WHERE lead_date=? AND manager_key=? AND chat_id=? LIMIT 1",
                (str(lead_date), _tp_qs_norm_key(manager_key), int(chat_id)),
            )
            row = await cur.fetchone()
            return dict(row) if row else {}
    except Exception:
        return {}


async def _update_daily_lead_fields(db_path: str, *, lead_date: str, manager_key: str, chat_id: int, **fields: Any) -> None:  # type: ignore[override]
    global _TP_QS_RECALC_GUARD
    if not fields:
        return
    await _ensure_daily_leads_table(db_path)
    allowed = {
        "age", "city", "region", "country", "city_raw", "country_raw", "geo_source", "geo_confidence", "geo_note",
        "status", "nonliquid_reason", "profile_done", "profile_question_sent", "profile_question_at", "profile_answered_at",
        "ua_text_sent", "ua_text_sent_at", "manager_work_status", "offline_notice_sent", "offline_notice_period_key",
        "manager_replied", "manager_replied_at", "clarify_attempts", "profile_final_sent", "profile_final_sent_at", "geoage_sent", "geoage_sent_at",
        "contact_kind", "lead_countable", "known_contact_id", "event_key", "dedupe_reason", "baseline_old", "returning_flag", "first_seen_global_at", "first_seen_global_manager_key", "duplicate", "ai_stat_sent",
        "quality_status", "quality_bucket", "quality_reason", "quality_confidence", "quality_source", "quality_checked_at", "quality_version",
        "profile_raw_text", "age_confidence", "country_confidence", "city_confidence", "manual_status_override", "manual_status_reason", "manual_status_by", "manual_status_at", "trash", "trash_reason",
        "updated_at",
    }
    data = {k: v for k, v in dict(fields).items() if k in allowed}
    if not data:
        return
    data["updated_at"] = data.get("updated_at") or _tp_qs_now_iso()
    keys = list(data.keys())
    vals = [data[k] for k in keys]
    sql = "UPDATE daily_leads SET " + ", ".join([f"{k}=?" for k in keys]) + " WHERE lead_date=? AND manager_key=? AND chat_id=?"
    vals.extend([str(lead_date), _tp_qs_norm_key(manager_key), int(chat_id)])
    async with aiosqlite.connect(db_path) as db:
        await db.execute(sql, tuple(vals))
        await db.commit()

    relevant = {
        "age", "city", "region", "country", "status", "nonliquid_reason", "profile_raw_text", "geo_confidence", "trash", "trash_reason",
        "manual_status_override", "quality_status", "quality_bucket", "quality_reason",
    }
    if _TP_QS_RECALC_GUARD or not (set(data.keys()) & relevant):
        return
    if int(data.get("manual_status_override") or 0) == 1 or any(k.startswith("quality_") for k in data.keys()):
        return
    if not await _autostatus_runtime_enabled():
        return
    try:
        _TP_QS_RECALC_GUARD = True
        row = await _tp_qs_fetch_daily_row(db_path, lead_date, manager_key, chat_id)
        if not row or int(row.get("manual_status_override") or 0) == 1:
            return
        decision = _tp_qs_decide(row, source="auto_update")
        await _tp_qs_insert_audit(db_path, row, decision, raw_text=str(row.get("profile_raw_text") or ""))
        qf = _tp_qs_decision_fields(decision)
        legacy = _tp_qs_legacy_fields(decision)
        keys2 = list(qf.keys()) + ["status", "nonliquid_reason", "profile_done", "updated_at"]
        vals2 = [qf[k] for k in qf.keys()] + [legacy["status"], legacy["nonliquid_reason"], legacy["profile_done"], _tp_qs_now_iso(), str(lead_date), _tp_qs_norm_key(manager_key), int(chat_id)]
        sql2 = "UPDATE daily_leads SET " + ", ".join([f"{k}=?" for k in keys2]) + " WHERE lead_date=? AND manager_key=? AND chat_id=?"
        async with aiosqlite.connect(db_path) as db:
            await db.execute(sql2, tuple(vals2))
            await db.commit()
    finally:
        _TP_QS_RECALC_GUARD = False


def _combine_profile(existing: Dict[str, Any], parsed: Dict[str, Any]) -> Dict[str, Any]:  # type: ignore[override]
    if callable(_TP_QS_ORIG_COMBINE_PROFILE):
        combined = _TP_QS_ORIG_COMBINE_PROFILE(existing, parsed)
    else:
        combined = dict(existing or {})
        combined.update(parsed or {})
    if _autostatus_enabled_sync():
        row = dict(existing or {})
        row.update(combined or {})
        decision = _tp_qs_decide(row, source="profile_parse")
        combined.update(_tp_qs_decision_fields(decision))
        combined.update(_tp_qs_legacy_fields(decision))
    try:
        if combined.get("age") is not None:
            combined["age_confidence"] = "high"
        if combined.get("country"):
            combined["country_confidence"] = "high"
        if combined.get("city"):
            combined["city_confidence"] = "high"
    except Exception:
        pass
    return combined


def _tp_qs_row_bucket(lead: Dict[str, Any]) -> Dict[str, Any]:
    if lead.get("quality_status") or lead.get("quality_bucket"):
        dec = {
            "status": _tp_qs_text(lead.get("quality_status") or "na"),
            "bucket": _tp_qs_text(lead.get("quality_bucket") or "na"),
            "reason": _tp_qs_text(lead.get("quality_reason") or ""),
            "confidence": _tp_qs_text(lead.get("quality_confidence") or ""),
        }
    else:
        dec = _tp_qs_decide(lead, source="read_runtime")
    bucket = _tp_qs_text(dec.get("bucket") or "na")
    if bucket in ("age_missing", "geo_missing"):
        status = "na"
    else:
        status = _tp_qs_text(dec.get("status") or "na")
    return {"status": status, "bucket": bucket, "reason": _tp_qs_text(dec.get("reason") or ""), "confidence": _tp_qs_text(dec.get("confidence") or "")}


async def _tp_qs_repair_db(db_path: str, *, date_filter: str = "") -> int:
    if not db_path or not os.path.exists(db_path):
        return 0
    if not await _autostatus_runtime_enabled():
        return 0
    await _tp_qs_ensure_status_tables(db_path)
    try:
        # Pull trash flags from reminder table when available.
        con = _tp_qs_connect(db_path)
        try:
            if _tp_qs_table_exists_sync(con, "lead_profile_reminders") and _tp_qs_table_exists_sync(con, "daily_leads"):
                rows_tr = con.execute("SELECT chat_id, trash, trash_reason FROM lead_profile_reminders WHERE COALESCE(trash,0)=1").fetchall()
                for tr in rows_tr or []:
                    con.execute("UPDATE daily_leads SET trash=1, trash_reason=CASE WHEN COALESCE(trash_reason,'')='' THEN ? ELSE trash_reason END WHERE chat_id=?", (str(tr["trash_reason"] or "trash"), int(tr["chat_id"] or 0)))
                con.commit()
        finally:
            con.close()
    except Exception:
        pass

    updated = 0
    async with aiosqlite.connect(db_path) as db:
        db.row_factory = aiosqlite.Row
        if date_filter:
            cur = await db.execute("SELECT * FROM daily_leads WHERE lead_date=? ORDER BY id ASC", (str(date_filter),))
        else:
            cur = await db.execute("SELECT * FROM daily_leads ORDER BY lead_date ASC, id ASC")
        rows = [dict(r) for r in await cur.fetchall()]
    for row in rows:
        try:
            if int(row.get("manual_status_override") or 0) == 1:
                continue
            decision = _tp_qs_decide(row, source="repair")
            await _tp_qs_insert_audit(db_path, row, decision, raw_text=str(row.get("profile_raw_text") or ""))
            qf = _tp_qs_decision_fields(decision)
            legacy = _tp_qs_legacy_fields(decision)
            async with aiosqlite.connect(db_path) as db:
                await db.execute(
                    """
                    UPDATE daily_leads
                    SET quality_status=?, quality_bucket=?, quality_reason=?, quality_confidence=?,
                        quality_source=?, quality_checked_at=?, quality_version=?,
                        status=?, nonliquid_reason=?, profile_done=?, updated_at=?
                    WHERE id=?
                    """,
                    (
                        qf["quality_status"], qf["quality_bucket"], qf["quality_reason"], qf["quality_confidence"],
                        qf["quality_source"], qf["quality_checked_at"], qf["quality_version"],
                        legacy["status"], legacy["nonliquid_reason"], legacy["profile_done"], _tp_qs_now_iso(), int(row.get("id") or 0),
                    ),
                )
                await db.commit()
            updated += 1
        except Exception as e:
            print(f"quality repair row error: {e!r}")
    return updated


async def _tp_qs_repair_all_manager_dbs(*, date_filter: str = "") -> int:
    total = 0
    try:
        rows = await _manager_rows_for_reporting()
    except Exception:
        rows = []
    for mgr in rows or []:
        dbp = str((mgr or {}).get("db_path") or "")
        if dbp and os.path.exists(dbp):
            total += await _tp_qs_repair_db(dbp, date_filter=date_filter)
    return total


async def _record_incoming_from_manager(event: events.NewMessage.Event) -> None:  # type: ignore[override]
    raw_text = ""
    chat_id = 0
    try:
        raw_text = str(getattr(event, "raw_text", "") or "")
        chat_id = int(getattr(event, "chat_id", 0) or 0)
    except Exception:
        pass
    if callable(_TP_QS_ORIG_RECORD_INCOMING):
        await _TP_QS_ORIG_RECORD_INCOMING(event)
    if not raw_text.strip() or chat_id <= 0 or CONTROLLER_MODE:
        return
    try:
        today = _kyiv_now().date().isoformat()
        row = await _tp_qs_fetch_daily_row(DB_PATH, today, MANAGER_RUNTIME_KEY, chat_id)
        if row and int(row.get("profile_question_sent") or 0) == 1 and int(row.get("manager_replied") or 0) != 1:
            await _update_daily_lead_fields(DB_PATH, lead_date=str(row.get("lead_date") or today), manager_key=str(row.get("manager_key") or MANAGER_RUNTIME_KEY), chat_id=chat_id, profile_raw_text=raw_text[:4000])
    except Exception as e:
        print(f"quality capture raw profile text error: {e!r}")


async def _tp_qs_find_lead_rows(chat_id: int) -> List[Dict[str, Any]]:
    out: List[Dict[str, Any]] = []
    try:
        mgrs = await _manager_rows_for_reporting()
    except Exception:
        mgrs = []
    for mgr in mgrs or []:
        try:
            mk = _tp_qs_norm_key((mgr or {}).get("manager_key") or "")
            dbp = str((mgr or {}).get("db_path") or "")
            if not dbp:
                dbp = str(BASE_DIR / "runtime" / "managers" / mk / f"{mk}.db")
            if not os.path.isabs(dbp):
                dbp = str((BASE_DIR / dbp).resolve())
            if not mk or not os.path.exists(dbp):
                continue
            con = _tp_qs_connect(dbp)
            try:
                if not _tp_qs_table_exists_sync(con, "daily_leads"):
                    continue
                for r in con.execute("SELECT * FROM daily_leads WHERE chat_id=? ORDER BY first_seen_utc DESC, id DESC", (int(chat_id),)).fetchall():
                    d = dict(r)
                    d["_db_path"] = dbp
                    d["_manager_key"] = mk
                    out.append(d)
            finally:
                con.close()
        except Exception:
            pass
    return out


async def _tp_qs_handle_lead_command(args: str, *, user_id: int = 0) -> str:
    parts = [p for p in str(args or "").split() if p.strip()]
    action = (parts[0].lower() if parts else "status")
    if action in ("help", ""):
        return "\n".join([
            "🧪 Lead Quality Engine",
            "",
            "/lead status <chat_id> - показать качество лида",
            "/lead fix <chat_id> liquid|geo|-18|under18|trash|na [причина] - ручное исправление",
            "/lead repair today|yesterday|all|ДД.ММ.ГГ - пересчита��ь статусы",
        ]).rstrip()
    if action == "status":
        if len(parts) < 2:
            return "Формат: /lead status <chat_id>"
        chat_id = int(parts[1])
        found = await _tp_qs_find_lead_rows(chat_id)
        if not found:
            return f"Лид не найден: {chat_id}"
        lines = ["🧪 Lead Quality", "", f"chat_id: {chat_id}"]
        for r in found[:10]:
            q = _tp_qs_row_bucket(r)
            lines += [
                "",
                f"Менеджер: {r.get('manager_key') or r.get('_manager_key')}",
                f"Дата: {r.get('lead_date')}",
                f"Контакт: {r.get('contact_kind') or '_'} | countable: {int(r.get('lead_countable', 0) or 0)}",
                f"Возраст: {_tp_qs_text(r.get('age')) or 'не определено'}",
                f"Страна: {_tp_qs_text(r.get('country')) or 'не определено'}",
                f"Регион: {_tp_qs_text(r.get('region')) or 'не определено'}",
                f"Город: {_tp_qs_text(r.get('city')) or 'не определено'}",
                f"Quality: {_tp_qs_bucket_label(q.get('bucket'))} | {q.get('reason') or '_'} | confidence: {q.get('confidence') or '_'}",
                f"Manual override: {'да' if int(r.get('manual_status_override') or 0) == 1 else 'нет'}",
            ]
            raw = _tp_qs_text(r.get("profile_raw_text"))
            if raw:
                lines.append("Ответ: " + raw[:500])
        if len(found) > 10:
            lines.append(f"\nПоказано 10 из {len(found)} строк.")
        return "\n".join(lines).rstrip()

    if action == "fix":
        if len(parts) < 3:
            return "Формат: /lead fix <chat_id> liquid|geo|-18|under18|trash|na [причина]"
        chat_id = int(parts[1])
        raw_status = parts[2].lower()
        comment = " ".join(parts[3:]).strip()
        mapping = {
            "liquid": ("liquid", "liquid", comment or "manual_liquid"),
            "geo": ("nonliquid", "geo", comment or "manual_geo"),
            "-18": ("nonliquid", "under18", "under18"),
            "under18": ("nonliquid", "under18", "under18"),
            "trash": ("trash", "trash", comment or "manual_trash"),
            "na": ("na", "na", comment or "manual_na"),
            "unknown": ("na", "na", comment or "manual_na"),
        }
        if raw_status not in mapping:
            return "Статус должен быть: liquid, geo, -18, under18, trash, na"
        qs, qb, qr = mapping[raw_status]
        legacy_status = "liquid" if qb == "liquid" else ("nonliquid" if qb in ("geo", "under18", "trash") else "unknown")
        legacy_reason = "" if qb == "liquid" else ("-18" if qb == "under18" else (qr if qb in ("geo", "trash") else ""))
        found = await _tp_qs_find_lead_rows(chat_id)
        if not found:
            return f"Лид не найден: {chat_id}"
        changed = 0
        for r in found:
            dbp = str(r.get("_db_path") or "")
            decision = {"status": qs, "bucket": qb, "reason": qr, "confidence": "manual", "source": "manual_override", "checked_at": _tp_qs_now_iso(), "version": _TP_QS_VERSION, "legacy_status": legacy_status, "legacy_reason": legacy_reason, "profile_done": 1}
            await _tp_qs_insert_audit(dbp, r, decision, raw_text=str(r.get("profile_raw_text") or ""))
            async with aiosqlite.connect(dbp) as db:
                await db.execute(
                    """
                    UPDATE daily_leads
                    SET quality_status=?, quality_bucket=?, quality_reason=?, quality_confidence=?, quality_source=?, quality_checked_at=?, quality_version=?,
                        status=?, nonliquid_reason=?, profile_done=1,
                        manual_status_override=1, manual_status_reason=?, manual_status_by=?, manual_status_at=?, updated_at=?
                    WHERE id=?
                    """,
                    (qs, qb, qr, "manual", "manual_override", _tp_qs_now_iso(), _TP_QS_VERSION, legacy_status, legacy_reason, qr, str(user_id or 0), _tp_qs_now_iso(), _tp_qs_now_iso(), int(r.get("id") or 0)),
                )
                await db.execute(
                    """
                    INSERT OR REPLACE INTO lead_status_overrides(chat_id, manager_key, status, bucket, reason, comment, updated_by, updated_at)
                    VALUES(?,?,?,?,?,?,?,?)
                    """,
                    (chat_id, _tp_qs_norm_key(r.get("manager_key") or r.get("_manager_key")), qs, qb, qr, comment, str(user_id or 0), _tp_qs_now_iso()),
                )
                await db.commit()
            changed += 1
        return f"✅ Статус исправлен\nchat_id: {chat_id}\nСтатус: {_tp_qs_bucket_label(qb)}\nСтрок обновлено: {changed}"

    if action == "repair":
        token = parts[1].lower() if len(parts) >= 2 else "today"
        date_filter = ""
        if token in ("today", "сегодня"):
            date_filter = _kyiv_now().date().isoformat()
        elif token in ("yesterday", "вчера"):
            date_filter = (_kyiv_now().date() - timedelta(days=1)).isoformat()
        elif token not in ("all", "в��е"):
            try:
                date_filter = _tp_parse_date_token(token).isoformat()  # type: ignore[name-defined]
            except Exception:
                try:
                    date_filter = datetime.strptime(token, "%d.%m.%y").date().isoformat()
                except Exception:
                    return "Формат: /lead repair today|yesterday|all|ДД.ММ.ГГ"
        total = await _tp_qs_repair_all_manager_dbs(date_filter=date_filter)
        return f"✅ Quality repair готов\nПериод: {date_filter or 'all'}\nСтрок пересчитано: {total}"
    return "Формат: /lead help"


async def _handle_ai_stat_command(event: events.NewMessage.Event) -> bool:  # type: ignore[override]
    try:
        if CONTROLLER_MODE and int(event.chat_id or 0) == int(AI_STAT_CHAT_ID or 0):
            cmd, args = _parse_cmd((event.raw_text or "").strip())
            if cmd == "/lead":
                await client.send_message(event.chat_id, await _tp_qs_handle_lead_command(args, user_id=int(event.sender_id or 0)))
                return True
    except Exception as e:
        try:
            await client.send_message(event.chat_id, f"Ошибка /lead: {e!r}")
            return True
        except Exception:
            pass
    if callable(_TP_QS_ORIG_HANDLE_AI_STAT_COMMAND):
        return await _TP_QS_ORIG_HANDLE_AI_STAT_COMMAND(event)
    return False


async def _panel_execute_command_text(command_text: str, *, requested_by: int = 0, source_chat_id: int = 0, response_chat_id: int = 0) -> Dict[str, Any]:  # type: ignore[override]
    cmd, args = _parse_cmd(str(command_text or ""))
    if cmd == "/lead":
        return {"ok": True, "result_text": await _tp_qs_handle_lead_command(args, user_id=requested_by)}
    if callable(_TP_QS_ORIG_PANEL_EXEC):
        try:
            return await _TP_QS_ORIG_PANEL_EXEC(command_text, requested_by=requested_by, source_chat_id=source_chat_id, response_chat_id=response_chat_id)
        except TypeError:
            try:
                return await _TP_QS_ORIG_PANEL_EXEC(command_text, requested_by=requested_by)
            except TypeError:
                return await _TP_QS_ORIG_PANEL_EXEC(command_text)
    return {"ok": False, "error_text": f"Команда не поддерживается: {cmd}"}


async def _tp_qs_startup_init() -> None:
    try:
        await _ensure_daily_leads_table(DB_PATH)
        if CONTROLLER_MODE:
            total = await _tp_qs_repair_all_manager_dbs(date_filter="")
            print(f"quality_status startup repair rows={total}")
    except Exception as e:
        print(f"quality_status startup init error: {e!r}")


