def _tp_report_v3_text(raw: Any) -> str:
    return str(raw or "").strip()


def _tp_report_v3_low(raw: Any) -> str:
    return _tp_report_v3_text(raw).lower().replace("ё", "е")


def _tp_report_v3_int(raw: Any, default: int = 0) -> int:
    try:
        return int(raw)
    except Exception:
        return int(default)


def _tp_report_v3_age(raw: Any) -> Optional[int]:
    # --- TPILOT AGE0 FIX M2.6I START ---
    # age=0 is a technical placeholder for "unknown", never a real age — normalize to None.
    try:
        if raw is None or str(raw).strip() == "":
            return None
        v = int(float(str(raw).strip()))
        return v if v != 0 else None
    except Exception:
        return None
    # --- TPILOT AGE0 FIX M2.6I END ---


def _tp_report_v3_country_title(raw: Any) -> str:
    s = _tp_report_v3_text(raw)
    if not s:
        return ""
    mapping = {
        "россия": "Россия", "рф": "Россия",
        "украина": "Украина", "узбекистан": "Узбекистан", "казахстан": "Казахстан",
        "кыргызстан": "Кыргызстан", "киргизия": "Кыргызстан", "беларусь": "Беларусь",
        "белоруссия": "Беларусь", "молдова": "Молдова", "таджикистан": "Таджикистан",
        "азербайджан": "Азербайджан", "армения": "Армения", "грузия": "Грузия",
        "германия": "Германия", "индия": "Индия", "гана": "Гана", "таиланд": "Таиланд",
        "турция": "Турция", "польша": "Польша", "литва": "Литва", "латвия": "Латвия",
        "эстония": "Эстония", "израиль": "Израиль", "сша": "США", "оаэ": "ОАЭ",
    }
    low = _tp_report_v3_low(s).replace("_", " ")
    return mapping.get(low, s[:1].upper() + s[1:])


def _tp_report_v3_reason_ru(reason: Any, *, bucket: str = "", country: Any = "") -> str:
    raw = _tp_report_v3_text(reason)
    low = _tp_report_v3_low(raw).replace("-", "_")
    bucket = _tp_report_v3_text(bucket)
    country_name = _tp_report_v3_country_title(country)
    if low.startswith("country_"):
        c = raw.split("_", 1)[1].replace("_", " ").strip()
        return "гео: " + _tp_report_v3_country_title(c)
    mapping = {
        "age_and_geo_missing": "не ответил на город и возраст",
        "age_missing": "18+ не подтверждён",
        "geo_missing": "гео не определено",
        "under18": "нет 18 лет / 18+ не подтверждён",
        "_18": "нет 18 лет / 18+ не подтверждён",
        "-18": "нет 18 лет / 18+ не подтверждён",
        "trash_text": "мусорный ответ / отказ",
        "trash": "трэш",
        "send_failed": "чат недоступен / отправка не прошла",
        "blocked": "клиент заблокировал",
        "inaccessible": "чат недоступен",
        "ru_18_plus": "Россия, 18+",
        "ru_18_plus_city_unknown": "Россия, 18+, город не определён",
        "unclear": "ответ не разобран",
        "unclear_profile": "ответ не разобран",
        "manual_liquid": "исправ��ено вручную: ликвид",
        "manual_geo": "исправлено вручную: гео",
        "manual_trash": "исправлено вручную: трэш",
        "manual_na": "исправлено вручную: NA",
        "new_contact": "новый контакт",
        "seen_before_same_manager": "уже писал этому менеджеру",
        "seen_before_other_manager": "уже писал другому менеджеру",
        "already_counted_today": "уже учтён сегодня",
        "baseline_old_chats": "старый чат из базы",
    }
    if low in mapping:
        return mapping[low]
    if country_name and bucket == "geo":
        return "гео: " + country_name
    if not raw:
        if bucket == "geo":
            return "гео"
        if bucket == "under18":
            return "нет 18 лет / 18+ не подтверждён"
        if bucket == "na":
            return "не ответил на город и воз��аст"
        if bucket == "trash":
            return "трэш"
        return "_"
    return raw


def _tp_report_v3_raw_bucket(lead: Dict[str, Any]) -> str:
    try:
        orig = globals().get("_TP_REPORT_V3_ORIG_TP_QS_ROW_BUCKET")
        if callable(orig):
            q = orig(lead)  # original quality engine function, before v3 override
            b = _tp_report_v3_text((q or {}).get("bucket"))
            if b:
                return b
    except Exception:
        pass
    b = _tp_report_v3_text((lead or {}).get("quality_bucket"))
    if b:
        return b
    status = _tp_report_v3_low((lead or {}).get("status"))
    reason = _tp_report_v3_low((lead or {}).get("quality_reason") or (lead or {}).get("nonliquid_reason"))
    country = _tp_report_v3_text((lead or {}).get("country"))
    city = _tp_report_v3_text((lead or {}).get("city"))
    age = _tp_report_v3_age((lead or {}).get("age"))
    if _tp_report_v3_int((lead or {}).get("trash")) == 1 or status == "trash" or "trash" in reason or "send_failed" in reason or "недоступ" in reason or "blocked" in reason:
        return "trash"
    if age is not None and age < 18:
        return "under18"
    if country and country != "Россия":
        return "geo"
    if country == "Россия" and age is not None and age >= 18:
        return "liquid"
    if age is None and (country or city):
        return "age_missing"
    if not country and not city:
        return "na"
    return "na"


def _tp_report_v3_bucket(lead: Dict[str, Any]) -> str:
    b = _tp_report_v3_raw_bucket(lead)
    # Final business rule: no separate NET 18 status. Age missing is paid-stat -18.
    if b == "age_missing":
        return "under18"
    if b == "geo_missing":
        return "na"
    if b in ("liquid", "geo", "under18", "trash", "na"):
        return b
    return "na"


def _tp_report_v3_lead_reason(lead: Dict[str, Any]) -> str:
    b_raw = _tp_report_v3_raw_bucket(lead)
    b = _tp_report_v3_bucket(lead)
    reason = _tp_report_v3_text((lead or {}).get("quality_reason") or (lead or {}).get("nonliquid_reason"))
    country = _tp_report_v3_text((lead or {}).get("country"))
    if b_raw == "age_missing":
        return "18+ не подтверждён"
    if b_raw == "geo_missing":
        return "гео не определено"
    return _tp_report_v3_reason_ru(reason, bucket=b, country=country)


def _tp_report_v3_empty_bucket(label: str = "") -> Dict[str, Any]:
    return {
        "label": label,
        "otpisok": 0,
        "total": 0,
        "new": 0,
        "duplicates": 0,
        "profile_done": 0,
        "nonliquid": 0,
        "geo": 0,
        "under18": 0,
        "na": 0,
        "trash": 0,
        "liquid": 0,
        "reasons": {},
    }


def _tp_qs_row_bucket(lead: Dict[str, Any]) -> Dict[str, Any]:  # type: ignore[override]
    orig = globals().get("_TP_REPORT_V3_ORIG_TP_QS_ROW_BUCKET")
    if callable(orig):
        try:
            q = orig(lead)
        except Exception:
            q = {}
    else:
        q = {}
    raw_bucket = _tp_report_v3_text((q or {}).get("bucket") or (lead or {}).get("quality_bucket") or "na")
    bucket = "under18" if raw_bucket == "age_missing" else ("na" if raw_bucket == "geo_missing" else raw_bucket)
    if bucket not in ("liquid", "geo", "under18", "trash", "na"):
        bucket = _tp_report_v3_bucket(lead)
    reason = _tp_report_v3_text((q or {}).get("reason") or (lead or {}).get("quality_reason") or (lead or {}).get("nonliquid_reason") or "")
    return {
        "status": "liquid" if bucket == "liquid" else ("trash" if bucket == "trash" else ("nonliquid" if bucket in ("geo", "under18") else "na")),
        "bucket": bucket,
        "reason": _tp_report_v3_reason_ru(reason, bucket=bucket, country=(lead or {}).get("country")),
        "confidence": _tp_report_v3_text((q or {}).get("confidence") or (lead or {}).get("quality_confidence") or ""),
    }


def _tp_report_v3_add_reason(b: Dict[str, Any], lead: Dict[str, Any]) -> None:
    reason = _tp_report_v3_lead_reason(lead)
    if reason and reason != "_":
        reasons = b.setdefault("reasons", {})
        reasons[reason] = int(reasons.get(reason, 0) or 0) + 1


def _tp_report_v3_bucket_add(b: Dict[str, Any], lead: Dict[str, Any]) -> None:
    b["otpisok"] = int(b.get("otpisok") or 0) + 1
    b["total"] = int(b.get("total") or 0) + 1
    if int((lead or {}).get("lead_countable", 1) or 0) == 1:
        b["new"] = int(b.get("new") or 0) + 1
    else:
        b["duplicates"] = int(b.get("duplicates") or 0) + 1
    if int((lead or {}).get("profile_done") or 0) == 1:
        b["profile_done"] = int(b.get("profile_done") or 0) + 1
    bucket = _tp_report_v3_bucket(lead)
    if bucket == "liquid":
        b["liquid"] = int(b.get("liquid") or 0) + 1
    elif bucket == "geo":
        b["geo"] = int(b.get("geo") or 0) + 1
    elif bucket == "under18":
        b["under18"] = int(b.get("under18") or 0) + 1
    elif bucket == "trash":
        b["trash"] = int(b.get("trash") or 0) + 1
    else:
        b["na"] = int(b.get("na") or 0) + 1
    b["nonliquid"] = int(b.get("geo") or 0) + int(b.get("under18") or 0) + int(b.get("na") or 0) + int(b.get("trash") or 0)
    b["otpisok"] = int(b.get("liquid") or 0) + int(b.get("nonliquid") or 0)
    _tp_report_v3_add_reason(b, lead)


def _tp_report_v3_bucket_lines(bucket: Dict[str, Any]) -> List[str]:
    return _format_det_bucket(bucket)


def _tp_report_v3_stats_from_leads(leads: List[Dict[str, Any]], manager_rows: List[Dict[str, Any]], target_key: str = "all") -> Dict[str, Any]:
    target_key = registry_normalize_manager_key(target_key or "all")
    buckets: Dict[str, Dict[str, Any]] = {}
    for mgr in manager_rows or []:
        key = registry_normalize_manager_key((mgr or {}).get("manager_key") or "")
        if not key:
            continue
        if target_key != "all" and key != target_key:
            continue
        b = _tp_report_v3_empty_bucket(_manager_label_from_row(mgr))
        b["key"] = key
        buckets[key] = b
    for lead in leads or []:
        key = registry_normalize_manager_key((lead or {}).get("manager_key") or "")
        if not key:
            continue
        if target_key != "all" and key != target_key:
            continue
        if key not in buckets:
            b = _tp_report_v3_empty_bucket(key)
            b["key"] = key
            buckets[key] = b
        _tp_report_v3_bucket_add(buckets[key], lead)
    total_bucket = _tp_report_v3_empty_bucket("ИТОГО")
    for b in buckets.values():
        for k in ("otpisok", "total", "new", "duplicates", "profile_done", "geo", "under18", "na", "trash", "liquid"):
            total_bucket[k] = int(total_bucket.get(k) or 0) + int(b.get(k) or 0)
        for reason, cnt in (b.get("reasons") or {}).items():
            total_bucket["reasons"][reason] = int(total_bucket["reasons"].get(reason, 0) or 0) + int(cnt or 0)
    total_bucket["nonliquid"] = int(total_bucket.get("geo") or 0) + int(total_bucket.get("under18") or 0) + int(total_bucket.get("na") or 0) + int(total_bucket.get("trash") or 0)
    total_bucket["otpisok"] = int(total_bucket.get("liquid") or 0) + int(total_bucket.get("nonliquid") or 0)
    return {"buckets": list(buckets.values()), **total_bucket}


async def _build_stat_text(target_key: str = "all", lead_date: Optional[str] = None) -> str:  # type: ignore[override]
    lead_date = lead_date or _kyiv_now().date().isoformat()
    target = registry_normalize_manager_key(target_key or "all")
    rows = await _manager_rows_for_reporting()
    leads = await _collect_day_leads(lead_date, target_key=target)
    stats = _tp_report_v3_stats_from_leads(leads, rows, target_key=target)
    date_disp = datetime.strptime(lead_date, "%Y-%m-%d").strftime("%d.%m.%y")
    lines: List[str] = [f"📊 Статистика за {date_disp}", ""]
    if not stats.get("buckets"):
        lines.append("Менеджеры не найдены.")
        return chr(10).join(lines).rstrip()
    for b in stats["buckets"]:
        if target == "all" and int(b.get("otpisok") or 0) == 0:
            continue
        lines.append(str(b.get("label") or b.get("key") or "_"))
        lines.extend(_tp_report_v3_bucket_lines(b))
        lines.append("")
    if target == "all":
        lines.append("ИТОГО")
        lines.extend(_tp_report_v3_bucket_lines(stats))
    return chr(10).join(lines).rstrip()


async def _build_stat_period_text(spec: Dict[str, Any]) -> str:  # type: ignore[override]
    scope = str((spec or {}).get("scope") or "all")
    key = str((spec or {}).get("key") or "all")
    start_iso = str((spec or {}).get("start") or "")
    end_iso = str((spec or {}).get("end") or "")
    label = str((spec or {}).get("label") or f"{start_iso} - {end_iso}")
    leads, rows, scope_label = await _collect_period_leads(scope, key, start_iso, end_iso)
    stats = _tp_report_v3_stats_from_leads(leads, rows, target_key="all")
    lines: List[str] = [f"📊 Статистика за период {label}", scope_label, ""]
    for b in stats["buckets"]:
        if int(b.get("otpisok") or 0) == 0:
            continue
        lines.append(str(b.get("label") or b.get("key") or "_"))
        lines.extend(_tp_report_v3_bucket_lines(b))
        lines.append("")
    lines.append("ИТОГО")
    lines.extend(_tp_report_v3_bucket_lines(stats))
    return chr(10).join(lines).rstrip()


async def _build_det_stat_text(target_key: str = "all", kind: str = "day", ref: Optional[Any] = None) -> str:  # type: ignore[override]
    date_val = None
    if isinstance(ref, str):
        date_val = _tp_parse_date_token(ref)
    elif hasattr(ref, "date"):
        try:
            date_val = ref.astimezone(TZ_KYIV).date() if getattr(ref, "tzinfo", None) else ref.date()
        except Exception:
            date_val = None
    if date_val and not _tp_date_within_history(date_val):
        return f"Дата вне доступного периода. Можно смотреть последние {HISTORY_DAYS_LIMIT} дней."
    start_local, end_local, label, title = _window_for_kind_date(kind, date_val)
    target_date = start_local.date()
    target = registry_normalize_manager_key(target_key or "all")
    rows = await _manager_rows_for_reporting()
    valid_keys = {registry_normalize_manager_key((r or {}).get("manager_key") or "") for r in rows}
    if target != "all" and target not in valid_keys:
        return f"Менеджер не найден: {target}"
    leads = await _collect_window_leads_extended(start_local, end_local, target, kind, target_date)
    mgr_labels = {registry_normalize_manager_key((r or {}).get("manager_key") or ""): _manager_label_from_row(r) for r in rows}
    buckets: Dict[str, Dict[str, Any]] = {}
    for lead in leads or []:
        key = registry_normalize_manager_key((lead or {}).get("manager_key") or "")
        if not key:
            continue
        if key not in buckets:
            buckets[key] = _tp_report_v3_empty_bucket(mgr_labels.get(key) or key)
        _tp_report_v3_bucket_add(buckets[key], lead)
    window_line = "Окно: 17:00-08:00" if str(kind).lower() == "flight" else "Окно: 08:00-17:00"
    lines: List[str] = [f"{title} за {label}", window_line, ""]
    keys_order = [registry_normalize_manager_key((r or {}).get("manager_key") or "") for r in rows]
    if target != "all":
        keys_order = [target]
    total_bucket = _tp_report_v3_empty_bucket("ИТОГО")
    any_block = False
    for key in keys_order:
        if not key:
            continue
        b = buckets.get(key) or _tp_report_v3_empty_bucket(mgr_labels.get(key) or key)
        if target == "all" and int(b.get("otpisok") or 0) == 0:
            continue
        any_block = True
        lines.append(str(b.get("label") or key))
        lines.extend(_tp_report_v3_bucket_lines(b))
        lines.append("")
        for k in ("otpisok", "total", "new", "duplicates", "profile_done", "geo", "under18", "na", "trash", "liquid"):
            total_bucket[k] = int(total_bucket.get(k) or 0) + int(b.get(k) or 0)
    total_bucket["nonliquid"] = int(total_bucket.get("geo") or 0) + int(total_bucket.get("under18") or 0) + int(total_bucket.get("na") or 0) + int(total_bucket.get("trash") or 0)
    total_bucket["otpisok"] = int(total_bucket.get("liquid") or 0) + int(total_bucket.get("nonliquid") or 0)
    if target == "all":
        if any_block:
            lines.append("ИТОГО")
            lines.extend(_tp_report_v3_bucket_lines(total_bucket))
        else:
            lines.append("Лидов за это окно пока нет.")
    elif not any_block:
        lines.append(str(mgr_labels.get(target) or target))
        lines.extend(_tp_report_v3_bucket_lines(_tp_report_v3_empty_bucket(mgr_labels.get(target) or target)))
    return chr(10).join(lines).rstrip()
