def _tpe_int(raw: Any, default: int = 0) -> int:
    try:
        if raw is None or str(raw).strip() == "":
            return int(default)
        return int(raw)
    except Exception:
        return int(default)


def _tpe_text(raw: Any) -> str:
    return str(raw or "").strip()


def _tpe_bool(raw: Any) -> bool:
    return str(raw).strip().lower() in ("1", "true", "yes", "да", "on")


async def _tpe_ensure_profile_schema(db_path: str) -> None:
    if not db_path:
        return
    await _ensure_daily_leads_table(db_path)
    async with aiosqlite.connect(str(db_path)) as db:
        try:
            await db.execute("PRAGMA journal_mode=WAL;")
            await db.execute("PRAGMA busy_timeout=30000;")
        except Exception:
            pass
        cols = await _table_columns(db, "daily_leads")
        migrations = [
            ("profile_extraction_version", "ALTER TABLE daily_leads ADD COLUMN profile_extraction_version TEXT NOT NULL DEFAULT ''"),
            ("profile_evidence_text", "ALTER TABLE daily_leads ADD COLUMN profile_evidence_text TEXT NOT NULL DEFAULT ''"),
            ("age_evidence_text", "ALTER TABLE daily_leads ADD COLUMN age_evidence_text TEXT NOT NULL DEFAULT ''"),
            ("geo_evidence_text", "ALTER TABLE daily_leads ADD COLUMN geo_evidence_text TEXT NOT NULL DEFAULT ''"),
            ("age_confirmed_18_plus", "ALTER TABLE daily_leads ADD COLUMN age_confirmed_18_plus INTEGER NOT NULL DEFAULT 0"),
            ("extraction_confidence", "ALTER TABLE daily_leads ADD COLUMN extraction_confidence TEXT NOT NULL DEFAULT ''"),
            ("extraction_method", "ALTER TABLE daily_leads ADD COLUMN extraction_method TEXT NOT NULL DEFAULT ''"),
            ("needs_review", "ALTER TABLE daily_leads ADD COLUMN needs_review INTEGER NOT NULL DEFAULT 0"),
            ("profile_decision_reason", "ALTER TABLE daily_leads ADD COLUMN profile_decision_reason TEXT NOT NULL DEFAULT ''"),
            ("negative_age_marker", "ALTER TABLE daily_leads ADD COLUMN negative_age_marker TEXT NOT NULL DEFAULT ''"),
            ("geo_conflict", "ALTER TABLE daily_leads ADD COLUMN geo_conflict INTEGER NOT NULL DEFAULT 0"),
        ]
        for col, ddl in migrations:
            if col not in cols:
                try:
                    await db.execute(ddl)
                except Exception:
                    pass
        await db.execute("""
            CREATE TABLE IF NOT EXISTS profile_extraction_audit(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                manager_key TEXT NOT NULL DEFAULT '',
                chat_id INTEGER NOT NULL DEFAULT 0,
                lead_date TEXT NOT NULL DEFAULT '',
                raw_messages TEXT NOT NULL DEFAULT '',
                old_age TEXT NOT NULL DEFAULT '',
                new_age TEXT NOT NULL DEFAULT '',
                old_city TEXT NOT NULL DEFAULT '',
                new_city TEXT NOT NULL DEFAULT '',
                old_country TEXT NOT NULL DEFAULT '',
                new_country TEXT NOT NULL DEFAULT '',
                old_quality_bucket TEXT NOT NULL DEFAULT '',
                new_quality_bucket TEXT NOT NULL DEFAULT '',
                method TEXT NOT NULL DEFAULT '',
                confidence TEXT NOT NULL DEFAULT '',
                reason TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL DEFAULT ''
            );
        """)
        await db.execute("CREATE INDEX IF NOT EXISTS profile_extraction_audit_chat_idx ON profile_extraction_audit(chat_id, id);")
        await db.execute("CREATE INDEX IF NOT EXISTS profile_extraction_audit_date_idx ON profile_extraction_audit(lead_date, manager_key);")
        await db.commit()


