# --- TPILOT PROFILE STATUS SYNC V1 20260512 START ---
# Synchronizes final lead status from already saved profile facts.
# Fixes cases where daily_leads has country=Russia and age>=18, but status is still unknown/pending.
import sqlite3 as _tp_pss_sqlite3
from datetime import datetime as _tp_pss_datetime, time as _tp_pss_time, timedelta as _tp_pss_timedelta

_TP_PSS_VERSION = "profile_status_sync_v1_20260512"
_TP_PSS_ORIG_UPDATE_DAILY_LEAD_FIELDS = globals().get("_update_daily_lead_fields")
_TP_PSS_ORIG_TPE_DIRECT_UPDATE_DAILY = globals().get("_tpe_direct_update_daily")
_TP_PSS_ORIG_TP_QS_HANDLE_LEAD_COMMAND = globals().get("_tp_qs_handle_lead_command")
_TP_PSS_ORIG_HANDLE_AI_STAT_COMMAND = globals().get("_handle_ai_stat_command")
_TP_PSS_ORIG_PANEL_EXEC = globals().get("_panel_execute_command_text")
_TP_PSS_RECALC_GUARD = False


def _tp_pss_now_iso():
    try:
        return _now_utc_iso()
    except Exception:
        return _tp_utc_now().replace(microsecond=0).isoformat()


def _tp_pss_text(v):
    return str(v or "").strip()


def _tp_pss_low(v):
    return _tp_pss_text(v).lower().replace("ё", "е")


def _tp_pss_norm_key(v):
    try:
        return registry_normalize_manager_key(v)
    except Exception:
        return re.sub(r"[^a-z0-9_-]+", "", _tp_pss_low(v))


def _tp_pss_int_or_none(v):
    # --- TPILOT AGE0 FIX M2.6I START ---
    # age=0 is a technical placeholder for "unknown", never a real age — normalize to None.
    try:
        if v is None:
            return None
        s = str(v).strip()
        if not s:
            return None
        r = int(float(s))
        return r if r != 0 else None
    except Exception:
        return None
    # --- TPILOT AGE0 FIX M2.6I END ---


def _tp_pss_is_russia(country):
    c = _tp_pss_low(country)
    return c in {"россия", "рф", "российская федерация", "russia", "ru"}


def _tp_pss_safe_label(v):
    s = _tp_pss_text(v)
    return s if s else "_"


def _tp_pss_parse_date_token(token):
    token = _tp_pss_low(token)
    try:
        now = _kyiv_now().date() if callable(globals().get("_kyiv_now")) else _tp_pss_datetime.now().date()
    except Exception:
        now = _tp_pss_datetime.now().date()
    if not token or token in {"today", "сегодня"}:
        return now
    if token in {"yesterday", "вчера"}:
        return now - _tp_pss_timedelta(days=1)
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d.%m.%y"):
        try:
            return _tp_pss_datetime.strptime(token, fmt).date()
        except Exception:
            pass
    m = re.fullmatch(r"(\d{1,2})\.(\d{1,2})", token)
    if m:
        return _tp_pss_datetime(now.year, int(m.group(2)), int(m.group(1))).date()
    raise ValueError("bad_date")


def _tp_pss_window_label(first_seen_kyiv):
    try:
        t = _tp_pss_datetime.strptime(str(first_seen_kyiv or "")[:19], "%Y-%m-%d %H:%M:%S").time()
        if _tp_pss_time(8, 0) <= t < _tp_pss_time(17, 0):
            return "day"
        return "flight"
    except Exception:
        return "unknown"


def _tp_pss_connect(path):
    con = _tp_pss_sqlite3.connect(str(path), timeout=30)
    con.row_factory = _tp_pss_sqlite3.Row
    try:
        con.execute("PRAGMA journal_mode=WAL;")
        con.execute("PRAGMA busy_timeout=30000;")
    except Exception:
        pass
    return con


def _tp_pss_cols(con, table):
    try:
        return {str(r[1]) for r in con.execute(f"PRAGMA table_info({table})").fetchall()}
    except Exception:
        return set()


def _tp_pss_ensure_status_schema_sync(db_path):
    if not db_path:
        return
    con = _tp_pss_connect(db_path)
    try:
        con.execute("""
            CREATE TABLE IF NOT EXISTS daily_leads(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                lead_date TEXT NOT NULL,
                manager_key TEXT NOT NULL DEFAULT '',
                chat_id INTEGER NOT NULL,
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT '',
                UNIQUE(lead_date, manager_key, chat_id)
            );
        """)
        cols = _tp_pss_cols(con, "daily_leads")
        migrations = [
            ("status", "ALTER TABLE daily_leads ADD COLUMN status TEXT DEFAULT ''"),
            ("nonliquid_reason", "ALTER TABLE daily_leads ADD COLUMN nonliquid_reason TEXT DEFAULT ''"),
            ("profile_done", "ALTER TABLE daily_leads ADD COLUMN profile_done INTEGER NOT NULL DEFAULT 0"),
            ("quality_status", "ALTER TABLE daily_leads ADD COLUMN quality_status TEXT NOT NULL DEFAULT ''"),
            ("quality_bucket", "ALTER TABLE daily_leads ADD COLUMN quality_bucket TEXT NOT NULL DEFAULT ''"),
            ("quality_reason", "ALTER TABLE daily_leads ADD COLUMN quality_reason TEXT NOT NULL DEFAULT ''"),
            ("quality_confidence", "ALTER TABLE daily_leads ADD COLUMN quality_confidence TEXT NOT NULL DEFAULT ''"),
            ("quality_source", "ALTER TABLE daily_leads ADD COLUMN quality_source TEXT NOT NULL DEFAULT ''"),
            ("quality_checked_at", "ALTER TABLE daily_leads ADD COLUMN quality_checked_at TEXT NOT NULL DEFAULT ''"),
            ("quality_version", "ALTER TABLE daily_leads ADD COLUMN quality_version TEXT NOT NULL DEFAULT ''"),
            ("manual_status_override", "ALTER TABLE daily_leads ADD COLUMN manual_status_override INTEGER NOT NULL DEFAULT 0"),
            ("trash", "ALTER TABLE daily_leads ADD COLUMN trash INTEGER NOT NULL DEFAULT 0"),
            ("trash_reason", "ALTER TABLE daily_leads ADD COLUMN trash_reason TEXT NOT NULL DEFAULT ''"),
            ("age_confirmed_18_plus", "ALTER TABLE daily_leads ADD COLUMN age_confirmed_18_plus INTEGER NOT NULL DEFAULT 0"),
            ("profile_decision_reason", "ALTER TABLE daily_leads ADD COLUMN profile_decision_reason TEXT NOT NULL DEFAULT ''"),
            ("profile_extraction_version", "ALTER TABLE daily_leads ADD COLUMN profile_extraction_version TEXT NOT NULL DEFAULT ''"),
        ]
        for col, ddl in migrations:
            if col not in cols:
                try:
                    con.execute(ddl)
                except Exception:
                    pass
        con.execute("CREATE INDEX IF NOT EXISTS daily_leads_profile_status_sync_idx ON daily_leads(lead_date, quality_bucket, status, manager_key);")
        con.execute("""
            CREATE TABLE IF NOT EXISTS profile_status_sync_audit(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                manager_key TEXT NOT NULL DEFAULT '',
                chat_id INTEGER NOT NULL DEFAULT 0,
                lead_date TEXT NOT NULL DEFAULT '',
                old_status TEXT NOT NULL DEFAULT '',
                new_status TEXT NOT NULL DEFAULT '',
                old_bucket TEXT NOT NULL DEFAULT '',
                new_bucket TEXT NOT NULL DEFAULT '',
                old_reason TEXT NOT NULL DEFAULT '',
                new_reason TEXT NOT NULL DEFAULT '',
                source TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL DEFAULT ''
            );
        """)
        con.execute("CREATE INDEX IF NOT EXISTS profile_status_sync_audit_date_idx ON profile_status_sync_audit(lead_date, manager_key);")
        con.commit()
    finally:
        con.close()


def _tp_pss_decide_from_facts(row, source="status_sync"):
    if not row:
        return None
    if int(row.get("manual_status_override") or 0) == 1:
        return None
    if not _autostatus_enabled_sync():
        return None
    now = _tp_pss_now_iso()
    age = _tp_pss_int_or_none(row.get("age"))
    country = _tp_pss_text(row.get("country"))
    country_low = _tp_pss_low(country)
    status_low = _tp_pss_low(row.get("status"))
    reason_low = _tp_pss_low(row.get("nonliquid_reason"))
    trash_reason = _tp_pss_text(row.get("trash_reason") or row.get("nonliquid_reason"))

    if int(row.get("trash") or 0) == 1 or status_low == "trash" or "trash" in reason_low:
        return {
            "status": "trash", "bucket": "trash", "reason": trash_reason or "trash",
            "legacy_status": "trash", "legacy_reason": trash_reason or "trash",
            "confidence": "high", "source": source, "checked_at": now, "profile_done": 1,
            "age_confirmed_18_plus": 1 if (age is not None and age >= 18) else 0,
        }

    if age is not None and age < 18:
        return {
            "status": "nonliquid", "bucket": "under18", "reason": "under18",
            "legacy_status": "nonliquid", "legacy_reason": "-18",
            "confidence": "high", "source": source, "checked_at": now, "profile_done": 1,
            "age_confirmed_18_plus": 0,
        }

    if country and not _tp_pss_is_russia(country):
        safe_country = re.sub(r"\s+", "_", country_low)
        return {
            "status": "nonliquid", "bucket": "geo", "reason": "country_" + safe_country,
            "legacy_status": "nonliquid", "legacy_reason": country,
            "confidence": "high", "source": source, "checked_at": now, "profile_done": 1,
            "age_confirmed_18_plus": 1 if (age is not None and age >= 18) else 0,
        }

    if country and _tp_pss_is_russia(country) and age is not None and age >= 18:
        city = _tp_pss_text(row.get("city"))
        region = _tp_pss_text(row.get("region"))
        return {
            "status": "liquid", "bucket": "liquid", "reason": "ru_18_plus" if (city or region) else "ru_18_plus_city_unknown",
            "legacy_status": "liquid", "legacy_reason": "",
            "confidence": "high", "source": source, "checked_at": now, "profile_done": 1,
            "age_confirmed_18_plus": 1,
        }

    return None


def _tp_pss_desired_fields(row, source="status_sync"):
    dec = _tp_pss_decide_from_facts(row, source=source)
    if not dec:
        return None
    fields = {
        "quality_status": dec["status"],
        "quality_bucket": dec["bucket"],
        "quality_reason": dec["reason"],
        "quality_confidence": dec["confidence"],
        "quality_source": dec["source"],
        "quality_checked_at": dec["checked_at"],
        "quality_version": _TP_PSS_VERSION,
        "status": dec["legacy_status"],
        "nonliquid_reason": dec["legacy_reason"],
        "profile_done": int(dec.get("profile_done") or 1),
        "updated_at": dec["checked_at"],
        "age_confirmed_18_plus": int(dec.get("age_confirmed_18_plus") or 0),
        "profile_decision_reason": dec["reason"],
        "profile_extraction_version": _TP_PSS_VERSION,
    }
    return fields


def _tp_pss_needs_update(row, fields):
    if not row or not fields:
        return False
    checks = ["quality_status", "quality_bucket", "quality_reason", "status", "nonliquid_reason", "profile_done"]
    for k in checks:
        old = row.get(k)
        new = fields.get(k)
        if k == "profile_done":
            try:
                if int(old or 0) != int(new or 0):
                    return True
            except Exception:
                return True
        else:
            if _tp_pss_text(old) != _tp_pss_text(new):
                return True
    return False


def _tp_pss_apply_row_sync(db_path, row, source="status_sync_apply"):
    _tp_pss_ensure_status_schema_sync(db_path)
    fields = _tp_pss_desired_fields(row, source=source)
    if not fields or not _tp_pss_needs_update(row, fields):
        return False, fields or {}
    con = _tp_pss_connect(db_path)
    try:
        cols = _tp_pss_cols(con, "daily_leads")
        data = {k: v for k, v in fields.items() if k in cols}
        if not data:
            return False, fields
        old_status = _tp_pss_text(row.get("quality_status") or row.get("status"))
        old_bucket = _tp_pss_text(row.get("quality_bucket"))
        old_reason = _tp_pss_text(row.get("quality_reason") or row.get("nonliquid_reason"))
        keys = list(data.keys())
        vals = [data[k] for k in keys]
        vals.append(int(row.get("id") or 0))
        con.execute("UPDATE daily_leads SET " + ", ".join([f"{k}=?" for k in keys]) + " WHERE id=?", tuple(vals))
        con.execute(
            """
            INSERT INTO profile_status_sync_audit(
                manager_key, chat_id, lead_date, old_status, new_status,
                old_bucket, new_bucket, old_reason, new_reason, source, created_at
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                _tp_pss_norm_key(row.get("manager_key")),
                int(row.get("chat_id") or 0),
                _tp_pss_text(row.get("lead_date")),
                old_status,
                fields.get("quality_status") or fields.get("status") or "",
                old_bucket,
                fields.get("quality_bucket") or "",
                old_reason,
                fields.get("quality_reason") or fields.get("nonliquid_reason") or "",
                source,
                _tp_pss_now_iso(),
            ),
        )
        con.commit()
        return True, fields
    finally:
        con.close()


async def _tp_pss_sync_one(db_path, lead_date, manager_key, chat_id, source="auto_status_sync"):
    if not db_path or not lead_date or not chat_id:
        return False
    try:
        _tp_pss_ensure_status_schema_sync(db_path)
        con = _tp_pss_connect(db_path)
        try:
            row = con.execute(
                "SELECT * FROM daily_leads WHERE lead_date=? AND manager_key=? AND chat_id=? LIMIT 1",
                (str(lead_date), _tp_pss_norm_key(manager_key), int(chat_id)),
            ).fetchone()
            row = dict(row) if row else {}
        finally:
            con.close()
        if not row:
            return False
        changed, _fields = _tp_pss_apply_row_sync(db_path, row, source=source)
        return bool(changed)
    except Exception as e:
        try:
            print(f"profile status sync one error: {e!r}")
        except Exception:
            pass
        return False


async def _update_daily_lead_fields(db_path: str, *, lead_date: str, manager_key: str, chat_id: int, **fields):  # type: ignore[override]
    global _TP_PSS_RECALC_GUARD
    if callable(_TP_PSS_ORIG_UPDATE_DAILY_LEAD_FIELDS):
        await _TP_PSS_ORIG_UPDATE_DAILY_LEAD_FIELDS(db_path, lead_date=lead_date, manager_key=manager_key, chat_id=chat_id, **fields)
    if _TP_PSS_RECALC_GUARD:
        return
    relevant = {
        "age", "city", "region", "country", "status", "nonliquid_reason",
        "quality_status", "quality_bucket", "quality_reason", "profile_raw_text", "trash", "trash_reason",
    }
    if not (set(dict(fields or {}).keys()) & relevant):
        return
    try:
        _TP_PSS_RECALC_GUARD = True
        await _tp_pss_sync_one(db_path, lead_date, manager_key, chat_id, source="auto_after_update")
    finally:
        _TP_PSS_RECALC_GUARD = False


if callable(_TP_PSS_ORIG_TPE_DIRECT_UPDATE_DAILY):
    async def _tpe_direct_update_daily(db_path: str, *, lead_date: str, manager_key: str, chat_id: int, **fields):  # type: ignore[override]
        global _TP_PSS_RECALC_GUARD
        await _TP_PSS_ORIG_TPE_DIRECT_UPDATE_DAILY(db_path, lead_date=lead_date, manager_key=manager_key, chat_id=chat_id, **fields)
        if _TP_PSS_RECALC_GUARD:
            return
        relevant = {
            "age", "city", "region", "country", "status", "nonliquid_reason",
            "quality_status", "quality_bucket", "quality_reason", "profile_raw_text", "trash", "trash_reason",
        }
        if not (set(dict(fields or {}).keys()) & relevant):
            return
        try:
            _TP_PSS_RECALC_GUARD = True
            await _tp_pss_sync_one(db_path, lead_date, manager_key, chat_id, source="auto_after_profile_direct_update")
        finally:
            _TP_PSS_RECALC_GUARD = False


async def _tp_pss_manager_rows():
    rows = []
    fn = globals().get("_manager_rows_for_reporting")
    if callable(fn):
        try:
            rows = await fn()
        except Exception:
            rows = []
    if rows:
        return rows
    try:
        base = Path(str(BASE_DIR)) / "runtime" / "managers"
    except Exception:
        base = Path("runtime") / "managers"
    out = []
    try:
        for p in sorted(base.glob("*/*.db")):
            out.append({"manager_key": p.parent.name, "db_path": str(p)})
    except Exception:
        pass
    return out


async def _tp_pss_collect_changes(date_iso, target="all"):
    target_key = _tp_pss_norm_key(target or "all")
    managers = await _tp_pss_manager_rows()
    changes = []
    checked = 0
    for mgr in managers:
        mk = _tp_pss_norm_key(mgr.get("manager_key") or mgr.get("key") or "")
        if target_key not in {"", "all"} and mk != target_key:
            continue
        dbp = _tp_pss_text(mgr.get("db_path"))
        if not dbp or not os.path.exists(dbp):
            continue
        try:
            _tp_pss_ensure_status_schema_sync(dbp)
            con = _tp_pss_connect(dbp)
            try:
                rows = [dict(r) for r in con.execute("SELECT * FROM daily_leads WHERE lead_date=? ORDER BY first_seen_kyiv, id", (str(date_iso),)).fetchall()]
            finally:
                con.close()
            for row in rows:
                checked += 1
                row["_db_path"] = dbp
                row["_manager_key"] = mk or _tp_pss_norm_key(row.get("manager_key"))
                fields = _tp_pss_desired_fields(row, source="status_sync_scan")
                if fields and _tp_pss_needs_update(row, fields):
                    changes.append((row, fields))
        except Exception as e:
            try:
                print(f"profile status sync collect error manager={mk}: {e!r}")
            except Exception:
                pass
    return checked, changes


def _tp_pss_summarize_changes(changes):
    by_window = {"day": 0, "flight": 0, "unknown": 0}
    by_manager = {}
    by_status = {}
    for row, fields in changes:
        win = _tp_pss_window_label(row.get("first_seen_kyiv"))
        by_window[win] = by_window.get(win, 0) + 1
        mk = _tp_pss_norm_key(row.get("manager_key") or row.get("_manager_key"))
        by_manager[mk] = by_manager.get(mk, 0) + 1
        old = _tp_pss_text(row.get("quality_bucket") or row.get("status") or "_")
        new = _tp_pss_text(fields.get("quality_bucket") or fields.get("status") or "_")
        key = f"{old} → {new}"
        by_status[key] = by_status.get(key, 0) + 1
    return by_window, by_manager, by_status


async def _tp_pss_status_sync_command(args, *, user_id=0):
    await _autostatus_runtime_enabled()  # warm the sync-context gate snapshot before any decide_from_facts call below
    parts = [p for p in str(args or "").split() if p.strip()]
    if parts and parts[0].lower() in {"status_sync", "status-sync", "sync_status", "sync-status", "статусы", "синхронизация"}:
        parts = parts[1:]
    if not parts or parts[0].lower() in {"help", "?"}:
        return "\n".join([
            "🧾 Синхронизация статусов профиля",
            "Формат:",
            "/lead status_sync сегодня dry",
            "/lead status_sync вчера dry",
            "/lead status_sync 11.05 dry",
            "/lead status_sync 11.05 apply",
            "",
            "Исправляет только уверенные факты: Россия + 18, -18, не Россия, trash.",
        ]).rstrip()
    date_token = parts[0]
    mode = "dry"
    target = "all"
    for p in parts[1:]:
        pl = p.lower()
        if pl in {"dry", "apply"}:
            mode = pl
        else:
            target = p
    if mode not in {"dry", "apply"}:
        mode = "dry"
    try:
        date_obj = _tp_pss_parse_date_token(date_token)
    except Exception:
        return "Формат даты: сегодня, вчера, 11.05, 11.05.26 или 2026-05-11"
    date_iso = date_obj.isoformat()
    checked, changes = await _tp_pss_collect_changes(date_iso, target=target)
    by_window, by_manager, by_status = _tp_pss_summarize_changes(changes)

    applied = 0
    if mode == "apply":
        for row, fields in changes:
            try:
                ok, _ = _tp_pss_apply_row_sync(str(row.get("_db_path") or ""), row, source="status_sync_apply")
                if ok:
                    applied += 1
            except Exception as e:
                try:
                    print(f"profile status sync apply row error: {e!r}")
                except Exception:
                    pass

    title = "✅ Синхронизация применена" if mode == "apply" else "🧪 Проверка синхронизации статусов"
    lines = [
        title,
        f"Версия: {_TP_PSS_VERSION}",
        f"Дата: {date_obj.strftime('%d.%m.%y')}",
        f"Цель: {target}",
        f"Проверено лидов: {checked}",
        f"Будет исправлено: {len(changes)}" if mode == "dry" else f"Исправлено: {applied}",
        "",
        "По окнам:",
        f"• День 08:00-17:00: {int(by_window.get('day') or 0)}",
        f"• Долёты 17:00-08:00: {int(by_window.get('flight') or 0)}",
    ]
    if by_window.get("unknown"):
        lines.append(f"• Без времени: {int(by_window.get('unknown') or 0)}")
    if by_status:
        lines.extend(["", "По изменениям:"])
        for k, v in sorted(by_status.items(), key=lambda x: (-x[1], x[0]))[:20]:
            lines.append(f"• {k}: {v}")
    if by_manager:
        lines.extend(["", "По менеджерам:"])
        for k, v in sorted(by_manager.items(), key=lambda x: (-x[1], x[0]))[:30]:
            lines.append(f"• {k}: {v}")
    if changes:
        lines.extend(["", "Первые изменения:"])
        for row, fields in changes[:15]:
            lines.append(
                f"• {row.get('manager_key') or row.get('_manager_key')} | {row.get('first_seen_kyiv') or row.get('lead_date')} | {row.get('chat_id')}: "
                f"{_tp_pss_safe_label(row.get('quality_bucket') or row.get('status'))} → {_tp_pss_safe_label(fields.get('quality_bucket'))}"
            )
    if mode == "dry":
        lines.extend(["", f"Для применения: /lead status_sync {date_obj.strftime('%d.%m.%y')} apply"])
    return "\n".join(lines).rstrip()


async def _tp_qs_handle_lead_command(args: str, *, user_id: int = 0) -> str:  # type: ignore[override]
    first = (str(args or "").split()[:1] or [""])[0].lower()
    if first in {"status_sync", "status-sync", "sync_status", "sync-status", "статусы", "синхронизация"}:
        return await _tp_pss_status_sync_command(args, user_id=user_id)
    if callable(_TP_PSS_ORIG_TP_QS_HANDLE_LEAD_COMMAND):
        return await _TP_PSS_ORIG_TP_QS_HANDLE_LEAD_COMMAND(args, user_id=user_id)
    return await _tp_pss_status_sync_command("help", user_id=user_id)


async def _handle_ai_stat_command(event):  # type: ignore[override]
    try:
        if CONTROLLER_MODE and int(event.chat_id or 0) == int(AI_STAT_CHAT_ID or 0):
            cmd, args = _parse_cmd((event.raw_text or "").strip())
            if cmd == "/lead":
                first = (str(args or "").split()[:1] or [""])[0].lower()
                if first in {"status_sync", "status-sync", "sync_status", "sync-status", "статусы", "синхронизация"}:
                    await client.send_message(event.chat_id, await _tp_pss_status_sync_command(args, user_id=int(event.sender_id or 0)))
                    return True
    except Exception as e:
        try:
            await client.send_message(event.chat_id, f"Ошибка синхронизации статусов: {e!r}")
            return True
        except Exception:
            pass
    if callable(_TP_PSS_ORIG_HANDLE_AI_STAT_COMMAND):
        return await _TP_PSS_ORIG_HANDLE_AI_STAT_COMMAND(event)
    return False


async def _panel_execute_command_text(command_text: str, *, requested_by: int = 0, source_chat_id: int = 0, response_chat_id: int = 0):  # type: ignore[override]
    text = str(command_text or "").strip()
    cmd, args = _parse_cmd(text)
    if cmd == "/lead":
        first = (str(args or "").split()[:1] or [""])[0].lower()
        if first in {"status_sync", "status-sync", "sync_status", "sync-status", "статусы", "синхронизация"}:
            return {"ok": True, "result_text": await _tp_pss_status_sync_command(args, user_id=requested_by)}
    if callable(_TP_PSS_ORIG_PANEL_EXEC):
        try:
            return await _TP_PSS_ORIG_PANEL_EXEC(command_text, requested_by=requested_by, source_chat_id=source_chat_id, response_chat_id=response_chat_id)
        except TypeError:
            try:
                return await _TP_PSS_ORIG_PANEL_EXEC(command_text, requested_by=requested_by)
            except TypeError:
                return await _TP_PSS_ORIG_PANEL_EXEC(command_text)
    return {"ok": False, "error_text": f"Команда не поддерживается: {cmd or text}"}

# --- TPILOT PROFILE STATUS SYNC V1 20260512 END ---

# --- TPILOT GREETING QUESTIONNAIRE SCHEDULE V1 20260513 START ---
# Разделяет клиентские сообщения на:
# 1) 👋 Приветствие / нет на месте
# 2) 📋 Автоанкету
# 3) passive parsing профиля, который работает даже когда клиентские авто-сообщения выключены.

_TP_GQ_VERSION = "tpilot_greeting_questionnaire_schedule_v1_20260513"
_TP_GQ_ORIG_MAYBE_AUTO_REPLY = globals().get("_maybe_auto_reply_to_lead")
_TP_GQ_ORIG_APPLY_PROFILE_FROM_TEXT = globals().get("_apply_profile_from_text")
_TP_GQ_ORIG_PANEL_EXEC = globals().get("_panel_execute_command_text")
_TP_GQ_ORIG_HANDLE_AI_STAT = globals().get("_handle_ai_stat_command")
_TP_GQ_ORIG_CONTENT_TEXT_DEFAULTS = globals().get("_content_text_defaults")

TP_GQ_DEFAULT_DAY_START = "08:00"
TP_GQ_DEFAULT_DAY_END = "17:00"
TP_GQ_DEFAULT_NIGHT_START = "17:00"
TP_GQ_DEFAULT_NIGHT_END = "08:00"
TP_GQ_OLD_CLIENT_AUTORESPONDER_KEY = "old_client_night_autoresponder"
TP_GQ_OLD_CLIENT_AUTORESPONDER_DEFAULT = "[Автоответчик]\nЯ сейчас не на рабочем месте, напишите что вас интересует, как только вернусь сразу Вам отвечу 🙂 Спасибо!"

try:
    _CONTENT_TEXT_LABELS["profile_question"] = "Дневное приветствие для новых"
    _CONTENT_TEXT_LABELS["offline_notice"] = "Ночное сообщение для новых"
    _CONTENT_TEXT_LABELS[TP_GQ_OLD_CLIENT_AUTORESPONDER_KEY] = "Автоответчик старым ночью"
except Exception:
    pass


def _content_text_defaults() -> dict:  # type: ignore[override]
    base = {}
    try:
        if callable(_TP_GQ_ORIG_CONTENT_TEXT_DEFAULTS):
            base = dict(_TP_GQ_ORIG_CONTENT_TEXT_DEFAULTS() or {})
    except Exception:
        base = {}
    if not base:
        base = {
            "profile_question": str(globals().get("PROFILE_QUESTION_TEXT") or "Здравствуйте! Подскажите, пожалуйста, из какого вы города и ваш возраст. Эта информация нужна для работы."),
            "offline_notice": str(globals().get("OFFLINE_NOTICE_TEXT") or "Здравствуйте, сейчас нерабочее время, с радостью ответим вам на все вопросы в рабочее время!"),
        }
    base.setdefault(TP_GQ_OLD_CLIENT_AUTORESPONDER_KEY, TP_GQ_OLD_CLIENT_AUTORESPONDER_DEFAULT)
    return base


def _tp_gq_now_iso() -> str:
    return _tp_utc_now().replace(microsecond=0).isoformat()


def _tp_gq_norm_key(raw: Any) -> str:
    return registry_normalize_manager_key(str(raw or ""))


def _tp_gq_parse_time(raw: Any) -> Optional[int]:
    s = str(raw or "").strip()
    m = re.fullmatch(r"(\d{1,2})(?::|\.)(\d{2})", s)
    if not m:
        m = re.fullmatch(r"(\d{1,2})", s)
        if not m:
            return None
        h, mm = int(m.group(1)), 0
    else:
        h, mm = int(m.group(1)), int(m.group(2))
    if not (0 <= h <= 23 and 0 <= mm <= 59):
        return None
    return h * 60 + mm


def _tp_gq_fmt_time(value: Any) -> str:
    if isinstance(value, int):
        minutes = int(value) % 1440
    else:
        parsed = _tp_gq_parse_time(value)
        minutes = 0 if parsed is None else int(parsed)
    return f"{minutes // 60:02d}:{minutes % 60:02d}"


def _tp_gq_segments(start_min: int, end_min: int) -> List[Tuple[int, int]]:
    start_min = int(start_min) % 1440
    end_min = int(end_min) % 1440
    if start_min == end_min:
        return []
    if start_min < end_min:
        return [(start_min, end_min)]
    return [(start_min, 1440), (0, end_min)]


def _tp_gq_contains_minute(start_min: int, end_min: int, minute: int) -> bool:
    return any(a <= int(minute) < b for a, b in _tp_gq_segments(start_min, end_min))


def _tp_gq_overlap_minutes(day_start: int, day_end: int, night_start: int, night_end: int) -> int:
    total = 0
    for a1, b1 in _tp_gq_segments(day_start, day_end):
        for a2, b2 in _tp_gq_segments(night_start, night_end):
            total += max(0, min(b1, b2) - max(a1, a2))
    return int(total)


def _tp_gq_covered_minutes(day_start: int, day_end: int, night_start: int, night_end: int) -> int:
    points = [False] * 1440
    for a, b in _tp_gq_segments(day_start, day_end) + _tp_gq_segments(night_start, night_end):
        for i in range(a, b):
            points[i] = True
    return sum(1 for x in points if x)


def _tp_gq_validate_schedule(day_start: str, day_end: str, night_start: str, night_end: str) -> Tuple[bool, str, Dict[str, int]]:
    ds = _tp_gq_parse_time(day_start)
    de = _tp_gq_parse_time(day_end)
    ns = _tp_gq_parse_time(night_start)
    ne = _tp_gq_parse_time(night_end)
    if None in (ds, de, ns, ne):
        return False, "⚠️ Время нужно писать в формате HH:MM. Пример: 08:00 17:00 17:00 08:00", {}
    assert ds is not None and de is not None and ns is not None and ne is not None
    if ds == de or ns == ne:
        return False, "⚠️ Начало и конец окна не могут совпадать.", {}
    overlap = _tp_gq_overlap_minutes(ds, de, ns, ne)
    if overlap > 0:
        return False, "⚠️ Дневное и ночное окно пересекаются. Сохранение запрещено. Отправьте правильный график.", {}
    return True, "", {"day_start": ds, "day_end": de, "night_start": ns, "night_end": ne, "covered": _tp_gq_covered_minutes(ds, de, ns, ne)}


async def _tp_gq_ensure_manager_tables(db_path: str) -> None:
    if not db_path:
        return
    parent = os.path.dirname(str(db_path))
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(str(db_path)) as db:
        await db.execute("PRAGMA journal_mode=WAL;")
        await db.execute("""
            CREATE TABLE IF NOT EXISTS old_client_night_autoresponder_state(
                manager_key TEXT NOT NULL DEFAULT '',
                chat_id INTEGER NOT NULL,
                night_key TEXT NOT NULL DEFAULT '',
                sent_at TEXT NOT NULL DEFAULT '',
                PRIMARY KEY(manager_key, chat_id, night_key)
            );
        """)
        await db.commit()


async def _tp_gq_get_schedule(manager_key: str) -> Dict[str, Any]:
    key = _tp_gq_norm_key(manager_key)
    default = {
        "manager_key": key,
        "day_start": TP_GQ_DEFAULT_DAY_START,
        "day_end": TP_GQ_DEFAULT_DAY_END,
        "night_start": TP_GQ_DEFAULT_NIGHT_START,
        "night_end": TP_GQ_DEFAULT_NIGHT_END,
        "is_default": 1,
        "is_inherited": 0,
        "source_key": None,
    }
    if not key:
        return default
    await _tp_gq_ensure_central_tables()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        # 1) Explicit per-manager override always wins (current behavior, byte-identical when set).
        cur = await db.execute("SELECT * FROM manager_client_message_schedule WHERE manager_key=?", (key,))
        row = await cur.fetchone()
        if row:
            d = dict(row)
            d["is_default"] = 0
            d["is_inherited"] = 0
            d["source_key"] = None
            return d
        # 2) Patch C2: no explicit override -> inherit the linked source's TIME schedule if its
        # source_message_schedule is enabled. Wrapped defensively so that a DB without
        # manager_source_links/source_message_schedule falls back to exactly today's default
        # (fully inert: no source row / enabled=0 => standard 08:00-17:00 / 17:00-08:00).
        linked_source = None
        try:
            link_cur = await db.execute(
                "SELECT source_key FROM manager_source_links "
                "WHERE manager_key=? AND COALESCE(source_key,'')<>'' LIMIT 1",
                (key,),
            )
            link_row = await link_cur.fetchone()
            linked_source = str((link_row["source_key"] if link_row else "") or "").strip() or None
            if linked_source:
                # Query source_message_schedule by the source_key exactly as stored in
                # manager_source_links (no re-normalization), matching C1's resolver join.
                src_cur = await db.execute(
                    "SELECT day_start, day_end, night_start, night_end, enabled "
                    "FROM source_message_schedule WHERE source_key=?",
                    (linked_source,),
                )
                src_row = await src_cur.fetchone()
                if src_row and int(src_row["enabled"] or 0) == 1:
                    return {
                        "manager_key": key,
                        "day_start": str(src_row["day_start"] or TP_GQ_DEFAULT_DAY_START),
                        "day_end": str(src_row["day_end"] or TP_GQ_DEFAULT_DAY_END),
                        "night_start": str(src_row["night_start"] or TP_GQ_DEFAULT_NIGHT_START),
                        "night_end": str(src_row["night_end"] or TP_GQ_DEFAULT_NIGHT_END),
                        "is_default": 0,
                        "is_inherited": 1,
                        "source_key": linked_source,
                    }
        except Exception:
            linked_source = linked_source  # fall through to default below
        # 3) Nothing configured -> standard default (inert). Surface the linked source_key if any.
        result = dict(default)
        if linked_source:
            result["source_key"] = linked_source
        return result


async def _tp_gq_set_schedule(manager_key: str, day_start: str, day_end: str, night_start: str, night_end: str, *, user_id: int = 0) -> str:
    key = _tp_gq_norm_key(manager_key)
    if not key:
        return "⚠️ Менеджер не указан."
    ok, err, meta = _tp_gq_validate_schedule(day_start, day_end, night_start, night_end)
    if not ok:
        return err
    await _tp_gq_ensure_central_tables()
    now = _tp_gq_now_iso()
    ds = _tp_gq_fmt_time(meta["day_start"])
    de = _tp_gq_fmt_time(meta["day_end"])
    ns = _tp_gq_fmt_time(meta["night_start"])
    ne = _tp_gq_fmt_time(meta["night_end"])
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute("""
            INSERT INTO manager_client_message_schedule(manager_key, day_start, day_end, night_start, night_end, updated_at, updated_by_user_id)
            VALUES(?,?,?,?,?,?,?)
            ON CONFLICT(manager_key) DO UPDATE SET
                day_start=excluded.day_start,
                day_end=excluded.day_end,
                night_start=excluded.night_start,
                night_end=excluded.night_end,
                updated_at=excluded.updated_at,
                updated_by_user_id=excluded.updated_by_user_id
        """, (key, ds, de, ns, ne, now, int(user_id or 0) or None))
        await db.commit()
    warn = ""
    if int(meta.get("covered") or 0) < 1440:
        warn = "\n⚠️ Есть промежуток без авто-сообщений. В этот промежуток клиенту ничего не отправляется."
    return f"✅ График сохранён для {key}\nДневное: {ds}-{de}\nНочное: {ns}-{ne}{warn}"


async def _tp_gq_reset_schedule(manager_key: str, *, user_id: int = 0) -> None:
    key = _tp_gq_norm_key(manager_key)
    if not key:
        return
    await _tp_gq_ensure_central_tables()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute("DELETE FROM manager_client_message_schedule WHERE manager_key=?", (key,))
        await db.commit()


def _tp_gq_schedule_minutes(schedule: Dict[str, Any]) -> Dict[str, int]:
    return {
        "day_start": _tp_gq_parse_time(schedule.get("day_start") or TP_GQ_DEFAULT_DAY_START) or 8 * 60,
        "day_end": _tp_gq_parse_time(schedule.get("day_end") or TP_GQ_DEFAULT_DAY_END) or 17 * 60,
        "night_start": _tp_gq_parse_time(schedule.get("night_start") or TP_GQ_DEFAULT_NIGHT_START) or 17 * 60,
        "night_end": _tp_gq_parse_time(schedule.get("night_end") or TP_GQ_DEFAULT_NIGHT_END) or 8 * 60,
    }


def _tp_gq_window_now(schedule: Dict[str, Any], now_local: Optional[datetime] = None) -> Tuple[str, str, str]:
    dt = now_local or _kyiv_now()
    minute = int(dt.hour) * 60 + int(dt.minute)
    m = _tp_gq_schedule_minutes(schedule)
    in_day = _tp_gq_contains_minute(m["day_start"], m["day_end"], minute)
    in_night = _tp_gq_contains_minute(m["night_start"], m["night_end"], minute)
    if in_day and not in_night:
        return "day", "Дневное", ""
    if in_night and not in_day:
        night_key = _tp_gq_night_key(str(schedule.get("manager_key") or MANAGER_RUNTIME_KEY), schedule, dt)
        return "night", "Ночное", night_key
    if in_day and in_night:
        return "overlap", "Ошибка графика: пересечение", ""
    return "gap", "Промежуток без авто-сообщений", ""


def _tp_gq_night_key(manager_key: str, schedule: Dict[str, Any], now_local: Optional[datetime] = None) -> str:
    dt = now_local or _kyiv_now()
    m = _tp_gq_schedule_minutes(schedule)
    ns, ne = int(m["night_start"]), int(m["night_end"])
    minute = int(dt.hour) * 60 + int(dt.minute)
    if ns > ne:
        end_date = (dt.date() + timedelta(days=1)) if minute >= ns else dt.date()
    else:
        end_date = dt.date()
    return f"{_tp_gq_norm_key(manager_key)}:night:{end_date.isoformat()}:{_tp_gq_fmt_time(ns)}-{_tp_gq_fmt_time(ne)}"


def _tp_gq_content_text(key: str, fallback: str = "") -> str:
    try:
        if callable(globals().get("_content_get_text")):
            val = _content_get_text(str(key))
            if str(val or "").strip():
                return str(val)
    except Exception:
        pass
    return str(fallback or _content_text_defaults().get(key) or "")


def _tp_gq_lead_date_is_today(lead: Dict[str, Any], now_local: Optional[datetime] = None) -> bool:
    dt = now_local or _kyiv_now()
    return str((lead or {}).get("lead_date") or "") == dt.date().isoformat()


def _tp_gq_question_sent(lead: Dict[str, Any], state: Dict[str, Any]) -> bool:
    return int((state or {}).get("profile_question_sent") or 0) == 1 or int((lead or {}).get("profile_question_sent") or 0) == 1


async def _tp_gq_old_autoresponder_sent(db_path: str, manager_key: str, chat_id: int, night_key: str) -> bool:
    await _tp_gq_ensure_manager_tables(db_path)
    async with aiosqlite.connect(str(db_path)) as db:
        cur = await db.execute("SELECT 1 FROM old_client_night_autoresponder_state WHERE manager_key=? AND chat_id=? AND night_key=? LIMIT 1", (_tp_gq_norm_key(manager_key), int(chat_id), str(night_key)))
        return bool(await cur.fetchone())


async def _tp_gq_mark_old_autoresponder_sent(db_path: str, manager_key: str, chat_id: int, night_key: str) -> None:
    await _tp_gq_ensure_manager_tables(db_path)
    async with aiosqlite.connect(str(db_path)) as db:
        await db.execute("INSERT OR IGNORE INTO old_client_night_autoresponder_state(manager_key, chat_id, night_key, sent_at) VALUES(?,?,?,?)", (_tp_gq_norm_key(manager_key), int(chat_id), str(night_key), _tp_gq_now_iso()))
        await db.commit()


async def _tp_gq_update_profile_passive(db_path: str, lead_row: Dict[str, Any], text: str, *, force: bool = False) -> Dict[str, Any]:
    chat_id = int((lead_row or {}).get("chat_id") or 0)
    if chat_id <= 0 or not str(text or "").strip():
        return dict(lead_row or {})
    existing_same = int((lead_row or {}).get("_existing_same_manager_chat") or 0) == 1
    gate_auto = int((lead_row or {}).get("profile_question_sent") or 0) == 1
    try:
        gate_manual = await _capture_is_open(db_path, chat_id)
    except Exception:
        gate_manual = False
    has_context = bool(str((lead_row or {}).get("profile_raw_text") or "").strip())
    if not (force or existing_same or gate_auto or gate_manual or has_context):
        # Do not parse the very first lead message blindly.
        if callable(_TP_GQ_ORIG_APPLY_PROFILE_FROM_TEXT):
            return await _TP_GQ_ORIG_APPLY_PROFILE_FROM_TEXT(db_path, lead_row, text)
        return dict(lead_row or {})
    try:
        pe = _tpe_import_extractor()
        await _tpe_ensure_profile_schema(db_path)
        msgs = _tpe_messages_with_new(str((lead_row or {}).get("profile_raw_text") or ""), str(text or ""))
        parsed = pe.extract_profile_v2(msgs, dict(lead_row or {}))
        parsed["profile_raw_text"] = "\n".join([x for x in msgs if str(x or "").strip()])[-4000:]
        parsed["profile_answered_at"] = _now_utc_iso()
        if int((lead_row or {}).get("manual_status_override") or 0) == 1:
            for k in ("status", "nonliquid_reason", "profile_done", "quality_status", "quality_bucket", "quality_reason", "quality_confidence", "quality_source", "quality_version"):
                parsed.pop(k, None)
        try:
            await _tpe_insert_profile_audit(db_path, dict(lead_row or {}), parsed)
        except Exception:
            pass
        await _tpe_direct_update_daily(
            db_path,
            lead_date=str((lead_row or {}).get("lead_date") or _kyiv_now().date().isoformat()),
            manager_key=str((lead_row or {}).get("manager_key") or MANAGER_RUNTIME_KEY),
            chat_id=chat_id,
            **parsed,
        )
        if gate_manual:
            try:
                await _decrement_capture(db_path, chat_id)
            except Exception:
                pass
        if int(parsed.get("profile_done") or 0) == 1:
            try:
                await _close_capture_if_done(db_path, chat_id)
            except Exception:
                pass
        out = dict(lead_row or {})
        out.update(parsed)
        return out
    except Exception as e:
        print(f"greeting_questionnaire passive profile error: {e!r}")
        if callable(_TP_GQ_ORIG_APPLY_PROFILE_FROM_TEXT):
            return await _TP_GQ_ORIG_APPLY_PROFILE_FROM_TEXT(db_path, lead_row, text)
        return dict(lead_row or {})


async def _apply_profile_from_text(db_path: str, lead_row: Dict[str, Any], text: str) -> Dict[str, Any]:  # type: ignore[override]
    return await _tp_gq_update_profile_passive(db_path, lead_row, text)


async def _tp_gq_send_questionnaire_followup(lead_row: Dict[str, Any], state: Dict[str, Any], chat_id: int) -> None:
    if int((state or {}).get("manager_replied") or 0) == 1 or int((lead_row or {}).get("manager_replied") or 0) == 1:
        await _update_daily_lead_fields(DB_PATH, lead_date=str(lead_row.get("lead_date") or _kyiv_now().date().isoformat()), manager_key=str(lead_row.get("manager_key") or MANAGER_RUNTIME_KEY), chat_id=chat_id, manager_replied=1, manager_replied_at=str((state or {}).get("manager_replied_at") or ""))
        return

    _tp_gq_qf_manager_key = _tp_gq_norm_key(str((lead_row or {}).get("manager_key") or MANAGER_RUNTIME_KEY or "")) if callable(globals().get("_tp_gq_norm_key")) else str((lead_row or {}).get("manager_key") or MANAGER_RUNTIME_KEY or "").strip().lower()
    _tp_gq_qf_allowed, _tp_gq_qf_reason = await _lead_automation_gate(_tp_gq_qf_manager_key, chat_id, "questionnaire", state)
    if not _tp_gq_qf_allowed:
        try:
            print(f"questionnaire followup gate-denied chat_id={chat_id} manager={_tp_gq_qf_manager_key} reason={_tp_gq_qf_reason}")
        except Exception:
            pass
        return

    country = str((lead_row or {}).get("country") or "").strip()
    lead_status = str((lead_row or {}).get("status") or "").strip().lower()
    client_text = str((lead_row or {}).get("_last_incoming_text") or "")

    if country == "Украина" and int((state or {}).get("ua_text_sent") or 0) != 1 and int((lead_row or {}).get("ua_text_sent") or 0) != 1:
        if await _send_manager_private(chat_id, _tp_gq_content_text("ua_redirect", str(globals().get("UA_REDIRECT_TEXT") or "")), human_delay=True, after_first_delay=True, new_dialog=False):
            await _set_daily_ua_sent(lead_row)
        return

    dialog_state = await load_profile_dialog_state(DB_PATH, chat_id)
    decision = choose_profile_reply(lead_row, client_text, dialog_state)
    # --- TPILOT LLM SUPERVISOR SHADOW (inert, never modifies state) ---
    _tp_f1_llm_parsed: Any = None
    try:
        if _LLM_SUPERVISOR_OK and _llm_supervisor_mod is not None and await _llm_runtime_enabled():
            _tp_f1_llm_parsed = await _llm_supervisor_mod.llm_supervisor_shadow(
                lead_row, dialog_state, client_text, det_decision=decision,
                recent_messages=_llmq_split_recent_messages(client_text),
            )
    except Exception:
        pass
    # --- TPILOT LLM SUPERVISOR SHADOW END ---
    # --- TPILOT LLM F1 AUDIT PERSIST (fail-open, no stats impact) ---
    try:
        await _tp_llm_status_persist(DB_PATH, lead_row, _tp_f1_llm_parsed, client_text)
    except Exception:
        pass
    # --- TPILOT LLM F1 AUDIT PERSIST END ---
    if decision.get("update_fields"):
        fields = dict(decision.get("update_fields") or {})
        try:
            await _update_daily_lead_fields(DB_PATH, lead_date=str(lead_row.get("lead_date") or _kyiv_now().date().isoformat()), manager_key=str(lead_row.get("manager_key") or MANAGER_RUNTIME_KEY), chat_id=chat_id, **fields)
            lead_row = dict(lead_row or {})
            lead_row.update(fields)
            lead_status = str(lead_row.get("status") or "").strip().lower()
        except Exception:
            pass
    if decision.get("send_text"):
        _det_text = str(decision.get("send_text") or "")
        _send_text = await _tp_llm_live_text_or_default(
            lead_row, dialog_state, client_text, decision, _det_text, chat_id
        )
        if await _send_manager_private(chat_id, _send_text, human_delay=True, after_first_delay=True, new_dialog=False):
            await _set_daily_question_sent(lead_row)
            attempts = int((lead_row or {}).get("clarify_attempts") or 0) + 1
            await _set_daily_clarify_attempts(lead_row, attempts)
            await mark_profile_dialog_sent(
                DB_PATH,
                chat_id,
                template_key=str(decision.get("template_key") or ""),
                intent=str(decision.get("intent") or ""),
                bot_text=_send_text,
                client_text=client_text,
                increment_city_attempt=bool(decision.get("increment_city_attempt")),
            )
        return

    if lead_status in ("liquid", "nonliquid") and int((lead_row or {}).get("profile_done") or 0) == 1:
        if int((lead_row or {}).get("profile_final_sent") or 0) != 1:
            txt = ""
            if lead_status == "liquid":
                txt = _tp_gq_content_text("profile_success", str(globals().get("PROFILE_SUCCESS_TEXT") or ""))
            elif lead_status == "nonliquid":
                txt = _nonliquid_country_client_text(lead_row)
            if txt:
                # TPILOT HEALTH RECOVERY HYBRID-D CORRECTIVE 20260723b (finding
                # H2): the send result was previously ignored and the sent-flag
                # was always written, so a health-gate denial (or any genuine
                # send failure) permanently lost this message -- no candidate
                # query ever re-selects a lead with profile_final_sent=1. Only
                # mark it sent when it actually was; a gate denial/failure now
                # leaves it pending for the next incoming message to retry.
                ok = await _send_manager_private(chat_id, txt, human_delay=True, after_first_delay=True, new_dialog=False)
                if ok:
                    await _set_daily_profile_final_sent(lead_row)
            else:
                # Nothing to send (no content for this lead_status) -- mark
                # handled so this branch isn't re-evaluated forever.
                await _set_daily_profile_final_sent(lead_row)
        return

    missing_age, missing_geo = _profile_missing_fields(lead_row)
    if missing_age or missing_geo:
        txt = _clarify_text_for_lead(lead_row) or _tp_gq_content_text("profile_question", str(globals().get("PROFILE_QUESTION_TEXT") or ""))
        if await _send_manager_private(chat_id, txt, human_delay=True, after_first_delay=True, new_dialog=False):
            await _set_daily_question_sent(lead_row)
            attempts = int((lead_row or {}).get("clarify_attempts") or 0) + 1
            await _set_daily_clarify_attempts(lead_row, attempts)
        return


async def _tp_gq_manager_keys(target: str) -> Tuple[List[str], str]:
    target = _tp_gq_norm_key(target or "all") or "all"
    rows = await manager_list_rows(include_removed=False)
    # TPILOT PREPARED ACCOUNTS PHASE 3: /greeting status all is an
    # operational AdminBot report over every manager's greeting/away-hours
    # settings; a prepared account has neither a working schedule nor
    # greeting configuration worth reporting, so it is excluded from the
    # bulk "all" enumeration -- same "default-excludes, explicit-lookup-
    # still-finds" shape as panel_bot.py's _manager_rows/_manager_row_by_key
    # (an admin explicitly querying a prepared account's own key is still
    # answered, only the "all" sweep is narrowed).
    if target == "all":
        rows = [r for r in (rows or []) if str(r.get("status") or "").strip().lower() != "prepared"]
    keys = [_tp_gq_norm_key(r.get("manager_key") or "") for r in rows if _tp_gq_norm_key(r.get("manager_key") or "")]
    if target != "all":
        if target not in keys:
            return [], f"Менеджер не найден: {target}"
        return [target], ""
    return keys, ""


async def _tp_gq_format_status(target: str = "all") -> str:
    keys, err = await _tp_gq_manager_keys(target)
    if err:
        return err
    rows = await manager_list_rows(include_removed=False)
    row_by_key = {_tp_gq_norm_key(r.get("manager_key") or ""): r for r in rows or []}
    lines = ["👋 Приветствие / нет на месте", f"Версия: {_TP_GQ_VERSION}", ""]
    if not keys:
        lines.append("Менеджеры не найдены.")
        return "\n".join(lines).rstrip()
    for key in keys:
        st = await _tp_gq_get_settings(key)
        sch = await _tp_gq_get_schedule(key)
        mode, label, _ = _tp_gq_window_now(sch, _kyiv_now())
        m = _tp_gq_schedule_minutes(sch)
        warn = ""
        if _tp_gq_covered_minutes(m["day_start"], m["day_end"], m["night_start"], m["night_end"]) < 1440:
            warn = "\n⚠️ Есть промежуток без авто-сообщений"
        label_mgr = _manager_label_from_row(row_by_key.get(key) or {"manager_key": key})
        lines.append(label_mgr)
        lines.append(f"Приветствие / нет на месте: {'включено' if int(st.get('greeting_enabled') or 0) == 1 else 'выключено'}")
        lines.append(f"Автоанкета: {'включена' if int(st.get('questionnaire_enabled') or 0) == 1 else 'выключена'}")
        if int(sch.get("is_inherited") or 0) == 1:
            sched_src = f"🟢 по источнику ({sch.get('source_key')})"
        elif int(sch.get("is_default") or 0) == 1:
            sched_src = "стандарт 08:00-17:00"
        else:
            sched_src = "личный график"
        lines.append(f"График времени: {sched_src}")
        lines.append(f"Дневное: {sch.get('day_start')}-{sch.get('day_end')}")
        lines.append(f"Ночное: {sch.get('night_start')}-{sch.get('night_end')}")
        lines.append(f"Сейчас: {label}")
        if warn:
            lines.append(warn.strip())
        lines.append("")
    return "\n".join(lines).rstrip()


async def _tp_gq_handle_schedule_command(args: str, *, user_id: int = 0) -> str:
    parts = [p for p in str(args or "").split() if p.strip()]
    action = (parts[0].lower() if parts else "status")
    if action in ("status", "st", "state"):
        target = parts[1] if len(parts) >= 2 else "all"
        return await _tp_gq_format_status(target)
    if action == "reset":
        target = parts[1] if len(parts) >= 2 else "all"
        keys, err = await _tp_gq_manager_keys(target)
        if err:
            return err
        for key in keys:
            await _tp_gq_reset_schedule(key, user_id=user_id)
        return await _tp_gq_format_status(target)
    if action == "set":
        if len(parts) < 6:
            return "Формат: /autoschedule set <manager> <day_start> <day_end> <night_start> <night_end>\nПример: /autoschedule set miller 08:00 17:00 17:00 08:00"
        target = _tp_gq_norm_key(parts[1])
        keys, err = await _tp_gq_manager_keys(target)
        if err:
            return err
        if len(keys) != 1:
            return "⚠️ График задаётся по одному менеджеру."
        return await _tp_gq_set_schedule(keys[0], parts[2], parts[3], parts[4], parts[5], user_id=user_id)
    return "Формат: /autoschedule status|set|reset <manager|all>"


async def _handle_ai_stat_command(event):  # type: ignore[override]
    try:
        if CONTROLLER_MODE and int(event.chat_id or 0) == int(AI_STAT_CHAT_ID or 0):
            cmd, args = _parse_cmd((event.raw_text or "").strip())
            if cmd == "/greeting":
                await client.send_message(event.chat_id, await _tp_gq_handle_greeting_command(args, user_id=int(event.sender_id or 0)))
                return True
            if cmd == "/questionnaire":
                await client.send_message(event.chat_id, await _tp_gq_handle_questionnaire_command(args, user_id=int(event.sender_id or 0)))
                return True
            if cmd == "/autoschedule":
                await client.send_message(event.chat_id, await _tp_gq_handle_schedule_command(args, user_id=int(event.sender_id or 0)))
                return True
    except Exception as e:
        try:
            await client.send_message(event.chat_id, f"Ошибка настроек приветствия: {e!r}")
            return True
        except Exception:
            pass
    if callable(_TP_GQ_ORIG_HANDLE_AI_STAT):
        return await _TP_GQ_ORIG_HANDLE_AI_STAT(event)
    return False


async def _panel_execute_command_text(command_text: str, *, requested_by: int = 0, source_chat_id: int = 0, response_chat_id: int = 0):  # type: ignore[override]
    text = str(command_text or "").strip()
    cmd, args = _parse_cmd(text)
    if cmd == "/greeting":
        return {"ok": True, "result_text": await _tp_gq_handle_greeting_command(args, user_id=requested_by)}
    if cmd == "/questionnaire":
        return {"ok": True, "result_text": await _tp_gq_handle_questionnaire_command(args, user_id=requested_by)}
    if cmd == "/autoschedule":
        return {"ok": True, "result_text": await _tp_gq_handle_schedule_command(args, user_id=requested_by)}
    if cmd == "/autoreply":
        return {"ok": True, "result_text": await _handle_autoreply_panel_command(args, user_id=requested_by)}
    if callable(_TP_GQ_ORIG_PANEL_EXEC):
        try:
            return await _TP_GQ_ORIG_PANEL_EXEC(command_text, requested_by=requested_by, source_chat_id=source_chat_id, response_chat_id=response_chat_id)
        except TypeError:
            try:
                return await _TP_GQ_ORIG_PANEL_EXEC(command_text, requested_by=requested_by)
            except TypeError:
                return await _TP_GQ_ORIG_PANEL_EXEC(command_text)
    return {"ok": False, "error_text": f"Команда не поддерживается: {cmd or text}"}

