def _tp_hg_error_text(exc: Any) -> str:
    try:
        cls = exc.__class__.__name__
        text = str(exc or "").strip()
        return f"{cls}: {text}" if text else cls
    except Exception:
        return repr(exc)


# TPILOT ACCOUNT LIVE VERIFICATION 20260810 (Correction A). Ordered,
# mutually-exclusive mark tuples for classifying the VERIFICATION probe's
# OWN outcome (a direct client.get_me() on the manager's OWN account) --
# deliberately separate from _tp_hg_classify_exception's blocked_marks
# below, which classifies an error about an ARBITRARY peer/operation and
# must never be trusted alone to declare a ban. Checked in this exact
# order: BANNED before DEACTIVATED, since a real UserDeactivatedBanError's
# class name also contains the substring "userdeactivated".
_TP_HG_VERIFY_BANNED_MARKS = ("userdeactivatedban", "phonenumberbanned", "phone number banned", "banned")
_TP_HG_VERIFY_DEACTIVATED_MARKS = ("userdeactivated", "deactivated", "account deleted")
_TP_HG_VERIFY_AUTH_MARKS = (
    "authkeyunregistered", "auth_key_unregistered", "authkeyduplicated", "authkeyerror",
    "sessionrevoked", "sessionexpired", "unauthorized", "not authorized", "not authorised",
    "session password needed", "session invalid", "authorization key", "key is not registered", "revoked",
)
_TP_HG_VERIFY_NETWORK_MARKS = (
    "timeout", "timed out", "connection", "proxy", "socks", "network",
    "dns", "refused", "reset by peer", "0 bytes read", "disconnected",
)

TP_HG_VERIFY_ACCOUNT_LIVE = "account_live"
TP_HG_VERIFY_AUTH_SESSION_PROBLEM = "auth_session_problem"
TP_HG_VERIFY_IDENTITY_MISMATCH = "identity_mismatch"
TP_HG_VERIFY_ACCOUNT_DEACTIVATED_CONFIRMED = "account_deactivated_confirmed"
TP_HG_VERIFY_ACCOUNT_BANNED_CONFIRMED = "account_banned_confirmed"
TP_HG_VERIFY_NETWORK_OR_PROXY_PROBLEM = "network_or_proxy_problem"
TP_HG_VERIFY_UNKNOWN = "unknown_verify_failed"


async def _tp_hg_verify_account_live(manager_key: str, *, source: str = "verify") -> Dict[str, Any]:
    """CORRECTION A 20260810: independently verifies the MANAGER'S OWN
    account state via a direct client.get_me() call, before a suspected-
    blocked classification derived from an error on an unrelated peer/
    operation (e.g. a SendMessageRequest to a lead) is allowed to become a
    durable 'blocked'/banned status. Reuses the SAME stored-vs-live
    tg_user_id comparison idiom already proven at manager-runtime startup
    (~main.py:5340-5354) and in the periodic self-check's identity reconcile
    (_identity_reconcile_from_me, ~main.py:22349), plus the existing
    _tp_hg_me_health_problem deleted/restricted-flag check -- no parallel
    verification mechanism invented.

    Costs exactly one extra Telegram API call (get_me) -- only ever invoked
    from _tp_hg_set_from_exception when about to declare BLOCKED, never on
    every exception, and never as a new periodic loop.

    Fails CLOSED: any ambiguity (network error during verification, empty
    get_me result, an unrecognised exception) returns TP_HG_VERIFY_UNKNOWN,
    never a confirmed ban/deactivation. A username is never consulted --
    the only identity anchor is tg_user_id."""
    key = _tp_hg_norm_key(manager_key)
    if not key:
        return {"verify_class": TP_HG_VERIFY_UNKNOWN, "detail": "empty manager_key", "error_source": f"{source}_verify_get_me"}
    try:
        me = await client.get_me()
    except Exception as verify_exc:
        vcls = str(getattr(getattr(verify_exc, "__class__", None), "__name__", "") or "")
        vlow = (vcls + " " + str(verify_exc or "")).lower()
        if any(m in vlow for m in _TP_HG_VERIFY_BANNED_MARKS):
            vclass = TP_HG_VERIFY_ACCOUNT_BANNED_CONFIRMED
        elif any(m in vlow for m in _TP_HG_VERIFY_DEACTIVATED_MARKS):
            vclass = TP_HG_VERIFY_ACCOUNT_DEACTIVATED_CONFIRMED
        elif any(m in vlow for m in _TP_HG_VERIFY_AUTH_MARKS):
            vclass = TP_HG_VERIFY_AUTH_SESSION_PROBLEM
        elif any(m in vlow for m in _TP_HG_VERIFY_NETWORK_MARKS):
            vclass = TP_HG_VERIFY_NETWORK_OR_PROXY_PROBLEM
        else:
            # Unrecognised exception during verification itself -- fail
            # closed, never assume ban on ambiguous evidence.
            vclass = TP_HG_VERIFY_UNKNOWN
        return {
            "verify_class": vclass,
            "error_class": vcls or "Exception",
            "error_text": _tp_hg_error_text(verify_exc),
            "error_source": f"{source}_verify_get_me",
        }

    if not me:
        return {"verify_class": TP_HG_VERIFY_UNKNOWN, "detail": "get_me returned empty result", "error_source": f"{source}_verify_get_me"}

    live_tg_id = int(getattr(me, "id", 0) or 0)
    if not live_tg_id:
        return {"verify_class": TP_HG_VERIFY_UNKNOWN, "detail": "get_me.id missing", "error_source": f"{source}_verify_get_me"}

    try:
        row = get_manager_row_from_db_sync(TPILOT_DB_PATH, key) or {}
        stored_tg_id = int(row.get("tg_user_id") or 0)
    except Exception:
        stored_tg_id = 0

    # Identity anchor is tg_user_id ONLY -- username is never consulted
    # (may legitimately change, be cleared, or be absent on a perfectly
    # live account).
    if stored_tg_id and stored_tg_id != live_tg_id:
        return {
            "verify_class": TP_HG_VERIFY_IDENTITY_MISMATCH,
            "error_class": "telegram_identity_mismatch",
            "error_text": f"Telegram id не совпадает: в реестре {stored_tg_id}, у текущей сессии {live_tg_id}.",
            "error_source": f"{source}_verify_get_me",
            "stored_tg_user_id": stored_tg_id,
            "live_tg_user_id": live_tg_id,
        }

    problem = _tp_hg_me_health_problem(me, source=f"{source}_verify_get_me")
    if problem:
        if str(problem.get("status") or "") == TP_HG_STATUS_BLOCKED:
            # get_me succeeded but Telegram's own API flags this account
            # (OUR OWN account, not a peer) as deleted -- this is direct,
            # first-party evidence, not a guess from a third-party error.
            return {
                "verify_class": TP_HG_VERIFY_ACCOUNT_DEACTIVATED_CONFIRMED,
                "error_class": "AccountDeactivatedConfirmed",
                "error_text": str(problem.get("error_text") or ""),
                "error_source": str(problem.get("error_source") or f"{source}_verify_get_me"),
            }
        # Restricted-but-not-deleted: the account is live, just limited --
        # never a ban.
        return {
            "verify_class": TP_HG_VERIFY_ACCOUNT_LIVE,
            "detail": "restricted_but_live",
            "error_text": str(problem.get("error_text") or ""),
        }

    return {"verify_class": TP_HG_VERIFY_ACCOUNT_LIVE, "tg_user_id": live_tg_id}


def _tp_hg_classify_exception(exc: Any, *, source: str = "") -> Dict[str, Any]:
    """Classify Telethon/Telegram errors without depending on exact class imports."""
    cls = str(getattr(getattr(exc, "__class__", None), "__name__", "") or "")
    text = str(exc or "")
    low = (cls + " " + text).lower()
    seconds = 0
    try:
        seconds = int(getattr(exc, "seconds", 0) or 0)
    except Exception:
        seconds = 0

    blocked_marks = [
        "authkeyunregistered", "auth_key_unregistered", "authkeyduplicated", "sessionrevoked",
        "userdeactivated", "userdeactivatedban", "phonenumberbanned", "phone number banned",
        "unauthorized", "not authorized", "not authorised", "session password needed",
        "session invalid", "authorization key", "key is not registered", "account deleted",
        "deactivated", "banned", "revoked",
    ]
    limited_marks = [
        "peerflood", "peer flood", "too many requests", "spam", "restricted",
        "you can't write", "cannot write", "initiate conversation", "write to this user",
        "user is restricted", "privacyrestricted", "forbidden to send",
    ]
    warning_marks = [
        "floodwait", "flood wait", "wait of", "timeout", "timed out", "connection",
        "proxy", "userisblocked", "user is blocked", "chatwriteforbidden", "chat write forbidden",
        "privacy", "forbidden",
    ]

    if any(m in low for m in blocked_marks):
        return {
            "status": TP_HG_STATUS_BLOCKED,
            "error_class": cls or "Exception",
            "error_text": _tp_hg_error_text(exc),
            "error_source": str(source or "telegram"),
            "action_required": "Проверить аккаунт вручную. Если session слетела, переподключить через PHONE / CODE / PASS.",
            "seconds": 0,
        }

    if "floodwait" in low or "flood wait" in low or "wait of" in low:
        if seconds >= 30 * 60:
            status = TP_HG_STATUS_LIMITED
            action = "Telegram дал большой FloodWait. Временно остановить трафик на аккаунт и дать ему отлежаться."
        else:
            status = TP_HG_STATUS_WARNING
            action = "Временный FloodWait. Наблюдать, уведомление не отправляется."
        return {
            "status": status,
            "error_class": cls or "FloodWait",
            "error_text": _tp_hg_error_text(exc),
            "error_source": str(source or "telegram"),
            "action_required": action,
            "seconds": seconds,
        }

    if any(m in low for m in limited_marks):
        return {
            "status": TP_HG_STATUS_LIMITED,
            "error_class": cls or "Exception",
            "error_text": _tp_hg_error_text(exc),
            "error_source": str(source or "telegram"),
            "action_required": "Временно остановить трафик на этот аккаунт, проверить отправку вручную в Telegram.",
            "seconds": 0,
        }

    if any(m in low for m in warning_marks):
        return {
            "status": TP_HG_STATUS_WARNING,
            "error_class": cls or "Exception",
            "error_text": _tp_hg_error_text(exc),
            "error_source": str(source or "telegram"),
            "action_required": "Временная или клиентская ошибка. Наблюдать, уведомление не отправляется.",
            "seconds": 0,
        }

    return {
        "status": TP_HG_STATUS_WARNING,
        "error_class": cls or "Exception",
        "error_text": _tp_hg_error_text(exc),
        "error_source": str(source or "telegram"),
        "action_required": "Неизвестная Telegram-ошибка. Проверить по логам, уведомление не отправляется.",
        "seconds": 0,
    }


# --- TPILOT HEALTH RECOVERY HYBRID-D 20260723 START ---
# Normalized restriction-family helper, layered on top of the classifier
# above. Uses only STRUCTURED fields (health_status, error_class -- never
# the free-text error_text) so family detection stays stable across
# differently-worded error messages for the same underlying restriction.
_TP_HG_FAMILY_PEERFLOOD = "peerflood"
_TP_HG_FAMILY_FLOODWAIT = "floodwait"
_TP_HG_FAMILY_BLOCKED = "blocked"
_TP_HG_FAMILY_WARNING = "warning_transient"
_TP_HG_FAMILY_UNKNOWN = "unknown"


def _tp_hg_restriction_family(*, status: str, error_class: str = "") -> str:
    """Normalized restriction family for a manager_telegram_health row's
    CURRENT structured fields. Distinguishes peerflood (sticky, no ordinary
    auto new-dialog sends) from floodwait (timed, exc.seconds-driven cooldown)
    from blocked (sticky, auth/session) from warning/transient (non-sticky)."""
    st = str(status or "").strip().lower()
    cls_low = str(error_class or "").strip().lower()
    if st == TP_HG_STATUS_BLOCKED:
        return _TP_HG_FAMILY_BLOCKED
    if "floodwait" in cls_low or "flood_wait" in cls_low:
        return _TP_HG_FAMILY_FLOODWAIT
    if "peerflood" in cls_low or "peer_flood" in cls_low:
        return _TP_HG_FAMILY_PEERFLOOD
    if st == TP_HG_STATUS_LIMITED:
        # Any other LIMITED classification (spam/restricted/manual mark/self-send
        # probe failure/...) defaults to the sticky peerflood-like family: safer
        # to require explicit recovery than to assume a timed restriction.
        return _TP_HG_FAMILY_PEERFLOOD
    if st == TP_HG_STATUS_WARNING:
        return _TP_HG_FAMILY_WARNING
    return _TP_HG_FAMILY_UNKNOWN
# --- TPILOT HEALTH RECOVERY HYBRID-D 20260723 END ---


def _tp_hg_connect_sync() -> _tp_hg_sqlite3.Connection:
    parent = os.path.dirname(os.path.abspath(TPILOT_DB_PATH))
    if parent:
        os.makedirs(parent, exist_ok=True)
    con = _tp_hg_sqlite3.connect(TPILOT_DB_PATH, timeout=30)
    con.row_factory = _tp_hg_sqlite3.Row
    try:
        con.execute("PRAGMA journal_mode=WAL;")
    except Exception:
        pass
    return con


async def _tp_hg_ensure_tables() -> None:
    parent = os.path.dirname(os.path.abspath(TPILOT_DB_PATH))
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute("PRAGMA journal_mode=WAL;")
        await db.execute("PRAGMA busy_timeout=5000;")
        await db.execute("""
            CREATE TABLE IF NOT EXISTS manager_telegram_health(
                manager_key TEXT PRIMARY KEY,
                health_status TEXT NOT NULL DEFAULT 'unknown',
                severity INTEGER NOT NULL DEFAULT 0,
                error_class TEXT NOT NULL DEFAULT '',
                error_text TEXT NOT NULL DEFAULT '',
                error_source TEXT NOT NULL DEFAULT '',
                first_seen_at TEXT NOT NULL DEFAULT '',
                last_seen_at TEXT NOT NULL DEFAULT '',
                last_ok_at TEXT NOT NULL DEFAULT '',
                last_check_at TEXT NOT NULL DEFAULT '',
                notify_sent_at TEXT NOT NULL DEFAULT '',
                notify_count INTEGER NOT NULL DEFAULT 0,
                last_notify_signature TEXT NOT NULL DEFAULT '',
                action_required TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT '',
                cooldown_until TEXT NOT NULL DEFAULT ''
            );
        """)
        # TPILOT HEALTH RECOVERY HYBRID-D 20260723: idempotent additive migration
        # for pre-existing DBs created before the cooldown_until column existed --
        # same _table_columns()+ALTER-if-missing convention used elsewhere in this
        # file (see _ensure_daily_leads_table). Never destructive, DEFAULT ''.
        try:
            _tp_hg_cols = await _table_columns(db, "manager_telegram_health")
        except Exception:
            _tp_hg_cols = []
        if "cooldown_until" not in _tp_hg_cols:
            try:
                await db.execute("ALTER TABLE manager_telegram_health ADD COLUMN cooldown_until TEXT NOT NULL DEFAULT ''")
            except Exception:
                pass
        await db.execute("CREATE INDEX IF NOT EXISTS manager_telegram_health_status_idx ON manager_telegram_health(health_status, updated_at)")
        await db.execute("""
            CREATE TABLE IF NOT EXISTS panel_notifications(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                kind TEXT NOT NULL DEFAULT '',
                title TEXT NOT NULL DEFAULT '',
                body TEXT NOT NULL DEFAULT '',
                status TEXT NOT NULL DEFAULT 'new',
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        await db.commit()


def _tp_hg_manager_row_sync(manager_key: str) -> Dict[str, Any]:
    key = _tp_hg_norm_key(manager_key)
    if not key:
        return {}
    try:
        con = _tp_hg_connect_sync()
        try:
            row = con.execute("SELECT * FROM managers WHERE manager_key=? LIMIT 1", (key,)).fetchone()
            return dict(row) if row else {"manager_key": key}
        finally:
            con.close()
    except Exception:
        return {"manager_key": key}


def _tp_hg_manager_label_from_key(manager_key: str) -> str:
    row = _tp_hg_manager_row_sync(manager_key)
    try:
        label = _manager_label_from_row(row) if row else _tp_hg_norm_key(manager_key)
    except Exception:
        name = str((row or {}).get("display_name") or manager_key or "").strip()
        username = str((row or {}).get("telegram_username") or "").strip()
        label = f"{name} | @{username}" if username else name
    return label or _tp_hg_norm_key(manager_key)


def _tp_hg_username_from_key(manager_key: str) -> str:
    row = _tp_hg_manager_row_sync(manager_key)
    username = str((row or {}).get("telegram_username") or "").strip()
    return ("@" + username.lstrip("@")) if username else "_"


def _tp_hg_severity(status: str) -> int:
    st = str(status or "").lower()
    return {TP_HG_STATUS_OK: 0, TP_HG_STATUS_UNKNOWN: 1, TP_HG_STATUS_WARNING: 2, TP_HG_STATUS_LIMITED: 3, TP_HG_STATUS_BLOCKED: 4}.get(st, 1)


def _tp_hg_build_alert_text(manager_key: str, row: Dict[str, Any]) -> str:
    status = str(row.get("health_status") or row.get("status") or TP_HG_STATUS_UNKNOWN).lower()
    source = str(row.get("error_source") or "_")
    error_class = str(row.get("error_class") or "_")
    error_text = str(row.get("error_text") or "_")
    action = str(row.get("action_required") or "Проверить аккаунт вручную.")
    now_local = _kyiv_now().strftime("%d.%m.%y %H:%M")
    # CORRECTION A 20260810: a BLOCKED status is no longer automatically a
    # confirmed ban -- _tp_hg_set_from_exception (after live get_me()
    # verification) also reaches BLOCKED for an auth/session problem or an
    # identity mismatch, neither of which is a ban. The alert must not
    # claim "забанен" for those, and must not suggest a plain PHONE/CODE/
    # PASS reconnect for a CONFIRMED ban (action_required already
    # explicitly forbids relogin there).
    ec_low = error_class.lower()
    is_identity_mismatch = error_class == "telegram_identity_mismatch"
    is_confirmed_ban = status == TP_HG_STATUS_BLOCKED and not is_identity_mismatch and any(
        m in ec_low for m in _TP_HG_VERIFY_BANNED_MARKS + _TP_HG_VERIFY_DEACTIVATED_MARKS
    )
    is_auth_problem = status == TP_HG_STATUS_BLOCKED and not is_identity_mismatch and not is_confirmed_ban and any(
        m in ec_low for m in _TP_HG_VERIFY_AUTH_MARKS
    )
    if status == TP_HG_STATUS_LIMITED:
        title = "Аккаунт живой, но Telegram ограничил отправку сообщений."
    elif is_identity_mismatch:
        title = "Telegram id текущей сессии не совпадает с реестром. Это НЕ подтверждённый бан -- нужна проверка аккаунта."
    elif is_auth_problem:
        title = "Сессия не авторизована, нужен перезаход. Это НЕ подтверждённый бан аккаунта."
    else:
        title = "Session умерла, аккаунт забанен, разлогинен или Telegram не даёт работать."
    lines = [
        "�� Telegram Health Alert",
        "",
        f"Статус: {_tp_hg_status_label(status)}",
        f"Аккаунт: {_tp_hg_manager_label_from_key(manager_key)}",
        f"Ключ: {_tp_hg_norm_key(manager_key)}",
        f"family: {_hnv2_tg_health_family(status, error_class)}",
        f"Username: {_tp_hg_username_from_key(manager_key)}",
        "",
        "Что случилось:",
        title,
    ]
    if status == TP_HG_STATUS_LIMITED:
        # PEERFLOOD RECOVERY 20260812 (M7): make explicit that this is not a
        # "manager stopped" alert -- _tp_hg_send_allowed no longer denies
        # ordinary sends for LIMITED, so the owner must not read this as a
        # full stop.
        lines.append(
            "Рабочие отправки менеджера НЕ остановлены: рабочий цикл продолжает "
            "контролируемые реальные попытки, и статус снимется автоматически "
            "после первой успешной рабочей отправки."
        )
    lines.extend([
        "",
        "Ошибка:",
        error_text or error_class,
        "",
        "Где поймали:",
        source,
        "",
        "Время:",
        now_local,
        "",
        "Что делать:",
    ])
    for i, part in enumerate([x.strip() for x in re.split(r"\n+|;", action) if x.strip()], 1):
        lines.append(f"{i}. {part}" if not re.match(r"^\d+\.", part) else part)
    if status == TP_HG_STATUS_LIMITED:
        lines.extend([
            "2. Проверить аккаунт вручную в Telegram.",
            "3. Если ограничение не снимается, заменить аккаунт или дать ему отлежаться.",
        ])
    elif is_confirmed_ban:
        lines.append("2. Проверить аккаунт вручную. Не перезапускать и не перелогинивать.")
    elif is_auth_problem or is_identity_mismatch:
        lines.append("2. Перезайти через карточку менеджера (QR / номер / session / TData).")
    elif status == TP_HG_STATUS_BLOCKED:
        lines.extend([
            "2. Проверить аккаунт вручную.",
            "3. Если session слетела, переподключить через PHONE / CODE / PASS.",
        ])
    return "\n".join(lines).rstrip()


def _tp_hg_build_recovery_alert_text(manager_key: str, old_row: Dict[str, Any]) -> str:
    old_status = str((old_row or {}).get("health_status") or TP_HG_STATUS_UNKNOWN).lower()
    now_local = _kyiv_now().strftime("%d.%m.%y %H:%M")
    lines = [
        "✅ Telegram Health Recovery",
        "",
        f"Аккаунт: {_tp_hg_manager_label_from_key(manager_key)}",
        f"Ключ: {_tp_hg_norm_key(manager_key)}",
        f"Был статус: {_tp_hg_status_label(old_status)}",
        f"Инцидент закрыт: {str((old_row or {}).get('error_class') or '_')} / {str((old_row or {}).get('error_source') or '_')}",
        f"Время: {now_local}",
    ]
    return "\n".join(lines).rstrip()


async def _tp_hg_insert_panel_notification(title: str, body: str) -> None:
    # TPILOT HEALTH RECOVERY HYBRID-D CORRECTIVE 20260723b: this insert is the
    # PRIMARY durable delivery path for a claimed notification (see
    # _tp_hg_notify_if_needed / health_incident_claim_notify) -- a bounded
    # retry on transient lock contention here reduces how often a genuinely
    # claimed notification ends up silently undelivered under concurrent
    # writers to the same DB file, without changing the outer fail-safe
    # (still swallows and logs on final failure -- the claim itself is not
    # re-attempted, matching the documented delivery tradeoff).
    for _attempt in range(3):
        try:
            await _tp_hg_ensure_tables()
            now = _tp_hg_now_iso()
            async with aiosqlite.connect(TPILOT_DB_PATH) as db:
                await db.execute("PRAGMA busy_timeout=5000;")
                await db.execute(
                    "INSERT INTO panel_notifications(kind,title,body,status,created_at,updated_at) VALUES(?,?,?,?,?,?)",
                    ("telegram_health", str(title or "🛡 Telegram Health Alert"), str(body or ""), "new", now, now),
                )
                await db.commit()
            return
        except Exception as e:
            if "database is locked" not in str(e).lower() or _attempt == 2:
                try:
                    print(f"telegram health panel notification error: {e!r}")
                except Exception:
                    pass
                return
            await asyncio.sleep(0.05 * (_attempt + 1))


async def _tp_hg_send_work_status_notification(body: str) -> None:
    if not WORK_STATUS_CHAT_ID:
        return
    try:
        await client.send_message(int(WORK_STATUS_CHAT_ID), str(body or ""))
    except Exception as e:
        try:
            print(f"telegram health WORK_STATUS notification error: {e!r}")
        except Exception:
            pass


def _tp_hg_stable_error_text(error_text: Any) -> str:
    """Strips volatile digits (FloodWait seconds, message ids, ...) out of a
    free-text error message so it can safely contribute to a dedup signature
    without defeating dedup on every retry. Also strips the Telethon
    "(caused by SomeRequest)" suffix (TPILOT HEALTH RECOVERY HYBRID-D
    CORRECTIVE 20260723b, finding L1) -- that suffix names whichever internal
    RPC happened to trigger the error and varies call-to-call for the exact
    same underlying restriction, so leaving it in defeated dedup between,
    e.g., a PeerFloodError raised by SendMessageRequest vs one raised by
    ImportContactsRequest."""
    t = str(error_text or "")
    t = re.sub(r"\(caused by[^)]*\)", "", t, flags=re.IGNORECASE)
    t = re.sub(r"\d+", "#", t)
    t = re.sub(r"\s+", " ", t).strip()
    return t[:80]


def _tp_hg_incident_signature(*, status: str, error_class: str, error_source: str, family: str, error_text: str = "") -> str:
    """Normalized, stable incident identity for storage.health_incident_* --
    manager key + status + restriction family + exception class + source
    category + normalized (digit-stripped, request-suffix-stripped) error
    text. Deliberately excludes volatile timestamps, peer/chat ids, raw
    message text, and stack addresses, so a repeated identical failure always
    maps to the SAME (manager_key, signature) row instead of opening a fresh
    incident every time.

    TPILOT HEALTH RECOVERY HYBRID-D CORRECTIVE 20260723b (finding M1):
    error_source is normalized to a coarse category (manual_mark vs auto)
    rather than used verbatim. The raw error_source is still preserved on the
    manager_telegram_health row itself for display/diagnostics -- only the
    SIGNATURE component is coarsened. Previously the exact source string
    (e.g. "client_auto_send" vs "periodic_self_check_get_dialogs" vs
    "manual_deepcheck_light_get_me") was part of the identity, so the SAME
    underlying restriction observed via a live send vs the periodic checker
    vs a deepcheck opened two (or three) independent incidents and alerted
    on each -- the fine-grained source is diagnostic information, not part
    of "is this the same unresolved problem"."""
    src_lower = str(error_source or "").strip().lower()
    source_cat = "manual_mark" if src_lower == "manual_mark" else "auto"
    cls = str(error_class or "").strip() or "Exception"
    stable_text = _tp_hg_stable_error_text(error_text)
    return f"{str(status or '').strip().lower()}:{family}:{cls}:{source_cat}:{stable_text}"


async def _tp_hg_bump_notify_meta(manager_key: str, signature: str) -> None:
    """Historical/compat-only bookkeeping on manager_telegram_health.
    notify_sent_at/notify_count/last_notify_signature are preserved for any
    existing panel/report code that reads them directly, but they are no
    longer the source of truth for the dedup DECISION -- that now lives in
    the durable storage.health_incidents CAS lifecycle (see
    _tp_hg_notify_if_needed). A failure here never blocks or re-triggers a
    notification by itself."""
    try:
        now = _tp_hg_now_iso()
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute("PRAGMA busy_timeout=5000;")
            await db.execute(
                """
                UPDATE manager_telegram_health
                SET notify_sent_at=?, notify_count=COALESCE(notify_count,0)+1, last_notify_signature=?, updated_at=?
                WHERE manager_key=?
                """,
                (now, signature, now, _tp_hg_norm_key(manager_key)),
            )
            await db.commit()
    except Exception:
        pass


async def _tp_hg_notify_if_needed(manager_key: str, new_row: Dict[str, Any], old_row: Dict[str, Any]) -> None:
    """TPILOT HEALTH RECOVERY HYBRID-D 20260723 (CORRECTIVE 20260723b, finding
    H1): alert dedup lives on the durable storage.health_incident_* lifecycle
    instead of comparing the current vs previous health_status column -- the
    old ad-hoc comparison re-fired on every OK<->LIMITED flap, bypassing the
    6h window entirely.

    The DELIVERY DECISION itself is made by an atomic SQL claim
    (storage.health_incident_claim_notify), not by a prior SELECT. The first
    corrective version of this function still raced: it read
    health_incident_get to decide "was this already open" and only called
    health_incident_mark_notified AFTER delivering (panel insert + Telegram
    send) -- so two callers (two asyncio tasks in this process, or two
    separate manager/controller OS processes sharing this SQLite file) could
    both observe "not yet notified" before either one's mark_notified ran,
    and both would deliver. health_incident_claim_notify closes that window:
    the CAS UPDATE that flips last_notified_at IS the decision, so only its
    winner ever reaches the delivery calls below.

    One unresolved incident per (manager_key, normalized signature); a
    genuinely different restriction (different family/class or manual vs
    auto) opens its own, independently-notified incident. On recovery, ALL
    of this manager's open incidents are resolved (finding M2) -- not only
    the one matching the last error state stored on manager_telegram_health
    -- so an incident orphaned by a later, different restriction overwriting
    that row is still closed instead of silently swallowing its own next
    recurrence for up to 6h.

    PEERFLOOD RECOVERY 20260812 (finding M5): PeerFlood now auto-recovers on
    an ordinary successful send (see _tp_hg_may_recover_on_send_success),
    which makes a fast LIMITED->OK->LIMITED flap possible in a way it never
    was before (PeerFlood used to be permanently sticky). Three additive
    guards keep that flap from spamming the owner:
    - the incident is always resolved (UI warning always clears), but the
      "✅ Telegram Health Recovery" message is only sent if at least one of
      the resolved incidents had actually been notified -- no point telling
      the owner something recovered when they were never told it broke.
    - a reopen within TP_HG_NOTIFY_REPEAT_SEC of its own resolution keeps the
      prior last_notified_at/reminder_count instead of resetting them, so
      the existing 6h claim_notify window survives the flap instead of
      re-firing an alert on every recurrence.
    - CORRECTIVE 20260812b (finding B-1, independent review): the guard above
      only dedups the PROBLEM alert -- any_was_notified stays True on every
      resolve of a preserved incident, so without a guard of its own the
      RECOVERY message would re-fire on every single flap cycle (measured:
      5 flap cycles -> 1 alert but 5 recoveries). The recovery message now
      gets its own claim_notify-backed 6h window, scoped to a companion
      "recovery:<signature>" key derived from the SAME signature identity as
      the problem alert (family/class/source/text) -- reusing the existing
      storage.health_incident_upsert_open/health_incident_claim_notify CAS
      primitives verbatim, no new storage function, no schema change. A
      different restriction (different family/class) gets an independent
      recovery-signature and is never suppressed by an unrelated incident's
      history. This companion row is intentionally never resolved (like the
      other non-Telegram-health signatures already sharing this table,
      e.g. "recovery_flap") -- it exists purely as a durable notify-clock.
    """
    key = _tp_hg_norm_key(manager_key)
    if not key:
        return
    new_status = str(new_row.get("health_status") or "").strip().lower()
    old_status = str((old_row or {}).get("health_status") or "").strip().lower()

    try:
        from storage import (
            ensure_health_incidents_table,
            health_incident_upsert_open,
            health_incident_claim_notify,
            health_incident_resolve_all_for_manager,
        )
    except Exception:
        # Cannot dedup safely without the durable API -- fail closed on
        # notifying (no spam) rather than fall back to the old ad-hoc compare.
        return
    try:
        ensure_health_incidents_table(TPILOT_DB_PATH)
    except Exception:
        pass

    # Recovery path: transitioned OUT of an unresolved LIMITED/BLOCKED.
    if new_status not in {TP_HG_STATUS_LIMITED, TP_HG_STATUS_BLOCKED} and old_status in {TP_HG_STATUS_LIMITED, TP_HG_STATUS_BLOCKED}:
        try:
            resolved_count, any_was_notified = health_incident_resolve_all_for_manager(key, db_path=TPILOT_DB_PATH, return_notified=True)
        except Exception:
            resolved_count, any_was_notified = 0, False
        # PEERFLOOD RECOVERY 20260812 (finding M5): the incident is resolved
        # unconditionally above (the UI warning clears either way) -- the
        # recovery message itself only goes out if the owner was actually
        # told about the problem in the first place (any_was_notified).
        if resolved_count > 0 and any_was_notified:
            # CORRECTIVE 20260812b (finding B-1): give the recovery message
            # its own 6h anti-flap window, keyed to the SAME identity
            # (family/class/source/text) the problem alert used -- otherwise
            # any_was_notified alone stays True on every resolve of a
            # preserved (see preserve_notify_within_sec below) incident and
            # a fast flap re-sends "✅ Telegram Health Recovery" every time.
            recovery_claim = None
            try:
                old_family = _tp_hg_restriction_family(status=old_status, error_class=str(old_row.get("error_class") or ""))
                old_signature = _tp_hg_incident_signature(
                    status=old_status,
                    error_class=str(old_row.get("error_class") or ""),
                    error_source=str(old_row.get("error_source") or ""),
                    family=old_family,
                    error_text=str(old_row.get("error_text") or ""),
                )
                recovery_signature = f"recovery:{old_signature}"
                health_incident_upsert_open(key, recovery_signature, db_path=TPILOT_DB_PATH)
                recovery_claim = health_incident_claim_notify(key, recovery_signature, repeat_after_sec=TP_HG_NOTIFY_REPEAT_SEC, db_path=TPILOT_DB_PATH)
            except Exception:
                recovery_claim = None
            if recovery_claim is not None:
                body = _tp_hg_build_recovery_alert_text(manager_key, old_row)
                await _tp_hg_insert_panel_notification("✅ Telegram Health Recovery", body)
                await _tp_hg_send_work_status_notification(body)
        return

    if new_status not in {TP_HG_STATUS_LIMITED, TP_HG_STATUS_BLOCKED}:
        return

    family = _tp_hg_restriction_family(status=new_status, error_class=str(new_row.get("error_class") or ""))
    signature = _tp_hg_incident_signature(
        status=new_status,
        error_class=str(new_row.get("error_class") or ""),
        error_source=str(new_row.get("error_source") or ""),
        family=family,
        error_text=str(new_row.get("error_text") or ""),
    )
    try:
        # PEERFLOOD RECOVERY 20260812 (finding M5): preserve_notify_within_sec
        # keeps last_notified_at/reminder_count across a reopen that follows
        # its own resolution within the same 6h repeat window, so a fast
        # flap does not defeat claim_notify's dedup below.
        health_incident_upsert_open(key, signature, db_path=TPILOT_DB_PATH, preserve_notify_within_sec=TP_HG_NOTIFY_REPEAT_SEC)
        claim = health_incident_claim_notify(key, signature, repeat_after_sec=TP_HG_NOTIFY_REPEAT_SEC, db_path=TPILOT_DB_PATH)
    except Exception:
        return
    if claim is None:
        # Nothing to claim right now: either another caller already owns
        # delivery for this incident, or the reminder window has not
        # elapsed yet. No delivery, no metadata write.
        return

    if claim == "open":
        body = _tp_hg_build_alert_text(manager_key, new_row)
    else:
        body = "🔁 Повтор\n\n" + _tp_hg_build_alert_text(manager_key, new_row)
    await _tp_hg_insert_panel_notification("🛡 Telegram Health Alert", body)
    await _tp_hg_send_work_status_notification(body)
    await _tp_hg_bump_notify_meta(key, signature)


async def _tp_hg_update_status(
    manager_key: str, *, status: str, error_class: str = "", error_text: str = "",
    error_source: str = "", action_required: str = "", allow_recover: bool = False,
    cooldown_seconds: int = 0,
) -> Dict[str, Any]:
    key = _tp_hg_norm_key(manager_key)
    if not key:
        return {}
    await _tp_hg_ensure_tables()
    status = str(status or TP_HG_STATUS_UNKNOWN).strip().lower()
    if status not in {TP_HG_STATUS_OK, TP_HG_STATUS_WARNING, TP_HG_STATUS_LIMITED, TP_HG_STATUS_BLOCKED, TP_HG_STATUS_UNKNOWN}:
        status = TP_HG_STATUS_UNKNOWN
    now = _tp_hg_now_iso()
    # TPILOT HEALTH RECOVERY HYBRID-D CORRECTIVE 20260723b: bounded retry on
    # transient SQLite lock contention. This entire block is a single
    # read-then-write attempt (re-reads old state fresh on each try), so
    # retrying it from scratch is safe -- unlike retrying a partial commit.
    # A raw "database is locked" here is already caught defensively by every
    # real production caller (_send_manager_private's except-block, the
    # periodic self-check loop, ...), so this does not change failure safety;
    # it only reduces how often a transient lock turns a health-state write
    # into a dropped/deferred one under concurrent access to the same file.
    new_d: Dict[str, Any] = {}
    old_d: Dict[str, Any] = {}
    for _attempt in range(3):
        try:
            async with aiosqlite.connect(TPILOT_DB_PATH) as db:
                db.row_factory = aiosqlite.Row
                await db.execute("PRAGMA busy_timeout=5000;")
                cur = await db.execute("SELECT * FROM manager_telegram_health WHERE manager_key=?", (key,))
                old = await cur.fetchone()
                old_d = dict(old) if old else {}
                old_status = str(old_d.get("health_status") or "").strip().lower()

                # TPILOT HEALTH RECOVERY HYBRID-D 20260723: sticky-incident downgrade
                # guard. An unresolved auto-detected LIMITED/BLOCKED incident is never
                # silently cleared by an ordinary OK/WARNING write (a successful send
                # to an existing dialog, or a passing get_me/get_dialogs light check --
                # neither proves permission to initiate a NEW dialog again). Only an
                # explicit allow_recover=True caller (manual reset, a genuine
                # FloodWait-cooldown retry success, or a deepcheck allowed to recover)
                # may downgrade it. This is what stops the OK<->LIMITED flapping that
                # made the 6h notify dedup window ineffective. A blocked downgrade only
                # touches observation fields (last_seen_at/last_check_at/updated_at) --
                # it never erases error_class/error_text/error_source/first_seen_at/
                # action_required/notify history/the manager key.
                if not allow_recover and status in {TP_HG_STATUS_OK, TP_HG_STATUS_WARNING} and old_status in {TP_HG_STATUS_LIMITED, TP_HG_STATUS_BLOCKED}:
                    await db.execute(
                        "UPDATE manager_telegram_health SET last_seen_at=?, last_check_at=?, updated_at=? WHERE manager_key=?",
                        (now, now, now, key),
                    )
                    await db.commit()
                    cur2 = await db.execute("SELECT * FROM manager_telegram_health WHERE manager_key=?", (key,))
                    unchanged = await cur2.fetchone()
                    return dict(unchanged) if unchanged else old_d

                first_seen = str(old_d.get("first_seen_at") or now)
                last_ok_at = str(old_d.get("last_ok_at") or "")
                cooldown_until = ""
                if status == TP_HG_STATUS_OK:
                    first_seen = ""
                    last_ok_at = now
                    error_class = ""
                    error_text = ""
                    error_source = str(error_source or "periodic_self_check")
                    action_required = ""
                if int(cooldown_seconds or 0) > 0:
                    cooldown_until = (_tp_utc_now().replace(microsecond=0) + timedelta(seconds=int(cooldown_seconds))).isoformat()
                sev = _tp_hg_severity(status)
                await db.execute(
                    """
                    INSERT INTO manager_telegram_health(
                        manager_key, health_status, severity, error_class, error_text, error_source,
                        first_seen_at, last_seen_at, last_ok_at, last_check_at, action_required, updated_at, cooldown_until
                    ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)
                    ON CONFLICT(manager_key) DO UPDATE SET
                        health_status=excluded.health_status,
                        severity=excluded.severity,
                        error_class=excluded.error_class,
                        error_text=excluded.error_text,
                        error_source=excluded.error_source,
                        first_seen_at=CASE WHEN excluded.health_status='ok' THEN '' WHEN COALESCE(manager_telegram_health.first_seen_at,'')='' OR manager_telegram_health.health_status<>excluded.health_status THEN excluded.first_seen_at ELSE manager_telegram_health.first_seen_at END,
                        last_seen_at=excluded.last_seen_at,
                        last_ok_at=CASE WHEN excluded.health_status='ok' THEN excluded.last_ok_at ELSE manager_telegram_health.last_ok_at END,
                        last_check_at=excluded.last_check_at,
                        action_required=excluded.action_required,
                        updated_at=excluded.updated_at,
                        cooldown_until=CASE WHEN excluded.health_status='ok' THEN '' WHEN excluded.cooldown_until<>'' THEN excluded.cooldown_until ELSE manager_telegram_health.cooldown_until END
                    """,
                    (key, status, sev, str(error_class or ""), str(error_text or "")[:2000], str(error_source or ""), first_seen, now, last_ok_at, now, str(action_required or ""), now, cooldown_until),
                )
                await db.commit()
                cur2 = await db.execute("SELECT * FROM manager_telegram_health WHERE manager_key=?", (key,))
                new = await cur2.fetchone()
                new_d = dict(new) if new else {"manager_key": key, "health_status": status}
            break
        except Exception as e:
            if "database is locked" not in str(e).lower() or _attempt == 2:
                raise
            await asyncio.sleep(0.05 * (_attempt + 1))
    await _tp_hg_notify_if_needed(key, new_d, old_d)
    return new_d


async def _tp_hg_set_from_exception(manager_key: str, exc: Any, *, source: str) -> Dict[str, Any]:
    d = _tp_hg_classify_exception(exc, source=source)
    # CORRECTION A 20260810: a single suspicious error (about an ARBITRARY
    # peer/operation, e.g. a SendMessageRequest to a lead) must never become
    # a durable "blocked"/banned status for the MANAGER'S OWN account
    # without an independent live get_me() verification first. Only runs
    # when about to declare BLOCKED (zero extra Telegram calls for the
    # WARNING/LIMITED/OK paths _tp_hg_classify_exception already returns
    # above), and only inside an actual manager runtime (never
    # CONTROLLER_MODE, never when MANAGER_RUNTIME_KEY is empty -- there is
    # no manager `client` to verify with in either case).
    if str(d.get("status") or "") == TP_HG_STATUS_BLOCKED and MANAGER_RUNTIME_KEY and not CONTROLLER_MODE:
        verify = await _tp_hg_verify_account_live(manager_key, source=source)
        vclass = str(verify.get("verify_class") or TP_HG_VERIFY_UNKNOWN)
        if vclass == TP_HG_VERIFY_ACCOUNT_LIVE:
            # Live-verified: the original exception was almost certainly
            # about the PEER, not the manager's own account. Never label
            # this "заблокирован".
            d = {
                "status": TP_HG_STATUS_WARNING,
                "error_class": "VerifiedLiveAfterSuspectedBlock",
                "error_text": (
                    f"Исходная ошибка ({d.get('error_class') or 'Exception'}: {d.get('error_text') or ''}) "
                    "выглядела как блокировка аккаунта, но live-проверка (get_me) подтвердила: "
                    "аккаунт менеджера жив. Вероятно, проблема на стороне собеседника."
                )[:2000],
                "error_source": str(d.get("error_source") or source),
                "action_required": "Проверка не требуется -- аккаунт подтверждён живым.",
                "seconds": 0,
            }
        elif vclass == TP_HG_VERIFY_IDENTITY_MISMATCH:
            d = {
                "status": TP_HG_STATUS_BLOCKED,
                "error_class": str(verify.get("error_class") or "telegram_identity_mismatch"),
                "error_text": str(verify.get("error_text") or "")[:2000],
                "error_source": source,
                "action_required": (
                    "Telegram id сессии не совпадает с реестром. Не переписывать identity "
                    "автоматически -- проверить аккаунт и при необходимости выполнить замену "
                    "через карточку менеджера."
                ),
                "seconds": 0,
            }
        elif vclass in (TP_HG_VERIFY_ACCOUNT_DEACTIVATED_CONFIRMED, TP_HG_VERIFY_ACCOUNT_BANNED_CONFIRMED):
            d = {
                "status": TP_HG_STATUS_BLOCKED,
                "error_class": str(verify.get("error_class") or d.get("error_class") or "Exception"),
                "error_text": str(verify.get("error_text") or d.get("error_text") or "")[:2000],
                "error_source": source,
                "action_required": (
                    "Подтверждено live-проверкой: аккаунт заблокирован/деактивирован Telegram. "
                    "Не перезапускать и не перелогинивать -- заменить аккаунт через карточку менеджер��."
                ),
                "seconds": 0,
            }
        elif vclass == TP_HG_VERIFY_AUTH_SESSION_PROBLEM:
            d = {
                "status": TP_HG_STATUS_BLOCKED,
                "error_class": str(verify.get("error_class") or d.get("error_class") or "Exception"),
                "error_text": str(verify.get("error_text") or d.get("error_text") or "")[:2000],
                "error_source": source,
                "action_required": "Нужен перезаход: сессия не авторизована. Перезайти через карточку менеджера (QR / номер / session / TData).",
                "seconds": 0,
            }
        else:
            # NETWORK_OR_PROXY_PROBLEM or UNKNOWN_VERIFY_FAILED -- fail
            # CLOSED. Verification itself could not confirm anything, so
            # this must never be written as a confirmed ban. Downgraded to
            # WARNING (not BLOCKED) so it does not trigger a false "banned"
            # alert/incident; the next suspicious error or the periodic
            # self-check will re-evaluate.
            d = {
                "status": TP_HG_STATUS_WARNING,
                "error_class": str(verify.get("error_class") or "VerificationInconclusive"),
                "error_text": (
                    f"Не удалось подтвердить состояние аккаунта live-проверкой ({vclass}). "
                    f"Исходная ошибка: {d.get('error_class') or 'Exception'}: {d.get('error_text') or ''}"
                )[:2000],
                "error_source": source,
                "action_required": "Не удалось подтвердить статус аккаунта (сеть/proxy?). Повторная проверка при следующей ошибке или самопроверке.",
                "seconds": 0,
            }
    return await _tp_hg_update_status(
        manager_key,
        status=str(d.get("status") or TP_HG_STATUS_WARNING),
        error_class=str(d.get("error_class") or ""),
        error_text=str(d.get("error_text") or ""),
        error_source=str(d.get("error_source") or source),
        action_required=str(d.get("action_required") or ""),
        cooldown_seconds=int(d.get("seconds") or 0),
    )


async def _tp_hg_periodic_self_check_loop() -> None:
    if CONTROLLER_MODE or not MANAGER_RUNTIME_KEY:
        return
    await asyncio.sleep(8.0)
    while True:
        try:
            await _tp_hg_run_self_check(source="periodic_self_check")
        except asyncio.CancelledError:
            return
        except Exception as e:
            try:
                print(f"telegram health periodic check error: {e!r}")
            except Exception:
                pass
        await asyncio.sleep(max(60, int(TP_HG_CHECK_INTERVAL_SEC or 1200)))


async def _tp_hg_list_rows(target: str = "all") -> List[Dict[str, Any]]:
    target_key = _tp_hg_norm_key(target or "all")
    await _tp_hg_ensure_tables()
    rows = []
    try:
        mgrs = await _manager_rows_for_reporting() if callable(globals().get("_manager_rows_for_reporting")) else []
    except Exception:
        mgrs = []
    if not mgrs:
        try:
            mgrs = await manager_list_rows(include_removed=False)
        except Exception:
            mgrs = []
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        for mgr in mgrs or []:
            key = _tp_hg_norm_key((mgr or {}).get("manager_key") or "")
            if not key:
                continue
            if target_key not in {"", "all"} and key != target_key:
                continue
            cur = await db.execute("SELECT * FROM manager_telegram_health WHERE manager_key=?", (key,))
            row = await cur.fetchone()
            d = dict(row) if row else {"manager_key": key, "health_status": TP_HG_STATUS_UNKNOWN, "last_check_at": "", "error_text": ""}
            d["manager_display_name"] = str((mgr or {}).get("display_name") or key)
            d["manager_username"] = str((mgr or {}).get("telegram_username") or "")
            rows.append(d)
    return rows


def _tp_hg_is_stale(row: Dict[str, Any]) -> bool:
    dt = _tp_hg_parse_iso(str(row.get("last_check_at") or ""))
    if not dt:
        return True
    try:
        return (_tp_utc_now().replace(microsecond=0) - dt).total_seconds() > TP_HG_UNKNOWN_AFTER_SEC
    except Exception:
        return True


def _tp_hg_manager_line(row: Dict[str, Any]) -> str:
    st = str(row.get("health_status") or TP_HG_STATUS_UNKNOWN).lower()
    if _tp_hg_is_stale(row) and st == TP_HG_STATUS_OK:
        st = TP_HG_STATUS_UNKNOWN
    name = str(row.get("manager_display_name") or row.get("manager_key") or "_").strip()
    username = str(row.get("manager_username") or "").strip()
    acc = f"{name} | @{username}" if username else name
    err = str(row.get("error_class") or "").strip()
    source = str(row.get("error_source") or "").strip()
    checked = str(row.get("last_check_at") or "").strip()
    try:
        checked_disp = _utc_iso_to_kyiv_dt(checked).strftime("%d.%m.%y %H:%M") if checked else "нет свежей проверки"
    except Exception:
        checked_disp = checked or "нет свежей проверки"
    suffix = f" | {err}" if err and st not in {TP_HG_STATUS_OK, TP_HG_STATUS_UNKNOWN} else ""
    source_s = f" | {source}" if source and st not in {TP_HG_STATUS_OK, TP_HG_STATUS_UNKNOWN} else ""
    return f"{_tp_hg_status_label(st)} | {acc} | {checked_disp}{suffix}{source_s}"


async def _tp_hg_format_status(target: str = "all") -> str:
    rows = await _tp_hg_list_rows(target)
    title = "🛡 Telegram Health"
    lines = [title, ""]
    if not rows:
        return title + "\n\nМенеджеры не найдены."
    for row in rows:
        lines.append(_tp_hg_manager_line(row))
        st = str(row.get("health_status") or TP_HG_STATUS_UNKNOWN).lower()
        if target != "all" and st not in {TP_HG_STATUS_OK, TP_HG_STATUS_UNKNOWN}:
            txt = str(row.get("error_text") or "").strip()
            action = str(row.get("action_required") or "").strip()
            if txt:
                lines.append(f"Ошибка: {txt}")
            if action:
                lines.append(f"Что делать: {action}")
        lines.append("")
    lines.append("Уведомления отправляются только по 🟠 LIMITED и 🔴 BLOCKED.")
    return "\n".join(lines).rstrip()


async def _tp_hg_reset(target: str) -> str:
    key = _tp_hg_norm_key(target or "")
    if not key:
        return "Формат: /tghealth reset <manager_key>"
    await _tp_hg_update_status(key, status=TP_HG_STATUS_UNKNOWN, error_source="manual_reset", action_required="", allow_recover=True)
    return f"✅ Telegram Health сброшен для {key}. Следующая проверка обновит статус."


async def _tp_hg_check_command(target: str, *, user_id: int = 0) -> str:
    key = _tp_hg_norm_key(target or "all")
    if key == "all":
        rows = await _manager_rows_for_reporting() if callable(globals().get("_manager_rows_for_reporting")) else []
        keys = [_tp_hg_norm_key(r.get("manager_key") or "") for r in rows if _tp_hg_norm_key(r.get("manager_key") or "")]
        if not keys:
            return "Менеджеры не найдены."
        tasks = [_tp_hg_queue_check_for_manager(k, user_id=user_id, timeout_sec=45) for k in keys]
        results = await asyncio.gather(*tasks, return_exceptions=True)
        lines = ["🔄 Telegram Health проверка запрошена", ""]
        for k, res in zip(keys, results):
            if isinstance(res, Exception):
                lines.append(f"{k}: ⚠️ {res!r}")
            else:
                ok, text = res
                lines.append(f"{k}: {'✅' if ok else '⚠️'} {text}")
        lines.extend(["", await _tp_hg_format_status("all")])
        return "\n".join(lines).rstrip()
    ok, text = await _tp_hg_queue_check_for_manager(key, user_id=user_id, timeout_sec=45)
    status_text = await _tp_hg_format_status(key)
    return (f"{'✅' if ok else '⚠️'} {text}\n\n" + status_text).rstrip()


async def _handle_ai_stat_command(event: events.NewMessage.Event) -> bool:  # type: ignore[override]
    try:
        if CONTROLLER_MODE and int(event.chat_id or 0) == int(AI_STAT_CHAT_ID or 0):
            cmd, args = _parse_cmd((event.raw_text or "").strip())
            if cmd == "/tghealth":
                await client.send_message(event.chat_id, await _tp_hg_handle_command(args, user_id=int(event.sender_id or 0)))
                return True
    except Exception as e:
        try:
            await client.send_message(event.chat_id, f"Ошибка /tghealth: {e!r}")
            return True
        except Exception:
            pass
    if callable(_TP_HG_ORIG_HANDLE_AI_STAT):
        return await _TP_HG_ORIG_HANDLE_AI_STAT(event)
    return False


async def _panel_execute_command_text(command_text: str, *, requested_by: int = 0, source_chat_id: int = 0, response_chat_id: int = 0):  # type: ignore[override]
    text = str(command_text or "").strip()
    cmd, args = _parse_cmd(text)
    if cmd == "/tghealth":
        return {"ok": True, "result_text": await _tp_hg_handle_command(args, user_id=requested_by)}
    if callable(_TP_HG_ORIG_PANEL_EXEC):
        try:
            return await _TP_HG_ORIG_PANEL_EXEC(command_text, requested_by=requested_by, source_chat_id=source_chat_id, response_chat_id=response_chat_id)
        except TypeError:
            try:
                return await _TP_HG_ORIG_PANEL_EXEC(command_text, requested_by=requested_by, source_chat_id=source_chat_id)
            except TypeError:
                try:
                    return await _TP_HG_ORIG_PANEL_EXEC(command_text, requested_by=requested_by)
                except TypeError:
                    return await _TP_HG_ORIG_PANEL_EXEC(command_text)
    return {"ok": False, "error_text": f"Команда не поддерживается: {cmd or text}"}


async def main() -> None:  # type: ignore[override]
    try:
        await _tp_hg_ensure_tables()
    except Exception as e:
        print(f"telegram health init table error: {e!r}")
    if MANAGER_RUNTIME_KEY and not CONTROLLER_MODE:
        try:
            client.loop.create_task(_tp_hg_periodic_self_check_loop())
        except Exception as e:
            print(f"telegram health task start error: {e!r}")
    if callable(_TP_HG_ORIG_MAIN):
        await _TP_HG_ORIG_MAIN()
    else:
        raise RuntimeError("Original main() is not available after Telegram Health Guard patch")

