# --- TPILOT TELEGRAM HEALTH GUARD V1.2 HOTFIX 20260514 START ---
# Hotfix:
# - unique nonce for /tghealth check all
# - manual mark limited/blocked
# - stronger get_me flags check: deleted/restricted/restriction_reason
# - honest API limitation note for UI-only Telegram freezes

import uuid as _tp_hg_uuid  # noqa: E402

_TP_HG_V12_VERSION = "telegram_health_guard_v1_2_hotfix_20260514"


def _tp_hg_me_flags(me: Any) -> Dict[str, Any]:
    flags: Dict[str, Any] = {}
    for attr in ("deleted", "restricted", "verified", "scam", "fake", "bot"):
        try:
            flags[attr] = getattr(me, attr, None)
        except Exception:
            pass
    try:
        rr = getattr(me, "restriction_reason", None)
        if rr:
            flags["restriction_reason"] = repr(rr)
    except Exception:
        pass
    return flags


def _tp_hg_me_health_problem(me: Any, *, source: str = "get_me") -> Optional[Dict[str, Any]]:
    """Detect account health flags that Telegram exposes through API.

    Telegram may show a freeze/ban in the official app UI while get_me still works.
    Such UI-only states are detected later by real send errors or manual mark.
    """
    flags = _tp_hg_me_flags(me)
    try:
        if bool(flags.get("deleted")):
            return {
                "status": TP_HG_STATUS_BLOCKED,
                "error_class": "AccountDeletedFlag",
                "error_text": "Telegram API returned get_me.deleted=True. Аккаунт выглядит удалённым или недоступным.",
                "error_source": str(source or "get_me"),
                "action_required": "Остановить трафик на аккаунт. Проверить аккаунт вручную. Если session слетела или аккаунт удалён, переподключить/заменить аккаунт.",
            }
    except Exception:
        pass
    try:
        restricted = bool(flags.get("restricted")) or bool(flags.get("restriction_reason"))
        if restricted:
            reason = str(flags.get("restriction_reason") or "Telegram API returned restricted=True")
            return {
                "status": TP_HG_STATUS_LIMITED,
                "error_class": "AccountRestrictedFlag",
                "error_text": reason[:2000],
                "error_source": str(source or "get_me"),
                "action_required": "Telegram показывает ограничение аккаунта. Временно остановить трафик на этот аккаунт и проверить аккаунт вручную.",
            }
    except Exception:
        pass
    return None

# --- TPILOT TELEGRAM HEALTH GUARD V1.2 HOTFIX 20260514 END ---

# --- TPILOT TELEGRAM HEALTH GUARD V1.3 SAFE HOTFIX 20260514 START ---
# Safe hotfix goals:
# - NO automatic Saved Messages self-send probe.
# - periodic /tghealth check stays lightweight: get_me + get_dialogs(limit=1), no messages.
# - manual /tghealth deepcheck <manager> performs one Saved Messages probe only on explicit admin request.
# - /tghealth mark works from PanelBot, AI_STAT_CHAT_ID, WORK_STATUS_CHAT_ID, and private controller chat after MANAGER AUTH.
# - manual LIMITED/BLOCKED mark is not cleared by ordinary OK checks; use /tghealth reset <manager>.
# - notifications only for LIMITED and BLOCKED, no auto-stop.

import uuid as _tp_hg_safe_uuid  # noqa: E402

_TP_HG_V13_SAFE_VERSION = "telegram_health_guard_v1_3_safe_hotfix_20260514"
_TP_HG_V13_SAFE_ORIG_HANDLE_AI_STAT = globals().get("_handle_ai_stat_command")
_TP_HG_V13_SAFE_ORIG_HANDLE_MANAGER_PLAINTEXT = globals().get("_handle_manager_plaintext")
_TP_HG_V13_SAFE_ORIG_PANEL_EXEC = globals().get("_panel_execute_command_text")


def _tp_hg_row_sync(manager_key: str) -> Dict[str, Any]:
    key = _tp_hg_norm_key(manager_key or "")
    if not key:
        return {}
    try:
        con = _tp_hg_connect_sync()
        try:
            ens = globals().get("_tp_hg_ensure_tables_sync")
            if callable(ens):
                try:
                    ens()
                except Exception:
                    pass
            row = con.execute("SELECT * FROM manager_telegram_health WHERE manager_key=? LIMIT 1", (key,)).fetchone()
            return dict(row) if row else {}
        finally:
            con.close()
    except Exception:
        return {}


async def _tp_hg_row(manager_key: str) -> Dict[str, Any]:
    key = _tp_hg_norm_key(manager_key or "")
    if not key:
        return {}
    try:
        await _tp_hg_ensure_tables()
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute("SELECT * FROM manager_telegram_health WHERE manager_key=? LIMIT 1", (key,))
            row = await cur.fetchone()
            return dict(row) if row else {}
    except Exception:
        return {}


async def _tp_hg_manual_override_active(manager_key: str) -> bool:
    row = await _tp_hg_row(manager_key)
    st = str(row.get("health_status") or "").strip().lower()
    src = str(row.get("error_source") or "").strip().lower()
    return st in {TP_HG_STATUS_LIMITED, TP_HG_STATUS_BLOCKED} and src == "manual_mark"


_TP_HG_GATE_DENY_BLOCKED = "blocked"
_TP_HG_GATE_DENY_NEW_DIALOG_LIMITED = "peerflood_limited_new_dialog"  # legacy compatibility value
_TP_HG_GATE_DENY_LIMITED_RESTRICTION = "limited_restriction_active"  # legacy compatibility value, no longer returned (PEERFLOOD RECOVERY 20260812)
_TP_HG_GATE_DENY_FLOODWAIT_COOLDOWN = "floodwait_cooldown_active"
_TP_HG_GATE_DENY_MANUAL_MARK = "manual_mark_active"
_TP_HG_GATE_ALLOW_LIMITED_PROBE = "limited_probe_passthrough"


async def _tp_hg_send_allowed(manager_key: str, *, new_dialog: bool, recovery_probe: bool = False) -> Tuple[bool, str]:
    """TPILOT HEALTH RECOVERY HYBRID-D 20260723 (PEERFLOOD RECOVERY CORRECTIVE
    20260812): central automatic-send health gate. Read-only -- never writes a
    health row, never sends a Telegram Health alert, never touches
    notify_count. An explicit recovery/deepcheck probe bypasses entirely
    (recovery_probe=True); it never goes through this gate to begin with
    (deepcheck's Saved Messages probe calls client.send_message directly, not
    through _send_manager_private).

    Decision table:
      OK / WARNING / UNKNOWN / no row  -> allow.
      BLOCKED                          -> deny (every ordinary automatic send).
      LIMITED + manual mark (error_source == 'manual_mark'):
        deny everything, same as BLOCKED -- the admin explicitly stopped this
        manager and only /tghealth reset (or a genuinely new auto-detected
        classification) may change that, never an ordinary send.
      LIMITED + floodwait family:
        cooldown_until still in the future -> deny.
        cooldown elapsed (or unset)        -> allow (one controlled retry).
      LIMITED + any other auto-detected restriction family (PeerFlood,
      spam/restriction signals, etc.): PEERFLOOD RECOVERY 20260812 -- the old
      HYBRID-D behavior denied every ordinary send here, which made recovery
      unreachable (a real send can never succeed if it is never attempted,
      so allow_recover in _tp_hg_may_recover_on_send_success could never
      fire). Now allow -- the caller gets exactly one controlled real-send
      attempt per tick (owner-approved "skip + one probe per tick" mode);
      the caller's own post-failure fail_kind handling (see
      _send_manager_private_ex) stops the tick after the first restriction
      failure instead of hammering Telegram. This never applies to BLOCKED or
      manual_mark, which stay denied above.
    """
    if recovery_probe:
        return True, "recovery_probe"
    key = _tp_hg_norm_key(manager_key)
    if not key:
        return True, "no_manager_key"
    row = await _tp_hg_row(key)
    status = str(row.get("health_status") or "").strip().lower()
    if status == TP_HG_STATUS_BLOCKED:
        return False, _TP_HG_GATE_DENY_BLOCKED
    if status != TP_HG_STATUS_LIMITED:
        return True, "status_ok"
    if str(row.get("error_source") or "").strip().lower() == "manual_mark":
        return False, _TP_HG_GATE_DENY_MANUAL_MARK
    family = _tp_hg_restriction_family(status=status, error_class=str(row.get("error_class") or ""))
    if family == _TP_HG_FAMILY_FLOODWAIT:
        cooldown_until = _tp_hg_parse_iso(str(row.get("cooldown_until") or ""))
        if cooldown_until and _tp_utc_now().replace(microsecond=0) < cooldown_until:
            return False, _TP_HG_GATE_DENY_FLOODWAIT_COOLDOWN
        return True, "floodwait_cooldown_elapsed"
    # Sticky non-FloodWait restrictions, including PeerFlood: no longer a
    # permanent internal deny (PEERFLOOD RECOVERY 20260812) -- allow one
    # controlled real-send attempt per tick instead. See docstring above.
    return True, _TP_HG_GATE_ALLOW_LIMITED_PROBE


async def _tp_hg_may_recover_on_send_success(manager_key: str) -> bool:
    """Whether an ORDINARY successful automatic send may clear the manager's
    currently unresolved health incident (allow_recover for the OK write that
    follows a successful client.send_message in _send_manager_private).

    PEERFLOOD RECOVERY 20260812: PeerFlood now recovers the same way
    FloodWait always has -- a genuinely successful real-send IS the evidence
    the restriction lifted; there is no stronger proof available (Saved
    Messages/get_me/get_dialogs never prove a new-dialog PeerFlood cleared,
    which is why deepcheck still refuses to recover it -- see
    _tp_hg_run_deep_self_check). BLOCKED and an explicit manual mark never
    auto-recover from an ordinary send; only /tghealth reset (or, for
    BLOCKED, a genuine re-classification) clears those."""
    row = await _tp_hg_row(manager_key)
    status = str(row.get("health_status") or "").strip().lower()
    if status not in {TP_HG_STATUS_LIMITED, TP_HG_STATUS_BLOCKED}:
        return True
    if str(row.get("error_source") or "").strip().lower() == "manual_mark":
        return False
    if status == TP_HG_STATUS_BLOCKED:
        return False
    family = _tp_hg_restriction_family(status=status, error_class=str(row.get("error_class") or ""))
    return family in {_TP_HG_FAMILY_FLOODWAIT, _TP_HG_FAMILY_PEERFLOOD}


def _tp_hg_manual_override_active_sync(manager_key: str) -> bool:
    row = _tp_hg_row_sync(manager_key)
    st = str(row.get("health_status") or "").strip().lower()
    src = str(row.get("error_source") or "").strip().lower()
    return st in {TP_HG_STATUS_LIMITED, TP_HG_STATUS_BLOCKED} and src == "manual_mark"


def _tp_hg_promote_self_send_classification(exc: Any, classified: Dict[str, Any], *, source: str) -> Dict[str, Any]:
    d = dict(classified or {})
    st = str(d.get("status") or TP_HG_STATUS_WARNING).strip().lower()
    err = str(d.get("error_text") or _tp_hg_error_text(exc))
    low = (str(getattr(getattr(exc, "__class__", None), "__name__", "")) + " " + str(exc or "")).lower()

    temporary = any(x in low for x in [
        "timeout", "timed out", "connection", "network", "proxy", "disconnected",
        "cannot send requests while disconnected", "server closed", "transport", "connection reset", "connectionerror",
    ])
    if st == TP_HG_STATUS_BLOCKED:
        d["error_source"] = str(source or d.get("error_source") or "manual_deepcheck_self_send")
        return d
    if "floodwait" in low or "flood wait" in low or "wait of" in low:
        d["error_source"] = str(source or d.get("error_source") or "manual_deepcheck_self_send")
        return d
    if temporary:
        d["status"] = TP_HG_STATUS_WARNING
        d["error_source"] = str(source or "manual_deepcheck_self_send")
        d["action_required"] = "Временная ошибка связи/proxy во время ручной deep-проверки. Наблюдать, уведомление не отправляется."
        return d

    if st not in {TP_HG_STATUS_LIMITED, TP_HG_STATUS_BLOCKED}:
        d["status"] = TP_HG_STATUS_LIMITED
        d["error_class"] = str(d.get("error_class") or getattr(getattr(exc, "__class__", None), "__name__", "SelfSendError"))
        d["error_text"] = err
        d["action_required"] = "Аккаунт не смог отправить тестовое сообщение в собственное Избранное. Временно остановить трафик на этот аккаунт и проверить его вручную в Telegram."
    d["error_source"] = str(source or "manual_deepcheck_self_send")
    return d


async def _tp_hg_saved_messages_send_probe(*, source: str = "manual_deepcheck_self_send") -> None:
    """Manual deep probe only.

    Sends one small message to Saved Messages of the same account and deletes it.
    This function is NOT used by periodic checks and NOT used by /tghealth check.
    It runs only through /tghealth deepcheck <manager>.
    """
    key = _tp_hg_norm_key(MANAGER_RUNTIME_KEY or "manager")
    marker = f"TPilot manual health deepcheck {key} {_tp_hg_now_iso()}"
    msg = await client.send_message("me", marker)
    try:
        await msg.delete()
    except Exception:
        pass


async def _tp_hg_set_from_self_send_exception(manager_key: str, exc: Any, *, source: str) -> Dict[str, Any]:
    classified = _tp_hg_classify_exception(exc, source=source)
    d = _tp_hg_promote_self_send_classification(exc, classified, source=source)
    return await _tp_hg_update_status(
        manager_key,
        status=str(d.get("status") or TP_HG_STATUS_LIMITED),
        error_class=str(d.get("error_class") or "SelfSendError"),
        error_text=str(d.get("error_text") or _tp_hg_error_text(exc)),
        error_source=str(d.get("error_source") or source),
        action_required=str(d.get("action_required") or "Проверить аккаунт вручную."),
        cooldown_seconds=int(d.get("seconds") or 0),
    )


# --- TPILOT IDENTITY RECONCILE 20260809 START ---
# Startup (see manager_sync_telegram_profile_in_db call inside main(), ~line 5330)
# already refreshes a manager's Telegram identity in the CENTRAL managers row exactly
# ONCE -- at process start. A Telegram rename/username change made while the manager
# has been running for days was never picked up again (confirmed production case:
# manager_key=ira ended up with a stale display_name/first_name/blank username long
# after the live session itself already knew the current identity). This function is
# the periodic counterpart, piggybacked on the existing 20-min health self-check loop
# (_tp_hg_periodic_self_check_loop) -- see the single call site inside the ACTIVE
# _tp_hg_run_self_check below. It is intentionally standalone/top-level so it can be
# extracted and unit-tested via AST the same way tools/*_selftest.py already does for
# other main.py functions (see tools/identity_sync_ira_selftest.py).
#
# Unlike the startup guard (which raises SystemExit on an identity mismatch -- a hard
# auth gate), this is a periodic COSMETIC profile sync: it must never kill the
# runtime, never touch tg_user_id on a mismatch, and only ever writes through the
# SAME canonical storage.manager_sync_telegram_profile_in_db(...) every other auth
# path already uses -- no second SQL UPDATE implementation. It always passes an
# EXPLICIT db_path (the caller must pass TPILOT_DB_PATH) because inside a manager
# runtime process storage.DB_PATH points at the PER-MANAGER database (main.py
# overwrites os.environ["DB_PATH"] before storage is imported), never the central
# registry -- relying on the module-level default would silently write to the wrong
# database.
async def _identity_reconcile_from_me(me, *, manager_key: str, db_path: str) -> Dict[str, Any]:
    key = registry_normalize_manager_key(manager_key or "")
    if not key or me is None:
        return {"action": "skipped", "reason": "empty manager_key or me"}

    live_tg_id = int(getattr(me, "id", 0) or 0)
    if not live_tg_id:
        return {"action": "skipped", "reason": "me.id missing"}

    row = get_manager_row_from_db_sync(db_path, key) or {}
    stored_tg_id = int(row.get("tg_user_id") or 0)
    if stored_tg_id and stored_tg_id != live_tg_id:
        # Never write, never raise, never touch the runtime -- just report the
        # divergence. A mismatch here means the registry and the live session
        # disagree about which Telegram account this manager is; the startup guard
        # (main(), ~line 5300) is the actual auth gate for that condition and would
        # already have refused to start the runtime were this a fresh boot -- if we
        # get here, something changed the registry (or a different session got
        # attached) AFTER a successful start, which this cosmetic sync has no
        # business resolving on its own.
        print(f"[identity-sync] manager={key} identity_mismatch stored_tg_user_id={stored_tg_id} live_tg_user_id={live_tg_id} -- not writing")
        return {"action": "identity_mismatch", "stored_tg_user_id": stored_tg_id, "live_tg_user_id": live_tg_id}

    live_username = str(getattr(me, "username", None) or "")
    live_first_name = str(getattr(me, "first_name", None) or "")
    live_last_name = str(getattr(me, "last_name", None) or "")

    stored_username = str(row.get("telegram_username") or "")
    stored_first_name = str(row.get("first_name") or "")
    stored_last_name = str(row.get("last_name") or "")

    if (
        stored_tg_id == live_tg_id
        and stored_username == live_username
        and stored_first_name == live_first_name
        and stored_last_name == live_last_name
    ):
        # Idempotent no-op: not even an updated_at bump, so a healthy manager
        # running for weeks doesn't churn its own managers row every 20 minutes.
        return {"action": "noop"}

    await manager_sync_telegram_profile_in_db(
        db_path,
        key,
        tg_user_id=live_tg_id,
        telegram_username=live_username,
        first_name=live_first_name,
        last_name=live_last_name,
    )
    print(f"[identity-sync] manager={key} reconciled tg_user_id={live_tg_id} username={live_username or '_'}")
    return {"action": "synced", "tg_user_id": live_tg_id, "telegram_username": live_username}
# --- TPILOT IDENTITY RECONCILE 20260809 END ---


async def _tp_hg_run_self_check(*, source: str = "periodic_self_check") -> Dict[str, Any]:  # type: ignore[override]
    """Lightweight manager self-check.

    Safe plan check: connection + get_me + exposed API flags + get_dialogs(limit=1).
    No messages, no Saved Messages probe, no client messages, no mass scans, no auto-stop.

    TPILOT HEALTH RECOVERY HYBRID-D 20260723: an unresolved auto-detected
    LIMITED/BLOCKED incident (e.g. PeerFlood) is NOT cleared just because this
    light check succeeds -- get_me/get_dialogs only proves connectivity/read
    access, never permission to initiate a new dialog. The returned "status"
    reflects the PERSISTED (possibly still-sticky) row; "live_probe_ok"
    separately reflects whether THIS get_me/get_dialogs attempt itself
    succeeded just now, independent of the persisted status -- /tghealth
    deepcheck uses live_probe_ok (not status) to decide whether it is worth
    proceeding to its own stronger self-send probe.
    Manual LIMITED/BLOCKED marks stay until /tghealth reset.
    """
    if not MANAGER_RUNTIME_KEY:
        return {"ok": False, "status": TP_HG_STATUS_UNKNOWN, "text": "manager runtime key is empty", "live_probe_ok": False}
    key = _tp_hg_norm_key(MANAGER_RUNTIME_KEY)
    try:
        if await _tp_hg_manual_override_active(key):
            row = await _tp_hg_row(key)
            return {"ok": False, "status": str(row.get("health_status") or TP_HG_STATUS_BLOCKED), "text": str(row.get("error_text") or "manual mark active"), "row": row, "live_probe_ok": False}

        if not client.is_connected():
            try:
                await client.connect()
            except Exception:
                pass
        me = await client.get_me()
        if not me:
            raise RuntimeError("get_me returned empty result")

        # TPILOT IDENTITY RECONCILE 20260809: piggyback on the `me` we already have
        # from the get_me() call two lines above -- zero additional Telegram network
        # calls. Never fatal: any error here must not affect the health self-check
        # result or the runtime. Only runs for actual manager runtimes (not the
        # controller, which never reaches this function with a real MANAGER_RUNTIME_KEY
        # -- see the guard at the top of this function).
        try:
            await _identity_reconcile_from_me(me, manager_key=MANAGER_RUNTIME_KEY, db_path=TPILOT_DB_PATH)
        except Exception as _idsync_exc:
            print(f"[identity-sync] periodic reconcile error manager={MANAGER_RUNTIME_KEY!r}: {_idsync_exc!r}")

        problem_fn = globals().get("_tp_hg_me_health_problem")
        if callable(problem_fn):
            try:
                problem = problem_fn(me, source=f"{source}_get_me")
            except TypeError:
                problem = problem_fn(me)
            if problem:
                row = await _tp_hg_update_status(
                    key,
                    status=str(problem.get("status") or TP_HG_STATUS_WARNING),
                    error_class=str(problem.get("error_class") or "AccountFlag"),
                    error_text=str(problem.get("error_text") or ""),
                    error_source=str(problem.get("error_source") or f"{source}_get_me"),
                    action_required=str(problem.get("action_required") or "Проверить аккаунт вручную."),
                )
                return {"ok": False, "status": row.get("health_status"), "text": str(row.get("error_text") or "account flag problem"), "row": row, "live_probe_ok": False}

        try:
            await client.get_dialogs(limit=1)
        except Exception as e:
            classified = _tp_hg_classify_exception(e, source=f"{source}_get_dialogs")
            st = str(classified.get("status") or TP_HG_STATUS_WARNING)
            if st in {TP_HG_STATUS_BLOCKED, TP_HG_STATUS_LIMITED}:
                row = await _tp_hg_set_from_exception(key, e, source=f"{source}_get_dialogs")
                return {"ok": False, "status": row.get("health_status"), "text": str(row.get("error_text") or repr(e)), "row": row, "live_probe_ok": False}
            row = await _tp_hg_update_status(
                key,
                status=TP_HG_STATUS_WARNING,
                error_class=str(classified.get("error_class") or "DialogCheckError"),
                error_text=str(classified.get("error_text") or repr(e)),
                error_source=f"{source}_get_dialogs",
                action_required="Лёгкая проверка диалогов дала ошибку. Наблюдать, уведомление не отпра��ляется.",
                cooldown_seconds=int(classified.get("seconds") or 0),
            )
            return {"ok": True, "status": row.get("health_status"), "text": str(row.get("error_text") or "warning"), "row": row, "live_probe_ok": True}

        row = await _tp_hg_update_status(key, status=TP_HG_STATUS_OK, error_source=source, allow_recover=False)
        actual_status = str(row.get("health_status") or TP_HG_STATUS_OK)
        return {
            "ok": actual_status not in {TP_HG_STATUS_LIMITED, TP_HG_STATUS_BLOCKED},
            "status": actual_status,
            "text": "OK" if actual_status == TP_HG_STATUS_OK else "Проверка связи прошла, но ранее обнаруженное ограничение остаётся активным (нужна ручная проверка).",
            "row": row,
            "live_probe_ok": True,
        }
    except Exception as e:
        row = await _tp_hg_set_from_exception(key, e, source=f"{source}_get_me")
        return {"ok": False, "status": row.get("health_status"), "text": str(row.get("error_text") or repr(e)), "row": row, "live_probe_ok": False}


async def _tp_hg_run_deep_self_check(*, source: str = "manual_deepcheck") -> Dict[str, Any]:
    """Manual deepcheck for one manager.

    This is the only place where a Saved Messages probe is used.
    It should be called only by explicit admin command /tghealth deepcheck <manager>.

    TPILOT HEALTH RECOVERY HYBRID-D 20260723 (PEERFLOOD RECOVERY CORRECTIVE
    20260812): gating now uses the light check's live_probe_ok (did
    get_me/get_dialogs succeed just now?) instead of its persisted status, so
    deepcheck can still run its self-send probe on an account whose status
    remains sticky-LIMITED from a past incident. A successful Saved Messages
    send never proves PeerFlood (new-peer) recovery -- Saved Messages is
    always in your own dialog list and is exempt from PeerFlood -- so an
    unresolved PeerFlood-family LIMITED incident stays LIMITED after a
    successful probe. Unlike before 20260812, this is no longer reported as
    requiring manual intervention: ordinary business sends are not stopped by
    LIMITED+PeerFlood (see _tp_hg_send_allowed), and the status clears itself
    automatically the moment a real business send next succeeds -- no
    /tghealth reset needed. Other restriction families (e.g. BLOCKED from a
    stale auth/session flag) may still recover here, same as before -- a
    genuine send success is real evidence the session itself is alive.
    """
    if not MANAGER_RUNTIME_KEY:
        return {"ok": False, "status": TP_HG_STATUS_UNKNOWN, "text": "manager runtime key is empty"}
    key = _tp_hg_norm_key(MANAGER_RUNTIME_KEY)
    try:
        light = await _tp_hg_run_self_check(source=f"{source}_light")
        if not light.get("live_probe_ok", False) and not await _tp_hg_manual_override_active(key):
            return light
        if await _tp_hg_manual_override_active(key):
            row = await _tp_hg_row(key)
            return {"ok": False, "status": str(row.get("health_status") or TP_HG_STATUS_BLOCKED), "text": str(row.get("error_text") or "manual mark active"), "row": row}

        try:
            await _tp_hg_saved_messages_send_probe(source=f"{source}_self_send")
        except Exception as e:
            row = await _tp_hg_set_from_self_send_exception(key, e, source=f"{source}_self_send")
            st = str(row.get("health_status") or TP_HG_STATUS_UNKNOWN)
            return {"ok": st in {TP_HG_STATUS_OK, TP_HG_STATUS_WARNING}, "status": st, "text": str(row.get("error_text") or repr(e)), "row": row}

        pre_row = await _tp_hg_row(key)
        pre_status = str(pre_row.get("health_status") or "").strip().lower()
        pre_family = _tp_hg_restriction_family(status=pre_status, error_class=str(pre_row.get("error_class") or ""))
        if pre_status == TP_HG_STATUS_LIMITED and pre_family == _TP_HG_FAMILY_PEERFLOOD:
            return {
                "ok": False,
                "status": pre_status,
                "text": "Отправка в Избранное прошла, но это не доказывает снятие ограничения Telegram на инициацию новых диалогов (PeerFlood) -- Избранное всегда исключение из PeerFlood. Рабочие отправки менеджера НЕ остановлены: рабочий цикл продолжает контролируемые реальные попытки, и статус снимется автоматически после первой успешной рабочей отправки. Ручной /tghealth reset не требуется.",
                "row": pre_row,
            }

        row = await _tp_hg_update_status(key, status=TP_HG_STATUS_OK, error_source=source, allow_recover=True)
        return {"ok": True, "status": TP_HG_STATUS_OK, "text": "OK. Ручная deep-проверка отправки в Избранное прошла.", "row": row}
    except Exception as e:
        row = await _tp_hg_set_from_exception(key, e, source=f"{source}_get_me")
        return {"ok": False, "status": row.get("health_status"), "text": str(row.get("error_text") or repr(e)), "row": row}


async def _send_manager_private_ex(chat_id: int, text: str, *, human_delay: bool = False, after_first_delay: bool = False, new_dialog: bool = True) -> Tuple[bool, str]:
    """Send client message and classify Telegram account restrictions on failure.
    PEERFLOOD RECOVERY 20260812: extended-result variant of
    _send_manager_private (which is now a thin bool wrapper around this) --
    callers that must distinguish a Telegram restriction failure from an
    ordinary send failure (post_manual_followup, profile reminders) use this
    directly. The send body itself is carried over verbatim from the prior
    single-def _send_manager_private.

    Manual LIMITED/BLOCKED marks are not cleared automatically by a later OK send.
    Use /tghealth reset <manager_key> to clear a manual mark.

    TPILOT HEALTH RECOVERY HYBRID-D 20260723:
    - new_dialog tells the central health send-gate (_tp_hg_send_allowed) whether
      this is the FIRST message the manager account itself has ever sent to this
      chat_id (new_dialog=True, e.g. the initial greeting/night-notice to a brand
      new lead) or a reply/follow-up in a dialog the account has already sent
      into before (new_dialog=False, e.g. a reminder, a questionnaire follow-up,
      an old-client notice). Callers must classify this from state they already
      hold (question_sent / existing_same_manager_chat / candidate source table)
      -- it is never guessed here and never resolved via a live dialog scan.
      Defaults to True (the safer, more conservative assumption) so any caller
      that is not updated to pass this explicitly stays gated while BLOCKED/
      manual-marked/FloodWait-cooldown rather than silently bypassing it.
    - A gate denial returns (False, "gate_denied") WITHOUT calling
      client.send_message (and without any typing-indicator action), so it
      never files a new Telegram Health Alert or increments notify_count --
      it is a plain deferred send, identical in shape to any other False
      return, so existing callers keep their current "not sent, leave
      pending" handling.
    - PEERFLOOD RECOVERY 20260812: an ordinary successful send now clears an
      unresolved incident for BOTH the FloodWait and PeerFlood families (a
      real send succeeding is itself the proof) -- see
      _tp_hg_may_recover_on_send_success. BLOCKED and an explicit manual mark
      stay sticky through ordinary sends.

    Returns (ok, fail_kind):
      ok=True,  fail_kind=""             -- sent successfully.
      ok=False, fail_kind="gate_denied"  -- the central health gate denied the
        send before any Telegram traffic (BLOCKED / manual mark / an
        unexpired FloodWait cooldown / a gate-check exception fail-closed).
      ok=False, fail_kind="restriction"  -- client.send_message raised and
        Telegram classified it as a LIMITED or BLOCKED restriction (PeerFlood,
        spam/restricted, FloodWait, ban/auth-family errors). Callers must not
        treat this as an ordinary delivery failure -- skip without marking
        trash and stop the tick (owner-approved "one probe per tick").
      ok=False, fail_kind="other"        -- any other send exception
        (network/proxy/timeout/unclassified) -- ordinary failure handling
        applies unchanged.
    """
    if MANAGER_RUNTIME_KEY:
        try:
            allowed, gate_reason = await _tp_hg_send_allowed(MANAGER_RUNTIME_KEY, new_dialog=new_dialog)
        except Exception as gate_error:
            allowed, gate_reason = (
                False,
                f"gate_error_fail_closed:{type(gate_error).__name__}",
            )
        if not allowed:
            try:
                print(f"manager private send gated key={MANAGER_RUNTIME_KEY} chat_id={chat_id} new_dialog={new_dialog} reason={gate_reason}")
            except Exception:
                pass
            return False, "gate_denied"
    try:
        out_text = str(text or "")
        try:
            resolver = globals().get("_content_resolve_outgoing_text")
            if callable(resolver):
                out_text = str(resolver(out_text) or out_text)
        except Exception:
            pass
        if human_delay:
            await _human_send_delay(int(chat_id), out_text, after_first=bool(after_first_delay))
        msg = await client.send_message(int(chat_id), out_text)
        mid = int(getattr(msg, "id", 0) or 0)
        if mid:
            try:
                _remember_program_sent(int(chat_id), mid)
            except Exception:
                pass
        if MANAGER_RUNTIME_KEY:
            try:
                if not await _tp_hg_manual_override_active(MANAGER_RUNTIME_KEY):
                    recover = await _tp_hg_may_recover_on_send_success(MANAGER_RUNTIME_KEY)
                    await _tp_hg_update_status(MANAGER_RUNTIME_KEY, status=TP_HG_STATUS_OK, error_source="client_send_success", allow_recover=recover)
            except Exception:
                pass
        return True, ""
    except Exception as e:
        try:
            print(f"manager private send error: {e!r}")
        except Exception:
            pass
        fail_kind = "other"
        if MANAGER_RUNTIME_KEY:
            try:
                classified = _tp_hg_classify_exception(e, source="client_auto_send")
                if str(classified.get("status") or "").strip().lower() in {TP_HG_STATUS_LIMITED, TP_HG_STATUS_BLOCKED}:
                    fail_kind = "restriction"
            except Exception:
                pass
            try:
                await _tp_hg_set_from_exception(MANAGER_RUNTIME_KEY, e, source="client_auto_send")
            except Exception as he:
                try:
                    print(f"telegram health send classification error: {he!r}")
                except Exception:
                    pass
        return False, fail_kind


async def _send_manager_private(chat_id: int, text: str, *, human_delay: bool = False, after_first_delay: bool = False, new_dialog: bool = True) -> bool:  # type: ignore[override]
    """Thin bool wrapper over _send_manager_private_ex (PEERFLOOD RECOVERY
    20260812) -- kept for the existing callers that only need the plain
    success/failure contract. Callers that must distinguish a Telegram
    restriction failure from an ordinary send failure (post_manual_followup,
    profile reminders) call _send_manager_private_ex directly instead."""
    ok, _fail_kind = await _send_manager_private_ex(
        chat_id, text, human_delay=human_delay, after_first_delay=after_first_delay, new_dialog=new_dialog,
    )
    return ok


async def _tp_hg_queue_command_for_manager(key: str, command: str, *, user_id: int = 0, timeout_sec: int = 45) -> Tuple[bool, str]:
    key = _tp_hg_norm_key(key)
    if not key:
        return False, "manager_key пустой"
    try:
        from storage import manager_queue_get, manager_queue_put
    except Exception as e:
        return False, f"Ошибка очереди менеджера: {e!r}"

    nonce = f"tghealth:{command}:{key}:{int(time.time() * 1000)}:{_tp_hg_safe_uuid.uuid4().hex}"
    try:
        await manager_queue_put(
            target_key=key,
            command=str(command or "tghealth_check"),
            created_by=str(user_id or "tghealth"),
            nonce=nonce,
            expires_at=_future_iso(int(timeout_sec) + 30),
            db_path=TPILOT_DB_PATH,
        )
    except Exception as e:
        return False, f"{key}: не удалось поставить проверку в очередь: {e!r}"

    deadline = time.monotonic() + max(10, int(timeout_sec or 45))
    while time.monotonic() < deadline:
        row = await manager_queue_get(nonce, db_path=TPILOT_DB_PATH)
        status = str((row or {}).get("status") or "")
        if status in ("done", "error", "timeout"):
            if status == "done" and int((row or {}).get("result_ok") or 0) == 1:
                return True, str((row or {}).get("result_text") or f"🟢 OK {key}: OK")
            return False, str((row or {}).get("error_text") or (row or {}).get("result_text") or f"{key}: ошибка проверки")
        await asyncio.sleep(0.7)
    return False, f"{key}: manager-процесс не ответил за {timeout_sec} сек. Проверьте, что он запущен."


async def _tp_hg_queue_check_for_manager(key: str, *, user_id: int = 0, timeout_sec: int = 45) -> Tuple[bool, str]:  # type: ignore[override]
    return await _tp_hg_queue_command_for_manager(key, "tghealth_check", user_id=user_id, timeout_sec=timeout_sec)


async def _tp_hg_queue_deepcheck_for_manager(key: str, *, user_id: int = 0, timeout_sec: int = 60) -> Tuple[bool, str]:
    return await _tp_hg_queue_command_for_manager(key, "tghealth_deepcheck", user_id=user_id, timeout_sec=timeout_sec)


async def _tp_hg_deepcheck_command(target: str, *, user_id: int = 0) -> str:
    key = _tp_hg_norm_key(target or "")
    if not key or key == "all":
        return "Формат: /tghealth deepcheck <manager_key>\nDeepcheck запускается только по одному менеджеру вручную. Массовый deepcheck отключён для безопасности."
    ok, text = await _tp_hg_queue_deepcheck_for_manager(key, user_id=user_id, timeout_sec=60)
    status_text = await _tp_hg_format_status(key)
    note = "Ручная deep-проверка делает одну отправку в Избранное самого аккаунта и удаляет сообщение. Она не запускается автоматически."
    return (f"{'✅' if ok else '⚠️'} {text}\n\n" + status_text + "\n\n" + note).rstrip()


async def _tp_hg_mark(target: str, status: str, reason: str = "") -> str:  # type: ignore[override]
    key = _tp_hg_norm_key(target or "")
    st = str(status or "").strip().lower()
    if not key or st not in {TP_HG_STATUS_LIMITED, TP_HG_STATUS_BLOCKED}:
        return "Формат: /tghealth mark <manager_key> limited|blocked причина"
    reason_s = str(reason or "").strip() or "ручная отметка администратора"
    err_cls = "ManualLimited" if st == TP_HG_STATUS_LIMITED else "ManualBlocked"
    action = "Проверить аккаунт вручную. Решение об остановке менеджера принимает администратор. Для снятия ручной отметки используйте /tghealth reset <manager_key>."
    row = await _tp_hg_update_status(
        key,
        status=st,
        error_class=err_cls,
        error_text=reason_s[:2000],
        error_source="manual_mark",
        action_required=action,
    )
    return "\n".join([
        "✅ Telegram Health обновлён вручную",
        "",
        f"Менеджер: {key}",
        f"Статус: {_tp_hg_status_label(str(row.get('health_status') or st))}",
        f"Причина: {reason_s}",
        "",
        "Ручная отметка держится до команды /tghealth reset.",
        "Уведомление от��равляется только по 🟠 LIMITED и 🔴 BLOCKED.",
    ]).rstrip()


async def _tp_hg_handle_command(args: str = "", *, user_id: int = 0) -> str:  # type: ignore[override]
    parts = [p for p in str(args or "").split() if p.strip()]
    if not parts or parts[0].lower() in {"status", "show", "стату��"}:
        target = parts[1] if len(parts) >= 2 else "all"
        return await _tp_hg_format_status(target)
    action = parts[0].lower()
    if action in {"all", "все"}:
        return await _tp_hg_format_status("all")
    if action in {"check", "проверить"}:
        target = parts[1] if len(parts) >= 2 else "all"
        text = await _tp_hg_check_command(target, user_id=user_id)
        text += "\n\nЛёгкая проверка безопасная: get_me + get_dialogs(limit=1), без отправки сообщений."
        text += "\nЕсли аккаунт визуально заморожен, но API отвечает OK, используйте ручную команду /tghealth deepcheck <manager_key> или /tghealth mark."
        return text.rstrip()
    if action in {"deepcheck", "deep", "глубокая"}:
        target = parts[1] if len(parts) >= 2 else ""
        return await _tp_hg_deepcheck_command(target, user_id=user_id)
    if action in {"mark", "set", "пометить"}:
        target = parts[1] if len(parts) >= 2 else ""
        st = parts[2].lower() if len(parts) >= 3 else ""
        reason = " ".join(parts[3:]).strip()
        return await _tp_hg_mark(target, st, reason)
    if action in {"reset", "clear", "сброс"}:
        target = parts[1] if len(parts) >= 2 else ""
        return await _tp_hg_reset(target)
    if action in {"help", "?"}:
        return "\n".join([
            "🛡 Telegram Health Guard",
            "",
            "/tghealth all - статусы всех аккаунтов",
            "/tghealth <manager_key> - статус одного аккаунта",
            "/tghealth check <manager_key> - лёгкая проверка без отправки сообщений",
            "/tghealth check all - лёгкая проверка всех запущенных менеджеров",
            "/tghealth deepcheck <manager_key> - ручная проверка отправки в Избранное одного аккаунта",
            "/tghealth mark <manager_key> blocked причина - вручную пометить BLOCKED",
            "/tghealth mark <manager_key> limited причина - вручную пометить LIMITED",
            "/tghealth reset <manager_key> - сбросить ошибку до UNKNOWN",
            "",
            "Уведомления отправляются только по 🟠 LIMITED и 🔴 BLOCKED.",
            "Плановая проверка каждые 20 минут, без тестовых сообщений.",
            "Deepcheck не запускается автоматически и работает только по одному менеджеру вручную.",
            "Автостоп менеджера не выполняется.",
        ]).rstrip()
    return await _tp_hg_format_status(action)


async def _handle_ai_stat_command(event: events.NewMessage.Event) -> bool:  # type: ignore[override]
    try:
        if CONTROLLER_MODE:
            chat_id = int(event.chat_id or 0)
            allowed_chats = {int(AI_STAT_CHAT_ID or 0)}
            try:
                if WORK_STATUS_CHAT_ID:
                    allowed_chats.add(int(WORK_STATUS_CHAT_ID))
            except Exception:
                pass
            if chat_id in allowed_chats:
                cmd, args = _parse_cmd((event.raw_text or "").strip())
                if cmd == "/tghealth":
                    await client.send_message(event.chat_id, await _tp_hg_handle_command(args, user_id=int(event.sender_id or 0)))
                    return True
    except Exception as e:
        try:
            await client.send_message(event.chat_id, f"Ошибка /tghealth: {e!r}")
            return True
        except Exception:
            pass
    if callable(_TP_HG_V13_SAFE_ORIG_HANDLE_AI_STAT):
        return await _TP_HG_V13_SAFE_ORIG_HANDLE_AI_STAT(event)
    return False


async def _handle_manager_plaintext(event: events.NewMessage.Event) -> bool:  # type: ignore[override]
    try:
        if CONTROLLER_MODE and event.raw_text and not event.out:
            text = str(event.raw_text or "").strip()
            cmd, args = _parse_cmd(text)
            if cmd == "/tghealth":
                if event.is_private:
                    try:
                        if not await _manager_require_auth(int(event.chat_id), int(event.sender_id or 0)):
                            return True
                    except Exception:
                        pass
                    await client.send_message(event.chat_id, await _tp_hg_handle_command(args, user_id=int(event.sender_id or 0)))
                    return True
    except Exception as e:
        try:
            await client.send_message(event.chat_id, f"Ошибка /tghealth: {e!r}")
            return True
        except Exception:
            pass
    if callable(_TP_HG_V13_SAFE_ORIG_HANDLE_MANAGER_PLAINTEXT):
        return await _TP_HG_V13_SAFE_ORIG_HANDLE_MANAGER_PLAINTEXT(event)
    return False


async def _panel_execute_command_text(command_text: str, *, requested_by: int = 0, source_chat_id: int = 0, response_chat_id: int = 0):  # type: ignore[override]
    text = str(command_text or "").strip()
    cmd, args = _parse_cmd(text)
    if cmd == "/tghealth":
        return {"ok": True, "result_text": await _tp_hg_handle_command(args, user_id=requested_by)}
    if callable(_TP_HG_V13_SAFE_ORIG_PANEL_EXEC):
        try:
            return await _TP_HG_V13_SAFE_ORIG_PANEL_EXEC(command_text, requested_by=requested_by, source_chat_id=source_chat_id, response_chat_id=response_chat_id)
        except TypeError:
            try:
                return await _TP_HG_V13_SAFE_ORIG_PANEL_EXEC(command_text, requested_by=requested_by, source_chat_id=source_chat_id)
            except TypeError:
                try:
                    return await _TP_HG_V13_SAFE_ORIG_PANEL_EXEC(command_text, requested_by=requested_by)
                except TypeError:
                    return await _TP_HG_V13_SAFE_ORIG_PANEL_EXEC(command_text)
    return {"ok": False, "error_text": f"Команда не поддерживается: {cmd or text}"}

