# --- TPILOT AUTOREPLY ENTERPRISE REPAIR V1 20260514 START ---
# Professional client auto-message layer:
# - 👋 Greeting / away notice is ON by default and stays ON until an admin turns it off.
# - 📋 Questionnaire is OFF by default and turns ON only by admin action.
# - 🛑 Emergency silence blocks all client auto-messages without changing greeting/questionnaire settings.
# - Contact Identity must not break client auto-replies.

_TP_AE_VERSION = "autoreply_enterprise_repair_v1_20260514"
_TP_AE_ORIG_PANEL_EXEC = globals().get("_panel_execute_command_text")
_TP_AE_ORIG_HANDLE_AI_STAT = globals().get("_handle_ai_stat_command")
_TP_AE_ORIG_RECORD_INCOMING = globals().get("_record_incoming_from_manager")
_TP_AE_ORIG_SET_PROFILE_AUTO_ENABLED = globals().get("_set_profile_auto_enabled")

TP_AE_DEFAULT_GREETING_ENABLED = 1
TP_AE_DEFAULT_QUESTIONNAIRE_ENABLED = 0


def _tp_ae_int(raw: Any, default: int = 0) -> int:
    try:
        if raw is None or str(raw).strip() == "":
            return int(default)
        return int(raw)
    except Exception:
        return int(default)


def _tp_ae_now_iso() -> str:
    try:
        return _now_utc_iso()
    except Exception:
        return _tp_utc_now().replace(microsecond=0).isoformat()


def _tp_ae_truth(raw: Any, default: int = 0) -> int:
    s = str(raw if raw is not None else "").strip().lower()
    if s in {"1", "true", "yes", "on", "вкл", "да"}:
        return 1
    if s in {"0", "false", "no", "off", "выкл", "нет"}:
        return 0
    return int(default)


async def _tp_gq_ensure_central_tables() -> None:  # type: ignore[override]
    parent = os.path.dirname(TPILOT_DB_PATH)
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute("PRAGMA journal_mode=WAL;")
        await db.execute("PRAGMA busy_timeout=30000;")
        await db.execute("""
            CREATE TABLE IF NOT EXISTS manager_client_auto_settings(
                manager_key TEXT PRIMARY KEY,
                greeting_enabled INTEGER NOT NULL DEFAULT 1,
                questionnaire_enabled INTEGER NOT NULL DEFAULT 0,
                updated_at TEXT NOT NULL DEFAULT '',
                updated_by_user_id INTEGER
            );
        """)
        await db.execute("""
            CREATE TABLE IF NOT EXISTS manager_client_message_schedule(
                manager_key TEXT PRIMARY KEY,
                day_start TEXT NOT NULL DEFAULT '08:00',
                day_end TEXT NOT NULL DEFAULT '17:00',
                night_start TEXT NOT NULL DEFAULT '17:00',
                night_end TEXT NOT NULL DEFAULT '08:00',
                updated_at TEXT NOT NULL DEFAULT '',
                updated_by_user_id INTEGER
            );
        """)
        # Patch C2: source-level greeting/away TIME schedule (defensive mirror of storage.py
        # ensure_source_message_schedule). Inert by default (enabled=0); inheritance resolved in
        # _tp_gq_get_schedule. Independent of source_work_schedule (C1 work DAYS).
        await db.execute("""
            CREATE TABLE IF NOT EXISTS source_message_schedule(
                source_key TEXT PRIMARY KEY,
                day_start TEXT NOT NULL DEFAULT '08:00',
                day_end TEXT NOT NULL DEFAULT '17:00',
                night_start TEXT NOT NULL DEFAULT '17:00',
                night_end TEXT NOT NULL DEFAULT '08:00',
                enabled INTEGER NOT NULL DEFAULT 0,
                updated_by_user_id INTEGER,
                updated_at TEXT
            );
        """)
        await db.execute("""
            CREATE TABLE IF NOT EXISTS client_auto_global_settings(
                setting_key TEXT PRIMARY KEY,
                value TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT '',
                updated_by_user_id INTEGER
            );
        """)
        await db.execute("""
            CREATE TABLE IF NOT EXISTS client_auto_silent_rules(
                scope TEXT NOT NULL DEFAULT '',
                rule_key TEXT NOT NULL DEFAULT '',
                enabled INTEGER NOT NULL DEFAULT 0,
                updated_at TEXT NOT NULL DEFAULT '',
                updated_by_user_id INTEGER,
                PRIMARY KEY(scope, rule_key)
            );
        """)
        await db.execute("""
            CREATE TABLE IF NOT EXISTS client_autoreply_audit(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                created_at TEXT NOT NULL DEFAULT '',
                manager_key TEXT NOT NULL DEFAULT '',
                chat_id INTEGER NOT NULL DEFAULT 0,
                action TEXT NOT NULL DEFAULT '',
                reason TEXT NOT NULL DEFAULT '',
                window_kind TEXT NOT NULL DEFAULT '',
                greeting_enabled INTEGER NOT NULL DEFAULT 0,
                questionnaire_enabled INTEGER NOT NULL DEFAULT 0,
                contact_kind TEXT NOT NULL DEFAULT '',
                lead_countable INTEGER NOT NULL DEFAULT 0,
                manager_replied INTEGER NOT NULL DEFAULT 0,
                baseline_old INTEGER NOT NULL DEFAULT 0,
                send_ok INTEGER,
                error_text TEXT NOT NULL DEFAULT '',
                extra TEXT NOT NULL DEFAULT ''
            );
        """)
        await db.execute("CREATE INDEX IF NOT EXISTS client_autoreply_audit_lookup_idx ON client_autoreply_audit(manager_key, chat_id, id);")
        now = _tp_ae_now_iso()
        await db.execute("INSERT OR IGNORE INTO client_auto_global_settings(setting_key,value,updated_at,updated_by_user_id) VALUES('default_greeting_enabled','1',?,NULL)", (now,))
        await db.execute("INSERT OR IGNORE INTO client_auto_global_settings(setting_key,value,updated_at,updated_by_user_id) VALUES('default_questionnaire_enabled','0',?,NULL)", (now,))
        await db.commit()


async def _tp_ae_global_default(setting_key: str, fallback: int) -> int:
    await _tp_gq_ensure_central_tables()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        cur = await db.execute("SELECT value FROM client_auto_global_settings WHERE setting_key=?", (str(setting_key),))
        row = await cur.fetchone()
        if not row:
            return int(fallback)
        return _tp_ae_truth(row[0], fallback)


async def _tp_ae_set_global_default(setting_key: str, value: int, *, user_id: int = 0) -> None:
    await _tp_gq_ensure_central_tables()
    now = _tp_ae_now_iso()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute("""
            INSERT INTO client_auto_global_settings(setting_key, value, updated_at, updated_by_user_id)
            VALUES(?,?,?,?)
            ON CONFLICT(setting_key) DO UPDATE SET
                value=excluded.value,
                updated_at=excluded.updated_at,
                updated_by_user_id=excluded.updated_by_user_id
        """, (str(setting_key), str(int(value)), now, int(user_id or 0) or None))
        await db.commit()


async def _tp_gq_get_settings(manager_key: str) -> Dict[str, Any]:  # type: ignore[override]
    key = _tp_gq_norm_key(manager_key)
    default_greeting = await _tp_ae_global_default("default_greeting_enabled", TP_AE_DEFAULT_GREETING_ENABLED)
    default_questionnaire = await _tp_ae_global_default("default_questionnaire_enabled", TP_AE_DEFAULT_QUESTIONNAIRE_ENABLED)
    if not key:
        return {"greeting_enabled": default_greeting, "questionnaire_enabled": default_questionnaire, "updated_at": ""}
    await _tp_gq_ensure_central_tables()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM manager_client_auto_settings WHERE manager_key=?", (key,))
        row = await cur.fetchone()
        if not row:
            return {"manager_key": key, "greeting_enabled": default_greeting, "questionnaire_enabled": default_questionnaire, "updated_at": "", "is_default": 1}
        d = dict(row)
        d["greeting_enabled"] = _tp_ae_truth(d.get("greeting_enabled"), default_greeting)
        d["questionnaire_enabled"] = _tp_ae_truth(d.get("questionnaire_enabled"), default_questionnaire)
        d["is_default"] = 0
        return d


async def _tp_gq_set_greeting_enabled(manager_key: str, enabled: bool, *, user_id: int = 0) -> None:  # type: ignore[override]
    key = _tp_gq_norm_key(manager_key)
    if not key:
        return
    await _tp_gq_ensure_central_tables()
    old = await _tp_gq_get_settings(key)
    q_enabled = _tp_ae_truth(old.get("questionnaire_enabled"), TP_AE_DEFAULT_QUESTIONNAIRE_ENABLED)
    now = _tp_ae_now_iso()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute("""
            INSERT INTO manager_client_auto_settings(manager_key, greeting_enabled, questionnaire_enabled, updated_at, updated_by_user_id)
            VALUES(?,?,?,?,?)
            ON CONFLICT(manager_key) DO UPDATE SET
                greeting_enabled=excluded.greeting_enabled,
                updated_at=excluded.updated_at,
                updated_by_user_id=excluded.updated_by_user_id
        """, (key, 1 if enabled else 0, int(q_enabled), now, int(user_id or 0) or None))
        await db.commit()


async def _tp_gq_set_questionnaire_enabled(manager_key: str, enabled: bool, *, user_id: int = 0) -> None:  # type: ignore[override]
    key = _tp_gq_norm_key(manager_key)
    if not key:
        return
    await _tp_gq_ensure_central_tables()
    old = await _tp_gq_get_settings(key)
    greeting_enabled = _tp_ae_truth(old.get("greeting_enabled"), TP_AE_DEFAULT_GREETING_ENABLED)
    now = _tp_ae_now_iso()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute("""
            INSERT INTO manager_client_auto_settings(manager_key, greeting_enabled, questionnaire_enabled, updated_at, updated_by_user_id)
            VALUES(?,?,?,?,?)
            ON CONFLICT(manager_key) DO UPDATE SET
                questionnaire_enabled=excluded.questionnaire_enabled,
                updated_at=excluded.updated_at,
                updated_by_user_id=excluded.updated_by_user_id
        """, (key, int(greeting_enabled), 1 if enabled else 0, now, int(user_id or 0) or None))
        await db.commit()
    # Legacy profile-auto table follows the new questionnaire switch, but never controls greeting.
    try:
        if callable(_TP_AE_ORIG_SET_PROFILE_AUTO_ENABLED):
            await _TP_AE_ORIG_SET_PROFILE_AUTO_ENABLED(key, bool(enabled), user_id=user_id)
    except Exception as e:
        print(f"autoreply enterprise legacy questionnaire sync error: {e!r}")


async def _tp_ae_active_manager_keys() -> List[str]:
    try:
        rows = await manager_list_rows(include_removed=False)
    except Exception:
        rows = []
    out: List[str] = []
    for r in rows or []:
        key = _tp_gq_norm_key((r or {}).get("manager_key") or "")
        if not key:
            continue
        try:
            if str((r or {}).get("status") or "") != "active":
                continue
            if int((r or {}).get("is_enabled") or 0) != 1:
                continue
            if int((r or {}).get("manual_stopped") or 0) == 1:
                continue
        except Exception:
            pass
        out.append(key)
    return out


async def _tp_ae_target_keys(target: str, *, write_all_active: bool = False) -> Tuple[List[str], str]:
    target = _tp_gq_norm_key(target or "all") or "all"
    if target == "all" and write_all_active:
        keys = await _tp_ae_active_manager_keys()
        return keys, "" if keys else "Активные менеджеры не найдены."
    return await _tp_gq_manager_keys(target)


async def _tp_ae_set_silent(scope: str, rule_key: str, enabled: bool, *, user_id: int = 0) -> None:
    await _tp_gq_ensure_central_tables()
    scope = str(scope or "manager").strip().lower()
    key = _tp_gq_norm_key(rule_key or "all") or "all"
    if scope in {"all", "global"}:
        scope, key = "global", "all"
    now = _tp_ae_now_iso()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute("""
            INSERT INTO client_auto_silent_rules(scope, rule_key, enabled, updated_at, updated_by_user_id)
            VALUES(?,?,?,?,?)
            ON CONFLICT(scope, rule_key) DO UPDATE SET
                enabled=excluded.enabled,
                updated_at=excluded.updated_at,
                updated_by_user_id=excluded.updated_by_user_id
        """, (scope, key, 1 if enabled else 0, now, int(user_id or 0) or None))
        await db.commit()


async def _tp_ae_silent_blocked(manager_key: str) -> bool:
    key = _tp_gq_norm_key(manager_key)
    await _tp_gq_ensure_central_tables()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        cur = await db.execute("SELECT enabled FROM client_auto_silent_rules WHERE scope='global' AND rule_key='all' LIMIT 1")
        row = await cur.fetchone()
        if row and int(row[0] or 0) == 1:
            return True
        if key:
            cur = await db.execute("SELECT enabled FROM client_auto_silent_rules WHERE scope='manager' AND rule_key=? LIMIT 1", (key,))
            row = await cur.fetchone()
            if row and int(row[0] or 0) == 1:
                return True
    return False


async def _tp_ae_format_silent_status(target: str = "all") -> str:
    target = _tp_gq_norm_key(target or "all") or "all"
    keys, err = await _tp_gq_manager_keys(target)
    if err:
        return err
    global_on = await _tp_ae_silent_blocked("")
    rows = await manager_list_rows(include_removed=False)
    by_key = {_tp_gq_norm_key((r or {}).get("manager_key") or ""): r for r in rows or []}
    lines = ["🛑 Аварийная тишина", "", f"Глобально: {'включена' if global_on else 'выключена'}", ""]
    for key in keys:
        blocked = await _tp_ae_silent_blocked(key)
        label = _manager_label_from_row(by_key.get(key) or {"manager_key": key})
        lines.append(f"{'🛑 тишина' if blocked else '✅ авто-сообщения разрешены'} - {label}")
    lines += ["", "Важно: аварийная тишина не меняет настройки приветствия и автоанкеты. Она только временно блокирует любые авто-сообщения клиентам."]
    return "\n".join(lines).rstrip()


async def _handle_silent_command(args: str, *, user_id: int = 0) -> str:  # type: ignore[override]
    parts = [p for p in str(args or "").split() if p.strip()]
    if not parts or parts[0].lower() in {"status", "st", "state", "проверить"}:
        target = parts[1] if len(parts) >= 2 else "all"
        return await _tp_ae_format_silent_status(target)
    action = parts[0].lower()
    scope = "manager"
    target = "all"
    if action in {"manager", "mgr"}:
        if len(parts) < 3:
            return "Формат: /silent manager on|off <manager|all>"
        action = parts[1].lower()
        target = parts[2]
    else:
        target = parts[1] if len(parts) >= 2 else "all"
    if action not in {"on", "off", "вкл", "выкл"}:
        return "Формат: /silent status|manager on|manager off <manager|all>"
    enabled = action in {"on", "вкл"}
    if _tp_gq_norm_key(target or "all") == "all":
        await _tp_ae_set_silent("global", "all", enabled, user_id=user_id)
    else:
        key = _tp_gq_norm_key(target)
        keys, err = await _tp_gq_manager_keys(key)
        if err:
            return err
        for k in keys:
            await _tp_ae_set_silent(scope, k, enabled, user_id=user_id)
    return await _tp_ae_format_silent_status(target)


async def _tp_ae_audit(
    manager_key: str,
    chat_id: int,
    *,
    action: str,
    reason: str = "",
    window_kind: str = "",
    settings: Optional[Dict[str, Any]] = None,
    lead_row: Optional[Dict[str, Any]] = None,
    state: Optional[Dict[str, Any]] = None,
    send_ok: Optional[bool] = None,
    error_text: str = "",
    extra: str = "",
) -> None:
    try:
        await _tp_gq_ensure_central_tables()
        st = dict(settings or {})
        lead = dict(lead_row or {})
        auto_state = dict(state or {})
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            await db.execute("""
                INSERT INTO client_autoreply_audit(
                    created_at, manager_key, chat_id, action, reason, window_kind,
                    greeting_enabled, questionnaire_enabled, contact_kind, lead_countable,
                    manager_replied, baseline_old, send_ok, error_text, extra
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            """, (
                _tp_ae_now_iso(),
                _tp_gq_norm_key(manager_key),
                int(chat_id or 0),
                str(action or ""),
                str(reason or ""),
                str(window_kind or ""),
                _tp_ae_truth(st.get("greeting_enabled"), 0),
                _tp_ae_truth(st.get("questionnaire_enabled"), 0),
                str(lead.get("contact_kind") or ""),
                _tp_ae_int(lead.get("lead_countable"), 0),
                1 if (_tp_ae_int(auto_state.get("manager_replied"), 0) == 1 or _tp_ae_int(lead.get("manager_replied"), 0) == 1) else 0,
                _tp_ae_int(lead.get("baseline_old"), 0),
                None if send_ok is None else (1 if send_ok else 0),
                str(error_text or "")[:1000],
                str(extra or "")[:1000],
            ))
            await db.commit()
    except Exception as e:
        print(f"autoreply audit error: {e!r}")


async def _tp_ae_format_why(manager_key: str = "", chat_id: int = 0) -> str:
    key = _tp_gq_norm_key(manager_key or "")
    cid = int(chat_id or 0)
    if not key or cid <= 0:
        return "Формат: /autoreply why <manager_key> <chat_id>"
    await _tp_gq_ensure_central_tables()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("""
            SELECT * FROM client_autoreply_audit
            WHERE manager_key=? AND chat_id=?
            ORDER BY id DESC
            LIMIT 10
        """, (key, cid))
        rows = [dict(r) for r in await cur.fetchall()]
    if not rows:
        st = await _tp_gq_get_settings(key)
        blocked = await _tp_ae_silent_blocked(key)
        return "\n".join([
            "🔎 Почему молчит автоответчик",
            "",
            f"Менеджер: {key}",
            f"chat_id: {cid}",
            "Записей audit пока нет.",
            "",
            f"Приветствие / нет на месте: {'включено' if _tp_ae_truth(st.get('greeting_enabled'), 0) == 1 else 'выключено'}",
            f"Автоанкета: {'включена' if _tp_ae_truth(st.get('questionnaire_enabled'), 0) == 1 else 'выключена'}",
            f"Аварийная тишина: {'включена' if blocked else 'выключена'}",
        ]).rstrip()
    lines = ["🔎 Почему молчит автоответчик", "", f"Менеджер: {key}", f"chat_id: {cid}", "", "Последние решения:"]
    for r in rows:
        lines.append("")
        lines.append(f"{str(r.get('created_at') or '')} | {str(r.get('window_kind') or '_')}")
        lines.append(f"Действие: {str(r.get('action') or '_')}")
        reason = str(r.get("reason") or "")
        if reason:
            lines.append(f"Причина: {reason}")
        lines.append(f"Приветствие: {'вкл' if _tp_ae_int(r.get('greeting_enabled'), 0) == 1 else 'выкл'} | Анкета: {'вкл' if _tp_ae_int(r.get('questionnaire_enabled'), 0) == 1 else 'выкл'}")
        if r.get("send_ok") is not None:
            lines.append(f"Отправка: {'успешно' if _tp_ae_int(r.get('send_ok'), 0) == 1 else 'ошибка/нет'}")
        err = str(r.get("error_text") or "")
        if err:
            lines.append(f"Ошибка: {err[:300]}")
    return "\n".join(lines).rstrip()


async def _tp_ci_ensure_daily_identity_columns(db_path: str) -> None:  # type: ignore[override]
    if callable(_TP_CI_ORIG_ENSURE_DAILY_LEADS_TABLE):
        await _TP_CI_ORIG_ENSURE_DAILY_LEADS_TABLE(db_path)
    if not db_path:
        return
    await _tp_ci_ensure_inbound_events_table(db_path)
    async with aiosqlite.connect(str(db_path)) as db:
        # R1A1-D (F-21): busy_timeout before journal_mode. This is the connection
        # used by _tp_ci_record_daily_lead_event's own DDL ensure step; without the
        # wait policy active first, the first statement here can fail after only
        # the driver's default ~5s instead of our 30s, which was observed to make
        # the identity pipeline raise systemically under contention (see F-20).
        await db.execute("PRAGMA busy_timeout=30000;")
        await db.execute("PRAGMA journal_mode=WAL;")
        cols = await _table_columns(db, "daily_leads")
        migrations = [
            ("contact_kind", "ALTER TABLE daily_leads ADD COLUMN contact_kind TEXT NOT NULL DEFAULT 'new'"),
            ("lead_countable", "ALTER TABLE daily_leads ADD COLUMN lead_countable INTEGER NOT NULL DEFAULT 1"),
            ("known_contact_id", "ALTER TABLE daily_leads ADD COLUMN known_contact_id INTEGER NOT NULL DEFAULT 0"),
            ("event_key", "ALTER TABLE daily_leads ADD COLUMN event_key TEXT NOT NULL DEFAULT ''"),
            ("dedupe_reason", "ALTER TABLE daily_leads ADD COLUMN dedupe_reason TEXT NOT NULL DEFAULT ''"),
            ("baseline_old", "ALTER TABLE daily_leads ADD COLUMN baseline_old INTEGER NOT NULL DEFAULT 0"),
            ("returning_flag", "ALTER TABLE daily_leads ADD COLUMN returning_flag INTEGER NOT NULL DEFAULT 0"),
            ("first_seen_global_at", "ALTER TABLE daily_leads ADD COLUMN first_seen_global_at TEXT NOT NULL DEFAULT ''"),
            ("first_seen_global_manager_key", "ALTER TABLE daily_leads ADD COLUMN first_seen_global_manager_key TEXT NOT NULL DEFAULT ''"),
        ]
        for col, ddl in migrations:
            if col not in cols:
                try:
                    await db.execute(ddl)
                except Exception as e:
                    print(f"contact_identity migration {col} warning: {e!r}")
        await db.execute("CREATE INDEX IF NOT EXISTS daily_leads_countable_idx ON daily_leads(lead_date, lead_countable, manager_key);")
        await db.execute("CREATE INDEX IF NOT EXISTS daily_leads_kind_idx ON daily_leads(lead_date, contact_kind, manager_key);")
        await db.execute("CREATE INDEX IF NOT EXISTS daily_leads_event_key_idx ON daily_leads(event_key);")
        await db.execute("CREATE INDEX IF NOT EXISTS daily_leads_known_contact_idx ON daily_leads(known_contact_id);")
        await db.commit()


_ensure_daily_leads_table = _tp_ci_ensure_daily_identity_columns  # type: ignore[assignment]


async def _tp_ci_set_daily_identity(db_path: str, row_id: int, *, contact_kind: str, lead_countable: int, known_contact_id: int = 0, event_key: str = "", dedupe_reason: str = "", baseline_old: int = 0, returning: int = 0, first_seen_global_at: str = "", first_seen_global_manager_key: str = "", duplicate: Optional[int] = None, ai_stat_sent: Optional[int] = None) -> None:  # type: ignore[override]
    if int(row_id or 0) <= 0:
        return
    await _tp_ci_ensure_daily_identity_columns(db_path)
    fields = {
        "contact_kind": str(contact_kind or "unknown"),
        "lead_countable": int(lead_countable or 0),
        "known_contact_id": int(known_contact_id or 0),
        "event_key": str(event_key or ""),
        "dedupe_reason": str(dedupe_reason or ""),
        "baseline_old": int(baseline_old or 0),
        "returning_flag": int(returning or 0),
        "first_seen_global_at": str(first_seen_global_at or ""),
        "first_seen_global_manager_key": _tp_ci_norm_key(first_seen_global_manager_key or ""),
        "updated_at": _tp_ci_now_iso(),
    }
    if duplicate is not None:
        fields["duplicate"] = int(duplicate or 0)
        fields["duplicate_checked"] = 1
    if ai_stat_sent is not None:
        fields["ai_stat_sent"] = int(ai_stat_sent or 0)
    keys = list(fields.keys())
    vals = [fields[k] for k in keys]
    sql = "UPDATE daily_leads SET " + ", ".join([f"{k}=?" for k in keys]) + " WHERE id=?"
    vals.append(int(row_id))
    async with aiosqlite.connect(str(db_path)) as db:
        await db.execute(sql, tuple(vals))
        await db.commit()


async def _tp_ae_apply_profile_defaults_to_active_managers(*, user_id: int = 0) -> None:
    keys = await _tp_ae_active_manager_keys()
    await _tp_ae_set_global_default("default_greeting_enabled", 1, user_id=user_id)
    await _tp_ae_set_global_default("default_questionnaire_enabled", 0, user_id=user_id)
    for key in keys:
        await _tp_gq_set_greeting_enabled(key, True, user_id=user_id)
        await _tp_gq_set_questionnaire_enabled(key, False, user_id=user_id)


async def _maybe_auto_reply_to_lead(lead_row: Dict[str, Any], state: Dict[str, Any], work: Dict[str, Any]) -> None:  # type: ignore[override]
    chat_id = int((lead_row or {}).get("chat_id") or 0)
    manager_key = _tp_gq_norm_key((lead_row or {}).get("manager_key") or MANAGER_RUNTIME_KEY)
    if chat_id <= 0 or not manager_key:
        return

    settings = await _tp_gq_get_settings(manager_key)
    schedule = await _tp_gq_get_schedule(manager_key)
    now_local = _kyiv_now()
    window, window_label, night_key = _tp_gq_window_now(schedule, now_local)
    status = str((work or {}).get("status") or "online").strip().lower()

    try:
        await _update_daily_lead_fields(
            DB_PATH,
            lead_date=str((lead_row or {}).get("lead_date") or now_local.date().isoformat()),
            manager_key=manager_key,
            chat_id=chat_id,
            manager_work_status=f"{status}|{window}",
        )
    except Exception:
        pass

    if await _tp_ae_silent_blocked(manager_key):
        await _tp_ae_audit(manager_key, chat_id, action="skipped", reason="emergency_silence", window_kind=window, settings=settings, lead_row=lead_row, state=state)
        return

    if int(settings.get("greeting_enabled") or 0) != 1:
        await _tp_ae_audit(manager_key, chat_id, action="skipped", reason="greeting_off", window_kind=window, settings=settings, lead_row=lead_row, state=state)
        return

    manager_replied = _tp_ae_int((state or {}).get("manager_replied"), 0) == 1 or _tp_ae_int((lead_row or {}).get("manager_replied"), 0) == 1
    if manager_replied:
        await _tp_ae_audit(manager_key, chat_id, action="skipped", reason="manager_replied", window_kind=window, settings=settings, lead_row=lead_row, state=state)
        return

    existing_same = int((lead_row or {}).get("_existing_same_manager_chat") or 0) == 1
    question_sent = _tp_gq_question_sent(lead_row, state)
    questionnaire_on = int(settings.get("questionnaire_enabled") or 0) == 1

    if window in {"gap", "overlap"}:
        await _tp_ae_audit(manager_key, chat_id, action="skipped", reason=f"schedule_{window}", window_kind=window, settings=settings, lead_row=lead_row, state=state)
        return

    if existing_same:
        if window != "night" or not night_key:
            await _tp_ae_audit(manager_key, chat_id, action="skipped", reason="old_client_day_silent", window_kind=window, settings=settings, lead_row=lead_row, state=state)
            return
        if await _tp_gq_old_autoresponder_sent(DB_PATH, manager_key, chat_id, night_key):
            await _tp_ae_audit(manager_key, chat_id, action="skipped", reason="old_client_night_already_sent", window_kind=window, settings=settings, lead_row=lead_row, state=state)
            return
        text = _tp_gq_content_text("offline_notice", str(globals().get("OFFLINE_NOTICE_TEXT") or ""))
        ok = await _send_manager_private(chat_id, text, human_delay=True, after_first_delay=True)
        if ok:
            await _tp_gq_mark_old_autoresponder_sent(DB_PATH, manager_key, chat_id, night_key)
        await _tp_ae_audit(manager_key, chat_id, action="sent_old_client_night_notice" if ok else "send_error", reason="old_client_night", window_kind=window, settings=settings, lead_row=lead_row, state=state, send_ok=ok)
        return

    if window == "night":
        if not night_key:
            night_key = _tp_gq_night_key(manager_key, schedule, now_local)
        if str((state or {}).get("offline_notice_period_key") or (lead_row or {}).get("offline_notice_period_key") or "") == str(night_key):
            await _tp_ae_audit(manager_key, chat_id, action="skipped", reason="night_notice_already_sent", window_kind=window, settings=settings, lead_row=lead_row, state=state)
            return
        text = _tp_gq_content_text("offline_notice", str(globals().get("OFFLINE_NOTICE_TEXT") or ""))
        ok = await _send_manager_private(chat_id, text, human_delay=True)
        if ok:
            await _set_daily_offline_sent(lead_row, night_key)
        await _tp_ae_audit(manager_key, chat_id, action="sent_night_notice" if ok else "send_error", reason="night_new_client", window_kind=window, settings=settings, lead_row=lead_row, state=state, send_ok=ok)
        return

    # Day window: first approved greeting. Questionnaire switch controls only follow-up questions after it.
    if not question_sent:
        text = _tp_gq_content_text("profile_question", str(globals().get("PROFILE_QUESTION_TEXT") or ""))
        ok = await _send_manager_private(chat_id, text, human_delay=True)
        if ok:
            await _set_daily_question_sent(lead_row)
        await _tp_ae_audit(manager_key, chat_id, action="sent_day_greeting" if ok else "send_error", reason="day_new_client", window_kind=window, settings=settings, lead_row=lead_row, state=state, send_ok=ok)
        return

    if questionnaire_on:
        await _tp_ae_audit(manager_key, chat_id, action="questionnaire_followup_attempt", reason="questionnaire_on", window_kind=window, settings=settings, lead_row=lead_row, state=state)
        await _tp_gq_send_questionnaire_followup(lead_row, state, chat_id)
    else:
        await _tp_ae_audit(manager_key, chat_id, action="skipped", reason="questionnaire_off_after_greeting", window_kind=window, settings=settings, lead_row=lead_row, state=state)


async def _tp_ae_fallback_record_and_reply(event: events.NewMessage.Event, original_error: Exception) -> None:
    try:
        if CONTROLLER_MODE or not MANAGER_RUNTIME_KEY or not event.is_private or event.out:
            return
        chat_id = int(event.chat_id or 0)
        if chat_id <= 0:
            return
        try:
            sender = await event.get_sender()
        except Exception:
            sender = None
        username = str(getattr(sender, "username", None) or "").strip()
        first_name = str(getattr(sender, "first_name", None) or "").strip()
        last_name = str(getattr(sender, "last_name", None) or "").strip()
        full_name = _full_name(first_name, last_name)
        phone = _tp_ci_phone(str(getattr(sender, "phone", None) or "")) if callable(globals().get("_tp_ci_phone")) else _phone_clean(str(getattr(sender, "phone", None) or ""))
        first_seen_utc = _event_utc_iso(event)
        created, row = (False, {})
        # R1A1-B (F-20): prefer the classification-aware recorder (canonical
        # `_record_daily_lead_event`, re-pointed to `_tp_ci_record_daily_lead_event`
        # at module load) over the pinned raw bypass
        # `_TP_CI_ORIG_RECORD_DAILY_LEAD_EVENT_DIRECT`, which writes daily_leads
        # via INSERT OR IGNORE with zero identity classification and lets the
        # table DEFAULT (contact_kind='new', lead_countable=1) apply. Fail-open
        # is forbidden: an identity/classification exception must never silently
        # produce a countable-new lead. The raw bypass is kept only as a last
        # resort if the canonical recorder is somehow unavailable.
        recorder = globals().get("_record_daily_lead_event") or globals().get("_TP_CI_ORIG_RECORD_DAILY_LEAD_EVENT_DIRECT")
        if callable(recorder):
            try:
                created, row = await recorder(
                    db_path=DB_PATH,
                    manager_key=MANAGER_RUNTIME_KEY,
                    manager_username=SELF_USERNAME,
                    chat_id=chat_id,
                    username=username,
                    full_name=full_name,
                    phone=phone,
                    first_seen_utc=first_seen_utc,
                )
            except Exception as rec_exc:
                print(f"autoreply enterprise fallback recorder failed: {rec_exc!r}")
                created, row = False, {}
        row = dict(row or {})
        if not row:
            # Recorder unavailable or itself failed: never default to
            # contact_kind='new'/lead_countable=1 -- unclassified/unknown and
            # non-countable is the only safe fail-closed default (autoreply below
            # still fires; it does not depend on contact_kind/lead_countable).
            dt_local = _utc_iso_to_kyiv_dt(first_seen_utc)
            row = {
                "lead_date": dt_local.date().isoformat(),
                "manager_key": MANAGER_RUNTIME_KEY,
                "chat_id": chat_id,
                "username": username,
                "full_name": full_name,
                "phone": phone,
                "first_seen_utc": first_seen_utc,
                "status": "unknown",
                "lead_countable": 0,
                "contact_kind": "unknown",
            }
        row.setdefault("manager_key", MANAGER_RUNTIME_KEY)
        row.setdefault("chat_id", chat_id)
        row.setdefault("lead_countable", 0)
        row.setdefault("contact_kind", "unknown")
        state = await _get_auto_state(DB_PATH, chat_id)
        work = await _get_manager_work_status(MANAGER_RUNTIME_KEY)
        await _tp_ae_audit(MANAGER_RUNTIME_KEY, chat_id, action="identity_error_fallback", reason="record_incoming_exception", window_kind="", settings=await _tp_gq_get_settings(MANAGER_RUNTIME_KEY), lead_row=row, state=state, error_text=repr(original_error))
        await _maybe_auto_reply_to_lead(row, state, work)
    except Exception as e:
        print(f"autoreply enterprise fallback error: {e!r}")


async def _record_incoming_from_manager(event: events.NewMessage.Event) -> None:  # type: ignore[override]
    if callable(_TP_AE_ORIG_RECORD_INCOMING):
        try:
            await _TP_AE_ORIG_RECORD_INCOMING(event)
            return
        except Exception as e:
            print(f"autoreply enterprise record_incoming fail-soft: {e!r}")
            await _tp_ae_fallback_record_and_reply(event, e)
            return
    return


async def _tp_gq_handle_greeting_command(args: str, *, user_id: int = 0) -> str:  # type: ignore[override]
    parts = [p for p in str(args or "").split() if p.strip()]
    action = (parts[0].lower() if parts else "status")
    target = parts[1] if len(parts) >= 2 else "all"
    if action in {"status", "st", "state", "проверить"}:
        return await _tp_gq_format_status(target)
    if action not in {"on", "off", "вкл", "выкл"}:
        return "Формат: /greeting status|on|off <manager|all>"
    enabled = action in {"on", "вкл"}
    if _tp_gq_norm_key(target or "all") == "all":
        await _tp_ae_set_global_default("default_greeting_enabled", 1 if enabled else 0, user_id=user_id)
    keys, err = await _tp_ae_target_keys(target, write_all_active=(_tp_gq_norm_key(target or "all") == "all"))
    if err:
        return err
    for key in keys:
        await _tp_gq_set_greeting_enabled(key, enabled, user_id=user_id)
    return await _tp_gq_format_status(target)


async def _tp_gq_handle_questionnaire_command(args: str, *, user_id: int = 0) -> str:  # type: ignore[override]
    parts = [p for p in str(args or "").split() if p.strip()]
    action = (parts[0].lower() if parts else "status")
    target = parts[1] if len(parts) >= 2 else "all"
    if action in {"status", "st", "state", "проверить"}:
        return await _tp_gq_format_status(target)
    if action not in {"on", "off", "вкл", "выкл"}:
        return "Формат: /questionnaire status|on|off <manager|all>"
    enabled = action in {"on", "вкл"}
    if _tp_gq_norm_key(target or "all") == "all":
        await _tp_ae_set_global_default("default_questionnaire_enabled", 1 if enabled else 0, user_id=user_id)
    keys, err = await _tp_ae_target_keys(target, write_all_active=(_tp_gq_norm_key(target or "all") == "all"))
    if err:
        return err
    for key in keys:
        await _tp_gq_set_questionnaire_enabled(key, enabled, user_id=user_id)
    return await _tp_gq_format_status(target)


async def _handle_autoreply_panel_command(args: str, *, user_id: int = 0) -> str:  # type: ignore[override]
    parts = [p for p in str(args or "").split() if p.strip()]
    action = (parts[0].lower() if parts else "status")
    if action == "why":
        if len(parts) < 3:
            return "Формат: /autoreply why <manager_key> <chat_id>"
        return await _tp_ae_format_why(parts[1], int(parts[2] or 0))
    target = parts[1] if len(parts) >= 2 else "all"
    if action in {"status", "st", "state"}:
        status_text = await _tp_gq_format_status(target)
        silent_text = await _tp_ae_format_silent_status(target)
        return status_text + "\n\n" + silent_text
    if action in {"auto", "on", "now"}:
        if _tp_gq_norm_key(target or "all") == "all":
            await _tp_ae_set_global_default("default_greeting_enabled", 1, user_id=user_id)
            await _tp_ae_set_silent("global", "all", False, user_id=user_id)
        keys, err = await _tp_ae_target_keys(target, write_all_active=(_tp_gq_norm_key(target or "all") == "all"))
        if err:
            return err
        for key in keys:
            await _tp_gq_set_greeting_enabled(key, True, user_id=user_id)
            await _tp_ae_set_silent("manager", key, False, user_id=user_id)
            if action == "now":
                try:
                    await _set_manager_work_status(key, "worknow", user_id=user_id, source="panel_autoreply_now")
                except Exception:
                    pass
        return await _handle_autoreply_panel_command("status " + str(target), user_id=user_id)
    if action in {"silent", "off"}:
        return await _handle_silent_command("manager on " + str(target), user_id=user_id)
    return "Формат: /autoreply status|auto|silent|why <manager|all>"


async def _handle_profile_auto_command(args: str, *, user_id: int = 0) -> str:  # type: ignore[override]
    # Compatibility alias: old /profile auto now controls only 📋 Автоанкету.
    parts = [p for p in str(args or "").split() if p.strip()]
    if parts and parts[0].lower() in {"auto", "анкета"}:
        return await _tp_gq_handle_questionnaire_command(" ".join(parts[1:]), user_id=user_id)
    return await _tp_gq_handle_questionnaire_command(args, user_id=user_id)


async def _handle_ai_stat_command(event: events.NewMessage.Event) -> bool:  # type: ignore[override]
    try:
        if CONTROLLER_MODE:
            chat_id = int(event.chat_id or 0)
            allowed_chats = {int(AI_STAT_CHAT_ID or 0)}
            try:
                if WORK_STATUS_CHAT_ID:
                    allowed_chats.add(int(WORK_STATUS_CHAT_ID))
            except Exception:
                pass
            if chat_id in allowed_chats:
                cmd, args = _parse_cmd((event.raw_text or "").strip())
                if cmd == "/greeting":
                    await client.send_message(event.chat_id, await _tp_gq_handle_greeting_command(args, user_id=int(event.sender_id or 0)))
                    return True
                if cmd == "/questionnaire":
                    await client.send_message(event.chat_id, await _tp_gq_handle_questionnaire_command(args, user_id=int(event.sender_id or 0)))
                    return True
                if cmd == "/silent":
                    await client.send_message(event.chat_id, await _handle_silent_command(args, user_id=int(event.sender_id or 0)))
                    return True
                if cmd == "/autoreply":
                    await client.send_message(event.chat_id, await _handle_autoreply_panel_command(args, user_id=int(event.sender_id or 0)))
                    return True
    except Exception as e:
        try:
            await client.send_message(event.chat_id, f"Ошибка autoreply enterprise: {e!r}")
            return True
        except Exception:
            pass
    if callable(_TP_AE_ORIG_HANDLE_AI_STAT):
        return await _TP_AE_ORIG_HANDLE_AI_STAT(event)
    return False


async def _panel_execute_command_text(command_text: str, *, requested_by: int = 0, source_chat_id: int = 0, response_chat_id: int = 0):  # type: ignore[override]
    text = str(command_text or "").strip()
    cmd, args = _parse_cmd(text)
    try:
        if cmd == "/greeting":
            return {"ok": True, "result_text": await _tp_gq_handle_greeting_command(args, user_id=requested_by)}
        if cmd == "/questionnaire":
            return {"ok": True, "result_text": await _tp_gq_handle_questionnaire_command(args, user_id=requested_by)}
        if cmd == "/silent":
            return {"ok": True, "result_text": await _handle_silent_command(args, user_id=requested_by)}
        if cmd == "/autoreply":
            return {"ok": True, "result_text": await _handle_autoreply_panel_command(args, user_id=requested_by)}
        if cmd == "/autoschedule":
            return {"ok": True, "result_text": await _tp_gq_handle_schedule_command(args, user_id=requested_by)}
    except Exception as e:
        return {"ok": False, "error_text": f"autoreply enterprise command error: {e!r}"}
    if callable(_TP_AE_ORIG_PANEL_EXEC):
        try:
            return await _TP_AE_ORIG_PANEL_EXEC(command_text, requested_by=requested_by, source_chat_id=source_chat_id, response_chat_id=response_chat_id)
        except TypeError:
            try:
                return await _TP_AE_ORIG_PANEL_EXEC(command_text, requested_by=requested_by)
            except TypeError:
                return await _TP_AE_ORIG_PANEL_EXEC(command_text)
    return {"ok": False, "error_text": f"Команда не поддерживается: {cmd or text}"}

# --- TPILOT AUTOREPLY ENTERPRISE REPAIR V1 20260514 END ---


# --- TPILOT PROFILE STRICT GATE + WORK PRESENCE V2 20260515 START ---
import json as _tp_fm_json
# Enterprise-safe rules:
# 1) The first client message is NEVER profile evidence. It only starts the lead.
# 2) Profile/liquid/nonliquid is based only on client messages AFTER the bot profile question.
# 3) Geo and age must both be known before final liquid/nonliquid. Missing fields -> ask up to 3 times -> NA.
# 4) From 07:50 to 17:00, day greeting is used only after real manager work presence.
#    Work presence = manual outbound messages to at least 2 distinct client chats within 45 minutes.

_TP_FM_VERSION = "profile_strict_presence_v2_20260515"
_TP_FM_ORIG_APPLY_PROFILE_FROM_TEXT = globals().get("_apply_profile_from_text")
_TP_FM_ORIG_CHOOSE_PROFILE_REPLY = globals().get("choose_profile_reply")
_TP_FM_ORIG_TP_QS_DECIDE = globals().get("_tp_qs_decide")
_TP_FM_ORIG_MAYBE_AUTO_REPLY = globals().get("_maybe_auto_reply_to_lead")
_TP_FM_ORIG_RECORD_INCOMING = globals().get("_record_incoming_from_manager")

TP_FM_WORK_PRESENCE_START = "07:50"
TP_FM_WORK_PRESENCE_END = "17:00"
TP_FM_WORK_PRESENCE_MIN_UNIQUE_CHATS = 2
TP_FM_WORK_PRESENCE_WINDOW_MINUTES = 45


def _tp_fm_int(raw: Any, default: int = 0) -> int:
    try:
        if raw is None or str(raw).strip() == "":
            return int(default)
        return int(raw)
    except Exception:
        return int(default)


def _tp_fm_text(raw: Any) -> str:
    return str(raw or "").strip()


def _tp_fm_bool(raw: Any) -> bool:
    return str(raw).strip().lower() in {"1", "true", "yes", "да", "on", "вкл"}


def _tp_fm_now_iso() -> str:
    try:
        return _now_utc_iso()
    except Exception:
        return _tp_utc_now().replace(microsecond=0).isoformat()


def _tp_fm_local_minutes(dt: datetime) -> int:
    return int(dt.hour) * 60 + int(dt.minute)


def _tp_fm_hhmm_to_minutes(raw: str) -> int:
    try:
        h, m = [int(x) for x in str(raw or "00:00").split(":", 1)]
        return max(0, min(24 * 60, h * 60 + m))
    except Exception:
        return 0


def _tp_fm_in_presence_window(local_dt: datetime) -> bool:
    cur = _tp_fm_local_minutes(local_dt)
    return _tp_fm_hhmm_to_minutes(TP_FM_WORK_PRESENCE_START) <= cur < _tp_fm_hhmm_to_minutes(TP_FM_WORK_PRESENCE_END)


def _tp_fm_work_date(local_dt: Optional[datetime] = None) -> str:
    return (local_dt or _kyiv_now()).date().isoformat()


async def _tp_fm_ensure_profile_schema(db_path: str) -> None:
    if not db_path:
        return
    try:
        if callable(globals().get("_tpe_ensure_profile_schema")):
            await globals()["_tpe_ensure_profile_schema"](db_path)
        else:
            await _ensure_daily_leads_table(db_path)
    except Exception:
        pass
    try:
        async with aiosqlite.connect(str(db_path)) as db:
            await db.execute("PRAGMA busy_timeout=30000;")
            cols = await _table_columns(db, "daily_leads")
            migrations = [
                ("profile_answer_texts", "ALTER TABLE daily_leads ADD COLUMN profile_answer_texts TEXT NOT NULL DEFAULT ''"),
                ("first_message_ignored", "ALTER TABLE daily_leads ADD COLUMN first_message_ignored INTEGER NOT NULL DEFAULT 0"),
                ("first_message_ignored_at", "ALTER TABLE daily_leads ADD COLUMN first_message_ignored_at TEXT NOT NULL DEFAULT ''"),
            ]
            for col, ddl in migrations:
                if col not in cols:
                    try:
                        await db.execute(ddl)
                    except Exception:
                        pass
            await db.commit()
    except Exception as e:
        print(f"strict profile schema warning: {e!r}")


async def _tp_fm_ensure_dialog_schema(db_path: str) -> None:
    try:
        if callable(globals().get("_tpe_ensure_dialog_schema")):
            await globals()["_tpe_ensure_dialog_schema"](db_path)
            return
    except Exception:
        pass
    try:
        if callable(globals().get("ensure_profile_dialog_table")):
            await globals()["ensure_profile_dialog_table"](db_path)
    except Exception:
        pass
    try:
        async with aiosqlite.connect(str(db_path)) as db:
            cols = await _table_columns(db, "lead_dialog_state")
            migrations = [
                ("age_attempts", "ALTER TABLE lead_dialog_state ADD COLUMN age_attempts INTEGER NOT NULL DEFAULT 0"),
                ("geo_attempts", "ALTER TABLE lead_dialog_state ADD COLUMN geo_attempts INTEGER NOT NULL DEFAULT 0"),
                ("both_attempts", "ALTER TABLE lead_dialog_state ADD COLUMN both_attempts INTEGER NOT NULL DEFAULT 0"),
                ("na_finalized", "ALTER TABLE lead_dialog_state ADD COLUMN na_finalized INTEGER NOT NULL DEFAULT 0"),
                ("na_finalized_at", "ALTER TABLE lead_dialog_state ADD COLUMN na_finalized_at TEXT NOT NULL DEFAULT ''"),
            ]
            for col, ddl in migrations:
                if col not in cols:
                    try:
                        await db.execute(ddl)
                    except Exception:
                        pass
            await db.commit()
    except Exception as e:
        print(f"strict dialog schema warning: {e!r}")


def _tp_fm_message_list(raw: Any) -> List[str]:
    if raw is None:
        return []
    if isinstance(raw, str):
        return [x.strip() for x in re.split(r"[\r\n]+", raw) if x.strip()]
    out: List[str] = []
    try:
        for x in raw:
            sx = str(x or "").strip()
            if sx:
                out.append(sx)
    except Exception:
        pass
    return out


def _tp_fm_messages_with_new(existing_answer_texts: Any, new_text: str) -> List[str]:
    msgs = _tp_fm_message_list(existing_answer_texts)
    nt = str(new_text or "").strip()
    if nt:
        msgs.append(nt)
    return msgs[-30:]


def _tp_fm_profile_context_for_parser(lead_row: Dict[str, Any]) -> Dict[str, Any]:
    # Do not pass old age/city/country/evidence to extractor. Those fields may contain the first client message.
    # Keep only harmless identifiers/manual flags.
    return {
        "manager_key": str((lead_row or {}).get("manager_key") or MANAGER_RUNTIME_KEY),
        "lead_date": str((lead_row or {}).get("lead_date") or _kyiv_now().date().isoformat()),
        "chat_id": int((lead_row or {}).get("chat_id") or 0),
        "manual_status_override": int((lead_row or {}).get("manual_status_override") or 0),
    }


def _tp_fm_age_known(profile: Dict[str, Any]) -> bool:
    if str((profile or {}).get("negative_age_marker") or "").strip():
        return True
    if (profile or {}).get("age") is not None and str((profile or {}).get("age") or "").strip() != "":
        return True
    if _tp_fm_bool((profile or {}).get("age_confirmed_18_plus")):
        return True
    return False


def _tp_fm_geo_known(profile: Dict[str, Any]) -> bool:
    return bool(str((profile or {}).get("country") or "").strip())


def _tp_fm_missing_category(profile: Dict[str, Any]) -> str:
    age_missing = not _tp_fm_age_known(profile)
    geo_missing = not _tp_fm_geo_known(profile)
    if age_missing and geo_missing:
        return "both"
    if age_missing:
        return "age"
    if geo_missing:
        return "geo"
    return ""


def _tp_fm_pending_fields(reason: str) -> Dict[str, Any]:
    return {
        "status": "unknown",
        "nonliquid_reason": "",
        "profile_done": 0,
        "quality_status": "pending",
        "quality_bucket": "na_pending",
        "quality_reason": reason,
        "quality_confidence": "low",
        "quality_source": "strict_profile_gate_v2",
        "quality_checked_at": _tp_fm_now_iso(),
        "quality_version": _TP_FM_VERSION,
        "profile_decision_reason": reason,
        "needs_review": 0,
        "extraction_method": "strict_gate_v2",
        "extraction_confidence": "low",
    }


def _tp_fm_enforce_complete_profile(parsed: Dict[str, Any]) -> Dict[str, Any]:
    out = dict(parsed or {})
    cat = _tp_fm_missing_category(out)
    if cat:
        reason_map = {
            "age": "Не хватает возраста после вопроса анкеты",
            "geo": "Не хватает гео после вопроса анкеты",
            "both": "Не хватает гео и возраста после вопроса анкеты",
        }
        out.update(_tp_fm_pending_fields(reason_map.get(cat, "Недостаточно данных после вопроса анкеты")))
        if not _tp_fm_age_known(out):
            out["age_confirmed_18_plus"] = 0
            out["age_evidence_text"] = ""
        return out
    return out


async def _tp_fm_load_answer_texts(db_path: str, lead_row: Dict[str, Any], chat_id: int) -> str:
    await _tp_fm_ensure_profile_schema(db_path)
    try:
        async with aiosqlite.connect(str(db_path)) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute(
                "SELECT profile_answer_texts FROM daily_leads WHERE lead_date=? AND manager_key=? AND chat_id=? ORDER BY id DESC LIMIT 1",
                (
                    str((lead_row or {}).get("lead_date") or _kyiv_now().date().isoformat()),
                    str((lead_row or {}).get("manager_key") or MANAGER_RUNTIME_KEY),
                    int(chat_id),
                ),
            )
            row = await cur.fetchone()
            if row:
                return str(row["profile_answer_texts"] or "")
    except Exception:
        pass
    return str((lead_row or {}).get("profile_answer_texts") or "")


async def _apply_profile_from_text(db_path: str, lead_row: Dict[str, Any], text: str) -> Dict[str, Any]:  # type: ignore[override]
    chat_id = int((lead_row or {}).get("chat_id") or 0)
    if chat_id <= 0:
        return dict(lead_row or {})

    # Hard gate: no parsing before bot/manual profile question.
    gate_auto = int((lead_row or {}).get("profile_question_sent") or 0) == 1
    try:
        gate_manual = await _capture_is_open(db_path, chat_id)
    except Exception:
        gate_manual = False
    if not (gate_auto or gate_manual):
        # Mark that the first/client-start message was intentionally ignored, but do not store it as evidence.
        try:
            await _tp_fm_ensure_profile_schema(db_path)
            await _update_daily_lead_fields(
                db_path,
                lead_date=str((lead_row or {}).get("lead_date") or _kyiv_now().date().isoformat()),
                manager_key=str((lead_row or {}).get("manager_key") or MANAGER_RUNTIME_KEY),
                chat_id=chat_id,
                first_message_ignored=1,
                first_message_ignored_at=_tp_fm_now_iso(),
                profile_raw_text="",
                profile_evidence_text="",
                age_evidence_text="",
                geo_evidence_text="",
                age_confirmed_18_plus=0,
            )
        except Exception:
            pass
        return dict(lead_row or {})

    raw_text = str(text or "").strip()
    if not raw_text:
        return dict(lead_row or {})

    try:
        pe = _tpe_import_extractor() if callable(globals().get("_tpe_import_extractor")) else __import__("profile_extractor")
        await _tp_fm_ensure_profile_schema(db_path)
        answer_texts_old = await _tp_fm_load_answer_texts(db_path, lead_row, chat_id)
        answer_msgs = _tp_fm_messages_with_new(answer_texts_old, raw_text)
        answer_joined = "\n".join([x for x in answer_msgs if str(x or "").strip()])[-4000:]

        # Parse only post-question answers. Previous profile fields are not trusted because they may come from the first message.
        parsed = pe.extract_profile_v2(answer_msgs, _tp_fm_profile_context_for_parser(lead_row))
        parsed = _tp_fm_enforce_complete_profile(parsed)
        parsed["profile_answer_texts"] = answer_joined
        parsed["profile_raw_text"] = answer_joined
        parsed["profile_evidence_text"] = answer_joined
        parsed["profile_answered_at"] = _tp_fm_now_iso()
        parsed["first_message_ignored"] = 1
        parsed["profile_extraction_version"] = _TP_FM_VERSION
        if not str(parsed.get("age_evidence_text") or "").strip():
            parsed["age_confirmed_18_plus"] = 0

        if int((lead_row or {}).get("manual_status_override") or 0) == 1:
            for k in ("status", "nonliquid_reason", "profile_done", "quality_status", "quality_bucket", "quality_reason", "quality_confidence", "quality_source", "quality_version"):
                parsed.pop(k, None)

        try:
            if callable(globals().get("_tpe_insert_profile_audit")):
                await globals()["_tpe_insert_profile_audit"](db_path, dict(lead_row or {}), parsed)
        except Exception:
            pass

        if callable(globals().get("_tpe_direct_update_daily")):
            await globals()["_tpe_direct_update_daily"](
                db_path,
                lead_date=str((lead_row or {}).get("lead_date") or _kyiv_now().date().isoformat()),
                manager_key=str((lead_row or {}).get("manager_key") or MANAGER_RUNTIME_KEY),
                chat_id=chat_id,
                **parsed,
            )
        else:
            await _update_daily_lead_fields(
                db_path,
                lead_date=str((lead_row or {}).get("lead_date") or _kyiv_now().date().isoformat()),
                manager_key=str((lead_row or {}).get("manager_key") or MANAGER_RUNTIME_KEY),
                chat_id=chat_id,
                **parsed,
            )

        if gate_manual:
            try:
                await _decrement_capture(db_path, chat_id)
            except Exception:
                pass
        if int(parsed.get("profile_done") or 0) == 1:
            try:
                await _close_capture_if_done(db_path, chat_id)
            except Exception:
                pass
        out = dict(lead_row or {})
        out.update(parsed)
        return out
    except Exception as e:
        print(f"strict profile gate v2 error: {e!r}")
        # Fail closed: never fall back to old parser when it could use the first message.
        return dict(lead_row or {})


def _tp_fm_sent_keys(state: Dict[str, Any]) -> List[str]:
    raw = (state or {}).get("sent_template_keys") or "[]"
    try:
        data = _tp_fm_json.loads(str(raw))
        if isinstance(data, list):
            return [str(x) for x in data if str(x).strip()]
    except Exception:
        pass
    return []


def _tp_fm_pick_template(category: str, state: Dict[str, Any]) -> Tuple[str, str]:
    fallbacks = {
        "missing_age": [
            "Город есть, спасибо. Подскажите, пожалуйста, сколько вам полных лет.",
            "По локации понял. Осталось уточнить возраст, сколько вам полных лет?",
            "Спасибо, город есть. Напишите, пожалуйста, ваш возраст полных лет.",
        ],
        "missing_geo": [
            "Возраст есть, спасибо. Напишите, пожалуйста, где вы сейчас находитесь.",
            "По возрасту понял. Осталось уточнить ваш текущий город.",
            "Хорошо, возраст есть. Подскажите, пожалуйста, город, где вы сейчас находитесь.",
        ],
        "missing_both": [
            "Напишите, пожалуйста, где вы сейчас находитесь и сколько вам полных лет.",
            "Для подбора нужен ваш текущий город и возраст. Напишите, пожалуйста, одним сообщением.",
            "Осталось уточнить город и возраст. Напишите, пожалуйста, эти данные одним сообщением.",
        ],
    }
    variants: List[str] = []
    try:
        variants = list((globals().get("PROFILE_DIALOG_TEMPLATES") or {}).get(category) or [])
    except Exception:
        variants = []
    if not variants:
        variants = fallbacks.get(category) or fallbacks["missing_both"]
    used = set(_tp_fm_sent_keys(state))
    for idx, txt in enumerate(variants):
        key = f"strict_v2:{category}:{idx}"
        if key not in used:
            return key, str(txt or "")
    return f"strict_v2:{category}:0", str(variants[0] or "")


def _tp_fm_final_na_fields(reason: str = "NA после 3 уточнений") -> Dict[str, Any]:
    try:
        pe = _tpe_import_extractor() if callable(globals().get("_tpe_import_extractor")) else __import__("profile_extractor")
        fields = pe.build_final_na_fields(reason)
        fields["quality_source"] = "strict_profile_gate_v2_final_na"
        fields["quality_version"] = _TP_FM_VERSION
        fields["profile_extraction_version"] = _TP_FM_VERSION
        return fields
    except Exception:
        return {
            "status": "nonliquid",
            "nonliquid_reason": "NA",
            "profile_done": 1,
            "quality_status": "nonliquid",
            "quality_bucket": "na",
            "quality_reason": reason,
            "quality_confidence": "high",
            "quality_source": "strict_profile_gate_v2_final_na",
            "quality_version": _TP_FM_VERSION,
            "profile_decision_reason": reason,
            "needs_review": 0,
            "extraction_method": "strict_gate_v2",
            "extraction_confidence": "high",
            "profile_extraction_version": _TP_FM_VERSION,
        }


def choose_profile_reply(lead: Dict[str, Any], client_text: str, state: Dict[str, Any]) -> Dict[str, Any]:  # type: ignore[override]
    lead = dict(lead or {})
    state = dict(state or {})
    if int(state.get("na_finalized") or 0) == 1:
        return {"send_text": "", "template_key": "", "intent": "na_finalized", "update_fields": {}}

    cat = _tp_fm_missing_category(lead)

    # F1P.4D D1: read-only diagnostic — observe questionnaire counters, no behavior change
    try:
        _d1_dialog_step = _tp_fm_int(state.get("dialog_step"), 0)
        _d1_age_att = _tp_fm_int(state.get("age_attempts"), 0)
        _d1_geo_att = _tp_fm_int(state.get("geo_attempts"), 0)
        _d1_both_att = _tp_fm_int(state.get("both_attempts"), 0)
        _d1_cat_att = _tp_fm_int(state.get(f"{cat}_attempts"), 0) if cat else 0
        print(
            f"[F1P4D_D1] mk={MANAGER_RUNTIME_KEY!r}"
            f" cid={int(lead.get('chat_id') or 0)}"
            f" step={_d1_dialog_step}"
            f" age_att={_d1_age_att}"
            f" geo_att={_d1_geo_att}"
            f" both_att={_d1_both_att}"
            f" cat={cat!r}"
            f" old_rule={'1' if cat and _d1_cat_att >= 3 else '0'}"
            f" new_rule={'1' if _d1_dialog_step >= 6 else '0'}"
            f" na_fin={int(state.get('na_finalized') or 0)}"
            f" mgr_rep={int(lead.get('manager_replied') or 0)}"
            f" status={lead.get('status')!r}"
            f" qbucket={lead.get('quality_bucket')!r}"
            f" pdone={int(lead.get('profile_done') or 0)}"
        )
    except Exception:
        pass  # F1P.4D D1: fail-open — logging never affects reply path

    if cat:
        max_attempts = 3
        current = _tp_fm_int(state.get(f"{cat}_attempts"), 0)
        if current >= max_attempts:
            return {
                "send_text": "",
                "template_key": "",
                "intent": "final_na",
                "update_fields": _tp_fm_final_na_fields("NA после 3 уточнений: не получены обязательные данные"),
            }
        category = {"age": "missing_age", "geo": "missing_geo", "both": "missing_both"}.get(cat, "missing_both")
        key, txt = _tp_fm_pick_template(category, state)
        return {
            "send_text": txt,
            "template_key": key,
            "intent": category,
            "increment_city_attempt": cat == "geo",
            "update_fields": {},
        }

    if callable(_TP_FM_ORIG_CHOOSE_PROFILE_REPLY):
        return _TP_FM_ORIG_CHOOSE_PROFILE_REPLY(lead, client_text, state)
    return {"send_text": "", "template_key": "", "intent": "", "update_fields": {}}


def _tp_qs_decide(row: Dict[str, Any], *, source: str = "rules") -> Dict[str, Any]:  # type: ignore[override]
    try:
        pe = _tpe_import_extractor() if callable(globals().get("_tpe_import_extractor")) else __import__("profile_extractor")
        raw = _tp_fm_text((row or {}).get("profile_answer_texts") or (row or {}).get("profile_raw_text") or (row or {}).get("profile_evidence_text") or "")
        if not raw:
            return {
                "status": "pending",
                "bucket": "na_pending",
                "reason": "Нет ответов клиента после вопроса анкеты",
                "confidence": "low",
                "source": source or "strict_profile_gate_v2",
                "checked_at": _tp_fm_now_iso(),
                "version": _TP_FM_VERSION,
                "legacy_status": "unknown",
                "legacy_reason": "",
                "profile_done": 0,
            }
        parsed = pe.extract_profile_v2(raw.splitlines(), _tp_fm_profile_context_for_parser(dict(row or {})))
        parsed = _tp_fm_enforce_complete_profile(parsed)
        return {
            "status": parsed.get("quality_status") or parsed.get("status") or "pending",
            "bucket": parsed.get("quality_bucket") or "na_pending",
            "reason": parsed.get("quality_reason") or parsed.get("profile_decision_reason") or "",
            "confidence": parsed.get("quality_confidence") or parsed.get("extraction_confidence") or "low",
            "source": source or "strict_profile_gate_v2",
            "checked_at": _tp_fm_now_iso(),
            "version": _TP_FM_VERSION,
            "legacy_status": parsed.get("status") or "unknown",
            "legacy_reason": parsed.get("nonliquid_reason") or "",
            "profile_done": int(parsed.get("profile_done") or 0),
        }
    except Exception:
        if callable(_TP_FM_ORIG_TP_QS_DECIDE):
            dec = _TP_FM_ORIG_TP_QS_DECIDE(row, source=source)
            if (dec or {}).get("bucket") == "liquid" and not _tp_fm_bool((row or {}).get("age_confirmed_18_plus")):
                dec = dict(dec or {})
                dec.update({"status": "pending", "bucket": "na_pending", "reason": "18+ не подтверждён strict gate", "legacy_status": "unknown", "legacy_reason": "", "profile_done": 0})
            return dec
        return {"status": "pending", "bucket": "na_pending", "reason": "strict_profile_decider_unavailable", "confidence": "low", "source": source, "checked_at": _tp_fm_now_iso(), "version": _TP_FM_VERSION, "legacy_status": "unknown", "legacy_reason": "", "profile_done": 0}


async def _tp_fm_ensure_presence_schema() -> None:
    parent = os.path.dirname(TPILOT_DB_PATH)
    if parent:
        os.makedirs(parent, exist_ok=True)
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        await db.execute("PRAGMA journal_mode=WAL;")
        await db.execute("PRAGMA busy_timeout=30000;")
        await db.execute("""
            CREATE TABLE IF NOT EXISTS manager_work_presence_day(
                manager_key TEXT NOT NULL DEFAULT '',
                work_date TEXT NOT NULL DEFAULT '',
                state TEXT NOT NULL DEFAULT 'not_started_today',
                first_activity_utc TEXT NOT NULL DEFAULT '',
                last_activity_utc TEXT NOT NULL DEFAULT '',
                unique_outbound_chats INTEGER NOT NULL DEFAULT 0,
                activated_at_utc TEXT NOT NULL DEFAULT '',
                source TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT '',
                PRIMARY KEY(manager_key, work_date)
            );
        """)
        await db.execute("""
            CREATE TABLE IF NOT EXISTS manager_work_presence_events(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                manager_key TEXT NOT NULL DEFAULT '',
                work_date TEXT NOT NULL DEFAULT '',
                chat_id INTEGER NOT NULL DEFAULT 0,
                message_id INTEGER NOT NULL DEFAULT 0,
                event_utc TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL DEFAULT '',
                UNIQUE(manager_key, chat_id, message_id)
            );
        """)
        await db.execute("""
            CREATE TABLE IF NOT EXISTS manager_work_presence_audit(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                created_at TEXT NOT NULL DEFAULT '',
                manager_key TEXT NOT NULL DEFAULT '',
                work_date TEXT NOT NULL DEFAULT '',
                old_state TEXT NOT NULL DEFAULT '',
                new_state TEXT NOT NULL DEFAULT '',
                reason TEXT NOT NULL DEFAULT '',
                unique_outbound_chats INTEGER NOT NULL DEFAULT 0,
                event_chat_id INTEGER NOT NULL DEFAULT 0,
                event_message_id INTEGER NOT NULL DEFAULT 0
            );
        """)
        await db.execute("CREATE INDEX IF NOT EXISTS mwp_events_lookup_idx ON manager_work_presence_events(manager_key, work_date, event_utc);")
        await db.execute("CREATE INDEX IF NOT EXISTS mwp_audit_lookup_idx ON manager_work_presence_audit(manager_key, work_date, id);")
        await db.commit()


async def _tp_fm_record_presence_audit(db, manager_key: str, work_date: str, old_state: str, new_state: str, reason: str, unique_chats: int, chat_id: int, message_id: int) -> None:
    try:
        await db.execute("""
            INSERT INTO manager_work_presence_audit(created_at, manager_key, work_date, old_state, new_state, reason, unique_outbound_chats, event_chat_id, event_message_id)
            VALUES(?,?,?,?,?,?,?,?,?)
        """, (_tp_fm_now_iso(), manager_key, work_date, old_state, new_state, reason, int(unique_chats or 0), int(chat_id or 0), int(message_id or 0)))
    except Exception:
        pass


async def _tp_fm_record_manual_outbound_presence(manager_key: str, chat_id: int, message_id: int = 0) -> None:
    key = _tp_gq_norm_key(manager_key or MANAGER_RUNTIME_KEY) if callable(globals().get("_tp_gq_norm_key")) else str(manager_key or MANAGER_RUNTIME_KEY).strip().lower()
    if not key or int(chat_id or 0) <= 0:
        return
    now_local = _kyiv_now()
    if not _tp_fm_in_presence_window(now_local):
        return
    work_date = _tp_fm_work_date(now_local)
    now_iso = _tp_fm_now_iso()
    cutoff_utc = (_tp_utc_now().replace(microsecond=0) - timedelta(minutes=int(TP_FM_WORK_PRESENCE_WINDOW_MINUTES))).isoformat()
    await _tp_fm_ensure_presence_schema()
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        await db.execute("PRAGMA busy_timeout=30000;")
        await db.execute("""
            INSERT OR IGNORE INTO manager_work_presence_events(manager_key, work_date, chat_id, message_id, event_utc, created_at)
            VALUES(?,?,?,?,?,?)
        """, (key, work_date, int(chat_id), int(message_id or 0), now_iso, now_iso))
        cur = await db.execute("""
            SELECT COUNT(DISTINCT chat_id) AS cnt
            FROM manager_work_presence_events
            WHERE manager_key=? AND work_date=? AND event_utc>=?
        """, (key, work_date, cutoff_utc))
        row = await cur.fetchone()
        unique_chats = int((row["cnt"] if row else 0) or 0)
        cur = await db.execute("SELECT * FROM manager_work_presence_day WHERE manager_key=? AND work_date=?", (key, work_date))
        old = await cur.fetchone()
        old_state = str((old["state"] if old else "") or "not_started_today")
        new_state = "active_today" if unique_chats >= int(TP_FM_WORK_PRESENCE_MIN_UNIQUE_CHATS) else old_state
        if old_state == "active_today":
            new_state = "active_today"
        first_activity = str((old["first_activity_utc"] if old else "") or now_iso)
        activated_at = str((old["activated_at_utc"] if old else "") or (now_iso if new_state == "active_today" else ""))
        if not old:
            await db.execute("""
                INSERT INTO manager_work_presence_day(manager_key, work_date, state, first_activity_utc, last_activity_utc, unique_outbound_chats, activated_at_utc, source, updated_at)
                VALUES(?,?,?,?,?,?,?,?,?)
            """, (key, work_date, new_state, first_activity, now_iso, unique_chats, activated_at, "manual_outbound_activity", now_iso))
            await _tp_fm_record_presence_audit(db, key, work_date, "", new_state, "first_manual_outbound", unique_chats, chat_id, message_id)
        else:
            await db.execute("""
                UPDATE manager_work_presence_day
                SET state=?, first_activity_utc=?, last_activity_utc=?, unique_outbound_chats=?, activated_at_utc=?, source=?, updated_at=?
                WHERE manager_key=? AND work_date=?
            """, (new_state, first_activity, now_iso, unique_chats, activated_at, "manual_outbound_activity", now_iso, key, work_date))
            if new_state != old_state:
                await _tp_fm_record_presence_audit(db, key, work_date, old_state, new_state, "presence_threshold_reached", unique_chats, chat_id, message_id)
        await db.commit()


async def _tp_fm_get_presence_state(manager_key: str, work_status: Dict[str, Any], now_local: Optional[datetime] = None) -> Dict[str, Any]:
    key = _tp_gq_norm_key(manager_key or MANAGER_RUNTIME_KEY) if callable(globals().get("_tp_gq_norm_key")) else str(manager_key or MANAGER_RUNTIME_KEY).strip().lower()
    now_local = now_local or _kyiv_now()
    status = str((work_status or {}).get("status") or "").strip().lower()
    if status == "worknow":
        return {"state": "manual_day_forced", "effective_window": "day", "reason": "manual_worknow"}
    if not _tp_fm_in_presence_window(now_local):
        return {"state": "outside_presence_window", "effective_window": "night", "reason": "outside_0750_1700"}
    await _tp_fm_ensure_presence_schema()
    work_date = _tp_fm_work_date(now_local)
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM manager_work_presence_day WHERE manager_key=? AND work_date=?", (key, work_date))
        row = await cur.fetchone()
        state = str((row["state"] if row else "") or "not_started_today")
    if state == "active_today":
        return {"state": state, "effective_window": "day", "reason": "manager_active_today"}
    return {"state": state, "effective_window": "night", "reason": "manager_not_started_today"}


async def _tp_fm_audit(manager_key: str, chat_id: int, **kwargs: Any) -> None:
    try:
        fn = globals().get("_tp_ae_audit")
        if callable(fn):
            await fn(manager_key, chat_id, **kwargs)
    except Exception:
        pass


async def _record_incoming_from_manager(event: events.NewMessage.Event) -> None:  # type: ignore[override]
    if not CONTROLLER_MODE and MANAGER_RUNTIME_KEY and getattr(event, "is_private", False) and getattr(event, "out", False):
        try:
            chat_id = int(event.chat_id or 0)
            msg_id = int(getattr(getattr(event, "message", None), "id", 0) or 0)
            text = str(getattr(event, "raw_text", None) or "").strip()
            is_program = False
            try:
                is_program = bool(callable(globals().get("_is_program_sent")) and globals()["_is_program_sent"](chat_id, msg_id))
            except Exception:
                is_program = False
            if chat_id > 0 and text and not is_program:
                await _tp_fm_record_manual_outbound_presence(MANAGER_RUNTIME_KEY, chat_id, msg_id)
        except Exception as e:
            print(f"work presence outbound track error: {e!r}")
    if callable(_TP_FM_ORIG_RECORD_INCOMING):
        return await _TP_FM_ORIG_RECORD_INCOMING(event)
    return None


# --- TPILOT CLOSER SELF-SERVICE SETTINGS 20260713 START --------------------
# ManagerBot's closer-only self-service settings screen (manager_bot.py's own
# "TPILOT CLOSER SELF-SERVICE SETTINGS" block) writes per-manager greeting/
# away texts to the standard 2-column settings KV (closer_greeting_text_{mk}
# / closer_away_text_{mk}) and writes the work window directly into the
# EXISTING manager_client_message_schedule table -- so the work-window part
# needs zero changes here, _tp_gq_get_schedule already reads that table as
# a per-manager override. This block only adds the TEXT lookup: a small,
# role-gated helper wired into the 3 existing content_text call sites below.
# Only manager_key rows with role='closer' in `managers` are ever affected;
# every other manager keeps using the shared default content_text exactly as
# before (the role check returns False immediately for them, before any KV
# read happens). No schema change, no new tables.

_TP_CLOSER_ROLE_CACHE: Dict[str, Any] = {}
_TP_CLOSER_ROLE_CACHE_TTL_SEC = 300.0  # role changes are rare; a stale hit self-heals within 5 min


def _tp_is_closer_manager(manager_key: str) -> bool:
    mk = _tp_gq_norm_key(manager_key) if callable(globals().get("_tp_gq_norm_key")) else str(manager_key or "").strip().lower()
    if not mk:
        return False
    now = time.monotonic()
    cached = _TP_CLOSER_ROLE_CACHE.get(mk)
    if cached and (now - cached[1]) < _TP_CLOSER_ROLE_CACHE_TTL_SEC:
        return bool(cached[0])
    import sqlite3 as _tp_closer_sqlite3
    is_closer = False
    try:
        con = _tp_closer_sqlite3.connect(TPILOT_DB_PATH, timeout=10)
        try:
            row = con.execute("SELECT role FROM managers WHERE manager_key=?", (mk,)).fetchone()
            is_closer = bool(row) and str(row[0] or "").strip().lower() == "closer"
        finally:
            con.close()
    except Exception:
        is_closer = False
    _TP_CLOSER_ROLE_CACHE[mk] = (is_closer, now)
    return is_closer


def _tp_closer_setting_get(key: str) -> str:
    import sqlite3 as _tp_closer_sqlite3
    try:
        con = _tp_closer_sqlite3.connect(TPILOT_DB_PATH, timeout=10)
        try:
            row = con.execute("SELECT value FROM settings WHERE key=? LIMIT 1", (str(key),)).fetchone()
            return str(row[0] or "") if row else ""
        finally:
            con.close()
    except Exception:
        return ""


def _tp_closer_text(manager_key: str, content_key: str, default_text: str) -> str:
    """If manager_key is role='closer' AND has a non-empty custom text for
    content_key ('profile_question' -> greeting, 'offline_notice' -> away),
    return it; otherwise return default_text completely unchanged. Never
    raises -- any failure silently falls back to default_text, matching
    the existing content_text call sites' own defensive style."""
    try:
        mk = _tp_gq_norm_key(manager_key) if callable(globals().get("_tp_gq_norm_key")) else str(manager_key or "").strip().lower()
        if not mk or not _tp_is_closer_manager(mk):
            return default_text
        if content_key == "profile_question":
            setting_key = f"closer_greeting_text_{mk}"
        elif content_key == "offline_notice":
            setting_key = f"closer_away_text_{mk}"
        else:
            return default_text
        custom = _tp_closer_setting_get(setting_key).strip()
        return custom if custom else default_text
    except Exception:
        return default_text

# --- TPILOT CLOSER SELF-SERVICE SETTINGS 20260713 END -----------------------


# --- TPILOT CLOSER AUTOMATION ISOLATION + STOPWORD GATE 20260716 START ------
# Single fail-closed gate checked immediately before every automatic
# lead-facing send. Precedence: (1) permanent per-lead stop word -> deny
# every kind, including closer greetings; (2) closer manager -> allow ONLY
# day_greeting/night_greeting, and only when that closer's own toggle is ON
# and their custom text is non-empty -- every other kind (questionnaire,
# profile_reminder, autodozhim, llm) is denied unconditionally for closers;
# (3) ordinary manager -> allowed (existing per-path gates downstream still
# apply as before). Any exception denies. No secrets/message text logged --
# only a bounded reason keyword.
_TP_LEAD_GATE_KINDS = {"day_greeting", "night_greeting", "questionnaire", "profile_reminder", "autodozhim", "llm"}


async def _lead_automation_gate(manager_key: str, chat_id: int, kind: str, state: Optional[Dict[str, Any]] = None) -> Tuple[bool, str]:
    try:
        mk = _tp_gq_norm_key(manager_key) if callable(globals().get("_tp_gq_norm_key")) else str(manager_key or "").strip().lower()
        cid = int(chat_id or 0)
        if not mk or cid <= 0:
            return False, "invalid_target"

        st = state
        if st is None:
            try:
                st = await _get_auto_state(DB_PATH, cid)
            except Exception:
                st = {}

        if int((st or {}).get("automation_stopped") or 0) == 1:
            return False, "manual_stop_word"

        if _tp_is_closer_manager(mk):
            if kind == "day_greeting":
                flag_key = f"closer_day_greeting_enabled_{mk}"
                text_key = f"closer_greeting_text_{mk}"
            elif kind == "night_greeting":
                flag_key = f"closer_night_greeting_enabled_{mk}"
                text_key = f"closer_away_text_{mk}"
            else:
                return False, "closer_denied"
            enabled = str(_tp_closer_setting_get(flag_key) or "").strip() == "1"
            if not enabled:
                return False, "closer_toggle_off"
            custom_text = str(_tp_closer_setting_get(text_key) or "").strip()
            if not custom_text:
                return False, "closer_text_empty"
            return True, "closer_allowed"

        return True, "ordinary_manager"
    except Exception:
        return False, "gate_error"
# --- TPILOT CLOSER AUTOMATION ISOLATION + STOPWORD GATE 20260716 END --------


async def _maybe_auto_reply_to_lead(lead_row: Dict[str, Any], state: Dict[str, Any], work: Dict[str, Any]) -> None:  # type: ignore[override]
    chat_id = int((lead_row or {}).get("chat_id") or 0)
    manager_key = _tp_gq_norm_key((lead_row or {}).get("manager_key") or MANAGER_RUNTIME_KEY) if callable(globals().get("_tp_gq_norm_key")) else str((lead_row or {}).get("manager_key") or MANAGER_RUNTIME_KEY).strip().lower()
    if chat_id <= 0 or not manager_key:
        return

    settings = await _tp_gq_get_settings(manager_key) if callable(globals().get("_tp_gq_get_settings")) else {"greeting_enabled": 1, "questionnaire_enabled": 0}
    schedule = await _tp_gq_get_schedule(manager_key) if callable(globals().get("_tp_gq_get_schedule")) else {"day_start": "08:00", "day_end": "17:00", "night_start": "17:00", "night_end": "08:00"}
    now_local = _kyiv_now()
    base_window, window_label, night_key = _tp_gq_window_now(schedule, now_local) if callable(globals().get("_tp_gq_window_now")) else ("day", "Дневное", "")
    presence = await _tp_fm_get_presence_state(manager_key, work or {}, now_local)

    # Client-facing day/night mode is based only on the schedule.
    # Presence is collected for audit/internal state and must not convert scheduled day into night.
    window = base_window
    presence_reason = str(presence.get("reason") or "")
    status = str((work or {}).get("status") or "online").strip().lower()

    try:
        await _update_daily_lead_fields(
            DB_PATH,
            lead_date=str((lead_row or {}).get("lead_date") or now_local.date().isoformat()),
            manager_key=manager_key,
            chat_id=chat_id,
            manager_work_status=f"{status}|{window}|presence={presence.get('state')}|reason={presence_reason}",
        )
    except Exception:
        pass

    try:
        blocked = bool(callable(globals().get("_tp_ae_silent_blocked")) and await globals()["_tp_ae_silent_blocked"](manager_key))
    except Exception:
        blocked = False
    if blocked:
        await _tp_fm_audit(manager_key, chat_id, action="skipped", reason="emergency_silence", window_kind=window, settings=settings, lead_row=lead_row, state=state, extra=presence_reason)
        return

    if int((settings or {}).get("greeting_enabled") or 0) != 1:
        await _tp_fm_audit(manager_key, chat_id, action="skipped", reason="greeting_off", window_kind=window, settings=settings, lead_row=lead_row, state=state, extra=presence_reason)
        return

    manager_replied = _tp_fm_int((state or {}).get("manager_replied"), 0) == 1 or _tp_fm_int((lead_row or {}).get("manager_replied"), 0) == 1
    if manager_replied:
        await _tp_fm_audit(manager_key, chat_id, action="skipped", reason="manager_replied", window_kind=window, settings=settings, lead_row=lead_row, state=state, extra=presence_reason)
        return

    existing_same = int((lead_row or {}).get("_existing_same_manager_chat") or 0) == 1
    question_sent = _tp_gq_question_sent(lead_row, state) if callable(globals().get("_tp_gq_question_sent")) else (int((lead_row or {}).get("profile_question_sent") or 0) == 1 or int((state or {}).get("profile_question_sent") or 0) == 1)
    questionnaire_on = int((settings or {}).get("questionnaire_enabled") or 0) == 1

    if window in {"gap", "overlap"}:
        await _tp_fm_audit(manager_key, chat_id, action="skipped", reason=f"schedule_{window}", window_kind=window, settings=settings, lead_row=lead_row, state=state, extra=presence_reason)
        return

    if existing_same:
        if window != "night" or not night_key:
            await _tp_fm_audit(manager_key, chat_id, action="skipped", reason="old_client_day_silent", window_kind=window, settings=settings, lead_row=lead_row, state=state, extra=presence_reason)
            return
        already_old = False
        try:
            already_old = bool(await _tp_gq_old_autoresponder_sent(DB_PATH, manager_key, chat_id, night_key)) if callable(globals().get("_tp_gq_old_autoresponder_sent")) else False
        except Exception:
            already_old = False
        if already_old:
            await _tp_fm_audit(manager_key, chat_id, action="skipped", reason="old_client_night_already_sent", window_kind=window, settings=settings, lead_row=lead_row, state=state, extra=presence_reason)
            return
        gate_allowed, gate_reason = await _lead_automation_gate(manager_key, chat_id, "night_greeting", state)
        if not gate_allowed:
            await _tp_fm_audit(manager_key, chat_id, action="skipped", reason=f"automation_gate_{gate_reason}", window_kind=window, settings=settings, lead_row=lead_row, state=state, extra=presence_reason)
            return
        text = _tp_gq_content_text("offline_notice", str(globals().get("OFFLINE_NOTICE_TEXT") or "")) if callable(globals().get("_tp_gq_content_text")) else str(globals().get("OFFLINE_NOTICE_TEXT") or "")
        text = _tp_closer_text(manager_key, "offline_notice", text)
        ok = await _send_manager_private(chat_id, text, human_delay=True, after_first_delay=True, new_dialog=False)
        if ok:
            try:
                await _tp_gq_mark_old_autoresponder_sent(DB_PATH, manager_key, chat_id, night_key)
            except Exception:
                pass
        await _tp_fm_audit(manager_key, chat_id, action="sent_old_client_night_notice" if ok else "send_error", reason="old_client_away_or_night", window_kind=window, settings=settings, lead_row=lead_row, state=state, send_ok=ok, extra=presence_reason)
        return

    if window == "night":
        if not night_key:
            try:
                night_key = _tp_gq_night_key(manager_key, schedule, now_local)
            except Exception:
                night_key = f"{manager_key}:night:{now_local.date().isoformat()}"
        if str((state or {}).get("offline_notice_period_key") or (lead_row or {}).get("offline_notice_period_key") or "") == str(night_key):
            await _tp_fm_audit(manager_key, chat_id, action="skipped", reason="night_notice_already_sent", window_kind=window, settings=settings, lead_row=lead_row, state=state, extra=presence_reason)
            return
        gate_allowed, gate_reason = await _lead_automation_gate(manager_key, chat_id, "night_greeting", state)
        if not gate_allowed:
            await _tp_fm_audit(manager_key, chat_id, action="skipped", reason=f"automation_gate_{gate_reason}", window_kind=window, settings=settings, lead_row=lead_row, state=state, extra=presence_reason)
            return
        text = _tp_gq_content_text("offline_notice", str(globals().get("OFFLINE_NOTICE_TEXT") or "")) if callable(globals().get("_tp_gq_content_text")) else str(globals().get("OFFLINE_NOTICE_TEXT") or "")
        text = _tp_closer_text(manager_key, "offline_notice", text)
        ok = await _send_manager_private(chat_id, text, human_delay=True, new_dialog=True)
        if ok:
            try:
                await _set_daily_offline_sent(lead_row, night_key)
            except Exception:
                pass
        await _tp_fm_audit(manager_key, chat_id, action="sent_night_notice" if ok else "send_error", reason="new_client_away_or_night", window_kind=window, settings=settings, lead_row=lead_row, state=state, send_ok=ok, extra=presence_reason)
        return

    # Effective day: bot asks profile question. Questionnaire switch only controls follow-up clarifications.
    if not question_sent:
        gate_allowed, gate_reason = await _lead_automation_gate(manager_key, chat_id, "day_greeting", state)
        if not gate_allowed:
            await _tp_fm_audit(manager_key, chat_id, action="skipped", reason=f"automation_gate_{gate_reason}", window_kind=window, settings=settings, lead_row=lead_row, state=state, extra=presence_reason)
            return
        text = _tp_gq_content_text("profile_question", str(globals().get("PROFILE_QUESTION_TEXT") or "")) if callable(globals().get("_tp_gq_content_text")) else str(globals().get("PROFILE_QUESTION_TEXT") or "")
        text = _tp_closer_text(manager_key, "profile_question", text)
        ok = await _send_manager_private(chat_id, text, human_delay=True, new_dialog=True)
        if ok:
            try:
                await _set_daily_question_sent(lead_row)
            except Exception:
                pass
        await _tp_fm_audit(manager_key, chat_id, action="sent_day_greeting" if ok else "send_error", reason="day_new_client_active_manager", window_kind=window, settings=settings, lead_row=lead_row, state=state, send_ok=ok, extra=presence_reason)
        return

    if questionnaire_on:
        await _tp_fm_audit(manager_key, chat_id, action="questionnaire_followup_attempt", reason="questionnaire_on", window_kind=window, settings=settings, lead_row=lead_row, state=state, extra=presence_reason)
        await _tp_gq_send_questionnaire_followup(lead_row, state, chat_id)
    else:
        await _tp_fm_audit(manager_key, chat_id, action="skipped", reason="questionnaire_off_after_greeting", window_kind=window, settings=settings, lead_row=lead_row, state=state, extra=presence_reason)

# --- TPILOT PROFILE STRICT GATE + WORK PRESENCE V2 20260515 END ---


# --- TPILOT PROFILE PARSE ALWAYS V3 20260516 START ---
# Enterprise rule: incoming-message ingestion/profile parsing is independent from auto-message sending.
# Приветствие off, автоанкета off, аварийная тишина, ночной режим, нет на месте
# блокируют только отправку авто-сообщений клиенту, но НЕ блокируют чтение чата и НЕ блокируют статус.
# First client message is still never profile evidence. All subsequent client incoming messages are evidence.
from typing import Any as _tp_pa_Any, Dict as _tp_pa_Dict, List as _tp_pa_List

_TP_PA_VERSION = "profile_parse_always_v3_20260516"
_TP_PA_ORIG_APPLY_PROFILE_FROM_TEXT = globals().get("_apply_profile_from_text")
_TP_PA_ORIG_TP_QS_DECIDE = globals().get("_tp_qs_decide")


def _tp_pa_now_iso():
    try:
        return _now_utc_iso()
    except Exception:
        try:
            return _tp_utc_now().replace(microsecond=0).isoformat()
        except Exception:
            return ""


def _tp_pa_str(raw):
    return str(raw or "").strip()


def _tp_pa_int(raw, default=0):
    try:
        if raw is None or str(raw).strip() == "":
            return int(default)
        return int(raw)
    except Exception:
        return int(default)


def _tp_pa_bool(raw):
    return str(raw).strip().lower() in {"1", "true", "yes", "да", "on", "вкл"}


async def _tp_pa_table_exists(db, table):
    try:
        cur = await db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (table,))
        return await cur.fetchone() is not None
    except Exception:
        return False


async def _tp_pa_columns(db, table):
    try:
        cur = await db.execute(f"PRAGMA table_info({table})")
        rows = await cur.fetchall()
        return {str(r[1]) for r in rows}
    except Exception:
        return set()


async def _tp_pa_ensure_profile_schema(db_path):
    if not db_path:
        return
    try:
        if callable(globals().get("_tpe_ensure_profile_schema")):
            await globals()["_tpe_ensure_profile_schema"](db_path)
        else:
            await _ensure_daily_leads_table(db_path)
    except Exception:
        pass
    try:
        async with aiosqlite.connect(str(db_path)) as db:
            await db.execute("PRAGMA busy_timeout=30000;")
            cols = await _tp_pa_columns(db, "daily_leads")
            migrations = [
                ("profile_answer_texts", "ALTER TABLE daily_leads ADD COLUMN profile_answer_texts TEXT NOT NULL DEFAULT ''"),
                ("first_message_ignored", "ALTER TABLE daily_leads ADD COLUMN first_message_ignored INTEGER NOT NULL DEFAULT 0"),
                ("first_message_ignored_at", "ALTER TABLE daily_leads ADD COLUMN first_message_ignored_at TEXT NOT NULL DEFAULT ''"),
            ]
            for col, ddl in migrations:
                if col not in cols:
                    try:
                        await db.execute(ddl)
                    except Exception:
                        pass
            await db.commit()
    except Exception as e:
        try:
            print(f"profile parse always schema warning: {e!r}")
        except Exception:
            pass


def _tp_pa_incoming_direction(direction):
    d = str(direction or "").strip().lower()
    if not d:
        return True
    # Treat only explicit outgoing/manager/bot as non-client. Everything else is incoming.
    if d in {"out", "outgoing", "manager", "bot", "self", "me", "исходящее"}:
        return False
    if d.startswith("out"):
        return False
    return True


async def _tp_pa_collect_client_messages_after_first(db_path, chat_id, current_text=""):
    """Return client incoming texts AFTER the first client message.
    This is independent from profile_question_sent/questionnaire/greeting/silence.
    """
    texts = []
    chat_id = int(chat_id or 0)
    if chat_id <= 0 or not db_path:
        return []
    try:
        async with aiosqlite.connect(str(db_path)) as db:
            db.row_factory = aiosqlite.Row
            await db.execute("PRAGMA busy_timeout=30000;")

            if await _tp_pa_table_exists(db, "inbound_events"):
                try:
                    cur = await db.execute("""
                        SELECT text
                        FROM inbound_events
                        WHERE chat_id=? AND COALESCE(text,'')<>''
                        ORDER BY COALESCE(message_date_utc, received_at_utc, created_at, ''), id
                    """, (chat_id,))
                    rows = await cur.fetchall()
                    texts = [_tp_pa_str(r["text"]) for r in rows if _tp_pa_str(r["text"])]
                except Exception:
                    texts = []

            # messages is the fallback and also useful if inbound_events is incomplete.
            if not texts and await _tp_pa_table_exists(db, "messages"):
                try:
                    cols = await _tp_pa_columns(db, "messages")
                    if "direction" in cols:
                        cur = await db.execute("""
                            SELECT direction, text
                            FROM messages
                            WHERE chat_id=? AND COALESCE(text,'')<>''
                            ORDER BY id
                        """, (chat_id,))
                        rows = await cur.fetchall()
                        for r in rows:
                            if _tp_pa_incoming_direction(r["direction"]):
                                t = _tp_pa_str(r["text"])
                                if t:
                                    texts.append(t)
                    else:
                        cur = await db.execute("""
                            SELECT text
                            FROM messages
                            WHERE chat_id=? AND COALESCE(text,'')<>''
                            ORDER BY id
                        """, (chat_id,))
                        rows = await cur.fetchall()
                        texts = [_tp_pa_str(r["text"]) for r in rows if _tp_pa_str(r["text"])]
                except Exception:
                    pass
    except Exception as e:
        try:
            print(f"profile parse always collect messages warning: {e!r}")
        except Exception:
            pass

    ct = _tp_pa_str(current_text)
    if ct:
        # Avoid the common duplicate when the current incoming message was already inserted into inbound_events/messages.
        if not texts or texts[-1] != ct:
            texts.append(ct)

    # Hard rule: first client message is never evidence.
    if len(texts) <= 1:
        return []
    return [x for x in texts[1:] if _tp_pa_str(x)][-30:]


def _tp_pa_import_extractor():
    try:
        if callable(globals().get("_tpe_import_extractor")):
            return globals()["_tpe_import_extractor"]()
    except Exception:
        pass
    import profile_extractor
    return profile_extractor


def _tp_pa_profile_context_for_parser(lead_row):
    return {
        "manager_key": str((lead_row or {}).get("manager_key") or MANAGER_RUNTIME_KEY),
        "lead_date": str((lead_row or {}).get("lead_date") or _kyiv_now().date().isoformat()),
        "chat_id": int((lead_row or {}).get("chat_id") or 0),
        "manual_status_override": int((lead_row or {}).get("manual_status_override") or 0),
    }


def _tp_pa_age_known(profile):
    if _tp_pa_str((profile or {}).get("negative_age_marker")):
        return True
    if (profile or {}).get("age") is not None and _tp_pa_str((profile or {}).get("age")) != "":
        return True
    if _tp_pa_bool((profile or {}).get("age_confirmed_18_plus")):
        return True
    return False


def _tp_pa_geo_known(profile):
    return bool(_tp_pa_str((profile or {}).get("country")))


def _tp_pa_missing_category(profile):
    age_missing = not _tp_pa_age_known(profile)
    geo_missing = not _tp_pa_geo_known(profile)
    if age_missing and geo_missing:
        return "both"
    if age_missing:
        return "age"
    if geo_missing:
        return "geo"
    return ""


def _tp_pa_pending_fields(reason):
    return {
        "status": "unknown",
        "nonliquid_reason": "",
        "profile_done": 0,
        "quality_status": "pending",
        "quality_bucket": "na_pending",
        "quality_reason": reason,
        "quality_confidence": "low",
        "quality_source": "profile_parse_always_v3",
        "quality_checked_at": _tp_pa_now_iso(),
        "quality_version": _TP_PA_VERSION,
        "profile_decision_reason": reason,
        "needs_review": 0,
        "extraction_method": "parse_always_v3",
        "extraction_confidence": "low",
    }


def _tp_pa_enforce_complete_profile(parsed):
    out = dict(parsed or {})
    cat = _tp_pa_missing_category(out)
    if cat:
        reason_map = {
            "age": "Не хватает возраста после первого сообщения клиента",
            "geo": "Не хватает гео после первого сообщения клиента",
            "both": "Не хватает гео и возраста после первого сообщения клиента",
        }
        out.update(_tp_pa_pending_fields(reason_map.get(cat, "Недостаточно данных после первого сообщения клиента")))
        if not _tp_pa_age_known(out):
            out["age_confirmed_18_plus"] = 0
            out["age_evidence_text"] = ""
    return out


async def _tp_pa_update_fields(db_path, lead_row, chat_id, **fields):
    clean = dict(fields or {})
    lead_date = str((lead_row or {}).get("lead_date") or _kyiv_now().date().isoformat())
    manager_key = str((lead_row or {}).get("manager_key") or MANAGER_RUNTIME_KEY)
    try:
        if callable(globals().get("_tpe_direct_update_daily")):
            await globals()["_tpe_direct_update_daily"](db_path, lead_date=lead_date, manager_key=manager_key, chat_id=chat_id, **clean)
            return
    except Exception:
        pass
    try:
        await _update_daily_lead_fields(db_path, lead_date=lead_date, manager_key=manager_key, chat_id=chat_id, **clean)
    except Exception as e:
        try:
            print(f"profile parse always update warning: {e!r}")
        except Exception:
            pass


async def _apply_profile_from_text(db_path, lead_row, text):  # type: ignore[override]
    chat_id = int((lead_row or {}).get("chat_id") or 0)
    if chat_id <= 0:
        return dict(lead_row or {})

    raw_text = _tp_pa_str(text)
    await _tp_pa_ensure_profile_schema(db_path)

    answer_msgs = await _tp_pa_collect_client_messages_after_first(db_path, chat_id, raw_text)

    # No second/client-after-start message yet: ignore the first message and do not create profile evidence.
    if not answer_msgs:
        try:
            pending = _tp_pa_pending_fields("Нет данных после первого сообщения клиента")
            if not await _autostatus_runtime_enabled():
                for k in (
                    "status", "nonliquid_reason", "profile_done",
                    "quality_status", "quality_bucket", "quality_reason", "quality_confidence",
                    "quality_source", "quality_version", "profile_decision_reason",
                ):
                    pending.pop(k, None)
            await _tp_pa_update_fields(
                db_path,
                lead_row,
                chat_id,
                first_message_ignored=1,
                first_message_ignored_at=_tp_pa_now_iso(),
                profile_answer_texts="",
                profile_raw_text="",
                profile_evidence_text="",
                age_evidence_text="",
                geo_evidence_text="",
                age_confirmed_18_plus=0,
                **pending,
            )
        except Exception:
            pass
        out = dict(lead_row or {})
        out.update({"first_message_ignored": 1, "profile_answer_texts": ""})
        return out

    try:
        pe = _tp_pa_import_extractor()
        answer_joined = "\n".join([_tp_pa_str(x) for x in answer_msgs if _tp_pa_str(x)])[-4000:]

        parsed = pe.extract_profile_v2(answer_msgs, _tp_pa_profile_context_for_parser(lead_row))
        parsed = _tp_pa_enforce_complete_profile(parsed)

        parsed["profile_answer_texts"] = answer_joined
        parsed["profile_raw_text"] = answer_joined
        parsed["profile_evidence_text"] = answer_joined
        parsed["profile_answered_at"] = _tp_pa_now_iso()
        parsed["first_message_ignored"] = 1
        parsed["first_message_ignored_at"] = str((lead_row or {}).get("first_message_ignored_at") or _tp_pa_now_iso())
        parsed["profile_extraction_version"] = _TP_PA_VERSION
        if not _tp_pa_str(parsed.get("age_evidence_text")):
            parsed["age_confirmed_18_plus"] = 0

        if int((lead_row or {}).get("manual_status_override") or 0) == 1 or not await _autostatus_runtime_enabled():
            for k in (
                "status", "nonliquid_reason", "profile_done",
                "quality_status", "quality_bucket", "quality_reason", "quality_confidence",
                "quality_source", "quality_version", "profile_decision_reason",
            ):
                parsed.pop(k, None)

        try:
            if callable(globals().get("_tpe_insert_profile_audit")):
                await globals()["_tpe_insert_profile_audit"](db_path, dict(lead_row or {}), parsed)
        except Exception:
            pass

        await _tp_pa_update_fields(db_path, lead_row, chat_id, **parsed)

        out = dict(lead_row or {})
        out.update(parsed)
        return out
    except Exception as e:
        try:
            print(f"profile parse always v3 error: {e!r}")
        except Exception:
            pass
        # Fail closed: never call the old parser because old parser can use the first message as evidence.
        return dict(lead_row or {})


def _tp_qs_decide(row, *, source="rules"):  # type: ignore[override]
    try:
        pe = _tp_pa_import_extractor()
        raw = _tp_pa_str((row or {}).get("profile_answer_texts") or "")
        if not raw:
            # Do not claim that the bot asked the questionnaire when it did not.
            reason = "Нет данных пос��е первого сообщения клиента"
            if _tp_pa_int((row or {}).get("profile_question_sent"), 0) == 1:
                reason = "Нет ответов клиента после вопроса анкеты"
            return {
                "status": "pending",
                "bucket": "na_pending",
                "reason": reason,
                "confidence": "low",
                "source": source or "profile_parse_always_v3",
                "checked_at": _tp_pa_now_iso(),
                "version": _TP_PA_VERSION,
                "legacy_status": "unknown",
                "legacy_reason": "",
                "profile_done": 0,
            }
        parsed = pe.extract_profile_v2(raw.splitlines(), _tp_pa_profile_context_for_parser(dict(row or {})))
        parsed = _tp_pa_enforce_complete_profile(parsed)
        return {
            "status": parsed.get("quality_status") or parsed.get("status") or "pending",
            "bucket": parsed.get("quality_bucket") or "na_pending",
            "reason": parsed.get("quality_reason") or parsed.get("profile_decision_reason") or "",
            "confidence": parsed.get("quality_confidence") or parsed.get("extraction_confidence") or "low",
            "source": source or "profile_parse_always_v3",
            "checked_at": _tp_pa_now_iso(),
            "version": _TP_PA_VERSION,
            "legacy_status": parsed.get("status") or "unknown",
            "legacy_reason": parsed.get("nonliquid_reason") or "",
            "profile_done": int(parsed.get("profile_done") or 0),
        }
    except Exception as e:
        try:
            print(f"profile parse always qs decide warning: {e!r}")
        except Exception:
            pass
        if callable(_TP_PA_ORIG_TP_QS_DECIDE):
            try:
                dec = _TP_PA_ORIG_TP_QS_DECIDE(row, source=source)
                if (dec or {}).get("bucket") == "liquid" and not _tp_pa_bool((row or {}).get("age_confirmed_18_plus")):
                    dec = dict(dec or {})
                    dec.update({
                        "status": "pending",
                        "bucket": "na_pending",
                        "reason": "18+ не подтверждён parse_always_v3",
                        "legacy_status": "unknown",
                        "legacy_reason": "",
                        "profile_done": 0,
                    })
                return dec
            except Exception:
                pass
        return {
            "status": "pending",
            "bucket": "na_pending",
            "reason": "profile_parse_always_decider_unavailable",
            "confidence": "low",
            "source": source or "profile_parse_always_v3",
            "checked_at": _tp_pa_now_iso(),
            "version": _TP_PA_VERSION,
            "legacy_status": "unknown",
            "legacy_reason": "",
            "profile_done": 0,
        }

# --- TPILOT PROFILE PARSE ALWAYS V3 20260516 END ---


# --- TPILOT DOWNTIME CATCH-UP V1 20260521 START ---
# Processes missed inbound private Telegram messages after manager restart.
# Hard rules:
# - Max 48h window. Manager runtime only (not controller).
# - Private user dialogs only; skip groups, channels, bots.
# - No auto-replies, questionnaire, offline, UA, or followup sends during catch-up.
# - Passive profile parsing and status updates work normally.
# - First client message is never profile evidence (delegated to _apply_profile_from_text).
# - Original Telegram message date used as first_seen_utc, not restart time.
# - Three-way idempotency: inserted / already-processed / recovered-unprocessed.

_TP_CATCHUP_VERSION = "downtime_catchup_v1_20260521"
_TP_CATCHUP_MAX_HOURS = 48
_TP_CATCHUP_MAX_DIALOGS = 500
_TP_CATCHUP_MAX_MESSAGES_PER_DIALOG = 50
_TP_CATCHUP_STARTUP_DELAY_SEC = 15
_TP_CATCHUP_CONNECT_RETRIES = 10
_TP_CATCHUP_CONNECT_INTERVAL_SEC = 3


def _tp_catchup_log(manager_key: str, msg: str) -> None:
    """Append one timestamped line to runtime/catchup_<manager_key>.log. Never raises."""
    try:
        ts = _now_utc_iso()
        log_path = BASE_DIR / "runtime" / f"catchup_{_tp_ci_norm_key(manager_key or 'unknown')}.log"
        log_path.parent.mkdir(parents=True, exist_ok=True)
        with log_path.open("a", encoding="utf-8") as _lf:
            _lf.write(f"{ts} {msg}\n")
    except Exception:
        pass


async def _tp_catchup_inbound_processed(db_path: str, event_key: str):
    """Return True if processed=1, False if processed=0, None if row missing or error.

    Used only after _tp_ci_try_insert_inbound_event returned False (row already exists).
    None means the processed state is genuinely unknown; caller should skip defensively.
    """
    try:
        await _tp_ci_ensure_inbound_events_table(db_path)
        async with aiosqlite.connect(str(db_path)) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute(
                "SELECT processed FROM inbound_events WHERE event_key=? LIMIT 1",
                (str(event_key or ""),),
            )
            row = await cur.fetchone()
            if row is None:
                return None
            return bool(int(row["processed"] or 0))
    except Exception:
        return None


async def _tp_catchup_enqueue_manager_card(manager_key: str, chat_id: int, lead_row: Dict[str, Any]) -> None:
    """CATCHUP MANAGERBOT CARD 20260711: after downtime catch-up creates or recovers a
    COUNTABLE daily_leads row, enqueue a ManagerBot lead_card for it so managers still
    see cards for leads that arrived during the outage.

    Scope guarantees (match the live pipeline's contract, see _mb_insert_event /
    _mb_enqueue_after_pipeline):
    * Only COUNTABLE real rows (lead_countable==1 AND a persisted id>0). Every
      duplicate/returning/old_baseline occurrence returns lead_countable=0 from
      _tp_ci_record_daily_lead_event, so the duplicate_card path is NEVER reached from
      catch-up -- historical duplicate spam is impossible.
    * Idempotent: _mb_insert_event does INSERT OR IGNORE keyed on the UNIQUE event_key
      lead_card:<manager_key>:<lead_date>:<chat_id>; a second catch-up run never
      duplicates an existing card and never touches one.
    * Only writes a manager_bot_events row -- no auto-reply/greeting/questionnaire/
      followup, no external send, no daily_leads/lead_status_overrides/manual-status
      writes. ManagerBot remains solely responsible for actual delivery.
    Never raises."""
    try:
        row = dict(lead_row or {})
        if int(row.get("lead_countable") or 0) != 1 or int(row.get("id") or 0) <= 0:
            return
        chat_id = int(chat_id or 0)
        row.setdefault("manager_key", manager_key)
        row.setdefault("chat_id", chat_id)
        lead_date = str(row.get("lead_date") or "").strip()
        if not manager_key or not chat_id or not lead_date:
            return
        event_key = _mb_build_event_key(row)
        already_existing = False
        if _mb_aiosqlite is not None:
            await _mb_ensure_events_table()
            async with _mb_aiosqlite.connect(TPILOT_DB_PATH) as db:
                cur = await db.execute(
                    "SELECT 1 FROM manager_bot_events WHERE event_key=? LIMIT 1", (event_key,)
                )
                already_existing = bool(await cur.fetchone())
        await _mb_insert_event(row)
        if already_existing:
            _tp_catchup_log(manager_key, f"card_enqueue_skipped_existing chat_id={chat_id} lead_date={lead_date} event_key={event_key}")
        else:
            _tp_catchup_log(manager_key, f"card_enqueue_ok chat_id={chat_id} lead_date={lead_date} event_key={event_key}")
    except Exception as exc:
        try:
            _ld = str((lead_row or {}).get("lead_date") or "") if isinstance(lead_row, dict) else ""
            _ek = ""
            try:
                _ek = _mb_build_event_key(dict(lead_row or {}))
            except Exception:
                pass
            _tp_catchup_log(manager_key, f"card_enqueue_error chat_id={chat_id} lead_date={_ld} event_key={_ek} error={exc!r}")
        except Exception:
            pass


async def _tp_catchup_run() -> None:
    """Scan last 48h of missed inbound private messages and process them passively.

    Called as an asyncio task at manager startup. Forbidden actions:
    _record_incoming_from_manager and _maybe_auto_reply_to_lead are never called.
    """
    if CONTROLLER_MODE or not MANAGER_RUNTIME_KEY:
        return

    mk = _tp_ci_norm_key(MANAGER_RUNTIME_KEY)

    # Readiness: startup delay, then connectivity retries.
    await asyncio.sleep(_TP_CATCHUP_STARTUP_DELAY_SEC)
    connected = False
    for _retry in range(_TP_CATCHUP_CONNECT_RETRIES):
        try:
            if client.is_connected():
                connected = True
                break
        except Exception:
            pass
        await asyncio.sleep(_TP_CATCHUP_CONNECT_INTERVAL_SEC)
    if not connected:
        _tp_catchup_log(mk, "catchup_aborted reason=client_not_connected")
        return

    from datetime import timezone as _tz
    _cutoff = datetime.now(tz=_tz.utc) - timedelta(hours=_TP_CATCHUP_MAX_HOURS)
    _t0 = time.monotonic()
    _tp_catchup_log(mk, f"catchup_start manager_key={mk} cutoff={_cutoff.replace(microsecond=0).isoformat()}")

    _dialogs_scanned = 0
    _processed_count = 0
    _skipped_count = 0
    _recovered_count = 0
    _error_count = 0

    try:
        async for _dlg in client.iter_dialogs(limit=_TP_CATCHUP_MAX_DIALOGS):
            # Private user dialogs only.
            try:
                _entity = _dlg.entity
                if not _dlg.is_user:
                    continue
                if getattr(_entity, "bot", False):
                    continue
            except Exception:
                continue

            _chat_id = int(getattr(_dlg, "id", 0) or 0)
            if _chat_id <= 0:
                continue
            _dialogs_scanned += 1

            try:
                _username = str(getattr(_entity, "username", "") or "")
                _first_name = str(getattr(_entity, "first_name", "") or "")
                _last_name = str(getattr(_entity, "last_name", "") or "")
                _contact_full_name = _full_name(_first_name, _last_name)
                _phone = _tp_ci_phone(str(getattr(_entity, "phone", "") or ""))

                # Collect inbound messages in the catch-up window, newest-first, then reverse.
                _msgs_window: list = []
                async for _msg in client.iter_messages(_chat_id, limit=_TP_CATCHUP_MAX_MESSAGES_PER_DIALOG):
                    try:
                        if _msg.out:
                            continue
                        if not _msg.date:
                            continue
                        _msg_dt = _msg.date if _msg.date.tzinfo else _msg.date.replace(tzinfo=_tz.utc)
                        if _msg_dt < _cutoff:
                            break  # newest-first; once past window, stop
                        _msgs_window.append(_msg)
                    except Exception:
                        continue
                _msgs_window.reverse()  # chronological order: oldest first

                for _msg in _msgs_window:
                    _msg_id = 0
                    try:
                        _msg_id = int(_msg.id or 0)
                        _msg_dt = _msg.date if _msg.date.tzinfo else _msg.date.replace(tzinfo=_tz.utc)
                        _msg_utc_iso = _msg_dt.astimezone(_tz.utc).replace(tzinfo=None, microsecond=0).isoformat()
                        _text = str(getattr(_msg, "raw_text", "") or "").strip()
                        _event_key = f"{mk}:{_chat_id}:{_msg_id}"

                        _inserted = await _tp_ci_try_insert_inbound_event(
                            DB_PATH,
                            event_key=_event_key,
                            manager_key=mk,
                            chat_id=_chat_id,
                            message_id=_msg_id,
                            message_date_utc=_msg_utc_iso,
                            username=_username,
                            phone=_phone,
                            full_name=_contact_full_name,
                            text=_text,
                        )

                        if _inserted:
                            # New event: record lead, update profile fields, mark catchup.
                            _, _lead_row = await _tp_ci_record_daily_lead_event(
                                db_path=DB_PATH,
                                manager_key=mk,
                                manager_username=SELF_USERNAME,
                                chat_id=_chat_id,
                                username=_username,
                                full_name=_contact_full_name,
                                phone=_phone,
                                first_seen_utc=_msg_utc_iso,
                            )
                            _lead_row = dict(_lead_row or {})
                            if _text:
                                try:
                                    await _update_daily_lead_fields(
                                        DB_PATH,
                                        lead_date=str(_lead_row.get("lead_date") or _kyiv_now().date().isoformat()),
                                        manager_key=mk,
                                        chat_id=_chat_id,
                                        profile_raw_text=_text[:4000],
                                    )
                                    _lead_row = await _apply_profile_from_text(DB_PATH, _lead_row, _text)
                                except Exception:
                                    pass
                            await _tp_ci_mark_inbound_processed(DB_PATH, _event_key, "catchup")
                            _processed_count += 1
                            _tp_catchup_log(mk, f"processed event_key={_event_key} chat_id={_chat_id} msg_id={_msg_id}")
                            # CATCHUP MANAGERBOT CARD 20260711: enqueue a ManagerBot lead_card
                            # for the restored countable lead (idempotent; countable-only; no send).
                            await _tp_catchup_enqueue_manager_card(mk, _chat_id, _lead_row)

                        else:
                            # Row already exists — apply three-way logic.
                            _proc = await _tp_catchup_inbound_processed(DB_PATH, _event_key)

                            if _proc is True:
                                # Already fully processed — skip.
                                _skipped_count += 1
                                _tp_catchup_log(mk, f"skipped_already_processed event_key={_event_key}")

                            elif _proc is False:
                                # Exists but not processed (interrupted earlier run) — recover.
                                _tp_catchup_log(mk, f"recovering event_key={_event_key} chat_id={_chat_id} msg_id={_msg_id}")
                                _, _lead_row = await _tp_ci_record_daily_lead_event(
                                    db_path=DB_PATH,
                                    manager_key=mk,
                                    manager_username=SELF_USERNAME,
                                    chat_id=_chat_id,
                                    username=_username,
                                    full_name=_contact_full_name,
                                    phone=_phone,
                                    first_seen_utc=_msg_utc_iso,
                                )
                                _lead_row = dict(_lead_row or {})
                                if _text:
                                    try:
                                        await _update_daily_lead_fields(
                                            DB_PATH,
                                            lead_date=str(_lead_row.get("lead_date") or _kyiv_now().date().isoformat()),
                                            manager_key=mk,
                                            chat_id=_chat_id,
                                            profile_raw_text=_text[:4000],
                                        )
                                        _lead_row = await _apply_profile_from_text(DB_PATH, _lead_row, _text)
                                    except Exception:
                                        pass
                                await _tp_ci_mark_inbound_processed(DB_PATH, _event_key, "catchup_recovered")
                                _recovered_count += 1
                                _tp_catchup_log(mk, f"catchup_recovered event_key={_event_key}")
                                # CATCHUP MANAGERBOT CARD 20260711: recover the ManagerBot
                                # lead_card too (idempotent; countable-only; no send).
                                await _tp_catchup_enqueue_manager_card(mk, _chat_id, _lead_row)

                            else:
                                # _proc is None — unknown state; skip defensively.
                                _skipped_count += 1
                                _tp_catchup_log(mk, f"skipped_unknown_processed_state event_key={_event_key}")

                    except FloodWaitError as _fwe:
                        _wait = min(int(getattr(_fwe, "seconds", 60) or 60), 300)
                        _tp_catchup_log(mk, f"flood_wait seconds={_wait} chat_id={_chat_id} msg_id={_msg_id}")
                        await asyncio.sleep(_wait)
                    except Exception as _me:
                        _error_count += 1
                        _tp_catchup_log(mk, f"dialog_error chat_id={_chat_id} msg_id={_msg_id} err={_me!r:.120}")

            except FloodWaitError as _fwe:
                _wait = min(int(getattr(_fwe, "seconds", 60) or 60), 300)
                _tp_catchup_log(mk, f"flood_wait seconds={_wait} chat_id={_chat_id}")
                await asyncio.sleep(_wait)
            except Exception as _de:
                _error_count += 1
                _tp_catchup_log(mk, f"dialog_error chat_id={_chat_id} err={_de!r:.120}")

    except asyncio.CancelledError:
        _tp_catchup_log(mk, "catchup_cancelled")
        raise
    except Exception as _fe:
        _tp_catchup_log(mk, f"catchup_fatal_error err={_fe!r:.200}")

    _elapsed = time.monotonic() - _t0
    _tp_catchup_log(
        mk,
        f"catchup_done dialogs_scanned={_dialogs_scanned} processed={_processed_count} "
        f"skipped={_skipped_count} recovered={_recovered_count} errors={_error_count} "
        f"elapsed_sec={_elapsed:.1f}",
    )


_TP_CATCHUP_ORIG_MAIN = globals().get("main")


async def main() -> None:  # type: ignore[override]
    """Schedule downtime catch-up task for manager runtime, then delegate to previous main()."""
    if MANAGER_RUNTIME_KEY and not CONTROLLER_MODE:
        try:
            client.loop.create_task(_tp_catchup_run())
        except Exception as _e:
            print(f"catchup task start error: {_e!r}")
    if callable(_TP_CATCHUP_ORIG_MAIN):
        await _TP_CATCHUP_ORIG_MAIN()
    else:
        raise RuntimeError("Original main() not available after downtime catch-up patch")

# --- TPILOT DOWNTIME CATCH-UP V1 20260521 END ---



# --- TPILOT MANAGER BOT IMMEDIATE ENQUEUE M2.2 20260531 START ---
# Producer side only.
# New outer wrapper for _record_incoming_from_manager.
# Calls the full original inbound pipeline first, then enqueues a ManagerBot event.
# Best-effort only. Must never break lead processing.

import json as _mb_json
from datetime import datetime as _mb_datetime

try:
    import aiosqlite as _mb_aiosqlite
except Exception:
    _mb_aiosqlite = None

_MB_EVENTS_READY = False


async def _mb_ensure_events_table() -> None:
    global _MB_EVENTS_READY
    if _MB_EVENTS_READY:
        return
    if _mb_aiosqlite is None:
        return

    async with _mb_aiosqlite.connect(TPILOT_DB_PATH) as db:
        try:
            await db.execute("PRAGMA journal_mode=WAL;")
            await db.execute("PRAGMA busy_timeout=30000;")
        except Exception:
            pass

        await db.executescript("""
        CREATE TABLE IF NOT EXISTS manager_bot_events(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_key TEXT UNIQUE NOT NULL DEFAULT '',
            event_type TEXT NOT NULL DEFAULT '',
            manager_key TEXT NOT NULL DEFAULT '',
            chat_id INTEGER NOT NULL DEFAULT 0,
            lead_date TEXT NOT NULL DEFAULT '',
            daily_lead_id INTEGER NOT NULL DEFAULT 0,
            old_status TEXT NOT NULL DEFAULT '',
            new_status TEXT NOT NULL DEFAULT '',
            payload_json TEXT NOT NULL DEFAULT '',
            source TEXT NOT NULL DEFAULT '',
            created_at TEXT NOT NULL DEFAULT ''
        );

        CREATE INDEX IF NOT EXISTS manager_bot_events_type_idx
            ON manager_bot_events(event_type, id);

        CREATE INDEX IF NOT EXISTS manager_bot_events_created_idx
            ON manager_bot_events(created_at);

        CREATE INDEX IF NOT EXISTS manager_bot_events_lead_idx
            ON manager_bot_events(manager_key, chat_id, lead_date);
        """)
        await db.commit()

    _MB_EVENTS_READY = True


def _mb_now_iso() -> str:
    return _tp_utc_now().replace(microsecond=0).isoformat()


def _mb_current_lead_date() -> str:
    # W3.2 D6 (2026-08-01, contract R3): the former
    # `except Exception: _mb_datetime.utcnow().date().isoformat()` substituted a UTC
    # date for the Kyiv business lead_date -- between 00:00 and 02:00/03:00 Kyiv that is
    # the previous day. storage.w3_now() raises loudly by contract; that failure must
    # propagate (every caller is covered by a whole-body handler) and never be papered
    # over with a silently wrong date.
    return _kyiv_now().date().isoformat()


async def _mb_fetch_daily_row_after_pipeline(chat_id: int) -> dict:
    manager_key = str(MANAGER_RUNTIME_KEY or "").strip()
    if not manager_key or not chat_id:
        return {}

    lead_date = _mb_current_lead_date()

    try:
        row = await _tp_qs_fetch_daily_row(DB_PATH, lead_date, manager_key, int(chat_id))
        return dict(row or {})
    except Exception:
        return {}


def _mb_build_event_key(row: dict) -> str:
    manager_key = str(row.get("manager_key") or MANAGER_RUNTIME_KEY or "").strip()
    lead_date = str(row.get("lead_date") or _mb_current_lead_date()).strip()
    chat_id = int(row.get("chat_id") or 0)
    return f"lead_card:{manager_key}:{lead_date}:{chat_id}"


def _mb_build_payload(row: dict) -> str:
    keys = (
        "id",
        "lead_date",
        "manager_key",
        "manager_username",
        "chat_id",
        "username",
        "full_name",
        "phone",
        "first_seen_utc",
        "first_seen_kyiv",
        "status",
        "nonliquid_reason",
        "quality_status",
        "quality_bucket",
        "quality_reason",
        "quality_confidence",
        "contact_kind",
        "lead_countable",
        "duplicate",
        "trash",
        "trash_reason",
        "profile_done",
        "manual_status_override",
        "manual_status_reason",
        "manual_status_by",
        "manual_status_at",
    )
    payload = {k: row.get(k) for k in keys if k in row}
    payload["source"] = "main_m22"
    return _mb_json.dumps(payload, ensure_ascii=False, default=str)


async def _mb_insert_event(row: dict) -> None:
    if not row:
        return
    if _mb_aiosqlite is None:
        return

    await _mb_ensure_events_table()

    manager_key = str(row.get("manager_key") or MANAGER_RUNTIME_KEY or "").strip()
    chat_id = int(row.get("chat_id") or 0)
    lead_date = str(row.get("lead_date") or _mb_current_lead_date()).strip()

    if not manager_key or not chat_id or not lead_date:
        return

    event_key = _mb_build_event_key(row)
    payload_json = _mb_build_payload(row)
    daily_lead_id = int(row.get("id") or 0)
    new_status = str(row.get("quality_bucket") or row.get("status") or "pending")

    async with _mb_aiosqlite.connect(TPILOT_DB_PATH) as db:
        try:
            await db.execute("PRAGMA busy_timeout=30000;")
        except Exception:
            pass

        await db.execute(
            """
            INSERT OR IGNORE INTO manager_bot_events(
                event_key,
                event_type,
                manager_key,
                chat_id,
                lead_date,
                daily_lead_id,
                old_status,
                new_status,
                payload_json,
                source,
                created_at
            )
            VALUES (?, 'lead_card', ?, ?, ?, ?, '', ?, ?, 'main_m22', ?)
            """,
            (
                event_key,
                manager_key,
                chat_id,
                lead_date,
                daily_lead_id,
                new_status,
                payload_json,
                _mb_now_iso(),
            ),
        )
        await db.commit()


async def _mb_enqueue_after_pipeline(chat_id: int) -> None:
    try:
        row = await _mb_fetch_daily_row_after_pipeline(int(chat_id))
        # R1A1-A (F-19): the live path must apply the same countability gate the
        # catch-up path already enforces (see main.py _tp_catchup_enqueue_manager_card,
        # `if int(row.get("lead_countable") or 0) != 1 or int(row.get("id") or 0) <= 0: return`).
        # A daily_leads row existing for today is NOT sufficient -- it may be a
        # non-countable duplicate/returning/old_baseline occurrence, which must fall
        # through to the duplicate_card path below, never an ordinary lead_card.
        if row and int(row.get("lead_countable") or 0) == 1 and int(row.get("id") or 0) > 0:
            # Countable lead → existing normal lead-card path, unchanged.
            await _mb_insert_event(row)
            return
        # M2.11C: no countable daily_leads row for this chat today. It may be a
        # non-countable duplicate / returning / old_baseline occurrence (those
        # intentionally never write daily_leads). Create a ManagerBot
        # duplicate_card so the current manager still sees the repeat contact.
        # This function is the LIVE-only trigger (called solely from the live
        # _record_incoming_from_manager wrapper, never from the catchup loop),
        # so historical duplicates can never be replayed as cards.
        await _mb_enqueue_duplicate_after_pipeline(int(chat_id))
    except Exception as exc:
        try:
            print(f"manager_bot enqueue failed: {exc!r}")
        except Exception:
            pass


# --- TPILOT MANAGER BOT DUPLICATE CARD M2.11C 20260608 START ---
# Live-only ManagerBot duplicate / returning / old_baseline notification.
# Writer hook lives exclusively in _mb_enqueue_after_pipeline (above). Must NOT
# be invoked from _tp_ci_record_daily_lead_event or _mirror_noncountable_partner_event
# (those run during catchup and would spam historical duplicate cards).
# Reads only source-internal tables (known_contacts / inbound_events / managers).
# Never writes daily_leads, partner_lead_events, partner_sent_events, or stats.

def _mb_kyiv_str(utc_iso: str) -> str:
    try:
        return _utc_iso_to_kyiv_dt(str(utc_iso)).strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return ""


def _mb_lookup_manager_label_sync(manager_key: str) -> Tuple[str, str]:
    """Read-only (display_name, username) lookup from the managers table."""
    key = _tp_ci_norm_key(manager_key)
    if not key:
        return "", ""
    try:
        con = _tp_ci_connect(TPILOT_DB_PATH)
        try:
            row = con.execute(
                "SELECT display_name, telegram_username FROM managers WHERE manager_key=? LIMIT 1",
                (key,),
            ).fetchone()
            if not row:
                return "", ""
            return str(row[0] or ""), str(row[1] or "").strip().lstrip("@")
        finally:
            con.close()
    except Exception:
        return "", ""


async def _mb_fetch_current_inbound(chat_id: int) -> dict:
    """Latest inbound_events row for this chat (the just-arrived message) — used
    for current contact PII and the current occurrence timestamp."""
    chat_id = int(chat_id or 0)
    if chat_id <= 0:
        return {}
    try:
        await _tp_ci_ensure_inbound_events_table(DB_PATH)
        async with aiosqlite.connect(DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute(
                """
                SELECT manager_key, message_date_utc, username, full_name, phone
                FROM inbound_events
                WHERE chat_id=?
                ORDER BY message_date_utc DESC, id DESC
                LIMIT 1
                """,
                (chat_id,),
            )
            row = await cur.fetchone()
            return dict(row) if row else {}
    except Exception:
        return {}


async def _mb_fetch_latest_prev_inbound(chat_id: int, current_seen_utc: str) -> dict:
    """Latest inbound_events row strictly before the current occurrence."""
    chat_id = int(chat_id or 0)
    cur_seen = str(current_seen_utc or "")
    if chat_id <= 0 or not cur_seen:
        return {}
    try:
        await _tp_ci_ensure_inbound_events_table(DB_PATH)
        async with aiosqlite.connect(DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute(
                """
                SELECT manager_key, message_date_utc
                FROM inbound_events
                WHERE chat_id=? AND COALESCE(message_date_utc,'')<>'' AND message_date_utc < ?
                ORDER BY message_date_utc DESC, id DESC
                LIMIT 1
                """,
                (chat_id, cur_seen),
            )
            row = await cur.fetchone()
            return dict(row) if row else {}
    except Exception:
        return {}


async def _mb_fetch_duplicate_occurrence_today(manager_key: str, chat_id: int, lead_date: str, current_seen_utc: str) -> Optional[dict]:
    """Decide whether the current no-daily-row occurrence is a cross-manager
    duplicate contact. Returns the occurrence dict ONLY for confirmed cross-manager
    duplicates (first_manager_key is set and differs from current manager_key).
    Same-manager returning leads and unknown-origin leads return None — no card.
    M2.12B: cross-manager-only gate; stable identity fields added to occ."""
    manager_key = _tp_ci_norm_key(manager_key)
    chat_id = int(chat_id or 0)
    if not manager_key or chat_id <= 0:
        return None

    contact = _tp_ci_contact_by_chat_sync(chat_id)
    if not contact:
        return None

    first_seen_global_at = str(contact.get("first_seen_at") or "")
    first_mgr = _tp_ci_norm_key(contact.get("first_manager_key") or "")
    cur_seen = str(current_seen_utc or "")

    # M2.12B cross-manager-only gate.
    # first_manager_key must be non-empty and differ from the current manager.
    # Empty origin → cannot prove cross-manager → silent (no card).
    # Same origin → same-manager returning → silent (no card).
    if not first_mgr:
        return None
    if first_mgr == manager_key:
        return None

    # Require real prior history: either the global first-seen predates the
    # current occurrence, or a strictly-earlier inbound row exists.
    has_prior = False
    try:
        if first_seen_global_at and cur_seen and first_seen_global_at < cur_seen:
            has_prior = True
    except Exception:
        has_prior = False

    prev_inbound = await _mb_fetch_latest_prev_inbound(chat_id, cur_seen)
    if prev_inbound:
        has_prior = True

    if not has_prior:
        return None

    # Confirmed cross-manager duplicate.
    contact_kind = "duplicate"
    dedupe_reason = "seen_before_other_manager"

    # Stable identity fields for the event_key and payload.
    known_contact_id = int(contact.get("id") or 0)
    canonical_contact_id = str(contact.get("canonical_contact_id") or "").strip()

    previous_manager_key = _tp_ci_norm_key(prev_inbound.get("manager_key") or "") or first_mgr
    previous_seen_utc = str(prev_inbound.get("message_date_utc") or "") or first_seen_global_at

    return {
        "manager_key": manager_key,
        "chat_id": chat_id,
        "lead_date": str(lead_date or ""),
        "contact_kind": contact_kind,
        "dedupe_reason": dedupe_reason,
        "current_seen_utc": cur_seen,
        "first_seen_global_at": first_seen_global_at,
        "first_seen_global_manager_key": first_mgr,
        "previous_manager_key": previous_manager_key,
        "previous_seen_utc": previous_seen_utc,
        "known_contact_id": known_contact_id,
        "canonical_contact_id": canonical_contact_id,
    }


def _mb_build_duplicate_event_key(manager_key: str, known_contact_id: int, canonical_contact_id: str, chat_id: int) -> str:
    """Stable, date-free idempotency key for duplicate_card events.
    M2.12B: no lead_date component — one card per (current_manager, lead_identity).
    Fallback order: known_contact_id → canonical_contact_id → tg:{chat_id}."""
    mk = _tp_ci_norm_key(manager_key)
    kcid = int(known_contact_id or 0)
    if kcid > 0:
        return f"dup_card:{mk}:{kcid}"
    canon = str(canonical_contact_id or "").strip()
    if canon:
        return f"dup_card:{mk}:canonical:{canon}"
    return f"dup_card:{mk}:tg:{int(chat_id or 0)}"


def _mb_build_duplicate_payload(occ: dict, current_contact: dict) -> str:
    mk = _tp_ci_norm_key(occ.get("manager_key") or MANAGER_RUNTIME_KEY)
    cur_disp, cur_user_tbl = _mb_lookup_manager_label_sync(mk)
    if not cur_disp:
        cur_disp = _tp_ci_manager_display_name_sync(mk) or mk
    cur_user = str(SELF_USERNAME or "").strip().lstrip("@") or cur_user_tbl

    prev_mk = _tp_ci_norm_key(occ.get("first_seen_global_manager_key") or occ.get("previous_manager_key") or "")
    prev_disp, prev_user = _mb_lookup_manager_label_sync(prev_mk) if prev_mk else ("", "")

    cur_seen = str(occ.get("current_seen_utc") or "")
    first_at = str(occ.get("first_seen_global_at") or "")
    prev_seen = str(occ.get("previous_seen_utc") or "")

    payload = {
        "manager_key": mk,
        "manager_display_name": cur_disp,
        "manager_username": cur_user,
        "chat_id": int(occ.get("chat_id") or 0),
        "username": str((current_contact or {}).get("username") or "").strip().lstrip("@"),
        "full_name": str((current_contact or {}).get("full_name") or "").strip(),
        "phone": str((current_contact or {}).get("phone") or "").strip(),
        "lead_date": str(occ.get("lead_date") or ""),
        "contact_kind": str(occ.get("contact_kind") or "duplicate"),
        "dedupe_reason": str(occ.get("dedupe_reason") or ""),
        "lead_countable": 0,
        "known_contact_id": int(occ.get("known_contact_id") or 0),
        "canonical_contact_id": str(occ.get("canonical_contact_id") or "").strip(),
        "current_seen_utc": cur_seen,
        "current_seen_kyiv": _mb_kyiv_str(cur_seen),
        "first_seen_global_at": first_at,
        "first_seen_global_kyiv": _mb_kyiv_str(first_at),
        "first_seen_global_manager_key": prev_mk,
        "previous_manager_key": _tp_ci_norm_key(occ.get("previous_manager_key") or ""),
        "previous_manager_display_name": prev_disp,
        "previous_manager_username": prev_user,
        "previous_seen_utc": prev_seen,
        "previous_seen_kyiv": _mb_kyiv_str(prev_seen),
        "status_text": "не считается в оплату",
        "source": "main_m211c",
    }
    return _mb_json.dumps(payload, ensure_ascii=False, default=str)


async def _mb_insert_duplicate_event(occ: dict, current_contact: dict) -> None:
    if not occ or _mb_aiosqlite is None:
        return
    await _mb_ensure_events_table()

    mk = _tp_ci_norm_key(occ.get("manager_key") or MANAGER_RUNTIME_KEY)
    chat_id = int(occ.get("chat_id") or 0)
    lead_date = str(occ.get("lead_date") or _mb_current_lead_date()).strip()
    if not mk or not chat_id:
        return

    # M2.12B: stable date-free key — one card per (current_manager, lead_identity).
    event_key = _mb_build_duplicate_event_key(
        mk,
        int(occ.get("known_contact_id") or 0),
        str(occ.get("canonical_contact_id") or "").strip(),
        chat_id,
    )
    payload_json = _mb_build_duplicate_payload(occ, current_contact or {})
    new_status = str(occ.get("contact_kind") or "duplicate")

    async with _mb_aiosqlite.connect(TPILOT_DB_PATH) as db:
        try:
            await db.execute("PRAGMA busy_timeout=30000;")
        except Exception:
            pass
        await db.execute(
            """
            INSERT OR IGNORE INTO manager_bot_events(
                event_key,
                event_type,
                manager_key,
                chat_id,
                lead_date,
                daily_lead_id,
                old_status,
                new_status,
                payload_json,
                source,
                created_at
            )
            VALUES (?, 'duplicate_card', ?, ?, ?, 0, '', ?, ?, 'main_m211c', ?)
            """,
            (
                event_key,
                mk,
                chat_id,
                lead_date,
                new_status,
                payload_json,
                _mb_now_iso(),
            ),
        )
        await db.commit()


async def _mb_enqueue_duplicate_after_pipeline(chat_id: int) -> None:
    # Defensive catchup guard: there is no global catchup flag today, so this
    # relies primarily on being unreachable from the catchup loop. If a flag is
    # ever introduced, honour it here without raising.
    if globals().get("_TP_CATCHUP_ACTIVE"):
        return

    manager_key = str(MANAGER_RUNTIME_KEY or "").strip()
    chat_id = int(chat_id or 0)
    if not manager_key or chat_id <= 0:
        return

    current = await _mb_fetch_current_inbound(chat_id)
    cur_seen = str((current or {}).get("message_date_utc") or "")
    lead_date = _mb_current_lead_date()
    if cur_seen:
        try:
            lead_date = _utc_iso_to_kyiv_dt(cur_seen).date().isoformat()
        except Exception:
            pass

    occ = await _mb_fetch_duplicate_occurrence_today(manager_key, chat_id, lead_date, cur_seen)
    if not occ:
        return

    await _mb_insert_duplicate_event(occ, current or {})

# --- TPILOT MANAGER BOT DUPLICATE CARD M2.11C 20260608 END ---


_MB_ORIG_RECORD_INCOMING = globals().get("_record_incoming_from_manager")


async def _record_incoming_from_manager(event: events.NewMessage.Event) -> None:  # type: ignore[override]
    result = None

    if callable(_MB_ORIG_RECORD_INCOMING):
        result = await _MB_ORIG_RECORD_INCOMING(event)

    try:
        if (
            not CONTROLLER_MODE
            and MANAGER_RUNTIME_KEY
            and getattr(event, "is_private", False)
            and not getattr(event, "out", False)
        ):
            chat_id = int(getattr(event, "chat_id", 0) or 0)
            if chat_id > 0:
                await _mb_enqueue_after_pipeline(chat_id)
    except Exception as exc:
        try:
            print(f"manager_bot immediate enqueue error: {exc!r}")
        except Exception:
            pass

    return result

