# --- TPILOT M2.12A STAGE1 RUNTIME RELIABILITY 20260609 START ---
# Manager runtime start status JSON + /manager_restart controller command.
# Status file: runtime/managers/{key}/start_status.json
# Phases: starting → connected → running → exited
# reason_class: proxy_timeout | auth_session | connection_error | process_exited | unknown
# /manager_restart: admin-only, calls _spawn_manager_process directly (no proxy re-test).
# All writes are best-effort and never raise into the main runtime.

def _m212a_write_start_status(manager_key: str, phase: str, **kwargs) -> None:
    """Best-effort write to runtime/managers/{key}/start_status.json. Never raises."""
    try:
        import json as _mj, os as _mo
        from datetime import datetime, timezone
        mk = str(manager_key or "").strip().lower()
        if not mk:
            return
        base_dir = _mo.path.dirname(_mo.path.abspath(__file__))
        d = _mo.path.join(base_dir, "runtime", "managers", mk)
        _mo.makedirs(d, exist_ok=True)
        now = datetime.now(timezone.utc).replace(microsecond=0).isoformat()
        path = _mo.path.join(d, "start_status.json")
        # Read existing to preserve last_connected_at across phase transitions
        existing: dict = {}
        try:
            with open(path, "r", encoding="utf-8") as _rf:
                existing = _mj.load(_rf) or {}
        except Exception:
            pass
        _prev_phase = str(existing.get("phase") or "")
        _prev_rc    = str(existing.get("reason_class") or "")
        _prev_err   = str(existing.get("error") or "")
        _kw_rc      = str(kwargs.get("reason_class") or "")
        _kw_err     = str(kwargs.get("error") or "")
        # HNV2 D1 20260807: authoritative last-exit evidence must survive a
        # respawn. Before this, every "starting" write blanked reason_class
        # and error below, so the health aggregator saw phase='starting' /
        # reason_class='' after any respawn and could no longer tell a dead
        # session apart from ordinary churn -- it fell through to the
        # recoveries>=3 rule and reported "recovery_flap" for what was
        # actually session_unauthorized. reason_class/error below keep their
        # existing per-write semantics unchanged for every existing reader;
        # the three last_exit_* keys are new, additive, and are only ever
        # advanced by an 'exited' write.
        if phase == "exited":
            _sticky_rc, _sticky_err, _sticky_at = _kw_rc, _kw_err, now
        elif _prev_phase == "exited" and not str(existing.get("last_exit_reason_class") or ""):
            _sticky_rc, _sticky_err = _prev_rc, _prev_err        # one-time backfill
            _sticky_at = str(existing.get("last_exit_at") or "")
        else:
            _sticky_rc  = str(existing.get("last_exit_reason_class") or "")
            _sticky_err = str(existing.get("last_exit_error") or "")
            _sticky_at  = str(existing.get("last_exit_at") or "")
        payload: dict = {
            "manager_key": mk,
            "phase": phase,
            "updated_at": now,
            "pid": _mo.getpid(),
            "reason_class": "",
            "error": "",
            "last_connected_at": existing.get("last_connected_at", ""),
            "last_exit_at": now if phase == "exited" else _sticky_at,
            "last_exit_reason_class": _sticky_rc,
            "last_exit_error": _sticky_err[:500],
            "respawn_seq": int(existing.get("respawn_seq") or 0) + (1 if phase == "starting" else 0),
        }
        payload.update({k: v for k, v in kwargs.items() if v is not None})
        with open(path, "w", encoding="utf-8") as _wf:
            _mj.dump(payload, _wf, ensure_ascii=False, indent=2)
    except Exception:
        pass


def _m212a_classify_exit_reason(exc: BaseException) -> str:
    """Map an exception to a reason_class string for start_status.json."""
    try:
        msg = str(exc).lower()
        tp = type(exc).__name__.lower()
        if any(x in msg for x in ("socks", "proxy", "couldn't connect", "connection refused")):
            return "proxy_timeout"
        if any(x in msg for x in ("timed out", "timeout", "time out")):
            return "proxy_timeout"
        if any(x in tp for x in ("authkeyerror", "sessionexpired", "sessionrevoked",
                                  "authrestarterror", "floodwaiterror")):
            return "auth_session"
        if ("auth" in msg or "session" in msg) and any(x in msg for x in ("fail", "invalid", "expired", "revoked")):
            return "auth_session"
        if any(x in tp for x in ("connectionerror", "networkerror")):
            return "connection_error"
        if "connection" in msg and any(x in msg for x in ("error", "reset", "closed", "refused")):
            return "connection_error"
        return "unknown"
    except Exception:
        return "unknown"


_M212A_ORIG_PANEL_EXEC = globals().get("_panel_execute_command_text")


async def _panel_execute_command_text(command_text: str, *, requested_by: int = 0, source_chat_id: int = 0, response_chat_id: int = 0):  # type: ignore[override]
    """M2.12A Stage 1: handle /manager_restart command for AdminBot."""
    text = str(command_text or "").strip()
    cmd, args = _parse_cmd(text)
    try:
        if cmd == "/manager_restart":
            mk = registry_normalize_manager_key(str(args or "").strip())
            if not mk:
                return {"ok": False, "error_text": "Не указан ключ менеджера.",
                        "result_text": "❌ Не указан ключ менеджера."}
            row = await manager_get(mk)
            if not row:
                return {"ok": False, "error_text": f"Менеджер не найден: {mk}",
                        "result_text": f"❌ Менеджер не найден: {mk}"}
            m_status = str(row.get("status") or "")
            if m_status == "archived":
                return {"ok": False, "error_text": f"Менеджер архивирован: {mk}",
                        "result_text": f"❌ Менеджер архивирован: {mk}"}
            if not int(row.get("is_enabled") or 0) or int(row.get("manual_stopped") or 0):
                return {"ok": False,
                        "error_text": f"Менеджер отключён: {mk}",
                        "result_text": f"��� Менеджер отключён: {mk}\nВключите перед перезапуском."}
            ok2, msg = await _spawn_manager_process(mk)
            print(f"[m2.12a] manager_restart key={mk} ok={ok2} msg={msg!r} by={requested_by}")
            if ok2:
                return {"ok": True, "result_text": f"✅ Менеджер перезапущен: {mk}"}
            return {"ok": False, "error_text": msg,
                    "result_text": f"❌ Не удалось перезапустить менеджера: {mk}\n{msg}"}
    except Exception as _m212a_cmd_exc:
        return {"ok": False, "error_text": repr(_m212a_cmd_exc),
                "result_text": f"❌ Ошибка перезапуск��: {_m212a_cmd_exc!r}"}
    if callable(_M212A_ORIG_PANEL_EXEC):
        try:
            return await _M212A_ORIG_PANEL_EXEC(command_text, requested_by=requested_by,
                                                source_chat_id=source_chat_id,
                                                response_chat_id=response_chat_id)
        except TypeError:
            try:
                return await _M212A_ORIG_PANEL_EXEC(command_text, requested_by=requested_by)
            except TypeError:
                return await _M212A_ORIG_PANEL_EXEC(command_text)
    return {"ok": False, "error_text": f"Команда не поддерживается: {cmd or text}"}

# --- TPILOT M2.12A STAGE1 RUNTIME RELIABILITY 20260609 END ---


