# Import M2.13C storage helpers
try:
    from storage import (
        bizlink_template_list as _bsl_tmpl_list_m213c,
        bizlinks_list_for_manager_date as _bsl_links_mgr_date_m213c,
        BIZLINKS_DELAY_BETWEEN_LINKS_SEC as _m213c_bsl_delay,
    )
    _M213C_STORAGE_OK = True
except Exception as _m213c_st_err:
    _bsl_tmpl_list_m213c = None  # type: ignore[assignment]
    _bsl_links_mgr_date_m213c = None  # type: ignore[assignment]
    _m213c_bsl_delay = 10
    _M213C_STORAGE_OK = False
