async def _manager_recover_link_limit(manager_key: str, current_target_date: str,
                                       needed: int = 15) -> Dict[str, Any]:
    """R5: on a tg_limit (Telegram business-chat-link cap) error, free up room by iteratively
    deleting the oldest TPilot-created links for this same account (at least 15, or `needed`
    if the caller asks for more), then let the caller retry.

    Iterates in batches because the oldest rows may already be dead on Telegram
    (CHATLINK_SLUG_EXPIRED) -- _manager_delete_business_links soft-deletes those so oldest_n
    never re-selects them, but an expired slug does NOT free tg_limit capacity by itself.
    So this loop keeps selecting deeper into the oldest list (skipping slugs already
    attempted this call) until it has freed `needed` real links, runs out of candidates,
    hits a FloodWait, or hits the hard batch/candidate cap (MAX_BATCHES / delete_count*3) --
    whichever comes first. Never loops forever.

    Reuses the existing delete primitive (_manager_delete_business_links — real Telegram-
    side DeleteBusinessChatLinkRequest, not DB-only) and the existing oldest_n selector —
    no controller queue/preview wrapper. Never deletes rows belonging to the current batch's
    target_date. One summary audit row is written via bizlink_delete_audit_add regardless of
    outcome (fail-open — an audit failure never blocks recovery). Never raises — all errors
    are captured in the returned dict.
    """
    MAX_BATCHES = 3
    delete_count = max(int(needed or 0), 15)
    needed_for_stop = max(int(needed or 0), 1)
    max_viewed = delete_count * 3
    started_at = _tp_utc_now().replace(microsecond=0).isoformat()

    attempted_slugs: set = set()
    touched_slugs: List[str] = []  # real deletes + expired-cleaned, for the audit row
    real_deleted = 0
    expired_cleaned = 0
    failed_count = 0
    error_parts: List[str] = []
    flood_hit = False
    reason = "no_eligible_old_links"

    def _r5_audit() -> None:
        try:
            if callable(_bsd3a_audit_add):
                import json as _m213r5_json
                try:
                    slugs_json_out = _m213r5_json.dumps(touched_slugs, ensure_ascii=False)
                except Exception:
                    slugs_json_out = "[]"
                error_text_out = "; ".join(filter(None, [reason] + error_parts))[:500]
                _bsd3a_audit_add(
                    manager_key, "tg_limit_auto",
                    target_date=current_target_date,
                    requested_count=needed_for_stop,
                    deleted_count=real_deleted,
                    failed_count=failed_count,
                    slugs_json=slugs_json_out,
                    link_urls_json="[]",
                    requested_by_user_id=0,
                    requested_by="system:auto_oldest_on_tg_limit",
                    source="tpilot",
                    result_ok=real_deleted > 0,
                    error_class="tg_limit",
                    error_text=error_text_out,
                    created_at=started_at,
                    finished_at=_tp_utc_now().replace(microsecond=0).isoformat(),
                    db_path=TPILOT_DB_PATH,
                )
        except Exception:
            pass

    try:
        # Bug fix (2026-07-07): eligibility must protect every date >= today, not just the
        # current batch's target_date -- otherwise oldest_n can walk straight into live
        # today/tomorrow/day-after-tomorrow links once older history is exhausted or dead.
        # Kyiv business date, ISO lexical comparison is safe here.
        # W3.2 D7 (2026-08-01): the former `except Exception: _tp_utc_now().date()...`
        # substituted a UTC date here, widening the deletion window by a day around Kyiv
        # midnight. Resolved inside this try so a W3TimezoneError is caught by the handler
        # below -> reason="exception", ok=False, zero deletions. Fail-closed; "never raises"
        # is preserved.
        today_iso_r5 = _kyiv_now().date().isoformat()
        if not callable(_bsd3a_select_candidates):
            reason = "selector_unavailable"
        else:
            for _batch_no in range(MAX_BATCHES):
                if len(attempted_slugs) >= max_viewed:
                    break
                # RUNTIME READINESS RC 20260805 (wave L4): the eligibility date
                # is now pushed INTO the query, so LIMIT applies to already-
                # eligible rows instead of truncating the pool before the filter
                # ever runs. The Python-side filter below is kept unchanged as a
                # second, independent layer -- it also enforces the
                # current_target_date exclusion, which is not expressible as a
                # single "< today" bound.
                candidates = _bsd3a_select_candidates(
                    manager_key, "oldest_n", count=delete_count, db_path=TPILOT_DB_PATH,
                    before_target_date=today_iso_r5,
                ) or []
                # Eligibility (business rule): a link may be auto-deleted ONLY when its
                # target_date is strictly before today (Kyiv) -- this protects today,
                # tomorrow, day-after-tomorrow, and any further future date, no matter
                # which target_date the current creation batch is for. The previous
                # current_target_date-only exclusion is kept as an extra safety net.
                candidates = [
                    c for c in candidates
                    if str(c.get("target_date") or "").strip()
                    and str(c.get("target_date") or "") < today_iso_r5
                    and str(c.get("target_date") or "") != str(current_target_date or "")
                ]
                # Oldest business date first, then oldest created_at, then lowest id.
                # The underlying oldest_n selector only orders by created_at/id (not
                # target_date), so history spanning multiple old dates is re-sorted here.
                candidates.sort(key=lambda c: (
                    str(c.get("target_date") or ""),
                    str(c.get("created_at") or ""),
                    int(c.get("id") or 0),
                ))
                batch_slugs = [
                    str(c.get("slug") or "") for c in candidates
                    if str(c.get("slug") or "").strip()
                    and str(c.get("slug") or "").strip() not in attempted_slugs
                ]
                if not batch_slugs:
                    break
                attempted_slugs.update(batch_slugs)
                result = await _manager_delete_business_links({
                    "manager_key": manager_key,
                    "mode": "oldest_n_auto",
                    "target_date": current_target_date,
                    "slugs": batch_slugs,
                    "delay_between_deletes_sec": 3,
                    "requested_by_user_id": 0,
                })
                real_deleted += int(result.get("deleted") or 0)
                expired_cleaned += int(result.get("expired_cleaned") or 0)
                failed_count += int(result.get("failed") or 0)
                touched_slugs.extend(str(s) for s in (result.get("deleted_slugs") or []))
                touched_slugs.extend(str(s) for s in (result.get("expired_slugs") or []))
                if result.get("errors"):
                    error_parts.extend(str(e)[:150] for e in (result.get("errors") or [])[:5])
                fw = int(result.get("flood_wait_seconds") or 0)
                if fw > 0:
                    flood_hit = True
                    error_parts.append(f"FloodWait {fw}s")
                    break
                if real_deleted >= needed_for_stop:
                    break

            # Layer 2 -- Telegram-live fallback. DB-only recovery (above) is blind
            # when Telegram still holds real live links that the DB no longer
            # tracks as active (deleted/failed/foreign/orphan rows) -- exactly the
            # dariass production case: bizlinks had status='deleted' rows for old
            # dates, so oldest_n found zero candidates while the account was still
            # over the real Telegram cap. Runs only when Layer 1 genuinely freed
            # nothing and didn't itself hit a FloodWait. Every TPilot-created link
            # is titled "TPilot YYYY-MM-DD #NN" (see slot creation above), so its
            # business date is provable straight from Telegram's own title field
            # without needing a matching DB row. Any title that does not match
            # this exact pattern is foreign/unknown and is NEVER touched.
            layer2_attempted = False
            layer2_list_ok = False
            layer2_had_matches = False
            if real_deleted == 0 and not flood_hit:
                layer2_attempted = True
                try:
                    tg_list_res = await _manager_list_business_links({"manager_key": manager_key})
                except Exception as _r5_l2_exc:
                    tg_list_res = {"ok": False, "error": repr(_r5_l2_exc)[:200]}
                layer2_list_ok = bool(tg_list_res.get("ok"))
                if layer2_list_ok and tg_list_res.get("links"):
                    tg_candidates: List[Tuple[str, str]] = []
                    for lnk in (tg_list_res.get("links") or []):
                        title = str(lnk.get("title") or "")
                        m = re.match(r"^TPilot\s+(\d{4}-\d{2}-\d{2})\s+#\d+", title)
                        if not m:
                            continue  # foreign/unknown title -- never auto-deleted
                        parsed_date = m.group(1)
                        slug = str(lnk.get("slug") or "").strip()
                        if not slug or slug in attempted_slugs:
                            continue
                        # Same protection as Layer 1: strictly before today (Kyiv),
                        # and never the current batch's own target_date.
                        if parsed_date >= today_iso_r5:
                            continue
                        if parsed_date == str(current_target_date or ""):
                            continue
                        tg_candidates.append((parsed_date, slug))
                    tg_candidates.sort(key=lambda t: (t[0], t[1]))
                    if tg_candidates:
                        layer2_had_matches = True
                        layer2_slugs = [s for _, s in tg_candidates[:max(needed_for_stop, delete_count)]]
                        attempted_slugs.update(layer2_slugs)
                        result2 = await _manager_delete_business_links({
                            "manager_key": manager_key,
                            "mode": "oldest_n_tglist_auto",
                            "target_date": current_target_date,
                            "slugs": layer2_slugs,
                            "delay_between_deletes_sec": 3,
                            "requested_by_user_id": 0,
                        })
                        real_deleted += int(result2.get("deleted") or 0)
                        expired_cleaned += int(result2.get("expired_cleaned") or 0)
                        failed_count += int(result2.get("failed") or 0)
                        touched_slugs.extend(str(s) for s in (result2.get("deleted_slugs") or []))
                        touched_slugs.extend(str(s) for s in (result2.get("expired_slugs") or []))
                        if result2.get("errors"):
                            error_parts.extend(str(e)[:150] for e in (result2.get("errors") or [])[:5])
                        fw2 = int(result2.get("flood_wait_seconds") or 0)
                        if fw2 > 0:
                            flood_hit = True
                            error_parts.append(f"FloodWait {fw2}s")

            # Determine final reason from the accumulated totals.
            if flood_hit:
                reason = "flood_wait"
            elif real_deleted > 0:
                reason = "telegram_fallback_deleted_ok" if (layer2_attempted and layer2_had_matches) else "deleted_ok"
            elif expired_cleaned > 0:
                reason = "only_expired_cleaned"
            elif layer2_attempted and layer2_list_ok and not layer2_had_matches:
                reason = "telegram_fallback_no_safe_matches"
            elif not attempted_slugs:
                reason = "no_eligible_old_links"
            else:
                reason = "delete_failed"
        _r5_audit()
        return {
            "attempted": True,
            "ok": real_deleted > 0,
            "deleted": real_deleted,
            "expired_cleaned": expired_cleaned,
            "failed": failed_count,
            "reason": reason,
            "error_text": "; ".join(filter(None, [reason] + error_parts))[:500],
        }
    except Exception as exc:
        # RUNTIME READINESS RC 20260805 (wave L3). This handler is deliberately
        # fail-closed -- a W3TimezoneError from _kyiv_now() lands here and must
        # produce zero deletions rather than fall back to a UTC date (W3.2 D7,
        # 2026-08-01). What it must NOT be is invisible: until now the only
        # trace was a 500-char audit column, so a tzdata fault on a manager host
        # would have killed auto-deletion silently and indefinitely. Two changes:
        # the cause is printed, and the text is sanitized first -- the old
        # repr(exc) went into bizlink_delete_audit.error_text verbatim and could
        # carry a link URL, a session path or a proxy credential string.
        reason = "exception"
        try:
            _sanitize = globals().get("_bizlink_delete_safe_sanitize")
            safe_exc = (_sanitize(f"{type(exc).__name__}: {exc}", 300)
                        if callable(_sanitize) else type(exc).__name__)
        except Exception:
            safe_exc = "unprintable"
        error_parts.append(safe_exc)
        try:
            print(
                f"[bizlink_recover] result=exception manager_key={manager_key}"
                f" target_date={current_target_date} deleted={real_deleted}"
                f" expired_cleaned={expired_cleaned} failed={failed_count}"
                f" detail={safe_exc}"
            )
        except Exception:
            pass
        _r5_audit()
        return {
            "attempted": True,
            "ok": False,
            "deleted": real_deleted,
            "expired_cleaned": expired_cleaned,
            "failed": failed_count,
            "reason": reason,
            "error_text": "; ".join(filter(None, [reason] + error_parts))[:500],
        }


async def _manager_create_15_business_links(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Batch-create up to 15 Telegram Business links sequentially. Manager runtime only.

    Skips slots where status='created' with non-empty link_url (idempotent).
    Stops on first error, except a single automatic recovery cycle on tg_limit (R5): the
    oldest 15 TPilot-created links for this account are deleted and the failed slot is
    retried once before giving up. Sleeps _m213c_bsl_delay seconds between real creates only.
    Never raises — all errors returned in result dict.
    """
    manager_key = str(payload.get("manager_key") or "")
    target_date = str(payload.get("target_date") or "")
    slots_raw = list(payload.get("slots") or [])
    delay_sec = int(payload.get("delay_between_links_sec") or _m213c_bsl_delay)

    created_count = 0
    skipped_count = 0
    error_count = 0
    failed_slot_no = 0
    error_class_out = ""
    error_text_out = ""
    flood_wait_sec_out = 0
    recovered_link_limit = False  # R5: caps auto-recovery at one cycle per batch
    recovery_attempted = False
    recovery_deleted = 0
    recovery_expired_cleaned = 0
    recovery_reason = ""
    recovery_ok = False  # R5: whether the post-recovery retry of the affected slot succeeded

    for i, slot_item in enumerate(slots_raw):
        slot_no = int(slot_item.get("slot_no") or 0)
        title = str(slot_item.get("title") or "")
        message_text = str(slot_item.get("message_text") or "")

        slot_payload: Dict[str, Any] = {
            "manager_key": manager_key,
            "target_date": target_date,
            "slot_no": slot_no,
            "title": title,
            "message_text": message_text,
        }

        res = await _manager_create_one_business_link(slot_payload)

        if res.get("ok"):
            if res.get("already_exists"):
                skipped_count += 1
                # No sleep on skipped slots
            else:
                created_count += 1
                # Sleep only after a real creation if more slots remain
                remaining = len(slots_raw) - (i + 1)
                if remaining > 0:
                    await asyncio.sleep(delay_sec)
            continue

        res_error_class = str(res.get("error_class") or "unknown")

        # R5: on a link-limit error, try exactly one auto-recovery cycle per package —
        # delete the oldest (>=15, or however many slots still remain if more) TPilot-
        # created links for this same account, then retry this slot once.
        if res_error_class == "tg_limit" and not recovered_link_limit:
            recovered_link_limit = True
            needed = len(slots_raw) - i
            recovery = await _manager_recover_link_limit(manager_key, target_date, needed=needed)
            recovery_attempted = True
            recovery_deleted = int(recovery.get("deleted") or 0)
            recovery_expired_cleaned = int(recovery.get("expired_cleaned") or 0)
            recovery_reason = str(recovery.get("reason") or "")
            if recovery_deleted > 0:
                retry_res = await _manager_create_one_business_link(slot_payload)
                if retry_res.get("ok"):
                    recovery_ok = True
                    if retry_res.get("already_exists"):
                        skipped_count += 1
                    else:
                        created_count += 1
                        remaining = len(slots_raw) - (i + 1)
                        if remaining > 0:
                            await asyncio.sleep(delay_sec)
                    continue  # Slot recovered — proceed to the next slot, no break
                # Retry after recovery still failed — give up on this slot as usual
                error_count += 1
                failed_slot_no = slot_no
                error_class_out = str(retry_res.get("error_class") or "unknown")
                error_text_out = str(retry_res.get("error") or "")[:300]
                flood_wait_sec_out = int(retry_res.get("flood_wait_seconds") or 0)
                break
            # Recovery freed nothing (no TPilot candidates outside this date, or the
            # delete primitive failed) — fall through to the standard failure path below.

        error_count += 1
        failed_slot_no = slot_no
        error_class_out = res_error_class
        error_text_out = str(res.get("error") or "")[:300]
        flood_wait_sec_out = int(res.get("flood_wait_seconds") or 0)
        break  # Stop batch on first error

    # Collect final link state (slots 1-15) from DB
    link_list: List[Tuple[int, Optional[str]]] = []
    try:
        if callable(_bsl_links_mgr_date_m213c):
            db_rows = _bsl_links_mgr_date_m213c(manager_key, target_date, TPILOT_DB_PATH)
            link_by_slot = {int(r.get("slot_no") or 0): r for r in db_rows}
            for n in range(1, 16):
                db_row = link_by_slot.get(n)
                if (db_row
                        and str(db_row.get("status") or "") == "created"
                        and str(db_row.get("link_url") or "").strip()
                        and not str(db_row.get("deleted_at") or "").strip()):
                    link_list.append((n, str(db_row.get("link_url") or "")))
                else:
                    link_list.append((n, None))
        else:
            link_list = [(n, None) for n in range(1, 16)]
    except Exception:
        link_list = [(n, None) for n in range(1, 16)]

    return {
        "ok": error_count == 0,
        "manager_key": manager_key,
        "target_date": target_date,
        "created": created_count,
        "skipped": skipped_count,
        "errors": error_count,
        "failed_slot": failed_slot_no,
        "error_class": error_class_out,
        "error_text": error_text_out,
        "flood_wait_seconds": flood_wait_sec_out,
        "link_list": link_list,
        "recovery_attempted": recovery_attempted,
        "recovery_deleted": recovery_deleted,
        "recovery_expired_cleaned": recovery_expired_cleaned,
        "recovery_reason": recovery_reason,
        "recovery_ok": recovery_ok,
    }


async def _queue_bizlink_create_15_for_manager(
    manager_key: str,
    target_date: str,
    *,
    user_id: int = 0,
    timeout_sec: int = 240,
) -> Tuple[bool, str]:
    """Controller-side: snapshot all 15 templates, enqueue bizlink_create_15, poll for result."""
    import json as _m213c_json
    try:
        from storage import (
            manager_queue_get as _mqget_c15,
            manager_queue_put as _mqput_c15,
        )
    except Exception as e:
        return False, f"Ошибка очереди менеджера: {e!r}"

    mk = registry_normalize_manager_key(manager_key)
    if not mk:
        return False, "Пустой ключ менеджера."

    # Controller-side: check if all 15 already created → short-circuit
    try:
        if callable(_bsl_links_mgr_date_m213c):
            existing_rows = _bsl_links_mgr_date_m213c(mk, target_date, TPILOT_DB_PATH)
            created_slots = {
                int(r.get("slot_no") or 0)
                for r in existing_rows
                if str(r.get("status") or "") == "created"
                and str(r.get("link_url") or "").strip()
                and not str(r.get("deleted_at") or "").strip()
            }
            if len(created_slots) >= 15 and all(n in created_slots for n in range(1, 16)):
                _link_by_slot_sc = {
                    int(r.get("slot_no") or 0): str(r.get("link_url") or "")
                    for r in existing_rows
                }
                _sc_lines = [
                    "ℹ️ Ссылки уже готовы",
                    "",
                    f"Менеджер: {mk}",
                    f"Дата: {target_date}",
                    "",
                    "Всего готово: 15/15",
                    "Создано новых: 0",
                    "Уже было: 15",
                    "Ошибок: 0",
                    "",
                ]
                for _sc_n in range(1, 16):
                    _sc_u = _link_by_slot_sc.get(_sc_n, "")
                    _sc_lines.append(f"{_sc_n}. {_sc_u}" if _sc_u else f"{_sc_n}. не создано")
                return True, "\n".join(_sc_lines)
    except Exception:
        pass

    # Snapshot all 15 templates at enqueue time
    if not callable(_bsl_tmpl_list_m213c):
        return False, "Ошибка: хранилище шаблонов недоступно."
    try:
        tmpl_rows = _bsl_tmpl_list_m213c(TPILOT_DB_PATH)
    except Exception as e:
        return False, f"Ошибка загрузки шаблонов: {e!r}"

    if len(tmpl_rows) < 15:
        return False, (
            f"Шаблонов только {len(tmpl_rows)}, нужно 15. "
            "Откройте «Изменить 15 текстов» и заполните все слоты."
        )

    # Validate all 15 texts
    slots: List[Dict[str, Any]] = []
    for row in tmpl_rows:
        s_no = int(row.get("slot_no") or 0)
        msg_text = str(row.get("message_text") or "").strip()
        if not msg_text:
            return False, f"Шаблон #{s_no} пустой. Заполните текст перед созданием ссылок."
        if len(msg_text) > 1024:
            return False, (
                f"Шаблон #{s_no} слишком длинный ({len(msg_text)} символов, максимум 1024)."
            )
        title = f"TPilot {target_date} #{s_no:02d}"
        slots.append({
            "slot_no": s_no,
            "title": title,
            "message_text": msg_text,
        })

    payload: Dict[str, Any] = {
        "manager_key": mk,
        "target_date": str(target_date),
        "slots": slots,
        "delay_between_links_sec": int(_m213c_bsl_delay),
    }

    nonce = await _mqput_c15(
        target_key=mk,
        command="bizlink_create_15",
        payload_json=_m213c_json.dumps(payload, ensure_ascii=False),
        created_by=str(user_id or "panel"),
        expires_at=_future_iso(int(timeout_sec) + 120),
        db_path=TPILOT_DB_PATH,
    )

    deadline = time.monotonic() + max(30, int(timeout_sec or 240))
    while time.monotonic() < deadline:
        row_q = await _mqget_c15(nonce, db_path=TPILOT_DB_PATH)
        status = str((row_q or {}).get("status") or "")
        if status in ("done", "error", "timeout"):
            if status == "done" and int((row_q or {}).get("result_ok") or 0) == 1:
                return True, str(
                    (row_q or {}).get("result_text") or f"✅ {mk}: 15 ссылок создано"
                )
            return False, str(
                (row_q or {}).get("error_text")
                or (row_q or {}).get("result_text")
                or f"{mk}: ошибка создания 15 бизнес-ссылок"
            )
        await asyncio.sleep(1.0)

    return False, (
        f"{mk}: менеджер не ответил за {timeout_sec} сек. "
        "Проверьте, что manager-процесс запущен."
    )


async def _handle_bizlink_create_15_command(args: str, *, user_id: int = 0) -> str:
    """Parse and execute /bizlink_create_15 <key> [YYYY-MM-DD]."""
    parts = str(args or "").split()
    if not parts or not parts[0]:
        return "Формат: /bizlink_create_15 <manager_key> [YYYY-MM-DD]"
    mk = registry_normalize_manager_key(parts[0])
    if not mk:
        return f"Неверный ключ менеджера: {parts[0]!r}"
    if len(parts) >= 2:
        target_date = str(parts[1]).strip()
    else:
        tz = ZoneInfo("Europe/Kyiv")
        target_date = (datetime.now(tz) + timedelta(days=1)).date().isoformat()
    working_keys = _bizlink_manual_schedule_working_keys(target_date)
    if working_keys and mk not in working_keys:
        return f"📅 Менеджер {mk} не в графике на {target_date}. Ссылки не создаются."
    ok, text = await _queue_bizlink_create_15_for_manager(
        mk, target_date, user_id=user_id, timeout_sec=240
    )
    return text


# Override _panel_execute_command_text — M2.13C adds /bizlink_create_15
_M213C_ORIG_PANEL_EXEC = globals().get("_panel_execute_command_text")


async def _panel_execute_command_text(  # type: ignore[override]
    command_text: str,
    *,
    requested_by: int = 0,
    source_chat_id: int = 0,
    response_chat_id: int = 0,
):
    """M2.13C: route /bizlink_create_15 before chaining to M2.13B override."""
    text = str(command_text or "").strip()
    cmd, args = _parse_cmd(text)
    if cmd == "/bizlink_create_15":
        try:
            result_text = await _handle_bizlink_create_15_command(args, user_id=requested_by)
            ok = result_text.startswith("✅") or result_text.startswith("ℹ")
            return {"ok": ok, "result_text": result_text,
                    "error_text": ("" if ok else result_text)}
        except Exception as exc:
            return {"ok": False, "error_text": repr(exc),
                    "result_text": f"❌ Ошибка bizlink_create_15: {exc!r}"}
    if callable(_M213C_ORIG_PANEL_EXEC):
        try:
            return await _M213C_ORIG_PANEL_EXEC(
                command_text,
                requested_by=requested_by,
                source_chat_id=source_chat_id,
                response_chat_id=response_chat_id,
            )
        except TypeError:
            try:
                return await _M213C_ORIG_PANEL_EXEC(command_text, requested_by=requested_by)
            except TypeError:
                return await _M213C_ORIG_PANEL_EXEC(command_text)
    return {"ok": False, "error_text": f"Команда не поддерживается: {cmd or text}"}

# --- TPILOT M2.13C BIZLINK BATCH CREATE 20260609 END ---


# --- TPILOT M2.13D-1 SCHEDULE SUMMARY CONTROLLER 20260609 START ---
# Daily 16:50 Kyiv summary: "Кто работает завтра" sent to admin stat chat.
# Controller-only. Restart-safe via settings flag. Separate task (not in _daily_report_loop).

try:
    from storage import manager_schedule_list_working_on_date as _sched_sum_list
    _SCHED_SUM_OK = True
except Exception:
    _sched_sum_list = None
    _SCHED_SUM_OK = False

_SCHED_SUM_RUNNING = False


async def _schedule_summary_if_due() -> None:
    """Send 'Кто работает завтра' once per day at or after 16:50 Kyiv. Claim-first restart-safe."""
    if not CONTROLLER_MODE:
        return
    now = _kyiv_now()
    # Fire at or after 16:50 Kyiv
    if now.hour < 16 or (now.hour == 16 and now.minute < 50):
        return
    today = now.date().isoformat()
    flag = "manager_schedule_summary_sent_{}".format(today)
    if (await get_setting(flag)) == "1":
        return
    # Claim first — prevents double-send on restart
    await set_setting(flag, "1")
    try:
        tomorr = (now + timedelta(days=1)).date()
        tomorr_iso = tomorr.isoformat()
        tomorr_disp = tomorr.strftime("%d.%m.%Y")
        # Working keys for tomorrow (explicit is_working=1 only)
        working_keys: list = []
        if _SCHED_SUM_OK and callable(_sched_sum_list):
            try:
                working_keys = _sched_sum_list(tomorr_iso, TPILOT_DB_PATH)
            except Exception as _we:
                print("schedule summary list error: {!r}".format(_we))
        # Active + enabled + not manually stopped managers
        try:
            mgr_rows = await manager_list_rows(include_removed=False, only_enabled=True, only_active=True)
        except Exception:
            mgr_rows = []
        active_map: dict = {}
        for row in mgr_rows:
            key = str(row.get("manager_key") or "").strip().lower()
            if not key:
                continue
            if int(row.get("manual_stopped") or 0):
                continue
            name = str(row.get("display_name") or "").strip() or key
            uname = str(row.get("telegram_username") or "").strip()
            active_map[key] = (name, uname)
        # Intersect: working AND active
        working_active = [k for k in working_keys if k in active_map]
        lines = [
            "\U0001f4c5 Кто работает завтра",
            "Дата: {}".format(tomorr_disp),
            "",
            "Всего работает: {}".format(len(working_active)),
        ]
        if working_active:
            lines.append("")
            for i, key in enumerate(working_active, 1):
                name, uname = active_map[key]
                lines.append("{}. {}".format(i, "{} / @{}".format(name, uname) if uname else name))
        else:
            lines.append("")
            lines.append("Никто не отмечен рабочим на завтра.")
        await _send_ai_stat("\n".join(lines))
    except Exception as exc:
        print("schedule summary send error: {!r}".format(exc))


async def _schedule_summary_loop() -> None:
    """Controller-only loop: check every 60 s and send summary once per day at 16:50 Kyiv."""
    global _SCHED_SUM_RUNNING
    if _SCHED_SUM_RUNNING:
        return
    _SCHED_SUM_RUNNING = True
    try:
        while True:
            try:
                await _schedule_summary_if_due()
            except asyncio.CancelledError:
                return
            except Exception as exc:
                print("schedule summary loop error: {!r}".format(exc))
            await asyncio.sleep(60)
    finally:
        _SCHED_SUM_RUNNING = False

# --- TPILOT M2.13D-1 SCHEDULE SUMMARY CONTROLLER 20260609 END ---


# --- TPILOT M2.13D-2 BIZLINK CREATE-N / AUTO-14:00 20260609 START ---
# Generalised bizlink_create_n (configurable count), all-managers background task,
# and 14:00 Kyiv daily auto-create loop (uses manager_work_schedule_days only).

try:
    from storage import (
        bizlink_clamp_count as _m213d2_clamp_count,
        manager_schedule_list_working_on_date as _sched_ac_list,
        BIZLINKS_DELAY_BETWEEN_MANAGERS_SEC as _m213d2_mgr_delay,
    )
    _M213D2_STORAGE_OK = True
except Exception as _m213d2_st_err:
    _m213d2_clamp_count = None  # type: ignore[assignment]
    _sched_ac_list = None  # type: ignore[assignment]
    _m213d2_mgr_delay = 90
    _M213D2_STORAGE_OK = False
    print(f"[m2.13d2] storage import warning: {_m213d2_st_err!r}")


async def _queue_bizlink_create_n_for_manager(
    manager_key: str,
    target_date: str,
    count: int,
    *,
    user_id: int = 0,
    timeout_sec: int = 600,
) -> Tuple[bool, str]:
    """Controller-side: snapshot first count templates, enqueue bizlink_create_n, poll for result.
    Clamps count to available templates. Short-circuits if all count slots already created."""
    import json as _m213d2_json
    try:
        from storage import (
            manager_queue_get as _mqget_cn,
            manager_queue_put as _mqput_cn,
        )
    except Exception as e:
        return False, f"Ошибка очереди менеджера: {e!r}"

    mk = registry_normalize_manager_key(manager_key)
    if not mk:
        return False, "Пустой ключ менеджера."

    # Clamp count to available templates
    if callable(_m213d2_clamp_count):
        count, _avail = _m213d2_clamp_count(int(count or 1), TPILOT_DB_PATH)
    else:
        count = min(max(1, int(count or 1)), 15)

    # Short-circuit: all count slots already created?
    try:
        if callable(_bsl_links_mgr_date_m213c):
            existing_rows = _bsl_links_mgr_date_m213c(mk, target_date, TPILOT_DB_PATH)
            created_slots = {
                int(r.get("slot_no") or 0)
                for r in existing_rows
                if str(r.get("status") or "") == "created"
                and str(r.get("link_url") or "").strip()
                and not str(r.get("deleted_at") or "").strip()
            }
            if len(created_slots) >= count and all(n in created_slots for n in range(1, count + 1)):
                _link_by_slot_sc = {
                    int(r.get("slot_no") or 0): str(r.get("link_url") or "")
                    for r in existing_rows
                }
                _sc_lines = [
                    "ℹ️ Ссылки уже готовы",
                    "",
                    f"Менеджер: {mk}",
                    f"Дата: {target_date}",
                    "",
                    f"Всего готово: {count}/{count}",
                    "Создано новых: 0",
                    f"Уже было: {count}",
                    "Ошибок: 0",
                    "",
                ]
                for _sc_n in range(1, count + 1):
                    _sc_u = _link_by_slot_sc.get(_sc_n, "")
                    _sc_lines.append(f"{_sc_n}. {_sc_u}" if _sc_u else f"{_sc_n}. не создано")
                return True, "\n".join(_sc_lines)
    except Exception:
        pass

    # Snapshot first count templates
    if not callable(_bsl_tmpl_list_m213c):
        return False, "Ошибка: хранилище шаблонов недоступно."
    try:
        all_tmpl_rows = _bsl_tmpl_list_m213c(TPILOT_DB_PATH)
    except Exception as e:
        return False, f"Ошибка загрузки шаблонов: {e!r}"

    if len(all_tmpl_rows) < count:
        return False, (
            f"Шаблонов только {len(all_tmpl_rows)}, запрошено {count}. "
            "Откройте «Изменить 15 текстов» и заполните слоты."
        )

    slots: List[Dict[str, Any]] = []
    for row_t in all_tmpl_rows[:count]:
        s_no = int(row_t.get("slot_no") or 0)
        msg_text = str(row_t.get("message_text") or "").strip()
        if not msg_text:
            return False, f"Шаблон #{s_no} пустой. Заполните текст перед созданием ссылок."
        if len(msg_text) > 1024:
            return False, (
                f"Шаблон #{s_no} слишком длинный ({len(msg_text)} символов, максимум 1024)."
            )
        title = f"TPilot {target_date} #{s_no:02d}"
        slots.append({"slot_no": s_no, "title": title, "message_text": msg_text})

    # TPILOT E 20260718: command readiness gate -- refuse to enqueue a
    # manager-dependent command against a runtime that isn't even running or
    # connected (this is exactly the enqueue-into-a-void that let the
    # valeria1 replacement sit at 0/15 links forever). A single bounded pass
    # (not the full polling manager_runtime_ready contract) -- cheap enough
    # to run before every enqueue; the manager worker itself re-checks its
    # own connected/authorized state when it actually executes the command
    # (runtime_ping is served locally, never a second Telethon client).
    # RUNTIME READINESS RC 20260805 (wave L2). Three changes, all confined to
    # this gate:
    #  1) bounded polling instead of a single pass -- reuses the existing
    #     manager_runtime_ready() poller rather than adding a second one, so a
    #     momentary SQLite lock or an in-flight health write no longer decides
    #     the outcome on its own;
    #  2) heartbeat_advisory=True -- this command targets an ALREADY-RUNNING
    #     runtime, so a background health row that is merely behind must not
    #     outvote the live runtime_ping. BLOCKED health and every other signal
    #     stay fatal. Replacement/onboarding keep the strict default;
    #  3) the exact structured cause is logged before it is flattened into the
    #     admin sentence. panel_commands id 2173 preserved only the sentence,
    #     which is why the failing signal had to be reconstructed from
    #     timestamps afterwards.
    readiness = await manager_runtime_ready(
        mk, deadline_sec=30, poll_interval_sec=3.0, ping_timeout_sec=15,
        heartbeat_advisory=True,
    )
    if not readiness.get("ok"):
        err_class = str(readiness.get("error_class") or "runtime_not_ready")
        _bizlink_readiness_safe_log(
            "bizlink_create_n", mk,
            target_date=str(target_date or ""),
            signal=str(readiness.get("signal") or ""),
            error_class=err_class,
            detail=str(readiness.get("detail") or ""),
        )
        return False, _bizlink_human_error_reason(err_class, str(readiness.get("detail") or ""))

    payload: Dict[str, Any] = {
        "manager_key": mk,
        "target_date": str(target_date),
        "slots": slots,
        "count": count,
        "delay_between_links_sec": int(_m213c_bsl_delay),
    }

    nonce = await _mqput_cn(
        target_key=mk,
        command="bizlink_create_n",
        payload_json=_m213d2_json.dumps(payload, ensure_ascii=False),
        created_by=str(user_id or "panel"),
        expires_at=_future_iso(int(timeout_sec) + 120),
        db_path=TPILOT_DB_PATH,
    )

    deadline = time.monotonic() + max(30, int(timeout_sec or 600))
    while time.monotonic() < deadline:
        row_q = await _mqget_cn(nonce, db_path=TPILOT_DB_PATH)
        status = str((row_q or {}).get("status") or "")
        if status in ("done", "error", "timeout"):
            if status == "done" and int((row_q or {}).get("result_ok") or 0) == 1:
                return True, str(
                    (row_q or {}).get("result_text") or f"✅ {mk}: {count} ссылок создано"
                )
            # Prefer a human-readable, actionable reason built from the structured
            # error signal (result_json carries error_class/recovery_reason/
            # flood_wait_seconds -- see _manager_create_15_business_links). Falls
            # back to the existing raw text on any parse failure; never raises.
            friendly = None
            try:
                raw_json = str((row_q or {}).get("result_json") or "")
                if raw_json:
                    import ast as _bsl_ast
                    parsed = _bsl_ast.literal_eval(raw_json)
                    if isinstance(parsed, dict):
                        friendly = _bizlink_human_error_reason(
                            str(parsed.get("error_class") or ""),
                            str(parsed.get("error_text") or ""),
                            recovery_reason=str(parsed.get("recovery_reason") or ""),
                            flood_wait_seconds=int(parsed.get("flood_wait_seconds") or 0),
                            manager_key=mk,
                        )
            except Exception:
                friendly = None
            if friendly:
                return False, friendly
            return False, str(
                (row_q or {}).get("error_text")
                or (row_q or {}).get("result_text")
                or f"{mk}: ошибка создания {count} бизнес-ссылок"
            )
        await asyncio.sleep(1.0)

    return False, (
        f"{mk}: менеджер не ответил за {timeout_sec} сек. "
        "Проверьте, что manager-процесс запущен."
    )


async def _handle_bizlink_create_n_command(args: str, *, user_id: int = 0) -> str:
    """Parse /bizlink_create_n <manager_key> <count> [YYYY-MM-DD] [force] and enqueue.

    Optional 4th token 'force' or 'override' bypasses the schedule gate (mirrors
    /bizlink_create_one's force support). Existing 3-token calls are unaffected.
    """
    parts = str(args or "").split()
    if not parts or not parts[0]:
        return "Формат: /bizlink_create_n <manager_key> <count> [YYYY-MM-DD] [force]"
    mk = registry_normalize_manager_key(parts[0])
    if not mk:
        return f"Неверный ключ менеджера: {parts[0]!r}"
    try:
        count = int(parts[1]) if len(parts) >= 2 else 15
    except (ValueError, IndexError):
        count = 15
    if len(parts) >= 3:
        target_date = str(parts[2]).strip()
    else:
        tz = ZoneInfo("Europe/Kyiv")
        target_date = (datetime.now(tz) + timedelta(days=1)).date().isoformat()
    # --- TPILOT BLD FORCE M2.14 START ---
    force = len(parts) >= 4 and str(parts[3]).strip().lower() in ("force", "override")
    if not force:
        working_keys = _bizlink_manual_schedule_working_keys(target_date)
        if working_keys and mk not in working_keys:
            return f"📅 Менеджер {mk} не в графике на {target_date}. Ссылки не создаются."
    else:
        print(
            f"[bizlink-override] schedule bypass confirmed by admin:"
            f" requested_by={user_id} manager_key={mk}"
            f" target_date={target_date} count={count}"
        )
        try:
            await _log_manager_danger_action(
                "bizlink_schedule_override",
                mk,
                int(user_id or 0),
                result=f"count={count} date={target_date}",
            )
        except Exception:
            pass
    # --- TPILOT BLD FORCE M2.14 END ---
    ok, text = await _queue_bizlink_create_n_for_manager(
        mk, target_date, count, user_id=user_id, timeout_sec=600
    )
    return text


async def _bizlink_create_all_bg_task(
    targets: list,
    count: int,
    target_date: str,
    user_id: int,
) -> None:
    """Background task: create count links for each target manager sequentially."""
    delay = _m213d2_mgr_delay if isinstance(_m213d2_mgr_delay, int) else 90
    results = []
    for r in targets:
        mk = registry_normalize_manager_key(str(r.get("manager_key") or ""))
        if not mk:
            continue
        try:
            ok, text = await _queue_bizlink_create_n_for_manager(
                mk, target_date, count, user_id=user_id, timeout_sec=600
            )
            if ok:
                results.append(f"✅ {mk}")
            else:
                results.append(f"⚠️ {mk}: {text[:100]}")
        except Exception as exc:
            results.append(f"❌ {mk}: {exc!r}"[:120])
        await asyncio.sleep(delay)
    try:
        p = target_date.split("-")
        date_disp = "{}-{}-{}".format(p[2], p[1], p[0])
    except Exception:
        date_disp = target_date
    lines = [
        "📦 Создание ссылок завершено",
        f"Дата: {date_disp} | Количество: {count}",
        "",
    ]
    lines += results
    try:
        await _send_ai_stat("\n".join(lines))
    except Exception as exc:
        print(f"bizlink_create_all_bg_task report error: {exc!r}")


async def _handle_bizlink_create_all_command(args: str, *, user_id: int = 0) -> str:
    """Parse /bizlink_create_all <count> [YYYY-MM-DD], fire background task, return fast."""
    parts = str(args or "").split()
    try:
        count = int(parts[0]) if parts else 15
    except (ValueError, IndexError):
        count = 15
    if len(parts) >= 2:
        target_date = str(parts[1]).strip()
    else:
        tz = ZoneInfo("Europe/Kyiv")
        target_date = (datetime.now(tz) + timedelta(days=1)).date().isoformat()
    # Clamp count
    if callable(_m213d2_clamp_count):
        count, avail = _m213d2_clamp_count(count, TPILOT_DB_PATH)
    else:
        avail = 15
        count = min(max(1, count), avail)
    # Gather active managers (not manually stopped)
    try:
        mgr_rows = await manager_list_rows(include_removed=False, only_enabled=True, only_active=True)
    except Exception:
        mgr_rows = []
    targets = [r for r in mgr_rows if not int(r.get("manual_stopped") or 0)]
    if not targets:
        return "Нет активных менеджеров для создания ссылок."
    working_keys = _bizlink_manual_schedule_working_keys(target_date)
    if working_keys:
        targets = [
            r for r in targets
            if registry_normalize_manager_key(str(r.get("manager_key") or "")) in working_keys
        ]
        if not targets:
            return f"📅 На {target_date} по графику нет рабочих менеджеров. Ссылки не создаются."
    asyncio.create_task(
        _bizlink_create_all_bg_task(targets, count, target_date, user_id)
    )
    try:
        p = target_date.split("-")
        date_disp = "{}-{}-{}".format(p[2], p[1], p[0])
    except Exception:
        date_disp = target_date
    note = f" (доступно {avail})" if avail < count else ""
    return (
        f"🚀 Создание ссылок запущено в фоне.\n"
        f"Менеджеров: {len(targets)}\n"
        f"Количество: {count}{note}\n"
        f"Дата: {date_disp}\n"
        f"Отчёт придёт по завершении."
    )


# M2.13D-2: stacked _panel_execute_command_text — routes /bizlink_create_n, /bizlink_create_all
_M213D2_ORIG_PANEL_EXEC = globals().get("_panel_execute_command_text")


async def _panel_execute_command_text(  # type: ignore[override]
    command_text: str,
    *,
    requested_by: int = 0,
    source_chat_id: int = 0,
    response_chat_id: int = 0,
):
    """M2.13D-2: route /bizlink_create_n and /bizlink_create_all before chaining to M2.13C."""
    text = str(command_text or "").strip()
    cmd, args = _parse_cmd(text)
    if cmd == "/bizlink_create_n":
        try:
            result_text = await _handle_bizlink_create_n_command(args, user_id=requested_by)
            ok = result_text.startswith("✅") or result_text.startswith("ℹ")
            return {"ok": ok, "result_text": result_text,
                    "error_text": ("" if ok else result_text)}
        except Exception as exc:
            return {"ok": False, "error_text": repr(exc),
                    "result_text": f"❌ Ошибка bizlink_create_n: {exc!r}"}
    if cmd == "/bizlink_create_all":
        try:
            result_text = await _handle_bizlink_create_all_command(args, user_id=requested_by)
            ok = result_text.startswith("🚀") or result_text.startswith("ℹ")
            return {"ok": ok, "result_text": result_text,
                    "error_text": ("" if ok else result_text)}
        except Exception as exc:
            return {"ok": False, "error_text": repr(exc),
                    "result_text": f"❌ Ошибка bizlink_create_all: {exc!r}"}
    if callable(_M213D2_ORIG_PANEL_EXEC):
        try:
            return await _M213D2_ORIG_PANEL_EXEC(
                command_text,
                requested_by=requested_by,
                source_chat_id=source_chat_id,
                response_chat_id=response_chat_id,
            )
        except TypeError:
            try:
                return await _M213D2_ORIG_PANEL_EXEC(command_text, requested_by=requested_by)
            except TypeError:
                return await _M213D2_ORIG_PANEL_EXEC(command_text)
    return {"ok": False, "error_text": f"Команда не поддерживается: {cmd or text}"}


# M2.13D-2: daily 14:00 Kyiv auto-create for managers marked working tomorrow
_BIZLINK_AC_RUNNING = False


async def _bizlink_autocreate_if_due() -> None:
    """Create bizlinks for tomorrow's working managers once per day at or after 14:00 Kyiv.
    Uses manager_work_schedule_days (is_working=1) — never manager_work_days."""
    if not CONTROLLER_MODE:
        return
    now = _kyiv_now()
    if now.hour < 14:
        return
    today = now.date().isoformat()
    flag = "bizlink_autocreate_done_{}".format(today)
    if (await get_setting(flag)) == "1":
        return
    # Claim first — prevents double-run on restart
    await set_setting(flag, "1")
    try:
        tz = ZoneInfo("Europe/Kyiv")
        tomorr = (now + timedelta(days=1)).date()
        tomorr_iso = tomorr.isoformat()
        tomorr_disp = tomorr.strftime("%d.%m.%Y")
        # Read configured default count
        count_raw = await get_setting("bizlink_default_count")
        try:
            req_count = int(count_raw or 15)
        except Exception:
            req_count = 15
        if callable(_m213d2_clamp_count):
            count, avail = _m213d2_clamp_count(req_count, TPILOT_DB_PATH)
        else:
            count = min(max(1, req_count), 15)
            avail = 15
        # Working keys for tomorrow (is_working=1 only, from schedule table)
        working_keys: set = set()
        if callable(_sched_ac_list):
            try:
                working_keys = set(_sched_ac_list(tomorr_iso, TPILOT_DB_PATH))
            except Exception as _we:
                print("bizlink_autocreate schedule list error: {!r}".format(_we))
        # Active + enabled + not manually stopped
        try:
            mgr_rows = await manager_list_rows(include_removed=False, only_enabled=True, only_active=True)
        except Exception:
            mgr_rows = []
        targets = [
            r for r in mgr_rows
            if not int(r.get("manual_stopped") or 0)
            and registry_normalize_manager_key(str(r.get("manager_key") or "")) in working_keys
        ]
        if not targets:
            await _send_ai_stat(
                "📦 Авто-создание ссылок на {}\n"
                "Нет менеджеров с is_working=1 в расписании.\n"
                "Отметьте рабочие дни в разделе Графики.".format(tomorr_disp)
            )
            return
        delay = _m213d2_mgr_delay if isinstance(_m213d2_mgr_delay, int) else 90
        results = []
        for r in targets:
            mk = registry_normalize_manager_key(str(r.get("manager_key") or ""))
            if not mk:
                continue
            display_name = str(r.get("display_name") or "").strip() or mk
            uname = str(r.get("telegram_username") or "").strip()
            label = f"{display_name} / @{uname}" if uname else display_name
            try:
                ok, text = await _queue_bizlink_create_n_for_manager(
                    mk, tomorr_iso, count, user_id=0, timeout_sec=600
                )
            except Exception as exc:
                ok, text = False, repr(exc)[:200]
            # Self-heal-first: judge readiness from actual DB state after the
            # attempt, not from ok/text alone -- ground truth for the alert.
            active_now = 0
            try:
                if callable(_bsl_links_mgr_date_m213c):
                    post_rows = _bsl_links_mgr_date_m213c(mk, tomorr_iso, TPILOT_DB_PATH)
                    active_now = sum(
                        1 for pr in post_rows
                        if str(pr.get("status") or "") == "created"
                        and str(pr.get("link_url") or "").strip()
                        and not str(pr.get("deleted_at") or "").strip()
                    )
            except Exception:
                pass
            missing_now = max(0, count - active_now)
            if missing_now <= 0:
                # Fully ready -- no alert needed, routine success line only.
                results.append(f"✅ {label}")
            else:
                reason = str(text or "").strip() or "неизвестная ошибка"
                hint = "" if "Панель" in reason else " Проверьте Панель → Бизнес-ссылки → Показать ссылки и Telegram Health."
                results.append(
                    "⚠️ {} ({}) — {}/{}, не хватает {}\n"
                    "Дата: {}\n"
                    "Причина: {}{}".format(
                        label, mk, active_now, count, missing_now, tomorr_disp, reason, hint
                    )
                )
            await asyncio.sleep(delay)
        lines = [
            "📦 Авто-создание ссылок",
            f"Дата: {tomorr_disp} | Количество: {count}/{avail}",
            "",
        ]
        lines += results
        await _send_ai_stat("\n".join(lines))
    except Exception as exc:
        print("bizlink_autocreate_if_due error: {!r}".format(exc))


async def _bizlink_autocreate_loop() -> None:
    """Controller-only loop: check every 60 s, run auto-create once per day at 14:00 Kyiv."""
    global _BIZLINK_AC_RUNNING
    if _BIZLINK_AC_RUNNING:
        return
    _BIZLINK_AC_RUNNING = True
    try:
        while True:
            try:
                await _bizlink_autocreate_if_due()
            except asyncio.CancelledError:
                return
            except Exception as exc:
                print("bizlink_autocreate_loop error: {!r}".format(exc))
            await asyncio.sleep(60)
    finally:
        _BIZLINK_AC_RUNNING = False

# --- TPILOT M2.13D-2 BIZLINK CREATE-N / AUTO-14:00 20260609 END ---


