_RSV_AC_RUNNING = False


async def _reserve_activation_process_one(event: Dict[str, Any]) -> None:
    """Process one claimed reserve_activation_events row (status already 'creating').
    Never raises: every failure path is captured into the event's status/last_error so
    PartnerBot's check button can show the partner a clear message."""
    if not callable(_rsvac_finish):
        return
    event_id = int(event.get("id") or 0)
    reserve_key = registry_normalize_manager_key(str(event.get("reserve_key") or ""))
    source_key = str(event.get("source_key") or "").strip()
    target_date = str(event.get("target_date") or "").strip()
    requested_by_user_id = int(event.get("requested_by_user_id") or 0)

    if not reserve_key or not target_date:
        try:
            _rsvac_finish(event_id, "failed", last_error="Некорректные данные заявки.", db_path=TPILOT_DB_PATH)
        except Exception:
            pass
        return

    try:
        reserve_row = await manager_get(reserve_key)
    except Exception as exc:
        reserve_row = None
        print(f"[stage_d_r2] manager_get failed for {reserve_key}: {exc!r}")

    if not reserve_row or str(reserve_row.get("status") or "") == "archived":
        try:
            _rsvac_finish(event_id, "failed", last_error=f"Резервный менеджер не найден: {reserve_key}", db_path=TPILOT_DB_PATH)
        except Exception:
            pass
        return

    if (
        str(reserve_row.get("status") or "") != "active"
        or int(reserve_row.get("is_enabled") or 0) != 1
        or int(reserve_row.get("manual_stopped") or 0) == 1
    ):
        try:
            _rsvac_finish(event_id, "failed", last_error=f"Резервный менеджер сейчас не активен: {reserve_key}", db_path=TPILOT_DB_PATH)
        except Exception:
            pass
        return

    # Make the reserve visible for the activation day (mirrors an admin schedule entry).
    # STAGE D R3: must run unconditionally, before the existing-links short-circuit below —
    # otherwise a reserve whose links already exist (e.g. re-activation, or an admin batch
    # that pre-created them) can be left with a stale is_working=0 row from an earlier
    # admin_toggle, which then hides it from PartnerBot's single-day stats filter.
    if callable(_rsvac_sched_set):
        try:
            _rsvac_sched_set(
                reserve_key, target_date, 1,
                source="reserve_activation", updated_by_user_id=requested_by_user_id,
                updated_by_role="reserve_activation", db_path=TPILOT_DB_PATH,
            )
        except Exception as exc:
            print(f"[stage_d_r3] schedule set failed for {reserve_key}: {exc!r}")

    # Ensure the reserve is linked to the same source as the primary (mirrors /source link).
    # STAGE D R3: also moved up, ahead of the idempotency short-circuit, for the same reason.
    if source_key:
        try:
            now = _now_utc_iso()
            async with aiosqlite.connect(TPILOT_DB_PATH) as db:
                await db.execute("""
                    INSERT INTO manager_source_links(manager_key, source_key, created_at, updated_at)
                    VALUES(?,?,?,?)
                    ON CONFLICT(manager_key) DO UPDATE SET source_key=excluded.source_key, updated_at=excluded.updated_at
                """, (reserve_key, source_key, now, now))
                await db.commit()
        except Exception as exc:
            print(f"[stage_d_r3] source link failed for {reserve_key}: {exc!r}")

    # Idempotency: count already-created links. If all 15 exist, finish done without
    # queueing duplicates (the same check also lives inside _queue_bizlink_create_n_for_manager).
    try:
        existing_rows = _bsl_links_mgr_date_m213c(reserve_key, target_date, TPILOT_DB_PATH) if callable(_bsl_links_mgr_date_m213c) else []
    except Exception:
        existing_rows = []
    created_slots = {
        int(r.get("slot_no") or 0)
        for r in existing_rows
        if str(r.get("status") or "") == "created"
        and str(r.get("link_url") or "").strip()
        and not str(r.get("deleted_at") or "").strip()
    }
    if len(created_slots) >= 15 and all(n in created_slots for n in range(1, 16)):
        try:
            _rsvac_finish(event_id, "done", db_path=TPILOT_DB_PATH)
        except Exception:
            pass
        try:
            await _rsvac_notify_activated(event)
        except Exception:
            pass
        return

    # Reuse the existing batch path unchanged. It already polls the manager process to
    # completion (or timeout), so ok=True here means the rows genuinely exist already.
    try:
        ok, text = await _queue_bizlink_create_n_for_manager(
            reserve_key, target_date, 15,
            user_id=requested_by_user_id, timeout_sec=255,
        )
    except Exception as exc:
        try:
            _rsvac_finish(event_id, "failed", last_error=repr(exc), db_path=TPILOT_DB_PATH)
        except Exception:
            pass
        return

    if not ok:
        try:
            _rsvac_finish(event_id, "failed", last_error=text, db_path=TPILOT_DB_PATH)
        except Exception:
            pass
        return

    try:
        _rsvac_finish(event_id, "done", batch_job_key=f"bizlink:{reserve_key}:{target_date}", db_path=TPILOT_DB_PATH)
    except Exception:
        pass
    try:
        await _rsvac_notify_activated(event)
    except Exception:
        pass


# --- TPILOT PATCH B RESERVE NOTIFY START ---
async def _rsvac_notify_activated(event: Dict[str, Any]) -> None:
    """Notify ManagerBot and AdminBot when a reserve activation completes successfully.
    Fail-open: never raises, never affects the activation result."""
    try:
        import json as _rsvac_nj
        primary_key = registry_normalize_manager_key(str(event.get("primary_key") or ""))
        reserve_key = registry_normalize_manager_key(str(event.get("reserve_key") or ""))
        source_key = str(event.get("source_key") or "").strip()
        target_date = str(event.get("target_date") or "").strip()
        partner_id = int(event.get("requested_by_user_id") or 0)
        if not primary_key or not reserve_key:
            return
        partner_name = ""
        if partner_id:
            try:
                async with aiosqlite.connect(TPILOT_DB_PATH) as _db:
                    _db.row_factory = aiosqlite.Row
                    _cur = await _db.execute(
                        "SELECT first_name, last_name, username FROM partner_buyers WHERE user_id=? LIMIT 1",
                        (partner_id,),
                    )
                    _row = await _cur.fetchone()
                    if not _row:
                        _cur2 = await _db.execute(
                            "SELECT first_name, last_name, username FROM partner_access_requests WHERE user_id=? LIMIT 1",
                            (partner_id,),
                        )
                        _row = await _cur2.fetchone()
                    if _row:
                        _fn = str(_row["first_name"] or "").strip()
                        _ln = str(_row["last_name"] or "").strip()
                        _un = str(_row["username"] or "").strip()
                        partner_name = " ".join([x for x in (_fn, _ln) if x]).strip()
                        if not partner_name and _un:
                            partner_name = f"@{_un}"
            except Exception:
                pass
        who = f"{partner_name} / {partner_id}" if partner_name else str(partner_id)
        time_str = datetime.now(tz=TZ_KYIV).replace(microsecond=0).strftime("%d.%m.%Y %H:%M")
        event_key = f"reserve_activated:{reserve_key}:{target_date}"
        payload_str = _rsvac_nj.dumps({
            "primary": primary_key,
            "reserve": reserve_key,
            "source_key": source_key,
            "target_date": target_date,
            "partner_id": partner_id,
            "partner_name": partner_name,
        }, ensure_ascii=False)
        now_iso = _now_utc_iso()
        try:
            async with aiosqlite.connect(TPILOT_DB_PATH) as _db:
                await _db.execute(
                    "INSERT OR IGNORE INTO manager_bot_events"
                    "(event_key, event_type, manager_key, chat_id, lead_date, daily_lead_id,"
                    " old_status, new_status, payload_json, source, created_at)"
                    " VALUES(?,?,?,0,?,0,'','',?,?,?)",
                    (event_key, "reserve_activated", primary_key, target_date,
                     payload_str, "reserve_activation", now_iso),
                )
                await _db.commit()
        except Exception as exc:
            print(f"[rsvac_notify] manager_bot_event insert error: {exc!r}")
        admin_body = (
            "\U0001f501 Активирован "
            "резервный "
            "аккаунт\n\n"
            f"Основной аккаунт: {primary_key}\n"
            f"Резервный аккаунт: {reserve_key}\n"
            f"Кто активировал: {who}\n"
            f"Источник действия: PartnerBot / {source_key or chr(8212)}\n"
            f"Время: {time_str}"
        )
        await _create_panel_notification(
            "reserve_activated", "\U0001f501 Активирован резервный аккаунт", admin_body
        )
    except Exception as exc:
        print(f"[rsvac_notify] notification error: {exc!r}")
# --- TPILOT PATCH B RESERVE NOTIFY END ---


async def _reserve_activation_loop() -> None:
    """Controller-only loop: poll reserve_activation_events every 5s, claim and process
    one request at a time. Reuses the existing 15-link batch path; no new Telethon logic,
    no stats changes."""
    global _RSV_AC_RUNNING
    if _RSV_AC_RUNNING:
        return
    _RSV_AC_RUNNING = True
    try:
        while True:
            try:
                if callable(_rsvac_take_next):
                    event = _rsvac_take_next(db_path=TPILOT_DB_PATH)
                    if event:
                        await _reserve_activation_process_one(event)
            except asyncio.CancelledError:
                return
            except Exception as exc:
                print(f"reserve_activation_loop error: {exc!r}")
            await asyncio.sleep(5)
    finally:
        _RSV_AC_RUNNING = False
# --- TPILOT STAGE D R2: RESERVE ACTIVATION CONTROLLER LOOP 20260621 END ---


