def _bizlink_delete_safe_sanitize(value: Any, max_len: int = 150) -> str:
    """Best-effort redaction for diagnostic text before it is logged or
    persisted (BIZLINK_DELETE_RESULT_FIX_CORRECTION 20260804, N-1/N-4).
    Never raises: any internal failure falls back to a fixed placeholder
    instead of propagating or returning the unredacted input.

    Redacts, in order: http(s):// and t.me URLs; proxy-like
    host:port:login:password strings; password/passwd/pwd/token/api_hash/
    api_id/api_key/auth/authorization/secret key=value pairs; *.session
    file paths. The exception class name and a short readable reason
    normally survive redaction (they rarely match the patterns above).
    Output is truncated to max_len -- this is for logs/audit rows, not an
    exact diagnostic.

    BIZLINK_DELETE_RESULT_FIX_FINAL_CORRECTION 20260804 (B-1): an
    independent review found that the original `\\S*\\.session\\S*` pattern
    -- two unanchored, unbounded `\\S*` quantifiers -- forces the backtracking
    sre engine into O(k^2) work for a whitespace-free run of length k that
    never matches ".session" (measured ~32s for a 128KB run, unusable for a
    1MB payload). Two independent fixes are applied together: (1) the regex
    itself now uses bounded `{0,80}` reps, which caps the engine's
    per-position backtrack cost at a constant regardless of run length,
    restoring O(n); (2) the working text is also truncated to a small
    bounded window BEFORE any regex runs at all, since only the first
    `max_len` output characters can ever survive the final truncation below
    -- content beyond a few times max_len can never appear in the returned
    string. Together this makes every call O(1) with respect to the input
    length, not just O(n).
    """
    try:
        limit = int(max_len)
        if limit <= 0:
            limit = 150
    except Exception:
        limit = 150
    try:
        text = str(value)
    except Exception:
        return "[unprintable]"
    try:
        # BIZLINK_DELETE_RESULT_FIX_FINAL_CORRECTION 20260804 (B-1): bound
        # the working text before any regex touches it. limit*4 leaves
        # generous headroom for redaction placeholders (which can locally
        # lengthen the text) to still land inside the final `limit`-char
        # output; the hard 4000 cap protects against a caller passing an
        # unusually large max_len.
        window = min(len(text), limit * 4, 4000)
        text = text[:window]
    except Exception:
        return "[sanitize_error]"
    try:
        text = re.sub(r"https?://\S+", "[URL_REDACTED]", text, flags=re.IGNORECASE)
        text = re.sub(r"\bt\.me/\S+", "[URL_REDACTED]", text, flags=re.IGNORECASE)
        text = re.sub(
            r"\b[A-Za-z0-9.\-]+:\d{2,5}:[^\s:]+:[^\s:]+",
            "[PROXY_REDACTED]", text,
        )
        text = re.sub(
            r"(?i)\b(password|passwd|pwd|token|api_hash|api_id|api_key|apikey|"
            r"authorization|auth|secret)\s*[:=]\s*\S+",
            lambda m: f"{m.group(1)}=[REDACTED]", text,
        )
        text = re.sub(
            r"[^\s]{0,80}\.session[^\s]{0,80}",
            "[SESSION_PATH_REDACTED]", text, flags=re.IGNORECASE,
        )
    except Exception:
        return "[sanitize_error]"
    try:
        return text[:limit]
    except Exception:
        return "[sanitize_error]"


def _bizlink_delete_safe_log(
    action: str,
    result: str,
    *,
    manager_key: str = "",
    slug: str = "",
    error_class: str = "",
    error_snippet: str = "",
) -> None:
    """Best-effort bounded structured log line for the bizlink delete audit
    path. The entire body -- argument handling, error_snippet sanitization,
    message construction and the print call -- runs inside one try/except,
    so this function can never raise regardless of what it is called with
    (BIZLINK_DELETE_RESULT_FIX_CORRECTION 20260804, N-6).

    error_snippet is passed through _bizlink_delete_safe_sanitize(), which
    redacts URLs, proxy host:port:login:password strings, password/token/
    api_hash/auth key=value pairs and *.session paths before logging
    (N-1). manager_key/slug/action/result/error_class are short internal
    identifiers and are logged as given.
    """
    try:
        parts = [f"action={action}", f"result={result}"]
        if manager_key:
            parts.append(f"manager_key={manager_key}")
        if slug:
            parts.append(f"slug={slug}")
        if error_class:
            parts.append(f"error_class={error_class}")
        if error_snippet:
            parts.append(f"error={_bizlink_delete_safe_sanitize(error_snippet)}")
        print("[bizlink_delete_audit] " + " ".join(parts))
    except Exception:
        pass


async def _manager_delete_business_links(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Delete TPilot-managed Business links by slug. Manager runtime only.

    Sequential; stops on FloodWait; marks each slug deleted/failed in DB.
    Never raises — all errors captured in return dict.
    """
    manager_key = str(payload.get("manager_key") or "")
    mode = str(payload.get("mode") or "")
    target_date = str(payload.get("target_date") or "")
    slugs = [str(s) for s in list(payload.get("slugs") or []) if str(s or "").strip()]
    links = list(payload.get("links") or [])
    requested_by_user_id = int(payload.get("requested_by_user_id") or 0)
    delay_sec = max(1, int(payload.get("delay_between_deletes_sec") or 3))

    deleted_slugs: List[str] = []
    failed_slugs: List[str] = []
    expired_slugs: List[str] = []
    errors: List[str] = []
    flood_wait_sec_out = 0

    if not _M213D3A_TG_DEL_AVAILABLE or _M213D3A_DelBizLinkReq is None:
        err = "Telethon DeleteBusinessChatLink not available"
        return {
            "ok": False,
            "manager_key": manager_key, "mode": mode, "target_date": target_date,
            "deleted": 0, "failed": len(slugs), "skipped": 0,
            "errors": [err], "deleted_slugs": [], "failed_slugs": slugs,
            "flood_wait_seconds": 0,
        }

    for i, slug in enumerate(slugs):
        slug = str(slug or "").strip()
        if not slug:
            continue
        try:
            await client(_M213D3A_DelBizLinkReq(slug=slug))
            # Success — soft-delete DB row
            try:
                if callable(_bsd3a_mark_deleted):
                    _bsd3a_mark_deleted(
                        manager_key, slug,
                        deleted_by_user_id=requested_by_user_id,
                        db_path=TPILOT_DB_PATH,
                    )
            except Exception as _db_err:
                print(f"[m2.13d3a] mark_deleted db error: {_db_err!r}")
            deleted_slugs.append(slug)
            # RUNTIME READINESS RC 20260805 (wave L7): the Telegram delete has
            # already succeeded at this point, so nothing after it may be able
            # to reclassify it. Logging is bookkeeping, not part of the delete
            # result -- if it ever raised (the helper is written not to, but
            # that is its own promise, not this loop's guarantee) the outer
            # `except` would have appended this same slug to failed_slugs as
            # well, putting it in BOTH lists and flipping ok to False for a
            # deletion that really happened.
            try:
                _bizlink_delete_safe_log(
                    "delete", "deleted", manager_key=manager_key, slug=slug
                )
            except Exception:
                pass
            # Sleep between deletes, but not after the last one
            remaining = len(slugs) - (i + 1)
            if remaining > 0:
                await asyncio.sleep(delay_sec)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            err_class = _bizlink_classify_error(exc)
            if err_class == "flood_wait":
                fw = int(getattr(exc, "seconds", 0) or 0)
                flood_wait_sec_out = fw
                err_text = f"FloodWait {fw}s"
                try:
                    if callable(_bsd3a_mark_delete_failed):
                        _bsd3a_mark_delete_failed(
                            manager_key, slug, err_text, TPILOT_DB_PATH
                        )
                except Exception:
                    pass
                failed_slugs.append(slug)
                errors.append(err_text)
                # Remaining slugs also fail (not attempted)
                for rem_slug in slugs[i + 1:]:
                    rem_slug = str(rem_slug or "").strip()
                    if rem_slug:
                        failed_slugs.append(rem_slug)
                break  # Stop on FloodWait — no retry
            low = repr(exc).lower()
            if "chatlink_slug_expired" in low or "slug_expired" in low:
                # The slug is already dead on Telegram's side -- treat it as already
                # deleted (soft-delete via the existing helper) so oldest_n never
                # re-selects it. This does NOT free tg_limit capacity by itself, but lets
                # the recovery loop skip past dead rows to reach real active old links.
                try:
                    if callable(_bsd3a_mark_deleted):
                        _bsd3a_mark_deleted(
                            manager_key, slug,
                            deleted_by_user_id=requested_by_user_id,
                            db_path=TPILOT_DB_PATH,
                        )
                except Exception as _db_err:
                    print(f"[m2.13d3a] mark_deleted (expired) db error: {_db_err!r}")
                expired_slugs.append(slug)
                # Wave L7: this call sits INSIDE the outer except handler, so a
                # raise here would escape _manager_delete_business_links entirely
                # and break its documented "never raises" contract.
                try:
                    _bizlink_delete_safe_log(
                        "delete", "slug_expired_cleaned", manager_key=manager_key, slug=slug
                    )
                except Exception:
                    pass
                # Sleep between deletes, but not after the last one (same pacing as a
                # real delete, to stay well clear of any Telegram rate limit).
                remaining = len(slugs) - (i + 1)
                if remaining > 0:
                    await asyncio.sleep(delay_sec)
                continue
            err_text = repr(exc)[:200]
            try:
                if callable(_bsd3a_mark_delete_failed):
                    _bsd3a_mark_delete_failed(
                        manager_key, slug, err_text, TPILOT_DB_PATH
                    )
            except Exception:
                pass
            failed_slugs.append(slug)
            errors.append(err_text)
            # Wave L7: same reasoning as the expired branch above -- this call
            # is inside the except handler and must not be able to escape it.
            try:
                _bizlink_delete_safe_log(
                    "delete", "failed", manager_key=manager_key, slug=slug,
                    error_class=type(exc).__name__, error_snippet=err_text,
                )
            except Exception:
                pass
            # Continue to next slug on non-FloodWait errors

    return {
        "ok": len(failed_slugs) == 0 and len(deleted_slugs) > 0 or (not slugs),
        "manager_key": manager_key,
        "mode": mode,
        "target_date": target_date,
        "deleted": len(deleted_slugs),
        "failed": len(failed_slugs),
        "skipped": 0,
        "errors": errors,
        "deleted_slugs": deleted_slugs,
        "failed_slugs": failed_slugs,
        "flood_wait_seconds": flood_wait_sec_out,
        "expired_cleaned": len(expired_slugs),
        "expired_slugs": expired_slugs,
    }


async def _queue_bizlink_delete_tpilot_for_manager(
    preview_id: str,
    *,
    user_id: int = 0,
    timeout_sec: int = 255,
) -> Tuple[bool, str]:
    """Controller-side: validate+consume preview, enqueue bizlink_delete_tpilot, poll result.

    Returns (ok, result_text). Writes audit row after completion.
    """
    import json as _m213d3a_ctrl_json
    try:
        from storage import (
            manager_queue_put as _mqput_del,
            manager_queue_get as _mqget_del,
        )
    except Exception as e:
        return False, f"Ошибка очереди: {e!r}"

    # Load preview
    if not callable(_bsd3a_preview_get):
        return False, "Модуль storage недоступен."
    preview = _bsd3a_preview_get(str(preview_id or ""), TPILOT_DB_PATH)
    if not preview:
        return False, "Preview не найден. Создайте новый запрос на удаление."

    if int(preview.get("consumed") or 0):
        return False, "Это подтверждение уже было использовано (single-use)."

    # Check expiry
    now_iso = _tp_utc_now().replace(microsecond=0).isoformat()
    if str(preview.get("expires_at") or "") <= now_iso:
        return False, "Preview ис��ёк (>5 мин). Создайте новый."

    # Atomic consume — prevents double execution
    if not callable(_bsd3a_preview_consume):
        return False, "Модуль storage недоступен."
    consumed = _bsd3a_preview_consume(str(preview_id or ""), TPILOT_DB_PATH)
    if not consumed:
        return False, "Не удалось зафиксировать подтверждение (уже выполнено или истекло)."

    mk = registry_normalize_manager_key(str(preview.get("manager_key") or ""))
    if not mk:
        return False, "Пустой ключ менеджера в preview."

    try:
        slugs = _m213d3a_ctrl_json.loads(str(preview.get("slugs_json") or "[]"))
    except Exception:
        slugs = []
    try:
        links = _m213d3a_ctrl_json.loads(str(preview.get("link_urls_json") or "[]"))
    except Exception:
        links = []

    if not slugs:
        return False, "Preview не содержит ссылок для удаления."

    mode = str(preview.get("mode") or "")
    target_date = str(preview.get("target_date") or "")
    preview_created_at = str(preview.get("created_at") or "")

    payload = {
        "manager_key": mk,
        "mode": mode,
        "target_date": target_date,
        "slugs": slugs,
        "links": links,
        "preview_id": str(preview_id or ""),
        "requested_by_user_id": int(user_id or preview.get("requested_by_user_id") or 0),
        "delay_between_deletes_sec": 3,
    }

    try:
        nonce = await _mqput_del(
            target_key=mk,
            command="bizlink_delete_tpilot",
            args="",
            payload_json=_m213d3a_ctrl_json.dumps(payload, ensure_ascii=False),
            created_by=f"admin:{user_id}",
            db_path=TPILOT_DB_PATH,
        )
    except Exception as e:
        return False, f"Ошибка постановки в очередь: {e!r}"

    # Poll for result
    started = asyncio.get_event_loop().time()
    while asyncio.get_event_loop().time() - started < timeout_sec:
        await asyncio.sleep(1.0)
        try:
            row = await _mqget_del(nonce, db_path=TPILOT_DB_PATH)
        except Exception:
            row = None
        if row and str(row.get("status") or "") in ("done", "error"):
            ok_flag = str(row.get("status") or "") == "done"
            result_text = str(row.get("result_text") or "")
            # Parse result dict for precise audit counts. Accepts both the
            # current JSON payload and legacy str(dict) Python-repr payloads
            # written by older D3A builds (BIZLINK_DELETE_RESULT_FIX
            # 20260804) -- a payload that parses as neither is a VISIBLE
            # parse failure, never a silent "0 deleted / 0 failed" that
            # looks like a real empty result.
            raw_result = str(row.get("result_json") or "")
            result_dict = None
            if raw_result.strip():
                try:
                    _parsed = _m213d3a_ctrl_json.loads(raw_result)
                    if isinstance(_parsed, dict):
                        result_dict = _parsed
                except Exception:
                    result_dict = None
                if result_dict is None:
                    try:
                        import ast as _m213d3a_ctrl_ast
                        _parsed_legacy = _m213d3a_ctrl_ast.literal_eval(raw_result)
                        if isinstance(_parsed_legacy, dict):
                            result_dict = _parsed_legacy
                    except Exception:
                        result_dict = None
            parse_failed = bool(raw_result.strip()) and result_dict is None
            if result_dict is None:
                result_dict = {}
            audit_result_ok = bool(ok_flag) and not parse_failed
            audit_error_class = "result_parse_failed" if parse_failed else ""
            # BIZLINK_DELETE_RESULT_FIX_FINAL_CORRECTION 20260804 (§3): the
            # queue row's own error_text can carry the same
            # URL/credential/session-path-shaped content the parse-failure
            # diagnostic already guards against (N-4) -- sanitize it too,
            # unconditionally, before it reaches bizlink_delete_audit.error_text.
            audit_error_text = _bizlink_delete_safe_sanitize(row.get("error_text") or "", 500)
            if parse_failed:
                safe_prefix = _bizlink_delete_safe_sanitize(raw_result, 200)
                note = f"result_parse_failed raw_prefix={safe_prefix!r}"
                audit_error_text = (
                    note if not audit_error_text else f"{audit_error_text} | {note}"
                )[:500]
                _bizlink_delete_safe_log(
                    "parse_delete_result", "failed",
                    manager_key=mk, error_class="result_parse_failed",
                )
            # Write audit row
            try:
                if callable(_bsd3a_audit_add):
                    _bsd3a_audit_add(
                        mk, mode,
                        target_date=target_date,
                        requested_count=int(preview.get("exact_count") or 0),
                        deleted_count=int(result_dict.get("deleted") or 0),
                        failed_count=int(result_dict.get("failed") or 0),
                        slugs_json=str(preview.get("slugs_json") or "[]"),
                        link_urls_json=str(preview.get("link_urls_json") or "[]"),
                        requested_by_user_id=int(user_id or 0),
                        requested_by=f"admin:{user_id}",
                        source="tpilot",
                        result_ok=audit_result_ok,
                        error_class=audit_error_class,
                        error_text=audit_error_text,
                        created_at=preview_created_at,
                        finished_at=_tp_utc_now().replace(microsecond=0).isoformat(),
                        db_path=TPILOT_DB_PATH,
                    )
            except Exception as _ae:
                print(f"[m2.13d3a] audit_add error: {_ae!r}")
            return ok_flag, result_text

    return False, f"Менеджер {mk} не ответил за {timeout_sec}s."


async def _handle_bizlink_delete_command(args: str, *, user_id: int = 0) -> str:
    """Parse /bizlink_delete_tpilot <preview_id> and execute via queue."""
    parts = str(args or "").strip().split()
    if not parts:
        return "Формат: /bizlink_delete_tpilot <preview_id>"
    preview_id = parts[0].strip()
    if not preview_id:
        return "Пустой preview_id."
    ok, text = await _queue_bizlink_delete_tpilot_for_manager(
        preview_id, user_id=user_id, timeout_sec=255
    )
    return text


# M2.13D-3A: stacked _panel_execute_command_text override — routes /bizlink_delete_tpilot
_M213D3A_ORIG_PANEL_EXEC = globals().get("_panel_execute_command_text")


async def _panel_execute_command_text(  # type: ignore[override]
    command_text: str, *, requested_by: int = 0
) -> dict:
    """M2.13D-3A: route /bizlink_delete_tpilot before chaining to M2.13D-2."""
    cmd, _, args = str(command_text or "").strip().partition(" ")
    args = args.strip()
    if cmd == "/bizlink_delete_tpilot":
        try:
            result_text = await _handle_bizlink_delete_command(args, user_id=requested_by)
        except Exception as exc:
            result_text = f"❌ Ошибка bizlink_delete_tpilot: {exc!r}"
        return {"ok": True, "result_text": result_text}
    if callable(_M213D3A_ORIG_PANEL_EXEC):
        return await _M213D3A_ORIG_PANEL_EXEC(command_text, requested_by=requested_by)
    return {"ok": False, "result_text": f"Команда не поддерживается: {cmd}"}


