# --- TPILOT LLM RUNTIME TOGGLE (Patch A) START ---
# AdminBot button writes settings['llm_supervisor_enabled'] = '0'/'1' to the central DB.
# This helper is the master gate: '0' stops all llm_supervisor_shadow calls even if env=true.
# Missing key or read error → fall back to env LLM_SUPERVISOR_ENABLED (behavior unchanged).
_LLM_RTGATE_CACHE: Optional[bool] = None
_LLM_RTGATE_CACHE_AT: float = 0.0
_LLM_RTGATE_TTL: float = 20.0  # seconds


async def _llm_runtime_enabled() -> bool:
    """Return True if LLM observer is enabled (DB toggle master; env fallback if key missing)."""
    global _LLM_RTGATE_CACHE, _LLM_RTGATE_CACHE_AT
    import time as _t
    now = _t.monotonic()
    if _LLM_RTGATE_CACHE is not None and now - _LLM_RTGATE_CACHE_AT < _LLM_RTGATE_TTL:
        return _LLM_RTGATE_CACHE
    try:
        val = await get_setting_from_db(TPILOT_DB_PATH, "llm_supervisor_enabled")
        if val == "0":
            result = False
        elif val == "1":
            result = True
        else:
            result = _llmq_cfg_bool("LLM_SUPERVISOR_ENABLED", False)
        _LLM_RTGATE_CACHE = result
        _LLM_RTGATE_CACHE_AT = now
        return result
    except Exception:
        return _llmq_cfg_bool("LLM_SUPERVISOR_ENABLED", False)
# --- TPILOT LLM RUNTIME TOGGLE (Patch A) END ---


# --- TPILOT DEBOUNCE QUESTIONNAIRE REPLY Stage C 20260624 START ---
# Wraps _tp_gq_send_questionnaire_followup so bursts of client messages
# (e.g. МО / Дубна / 22 sent as 3 messages) are coalesced into one reply.
#
# Feature flags (env, defaults OFF):
#   LLM_QUEUE_DEBOUNCE_ENABLED=false    — master switch; false = no timing change
#   LLM_QUEUE_DEBOUNCE_IDLE_SEC=6       — reset on each new message in the burst
#   LLM_QUEUE_DEBOUNCE_MAX_WAIT_SEC=20  — hard cap from first message in burst
#
# Safety:
#   - flag off  → original called immediately, zero behaviour change
#   - any error → fail-open, call original once
#   - no DB writes, no schema change, no Telegram sends added
#   - CancelledError silently swallowed (not an unhandled warning)

_LLMQ_VERSION = "debounce_v1_20260624"
_LLMQ_ORIG_FOLLOWUP = globals().get("_tp_gq_send_questionnaire_followup")

# Per-chat in-process state; keys are int chat_id
_llmq_debounce_tasks: Dict[int, "asyncio.Task[None]"] = {}
_llmq_debounce_first_seen: Dict[int, float] = {}
_llmq_debounce_last_args: Dict[int, tuple] = {}


def _llmq_cfg_bool(key: str, default: bool) -> bool:
    v = os.environ.get(key, "").strip().lower()
    return default if not v else v in ("1", "true", "yes", "on")


def _llmq_cfg_float(key: str, default: float) -> float:
    try:
        v = os.environ.get(key, "").strip()
        return float(v) if v else default
    except Exception:
        return default


def _llmq_split_recent_messages(text: str) -> Optional[List[str]]:
    """Split burst/single text into a clean list for LLM recent_messages payload. Return None if empty."""
    parts = [s[:400] for s in str(text or "").split("\n") if s.strip()][:6]
    return parts if parts else None


async def _llmq_aggregate_burst(chat_id: int, max_wait_sec: float) -> str:
    """Return recent client inbound texts joined by newline. Fail-open → ""."""
    try:
        cutoff_dt = datetime.now(timezone.utc) - timedelta(seconds=max_wait_sec + 5)
        cutoff_iso = cutoff_dt.replace(tzinfo=None, microsecond=0).isoformat()
        async with aiosqlite.connect(DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            await db.execute("PRAGMA busy_timeout=5000;")
            cur = await db.execute(
                """
                SELECT text FROM inbound_events
                WHERE chat_id=?
                  AND COALESCE(message_date_utc, received_at_utc, created_at, '') >= ?
                  AND COALESCE(text, '') <> ''
                ORDER BY COALESCE(message_date_utc, received_at_utc, created_at) ASC, id ASC
                LIMIT 6
                """,
                (int(chat_id), cutoff_iso),
            )
            rows = await cur.fetchall()
        texts = [str(r["text"] or "").strip() for r in rows if str(r["text"] or "").strip()]
        return "\n".join(texts) if texts else ""
    except Exception:
        return ""


async def _llmq_fire(chat_id: int, idle_sec: float, max_wait_sec: float) -> None:
    """Sleep idle_sec, then fire the original followup once for this chat_id."""
    try:
        await asyncio.sleep(idle_sec)
    except asyncio.CancelledError:
        return  # superseded by a later message in the burst — do nothing

    # Retrieve and clear stored args
    stored = _llmq_debounce_last_args.pop(chat_id, None)
    _llmq_debounce_tasks.pop(chat_id, None)
    _llmq_debounce_first_seen.pop(chat_id, None)

    if stored is None or not callable(_LLMQ_ORIG_FOLLOWUP):
        return

    orig_lead_row, orig_state, orig_cid = stored

    # Reload fresh lead_row so passive-parse updates during the wait are visible
    try:
        lead_date = str(orig_lead_row.get("lead_date") or _kyiv_now().date().isoformat())
        manager_key = str(orig_lead_row.get("manager_key") or MANAGER_RUNTIME_KEY or "")
        if manager_key:
            fresh = await _tp_qs_fetch_daily_row(DB_PATH, lead_date, manager_key, int(orig_cid))
            if fresh:
                fresh = dict(fresh)
                # Preserve runtime-only key set before the debounce window
                if orig_lead_row.get("_last_incoming_text"):
                    fresh.setdefault("_last_incoming_text", orig_lead_row["_last_incoming_text"])
                orig_lead_row = fresh
    except Exception:
        pass

    # Aggregate burst texts and inject as _last_incoming_text
    try:
        burst = await _llmq_aggregate_burst(orig_cid, max_wait_sec)
        if burst:
            orig_lead_row = dict(orig_lead_row)
            orig_lead_row["_last_incoming_text"] = burst
    except Exception:
        pass

    # Reload auto-state so reply decisions use up-to-date counters
    try:
        fresh_state = await _get_auto_state(DB_PATH, orig_cid)
        if fresh_state:
            orig_state = fresh_state
    except Exception:
        pass

    try:
        await _LLMQ_ORIG_FOLLOWUP(orig_lead_row, orig_state, orig_cid)
    except Exception as _llmq_fire_exc:
        try:
            print(f"[llmq_debounce] fire error chat={orig_cid}: {_llmq_fire_exc!r:.120}")
        except Exception:
            pass


async def _tp_gq_send_questionnaire_followup(  # type: ignore[override]
    lead_row: Dict[str, Any],
    state: Dict[str, Any],
    chat_id: int,
) -> None:
    """Stage C debounce wrapper for questionnaire followup replies.

    If LLM_QUEUE_DEBOUNCE_ENABLED is false (default), calls original immediately —
    zero behavior change. If true, coalesces burst messages before replying once.
    """
    if not _llmq_cfg_bool("LLM_QUEUE_DEBOUNCE_ENABLED", False):
        if callable(_LLMQ_ORIG_FOLLOWUP):
            await _LLMQ_ORIG_FOLLOWUP(lead_row, state, chat_id)
        return

    idle_sec = _llmq_cfg_float("LLM_QUEUE_DEBOUNCE_IDLE_SEC", 6.0)
    max_wait_sec = _llmq_cfg_float("LLM_QUEUE_DEBOUNCE_MAX_WAIT_SEC", 20.0)
    cid = int(chat_id or 0)
    if cid <= 0:
        if callable(_LLMQ_ORIG_FOLLOWUP):
            await _LLMQ_ORIG_FOLLOWUP(lead_row, state, cid)
        return

    now_mono = asyncio.get_event_loop().time()

    # Always store latest args for this chat (fire task reads these)
    _llmq_debounce_last_args[cid] = (dict(lead_row or {}), dict(state or {}), cid)

    first_seen = _llmq_debounce_first_seen.get(cid)

    # Hard cap: if max_wait already elapsed, fire inline without further delay
    if first_seen is not None and (now_mono - first_seen) >= max_wait_sec:
        pending = _llmq_debounce_tasks.pop(cid, None)
        if pending and not pending.done():
            pending.cancel()
        _llmq_debounce_first_seen.pop(cid, None)
        _llmq_debounce_last_args.pop(cid, None)
        burst = ""
        try:
            burst = await _llmq_aggregate_burst(cid, max_wait_sec)
        except Exception:
            pass
        lead_copy = dict(lead_row or {})
        if burst:
            lead_copy["_last_incoming_text"] = burst
        if callable(_LLMQ_ORIG_FOLLOWUP):
            await _LLMQ_ORIG_FOLLOWUP(lead_copy, state, cid)
        return

    # Mark first_seen for this burst
    if first_seen is None:
        _llmq_debounce_first_seen[cid] = now_mono

    # Cancel any pending task and schedule a new one
    pending = _llmq_debounce_tasks.pop(cid, None)
    if pending and not pending.done():
        pending.cancel()

    task = asyncio.create_task(_llmq_fire(cid, idle_sec, max_wait_sec))
    _llmq_debounce_tasks[cid] = task

# --- TPILOT DEBOUNCE QUESTIONNAIRE REPLY Stage C 20260624 END ---


# --- TPILOT LLM LIVE Stage E 20260624 START ---
# Guarded live LLM clarification text for allowlisted managers/chats.
#
# Feature flags (env, defaults safe/off):
#   LLM_SUPERVISOR_ENABLED=true      — master switch (existing)
#   LLM_SUPERVISOR_MODE=live         — must be exactly "live" (existing)
#   LLM_LIVE_ALLOW_MANAGERS=te,mgr2 — comma-sep normalized manager_keys
#   LLM_LIVE_ALLOW_CHAT_IDS=...      — optional; if set, also filter by chat_id
#   LLM_LIVE_TIMEOUT_SEC=4           — live API timeout (supervisor default 4s)
#   LLM_LIVE_MIN_CONFIDENCE=high     — supervisor default; min confidence to accept
#
# Safety:
#   - empty allowlist  -> no live (default)
#   - mode != live     -> no live
#   - disabled         -> no live
#   - any error        -> fail-open to deterministic det_text
#   - only replaces wording in decision.send_text branch
#   - deterministic close, update_fields, attempts, counters all unchanged
#   - passive autodetection not touched


def _tp_llm_live_allowed(lead_row: Dict[str, Any], chat_id: int) -> bool:
    """Quick pre-check: is live LLM configured for this manager/chat?
    Does NOT check enabled/mode — llm_supervisor_live_text gates those internally."""
    if not _LLM_SUPERVISOR_OK or _llm_supervisor_mod is None:
        return False
    allow_mgr = os.environ.get("LLM_LIVE_ALLOW_MANAGERS", "").strip()
    if not allow_mgr:
        return False
    manager_key = _tp_gq_norm_key(
        str((lead_row or {}).get("manager_key") or MANAGER_RUNTIME_KEY or "")
    )
    if not manager_key:
        return False
    allowed_mgrs = {
        _tp_gq_norm_key(m) for m in allow_mgr.split(",") if m.strip()
    }
    if manager_key not in allowed_mgrs:
        return False
    allow_chats = os.environ.get("LLM_LIVE_ALLOW_CHAT_IDS", "").strip()
    if allow_chats:
        try:
            allowed_ids = {int(c.strip()) for c in allow_chats.split(",") if c.strip()}
            if int(chat_id) not in allowed_ids:
                return False
        except Exception:
            return False
    return True


async def _tp_llm_live_text_or_default(
    lead_row: Dict[str, Any],
    dialog_state: Dict[str, Any],
    client_text: str,
    decision: Dict[str, Any],
    det_text: str,
    chat_id: int,
) -> str:
    """Return LLM-generated clarification wording or det_text on any failure/fallback.
    llm_supervisor_live_text applies all acceptance checks internally and returns
    the validated dict only when live_used; None means live_fallback -> use det_text."""
    if not det_text:
        return det_text
    if not _tp_llm_live_allowed(lead_row, int(chat_id)):
        return det_text
    try:
        result = await _llm_supervisor_mod.llm_supervisor_live_text(
            lead_row, dialog_state, client_text, det_decision=decision,
        )
        if result is None:
            return det_text
        live_msg = str(result.get("message_to_send") or "").strip()
        return live_msg if live_msg else det_text
    except Exception:
        return det_text

# --- TPILOT LLM LIVE Stage E 20260624 END ---


# --- TPILOT LLM F1 AUDIT Stage F1 20260624 START ---
# Persist LLM auto status into llm_auto_status table for audit/comparison only.
# Does NOT affect official statistics, daily_leads, lead_status_overrides, or stats_engine.
# Fail-open: any exception is silently swallowed.
#
# Status mapping:
#   LLM handoff liquid              -> "liquid"
#   LLM handoff nonliquid_geo       -> "geo"
#   LLM handoff nonliquid_under18   -> "under18"
#   LLM handoff nonliquid_na        -> "na"
#   LLM handoff ua_redirect         -> "geo"
#   LLM action clarify              -> "na" (still gathering info)
#   LLM action wait/no_action       -> skip (noisy, no classification yet)
#
# Write policy: write row only when action in ("handoff", "clarify").
# Upsert (INSERT OR REPLACE) on UNIQUE(lead_date, manager_key, chat_id).
# Manual priority: manual_status_override==1 is flagged in manual_status;
#   no extra DB read is made (lead_status_overrides JOIN deferred to reporting).

_LLM_HANDOFF_TO_STATUS: Dict[str, str] = {
    "liquid": "liquid",
    "nonliquid_geo": "geo",
    "nonliquid_under18": "under18",
    "nonliquid_na": "na",
    "ua_redirect": "geo",
}


async def _tp_llm_status_persist(
    db_path: str,
    lead_row: Dict[str, Any],
    llm_parsed: Optional[Dict[str, Any]],
    client_text: str,
    *,
    store_noaction_as_pending: bool = False,
) -> None:
    """Write LLM auto status audit row to llm_auto_status. Fail-open. Never raises.
    No impact on official statistics, daily_leads, or lead_status_overrides.
    store_noaction_as_pending: if True, write wait/no_action rows with llm_auto_status='pending'
    (passive observer observability). Existing followup callers default to False."""
    try:
        if not db_path or not lead_row:
            return
        if llm_parsed is None:
            return

        action = str(llm_parsed.get("action") or "")
        _store_noaction = store_noaction_as_pending and action in ("wait", "no_action")
        if action not in ("handoff", "clarify") and not _store_noaction:
            return

        handoff = str(llm_parsed.get("handoff") or "")
        _invalid_handoff_flag = False
        if action == "handoff":
            if handoff and handoff != "none" and handoff in _LLM_HANDOFF_TO_STATUS:
                llm_auto = _LLM_HANDOFF_TO_STATUS[handoff]
            else:
                llm_auto = "na"
                _invalid_handoff_flag = True
        elif action == "clarify":
            llm_auto = "na"
        else:
            llm_auto = "na"

        manager_key = str(lead_row.get("manager_key") or "")
        chat_id = str(lead_row.get("chat_id") or "")
        lead_date = str(lead_row.get("lead_date") or "")
        if not manager_key or not chat_id or not lead_date:
            return

        det_auto = str(lead_row.get("quality_bucket") or lead_row.get("status") or "")
        manual_override = int(lead_row.get("manual_status_override") or 0)
        manual_status_val = "manual_override" if manual_override == 1 else ""

        if manual_override == 1:
            final_status_used = "manual_override"
        elif det_auto:
            final_status_used = det_auto
        else:
            final_status_used = llm_auto

        agrees: Optional[int] = None
        mismatch_reason = "invalid_handoff" if _invalid_handoff_flag else ""
        if manual_override == 1:
            sep = " " if mismatch_reason else ""
            mismatch_reason += sep + "manual_present_no_lookup"
        elif det_auto:
            agrees = 1 if llm_auto == det_auto else 0
            if agrees == 0:
                sep = " " if mismatch_reason else ""
                mismatch_reason += sep + f"llm={llm_auto} det={det_auto}"

        try:
            src_hash = hashlib.sha256(
                str(client_text or "").encode("utf-8", errors="replace")
            ).hexdigest()[:12]
        except Exception:
            src_hash = ""

        safety_raw = llm_parsed.get("safety_flags") or []
        safety_str = ",".join(str(f) for f in safety_raw) if safety_raw else ""
        now_iso = datetime.now(timezone.utc).isoformat()

        async with aiosqlite.connect(str(db_path)) as db:
            await db.execute("PRAGMA busy_timeout=5000;")
            await db.execute(
                """INSERT OR REPLACE INTO llm_auto_status(
                    manager_key, chat_id, lead_date,
                    final_status_used, manual_status,
                    llm_auto_status, deterministic_auto_status,
                    llm_reason, llm_detail,
                    city, country, region, age, current_location,
                    confidence, safety_flags,
                    source_hash, source_window,
                    agrees_with_manager, mismatch_reason,
                    created_at, updated_at
                ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    manager_key, chat_id, lead_date,
                    final_status_used, manual_status_val,
                    llm_auto, det_auto,
                    str(llm_parsed.get("reason") or "")[:200], "",
                    str(lead_row.get("city") or ""),
                    str(lead_row.get("country") or ""),
                    str(lead_row.get("region") or ""),
                    str(lead_row.get("age") or ""),
                    str(lead_row.get("current_location") or ""),
                    str(llm_parsed.get("confidence") or ""),
                    safety_str,
                    src_hash, str(len(str(client_text or ""))),
                    agrees, mismatch_reason,
                    now_iso, now_iso,
                ),
            )
            await db.commit()
    except Exception:
        pass

# --- TPILOT LLM F1 AUDIT Stage F1 20260624 END ---


# --- TPILOT LLM F1P PASSIVE OBSERVER Stage F1P 20260624 START ---
# Passive LLM observer for manual manager-lead chats.
# Triggers after every eligible inbound client message, independent of auto questionnaire.
#
# Feature flags (env, all default safe/off):
#   LLM_PASSIVE_OBSERVER_ENABLED=false          — master switch; false = noop (default OFF)
#   LLM_PASSIVE_OBSERVER_IDLE_SEC=8             — reset debounce on each new message in burst
#   LLM_PASSIVE_OBSERVER_MIN_INTERVAL_SEC=90    — throttle: skip LLM if last call < N sec ago
#   LLM_PASSIVE_OBSERVER_STORE_NOACTION=false   — write wait/no_action rows as pending (default OFF)
#
# Safety invariants:
#   - master flag off           → noop, zero behavior change
#   - any error                 → fail-open, original inbound handler always unaffected
#   - no _send_manager_private or client.send_message calls
#   - no daily_leads / quality_* / lead_status_overrides / stats_engine writes
#   - only DB write: _tp_llm_status_persist → llm_auto_status (audit only)
#   - does NOT call _maybe_auto_reply_to_lead
#   - LLM_SUPERVISOR_ENABLED + LLM_SUPERVISOR_MODE gating respected inside llm_supervisor_shadow
#   - CancelledError silently swallowed (debounce burst coalescing)

_PASSIVE_LLM_ORIG_RECORD_INCOMING = globals().get("_record_incoming_from_manager")

# Per-chat in-process debounce/throttle state (chat_id → asyncio.Task / float)
_plobs_debounce_tasks: Dict[int, "asyncio.Task[None]"] = {}
_plobs_last_call_mono: Dict[int, float] = {}


async def _plobs_fire(
    chat_id: int,
    text_at_schedule: str,
    idle_sec: float,
    min_interval: float,
    store_noaction: bool,
) -> None:
    """Debounced passive LLM observer fire. Fail-open. Never raises."""
    try:
        await asyncio.sleep(idle_sec)
    except asyncio.CancelledError:
        return  # Superseded by a later message in the burst — normal burst coalescing

    try:
        _plobs_debounce_tasks.pop(chat_id, None)

        # Throttle: skip if LLM was called too recently for this chat
        now_mono = asyncio.get_event_loop().time()
        last = _plobs_last_call_mono.get(chat_id, 0.0)
        if now_mono - last < min_interval:
            return
        _plobs_last_call_mono[chat_id] = now_mono

        if not DB_PATH or not MANAGER_RUNTIME_KEY:
            return

        # Re-fetch fresh lead_row — passive parse already ran in original handler
        today = _kyiv_now().date().isoformat()
        lead_row: Dict[str, Any] = {}
        try:
            fetched = await _tp_qs_fetch_daily_row(DB_PATH, today, MANAGER_RUNTIME_KEY, chat_id)
            if fetched:
                lead_row = dict(fetched)
        except Exception:
            pass

        if not lead_row:
            return
        if not str(lead_row.get("manager_key") or "").strip():
            lead_row["manager_key"] = MANAGER_RUNTIME_KEY
        if not str(lead_row.get("chat_id") or "").strip():
            lead_row["chat_id"] = str(chat_id)

        # Aggregate recent burst from inbound_events (reuse Stage C helper)
        max_wait = max(idle_sec * 2, 20.0)
        client_text = ""
        try:
            if callable(globals().get("_llmq_aggregate_burst")):
                client_text = await _llmq_aggregate_burst(chat_id, max_wait) or ""
        except Exception:
            pass
        if not client_text:
            client_text = text_at_schedule

        # Load dialog state
        dialog_state: Dict[str, Any] = {}
        try:
            ds = await load_profile_dialog_state(DB_PATH, chat_id)
            if ds:
                dialog_state = dict(ds)
        except Exception:
            pass

        # Build deterministic decision context (comparison only, not sent)
        det_decision: Optional[Dict[str, Any]] = None
        try:
            if callable(globals().get("choose_profile_reply")):
                _tmp_row = dict(lead_row)
                _tmp_row["_last_incoming_text"] = client_text
                det_decision = choose_profile_reply(_tmp_row, client_text, dialog_state)
        except Exception:
            pass

        # LLM shadow (LLM_SUPERVISOR_ENABLED + MODE gating lives inside shadow)
        llm_parsed: Optional[Dict[str, Any]] = None
        try:
            if _LLM_SUPERVISOR_OK and _llm_supervisor_mod is not None and await _llm_runtime_enabled():
                llm_parsed = await _llm_supervisor_mod.llm_supervisor_shadow(
                    lead_row, dialog_state, client_text, det_decision=det_decision,
                    recent_messages=_llmq_split_recent_messages(client_text),
                )
        except Exception:
            pass

        # Persist to llm_auto_status only — no other DB writes
        try:
            await _tp_llm_status_persist(
                DB_PATH, lead_row, llm_parsed, client_text,
                store_noaction_as_pending=store_noaction,
            )
        except Exception:
            pass

    except Exception:
        pass


async def _record_incoming_from_manager(event: events.NewMessage.Event) -> None:  # type: ignore[override]
    """Stage F1P: passive observer wrapper. Calls original first; schedules audit task after."""
    result = None
    if callable(_PASSIVE_LLM_ORIG_RECORD_INCOMING):
        result = await _PASSIVE_LLM_ORIG_RECORD_INCOMING(event)

    try:
        if (
            not CONTROLLER_MODE
            and MANAGER_RUNTIME_KEY
            and DB_PATH
            and getattr(event, "is_private", False)
            and not getattr(event, "out", False)
            and _llmq_cfg_bool("LLM_PASSIVE_OBSERVER_ENABLED", False)
        ):
            chat_id = int(getattr(event, "chat_id", 0) or 0)
            text = str(getattr(event, "raw_text", None) or "").strip()
            if chat_id > 0 and text:
                # F1P.4B: start-gate — only observe after questionnaire prompt has been sent
                _gate_ok = False
                try:
                    _today = _kyiv_now().date().isoformat()
                    _gate_row = await _tp_qs_fetch_daily_row(DB_PATH, _today, MANAGER_RUNTIME_KEY, chat_id)
                    if _gate_row and int(_gate_row.get("profile_question_sent") or 0) == 1:
                        _gate_ok = True
                except Exception:
                    pass  # fail closed: skip LLM observer if gate check errors
                if _gate_ok:
                    idle_sec = _llmq_cfg_float("LLM_PASSIVE_OBSERVER_IDLE_SEC", 8.0)
                    min_interval = _llmq_cfg_float("LLM_PASSIVE_OBSERVER_MIN_INTERVAL_SEC", 90.0)
                    store_noaction = _llmq_cfg_bool("LLM_PASSIVE_OBSERVER_STORE_NOACTION", False)

                    # Cancel existing debounce task for this chat (burst coalescing)
                    pending = _plobs_debounce_tasks.pop(chat_id, None)
                    if pending and not pending.done():
                        pending.cancel()

                    task = asyncio.create_task(
                        _plobs_fire(chat_id, text, idle_sec, min_interval, store_noaction)
                    )
                    _plobs_debounce_tasks[chat_id] = task
    except Exception:
        pass

    return result

# --- TPILOT LLM F1P PASSIVE OBSERVER Stage F1P 20260624 END ---


# --- TPILOT TRANSFERS STAGE3 START ---
# Confirmation detection: when the same lead writes to the closer account, mark the
# open lead_transfers row confirmed and notify both sides. Never touches daily_leads,
# never touches the main lead quality status, never touches PartnerBot.

async def _transfer_is_closer_runtime(manager_key: str) -> bool:
    """Cheap single-row check so ordinary manager runtimes pay only this one query per
    inbound message and never reach the heavier lead_transfers lookup."""
    mk = registry_normalize_manager_key(manager_key or "")
    if not mk:
        return False
    try:
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute("SELECT role FROM managers WHERE manager_key=?", (mk,))
            row = await cur.fetchone()
            return bool(row) and str(row["role"] or "").strip().lower() == "closer"
    except Exception:
        return False


async def _transfer_resolve_known_contact_id(chat_id: int) -> int:
    """Read-only lookup via contact_identifiers (telegram_chat_id), the same table the
    existing contact-identity system already maintains. Returns 0 if not found -- callers
    still work via the primary lead_chat_id match."""
    cid = int(chat_id or 0)
    if cid <= 0:
        return 0
    try:
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute(
                "SELECT known_contact_id FROM contact_identifiers "
                "WHERE identifier_type='telegram_chat_id' AND identifier_value=?",
                (str(cid),),
            )
            row = await cur.fetchone()
            return int(row["known_contact_id"]) if row and row["known_contact_id"] else 0
    except Exception:
        return 0


async def _transfer_notify_confirmed(db: "aiosqlite.Connection", transfer: Dict[str, Any]) -> None:
    """Enqueue manager_bot_events for both sides of a confirmed transfer. INSERT OR IGNORE
    on a unique event_key makes this idempotent -- a retry never spams duplicate events.
    Every failure is logged to transfer_audit and never raised -- the confirmation itself
    was already committed by the caller before this runs."""
    import json as _tr3_json

    transfer_id = int(transfer.get("id") or 0)
    batch_id = str(transfer.get("batch_id") or "")
    manager_key = registry_normalize_manager_key(transfer.get("manager_key") or "")
    closer_key = registry_normalize_manager_key(transfer.get("closer_key") or "")
    now = _now_utc_iso()

    payload_base = {
        "transfer_id": transfer_id,
        "batch_id": batch_id,
        "manager_key": manager_key,
        "closer_key": closer_key,
        "lead_chat_id": int(transfer.get("lead_chat_id") or 0),
        "known_contact_id": int(transfer.get("known_contact_id") or 0),
        "lead_date": str(transfer.get("lead_date") or ""),
        "raw_text": str(transfer.get("raw_text") or ""),
        "full_name": str(transfer.get("full_name") or ""),
        "username": str(transfer.get("username") or ""),
        "phone": str(transfer.get("phone") or ""),
        "age": str(transfer.get("age") or ""),
        "city": str(transfer.get("city") or ""),
        "car_license": str(transfer.get("car_license") or ""),
        "comment": str(transfer.get("comment") or ""),
        "confirmed_at": str(transfer.get("confirmed_at") or now),
        "confirmed_chat_id": int(transfer.get("confirmed_chat_id") or 0),
    }

    for target, event_manager_key in (("manager", manager_key), ("closer", closer_key)):
        if not event_manager_key:
            continue
        payload = dict(payload_base)
        payload["target"] = target
        event_key = f"transfer_confirmed:{target}:{transfer_id}"
        try:
            cur = await db.execute(
                "INSERT OR IGNORE INTO manager_bot_events"
                "(event_key, event_type, manager_key, chat_id, lead_date, daily_lead_id,"
                " old_status, new_status, payload_json, source, created_at)"
                " VALUES(?,?,?,?,?,0,'','',?,?,?)",
                (
                    event_key, "transfer_confirmed", event_manager_key,
                    int(transfer.get("lead_chat_id") or 0), str(transfer.get("lead_date") or ""),
                    _tr3_json.dumps(payload, ensure_ascii=False), "transfer", now,
                ),
            )
            await db.commit()
            await db.execute(
                "INSERT INTO transfer_audit(transfer_id, action, actor, detail, created_at) VALUES (?,?,?,?,?)",
                (transfer_id, f"notify_enqueued_{target}", "system", f"event_key={event_key} rowcount={cur.rowcount}", now),
            )
            await db.commit()
        except Exception as exc:
            print(f"[transfer-confirm] {target} notify enqueue failed transfer_id={transfer_id} error={exc!r}")
            try:
                await db.execute(
                    "INSERT INTO transfer_audit(transfer_id, action, actor, detail, created_at) VALUES (?,?,?,?,?)",
                    (transfer_id, "notify_fail", "system", f"target={target} error={exc!r}", now),
                )
                await db.commit()
            except Exception:
                pass


async def _transfer_confirm_check(closer_key: str, chat_id: int, known_contact_id: int = 0) -> None:
    """Mark an open lead_transfers row confirmed when this closer runtime receives an
    inbound message from the same lead (matched by lead_chat_id, or known_contact_id as a
    secondary match). Never raises -- defensive so a DB hiccup here never blocks ingestion."""
    ck = registry_normalize_manager_key(closer_key or "")
    cid = int(chat_id or 0)
    kcid = int(known_contact_id or 0)
    if not ck or cid <= 0:
        return
    try:
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            db.row_factory = aiosqlite.Row

            # Step 1: cheap early exit unless this account is actually a closer.
            cur = await db.execute("SELECT role FROM managers WHERE manager_key=?", (ck,))
            role_row = await cur.fetchone()
            if not role_row or str(role_row["role"] or "").strip().lower() != "closer":
                return

            # Step 2: find the oldest still-open transfer for this closer+lead.
            cur = await db.execute(
                """
                SELECT * FROM lead_transfers
                WHERE closer_key=? AND status='created'
                  AND (lead_chat_id=? OR (known_contact_id>0 AND known_contact_id=?))
                ORDER BY id ASC LIMIT 1
                """,
                (ck, cid, kcid),
            )
            transfer_row = await cur.fetchone()
            if not transfer_row:
                return

            transfer_id = int(transfer_row["id"])
            now = _now_utc_iso()

            # Step 3: guarded update -- WHERE status='created' makes this idempotent
            # against duplicate/concurrent inbound messages for the same lead.
            cur = await db.execute(
                """
                UPDATE lead_transfers
                SET status='confirmed', confirmed_at=?, confirmed_chat_id=?, updated_at=?
                WHERE id=? AND status='created'
                """,
                (now, cid, now, transfer_id),
            )
            await db.commit()
            if cur.rowcount != 1:
                return  # already confirmed/cancelled by a concurrent call -- nothing more to do

            try:
                await db.execute(
                    "INSERT INTO transfer_audit(transfer_id, action, actor, detail, created_at) VALUES (?,?,?,?,?)",
                    (transfer_id, "confirmed", "system", f"closer_key={ck} chat_id={cid}", now),
                )
                await db.commit()
            except Exception as exc:
                print(f"[transfer-confirm] audit insert failed transfer_id={transfer_id} error={exc!r}")

            transfer = dict(transfer_row)
            transfer["confirmed_at"] = now
            transfer["confirmed_chat_id"] = cid
            try:
                await _transfer_notify_confirmed(db, transfer)
            except Exception as exc:
                print(f"[transfer-confirm] notify failed transfer_id={transfer_id} error={exc!r}")
    except Exception as exc:
        print(f"[transfer-confirm] check failed closer={ck} chat_id={cid} error={exc!r}")


_TR3_ORIG_RECORD_INCOMING = globals().get("_record_incoming_from_manager")


async def _record_incoming_from_manager(event: events.NewMessage.Event) -> None:  # type: ignore[override]
    """TPILOT TRANSFERS STAGE3: confirmation-detection hook. Calls the original first,
    unconditionally, then -- only for closer runtimes -- checks whether this inbound
    message confirms an open transfer. Cheap for ordinary managers: a single indexed
    SELECT on managers.role and nothing else."""
    result = None
    if callable(_TR3_ORIG_RECORD_INCOMING):
        result = await _TR3_ORIG_RECORD_INCOMING(event)

    try:
        if (
            not CONTROLLER_MODE
            and MANAGER_RUNTIME_KEY
            and getattr(event, "is_private", False)
            and not getattr(event, "out", False)
        ):
            chat_id = int(getattr(event, "chat_id", 0) or 0)
            if chat_id > 0 and await _transfer_is_closer_runtime(MANAGER_RUNTIME_KEY):
                known_contact_id = await _transfer_resolve_known_contact_id(chat_id)
                await _transfer_confirm_check(MANAGER_RUNTIME_KEY, chat_id, known_contact_id)
    except Exception as exc:
        print(f"[transfer-confirm] hook error: {exc!r}")

    return result

# --- TPILOT TRANSFERS STAGE3 END ---


