# Source-first statistics for AdminBot New Menu. Reuses stats_engine.se_window_body (no
# reimplementation of bucket/window math) and storage.source_work_window_get (no schema
# changes, no new tables, no changes to either module). Purely additive: old /stat,
# /stat det, /stat range, /flight and their builders are completely untouched; PartnerBot
# and stats_engine are not modified; schedule_aware stays disabled (False), matching
# project policy. Command is controller-side (reads across per-manager DBs directly, like
# /stat range already does) -- not routed through manager_queue.

try:
    from stats_engine import se_window_body as _nmstat_se_window_body
    _NMSTAT_ENGINE_OK = True
except Exception as _nmstat_engine_err:
    _nmstat_se_window_body = None  # type: ignore[assignment]
    _NMSTAT_ENGINE_OK = False
    print(f"[nmstat] stats_engine import error: {_nmstat_engine_err!r}")

try:
    from storage import source_work_window_get as _nmstat_window_get
    _NMSTAT_STORAGE_OK = True
except Exception as _nmstat_storage_err:
    _nmstat_window_get = None  # type: ignore[assignment]
    _NMSTAT_STORAGE_OK = False
    print(f"[nmstat] storage import error: {_nmstat_storage_err!r}")


def _nmstat_window_text(cfg: Optional[Dict[str, Any]]) -> str:
    if not cfg:
        return "08:00-17:00 (по умолчанию)"
    try:
        ds = int(cfg.get("day_start") or 0)
        de = int(cfg.get("day_end") or 0)
        return f"{ds // 60:02d}:{ds % 60:02d}-{de // 60:02d}:{de % 60:02d}"
    except Exception:
        return "08:00-17:00 (по умолчанию)"


async def _nmstat_source_name(source_key: str) -> str:
    key = str(source_key or "").strip()
    if not key:
        return key
    try:
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            cur = await db.execute(
                "SELECT name FROM traffic_sources WHERE source_key=? LIMIT 1", (key,)
            )
            row = await cur.fetchone()
            if row and row[0]:
                return str(row[0])
    except Exception:
        pass
    return key


async def _nmstat_linked_manager_keys(source_key: str) -> set:
    keys: set = set()
    try:
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            cur = await db.execute(
                "SELECT manager_key FROM manager_source_links WHERE source_key=?",
                (str(source_key or "").strip(),),
            )
            for r in await cur.fetchall():
                mk = registry_normalize_manager_key(r[0])
                if mk:
                    keys.add(mk)
    except Exception:
        pass
    # DELETED MANAGER STATS RETENTION 20260711 (period-filter correction):
    # manager_source_links is hard-deleted with the manager, so a tombstoned
    # manager can never be found via the query above. Union in tombstoned
    # managers whose own stored source_key matches -- actual date/data
    # eligibility is enforced later by _manager_rows_for_reporting_period, this
    # only prevents them being excluded here by the linked-keys intersection.
    try:
        from storage import manager_stats_tombstone_list_active as _tombstones_active
        sk_norm = str(source_key or "").strip().lower()
        for t in (_tombstones_active(retention_days=60, db_path=TPILOT_DB_PATH) or []):
            t_source = str(t.get("source_key") or "").strip().lower()
            if t_source and t_source == sk_norm:
                mk = registry_normalize_manager_key(t.get("manager_key") or "")
                if mk:
                    keys.add(mk)
    except Exception:
        pass
    return keys


async def _handle_nmstat_command(args: str, *, user_id: int = 0) -> str:
    """Parse /nmstat <source_key> <date_from> <date_to> <day|flight> [mk1,mk2,...]."""
    parts = [p for p in str(args or "").strip().split() if p]
    if len(parts) < 4:
        return (
            "Формат: /nmstat <source_key> <дата_с> <дата_по> <day|flight> "
            "[менеджеры через запятую]"
        )
    source_key = parts[0].strip()
    d1_raw, d2_raw, kind_raw = parts[1], parts[2], parts[3].strip().lower()
    mk_csv = parts[4] if len(parts) > 4 else ""
    if kind_raw not in ("day", "flight"):
        return "Тип отчёта должен быть day или flight."

    d1 = _period_parse_date(d1_raw)
    d2 = _period_parse_date(d2_raw)
    if not d1 or not d2:
        return "Не удалось разобрать дату. Формат: дд.мм.гг или гггг-мм-дд."
    start_d, end_d, err = _period_validate_dates(d1, d2)
    if err:
        return err

    if not _NMSTAT_STORAGE_OK or not callable(_nmstat_window_get):
        return "Модуль storage недоступен (source_work_window_get)."
    if not _NMSTAT_ENGINE_OK or not callable(_nmstat_se_window_body):
        return "Модуль stats_engine недоступен."

    cfg = _nmstat_window_get(source_key, TPILOT_DB_PATH)
    pro_include_dolyoty = int(cfg.get("pro_include_dolyoty")) if cfg else 1
    window_cfg = None
    if cfg:
        window_cfg = {
            "day_start_min": int(cfg.get("day_start") or 0),
            "day_end_min": int(cfg.get("day_end") or 0),
        }
    period_mode = "calendar_day" if (kind_raw == "day" and cfg and pro_include_dolyoty == 0) else None

    if kind_raw == "flight" and cfg and pro_include_dolyoty == 0:
        source_name = await _nmstat_source_name(source_key)
        return (
            f"📊 {source_name} | {_period_display(start_d, end_d)} | Долёты\n\n"
            "🌙 Долёты для этого источника отключены. Этот источник считается "
            "календарным днём 00:00-24:00."
        )

    linked_keys = await _nmstat_linked_manager_keys(source_key)
    # DELETED MANAGER STATS RETENTION 20260711 (period-filter correction): use
    # the requested [start_d, end_d] range so a tombstoned manager only
    # surfaces when that range actually intersects their real data (or
    # schedule) up to their own deletion date.
    all_rows = await _manager_rows_for_reporting_period(start_d.isoformat(), end_d.isoformat())
    requested_keys: set = set()
    if mk_csv:
        for tok in mk_csv.split(","):
            mk = registry_normalize_manager_key(tok)
            if mk:
                requested_keys.add(mk)

    warn_line = ""
    if linked_keys:
        target_keys = (linked_keys & requested_keys) if requested_keys else linked_keys
        rows = [
            r for r in all_rows
            if registry_normalize_manager_key(r.get("manager_key") or "") in target_keys
        ]
        mgr_label = (
            f"{len(rows)} выбранных менеджер(ов)" if requested_keys
            else f"{len(rows)} менеджер(ов) источника"
        )
    else:
        target_keys = requested_keys if requested_keys else None
        if target_keys:
            rows = [
                r for r in all_rows
                if registry_normalize_manager_key(r.get("manager_key") or "") in target_keys
            ]
            mgr_label = f"{len(rows)} выбранных менеджер(ов)"
        else:
            rows = all_rows
            mgr_label = f"{len(rows)} менеджер(ов) (все)"
        warn_line = "⚠️ У источника нет привязанных менеджеров, показаны все.\n\n"

    source_name = await _nmstat_source_name(source_key)
    kind_label = "☀️ День" if kind_raw == "day" else "🌙 Долёты"
    window_disp = "00:00-24:00 (календарный день)" if period_mode == "calendar_day" else _nmstat_window_text(cfg)

    if not rows:
        return (
            f"📊 {source_name} | {_period_display(start_d, end_d)} | {kind_label}\n"
            f"Окно: {window_disp}\n\n"
            "Менеджеры для отчёта не найдены."
        )

    header = (
        f"📊 {source_name} | {_period_display(start_d, end_d)} | {kind_label}\n"
        f"Окно: {window_disp} | Менеджеры: {mgr_label}\n\n"
    )
    body = _nmstat_se_window_body(
        rows, start_d, end_d, kind_raw,
        schedule_aware=False,
        window_cfg=window_cfg,
        period_mode=period_mode,
    )
    return warn_line + header + body


_NMSTAT_PREV_PANEL_EXEC = globals().get("_panel_execute_command_text")


async def _panel_execute_command_text(  # type: ignore[override]
    command_text: str, *, requested_by: int = 0
) -> dict:
    """Stage 3A: route /nmstat before chaining to the previous handler."""
    cmd, _, args = str(command_text or "").strip().partition(" ")
    args = args.strip()
    if cmd == "/nmstat":
        try:
            result_text = await _handle_nmstat_command(args, user_id=requested_by)
        except Exception as exc:
            result_text = f"❌ Ошибка /nmstat: {exc!r}"
        return {"ok": True, "result_text": result_text}
    if callable(_NMSTAT_PREV_PANEL_EXEC):
        return await _NMSTAT_PREV_PANEL_EXEC(command_text, requested_by=requested_by)
    return {"ok": False, "result_text": f"Команда не поддерживается: {cmd}"}

# --- TPILOT NMSTAT STAGE3A END ---


# --- TPILOT PROXY BUY STAGE4 (Proxy-Seller automatic SOCKS5 purchase) START ---
# Admin-initiated automatic SOCKS5 purchase for the add-manager proxy step.
# Controller-side only: PanelBot is UI + panel_commands submission, exactly
# like the existing manual /manager_proxy_set flow -- all provider HTTP
# calls, storage writes, and manager-field application happen here, never
# in panel_bot.py.
#
# SPEND SAFETY: allow_spend=True is passed to make_ipv4() in EXACTLY ONE
# place in this entire project -- inside
# _handle_manager_proxy_buy_confirm_command below. That function is only
# ever invoked via the "/manager_proxy_buy_confirm <key>" panel command,
# which PanelBot only ever submits in response to the admin explicitly
# tapping "✅ Подтвердить покупку" after already having seen a no-spend
# calc_ipv4() price preview. There is no automatic/background call path.
#
# RESPONSE-SHAPE CAVEAT: reference_list/order/calc/order/make/proxy/list/
# proxy/download response shapes have not been verified against live
# Proxy-Seller traffic in this project -- proxy_provider.py's
# find_country_id()/extract_*() helpers are defensive/best-effort and
# return None/[] rather than guessing when a shape isn't recognized. This
# must be validated against a real account before being trusted for an
# unattended purchase.

import json as _pbuy_json

PROXY_SELLER_API_KEY = (os.getenv("PROXY_SELLER_API_KEY") or "").strip()

_PBUY_COUNTRY_ALPHA3 = "DEU"
_PBUY_COUNTRY_NAME = "Germany"
_PBUY_PERIOD_ID = "1m"          # preferred period id (also the admin-facing display label)
_PBUY_PERIOD_NAME = "1 month"   # preferred period name -- name-fallback + admin-facing display label
_PBUY_PAYMENT_ID = 1
_PBUY_QUANTITY = 1
_PBUY_PROXY_TYPE = "ipv4"
# Live incident 2026-07-09 (order 4953243): the provider can take longer
# than ~1 minute to provision a freshly-bought proxy. 10x3s=30s was too
# short and made buy-confirm tell the admin to fall back to manual
# /manager_proxy_set even though the money was already spent and the
# order was valid. Buy-confirm now waits at least 5 minutes total.
_PBUY_PROVISION_POLL_ATTEMPTS = 60
_PBUY_PROVISION_POLL_INTERVAL_SEC = 5.0
# Buy-recover (admin-triggered re-check of an already-placed order) uses a
# shorter poll -- it's a quick on-demand check the admin can invoke again
# via the "🔄 Дозабрать proxy" button if the provider still isn't ready.
_PBUY_RECOVER_POLL_ATTEMPTS = 6
_PBUY_RECOVER_POLL_INTERVAL_SEC = 5.0


def _pbuy_provider():
    """Return a ProxySellerProvider (allow_spend is always False at the
    provider/constructor level here -- the confirm handler passes
    allow_spend=True per-call only) or None if no API key is configured.
    Never raises; never makes a network call itself."""
    if not PROXY_SELLER_API_KEY:
        return None
    try:
        from proxy_provider import ProxySellerProvider
        return ProxySellerProvider(PROXY_SELLER_API_KEY, allow_spend=False)
    except Exception:
        return None


async def _pbuy_call(fn, *args, **kwargs):
    """Run a synchronous proxy_provider.py method off the event loop
    thread, per that module's own documented executor-offload contract."""
    loop = asyncio.get_event_loop()
    return await loop.run_in_executor(None, lambda: fn(*args, **kwargs))


def _pbuy_safe_error(exc: Exception) -> str:
    """proxy_provider.py's own exceptions (ProxyProviderError/
    SpendGuardError) are already scrubbed of the API key and submitted
    credentials -- pass those through as-is. Guard against any other
    exception type leaking something unexpected (e.g. a raw stdlib
    exception) by never including its str() in the admin-facing message."""
    try:
        from proxy_provider import ProxyProviderError
        if isinstance(exc, ProxyProviderError):
            return str(exc)
    except Exception:
        pass
    return f"{type(exc).__name__}: непредвиденная ошибка провайдера"


# --- PROXY RENEWAL RELIABILITY R4 (provider error classification) 20260808 START ---
# API-key-scrubbed is NOT the same as human-safe -- _pbuy_safe_error() above
# still passes through the provider's raw errors[] structure verbatim (e.g.
# "provider returned errors[] on prolong/make/ipv4: [{'message': 'IP not
# found', 'code': 0, 'customData': None}]", the exact text seen in
# production). This maps that (or any renewal-tail failure) to one of a
# small, fixed set of RU categories with a canned reason/action -- the
# category's fixed text is the ONLY thing ever shown to an admin; the raw
# message stays in storage/stdout logs only (technical audit trail).
def _prenew_classify_provider_error(*, error_code: str = "", message: str = "", kind: Optional[str] = None, post_spend: bool = False) -> Dict[str, str]:
    """Map a provider/spend-tail failure to one of a small set of RU
    categories. NEVER echoes raw provider structure (errors[]/code/
    customData/dict-repr) into its output -- message/kind are inspected
    ONLY to pick a category; the returned reason/action always come from
    the fixed table below. `kind` is proxy_provider.ProxyProviderError.kind
    (transport/provider_errors/http/response_shape/auth) when available --
    a coarse hint used before falling back to text sniffing on the (already
    API-key-scrubbed) message. `error_code` is the short internal code the
    renewal call sites already produce (not_configured/period_not_found/
    unverified/...) and short-circuits to an unambiguous category when it
    already pins one. Never raises -- anything unrecognized falls back to
    'unknown'.

    `post_spend` (BLOCKER-1 fix, retry-policy correction 20260809; NARROWED
    by the money-safety correction of the same day -- see
    _renewal_wrapped_execute's docstring): the fixed action text for
    network_timeout/rate_limit/provider_unavailable below claims "TPilot
    will retry automatically" -- true when the failure happened BEFORE
    prolong_make was ever called (reference_list/period lookup in
    _prenew_preflight_check: no spend attempted, freely retryable), but
    FALSE when the SAME kind of transport/HTTP failure happens AFTER
    prolong_make was called (_prenew_execute_renewal's own except-block).
    ANY failure classified after prolong_make has been called -- including
    an explicit provider business-rule rejection (PROVIDER_ERRORS/errors[])
    or an auth reject (401/403) -- is spend-AMBIGUOUS and never auto-
    retried: proxy_provider.py's own _request() checks errors[]/envelope-
    status BEFORE the HTTP status code, so the SAME kind/category can be
    produced by an HTTP 5xx/429 response that also carries a JSON errors[]
    body (the provider may already have processed the spend before failing
    to report success cleanly) -- kind alone is not sufficient structural
    proof that no charge occurred. Callers in a post-spend context (only
    _prenew_execute_renewal's prolong_make except-block today) must pass
    post_spend=True so the admin is told the truth instead of a promise
    that can't be kept. Categories with proof-of-no-spend action text
    (ip_not_found/insufficient_balance/provider_auth/invalid_period/
    not_configured) never claimed auto-retry to begin with and are
    unaffected by this flag -- but note their action text is UI-only; it
    does NOT imply the idempotency_key is freed (see
    _renewal_wrapped_execute)."""
    categories = {
        "ip_not_found": {
            "reason": "Провайдер больше не находит этот прокси.",
            "action": "Проверьте прокси и при необходимости замените его.",
        },
        "insufficient_balance": {
            "reason": "Недостаточно средств на балансе Proxy-Seller.",
            "action": "Пополните баланс Proxy-Seller.",
        },
        "provider_auth": {
            "reason": "Proxy-Seller отклонил доступ к API.",
            "action": "Проверьте API-ключ.",
        },
        "rate_limit": {
            "reason": "Proxy-Seller временно ограничил запросы.",
            "action": "Ничего — TPilot повторит попытку автоматически.",
        },
        "network_timeout": {
            "reason": "Proxy-Seller временно недоступен.",
            "action": "Ничего — TPilot повторит попытку автоматически.",
        },
        "invalid_period": {
            "reason": "Период продления недоступен у провайдера.",
            "action": "Проверьте настройки периода продления.",
        },
        "provider_unavailable": {
            "reason": "Proxy-Seller временно недоступен.",
            "action": "Ничего — TPilot повторит попытку автоматически.",
        },
        "not_configured": {
            "reason": "Не настроен API-ключ Proxy-Seller.",
            "action": "Обратитесь к администратору TPilot.",
        },
        "unverified": {
            "reason": "Новый срок прокси не подтверждён.",
            "action": "Синхронизируйте пул и проверьте прокси.",
        },
        "unknown": {
            "reason": "Не удалось определить причину ошибки провайдера.",
            "action": "Откройте карточку прокси и проверьте вручную.",
        },
    }
    text = str(message or "").lower()
    code = str(error_code or "").strip().lower()

    category = "unknown"
    if code == "not_configured":
        category = "not_configured"
    elif code == "unverified":
        category = "unverified"
    elif code == "period_not_found":
        category = "invalid_period"
    elif kind == "auth" or any(t in text for t in ("unauthorized", " 401", " 403", "access denied", "invalid key", "api key rejected")):
        category = "provider_auth"
    elif any(t in text for t in ("ip not found", "proxy not found", "не найден")):
        category = "ip_not_found"
    elif any(t in text for t in ("insufficient", "not enough", "balance too low", "недостаточно", "низкий баланс")):
        category = "insufficient_balance"
    elif any(t in text for t in ("429", "too many requests", "rate limit")):
        category = "rate_limit"
    elif "period" in text:
        category = "invalid_period"
    elif kind == "transport" or any(t in text for t in ("timeout", "timed out", "network error", "connection")):
        category = "network_timeout"
    elif kind == "http" or any(t in text for t in ("http 5", "provider unavailable", "bad gateway", "service unavailable")):
        category = "provider_unavailable"

    tpl = categories.get(category) or categories["unknown"]
    action = tpl["action"]
    if post_spend and category in ("network_timeout", "rate_limit", "provider_unavailable"):
        # BLOCKER-1 fix: this failure happened AFTER prolong_make was
        # called -- spend is ambiguous, never auto-retried. Never promise
        # a retry this project won't perform.
        action = "Повторное списание автоматически не выполняется, пока результат предыдущей попытки не подтверждён."
    return {"category": category, "reason": tpl["reason"], "action": action}
# --- PROXY RENEWAL RELIABILITY R4 (provider error classification) 20260808 END ---


def _pbuy_custom_target_name(manager_key: str) -> str:
    """Build a safe, non-secret customTargetName for order/calc + order/make
    -- Proxy-Seller rejects both endpoints with errors[] "Set
    [customTargetName]" when this field is empty. Contains only a
    sanitized manager_key; never an API key, proxy password, phone
    number, session path, or token."""
    safe = re.sub(r"[^A-Za-z0-9_-]", "_", str(manager_key or "").strip())
    safe = re.sub(r"_+", "_", safe).strip("_-")
    if not safe:
        safe = "manager"
    return f"TPilot_{safe}"[:64]


async def _handle_manager_proxy_buy_calc_command(args: str) -> str:
    """No-spend price preview (reference_list + calc_ipv4 + balance only).
    Returns a JSON string -- panel_commands has no result_json column, so
    structured data travels in result_text (same convention _panel_
    execute_command_text already uses for other JSON-returning commands)."""
    key = registry_normalize_manager_key(str(args or "").strip().split()[0] if str(args or "").strip() else "")
    if not key:
        return _pbuy_json.dumps({"ok": False, "error": "bad_args", "message": "Пустой manager_key"}, ensure_ascii=False)

    row = await _tpag_registry_get(key)
    if not row or str(row.get("status") or "") == "archived":
        return _pbuy_json.dumps({"ok": False, "error": "manager_not_found", "message": f"Менеджер не найден: {key}"}, ensure_ascii=False)

    provider = _pbuy_provider()
    if provider is None:
        return _pbuy_json.dumps({"ok": False, "error": "not_configured", "message": "Proxy-Seller API key не настроен"}, ensure_ascii=False)

    from proxy_provider import find_country_id, find_period_id, extract_price_info

    try:
        ref = await _pbuy_call(provider.reference_list, _PBUY_PROXY_TYPE)
    except Exception as e:
        return _pbuy_json.dumps({"ok": False, "error": "reference_list_failed", "message": _pbuy_safe_error(e)}, ensure_ascii=False)

    country_id = find_country_id(ref, alpha3=_PBUY_COUNTRY_ALPHA3, name=_PBUY_COUNTRY_NAME)
    if country_id is None:
        return _pbuy_json.dumps({
            "ok": False, "error": "country_not_found",
            "message": f"Страна {_PBUY_COUNTRY_NAME} ({_PBUY_COUNTRY_ALPHA3}) не найдена в справочнике провайдера.",
        }, ensure_ascii=False)

    period_id = find_period_id(ref, preferred_id=_PBUY_PERIOD_ID, preferred_name=_PBUY_PERIOD_NAME)
    if period_id is None:
        return _pbuy_json.dumps({
            "ok": False, "error": "period_not_found",
            "message": f"Период {_PBUY_PERIOD_NAME} ({_PBUY_PERIOD_ID}) не найден в справочнике провайдера.",
        }, ensure_ascii=False)

    custom_target_name = _pbuy_custom_target_name(key)
    try:
        calc = await _pbuy_call(
            provider.calc_ipv4,
            country_id, period_id, _PBUY_QUANTITY,
            "", "", custom_target_name, _PBUY_PAYMENT_ID,
        )
    except Exception as e:
        return _pbuy_json.dumps({"ok": False, "error": "calc_failed", "message": _pbuy_safe_error(e)}, ensure_ascii=False)

    try:
        bal = await _pbuy_call(provider.balance)
    except Exception:
        bal = {}

    price_info = extract_price_info(calc)
    return _pbuy_json.dumps({
        "ok": True,
        "manager_key": key,
        "display_name": str(row.get("display_name") or "").strip() or key,
        "country_id": country_id,
        "country_name": _PBUY_COUNTRY_NAME,
        "country_alpha3": _PBUY_COUNTRY_ALPHA3,
        "period_id": _PBUY_PERIOD_ID,
        "quantity": _PBUY_QUANTITY,
        "price": price_info.get("price"),
        "total": price_info.get("total"),
        "currency": price_info.get("currency"),
        "balance": bal.get("summ") if isinstance(bal, dict) else None,
    }, ensure_ascii=False)


async def _pbuy_poll_for_proxy(provider, order_id, *, attempts: int, interval_sec: float) -> Optional[Dict[str, Any]]:
    """Poll list_proxies(order_id) up to `attempts` times, `interval_sec`
    apart, then fall back to the raw download endpoint (parsed through the
    central Stage 1 proxy_parser rather than trusting provider field
    names). Returns a proxy_entry dict (host/port/login/password/
    provider_proxy_id/expires_at) or None if the provider still hasn't
    provisioned anything. Read-only provider calls only -- never spends,
    never calls order/make. Shared by buy-confirm (right after order/make)
    and buy-recover (re-checking an already-placed order)."""
    from proxy_provider import extract_proxy_entries, extract_download_lines

    proxy_entry: Optional[Dict[str, Any]] = None
    for _attempt in range(attempts):
        try:
            lst = await _pbuy_call(provider.list_proxies, _PBUY_PROXY_TYPE, order_id)
        except Exception:
            lst = None
        entries = extract_proxy_entries(lst) if lst is not None else []
        if entries:
            proxy_entry = entries[0]
            break
        if _attempt < attempts - 1:
            await asyncio.sleep(interval_sec)

    if proxy_entry is None:
        try:
            dl = await _pbuy_call(provider.download_proxies, _PBUY_PROXY_TYPE, "socks5", "txt")
        except Exception:
            dl = None
        if dl is not None:
            for line in extract_download_lines(dl):
                parsed_line = proxy_parser.parse_proxy_line(line)
                if parsed_line:
                    proxy_entry = {
                        "host": parsed_line.get("host"),
                        "port": parsed_line.get("port"),
                        "login": parsed_line.get("login"),
                        "password": parsed_line.get("password"),
                        "provider_proxy_id": None,
                        "expires_at": None,
                        "order_id": order_id,
                    }
                    break

    return proxy_entry


async def _pbuy_apply_lease_to_manager(
    lease: Dict[str, Any], manager_key: str, *, source: str, link_lease: bool = True
) -> Dict[str, Any]:
    """Shared tail: link an EXISTING lease (lease["id"] must already exist
    in proxy_leases) to a manager, apply the manager's proxy fields, and
    run the guard. Used by:
    - _pbuy_finalize_lease (Stage 4 buy/recover, right after creating a
      brand-new lease row)
    - /proxy_pool_assign (Stage 6 P3, linking/reassigning an EXISTING pool
      lease)
    Never spends, never calls the provider, never creates/deletes a lease
    row itself -- purely storage writes + one guard check. Returns a plain
    dict (caller does the JSON encoding); never includes the raw
    password.

    PROXY USAGE DETECTION 20260711: link_lease=False is the multi-assign
    path (see _handle_proxy_pool_assign_command's 'multi' token) -- the
    SAME host/port/login/password fields are still applied to this
    manager's own proxy_* columns, but proxy_leases.manager_key /
    managers.proxy_lease_id are left untouched, so the lease keeps its
    original owner as the pool's single tracked owner. The new manager's
    usage is still correctly detected afterwards via their own
    proxy_host/proxy_port/proxy_enabled fields (same mechanism as any
    external proxy). Every existing caller omits this kwarg and gets the
    exact original link-always behavior."""
    from storage import (
        proxy_lease_assign_to_manager as _pbuy_lease_assign,
        proxy_lease_get as _pbuy_lease_get,
        proxy_lease_to_manager_proxy_fields as _pbuy_lease_to_fields,
    )

    lease_id = lease.get("id")
    if link_lease:
        await _pbuy_lease_assign(lease_id, manager_key, db_path=TPILOT_DB_PATH)
    lease2 = await _pbuy_lease_get(lease_id, db_path=TPILOT_DB_PATH)
    fields = _pbuy_lease_to_fields(lease2 or {})
    # Consistent with the existing manual SOCKS5 flow's semantics -- an
    # actively-assigned pool proxy is required, not optional/bypassable.
    fields["proxy_required"] = 1
    await _tpag_registry_set_fields(manager_key, **fields)

    try:
        guard_ok, guard_text = await _tpag_run_guard(manager_key, source=source, force=True)
    except Exception as e:
        guard_ok, guard_text = False, f"Проверка не выполнена: {_pbuy_safe_error(e)}"

    row2 = await _tpag_registry_get(manager_key) or {}
    try:
        info_text = _manager_proxy_info_text(row2)
    except Exception:
        info_text = ""

    return {
        "ok": True,
        "manager_key": manager_key,
        "display_name": str(row2.get("display_name") or "").strip() or manager_key,
        "telegram_username": str(row2.get("telegram_username") or "").strip(),
        "lease_id": lease_id,
        "provider_order_id": (lease2 or {}).get("provider_order_id"),
        "provider_order_number": (lease2 or {}).get("provider_order_number"),
        "provider_proxy_id": (lease2 or {}).get("provider_proxy_id"),
        "expires_at": (lease2 or {}).get("expires_at"),
        "check_ok": bool(guard_ok),
        "info_text": info_text,
        "guard_text": guard_text,
    }


async def _pbuy_finalize_lease(key: str, order_id, order_number, proxy_entry: Dict[str, Any], *, source: str) -> Dict[str, Any]:
    """Shared tail for both buy-confirm and buy-recover once a proxy_entry
    has been found: create the lease row, then delegate the assign
    +apply-fields+guard tail to _pbuy_apply_lease_to_manager (also used by
    Stage 6 P3's /proxy_pool_assign). Never spends -- storage writes + one
    guard check only."""
    host = str(proxy_entry.get("host") or "").strip()
    try:
        port_i = int(str(proxy_entry.get("port")).strip())
    except Exception:
        port_i = None
    login = proxy_entry.get("login")
    password = proxy_entry.get("password")

    if not host or not port_i:
        return {
            "ok": False, "error": "unparseable_proxy",
            "order_id": order_id, "order_number": order_number,
            "message": (
                f"Прокси найден (Order ID: {order_id}), но не удалось распознать "
                "host/port в ответе провайдера. Проверьте вручную у провайдера."
            ),
        }

    from storage import proxy_lease_create as _pbuy_lease_create

    lease_id = await _pbuy_lease_create(
        provider_type="proxy_seller",
        host=host,
        port=port_i,
        manager_key=key,
        provider_order_id=str(order_id) if order_id is not None else None,
        provider_order_number=str(order_number) if order_number is not None else None,
        provider_proxy_id=str(proxy_entry.get("provider_proxy_id")) if proxy_entry.get("provider_proxy_id") is not None else None,
        proxy_type=_PBUY_PROXY_TYPE,
        scheme="socks5",
        login=str(login) if login else None,
        password=str(password) if password else None,
        expires_at=str(proxy_entry.get("expires_at")) if proxy_entry.get("expires_at") else None,
        auto_renew_enabled=False,
        status="active",
        db_path=TPILOT_DB_PATH,
    )

    result = await _pbuy_apply_lease_to_manager({"id": lease_id}, key, source=source)
    if result.get("ok"):
        result["country_name"] = _PBUY_COUNTRY_NAME
    return result


async def _handle_manager_proxy_buy_confirm_command(args: str) -> str:
    """Real purchase. See the module-level SPEND SAFETY note above -- this
    is the ONLY place in the project that ever passes allow_spend=True to
    make_ipv4()."""
    key = registry_normalize_manager_key(str(args or "").strip().split()[0] if str(args or "").strip() else "")
    if not key:
        return _pbuy_json.dumps({"ok": False, "error": "bad_args", "message": "Пустой manager_key"}, ensure_ascii=False)

    row = await _tpag_registry_get(key)
    if not row or str(row.get("status") or "") == "archived":
        return _pbuy_json.dumps({"ok": False, "error": "manager_not_found", "message": f"Менеджер не найден: {key}"}, ensure_ascii=False)

    provider = _pbuy_provider()
    if provider is None:
        return _pbuy_json.dumps({"ok": False, "error": "not_configured", "message": "Proxy-Seller API key не настроен"}, ensure_ascii=False)

    from proxy_provider import find_country_id, find_period_id, extract_order_info

    try:
        ref = await _pbuy_call(provider.reference_list, _PBUY_PROXY_TYPE)
    except Exception as e:
        return _pbuy_json.dumps({"ok": False, "error": "reference_list_failed", "message": _pbuy_safe_error(e)}, ensure_ascii=False)

    country_id = find_country_id(ref, alpha3=_PBUY_COUNTRY_ALPHA3, name=_PBUY_COUNTRY_NAME)
    if country_id is None:
        return _pbuy_json.dumps({
            "ok": False, "error": "country_not_found",
            "message": f"Страна {_PBUY_COUNTRY_NAME} ({_PBUY_COUNTRY_ALPHA3}) не найдена в справочнике провайдера.",
        }, ensure_ascii=False)

    period_id = find_period_id(ref, preferred_id=_PBUY_PERIOD_ID, preferred_name=_PBUY_PERIOD_NAME)
    if period_id is None:
        return _pbuy_json.dumps({
            "ok": False, "error": "period_not_found",
            "message": f"Период {_PBUY_PERIOD_NAME} ({_PBUY_PERIOD_ID}) не найден в справочнике провайдера.",
        }, ensure_ascii=False)

    custom_target_name = _pbuy_custom_target_name(key)
    try:
        make_res = await _pbuy_call(
            provider.make_ipv4,
            country_id, period_id, _PBUY_QUANTITY,
            "", "", custom_target_name, _PBUY_PAYMENT_ID,
            allow_spend=True,
        )
    except Exception as e:
        return _pbuy_json.dumps({"ok": False, "error": "make_failed", "message": _pbuy_safe_error(e)}, ensure_ascii=False)

    order_info = extract_order_info(make_res)
    order_id = order_info.get("order_id")
    order_number = order_info.get("order_number")

    # Money is already spent past this point -- provisioning is read-only
    # (list_proxies / download_proxies), never order/make again.
    proxy_entry = await _pbuy_poll_for_proxy(
        provider, order_id,
        attempts=_PBUY_PROVISION_POLL_ATTEMPTS,
        interval_sec=_PBUY_PROVISION_POLL_INTERVAL_SEC,
    )

    if proxy_entry is None:
        # Live incident 2026-07-09: never point the admin at manual
        # /manager_proxy_set as the primary path here -- the order is
        # valid and paid for, it just isn't provisioned yet. Recovery
        # (read-only, no spend) is the correct next step, exposed via
        # /manager_proxy_buy_recover and the "🔄 Дозабрать proxy" button.
        return _pbuy_json.dumps({
            "ok": False, "error": "provisioning_pending",
            "order_id": order_id, "order_number": order_number,
            "manager_key": key,
            "message": (
                f"Покупка совершена, orderId сохранён ({order_id}), но proxy ещё не выдан "
                "провайдером. Нажмите «🔄 Дозабрать proxy» позже."
            ),
        }, ensure_ascii=False)

    result = await _pbuy_finalize_lease(key, order_id, order_number, proxy_entry, source="panel_buy_confirm")
    return _pbuy_json.dumps(result, ensure_ascii=False)


async def _handle_manager_proxy_buy_recover_command(args: str) -> str:
    """Recover an already-purchased order whose proxy wasn't ready during
    the original buy-confirm's poll window. NEVER calls order/make, NEVER
    passes allow_spend=True -- read-only provider calls only (list_proxies
    / download_proxies), same as buy-confirm's provisioning poll but with
    a shorter, admin-repeatable wait."""
    parts = str(args or "").strip().split()
    key = registry_normalize_manager_key(parts[0]) if parts else ""
    order_id = parts[1].strip() if len(parts) > 1 else ""
    if not key:
        return _pbuy_json.dumps({"ok": False, "error": "bad_args", "message": "Пустой manager_key"}, ensure_ascii=False)
    if not order_id:
        return _pbuy_json.dumps({"ok": False, "error": "bad_args", "message": "Пустой order_id"}, ensure_ascii=False)

    row = await _tpag_registry_get(key)
    if not row or str(row.get("status") or "") == "archived":
        return _pbuy_json.dumps({"ok": False, "error": "manager_not_found", "message": f"Менеджер не найден: {key}"}, ensure_ascii=False)

    provider = _pbuy_provider()
    if provider is None:
        return _pbuy_json.dumps({"ok": False, "error": "not_configured", "message": "Proxy-Seller API key не настроен"}, ensure_ascii=False)

    proxy_entry = await _pbuy_poll_for_proxy(
        provider, order_id,
        attempts=_PBUY_RECOVER_POLL_ATTEMPTS,
        interval_sec=_PBUY_RECOVER_POLL_INTERVAL_SEC,
    )
    if proxy_entry is None:
        return _pbuy_json.dumps({
            "ok": False, "error": "still_pending",
            "order_id": order_id, "manager_key": key,
            "message": "Proxy ещё не готов у провайдера, попробуйте позже.",
        }, ensure_ascii=False)

    result = await _pbuy_finalize_lease(key, order_id, None, proxy_entry, source="panel_buy_recover")
    return _pbuy_json.dumps(result, ensure_ascii=False)


_PBUY_PREV_PANEL_EXEC = globals().get("_panel_execute_command_text")


async def _panel_execute_command_text(  # type: ignore[override]
    command_text: str, *, requested_by: int = 0
) -> dict:
    """Stage 4: route the automatic-SOCKS5-purchase commands before
    chaining to the previous handler."""
    cmd, _, args = str(command_text or "").strip().partition(" ")
    args = args.strip()
    if cmd == "/manager_proxy_buy_calc":
        try:
            result_text = await _handle_manager_proxy_buy_calc_command(args)
        except Exception as exc:
            result_text = _pbuy_json.dumps({"ok": False, "error": "internal_error", "message": _pbuy_safe_error(exc)}, ensure_ascii=False)
        return {"ok": True, "result_text": result_text}
    if cmd == "/manager_proxy_buy_confirm":
        try:
            result_text = await _handle_manager_proxy_buy_confirm_command(args)
        except Exception as exc:
            result_text = _pbuy_json.dumps({"ok": False, "error": "internal_error", "message": _pbuy_safe_error(exc)}, ensure_ascii=False)
        return {"ok": True, "result_text": result_text}
    if cmd == "/manager_proxy_buy_recover":
        try:
            result_text = await _handle_manager_proxy_buy_recover_command(args)
        except Exception as exc:
            result_text = _pbuy_json.dumps({"ok": False, "error": "internal_error", "message": _pbuy_safe_error(exc)}, ensure_ascii=False)
        return {"ok": True, "result_text": result_text}
    if callable(_PBUY_PREV_PANEL_EXEC):
        return await _PBUY_PREV_PANEL_EXEC(command_text, requested_by=requested_by)
    return {"ok": False, "result_text": f"Команда не поддерживается: {cmd}"}

# --- TPILOT PROXY BUY STAGE4 END ---


# --- TPILOT PROXY RENEW STAGE5 (safe expiration warnings + admin-confirmed renewal) START ---
# Controller-side only, mirrors the Stage 4 buy-flow architecture: PanelBot
# is UI + panel_commands submission; every real provider HTTP call and
# storage write happens here. The background warning loop NEVER spends --
# it only reads proxy_leases and (at most) writes a notification + cooldown
# bookkeeping via proxy_lease_update_renew(status_text="notified"/"deferred").
#
# SPEND SAFETY: allow_spend=True is passed to prolong_make() in EXACTLY ONE
# place in this entire project (in addition to Stage 4's make_ipv4() call)
# -- inside _handle_proxy_renew_confirm_command below. That function is only
# ever invoked via "/proxy_renew_confirm <lease_id>", which PanelBot only
# submits after the admin explicitly taps "✅ Подтвердить продление" having
# already seen a no-spend prolong_calc() price preview. No automatic/
# background renewal call path exists. _pbuy_provider()/_pbuy_call()/
# _pbuy_safe_error() (Stage 4) are reused as-is -- they are already fully
# generic, not buy-specific.

_PRENEW_PROXY_TYPE = "ipv4"
_PRENEW_PAYMENT_ID = 1
_PRENEW_BEFORE_DAYS = 3  # kept as a defensive outer bound; precise day math is Kyiv-local below
_PRENEW_LOOP_TICK_SEC = 600  # 10 minutes -- well under the +/-30min slot window so no slot is ever skipped

# --- Stage 6.1E: Kyiv-local, slot-based, per-lease/date/slot deduped
# scheduling. Replaces the old 3-day-horizon + 6h-cooldown + 30min-loop
# design (which spammed several messages/lease/day with no time-of-day
# awareness). Warnings and auto-renew attempts are two INDEPENDENT slot
# namespaces in the SAME proxy_renew_notify_log table -- a lease can be
# warned about AND auto-renewed in the same physical time window without
# either one blocking the other.
# R5 (Proxy Renewal Reliability, 20260808): reminders are now T-1 and T=0
# ONLY -- one per lease per day, not three (today_day/today_evening
# dropped). Retrying a REMINDER three times a day was pure noise (the
# lease's expiry hadn't changed since the morning); the auto-renew engine
# keeps its own separate retry cadence below (_PRENEW_AUTORENEW_SLOTS,
# unchanged) since retrying an actual renewal ATTEMPT after a transient
# provider failure is legitimate and unrelated to how often we remind a
# human about it.
_PRENEW_WARN_SLOTS = {
    "tomorrow_noon": (12, 0),
    "today_morning": (9, 0),
}
_PRENEW_AUTORENEW_SLOTS = {
    "autorenew_pre": (12, 0),
    "autorenew_today_morning": (9, 0),
    "autorenew_today_day": (13, 0),
    "autorenew_today_evening": (17, 0),
}
_PRENEW_SLOT_WINDOW_MIN = 30


def _prenew_slot_for_now(now_local: datetime, windows: Dict[str, Tuple[int, int]]) -> Optional[str]:
    """Return the slot name whose target (hour, minute) is within
    _PRENEW_SLOT_WINDOW_MIN of `now_local`, or None. `now_local` must
    already be a naive Kyiv-local datetime (tzinfo stripped)."""
    for slot, (h, m) in windows.items():
        target = now_local.replace(hour=h, minute=m, second=0, microsecond=0)
        delta_min = abs((now_local - target).total_seconds()) / 60.0
        if delta_min <= _PRENEW_SLOT_WINDOW_MIN:
            return slot
    return None


async def _prenew_display_name(manager_key: str) -> str:
    manager_key = str(manager_key or "").strip()
    if not manager_key:
        return ""
    try:
        row = await _tpag_registry_get(manager_key)
        if row:
            return str(row.get("display_name") or "").strip() or manager_key
    except Exception:
        pass
    return manager_key


# --- PROXY RENEWAL RELIABILITY R5 (identity + expiry display) 20260808 START ---
async def _prenew_manager_identity_line(manager_key: str) -> str:
    """'{display_name} | @{username}' / '{display_name} | без username',
    deliberately matching panel_bot.py's _pxm_manager_identity wording
    (panel_bot.py:428) -- an admin should see the SAME identity phrasing on
    a push notification as on the pool/method-menu screens. main.py cannot
    import panel_bot.py (separate process concerns), so this is kept in
    sync by convention, not by shared code. Returns 'не назначен' for an
    empty manager_key (unassigned/orphan lease) -- panel_bot.py's helper has
    no equivalent case since it is always called with a real manager row."""
    manager_key = str(manager_key or "").strip()
    if not manager_key:
        return "не назначен"
    try:
        row = await _tpag_registry_get(manager_key)
    except Exception:
        row = None
    if not row:
        return manager_key
    name = str(row.get("display_name") or manager_key).strip() or manager_key
    user = str(row.get("telegram_username") or "").strip()
    return f"{name} | @{user}" if user else f"{name} | без username"


def _prenew_format_expires_display(raw: Any) -> str:
    """DD.MM.YYYY for any expires_at shape this subsystem has seen
    (YYYY-MM-DD / YYYY-MM-DDTHH:MM:SS / DD.MM.YYYY / ISO with offset) --
    falls back to the raw stored string if unparseable (never guesses,
    never blanks it out)."""
    dt = _ppool_parse_expires_at(raw)
    if dt is not None:
        return dt.strftime("%d.%m.%Y")
    return str(raw or "_")
# --- PROXY RENEWAL RELIABILITY R5 (identity + expiry display) 20260808 END ---


async def _prenew_collect_active_seller_leases() -> List[Dict[str, Any]]:
    """All active proxy_seller leases, read fresh each tick. Bypasses
    proxy_lease_list_expiring()'s string-comparison horizon (unreliable
    for DD.MM.YYYY expires_at) -- precise day-math happens in Python via
    _ppool_parse_expires_at on the caller side."""
    from storage import proxy_lease_list_all as _prenew_list_all
    leases = await _prenew_list_all(db_path=TPILOT_DB_PATH)
    return [
        l for l in leases
        if str(l.get("status") or "").strip().lower() == "active"
        and str(l.get("provider_type") or "") == "proxy_seller"
    ]


# --- PROXY RENEWAL RELIABILITY R1 (lease role classifier, OBSERVE MODE) 20260808 START ---
# Single authoritative classification of a proxy_leases row into
# 'managed' | 'orphan' | 'free'. Built ONLY from data that already exists
# (proxy_leases.manager_key/status/provider_type, managers.status/
# proxy_enabled/proxy_lease_id/proxy_host/proxy_port, and the same
# host:port usage map _ppool_derive_status already uses for 'occupied').
# No new table, no new column, no second classifier anywhere else in the
# project -- this is the ONE place lease role is decided.
#
# CORRECTION B 20260810: flipped from observe-mode to ENFORCED, per the
# rollout this flag was staged for -- the warn loop (_prenew_notify_expiring_
# loop) and engine-1 autorenew loop (_prenew_autorenew_loop) now actually
# skip a non-'managed' lease instead of only logging it. No other change was
# needed at either of those two call sites for this flip alone -- see
# _prenew_lease_is_orphan below for the additional gates this correction adds
# at the other renewal entry points (_renewal_wrapped_execute, engine 2).
_PRENEW_ROLE_ENFORCEMENT_ENABLED = True


def _prenew_lease_role(
    lease: Dict[str, Any],
    manager_row: Optional[Dict[str, Any]],
    usage_map: Optional[Dict[Tuple[str, int], List[Dict[str, Any]]]] = None,
) -> str:
    """Pure (no I/O), never raises. Returns 'managed' | 'orphan' | 'free'.

    managed: lease.manager_key points at a live (status != 'archived'),
      proxy-enabled (proxy_enabled==1) manager, AND this lease is that
      manager's CURRENT proxy -- either by managers.proxy_lease_id, or (for
      rows predating that column / manual entry) by host:port matching the
      manager's own proxy_host:proxy_port. A manager_key-less lease whose
      host:port is nonetheless found in the live usage map (proxy applied
      outside the pool) also counts as managed -- never silently let an
      in-use proxy look 'free' and expire unnoticed.
    orphan: manager_key set but the manager is missing/archived/proxy_
      disabled, OR the lease is a replaced/old lease of a still-live
      manager (usage/proxy_lease_id now point elsewhere).
    free: no manager_key and the host:port is not in use anywhere.
    """
    try:
        manager_key = str(lease.get("manager_key") or "").strip()
        usage_key = _ppool_usage_key(lease.get("host"), lease.get("port"))
        used_by_someone = bool(usage_map and usage_key and usage_map.get(usage_key))

        if manager_key:
            if manager_row is None:
                return "orphan"
            if str(manager_row.get("status") or "").strip().lower() == "archived":
                return "orphan"
            if int(manager_row.get("proxy_enabled") or 0) != 1:
                return "orphan"

            is_current = False
            lease_id = lease.get("id")
            mgr_lease_id = manager_row.get("proxy_lease_id")
            if lease_id is not None and mgr_lease_id is not None:
                try:
                    is_current = int(lease_id) == int(mgr_lease_id)
                except Exception:
                    is_current = False
            if not is_current:
                mgr_usage_key = _ppool_usage_key(manager_row.get("proxy_host"), manager_row.get("proxy_port"))
                is_current = bool(usage_key is not None and mgr_usage_key is not None and usage_key == mgr_usage_key)

            return "managed" if is_current else "orphan"

        return "managed" if used_by_someone else "free"
    except Exception:
        # Never crash a caller over an unclassifiable row -- 'orphan' is the
        # safe default (skip this tick), same convention as
        # _prenew_warn_eligible/_prenew_autorenew_gates_ok returning False.
        return "orphan"


async def _prenew_role_diagnostic(lease: Dict[str, Any], usage_map: Optional[Dict[Tuple[str, int], List[Dict[str, Any]]]], *, context: str) -> str:
    """OBSERVE-mode diagnostic: compute the lease's role and log ONE line
    only when it diverges from the legacy (role-blind) eligibility that let
    the caller reach this point -- i.e. only when an enforced gate WOULD
    have skipped this lease. Never raises, never blocks. Returns the role so
    callers can also use it once _PRENEW_ROLE_ENFORCEMENT_ENABLED is True."""
    try:
        manager_key = str(lease.get("manager_key") or "").strip()
        manager_row = await _tpag_registry_get(manager_key) if manager_key else None
        role = _prenew_lease_role(lease, manager_row, usage_map)
        if role != "managed":
            try:
                print(
                    f"[prenew-role-observe] context={context} lease_id={lease.get('id')} "
                    f"role={role} manager_key={manager_key or '_'} "
                    f"host={lease.get('host') or '_'}:{lease.get('port') or '_'} "
                    f"enforcement={_PRENEW_ROLE_ENFORCEMENT_ENABLED}"
                )
            except Exception:
                pass
        return role
    except Exception:
        return "orphan"
# --- PROXY RENEWAL RELIABILITY R1 (lease role classifier, OBSERVE MODE) 20260808 END ---


# --- CORRECTION B 20260810 (orphan proxy lease suppression) START ---
async def _prenew_lease_is_orphan(
    lease: Dict[str, Any],
    usage_map: Optional[Dict[Tuple[str, int], List[Dict[str, Any]]]] = None,
    *, context: str = "gate",
) -> bool:
    """Single reused orphan gate for the renewal entry points that don't
    already have one (_renewal_wrapped_execute -- the shared spend choke
    point for BOTH renewal engines plus both manual confirm paths -- and
    engine 2's _renewal_auto_tick loop). Read-only, deterministic, no
    Telegram/network, no DB writes -- delegates entirely to the SAME pure
    classifier (_prenew_lease_role, R1 20260808) engine 1 and the warn loop
    already use via _prenew_role_diagnostic; this is NOT a second orphan
    definition, only a second thin async wrapper around the one pure
    function, for callers that don't have a per-tick usage_map handy
    (usage_map defaults to None -- _prenew_lease_role's own documented
    fallback: a manager_key match is still decided correctly via
    proxy_lease_id/host:port against the manager row; only the extra
    'used outside pool' signal for a manager_key-less lease is skipped).

    Both 'orphan' (assigned but broken -- manager missing/archived/disabled/
    assignment mismatch) and 'free' (never assigned) roles return True here
    -- neither has a real manager who should ever be billed for this lease,
    regardless of which of the two applies. A manager that merely exists but
    is disabled/manual_stopped is NOT orphan by itself (_prenew_lease_role's
    own 'orphan' condition is status=='archived' or proxy_enabled!=1 --
    disabled/manual_stopped is neither).

    Fails CLOSED: any lookup error is treated as orphan (never spend/notify
    on a lease this gate could not confidently classify)."""
    try:
        lease_id = lease.get("id")
        manager_key = str(lease.get("manager_key") or "").strip()
        manager_row = await _tpag_registry_get(manager_key) if manager_key else None
        role = _prenew_lease_role(lease, manager_row, usage_map)
        is_orphan = role != "managed"
        if is_orphan:
            reason = "manager_not_found" if (manager_key and manager_row is None) else (
                "assignment_mismatch" if (manager_key and manager_row is not None) else (
                    "placeholder_key" if manager_key == "_" else "missing_manager_key"
                )
            )
            try:
                print(
                    f"[proxy-orphan] context={context} lease_id={lease_id} "
                    f"proxy={lease.get('host') or '_'}:{lease.get('port') or '_'} "
                    f"provider_proxy_id={lease.get('provider_proxy_id') or '_'} "
                    f"raw_manager_key={manager_key or '_'} role={role} reason={reason}"
                )
            except Exception:
                pass
        return is_orphan
    except Exception:
        return True
# --- CORRECTION B 20260810 (orphan proxy lease suppression) END ---


# --- PROXY RENEWAL RELIABILITY R5 (notification policy) 20260808 START ---
# Core principle: NO ACTION REQUIRED = NO ALERT. A lease with auto-renew
# configured, a provider identity, and no recent failed/unverified attempt
# will be (or already was) handled by TPilot on its own -- no reminder is
# sent for it at all. A reminder only fires when the admin genuinely needs
# to do something about it, and it says what.
def _prenew_warn_action_needed(lease: Dict[str, Any]) -> Optional[Dict[str, str]]:
    """Decide whether a warn-eligible (T-1 or T=0) lease actually needs a
    reminder. Returns None (silent) when auto-renew is configured, has a
    provider identity, and hasn't just failed/gone unverified -- TPilot
    will (or already did) handle it. Otherwise returns {'reason','action'}
    for the reminder body. Pure, no I/O, never raises."""
    recent_failure_window_sec = 36 * 3600  # covers the T-1 -> T=0 gap plus a buffer
    try:
        if not str(lease.get("provider_proxy_id") or "").strip():
            return {
                "reason": "У прокси нет идентификатора провайдера — автопродление невозможно.",
                "action": "Обратитесь к провайдеру вручную или замените прокси.",
            }
        if int(lease.get("auto_renew_enabled") or 0) != 1:
            return {
                "reason": "Автопродление для этого прокси выключено.",
                "action": "Включите автопродление или продлите вручную.",
            }
        last_status = str(lease.get("last_renew_status") or "")
        last_attempt = lease.get("last_renew_attempt_at")
        recently_failed = last_status.startswith("renew_failed") or last_status == "renew_unverified"
        if recently_failed and last_attempt:
            try:
                elapsed = (_tp_utc_now() - datetime.fromisoformat(str(last_attempt))).total_seconds()
            except Exception:
                elapsed = None
            if elapsed is None or elapsed <= recent_failure_window_sec:
                return {
                    "reason": "Последняя попытка автопродления не удалась.",
                    "action": "Проверьте прокси и продлите вручную.",
                }
        return None
    except Exception:
        return {
            "reason": "Не удалось определить состояние автопродления.",
            "action": "Откройте карточку прокси и проверьте вручную.",
        }


async def _prenew_send_lease_warning(lease: Dict[str, Any], need: Dict[str, str], *, is_today: bool) -> None:
    """Per-lease T-1/T=0 reminder -- replaces the old grouped multi-lease
    format entirely (R5). Only ever called for a lease that IS warn-eligible
    AND needs action (_prenew_warn_action_needed returned non-None); a
    normally-auto-renewing lease never reaches this function. `lease_id` is
    kept as the LAST technical line (blank-line separated from the human
    text) purely for panel_bot.py's existing lease_id: regex button parser
    -- never mixed into the human-readable body."""
    lease_id = lease.get("id")
    # CORRECTION B 20260810: defensive barrier, same rationale as the
    # identical check in _prenew_autorenew_one/_renewal_auto_tick_report_
    # outcome -- the caller (_prenew_notify_expiring_loop) already gates on
    # role before calling this function, but re-checking here means a
    # future direct caller can never reintroduce an orphan T-1/T=0 alert by
    # forgetting that gate.
    if await _prenew_lease_is_orphan(lease, context="warn_send"):
        return
    identity = await _prenew_manager_identity_line(str(lease.get("manager_key") or ""))
    title = "⚠️ Прокси заканчивается сегодня" if is_today else "⚠️ Прокси заканчивается завтра"
    lines = [
        title,
        "",
        f"Менеджер: {identity}",
        f"Ключ: {lease.get('manager_key') or '_'}",
        f"Прокси: {lease.get('host') or '_'}:{lease.get('port') or '_'}",
        f"Действует до: {_prenew_format_expires_display(lease.get('expires_at'))}",
        "",
        f"Причина: {need.get('reason') or 'Причина не определена.'}",
        f"Что делать: {need.get('action') or 'Проверьте прокси.'}",
        "",
        f"lease_id: {lease_id}",
    ]
    body = "\n".join(lines)
    try:
        await _create_panel_notification("proxy_renew_warning", title, body)
    except Exception as exc:
        print(f"[prenew] lease warning send error: {exc!r}")
# --- PROXY RENEWAL RELIABILITY R5 (notification policy) 20260808 END ---


def _prenew_warn_eligible(lease: Dict[str, Any], slot: str, now_local: datetime) -> bool:
    """Pure (no I/O), independently-testable warning-eligibility check
    for ONE lease at the CURRENT slot -- mirrors _prenew_autorenew_gates_
    ok's structure. Caller has already filtered to status=='active' and
    provider_type=='proxy_seller'. Does NOT check per-slot dedupe (that's
    proxy_renew_notify_mark_once, checked separately). Never raises."""
    try:
        expires_dt = _ppool_parse_expires_at(lease.get("expires_at"))
        if expires_dt is None:
            return False
        day_delta = (expires_dt.date() - now_local.date()).days
        if slot == "tomorrow_noon":
            return day_delta == 1
        if slot == "today_morning":
            return day_delta == 0
        return False
    except Exception:
        return False


_PRENEW_NOTIFY_LOG_RETENTION_DAYS = 90
_prenew_last_purge_date: Optional[str] = None  # in-memory, once/day best-effort -- harmless if it re-fires after a restart


async def _prenew_notify_expiring_loop() -> None:
    """Kyiv-local, slot-based, per-lease/date/slot deduped expiry
    reminders. Tomorrow-expiry -> at most one reminder at tomorrow_noon;
    today-expiry -> at most one reminder at today_morning (R5, 20260808:
    down from up to 4/day -- see _PRENEW_WARN_SLOTS). Never spends, never
    calls the provider, never writes last_renew_attempt_at -- that column
    is reserved for actual renewal attempts, not mere notifications
    (dedupe lives entirely in proxy_renew_notify_log).

    R5 (20260808): a lease that's warn-eligible AND already claimed its
    per-slot dedupe key is THEN checked against _prenew_warn_action_needed
    -- 'no action needed' leases (auto-renew configured & healthy) are
    silently skipped, no Telegram card at all. Grouped multi-lease
    messages are gone -- every reminder is per-lease now (also fixes the
    old grouped card never carrying a lease_id: marker, so it had no
    action buttons)."""
    global _prenew_last_purge_date
    while True:
        try:
            now_local = _kyiv_now().replace(tzinfo=None)
            today_str = now_local.strftime("%Y-%m-%d")
            slot = _prenew_slot_for_now(now_local, _PRENEW_WARN_SLOTS)
            if slot:
                from storage import proxy_renew_notify_mark_once as _prenew_mark_once
                leases = await _prenew_collect_active_seller_leases()
                usage_map = await _ppool_manager_usage_map()  # R1: observe-mode role diagnostic only
                for lease in leases:
                    try:
                        if not _prenew_warn_eligible(lease, slot, now_local):
                            continue
                        # R1 (observe mode): compute+log role, never gate on it unless enforcement is on.
                        role = await _prenew_role_diagnostic(lease, usage_map, context="warn")
                        if _PRENEW_ROLE_ENFORCEMENT_ENABLED and role != "managed":
                            continue
                        lease_id = int(lease.get("id") or 0)
                        if not lease_id:
                            continue
                        should_consider = await _prenew_mark_once(lease_id, today_str, slot, db_path=TPILOT_DB_PATH)
                        if not should_consider:
                            continue
                        need = _prenew_warn_action_needed(lease)
                        if need is None:
                            continue  # R5: auto-renew configured & healthy -- silence
                        await _prenew_send_lease_warning(lease, need, is_today=(slot == "today_morning"))
                    except Exception as exc:
                        print(f"[prenew] per-lease slot-eval error: {exc!r}")
            # R5d: housekeeping -- purge notify-log rows older than the
            # retention window, at most once per Kyiv-day. Best-effort;
            # never blocks/breaks the warn tick itself.
            if _prenew_last_purge_date != today_str:
                try:
                    from storage import proxy_renew_notify_purge_old as _prenew_purge_old
                    cutoff = (now_local - timedelta(days=_PRENEW_NOTIFY_LOG_RETENTION_DAYS)).strftime("%Y-%m-%d")
                    await _prenew_purge_old(cutoff, db_path=TPILOT_DB_PATH)
                    _prenew_last_purge_date = today_str
                except Exception as exc:
                    print(f"[prenew] notify-log purge error: {exc!r}")
        except asyncio.CancelledError:
            return
        except Exception as exc:
            print(f"[prenew] notify loop error: {exc!r}")
        await asyncio.sleep(_PRENEW_LOOP_TICK_SEC)


async def _handle_proxy_renew_calc_command(args: str) -> str:
    """No-spend renewal price preview (reference_list + prolong_calc +
    balance only). Returns a JSON string (panel_commands has no
    result_json column, same convention as Stage 4).

    BL-2 fix (Proxy Renewal Reliability review, 20260808): every failure
    branch now also carries error_category/reason/action (same shape as
    _prenew_preflight_check/_prenew_execute_renewal) so panel_bot.py's
    calc-preview screen never has to fall back to showing this dict's raw
    `message` (which for the two provider-facing branches below is only a
    best-effort _pbuy_safe_error scrub, not a guaranteed-safe user text)."""
    try:
        lease_id = int(str(args or "").strip().split()[0])
    except Exception:
        return _pbuy_json.dumps({
            "ok": False, "error": "bad_args", "message": "Пустой или некорректный lease_id",
            "reason": "Некорректный запрос.", "action": "Повторите действие из карточки прокси.",
        }, ensure_ascii=False)

    from storage import proxy_lease_get as _prenew_lease_get

    lease = await _prenew_lease_get(lease_id, db_path=TPILOT_DB_PATH)
    if not lease or str(lease.get("status") or "") != "active":
        return _pbuy_json.dumps({
            "ok": False, "error": "lease_not_found", "message": f"Активный lease не найден: {lease_id}",
            "reason": "Активная аренда прокси не найдена.", "action": "Обновите список прокси и повторите попытку.",
        }, ensure_ascii=False)

    provider_proxy_id = lease.get("provider_proxy_id")
    if not provider_proxy_id:
        return _pbuy_json.dumps({
            "ok": False, "error": "missing_provider_proxy_id",
            "message": "У этого прокси нет provider_proxy_id — автоматическое продление невозможно. Обратитесь к провайдеру вручную.",
            "reason": "У прокси нет привязки к провайдеру.", "action": "Обратитесь к провайдеру вручную.",
        }, ensure_ascii=False)

    provider = _pbuy_provider()
    if provider is None:
        cat = _prenew_classify_provider_error(error_code="not_configured")
        return _pbuy_json.dumps({
            "ok": False, "error": "not_configured", "message": "Proxy-Seller API key не настроен",
            "error_category": cat["category"], "reason": cat["reason"], "action": cat["action"],
        }, ensure_ascii=False)

    from proxy_provider import find_period_id, extract_renewal_info

    try:
        ref = await _pbuy_call(provider.reference_list, _PRENEW_PROXY_TYPE)
    except Exception as e:
        err_text = _pbuy_safe_error(e)
        cat = _prenew_classify_provider_error(message=err_text, kind=getattr(e, "kind", None))
        return _pbuy_json.dumps({
            "ok": False, "error": "reference_list_failed", "message": err_text,
            "error_category": cat["category"], "reason": cat["reason"], "action": cat["action"],
        }, ensure_ascii=False)

    period_id = find_period_id(ref, preferred_id=_PBUY_PERIOD_ID, preferred_name=_PBUY_PERIOD_NAME)
    if period_id is None:
        cat = _prenew_classify_provider_error(error_code="period_not_found")
        return _pbuy_json.dumps({
            "ok": False, "error": "period_not_found",
            "message": f"Период {_PBUY_PERIOD_NAME} ({_PBUY_PERIOD_ID}) не найден в справочнике провайдера.",
            "error_category": cat["category"], "reason": cat["reason"], "action": cat["action"],
        }, ensure_ascii=False)

    try:
        calc = await _pbuy_call(provider.prolong_calc, _PRENEW_PROXY_TYPE, [provider_proxy_id], period_id, _PRENEW_PAYMENT_ID)
    except Exception as e:
        err_text = _pbuy_safe_error(e)
        cat = _prenew_classify_provider_error(message=err_text, kind=getattr(e, "kind", None))
        return _pbuy_json.dumps({
            "ok": False, "error": "calc_failed", "message": err_text,
            "error_category": cat["category"], "reason": cat["reason"], "action": cat["action"],
        }, ensure_ascii=False)

    try:
        bal = await _pbuy_call(provider.balance)
    except Exception:
        bal = {}

    display_name = await _prenew_display_name(str(lease.get("manager_key") or ""))
    info = extract_renewal_info(calc)
    return _pbuy_json.dumps({
        "ok": True,
        "lease_id": lease_id,
        "manager_key": lease.get("manager_key"),
        "display_name": display_name,
        "host": lease.get("host"),
        "port": lease.get("port"),
        "expires_at": lease.get("expires_at"),
        "period_id": _PBUY_PERIOD_ID,
        "price": info.get("price"),
        "total": info.get("total"),
        "currency": info.get("currency"),
        "balance": bal.get("summ") if isinstance(bal, dict) else None,
    }, ensure_ascii=False)


# --- PROXY RENEWAL RELIABILITY R2 (verify-after-renew) 20260808 START ---
# A prolong/make response that doesn't raise is NOT proof the expiry
# actually moved -- Proxy-Seller's own response has been observed WITHOUT a
# date_end field. This block adds a READ-ONLY post-spend confirmation step:
# if the make response itself doesn't carry a usable newer date, re-read
# the provider's own list (list_proxies, already used elsewhere for sync)
# and only accept the renewal as confirmed if the provider's OWN state now
# shows a later expiry than before the spend. Bounded (a fixed number of
# read-only attempts with backoff) -- never an unbounded retry, and NEVER a
# second prolong/make for the same attempt.
_PRENEW_VERIFY_MAX_REFRESH_ATTEMPTS = 2
_PRENEW_VERIFY_REFRESH_BACKOFF_SEC = 60.0


def _prenew_find_provider_entry(
    entries: List[Dict[str, Any]], provider_proxy_id: Any, *, host: Any = None, port: Any = None,
) -> Optional[Dict[str, Any]]:
    """Match a proxy/list entry to our lease: by provider_proxy_id first
    (string compare -- ids may arrive as int or str depending on the
    endpoint), falling back to host:port if the id doesn't match anything
    (the provider may rotate the internal id on renewal while keeping the
    same host:port). Never raises."""
    try:
        pid = str(provider_proxy_id or "").strip()
        if pid:
            for e in entries or []:
                if str(e.get("provider_proxy_id") or "").strip() == pid:
                    return e
        if host and port:
            h = str(host).strip().lower()
            p = str(port).strip()
            for e in entries or []:
                if str(e.get("host") or "").strip().lower() == h and str(e.get("port") or "").strip() == p:
                    return e
    except Exception:
        pass
    return None


async def _prenew_verify_renewal_via_refresh(
    provider: Any, provider_proxy_id: Any, before_dt: Optional[datetime], *,
    host: Any = None, port: Any = None,
    max_attempts: int = _PRENEW_VERIFY_MAX_REFRESH_ATTEMPTS,
    backoff_sec: float = _PRENEW_VERIFY_REFRESH_BACKOFF_SEC,
) -> Dict[str, Any]:
    """READ-ONLY provider refresh used ONLY to confirm a renewal whose make
    response didn't carry a usable newer date_end. list_proxies is a
    read-only endpoint (same one _plc_reconcile_loop/proxy_pool_sync already
    call) -- this NEVER spends. Bounded: at most max_attempts reads, with
    backoff_sec between attempts -- never an unbounded retry. Returns
    {"confirmed": bool, "new_expires_at": str|None, "entry": dict|None}."""
    from proxy_provider import extract_proxy_entries as _verify_extract
    last_entry: Optional[Dict[str, Any]] = None
    for attempt in range(max(1, int(max_attempts))):
        if attempt > 0:
            try:
                await asyncio.sleep(backoff_sec)
            except asyncio.CancelledError:
                raise
            except Exception:
                pass
        try:
            lst = await _pbuy_call(provider.list_proxies, _PRENEW_PROXY_TYPE)
            entries = _verify_extract(lst)
        except Exception:
            continue
        entry = _prenew_find_provider_entry(entries, provider_proxy_id, host=host, port=port)
        if entry is None:
            continue
        last_entry = entry
        new_dt = _ppool_parse_expires_at(entry.get("expires_at"))
        if new_dt is not None and (before_dt is None or new_dt > before_dt):
            return {"confirmed": True, "new_expires_at": entry.get("expires_at"), "entry": entry}
    return {"confirmed": False, "new_expires_at": (last_entry or {}).get("expires_at"), "entry": last_entry}
# --- PROXY RENEWAL RELIABILITY R2 (verify-after-renew) 20260808 END ---


async def _prenew_preflight_check(lease: Dict[str, Any]) -> Dict[str, Any]:
    """PRE-SPEND stage (BL-1 fix, Proxy Renewal Reliability review
    20260808): safe READ/PRECHECK steps only -- provider configuration,
    reference_list, period lookup. Never calls prolong_make, never touches
    proxy_renewal_ops/idempotency_key. Safe to call and retry an unlimited
    number of times (a scheduler tick, a manual retry, a restart) without
    ever risking a spend. On success returns the provider handle + resolved
    period_id + parsed pre-renewal expiry for the caller to hand straight
    to the SPEND-PROTECTED stage (_prenew_execute_renewal) so the same
    reference_list/period lookup isn't repeated. On failure returns the
    SAME structured error shape _prenew_execute_renewal has always
    returned for these three cases (not_configured/reference_list_failed/
    period_not_found) -- callers must treat ok=False here as freely
    retryable (no idempotency key was ever created for it)."""
    provider = _pbuy_provider()
    if provider is None:
        cat = _prenew_classify_provider_error(error_code="not_configured")
        return {
            "ok": False, "error": "not_configured", "message": "Proxy-Seller API key не настроен",
            "error_category": cat["category"], "reason": cat["reason"], "action": cat["action"],
        }

    from proxy_provider import find_period_id

    try:
        ref = await _pbuy_call(provider.reference_list, _PRENEW_PROXY_TYPE)
    except Exception as e:
        err_text = _pbuy_safe_error(e)
        cat = _prenew_classify_provider_error(message=err_text, kind=getattr(e, "kind", None))
        return {
            "ok": False, "error": "reference_list_failed", "message": err_text,
            "error_category": cat["category"], "reason": cat["reason"], "action": cat["action"],
        }

    period_id = find_period_id(ref, preferred_id=_PBUY_PERIOD_ID, preferred_name=_PBUY_PERIOD_NAME)
    if period_id is None:
        cat = _prenew_classify_provider_error(error_code="period_not_found")
        return {
            "ok": False, "error": "period_not_found",
            "message": f"Период {_PBUY_PERIOD_NAME} ({_PBUY_PERIOD_ID}) не найден в справочнике провайдера.",
            "error_category": cat["category"], "reason": cat["reason"], "action": cat["action"],
        }

    before_dt = _ppool_parse_expires_at(lease.get("expires_at"))
    return {"ok": True, "provider": provider, "period_id": period_id, "before_dt": before_dt}


async def _prenew_execute_renewal(
    lease: Dict[str, Any], *, source: str, _preflight: Optional[Dict[str, Any]] = None,
    _op_id: Optional[int] = None,
) -> Dict[str, Any]:
    """Shared spend tail. This is the ONLY place in the entire project
    that ever passes allow_spend=True to prolong_make() (mirrors
    _pbuy_apply_lease_to_manager being the only make_ipv4() call site for
    buys). Called by:
    - _handle_proxy_renew_confirm_command (manual, after the admin has
      already seen a no-spend prolong_calc() preview and explicitly
      tapped confirm)
    - _prenew_autorenew_one (automatic, only after the caller has already
      verified ALL auto-renew gates: status==active, auto_renew_enabled
      ==1, provider_type==proxy_seller, provider_proxy_id present, and
      per-slot dedupe)
    This function itself does NOT check auto_renew_enabled -- that gate
    belongs entirely to the caller. Returns a plain dict (never a JSON
    string); never includes the raw password or API key.

    R2 (Proxy Renewal Reliability, 20260808): a make response that doesn't
    raise is NOT treated as proof of success anymore. The new expiry is only
    ever written to storage once it is CONFIRMED (either the make response
    itself carries a usable newer date, or a bounded read-only provider
    refresh shows one). If it can't be confirmed, the outcome is
    'renew_unverified' -- money may have been charged, but expires_at is
    left untouched (never guessed) and the caller must NOT re-spend for
    this same pre-renewal expiry (proxy_renewal_ops.idempotency_key, keyed
    on the UNCHANGED expires_at, already makes a second prolong/make for the
    same cycle impossible once this returns -- see _renewal_wrapped_execute).

    BL-1 fix (Proxy Renewal Reliability review, 20260808): the PRE-SPEND
    checks (provider configured / reference_list / period lookup) now live
    in _prenew_preflight_check, called here on-demand when a caller invokes
    this function directly (e.g. a selftest, or _handle_proxy_renew_confirm_
    command's no-spend preview path) without ALSO passing `_preflight`.
    _renewal_wrapped_execute -- the ONLY caller that actually creates a
    proxy_renewal_ops row / burns the idempotency_key -- runs preflight
    FIRST, and only reaches proxy_renewal_op_create (and then this
    function, passing its already-computed `_preflight`) once preflight has
    succeeded, so a pre-spend failure never consumes the idempotency_key
    and stays freely retryable.

    Crash-window fix (independent re-review correction, 20260809): `_op_id`,
    when passed by _renewal_wrapped_execute, is the freshly-created op row's
    id, still in status='pending' (RESERVED -- spend definitely not started).
    Immediately before the prolong_make call below, that row is CAS-advanced
    to 'make_pending' (SPEND_STARTED) via a single atomic UPDATE ... WHERE
    status='pending' -- the durable, explicit boundary the review asked for:
    once that UPDATE's commit() returns, any later crash must be treated as
    POTENTIALLY spent (ordinary provider-refresh reconcile handles it, same
    as before this fix). If the marker write itself fails to land (exception
    or CAS mismatch), prolong_make is NEVER called -- the op is provably
    still pre-spend, so the caller (_renewal_wrapped_execute) frees it via
    proxy_renewal_op_delete_pending instead of leaving a permanently-stuck
    'pending' row. This is the ONLY new write on the spend path; no new
    allow_spend site, no new table."""
    lease_id = lease.get("id")
    provider_proxy_id = lease.get("provider_proxy_id")

    pre = _preflight if _preflight is not None else await _prenew_preflight_check(lease)
    if not pre.get("ok"):
        return pre
    provider = pre["provider"]
    period_id = pre["period_id"]
    before_dt = pre["before_dt"]

    from proxy_provider import extract_renewal_info
    from storage import (
        proxy_lease_get as _prenew_lease_get2,
        proxy_lease_update_renew as _prenew_update_renew2,
        proxy_lease_update_provider_identity as _prenew_update_identity2,
    )

    if _op_id is not None:
        from storage import proxy_renewal_op_advance as _prenew_mark_spend_started
        marked = False
        try:
            marked = await _prenew_mark_spend_started(
                _op_id, "make_pending", from_status="pending", db_path=TPILOT_DB_PATH,
            )
        except Exception as exc:
            print(f"[proxy_renewal] spend-started marker write error op_id={_op_id}: {exc!r}")
        if not marked:
            # The durable SPEND_STARTED write did not land -- prolong_make
            # is NOT called. The op stays 'pending' (provably pre-spend);
            # the caller frees it.
            return {
                "ok": False, "error": "spend_marker_failed",
                "message": "internal: could not durably mark spend-started before calling the provider",
                "error_category": "unknown",
                "reason": "Внутренняя ошибка перед списанием — провайдер не вызывался.",
                "action": "Повторите попытку позже.",
            }

    try:
        make_res = await _pbuy_call(
            provider.prolong_make, _PRENEW_PROXY_TYPE, [provider_proxy_id], period_id, _PRENEW_PAYMENT_ID,
            allow_spend=True,
        )
    except Exception as e:
        err_text = _pbuy_safe_error(e)
        exc_kind = getattr(e, "kind", None)
        cat = _prenew_classify_provider_error(message=err_text, kind=exc_kind, post_spend=True)
        try:
            await _prenew_update_renew2(lease_id, status_text=f"renew_failed:{err_text}", db_path=TPILOT_DB_PATH)
        except Exception:
            pass
        # Money-safety correction (independent re-review, 20260809, second
        # pass): a prior version of this fix distinguished PROVIDER_ERRORS/
        # AUTH from TRANSPORT/HTTP/RESPONSE_SHAPE and freed the idempotency_
        # key for the former two, reasoning that proxy_provider.py's own
        # _request() checks errors[]/envelope-status BEFORE the HTTP status
        # code, so an explicit business-rule rejection or an auth reject
        # must mean the operation was refused pre-billing. That reasoning
        # does not hold: _request() checks errors[] BEFORE the HTTP status
        # on EVERY response, so an HTTP 500/502/429 whose body ALSO happens
        # to carry a JSON errors[] list (a very ordinary shape for a
        # provider-side failure) produces the exact SAME kind=PROVIDER_ERRORS
        # as a clean pre-billing rejection -- the provider may already have
        # processed prolong_make before failing to report success cleanly.
        # ProxyProviderError.kind carries no HTTP status and no separate
        # signal (e.g. request_not_sent/spend_not_attempted) that could
        # disambiguate these -- so kind alone is NOT sufficient structural
        # proof that no charge occurred. Until proxy_provider.py's contract
        # is verified against live Proxy-Seller documentation/traffic and
        # extended with an explicit no-spend signal, EVERY failure reaching
        # this except-block (any kind, any category) is spend-AMBIGUOUS:
        # the caller (_renewal_wrapped_execute) always keeps the
        # idempotency_key burned (status='failed'), never auto-retries, and
        # never frees this op row. Money safety over convenience.
        return {
            "ok": False, "error": "make_failed", "message": err_text,
            "error_category": cat["category"], "reason": cat["reason"], "action": cat["action"],
        }

    # --- R2 verify-after-renew: don't trust "call didn't raise" alone ---
    info = extract_renewal_info(make_res)
    make_new_expires_at = info.get("new_expires_at")
    make_new_dt = _ppool_parse_expires_at(make_new_expires_at) if make_new_expires_at else None

    confirmed_value: Optional[str] = None
    if make_new_dt is not None and (before_dt is None or make_new_dt > before_dt):
        confirmed_value = str(make_new_expires_at)
    else:
        refresh = await _prenew_verify_renewal_via_refresh(
            provider, provider_proxy_id, before_dt, host=lease.get("host"), port=lease.get("port"),
        )
        if refresh.get("confirmed"):
            confirmed_value = str(refresh.get("new_expires_at"))
            entry = refresh.get("entry") or {}
            entry_pid = str(entry.get("provider_proxy_id") or "").strip()
            if entry_pid and entry_pid != str(provider_proxy_id or "").strip():
                # Provider rotated the identity on renewal -- resync THIS
                # lease row in place (never creates a second/orphan row).
                try:
                    await _prenew_update_identity2(
                        lease_id, provider_proxy_id=entry_pid, provider_order_id=entry.get("order_id"),
                        db_path=TPILOT_DB_PATH,
                    )
                    provider_proxy_id = entry_pid
                except Exception:
                    pass

    if confirmed_value is None:
        # Spend may have happened, but the new expiry could not be
        # confirmed. NEVER write expires_at on a guess; NEVER retry the
        # spend for this cycle (the idempotency_key above stays pinned to
        # the unchanged pre-renewal expiry, so a later tick cannot re-spend).
        try:
            await _prenew_update_renew2(lease_id, status_text="renew_unverified", db_path=TPILOT_DB_PATH)
        except Exception:
            pass
        cat = _prenew_classify_provider_error(error_code="unverified")
        return {
            "ok": False, "error": "unverified",
            "message": "Списание могло пройти, но новый срок действия не подтверждён провайдером.",
            "lease_id": lease_id, "manager_key": lease.get("manager_key"),
            "host": lease.get("host"), "port": lease.get("port"),
            "old_expires_at": lease.get("expires_at"), "provider_proxy_id": provider_proxy_id,
            "price": info.get("price"), "total": info.get("total"), "currency": info.get("currency"),
            "error_category": cat["category"], "reason": cat["reason"], "action": cat["action"],
        }

    await _prenew_update_renew2(
        lease_id, status_text="renew_ok", new_expires_at=confirmed_value, db_path=TPILOT_DB_PATH,
    )
    lease2 = await _prenew_lease_get2(lease_id, db_path=TPILOT_DB_PATH) or lease

    return {
        "ok": True,
        "lease_id": lease_id,
        "manager_key": lease.get("manager_key"),
        "host": lease2.get("host"),
        "port": lease2.get("port"),
        "old_expires_at": lease.get("expires_at"),
        "expires_at": lease2.get("expires_at"),
        "provider_proxy_id": provider_proxy_id,
        "price": info.get("price"),
        "total": info.get("total"),
        "currency": info.get("currency"),
    }


async def _handle_proxy_renew_confirm_command(args: str) -> str:
    """Real renewal (manual, admin-confirmed path). Validates the lease,
    then delegates to the SAME idempotent+guarded spend path as the
    auto-renew scheduler (R3, 20260808): _renewal_guard_check ->
    _renewal_wrapped_execute -> _prenew_execute_renewal. There is only ONE
    protected spend path in the project now, manual and automatic alike --
    a double-tap or a manual retry for the SAME pre-renewal expiry can no
    longer double-spend (proxy_renewal_ops idempotency), and an admin-set
    emergency stop/pause/cap/budget/balance floor now applies here too."""
    try:
        lease_id = int(str(args or "").strip().split()[0])
    except Exception:
        return _pbuy_json.dumps({
            "ok": False, "error": "bad_args", "message": "Пустой или некорректный lease_id",
            "reason": "Некорректный запрос.", "action": "Повторите действие из карточки прокси.",
        }, ensure_ascii=False)

    from storage import proxy_lease_get as _prenew_lease_get

    lease = await _prenew_lease_get(lease_id, db_path=TPILOT_DB_PATH)
    if not lease or str(lease.get("status") or "") != "active":
        return _pbuy_json.dumps({
            "ok": False, "error": "lease_not_found", "message": f"Активный lease не найден: {lease_id}",
            "reason": "Активная аренда прокси не найдена.", "action": "Обновите список прокси и повторите попытку.",
        }, ensure_ascii=False)

    provider_proxy_id = lease.get("provider_proxy_id")
    if not provider_proxy_id:
        return _pbuy_json.dumps({
            "ok": False, "error": "missing_provider_proxy_id",
            "message": "У этого прокси нет provider_proxy_id — автоматическое продление невозможно. Обратитесь к провайдеру вручную.",
            "reason": "У прокси нет привязки к провайдеру.", "action": "Обратитесь к провайдеру вручную.",
        }, ensure_ascii=False)

    # CORRECTION B checkpoint follow-up 20260810: this manual command called
    # _renewal_calc_preview (a real, if no-spend, provider reference_list +
    # prolong_calc round trip) BEFORE ever reaching _renewal_wrapped_
    # execute's own orphan gate -- an admin manually confirming an orphan
    # lease still made two live provider calls before being rejected. Gate
    # here too, before ANY provider interaction, not just before spend.
    if await _prenew_lease_is_orphan(lease, context="panel_renew_confirm_entry"):
        return _pbuy_json.dumps({
            "ok": False, "skipped": True, "error": "orphan_lease",
            "message": "У этого прокси нет реального назначенного менеджера — автопродление и списание не выполняются.",
            "reason": "Прокси не привязан к активному менеджеру (orphan lease).",
            "action": "Проверьте привязку прокси в пуле (синхронизация/переназначение).",
        }, ensure_ascii=False)

    import storage as _rn_confirm_storage
    cfg = await _rn_confirm_storage.proxy_renewal_config_get(db_path=TPILOT_DB_PATH)
    day_str = _renewal_kyiv_today_str()
    preview = await _renewal_calc_preview(lease)
    calc_total = preview.get("total") if preview.get("ok") else None
    block = await _renewal_guard_check(cfg, calc_total, day_str)
    if block:
        return _pbuy_json.dumps({
            "ok": False, "error": "blocked", "message": block,
            "reason": block, "action": "Проверьте настройки автопродления (лимиты/баланс/пауза).",
        }, ensure_ascii=False)

    result = await _renewal_wrapped_execute(lease, source="panel_renew_confirm", actor_user_id=None)
    if result.get("skipped"):
        return _pbuy_json.dumps(result, ensure_ascii=False)
    if result.get("ok"):
        result["display_name"] = await _prenew_display_name(str(lease.get("manager_key") or ""))
    return _pbuy_json.dumps(result, ensure_ascii=False)


async def _handle_proxy_renew_defer_command(args: str) -> str:
    """Pure bookkeeping (last_renew_status='deferred'). Since Stage 6.1E,
    the warning loop's dedupe is per-lease/date/slot (proxy_renew_notify_
    log), not a last_renew_attempt_at cooldown -- deferring no longer
    suppresses the next slot's warning, it only records that the admin
    saw and dismissed this one. Never touches the provider, never
    spends."""
    try:
        lease_id = int(str(args or "").strip().split()[0])
    except Exception:
        return _pbuy_json.dumps({"ok": False, "error": "bad_args", "message": "Пустой или некорректный lease_id"}, ensure_ascii=False)

    from storage import proxy_lease_get as _prenew_lease_get, proxy_lease_update_renew as _prenew_update_renew

    lease = await _prenew_lease_get(lease_id, db_path=TPILOT_DB_PATH)
    if not lease:
        return _pbuy_json.dumps({"ok": False, "error": "lease_not_found", "message": f"Lease не найден: {lease_id}"}, ensure_ascii=False)
    await _prenew_update_renew(lease_id, status_text="deferred", db_path=TPILOT_DB_PATH)
    return _pbuy_json.dumps({"ok": True, "lease_id": lease_id, "message": "Напоминание отложено."}, ensure_ascii=False)


async def _handle_proxy_pool_autorenew_command(args: str) -> str:
    """Toggle proxy_leases.auto_renew_enabled for one lease (Stage 6.1F).
    Pure storage write -- never calls the provider, never spends."""
    parts = str(args or "").strip().split()
    try:
        lease_id = int(parts[0])
    except Exception:
        return _pbuy_json.dumps({"ok": False, "error": "bad_args", "message": "Пустой или некорректный lease_id"}, ensure_ascii=False)
    if len(parts) < 2 or parts[1] not in ("0", "1"):
        return _pbuy_json.dumps({"ok": False, "error": "bad_args", "message": "Формат: /proxy_pool_autorenew <lease_id> <0|1>"}, ensure_ascii=False)
    enabled = parts[1] == "1"

    from storage import proxy_lease_get as _ar_lease_get, proxy_lease_set_auto_renew as _ar_set_autorenew

    lease = await _ar_lease_get(lease_id, db_path=TPILOT_DB_PATH)
    if not lease:
        return _pbuy_json.dumps({"ok": False, "error": "lease_not_found", "message": f"Lease не найден: {lease_id}"}, ensure_ascii=False)

    ok = await _ar_set_autorenew(lease_id, enabled, db_path=TPILOT_DB_PATH)
    if not ok:
        return _pbuy_json.dumps({"ok": False, "error": "update_failed", "message": "Не удалось изменить автопродление."}, ensure_ascii=False)

    return _pbuy_json.dumps({"ok": True, "lease_id": lease_id, "auto_renew_enabled": enabled}, ensure_ascii=False)


async def _prenew_autorenew_one(lease: Dict[str, Any]) -> None:
    """Attempt one guarded auto-renewal for a lease that has ALREADY
    passed every gate in the caller (_prenew_autorenew_loop): status ==
    'active', provider_type == 'proxy_seller', provider_proxy_id present,
    auto_renew_enabled == 1, and not already attempted in this slot/date.
    Sends exactly one admin message reporting success or failure. Never
    exposes the password/API key (only scrubbed provider errors, host,
    lease_id, dates, and a possible price are included).

    R3 (Proxy Renewal Reliability, 20260808): the spend itself is no longer
    a direct call to _prenew_execute_renewal. It goes through the SAME
    idempotent+guarded path as the (previously dormant) TPilot-managed
    engine: _renewal_guard_check (emergency stop/pause/per-op cap/daily
    budget/min balance -- all no-ops with the default unconfigured values,
    so this changes nothing for an admin who never touched those settings)
    and _renewal_wrapped_execute (proxy_renewal_ops idempotency -- a second
    attempt for the SAME pre-renewal expiry is rejected before it can ever
    reach the provider). This intentionally does NOT gate on
    proxy_renewal_config.automation_enabled -- that flag is the OTHER
    (still-dormant) engine's separate one-time-consent switch for running
    UNPROMPTED background renewals on its own 6h cadence; this scheduler
    has always run on its own slot cadence regardless of that flag, and
    gating on it here would silently stop all auto-renewal in production."""
    lease_id = lease.get("id")
    # CORRECTION B 20260810: defensive barrier, same rationale as the
    # identical check in _renewal_auto_tick_report_outcome -- the caller
    # (_prenew_autorenew_loop) already gates on role before calling this
    # function at all, but re-checking here with the SAME classifier means a
    # future direct caller can never reintroduce an orphan alert/spend by
    # forgetting that gate.
    if await _prenew_lease_is_orphan(lease, context="autorenew_one"):
        return
    import storage as _ar_storage
    cfg = await _ar_storage.proxy_renewal_config_get(db_path=TPILOT_DB_PATH)
    day_str = _renewal_kyiv_today_str()
    preview = await _renewal_calc_preview(lease)
    calc_total = preview.get("total") if preview.get("ok") else None
    block = await _renewal_guard_check(cfg, calc_total, day_str)
    if block:
        result: Dict[str, Any] = {"ok": False, "error": "blocked", "message": block}
    else:
        result = await _renewal_wrapped_execute(lease, source="autorenew", actor_user_id=None)
        if result.get("skipped"):
            if result.get("error") != "blocked_unresolved":
                # Already in flight -- the FIRST attempt for this
                # pre-renewal expiry already reported its outcome; nothing
                # new happened, so nothing new to tell the admin.
                return
            # BLOCKER-1 fix (retry-policy correction, 20260809):
            # 'blocked_unresolved' means a durably-stuck ambiguous op from
            # an EARLIER attempt is occupying this lease's idempotency_key
            # -- previously this fell through the same silent `return` as
            # a benign in-flight skip, so the admin was never told a lease
            # near expiry could no longer renew at all ("тихая смерть").
            # Falls through into the shared non-success reporting block
            # below (same dedup/notify machinery as every other outcome).
    # R5 (Proxy Renewal Reliability, 20260808): SUCCESS is now SILENT (no
    # Telegram at all -- NO ACTION REQUIRED = NO ALERT). It's recorded as a
    # safe lifecycle/audit event instead (proxy_lifecycle_events, already
    # used by the lifecycle-sync subsystem for exactly this purpose --
    # append-only, never stores secrets).
    if result.get("ok"):
        try:
            total = result.get("total")
            price = result.get("price")
            currency = str(result.get("currency") or "").strip()
            amount_text = f"{total} {currency}".strip() if total is not None else (f"{price} {currency}".strip() if price is not None else "")
            await _ar_storage.proxy_lifecycle_event_add(
                lease_id, "renew_ok", provider_proxy_id=result.get("provider_proxy_id"),
                actor="autorenew",
                detail=f"old={result.get('old_expires_at')} new={result.get('expires_at')} amount={amount_text}".strip(),
                db_path=TPILOT_DB_PATH,
            )
        except Exception as exc:
            print(f"[prenew-autorenew] success audit-log error: {exc!r}")
        return

    # --- Non-success: blocked / unverified / classified provider failure.
    # R5d dedup: at most ONE non-success card per lease per Kyiv day PER
    # error_category (NB-6 fix, review 20260808) -- BL-1 means a pre-spend
    # failure (e.g. provider not_configured) is now freely retryable, so
    # several DIFFERENT real causes can legitimately occur for the same
    # lease on the same day; deduping on a single flat "outcome_notify" slot
    # would silently swallow every category after the first one to fire.
    # Genuine provider failures/unverified outcomes that DID reach the spend
    # stage are ALSO naturally deduped by proxy_renewal_ops.idempotency_key
    # (it stays pinned to the unchanged pre-renewal expiry), so this is a
    # belt-and-suspenders guarantee, not the only one -- and a materially
    # DIFFERENT category (e.g. insufficient_balance today after a
    # not_configured card yesterday morning) is still shown, exactly once.
    error_code = str(result.get("error") or "")
    if error_code == "unverified":
        notify_category = "unverified"
    elif error_code == "blocked":
        notify_category = "blocked"
    elif error_code == "blocked_unresolved":
        notify_category = "blocked_unresolved"
    else:
        notify_category = str(result.get("error_category") or "unknown")
    should_notify = await _ar_storage.proxy_renew_notify_mark_once(
        lease_id, day_str, f"outcome_notify:{notify_category}", db_path=TPILOT_DB_PATH,
    )
    if not should_notify:
        return

    header = [
        f"Менеджер: {await _prenew_manager_identity_line(str(lease.get('manager_key') or ''))}",
        f"Ключ: {lease.get('manager_key') or '_'}",
        f"Прокси: {lease.get('host') or '_'}:{lease.get('port') or '_'}",
        f"Действует до: {_prenew_format_expires_display(lease.get('expires_at'))}",
    ]

    if error_code == "unverified":
        title = "⚠️ Продление прокси не подтверждено"
        lines = [title, "", *header, "",
                 "Списание могло пройти, но Proxy-Seller пока не подтвердил новый срок.",
                 "Повторное списание автоматически не выполн��ется.",
                 "",
                 "Что делать: синхронизируйте пул и проверьте прокси.",
                 "", f"lease_id: {lease_id}"]
        kind = "proxy_autorenew_unverified"
    elif error_code == "blocked_unresolved":
        # BLOCKER-1 fix (retry-policy correction, 20260809): this lease's
        # idempotency_key is durably occupied by an earlier ambiguous
        # attempt (proxy_renewal_ops status='failed') -- no automatic
        # retry is possible until either a later provider-refresh reconcile
        # confirms the renewal actually went through, or the admin
        # verifies via sync. NO spend button (proxy_autorenew_unverified's
        # existing buttons: sync pool + open card only).
        title = "⚠️ Продление прокси требует проверки"
        lines = [title, "", *header, "",
                 "Причина: предыдущая попытка продления не подтверждена.",
                 "Повторное списание автоматически не выполняется.",
                 "",
                 "Что делать: синхронизируйте пул и проверьте прокси.",
                 "", f"lease_id: {lease_id}"]
        kind = "proxy_autorenew_unverified"
    elif error_code == "blocked":
        title = "⚠️ Автопродление заблокировано"
        lines = [title, "", *header, "",
                 f"Причина: {result.get('message') or 'автопродление заблокировано настройками'}",
                 "Что делать: проверьте настройки автопродления (лимиты/баланс/пауза).",
                 "", f"lease_id: {lease_id}"]
        kind = "proxy_autorenew_blocked"
    else:
        title = "⚠️ Не удалось продлить прокси"
        reason = result.get("reason") or "Не удалось определить причину ошибки провайдера."
        action = result.get("action") or "Откройте карточку прокси и проверьте вручную."
        lines = [title, "", *header, "",
                 f"Причина: {reason}",
                 f"Что делать: {action}",
                 "", f"lease_id: {lease_id}"]
        kind = "proxy_autorenew_failed"

    body = "\n".join(lines)
    try:
        await _create_panel_notification(kind, title, body)
    except Exception as exc:
        print(f"[prenew-autorenew] {kind} notify error: {exc!r}")


def _prenew_autorenew_gates_ok(lease: Dict[str, Any], slot: str, now_local: datetime) -> bool:
    """Pure (no I/O), independently-testable auto-renew eligibility check
    for ONE lease at the CURRENT slot. Caller (_prenew_autorenew_loop) has
    already filtered to status=='active' and provider_type=='proxy_seller'
    via _prenew_collect_active_seller_leases -- this checks the remaining
    gates: auto_renew_enabled==1, provider_proxy_id present, and the
    day-delta matches this slot's bucket (tomorrow for autorenew_pre,
    today for the 3 today_* slots). Does NOT check per-slot dedupe (that
    is proxy_renew_notify_mark_once, a DB side effect the caller checks
    separately). Never raises."""
    try:
        if int(lease.get("auto_renew_enabled") or 0) != 1:
            return False
        if not lease.get("provider_proxy_id"):
            return False
        expires_dt = _ppool_parse_expires_at(lease.get("expires_at"))
        if expires_dt is None:
            return False
        day_delta = (expires_dt.date() - now_local.date()).days
        if slot == "autorenew_pre":
            return day_delta == 1
        if slot in ("autorenew_today_morning", "autorenew_today_day", "autorenew_today_evening"):
            return day_delta == 0
        return False
    except Exception:
        return False


async def _prenew_autorenew_loop() -> None:
    """Kyiv-local, slot-based, per-lease/date/slot deduped auto-renewal.
    First attempt at the autorenew_pre slot (day before expiry, ~12:00);
    on failure, retries at autorenew_today_morning/day/evening. Spends
    ONLY when ALL gates pass: status active, provider_type proxy_seller,
    provider_proxy_id present, auto_renew_enabled==1, and this exact
    (lease_id, date, slot) hasn't already been attempted."""
    while True:
        try:
            now_local = _kyiv_now().replace(tzinfo=None)
            slot = _prenew_slot_for_now(now_local, _PRENEW_AUTORENEW_SLOTS)
            if slot:
                notify_date = now_local.strftime("%Y-%m-%d")
                from storage import proxy_renew_notify_mark_once as _ar_mark_once
                leases = await _prenew_collect_active_seller_leases()
                usage_map = await _ppool_manager_usage_map()  # R1: observe-mode role diagnostic only
                for lease in leases:
                    try:
                        if not _prenew_autorenew_gates_ok(lease, slot, now_local):
                            continue
                        # R1 (observe mode): compute+log role, never gate on it unless enforcement is on.
                        role = await _prenew_role_diagnostic(lease, usage_map, context="autorenew")
                        if _PRENEW_ROLE_ENFORCEMENT_ENABLED and role != "managed":
                            continue
                        lease_id = int(lease.get("id") or 0)
                        if not lease_id:
                            continue
                        should_attempt = await _ar_mark_once(lease_id, notify_date, slot, db_path=TPILOT_DB_PATH)
                        if not should_attempt:
                            continue
                        await _prenew_autorenew_one(lease)
                    except Exception as exc:
                        print(f"[prenew-autorenew] per-lease error: {exc!r}")
        except asyncio.CancelledError:
            return
        except Exception as exc:
            print(f"[prenew-autorenew] loop error: {exc!r}")
        await asyncio.sleep(_PRENEW_LOOP_TICK_SEC)


_PRENEW_PREV_PANEL_EXEC = globals().get("_panel_execute_command_text")


async def _panel_execute_command_text(  # type: ignore[override]
    command_text: str, *, requested_by: int = 0
) -> dict:
    """Stage 5/6.1F: route the renewal calc/confirm/defer/autorenew-toggle
    commands before chaining to the previous (Stage 4) handler."""
    cmd, _, args = str(command_text or "").strip().partition(" ")
    args = args.strip()
    if cmd == "/proxy_renew_calc":
        try:
            result_text = await _handle_proxy_renew_calc_command(args)
        except Exception as exc:
            result_text = _pbuy_json.dumps({"ok": False, "error": "internal_error", "message": _pbuy_safe_error(exc)}, ensure_ascii=False)
        return {"ok": True, "result_text": result_text}
    if cmd == "/proxy_renew_confirm":
        try:
            result_text = await _handle_proxy_renew_confirm_command(args)
        except Exception as exc:
            result_text = _pbuy_json.dumps({"ok": False, "error": "internal_error", "message": _pbuy_safe_error(exc)}, ensure_ascii=False)
        return {"ok": True, "result_text": result_text}
    if cmd == "/proxy_renew_defer":
        try:
            result_text = await _handle_proxy_renew_defer_command(args)
        except Exception as exc:
            result_text = _pbuy_json.dumps({"ok": False, "error": "internal_error", "message": _pbuy_safe_error(exc)}, ensure_ascii=False)
        return {"ok": True, "result_text": result_text}
    if cmd == "/proxy_pool_autorenew":
        try:
            result_text = await _handle_proxy_pool_autorenew_command(args)
        except Exception as exc:
            result_text = _pbuy_json.dumps({"ok": False, "error": "internal_error", "message": _pbuy_safe_error(exc)}, ensure_ascii=False)
        return {"ok": True, "result_text": result_text}
    if callable(_PRENEW_PREV_PANEL_EXEC):
        return await _PRENEW_PREV_PANEL_EXEC(command_text, requested_by=requested_by)
    return {"ok": False, "result_text": f"Команда не поддерживается: {cmd}"}

# --- TPILOT PROXY RENEW STAGE5 END ---


# --- TPILOT PROXY POOL STAGE6 P2 (read-only pool screens) START ---
# Read-only: no assign/unassign/reassign/sync/check/buy/renew here (those
# are later stages). Every command below only reads proxy_leases +
# managers and derives a status label on the fly -- no schema change, no
# DB writes, no provider calls, no spend.

def _ppool_parse_expires_at(raw: Any) -> Optional[datetime]:
    """Defensive expires_at parser. Live Proxy-Seller data has been seen
    as ISO ("2026-09-09" / "2026-09-09T00:00:00") and as "DD.MM.YYYY"
    ("07.08.2026"). Returns None (never raises) if the format isn't
    recognized -- callers must treat None as "cannot determine, don't
    mark expired", never guess."""
    text = str(raw or "").strip()
    if not text:
        return None
    for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%d.%m.%Y"):
        try:
            return datetime.strptime(text, fmt)
        except Exception:
            pass
    try:
        dt = datetime.fromisoformat(text.replace("Z", "+00:00"))
        return dt.replace(tzinfo=None) if dt.tzinfo is not None else dt
    except Exception:
        return None


# --- PROXY USAGE DETECTION 20260711 START -----------------------------
# Detect which host+port pairs are ACTUALLY in use, by reading real live
# managers' own proxy_* fields (not just proxy_leases.manager_key). This
# catches proxies applied outside the pool (manual SOCKS5 entry, legacy
# data) as well as pool leases, and is what powers the "occupied" status,
# the "external" (сторонний) proxy list, and the multi-assign warning.
# Pure read-only, no schema change, no provider call, never includes a
# password anywhere in its output.

def _ppool_usage_key(host: Any, port: Any) -> Optional[Tuple[str, int]]:
    """Normalize a host+port pair into the map key: host lower/strip, port
    coerced to a positive int. Returns None if either is missing/invalid."""
    h = str(host or "").strip().lower()
    if not h:
        return None
    try:
        p = int(str(port).strip())
    except Exception:
        return None
    if p <= 0:
        return None
    return (h, p)


async def _ppool_manager_usage_map() -> Dict[Tuple[str, int], List[Dict[str, Any]]]:
    """Read-only map of (host_norm, port) -> live managers whose OWN
    proxy_enabled=1 fields point at that host+port. Built ONCE per command
    (never per-lease) from manager_list_rows(include_removed=False) --
    real manager configuration, not proxy_leases -- so this also surfaces
    proxies never bought through the pool ("external"). A manager with
    proxy_enabled=0 (a saved-but-disabled config) is never counted as
    actively occupying its proxy (owner decision)."""
    usage: Dict[Tuple[str, int], List[Dict[str, Any]]] = {}
    try:
        rows = await manager_list_rows(include_removed=False)
    except Exception:
        return usage
    for r in rows or []:
        if int(r.get("proxy_enabled") or 0) != 1:
            continue
        key = _ppool_usage_key(r.get("proxy_host"), r.get("proxy_port"))
        if not key:
            continue
        mk = registry_normalize_manager_key(r.get("manager_key") or "")
        if not mk:
            continue
        usage.setdefault(key, []).append({
            "manager_key": mk,
            "display_name": str(r.get("display_name") or "").strip() or mk,
            "telegram_username": str(r.get("telegram_username") or "").strip(),
            "proxy_login": str(r.get("proxy_username") or "").strip(),
            "proxy_enabled": 1,
        })
    return usage


def _ppool_usage_public(entries: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Strip a usage-map entry list down to the public used_by shape --
    identity fields only, never login/password."""
    return [
        {"manager_key": e.get("manager_key"), "display_name": e.get("display_name"), "telegram_username": e.get("telegram_username")}
        for e in (entries or [])
    ]

# --- PROXY USAGE DETECTION 20260711 END --------------------------------


async def _ppool_derive_status(
    lease: Dict[str, Any], usage_map: Optional[Dict[Tuple[str, int], List[Dict[str, Any]]]] = None
) -> Tuple[str, Optional[Dict[str, Any]]]:
    """Derive a pool status label without any schema change. Priority:
    disabled (explicit lease.status) > orphaned (manager_key points at a
    missing or archived manager) > expired > assigned > occupied (real
    usage-map match, PROXY USAGE DETECTION 20260711) > free. Returns
    (status, manager_row) -- manager_row is None when there's no
    manager_key, or the manager wasn't found. `usage_map` is optional and
    backward-compatible: omitting it (existing callers) simply skips the
    occupied check and preserves the original free/assigned/... behavior
    byte-for-byte."""
    status_col = str(lease.get("status") or "").strip().lower()
    manager_key = str(lease.get("manager_key") or "").strip()
    manager_row: Optional[Dict[str, Any]] = None
    if manager_key:
        manager_row = await _tpag_registry_get(manager_key)

    if status_col and status_col != "active":
        return "disabled", manager_row

    expires_dt = _ppool_parse_expires_at(lease.get("expires_at"))
    # R5b (Proxy Renewal Reliability, 20260808): compare Kyiv CALENDAR DATES,
    # not a naive expiry datetime against UTC now -- day-math elsewhere in
    # this subsystem (_prenew_warn_eligible/_prenew_autorenew_gates_ok/
    # _renewal_eligible_leases) is already Kyiv-based, and a date-only
    # expires_at parses to midnight, so comparing it to _tp_utc_now()
    # mislabelled a lease expiring TODAY as already "(expired)" for several
    # hours every morning (Kyiv is ahead of UTC).
    is_expired = expires_dt is not None and expires_dt.date() < _kyiv_now().date()

    if manager_key:
        if manager_row is None or str(manager_row.get("status") or "").strip().lower() == "archived":
            return "orphaned", manager_row
        if is_expired:
            return "expired", manager_row
        return "assigned", manager_row

    if is_expired:
        return "expired", None

    if usage_map:
        key = _ppool_usage_key(lease.get("host"), lease.get("port"))
        if key and usage_map.get(key):
            return "occupied", None

    return "free", None


async def _ppool_lease_summary(
    lease: Dict[str, Any], usage_map: Optional[Dict[Tuple[str, int], List[Dict[str, Any]]]] = None
) -> Dict[str, Any]:
    status, manager_row = await _ppool_derive_status(lease, usage_map=usage_map)
    manager_key = str(lease.get("manager_key") or "").strip() or None
    usage_key = _ppool_usage_key(lease.get("host"), lease.get("port"))
    used_by = _ppool_usage_public((usage_map or {}).get(usage_key, [])) if usage_key else []
    return {
        "lease_id": lease.get("id"),
        "host": lease.get("host"),
        "port": lease.get("port"),
        "scheme": lease.get("scheme"),
        "proxy_type": lease.get("proxy_type"),
        "manager_key": manager_key,
        "manager_display_name": (str(manager_row.get("display_name") or "").strip() or manager_key) if manager_row else manager_key,
        "status": status,
        "used_by": used_by,
        "expires_at": lease.get("expires_at"),
        "provider_order_id": lease.get("provider_order_id"),
        "provider_proxy_id": lease.get("provider_proxy_id"),
    }


_PPOOL_VALID_FILTERS = ("all", "free", "occupied", "assigned", "orphaned", "expired", "disabled", "external", "available")
# "available" (Stage 6.1A, manager-onboarding pool picker) == status in
# (free, orphaned) -- active leases with no live manager currently on
# them, i.e. safe to hand to a newly-created/existing manager. "occupied"
# (PROXY USAGE DETECTION 20260711) is deliberately NOT in this tuple --
# an occupied proxy is, by definition, in active use and must never be
# offered as available.
_PPOOL_AVAILABLE_STATUSES = ("free", "orphaned")


async def _handle_proxy_pool_list_command(args: str) -> str:
    """Read-only: list every lease (optionally filtered by derived
    status). Never includes raw login/password. Never calls the
    provider.

    PROXY USAGE DETECTION 20260711: builds the manager-usage map ONCE
    (not per-lease) so "occupied" leases are correctly excluded from
    free/available, and each item carries a used_by list. filt="external"
    switches to an entirely different result shape: manager-used host+port
    pairs that have NO matching proxy_leases row at all (a "сторонний"
    proxy never bought through the pool) -- host/port/used_by only, no
    login/password beyond what each used_by entry's own manager already
    exposes about itself (still identity-only, per _ppool_usage_public)."""
    raw_filt = str(args or "").strip().lower().split()[0] if str(args or "").strip() else "all"
    filt = raw_filt if raw_filt in _PPOOL_VALID_FILTERS else "all"

    from storage import proxy_lease_list_all as _ppool_list_all
    leases = await _ppool_list_all(db_path=TPILOT_DB_PATH)
    usage_map = await _ppool_manager_usage_map()

    if filt == "external":
        lease_keys = {k for k in (_ppool_usage_key(l.get("host"), l.get("port")) for l in leases) if k}
        items = []
        for key, entries in usage_map.items():
            if key in lease_keys:
                continue
            host, port = key
            items.append({
                "host": host,
                "port": port,
                "status": "external",
                "used_by": [
                    {"manager_key": e.get("manager_key"), "display_name": e.get("display_name"),
                     "telegram_username": e.get("telegram_username"), "proxy_login": e.get("proxy_login") or ""}
                    for e in entries
                ],
            })
        items.sort(key=lambda it: (it["host"], it["port"]))
        return _pbuy_json.dumps({"ok": True, "filter": filt, "count": len(items), "items": items}, ensure_ascii=False)

    items = []
    for lease in leases:
        summary = await _ppool_lease_summary(lease, usage_map=usage_map)
        if filt == "available":
            if summary["status"] not in _PPOOL_AVAILABLE_STATUSES:
                continue
        elif filt != "all" and summary["status"] != filt:
            continue
        items.append(summary)

    return _pbuy_json.dumps({"ok": True, "filter": filt, "count": len(items), "items": items}, ensure_ascii=False)


async def _handle_proxy_pool_card_command(args: str) -> str:
    """Read-only: one lease's full card. Password is NEVER included, even
    masked -- only a has_password boolean travels through result_text;
    the UI shows "****" for True. Never calls the provider."""
    try:
        lease_id = int(str(args or "").strip().split()[0])
    except Exception:
        return _pbuy_json.dumps({"ok": False, "error": "bad_args", "message": "Пустой или некорректный lease_id"}, ensure_ascii=False)

    from storage import proxy_lease_get as _ppool_lease_get
    lease = await _ppool_lease_get(lease_id, db_path=TPILOT_DB_PATH)
    if not lease:
        return _pbuy_json.dumps({"ok": False, "error": "lease_not_found", "message": f"Lease не найден: {lease_id}"}, ensure_ascii=False)

    # PROXY USAGE DETECTION 20260711: same usage-aware status + used_by list
    # as the list command, so the card can show an "occupied" warning too.
    usage_map = await _ppool_manager_usage_map()
    status, manager_row = await _ppool_derive_status(lease, usage_map=usage_map)
    manager_key = str(lease.get("manager_key") or "").strip() or None
    usage_key = _ppool_usage_key(lease.get("host"), lease.get("port"))
    used_by = _ppool_usage_public(usage_map.get(usage_key, [])) if usage_key else []

    return _pbuy_json.dumps({
        "ok": True,
        "lease_id": lease.get("id"),
        "host": lease.get("host"),
        "port": lease.get("port"),
        "scheme": lease.get("scheme"),
        "proxy_type": lease.get("proxy_type"),
        "status": status,
        "used_by": used_by,
        "login": lease.get("login") or None,
        "has_password": bool(str(lease.get("password") or "").strip()),
        "manager_key": manager_key,
        "manager_display_name": (str(manager_row.get("display_name") or "").strip() or manager_key) if manager_row else None,
        "expires_at": lease.get("expires_at"),
        "provider_order_id": lease.get("provider_order_id"),
        "provider_order_number": lease.get("provider_order_number"),
        "provider_proxy_id": lease.get("provider_proxy_id"),
        "auto_renew_enabled": bool(int(lease.get("auto_renew_enabled") or 0)),
        "last_check_at": lease.get("last_check_at"),
        "last_check_ok": lease.get("last_check_ok"),
        "last_check_status": lease.get("last_check_status"),
        "last_renew_attempt_at": lease.get("last_renew_attempt_at"),
        "last_renew_status": lease.get("last_renew_status"),
        "created_at": lease.get("created_at"),
        # PROXY LIFECYCLE SYNC 20260721: bidirectional desired-vs-observed
        # provider auto_renew state, for the card's informational display.
        "lifecycle_status": lease.get("lifecycle_status"),
        "desired_provider_auto_renew": lease.get("desired_provider_auto_renew"),
        "observed_provider_auto_renew": lease.get("observed_provider_auto_renew"),
        "provider_sync_at": lease.get("provider_sync_at"),
    }, ensure_ascii=False)

# --- TPILOT PROXY POOL STAGE6 P2 END ---


# --- TPILOT PROXY POOL STAGE6 P3 (assign / unassign / reassign) START ---
# Controller-side only, mirrors the read-only P2 commands' architecture:
# PanelBot is UI + panel_commands submission; every storage write happens
# here. NEVER calls the provider (no reference_list/calc/make/prolong),
# NEVER spends (allow_spend=True is not referenced anywhere in this
# block). Assign/unassign/reassign are pure storage writes + a guard
# check (same TCP/SOCKS/Telethon liveness check the manual /manager_
# proxy_set flow already runs) -- no purchase, no renewal, no provider
# sync.

async def _ppool_disable_manager_proxy_fields(manager_key: str) -> None:
    """Disable a manager's proxy fields after their lease is unassigned.
    Mirrors the EXISTING /manager_proxy_bypass convention (proxy_enabled=0,
    proxy_bypass_allowed=1) plus the one-time-migration's proxy_mode=
    'direct' pairing -- see _tpilot_panel_manager_proxy_bypass_command and
    the tpag_v2_mode_migration SQL. Also resets proxy_required=0 so the
    manager isn't gated on a proxy it no longer has. Does NOT clear
    proxy_host/port/username/password (same as the existing bypass
    command) -- the proxy_leases row (not these columns) is the pool's
    source of truth, and preserving them keeps a debugging trail. Never
    raises (best-effort, same convention as _tpag_registry_set_fields)."""
    await _tpag_registry_set_fields(
        manager_key,
        proxy_enabled=0,
        proxy_mode="direct",
        proxy_required=0,
        proxy_bypass_allowed=1,
        proxy_bypass_reason="pool_unassign",
        proxy_bypass_at=_now_utc_iso(),
    )


async def _handle_proxy_pool_assign_command(args: str) -> str:
    """Link an EXISTING pool lease to a manager (assign, or reassign if it
    was already linked to a different manager). Idempotent when the lease
    is already linked to the SAME manager. Never calls the provider, never
    spends, never creates/deletes a lease row.

    PROXY USAGE DETECTION 20260711: format is now
    '<lease_id> <manager_key> [multi]'. Before applying, checks whether
    this lease's host+port is actively used (proxy_enabled=1) by any live
    manager OTHER than the target and OTHER than this lease's own current
    owner (a plain reassign FROM the current owner TO someone else remains
    the existing, unmodified single-owner transfer below). Without the
    trailing 'multi' token, a real conflict refuses with error=proxy_in_use
    and a used_by list (identity only, never a password) instead of
    silently detaching/overwriting anyone. With 'multi', the caller has
    explicitly confirmed 1 proxy -> N managers: the conflicting occupant(s)
    are left completely untouched (no detach, no field clearing), and if
    the lease already had a tracked owner, that owner's link is preserved
    too (proxy_leases.manager_key / managers.proxy_lease_id are NOT
    reassigned) -- see _pbuy_apply_lease_to_manager's link_lease=False. A
    lease with NO prior owner is still linked to the new manager even under
    multi (nothing to protect by refusing to)."""
    parts = str(args or "").strip().split()
    try:
        lease_id = int(parts[0])
    except Exception:
        return _pbuy_json.dumps({"ok": False, "error": "bad_args", "message": "Пустой или некорректный lease_id"}, ensure_ascii=False)
    manager_key = registry_normalize_manager_key(parts[1]) if len(parts) > 1 else ""
    if not manager_key:
        return _pbuy_json.dumps({"ok": False, "error": "bad_args", "message": "Пустой manager_key"}, ensure_ascii=False)
    multi = len(parts) > 2 and str(parts[2]).strip().lower() == "multi"

    from storage import proxy_lease_get as _ppool_lease_get, proxy_lease_unassign as _ppool_unassign_lease

    lease = await _ppool_lease_get(lease_id, db_path=TPILOT_DB_PATH)
    if not lease:
        return _pbuy_json.dumps({"ok": False, "error": "lease_not_found", "message": f"Lease не найден: {lease_id}"}, ensure_ascii=False)

    lease_status_col = str(lease.get("status") or "").strip().lower()
    if lease_status_col and lease_status_col != "active":
        return _pbuy_json.dumps({
            "ok": False, "error": "lease_not_active",
            "message": f"Прокси #{lease_id} отключён (status={lease_status_col}) и не может быть назначен.",
        }, ensure_ascii=False)

    new_manager_row = await _tpag_registry_get(manager_key)
    if not new_manager_row:
        return _pbuy_json.dumps({"ok": False, "error": "manager_not_found", "message": f"Менеджер не найден: {manager_key}"}, ensure_ascii=False)
    if str(new_manager_row.get("status") or "").strip().lower() == "archived":
        return _pbuy_json.dumps({"ok": False, "error": "manager_archived", "message": f"Менеджер архивирован: {manager_key}"}, ensure_ascii=False)

    old_manager_key = str(lease.get("manager_key") or "").strip() or None

    # PROXY USAGE DETECTION 20260711: block on a real conflict unless the
    # caller explicitly opted into multi-assign. The lease's own CURRENT
    # owner (old_manager_key) is excluded from the conflict set -- a plain
    # reassign FROM the current owner TO someone else is the existing,
    # already-supported single-owner transfer (the old owner is cleanly
    # detached a few lines below); it is not a "proxy already used
    # elsewhere" situation. A conflict is any OTHER live manager (neither
    # the target nor the lease's own current owner) whose own proxy_*
    # fields independently point at this same host+port.
    if not multi:
        usage_key = _ppool_usage_key(lease.get("host"), lease.get("port"))
        if usage_key:
            usage_map = await _ppool_manager_usage_map()
            conflict = [
                u for u in usage_map.get(usage_key, [])
                if u.get("manager_key") != manager_key and u.get("manager_key") != old_manager_key
            ]
            if conflict:
                return _pbuy_json.dumps({
                    "ok": False, "error": "proxy_in_use",
                    "lease_id": lease_id, "manager_key": manager_key,
                    "used_by": _ppool_usage_public(conflict),
                    "message": f"Прокси #{lease_id} уже используется другим менеджером.",
                }, ensure_ascii=False)

    if old_manager_key and old_manager_key != manager_key and not multi:
        # Reassign: detach from the OLD manager first (clears both sides
        # of the old link + disables the old manager's proxy fields) only
        # if that manager still exists -- an orphaned lease (old manager
        # deleted) has nothing to detach; _pbuy_apply_lease_to_manager
        # below overwrites proxy_leases.manager_key to the new value
        # directly in that case. Skipped entirely under 'multi' -- the
        # old owner keeps using this proxy untouched.
        old_manager_row = await _tpag_registry_get(old_manager_key)
        if old_manager_row:
            await _ppool_unassign_lease(lease_id, db_path=TPILOT_DB_PATH)
            try:
                await _ppool_disable_manager_proxy_fields(old_manager_key)
            except Exception:
                pass

    # --- Stage 6 P3.1 consistency fix -----------------------------------
    # Still runs under 'multi' -- this frees the TARGET manager's own
    # stale PREVIOUS lease/proxy_lease_id, which is unrelated to the
    # shared-proxy scenario above (a manager should never be left pointing
    # at two different stale lease ids just because they're now sharing
    # someone else's proxy).
    # The TARGET manager may already have a DIFFERENT lease linked -- via
    # managers.proxy_lease_id, or via a stale proxy_leases.manager_key
    # that never got a matching proxy_lease_id (e.g. leftover/inconsistent
    # pool state). Free every such lease BEFORE linking the new one, so a
    # manager never ends up "assigned" to more than one lease at once.
    # Never touches unrelated managers; never calls the provider; never
    # deletes a lease row or clears its provider_proxy_id/host/password --
    # proxy_lease_unassign() only clears the manager link (P1 contract).
    from storage import proxy_lease_list_all as _ppool_list_all_for_cleanup

    stale_lease_ids: set = set()
    current_proxy_lease_id = new_manager_row.get("proxy_lease_id")
    if current_proxy_lease_id not in (None, ""):
        try:
            current_proxy_lease_id_i = int(current_proxy_lease_id)
            if current_proxy_lease_id_i != lease_id:
                stale_lease_ids.add(current_proxy_lease_id_i)
        except Exception:
            pass
    try:
        all_leases = await _ppool_list_all_for_cleanup(db_path=TPILOT_DB_PATH)
        for other in all_leases:
            other_id = other.get("id")
            if other_id is None or int(other_id) == lease_id:
                continue
            if str(other.get("manager_key") or "").strip() == manager_key:
                stale_lease_ids.add(int(other_id))
    except Exception:
        pass

    for stale_id in stale_lease_ids:
        try:
            await _ppool_unassign_lease(stale_id, db_path=TPILOT_DB_PATH)
        except Exception:
            pass
    # --- end Stage 6 P3.1 consistency fix --------------------------------

    # PROXY USAGE DETECTION 20260711: under multi, keep the lease's own
    # CURRENT owner unchanged (link_lease=False) only when one actually
    # exists -- a genuinely FREE lease (old_manager_key is None) has no
    # prior owner to protect, so linking the new manager as its tracked
    # owner is safe and avoids leaving the lease permanently ownerless in
    # the pool even though it is now in active use.
    link_lease = (not multi) or (old_manager_key is None)
    result = await _pbuy_apply_lease_to_manager(lease, manager_key, source="panel_pool_assign", link_lease=link_lease)
    if result.get("ok"):
        result["old_manager_key"] = old_manager_key if (old_manager_key != manager_key and not multi) else None
        result["multi_assigned"] = multi
        if stale_lease_ids:
            result["freed_lease_ids"] = sorted(stale_lease_ids)
        lease_after = await _ppool_lease_get(lease_id, db_path=TPILOT_DB_PATH)
        usage_map_after = await _ppool_manager_usage_map()
        status_after, _ = await _ppool_derive_status(lease_after or {}, usage_map=usage_map_after)
        result["status"] = status_after
    return _pbuy_json.dumps(result, ensure_ascii=False)


async def _handle_proxy_pool_unassign_command(args: str) -> str:
    """Detach a lease from its manager, keeping it in the pool. Never
    deletes the lease, never touches the provider's own proxy. Returns
    ok=True with old_manager_key even if the lease had no manager (no-op
    unassign is not an error)."""
    try:
        lease_id = int(str(args or "").strip().split()[0])
    except Exception:
        return _pbuy_json.dumps({"ok": False, "error": "bad_args", "message": "Пустой или некорректный lease_id"}, ensure_ascii=False)

    from storage import proxy_lease_get as _ppool_lease_get, proxy_lease_unassign as _ppool_unassign_lease

    lease = await _ppool_lease_get(lease_id, db_path=TPILOT_DB_PATH)
    if not lease:
        return _pbuy_json.dumps({"ok": False, "error": "lease_not_found", "message": f"Lease не найден: {lease_id}"}, ensure_ascii=False)

    old_manager_key = str(lease.get("manager_key") or "").strip() or None

    unassigned = await _ppool_unassign_lease(lease_id, db_path=TPILOT_DB_PATH)
    if not unassigned:
        return _pbuy_json.dumps({"ok": False, "error": "unassign_failed", "message": f"Не удалось отвязать lease {lease_id}."}, ensure_ascii=False)

    if old_manager_key:
        old_manager_row = await _tpag_registry_get(old_manager_key)
        if old_manager_row:
            try:
                await _ppool_disable_manager_proxy_fields(old_manager_key)
            except Exception:
                pass

    return _pbuy_json.dumps({"ok": True, "lease_id": lease_id, "old_manager_key": old_manager_key}, ensure_ascii=False)

# --- TPILOT PROXY POOL STAGE6 P3 END ---


# --- TPILOT PROXY POOL STAGE6 P4 (check / sync) START ---
# Controller-side only. /proxy_pool_check hits Proxy-Seller's tools/proxy/
# check endpoint (read-only liveness check, NOT a spend endpoint) and
# records the result. /proxy_pool_sync hits reference-free list_proxies
# (read-only, no order_id -> full account list) and idempotently upserts
# into the local pool via storage.proxy_lease_upsert_from_provider (P1),
# keyed by provider_proxy_id, never touching manager_key/status. NEITHER
# command ever calls order/make, prolong/make, calc_ipv4, or passes
# allow_spend=True -- allow_spend=True remains exactly where it was
# before this stage (buy-confirm, renew-confirm).

def _ppool_extract_check_info(data: Any) -> Dict[str, Any]:
    """Best-effort extraction of validity/protocol/time/ip from a
    tools/proxy/check response. The real response shape has not been
    verified against live traffic -- defensive digging only, never
    guesses when nothing is recognized, never raises."""
    out: Dict[str, Any] = {"valid": None, "protocol": None, "time": None, "ip": None}

    def _dig(node: Any) -> None:
        if isinstance(node, dict):
            for k, v in node.items():
                kl = str(k).lower()
                if kl in ("valid", "is_valid", "isvalid") and out["valid"] is None and isinstance(v, bool):
                    out["valid"] = v
                elif kl in ("protocol", "proto", "scheme") and out["protocol"] is None and not isinstance(v, (dict, list)):
                    out["protocol"] = v
                elif kl in ("time", "response_time", "responsetime", "latency", "ping") and out["time"] is None and not isinstance(v, (dict, list)):
                    out["time"] = v
                elif kl in ("ip", "external_ip", "externalip", "proxy_ip", "proxyip") and out["ip"] is None and not isinstance(v, (dict, list)):
                    out["ip"] = v
                else:
                    _dig(v)
        elif isinstance(node, (list, tuple)):
            for item in node:
                _dig(item)

    try:
        _dig(data)
    except Exception:
        pass
    return out


async def _handle_proxy_pool_check_command(args: str) -> str:
    """Check one pool lease's liveness with a LOCAL server-side SOCKS5
    connectivity check (read-only, no spend, no provider call) and record
    the result via storage.proxy_lease_update_check. Never buys, never
    renews. The returned JSON never includes the raw proxy string, login,
    or password -- only booleans/scrubbed text.

    LOCAL PROXY CHECK 20260711: Proxy-Seller's tools/proxy/check endpoint
    proved unreliable for our SOCKS5 leases -- live diagnosis returned
    errors=[{"message": "Empty result!", ...}] for every tested request
    shape/method, even though the proxy itself works. Replaced with the
    same local connectivity check the existing auth guard already runs
    (_tpag_v4_proxy_geo_via_socks: a real PySocks SOCKS5 connect + a plain
    HTTP GET to ip-api.com through the tunnel). Tries socks5h (rdns=True,
    DNS resolved through the proxy) first, then falls back to socks5
    (rdns=False, DNS resolved locally) -- mirrors the live diagnostic that
    proved both modes work for this provider's leases. provider.check_proxy
    is no longer called from this command at all."""
    try:
        lease_id = int(str(args or "").strip().split()[0])
    except Exception:
        return _pbuy_json.dumps({"ok": False, "error": "bad_args", "message": "Пустой или некорректный lease_id"}, ensure_ascii=False)

    from storage import proxy_lease_get as _ppool_lease_get, proxy_lease_update_check as _ppool_update_check

    lease = await _ppool_lease_get(lease_id, db_path=TPILOT_DB_PATH)
    if not lease:
        return _pbuy_json.dumps({"ok": False, "error": "lease_not_found", "message": f"Lease не найден: {lease_id}"}, ensure_ascii=False)

    host = str(lease.get("host") or "").strip()
    port = lease.get("port")
    if not host or not port:
        return _pbuy_json.dumps({"ok": False, "error": "unparseable_proxy", "message": f"У lease #{lease_id} не задан host/port."}, ensure_ascii=False)

    login = str(lease.get("login") or "").strip()
    password = str(lease.get("password") or "").strip()

    check_ok = False
    info: Dict[str, Any] = {}
    method = ""
    last_exc: Optional[Exception] = None
    for method_name, rdns in (("socks5h", True), ("socks5", False)):
        try:
            geo, ms = await _pbuy_call(_tpag_v4_proxy_geo_via_socks, host, int(port), login, password, rdns=rdns)
        except Exception as e:
            last_exc = e
            continue
        if geo.get("ip"):
            check_ok = True
            method = method_name
            info = {"protocol": method, "time": f"{ms} ms", "ip": geo.get("ip")}
            break

    if check_ok:
        status_text = f"ok, IP {info.get('ip')} ({method})"
    else:
        try:
            reason = _tpag_classify_error_reason(last_exc) if last_exc is not None else ""
        except Exception:
            reason = ""
        status_text = str(reason or "connection failed")[:200]

    try:
        await _ppool_update_check(lease_id, ok=check_ok, status_text=status_text, db_path=TPILOT_DB_PATH)
    except Exception:
        pass

    return _pbuy_json.dumps({
        "ok": True,
        "lease_id": lease_id,
        "check_ok": check_ok,
        "message": status_text,
        "protocol": info.get("protocol"),
        "time": info.get("time"),
        "ip": info.get("ip"),
    }, ensure_ascii=False)


# --- PROXY RENEWAL RELIABILITY R5c (shared pool-sync upsert) 20260808 START ---
async def _ppool_sync_entries_to_pool(entries: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Idempotent upsert of a provider list_proxies extraction into the
    local pool, keyed by provider_proxy_id via
    storage.proxy_lease_upsert_from_provider (P1) -- never overwrites
    manager_key/status, never deletes a local lease absent from `entries`.
    Extracted (R5c) from _handle_proxy_pool_sync_command so the periodic
    reconcile loop can refresh expires_at/host/port too (previously only a
    manual /proxy_pool_sync tap did this -- a lease that went unverified or
    otherwise fell out of sync stayed stale until an admin noticed). Pure
    storage; never calls the provider itself (caller already has `entries`)."""
    from storage import (
        proxy_lease_upsert_from_provider as _ppool_upsert,
        proxy_lease_get_by_provider_proxy_id as _ppool_get_by_pid,
    )

    created_count = 0
    updated_count = 0
    skipped_count = 0
    skipped_reasons: List[str] = []

    for entry in entries or []:
        provider_proxy_id = entry.get("provider_proxy_id")
        host = str(entry.get("host") or "").strip()
        port_raw = entry.get("port")
        if not provider_proxy_id or not host or port_raw in (None, ""):
            skipped_count += 1
            if len(skipped_reasons) < 10:
                skipped_reasons.append("пропущен: нет provider_proxy_id/host/port")
            continue
        try:
            port_i = int(str(port_raw).strip())
        except Exception:
            skipped_count += 1
            if len(skipped_reasons) < 10:
                skipped_reasons.append(f"пропущен provider_proxy_id={provider_proxy_id}: нечитаемый port")
            continue

        try:
            existing = await _ppool_get_by_pid("proxy_seller", str(provider_proxy_id), db_path=TPILOT_DB_PATH)
            await _ppool_upsert(
                provider_type="proxy_seller",
                provider_proxy_id=str(provider_proxy_id),
                host=host,
                port=port_i,
                login=entry.get("login"),
                password=entry.get("password"),
                scheme="socks5",
                proxy_type=_PBUY_PROXY_TYPE,
                provider_order_id=str(entry.get("order_id")) if entry.get("order_id") is not None else None,
                expires_at=str(entry.get("expires_at")) if entry.get("expires_at") else None,
                db_path=TPILOT_DB_PATH,
            )
            if existing:
                updated_count += 1
            else:
                created_count += 1
        except Exception as e:
            skipped_count += 1
            if len(skipped_reasons) < 10:
                skipped_reasons.append(_pbuy_safe_error(e))

    return {
        "total_seen": len(entries or []),
        "created_count": created_count,
        "updated_count": updated_count,
        "skipped_count": skipped_count,
        "skipped_reasons": skipped_reasons,
    }
# --- PROXY RENEWAL RELIABILITY R5c (shared pool-sync upsert) 20260808 END ---


async def _handle_proxy_pool_sync_command(args: str) -> str:
    """Sync the local pool from the provider's own proxy list
    (list_proxies with no order_id -> the FULL account list, read-only).
    Idempotent upsert keyed by provider_proxy_id via
    storage.proxy_lease_upsert_from_provider (P1) -- never overwrites
    manager_key/status, never deletes a local lease absent from this
    response. Never calls order/make or prolong/make; never passes
    allow_spend=True."""
    provider = _pbuy_provider()
    if provider is None:
        return _pbuy_json.dumps({"ok": False, "error": "not_configured", "message": "Proxy-Seller API key не настроен"}, ensure_ascii=False)

    try:
        lst = await _pbuy_call(provider.list_proxies, _PBUY_PROXY_TYPE)
    except Exception as e:
        return _pbuy_json.dumps({"ok": False, "error": "list_proxies_failed", "message": _pbuy_safe_error(e)}, ensure_ascii=False)

    from proxy_provider import extract_proxy_entries

    entries = extract_proxy_entries(lst)
    sync_summary = await _ppool_sync_entries_to_pool(entries)

    # PROXY LIFECYCLE SYNC 20260721: bidirectional desired-vs-observed
    # reconciliation, using the SAME provider read this sync already made
    # (no second call). Read-only against the provider; writes only local
    # lifecycle_status/desired/observed + audit + (on an actual state change)
    # an AdminBot notification. Never calls order/make or prolong/make.
    try:
        lifecycle_summary = await _plc_reconcile_all(entries)
    except Exception as e:
        lifecycle_summary = {"error": _pbuy_safe_error(e)}

    return _pbuy_json.dumps({
        "ok": True,
        "total_seen": sync_summary["total_seen"],
        "created_count": sync_summary["created_count"],
        "updated_count": sync_summary["updated_count"],
        "skipped_count": sync_summary["skipped_count"],
        "skipped_reasons": sync_summary["skipped_reasons"],
        "lifecycle": lifecycle_summary,
    }, ensure_ascii=False)


_PPOOL_PREV_PANEL_EXEC = globals().get("_panel_execute_command_text")


async def _panel_execute_command_text(  # type: ignore[override]
    command_text: str, *, requested_by: int = 0
) -> dict:
    """Stage 6 P2/P3/P4: route the Proxy Pool commands before chaining to
    the previous (Stage 5) handler. P2 (list/card) is read-only; P3
    (assign/unassign) writes storage + runs the guard; P4 (check/sync)
    hits read-only provider endpoints (tools/proxy/check, list_proxies)
    and writes storage. None of P2/P3/P4 ever spends or passes
    allow_spend=True."""
    cmd, _, args = str(command_text or "").strip().partition(" ")
    args = args.strip()
    if cmd == "/proxy_pool_list":
        try:
            result_text = await _handle_proxy_pool_list_command(args)
        except Exception as exc:
            result_text = _pbuy_json.dumps({"ok": False, "error": "internal_error", "message": _pbuy_safe_error(exc)}, ensure_ascii=False)
        return {"ok": True, "result_text": result_text}
    if cmd == "/proxy_pool_card":
        try:
            result_text = await _handle_proxy_pool_card_command(args)
        except Exception as exc:
            result_text = _pbuy_json.dumps({"ok": False, "error": "internal_error", "message": _pbuy_safe_error(exc)}, ensure_ascii=False)
        return {"ok": True, "result_text": result_text}
    if cmd == "/proxy_pool_assign":
        try:
            result_text = await _handle_proxy_pool_assign_command(args)
        except Exception as exc:
            result_text = _pbuy_json.dumps({"ok": False, "error": "internal_error", "message": _pbuy_safe_error(exc)}, ensure_ascii=False)
        return {"ok": True, "result_text": result_text}
    if cmd == "/proxy_pool_unassign":
        try:
            result_text = await _handle_proxy_pool_unassign_command(args)
        except Exception as exc:
            result_text = _pbuy_json.dumps({"ok": False, "error": "internal_error", "message": _pbuy_safe_error(exc)}, ensure_ascii=False)
        return {"ok": True, "result_text": result_text}
    if cmd == "/proxy_pool_check":
        try:
            result_text = await _handle_proxy_pool_check_command(args)
        except Exception as exc:
            result_text = _pbuy_json.dumps({"ok": False, "error": "internal_error", "message": _pbuy_safe_error(exc)}, ensure_ascii=False)
        return {"ok": True, "result_text": result_text}
    if cmd == "/proxy_pool_sync":
        try:
            result_text = await _handle_proxy_pool_sync_command(args)
        except Exception as exc:
            result_text = _pbuy_json.dumps({"ok": False, "error": "internal_error", "message": _pbuy_safe_error(exc)}, ensure_ascii=False)
        return {"ok": True, "result_text": result_text}
    if callable(_PPOOL_PREV_PANEL_EXEC):
        return await _PPOOL_PREV_PANEL_EXEC(command_text, requested_by=requested_by)
    return {"ok": False, "result_text": f"Команда не поддерживается: {cmd}"}

# --- TPILOT PROXY POOL STAGE6 P4 END ---


# --- TPILOT DELETED MANAGER STATS BACKFILL 20260711 START ---
# One-off/repeatable admin backfill: creates a manager_stats_tombstones row for a
# manager that was hard-deleted BEFORE the tombstone feature existed (e.g. dariass),
# by reading identity + timing from what's still on disk/in the central DB. Purely
# additive and idempotent: never touches managers, manager_reserve_pairs, or any
# backup file/folder; only ever writes new rows to manager_stats_tombstones (via the
# existing manager_stats_tombstone_upsert/_get helpers). Safe to run any number of
# times -- a manager that already has a tombstone is skipped, not overwritten.

import re as _mgrbf_re


def _tp_mgrbf_scan_backup_candidates(manager_key: str, *, base_dir: Optional[str] = None) -> List[Tuple[str, datetime]]:
    """Find every _deleted_managers_backup/<key>_<ts>/<key>.db for this manager,
    newest first. deleted_at is parsed from the folder's <ts> suffix
    (YYYYMMDD_HHMMSS, matching _panel_manager_delete_full_command's own naming);
    falls back to the .db file's mtime if the suffix is not parseable. Read-only:
    only Path.glob/.stat, never writes or moves anything."""
    key = registry_normalize_manager_key(manager_key)
    if not key:
        return []
    backup_root = Path(base_dir or BASE_DIR) / "_deleted_managers_backup"
    if not backup_root.exists():
        return []
    out: List[Tuple[str, datetime]] = []
    try:
        for folder in backup_root.glob(f"{key}_*"):
            if not folder.is_dir():
                continue
            db_file = folder / f"{key}.db"
            if not db_file.exists():
                continue
            suffix = folder.name[len(key) + 1:]
            deleted_at: Optional[datetime] = None
            try:
                deleted_at = datetime.strptime(suffix, "%Y%m%d_%H%M%S")
            except Exception:
                deleted_at = None
            if deleted_at is None:
                try:
                    deleted_at = datetime.utcfromtimestamp(db_file.stat().st_mtime)
                except Exception:
                    deleted_at = _tp_utc_now()
            out.append((str(db_file), deleted_at))
    except Exception:
        return []
    out.sort(key=lambda c: c[1], reverse=True)
    return out


async def _tp_mgrbf_identity_from_sources(manager_key: str, backup_db_path: str, *, central_db_path: Optional[str] = None) -> Dict[str, str]:
    """Resolve display_name/telegram_username/source_key for a backfilled tombstone:
    1) latest central partner_lead_events snapshot for this manager_key (authoritative
       -- the same frozen columns the live full-delete path already trusts);
    2) fallback: the backup per-manager DB's own daily_leads.manager_username;
    3) fallback: the bare manager_key.
    Read-only throughout -- never writes to either database."""
    key = registry_normalize_manager_key(manager_key)
    display_name = ""
    telegram_username = ""
    source_key = ""
    try:
        async with aiosqlite.connect(str(central_db_path or TPILOT_DB_PATH)) as db:
            cur = await db.execute(
                "SELECT manager_display_name, manager_username, source_key FROM partner_lead_events "
                "WHERE manager_key=? ORDER BY id DESC LIMIT 1",
                (key,),
            )
            row = await cur.fetchone()
            if row:
                display_name = str(row[0] or "")
                telegram_username = str(row[1] or "")
                source_key = str(row[2] or "")
    except Exception:
        pass
    if not telegram_username and backup_db_path and os.path.exists(backup_db_path):
        try:
            async with aiosqlite.connect(backup_db_path) as db:
                cur = await db.execute(
                    "SELECT manager_username FROM daily_leads WHERE manager_key=? "
                    "AND COALESCE(manager_username,'')<>'' ORDER BY id DESC LIMIT 1",
                    (key,),
                )
                row = await cur.fetchone()
                if row:
                    telegram_username = str(row[0] or "")
        except Exception:
            pass
    if not display_name:
        display_name = key
    return {"display_name": display_name, "telegram_username": telegram_username, "source_key": source_key}


async def _tp_mgrbf_backfill_one(manager_key: str, *, retention_days: int = 60) -> Dict[str, Any]:
    """Backfill a single manager's tombstone from disk/central-DB evidence, if (and
    only if) no tombstone already exists for it -- idempotent, safe to re-run.
    Never touches managers, manager_reserve_pairs, backup folders, or the backup
    per-manager DB (read-only there). Returns a status dict for command rendering."""
    key = registry_normalize_manager_key(manager_key)
    if not key:
        return {"manager_key": str(manager_key or ""), "status": "invalid_key"}
    try:
        from storage import manager_stats_tombstone_get as _tomb_get
        existing = _tomb_get(key, db_path=TPILOT_DB_PATH)
    except Exception as e:
        return {"manager_key": key, "status": "error", "error": repr(e)}
    if existing:
        return {"manager_key": key, "status": "skipped_existing"}
    candidates = _tp_mgrbf_scan_backup_candidates(key)
    if not candidates:
        return {"manager_key": key, "status": "no_backup_found"}
    backup_db_path, deleted_at = candidates[0]
    identity = await _tp_mgrbf_identity_from_sources(key, backup_db_path)
    try:
        from storage import manager_stats_tombstone_upsert as _tomb_upsert
        ok = bool(_tomb_upsert(
            key,
            display_name=identity["display_name"],
            telegram_username=identity["telegram_username"],
            manager_db_path=backup_db_path,
            source_key=identity["source_key"],
            deleted_at=deleted_at.replace(microsecond=0).isoformat(),
            retention_days=retention_days,
            db_path=TPILOT_DB_PATH,
        ))
    except Exception as e:
        return {"manager_key": key, "status": "error", "error": repr(e)}
    return {
        "manager_key": key,
        "status": "created" if ok else "error",
        "db_path": backup_db_path,
        "deleted_at": deleted_at.replace(microsecond=0).isoformat(),
        "display_name": identity["display_name"],
        "telegram_username": identity["telegram_username"],
        "source_key": identity["source_key"],
    }


async def _tp_mgrbf_backfill_all(*, retention_days: int = 60, base_dir: Optional[str] = None) -> List[Dict[str, Any]]:
    """Scan every _deleted_managers_backup/<key>_<ts>/ folder and backfill a
    tombstone for each manager_key that doesn't already have one. Idempotent."""
    backup_root = Path(base_dir or BASE_DIR) / "_deleted_managers_backup"
    results: List[Dict[str, Any]] = []
    if not backup_root.exists():
        return results
    seen_keys: set = set()
    try:
        folders = sorted(backup_root.iterdir())
    except Exception:
        return results
    for folder in folders:
        if not folder.is_dir():
            continue
        m = _mgrbf_re.match(r"^(.+)_\d{8}_\d{6}$", folder.name)
        if not m:
            continue
        key = registry_normalize_manager_key(m.group(1))
        if not key or key in seen_keys:
            continue
        seen_keys.add(key)
        results.append(await _tp_mgrbf_backfill_one(key, retention_days=retention_days))
    return results


_MGRBF_PREV_PANEL_EXEC = globals().get("_panel_execute_command_text")


async def _panel_execute_command_text(  # type: ignore[override]
    command_text: str, *, requested_by: int = 0, source_chat_id: int = 0, response_chat_id: int = 0
) -> dict:
    """DELETED MANAGER STATS BACKFILL 20260711: /manager_stats_backfill <key|all> --
    admin panel command, non-destructive, idempotent backfill of
    manager_stats_tombstones for managers hard-deleted before this retention
    feature existed. Read-only against managers/manager_reserve_pairs/backup
    folders/backup per-manager DB; only ever writes new manager_stats_tombstones
    rows via the existing helper (never overwrites an existing tombstone)."""
    cmd, _, args = str(command_text or "").strip().partition(" ")
    args = args.strip()
    if cmd == "/manager_stats_backfill":
        if not args:
            return {"ok": False, "result_text": "Формат: /manager_stats_backfill <manager_key|all>"}
        if registry_normalize_manager_key(args) == "all":
            results = await _tp_mgrbf_backfill_all()
            if not results:
                return {"ok": True, "result_text": "Backup-папок для восстановления не найдено."}
            lines = [f"Проверено менеджеров: {len(results)}"]
            for r in results:
                lines.append(f"• {r.get('manager_key')}: {r.get('status')}")
            return {"ok": True, "result_text": "\n".join(lines)}
        result = await _tp_mgrbf_backfill_one(args)
        status = result.get("status")
        if status == "created":
            lines = [
                f"✅ Снимок статистики создан для {result.get('manager_key')}",
                f"Имя: {result.get('display_name')} | @{result.get('telegram_username') or '_'}",
                f"Источник: {result.get('source_key') or '_'}",
                f"Удалён: {result.get('deleted_at')}",
                f"БД: {result.get('db_path')}",
            ]
            return {"ok": True, "result_text": "\n".join(lines)}
        if status == "skipped_existing":
            return {"ok": True, "result_text": f"Снимок для {result.get('manager_key')} уже существует, ничего не изменено."}
        if status == "no_backup_found":
            return {"ok": True, "result_text": f"⚠️ Backup-папка для {result.get('manager_key')} не найдена в _deleted_managers_backup."}
        if status == "invalid_key":
            return {"ok": False, "result_text": "Некорректный manager_key."}
        return {"ok": False, "result_text": f"⚠️ Ошибка снимка для {result.get('manager_key')}: {result.get('error')}"}
    if callable(_MGRBF_PREV_PANEL_EXEC):
        try:
            return await _MGRBF_PREV_PANEL_EXEC(command_text, requested_by=requested_by, source_chat_id=source_chat_id, response_chat_id=response_chat_id)
        except TypeError:
            try:
                return await _MGRBF_PREV_PANEL_EXEC(command_text, requested_by=requested_by)
            except TypeError:
                return await _MGRBF_PREV_PANEL_EXEC(command_text)
    return {"ok": False, "result_text": f"Команда не поддерживается: {cmd}"}

# --- TPILOT DELETED MANAGER STATS BACKFILL 20260711 END ---


# --- TPILOT MANAGER RELOGIN 20260714 START ---
# Safe re-authorization of an EXISTING manager's Telegram .session ("🔐 Перезайти").
#
# Scope: replaces ONLY the Telegram .session file and the identity fields of the SAME
# managers row (tg_user_id, telegram_username, first_name, last_name, phone,
# last_login_at). Never creates a manager_key, never INSERTs into managers, never
# creates/recreates the manager DB or runtime directory, never touches
# source/proxy/schedule/roles/closer flag/settings/statistics/business links.
#
# Architecture: the ENTIRE phone -> code -> 2FA -> identity-check flow runs against a
# TEMPORARY session file (<key>.relogin.session), which has no SQLite lock conflict with
# the manager's boevoy runtime process (a different file) -- so the runtime keeps running
# throughout. Only after a fully successful sign_in + identity confirmation does
# _manager_relogin_commit stop the runtime, back up the old session, atomically
# os.replace the temp session onto the boevoy path, call the EXISTING
# _manager_finalize_login (updates identity fields + restarts the runtime), and clean up.
# Before that point the boevoy .session is never opened, never modified, never deleted.
#
# State: reuses the existing manager_onboarding table (one row per admin/owner_user_id,
# exactly like the add-manager flow) with a distinct 'relogin_*' step prefix so it can
# never collide with an in-progress add-manager onboarding for the same admin. Per-
# manager-key exclusivity (so two admins can't relogin the SAME manager concurrently) is
# enforced by scanning manager_list_pending() for any OTHER admin's non-expired
# relogin_* row on the same manager_key -- no new table, no schema migration.

_RELOGIN_STEP_PHONE = "relogin_phone"
_RELOGIN_STEP_CODE = "relogin_code"
_RELOGIN_STEP_PASS = "relogin_pass"
_RELOGIN_STEP_IDENTITY_CONFIRM = "relogin_identity_confirm"
_RELOGIN_STEP_READY_COMMIT = "relogin_ready_commit"
_RELOGIN_STEPS = {
    _RELOGIN_STEP_PHONE, _RELOGIN_STEP_CODE, _RELOGIN_STEP_PASS,
    _RELOGIN_STEP_IDENTITY_CONFIRM, _RELOGIN_STEP_READY_COMMIT,
}

# Marker lines: the only channel between this controller and panel_bot.py for these two
# outcomes (mirrors the existing _ONBOARDING_SOURCE_PICK_MARKER convention -- a plain
# text marker in result_text, never a shared Python object, since the two run as
# separate processes talking only through panel_commands).
_RELOGIN_IDENTITY_MISMATCH_MARKER = "⚠️ RELOGIN_IDENTITY_MISMATCH"
_RELOGIN_COMMIT_OK_MARKER = "✅ RELOGIN_COMMIT_OK"


def _manager_relogin_temp_session_path(key: str) -> str:
    key = registry_normalize_manager_key(key or "")
    paths = _manager_runtime_paths_for_key(key)
    return os.path.join(paths["root"], f"{key}.relogin.session")


def _manager_relogin_cleanup_temp_files(key: str) -> None:
    """Removes ONLY this manager's temporary relogin session + its sidecar journal.
    Never touches the boevoy .session. Best-effort, never raises."""
    temp_path = _manager_relogin_temp_session_path(key)
    for fp in (temp_path, temp_path + "-journal"):
        try:
            if os.path.exists(fp):
                os.remove(fp)
        except Exception:
            pass


async def _manager_relogin_cleanup_state(key: str, owner_user_id: int) -> None:
    _manager_relogin_cleanup_temp_files(key)
    try:
        await manager_delete_onboarding(int(owner_user_id or 0))
    except Exception:
        pass


async def _manager_relogin_active_owner(key: str, *, exclude_owner: int = 0) -> int:
    """Returns the owner_user_id of ANOTHER admin's non-expired relogin_* onboarding row
    for this manager_key, or 0 if none. The SAME admin (exclude_owner) continuing their
    own flow is never blocked by this. Opportunistically clears any relogin_* row (for
    any manager_key) it finds already expired, including that manager's temp files."""
    key = registry_normalize_manager_key(key or "")
    now = _now_utc_iso()
    try:
        rows = await manager_list_pending()
    except Exception:
        return 0
    active_owner = 0
    for row in rows:
        step = str(row.get("step") or "")
        if step not in _RELOGIN_STEPS:
            continue
        row_key = registry_normalize_manager_key(row.get("manager_key") or "")
        owner = int(row.get("owner_user_id") or 0)
        expires_at = str(row.get("expires_at") or "")
        if expires_at and expires_at < now:
            try:
                await manager_delete_onboarding(owner)
            except Exception:
                pass
            _manager_relogin_cleanup_temp_files(row_key)
            continue
        if row_key == key and owner and owner != int(exclude_owner or 0):
            active_owner = owner
    return active_owner


async def _manager_relogin_begin(key: str, owner_user_id: int) -> Tuple[bool, str, Optional[Dict[str, Any]]]:
    """'Re-login start' checklist: validate key/row, reject archived/deleted, enforce the
    per-manager-key lock. Never touches the boevoy session, never stops the runtime."""
    ok_key, err_key, key = validate_manager_key(key)
    if not ok_key:
        return False, (err_key or "Некорректный manager_key."), None
    row = await manager_get(key)
    if not row:
        return False, f"Менеджер не найден: {key}", None
    status = str(row.get("status") or "").strip().lower()
    if status in ("archived", "deleted"):
        return False, f"Менеджер архивирован/удалён, повт��рный вход недоступен: {key}", None
    other_owner = await _manager_relogin_active_owner(key, exclude_owner=owner_user_id)
    if other_owner:
        return False, f"Повторный вход для {key} уже выполняется другим администратором. Попробуйте позже.", None
    # Stage 3 reverse mutual exclusion: relogin re-authenticates the SAME
    # manager_key/session; a replacement operation for the same old key is
    # building a completely different new session in parallel -- letting
    # both run at once would race on the old manager's identity. Only
    # non-terminal replacement operations block (replacement_active_for_
    # old_key already excludes done/failed/cancelled).
    if await replacement_active_for_old_key(key):
        return False, "Сначала завершите или отмените текущую замену аккаунта.", None
    return True, "", row


async def _panel_manager_relogin_phone_command(args: str, *, requested_by: int = 0) -> str:
    parts = str(args or "").strip().split(None, 1)
    key = registry_normalize_manager_key(parts[0] if parts else "")
    phone = str(parts[1] if len(parts) > 1 else "").strip()
    if not key or not phone:
        return "Формат: /manager_relogin_phone <manager_key> <телефон>"
    owner = int(requested_by or 0)
    ok, err, row = await _manager_relogin_begin(key, owner)
    if not ok:
        return err
    temp_path = _manager_relogin_temp_session_path(key)
    _, _, api_profile_name = _api_profile_for("onboarding")
    _manager_auth_audit_log("relogin_send_code_start", key, phone_masked=mask_phone(phone), api_profile=api_profile_name, admin_user_id=owner)
    temp_client = None
    try:
        temp_client = _build_manager_telegram_client_from_row(dict(row), temp_path, source="onboarding")
        await temp_client.connect()
        sent = await temp_client.send_code_request(phone)
        phone_code_hash = str(getattr(sent, "phone_code_hash", "") or "")
        if not phone_code_hash:
            raise RuntimeError("empty_phone_code_hash")
        expires_at = _future_iso(MANAGER_ONBOARD_TIMEOUT_SEC)
        await manager_save_onboarding(
            owner, manager_key=key, step=_RELOGIN_STEP_CODE,
            phone=phone, phone_code_hash=phone_code_hash,
            tmp_session_path=temp_path, expires_at=expires_at,
        )
        _manager_auth_audit_log("relogin_send_code_finish", key, ok=1, api_profile=api_profile_name, admin_user_id=owner)
        return "✅ Код отправлен. Введите код Telegram одним сообщением."
    except Exception as e:
        if _manager_is_rate_limit_error(e):
            wait_sec = _manager_extract_wait_seconds(e, MANAGER_PHONE_COOLDOWN_SEC)
            _manager_auth_audit_log("relogin_send_code_finish", key, ok=0, api_profile=api_profile_name, admin_user_id=owner, error_class=e.__class__.__name__, rate_limited=1)
            return f"Telegram временно ограничил запросы кода. Повторите примерно через {wait_sec} сек."
        _manager_auth_audit_log("relogin_send_code_finish", key, ok=0, api_profile=api_profile_name, admin_user_id=owner, error_class=e.__class__.__name__)
        return _map_send_code_error(e)
    finally:
        if temp_client is not None:
            try:
                await temp_client.disconnect()
            except Exception:
                pass


async def _manager_relogin_after_signin(key: str, owner_user_id: int, temp_client) -> str:
    """Shared post-sign_in handling for both the code and 2FA paths: verify the temp
    session is genuinely authorized, fetch Telegram identity, then either auto-commit
    (tg_user_id matches or is not yet known) or return the identity-mismatch marker text
    for PanelBot to render the confirm/cancel screen. Always disconnects temp_client."""
    key = registry_normalize_manager_key(key or "")
    try:
        authorized = await temp_client.is_user_authorized()
        me = await temp_client.get_me() if authorized else None
    except Exception as e:
        _manager_auth_audit_log("relogin_post_signin_error", key, admin_user_id=owner_user_id, error_class=e.__class__.__name__)
        try:
            await temp_client.disconnect()
        except Exception:
            pass
        return f"Ошибка проверки входа: {e!r}"
    try:
        await temp_client.disconnect()
    except Exception:
        pass
    if not authorized or me is None:
        return "❌ Временная сессия не авторизована после входа. Начните заново."

    actual_user_id = int(getattr(me, "id", 0) or 0)
    actual_username = str(getattr(me, "username", None) or "")
    actual_first = str(getattr(me, "first_name", None) or "")
    actual_last = str(getattr(me, "last_name", None) or "")
    row = await manager_get(key)
    if not row:
        await _manager_relogin_cleanup_state(key, owner_user_id)
        return f"Менеджер не найден: {key}"
    expected_user_id = int(row.get("tg_user_id") or 0)
    _manager_auth_audit_log(
        "relogin_signin_ok", key, admin_user_id=owner_user_id,
        expected_user_id=expected_user_id or "_", actual_user_id=actual_user_id or "_",
    )
    if expected_user_id and expected_user_id != actual_user_id:
        expires_at = _future_iso(MANAGER_ONBOARD_TIMEOUT_SEC)
        await manager_save_onboarding(
            owner_user_id, manager_key=key, step=_RELOGIN_STEP_IDENTITY_CONFIRM,
            tmp_session_path=_manager_relogin_temp_session_path(key), expires_at=expires_at,
        )
        lines = [
            _RELOGIN_IDENTITY_MISMATCH_MARKER,
            f"MANAGER_KEY={key}",
            f"EXPECTED_ID={expected_user_id}",
            f"ACTUAL_ID={actual_user_id or '_'}",
            f"ACTUAL_USERNAME={actual_username or '-'}",
            f"ACTUAL_FIRST_NAME={actual_first or '-'}",
            f"ACTUAL_LAST_NAME={actual_last or '-'}",
        ]
        return "\n".join(lines)
    return await _manager_relogin_commit(key, owner_user_id, phone_hint=str(row.get("phone") or ""))


async def _panel_manager_relogin_code_command(args: str, *, requested_by: int = 0) -> str:
    parts = str(args or "").strip().split(None, 1)
    key = registry_normalize_manager_key(parts[0] if parts else "")
    code = re.sub(r"\D+", "", str(parts[1] if len(parts) > 1 else "").strip())
    if not key or not code:
        return "Введите код Telegram цифрами."
    owner = int(requested_by or 0)
    onboarding = await manager_get_onboarding(owner)
    if (not onboarding or registry_normalize_manager_key(onboarding.get("manager_key") or "") != key
            or str(onboarding.get("step") or "") != _RELOGIN_STEP_CODE):
        return "Нет активного повторного входа, ожидающего код. Начните заново через карточку менеджера."
    phone = str(onboarding.get("phone") or "").strip()
    phone_code_hash = str(onboarding.get("phone_code_hash") or "").strip()
    if not phone or not phone_code_hash:
        return "Не найден активный запрос кода. Начните заново."
    temp_path = _manager_relogin_temp_session_path(key)
    row = await manager_get(key)
    if not row:
        await _manager_relogin_cleanup_state(key, owner)
        return f"Менеджер не найден: {key}"
    temp_client = None
    try:
        temp_client = _build_manager_telegram_client_from_row(dict(row), temp_path, source="onboarding")
        await temp_client.connect()
        await temp_client.sign_in(phone=phone, code=code, phone_code_hash=phone_code_hash)
        _manager_auth_audit_log("relogin_sign_in_code", key, admin_user_id=owner, ok=1)
        return await _manager_relogin_after_signin(key, owner, temp_client)
    except SessionPasswordNeededError:
        expires_at = _future_iso(MANAGER_ONBOARD_TIMEOUT_SEC)
        await manager_save_onboarding(
            owner, manager_key=key, step=_RELOGIN_STEP_PASS,
            phone=phone, phone_code_hash=phone_code_hash,
            tmp_session_path=temp_path, expires_at=expires_at,
        )
        _manager_auth_audit_log("relogin_sign_in_code", key, admin_user_id=owner, ok=0, error_class="SessionPasswordNeededError")
        return "Нужен пароль 2FA. Введите пароль одним сообщением."
    except (PhoneCodeInvalidError, PhoneCodeExpiredError) as e:
        _manager_auth_audit_log("relogin_sign_in_code", key, admin_user_id=owner, ok=0, error_class=e.__class__.__name__)
        return "Код неверный или истёк. Нажмите «📱 Войти по номеру и коду» ещё раз, чтобы запросить новый код."
    except Exception as e:
        _manager_auth_audit_log("relogin_sign_in_code", key, admin_user_id=owner, ok=0, error_class=e.__class__.__name__, error_repr=repr(e)[:300])
        return f"Ошибка входа по коду: {e!r}"
    finally:
        if temp_client is not None:
            try:
                await temp_client.disconnect()
            except Exception:
                pass


async def _panel_manager_relogin_pass_command(args: str, *, requested_by: int = 0) -> str:
    parts = str(args or "").strip().split(None, 1)
    key = registry_normalize_manager_key(parts[0] if parts else "")
    password = str(parts[1] if len(parts) > 1 else "").strip()
    if not key or not password:
        return "Введите пароль 2FA одним сообщением."
    owner = int(requested_by or 0)
    onboarding = await manager_get_onboarding(owner)
    if (not onboarding or registry_normalize_manager_key(onboarding.get("manager_key") or "") != key
            or str(onboarding.get("step") or "") != _RELOGIN_STEP_PASS):
        return "Нет активного повторного входа, ожидающего пароль 2FA. Начните заново через карточку менеджера."
    temp_path = _manager_relogin_temp_session_path(key)
    row = await manager_get(key)
    if not row:
        await _manager_relogin_cleanup_state(key, owner)
        return f"Менеджер не найден: {key}"
    temp_client = None
    try:
        temp_client = _build_manager_telegram_client_from_row(dict(row), temp_path, source="onboarding")
        await temp_client.connect()
        await temp_client.sign_in(password=password)
        _manager_auth_audit_log("relogin_sign_in_pass", key, admin_user_id=owner, ok=1)
        return await _manager_relogin_after_signin(key, owner, temp_client)
    except PasswordHashInvalidError:
        _manager_auth_audit_log("relogin_sign_in_pass", key, admin_user_id=owner, ok=0, error_class="PasswordHashInvalidError")
        return "Неверный пароль 2FA. Введите пароль ещё раз."
    except Exception as e:
        _manager_auth_audit_log("relogin_sign_in_pass", key, admin_user_id=owner, ok=0, error_class=e.__class__.__name__, error_repr=repr(e)[:300])
        return f"Ошибка входа по 2FA: {e!r}"
    finally:
        if temp_client is not None:
            try:
                await temp_client.disconnect()
            except Exception:
                pass


async def _panel_manager_relogin_confirm_command(args: str, *, requested_by: int = 0) -> str:
    key = registry_normalize_manager_key(str(args or "").strip())
    if not key:
        return "Формат: /manager_relogin_confirm <manager_key>"
    owner = int(requested_by or 0)
    onboarding = await manager_get_onboarding(owner)
    if (not onboarding or registry_normalize_manager_key(onboarding.get("manager_key") or "") != key
            or str(onboarding.get("step") or "") != _RELOGIN_STEP_IDENTITY_CONFIRM):
        return "Нет ожидающего подтверждения смены аккаунта. Начните заново через карточку менеджера."
    row = await manager_get(key)
    if not row:
        await _manager_relogin_cleanup_state(key, owner)
        return f"Менеджер не найден: {key}"
    return await _manager_relogin_commit(key, owner, phone_hint=str(row.get("phone") or ""))


async def _panel_manager_relogin_cancel_command(args: str, *, requested_by: int = 0) -> str:
    key = registry_normalize_manager_key(str(args or "").strip())
    if not key:
        return "Формат: /manager_relogin_cancel <manager_key>"
    owner = int(requested_by or 0)
    temp_path = _manager_relogin_temp_session_path(key)
    if os.path.exists(temp_path):
        row = await manager_get(key) or {}
        temp_client = None
        try:
            temp_client = _build_manager_telegram_client_from_row(dict(row), temp_path, source="onboarding")
            await temp_client.connect()
            if await temp_client.is_user_authorized():
                try:
                    await temp_client.log_out()
                except Exception:
                    pass
        except Exception:
            pass
        finally:
            if temp_client is not None:
                try:
                    await temp_client.disconnect()
                except Exception:
                    pass
    _manager_relogin_cleanup_temp_files(key)
    await manager_delete_onboarding(owner)
    _manager_auth_audit_log("relogin_cancel", key, admin_user_id=owner)
    return "Повторный вход отменён. Данные и текущая session не изменены."


async def _manager_relogin_commit(key: str, owner_user_id: int, *, phone_hint: str = "") -> str:
    """Atomic replace of an EXISTING manager's Telegram session. Called only after a
    successful sign_in on the TEMPORARY session and a passed/confirmed identity check.
    Never creates a manager, never inserts into managers, never creates/recreates the
    manager DB or runtime directory -- only replaces the .session file and, via the
    existing _manager_finalize_login, the identity fields of the SAME row."""
    key = registry_normalize_manager_key(key or "")
    row = await manager_get(key)
    if not row:
        await _manager_relogin_cleanup_state(key, owner_user_id)
        return f"Менеджер не найден: {key}. Замена отменена."
    status = str(row.get("status") or "").strip().lower()
    if status in ("archived", "deleted"):
        await _manager_relogin_cleanup_state(key, owner_user_id)
        return f"Менеджер архивирован/удалён, замена отменена: {key}."

    temp_path = _manager_relogin_temp_session_path(key)
    if not os.path.exists(temp_path):
        await _manager_relogin_cleanup_state(key, owner_user_id)
        return "Временная сессия не найдена. Начните заново."

    # Re-verify the temp session is genuinely authorized right before touching anything
    # boevoy -- a short-lived open/close, never left connected across the replace below.
    verify_client = None
    authorized = False
    me = None
    try:
        verify_client = _build_manager_telegram_client_from_row(dict(row), temp_path, source="onboarding")
        await verify_client.connect()
        authorized = await verify_client.is_user_authorized()
        me = await verify_client.get_me() if authorized else None
    except Exception as e:
        _manager_auth_audit_log("relogin_commit", key, admin_user_id=owner_user_id, ok=0, stage="verify", error_class=e.__class__.__name__)
        return f"Не удалось проверить временную сессию перед заменой: {e!r}"
    finally:
        if verify_client is not None:
            try:
                await verify_client.disconnect()
            except Exception:
                pass
    if not authorized or me is None:
        await _manager_relogin_cleanup_state(key, owner_user_id)
        _manager_auth_audit_log("relogin_commit", key, admin_user_id=owner_user_id, ok=0, stage="verify", reason="not_authorized")
        return "Временная сессия не авторизована. Начните заново."

    phone = str(getattr(me, "phone", "") or phone_hint or row.get("phone") or "")

    runtime_was_running = False
    try:
        runtime_was_running = await _manager_process_running(key)
    except Exception:
        runtime_was_running = False
    if runtime_was_running:
        try:
            await _stop_manager_process(key, silent=True)
        except Exception:
            pass
        try:
            await asyncio.sleep(2.0)  # let Windows release the .session file lock
        except Exception:
            pass

    backup_path = ""
    try:
        backup_path = await _backup_manager_session_files(key, "relogin")
        if not backup_path or not Path(backup_path).exists():
            raise RuntimeError("backup не создан")
    except Exception as e:
        if runtime_was_running:
            try:
                await _spawn_manager_process(key)
            except Exception:
                pass
        _manager_auth_audit_log("relogin_commit", key, admin_user_id=owner_user_id, ok=0, stage="backup", error_class=e.__class__.__name__)
        return f"⚠️ Backup не создан, замена отменена: {e!r}. Старая сессия и процесс не тронуты."

    paths = _manager_runtime_paths_for_key(key)
    boevoy_session = paths["session_path"]
    # Remove stale sidecars of the OLD boevoy session only now, after the backup exists.
    for suffix in ("-journal", "-wal", "-shm"):
        try:
            fp = boevoy_session + suffix
            if os.path.exists(fp):
                os.remove(fp)
        except Exception:
            pass

    try:
        os.replace(temp_path, boevoy_session)
    except Exception as e:
        # rollback: restore the boevoy session from the backup we just made.
        try:
            backup_session = Path(backup_path) / f"{key}.session"
            if backup_session.exists():
                shutil.copy2(str(backup_session), boevoy_session)
        except Exception:
            pass
        if runtime_was_running:
            try:
                await _spawn_manager_process(key)
            except Exception:
                pass
        _manager_relogin_cleanup_temp_files(key)
        _manager_auth_audit_log("relogin_commit", key, admin_user_id=owner_user_id, ok=0, stage="replace", error_class=e.__class__.__name__, backup_path=backup_path)
        return f"⚠️ Ошибка замены сессии: {e!r}. Старая сессия восстановлена из backup."

    # Temp session's own sidecar (if any) is no longer needed -- Telethon creates a fresh
    # one on next connect as usual.
    try:
        jp = temp_path + "-journal"
        if os.path.exists(jp):
            os.remove(jp)
    except Exception:
        pass

    try:
        finalize_text = await _manager_finalize_login(
            owner_user_id, key, phone, me,
            preserve_owner_user_id=True,
            preserve_runtime_state=True,
            spawn_after_login=runtime_was_running,
        )
        spawn_ok = "✅ Менеджер активирован и запущен" in finalize_text
    except Exception as e:
        _manager_auth_audit_log("relogin_commit", key, admin_user_id=owner_user_id, ok=0, stage="finalize", error_class=e.__class__.__name__, backup_path=backup_path)
        await _manager_relogin_cleanup_state(key, owner_user_id)
        return (
            "⚠️ Сессия заменена, но обновление карточки/запуск не завершились штатно: "
            f"{e!r}. Проверьте карточку менеджера, при необходимости запустите вручную."
        )

    await _manager_relogin_cleanup_state(key, owner_user_id)
    _manager_auth_audit_log(
        "relogin_commit", key, admin_user_id=owner_user_id, ok=1,
        backup_path=backup_path, spawn_ok=int(spawn_ok),
        actual_user_id=int(getattr(me, "id", 0) or 0),
    )
    try:
        await _log_manager_danger_action("relogin", key, owner_user_id, backup_path=backup_path, result="ok")
    except Exception:
        pass

    lines = [
        _RELOGIN_COMMIT_OK_MARKER,
        f"MANAGER_KEY={key}",
        f"SPAWN_OK={1 if spawn_ok else 0}",
        f"BACKUP_PATH={backup_path}",
    ]
    return "\n".join(lines)


_RELOGIN_PREV_PANEL_EXEC = globals().get("_panel_execute_command_text")


async def _panel_execute_command_text(  # type: ignore[override]
    command_text: str, *, requested_by: int = 0, source_chat_id: int = 0, response_chat_id: int = 0
) -> Dict[str, Any]:
    cmd, args = _parse_cmd(str(command_text or ""))
    if cmd == "/manager_relogin_phone":
        return {"ok": True, "result_text": await _panel_manager_relogin_phone_command(args, requested_by=requested_by)}
    if cmd == "/manager_relogin_code":
        return {"ok": True, "result_text": await _panel_manager_relogin_code_command(args, requested_by=requested_by)}
    if cmd == "/manager_relogin_pass":
        return {"ok": True, "result_text": await _panel_manager_relogin_pass_command(args, requested_by=requested_by)}
    if cmd == "/manager_relogin_confirm":
        return {"ok": True, "result_text": await _panel_manager_relogin_confirm_command(args, requested_by=requested_by)}
    if cmd == "/manager_relogin_cancel":
        return {"ok": True, "result_text": await _panel_manager_relogin_cancel_command(args, requested_by=requested_by)}
    if callable(_RELOGIN_PREV_PANEL_EXEC):
        try:
            return await _RELOGIN_PREV_PANEL_EXEC(command_text, requested_by=requested_by, source_chat_id=source_chat_id, response_chat_id=response_chat_id)
        except TypeError:
            try:
                return await _RELOGIN_PREV_PANEL_EXEC(command_text, requested_by=requested_by)
            except TypeError:
                return await _RELOGIN_PREV_PANEL_EXEC(command_text)
    return {"ok": False, "result_text": f"Команда не поддерживается: {cmd}"}

# --- TPILOT MANAGER RELOGIN 20260714 END ---


# --- TPILOT MANAGER REPLACEMENT STAGE2 20260715 START ---
# Fresh-Telegram-authorization account REPLACEMENT backend (architecture audit
# 2026-07-15; Stage 1 = storage.py durable state machine, independently
# reviewed and fixed; Stage 2 = this block).
#
# Replacement is NOT relogin. Relogin (above) re-authenticates the SAME
# manager_key against the SAME permanent session path. Replacement creates a
# BRAND NEW manager_key with its own brand new temporary AND future permanent
# session -- the old manager's row, session, and runtime are never touched by
# anything in this block. The two features intentionally share only small,
# pure, pre-existing primitives (_map_send_code_error, _manager_is_rate_limit_
# error, _manager_extract_wait_seconds, mask_phone, manager_registry's key
# validation/path builders, and the manager_onboarding scratch table via a
# distinct 'replace_*' step prefix so a replacement flow can never collide
# with an in-progress add-manager or relogin flow for the same admin).
#
# Stage 2 boundary (hard, enforced throughout this block):
#   - never calls _manager_finalize_login;
#   - never creates a managers-table row;
#   - never mutates the OLD manager row/session/runtime in any way;
#   - never advances a replacement operation past 'ready_commit' (the
#     guarded replacement_finalize() -- Stage 1's ONLY path to 'done' -- is
#     never called from here);
#   - never sends a PartnerBot notification (no notify-eligible status is
#     ever reached from this block);
#   - every phone/code/2FA-password value lives in a local variable or, for
#     phone/phone_code_hash only, the pre-existing manager_onboarding scratch
#     row (mirrors relogin's own pattern) -- the 2FA password and the code
#     itself are NEVER persisted anywhere, NEVER logged, NEVER included in
#     any returned result/exception text.
#
# Every function below accepts db_path/base_dir/client_factory/now_fn/
# operation_id_fn/relogin_active_fn as optional keyword overrides purely for
# testability -- production callers omit them and get the real project
# paths/functions (storage.DB_PATH, BASE_DIR, a real TelegramClient, etc.),
# exactly like every other function in this file.

import storage as _repl_storage


_REPLACE_STEP_PHONE = "replace_phone"
_REPLACE_STEP_CODE = "replace_code"
_REPLACE_STEP_PASS = "replace_pass"
_REPLACE_STEPS = {_REPLACE_STEP_PHONE, _REPLACE_STEP_CODE, _REPLACE_STEP_PASS}
_REPLACE_TEMP_SESSION_SUFFIX = ".replace.session"

_REPLACE_NEXT_STEP_BY_STATUS = {
    "draft": "reserve_key",
    "auth_phone": "continue_phone",
    "auth_code": "continue_code",
    "auth_pass": "continue_password",
    "identity_ok": "ready_commit",
    "ready_commit": "confirm_commit",
    "committing": "cleanup_required",
    "links_pending": "cleanup_required",
    "links_ready": "cleanup_required",
    "cutover_done": "cleanup_required",
    "notified": "cleanup_required",
    "done": "done",
    "failed": "failed",
    "cancelled": "cancelled",
}


def _replacement_next_step_for_status(status: str) -> str:
    return _REPLACE_NEXT_STEP_BY_STATUS.get(str(status or ""), "unknown")


def _replacement_result(ok: bool, code: str, message: str, *, operation_id: str = "",
                         next_step: str = "", retryable: bool = False, **extra: Any) -> Dict[str, Any]:
    """The one structured-result shape every Stage 2 function returns. Callers
    branch on ok/code/next_step -- never on parsing the (Russian) message
    text. extra fields (e.g. preview=..., new_manager_key=...) are merged in
    verbatim; callers of THIS function are responsible for never putting a
    secret value into extra."""
    out: Dict[str, Any] = {
        "ok": bool(ok), "code": str(code), "message": str(message),
        "operation_id": str(operation_id or ""), "next_step": str(next_step or ""),
        "retryable": bool(retryable),
    }
    out.update(extra)
    return out


# ---------------------------------------------------------------------------
# Session path model. Three distinct identities are used throughout Stage 2:
#   old permanent session   -- untouched, never referenced by any function here
#   new TEMPORARY session   -- <new_key>.replace.session (this block's own)
#   new FUTURE permanent    -- <new_key>.session (never created in Stage 2;
#                               only existence-checked as a conflict guard)
# Every path is derived from validate_manager_key(new_manager_key) first, so
# a malformed/traversal key raises before any path is ever built, and cleanup
# can never reach outside runtime/managers/<new_key>/.
# ---------------------------------------------------------------------------

def _replacement_temp_session_path(new_manager_key: str, *, base_dir: Optional[Path] = None) -> str:
    ok, err, key = validate_manager_key(new_manager_key)
    if not ok:
        raise ValueError(err or "Некорректный manager_key.")
    paths = build_manager_paths(str(base_dir if base_dir is not None else BASE_DIR), key)
    return os.path.join(paths["root"], f"{key}{_REPLACE_TEMP_SESSION_SUFFIX}")


def _replacement_permanent_session_path(new_manager_key: str, *, base_dir: Optional[Path] = None) -> str:
    ok, err, key = validate_manager_key(new_manager_key)
    if not ok:
        raise ValueError(err or "Некорректный manager_key.")
    return build_manager_paths(str(base_dir if base_dir is not None else BASE_DIR), key)["session_path"]


def _replacement_cleanup_temp_files(new_manager_key: str, *, base_dir: Optional[Path] = None) -> None:
    """Removes ONLY this new_manager_key's <key>.replace.session and its
    -journal/-wal/-shm companions. Never touches <key>.session (the future
    permanent path -- Stage 2 never creates it, so there is nothing of its
    own to remove there) and, by construction (every path is derived from
    validate_manager_key(new_manager_key)), can never reach the OLD
    manager's directory. Best-effort, never raises."""
    try:
        temp_path = _replacement_temp_session_path(new_manager_key, base_dir=base_dir)
    except ValueError:
        return
    for suffix in ("", "-journal", "-wal", "-shm"):
        fp = temp_path + suffix
        try:
            if os.path.exists(fp):
                os.remove(fp)
        except Exception:
            pass


def _replacement_build_client(session_path: str, proxy_config: Optional[Dict[str, Any]]) -> TelegramClient:
    """Production default Telethon client factory for Stage 2 -- resolves the
    caller-supplied proxy_config (same field shape as a managers-table row's
    proxy_* columns) via the EXISTING _resolve_manager_telethon_proxy, never
    a second proxy parser. Tests inject client_factory=... instead of calling
    this at all (no real network)."""
    api_id, api_hash, _profile = _api_profile_for("onboarding")
    proxy = _resolve_manager_telethon_proxy(dict(proxy_config or {}))
    return TelegramClient(session_path, api_id, api_hash, proxy=proxy, **_TELETHON_DEVICE_KWARGS)


# ---------------------------------------------------------------------------
# Durable proxy state (Stage 2 fix R2). A replacement operation never gets a
# managers-table row, so -- unlike add-manager/relogin, which can always
# re-resolve proxy_config from the (real) managers row by manager_key --
# Stage 2 has nowhere durable to read proxy_config back from unless it saves
# it itself. manager_replacements.proxy_mode/proxy_ref record the NON-SECRET
# route choice ('direct'/'proxy' + a free-text caller-supplied tag such as
# 'manual'/'pool'/'purchased'); the actual credentials (needed only for
# 'proxy' mode) live in manager_onboarding's proxy_* scratch columns -- the
# exact same table/security model already used for phone/phone_code_hash.
# Once proxy_confirmed=1, later reconnects NEVER depend on the caller
# resupplying proxy_config, and NEVER silently fall back to direct.
# ---------------------------------------------------------------------------

def _replacement_onboarding_proxy_fields(proxy_config: Optional[Dict[str, Any]], proxy_mode: str) -> Dict[str, Any]:
    """Maps a caller's proxy_config dict onto manager_save_onboarding's
    proxy_* kwargs for durable storage. Direct mode stores no credentials at
    all (there are none) -- the columns are simply left at their blank/zero
    defaults."""
    if proxy_mode != "proxy":
        return {
            "proxy_type": "", "proxy_host": "", "proxy_port": None,
            "proxy_username": "", "proxy_password": "", "proxy_enabled": 0,
            "proxy_bypass_allowed": 0, "proxy_mode": "direct",
        }
    cfg = dict(proxy_config or {})
    return {
        "proxy_type": str(cfg.get("proxy_type") or "socks5"),
        "proxy_host": str(cfg.get("proxy_host") or ""),
        "proxy_port": cfg.get("proxy_port"),
        "proxy_username": str(cfg.get("proxy_username") or ""),
        "proxy_password": str(cfg.get("proxy_password") or ""),
        "proxy_enabled": 1,
        "proxy_bypass_allowed": int(cfg.get("proxy_bypass_allowed") or 0),
        "proxy_mode": "proxy",
    }


def _replacement_resolve_durable_proxy(op_row: Dict[str, Any], onboarding_row: Optional[Dict[str, Any]]):
    """Rebuilds the exact proxy_config a reconnect must use from durable
    state only -- never from a caller-resupplied value. Returns
    (proxy_config_dict, None) on success, or (None, error_result) when the
    durable state is missing/unresolvable. NEVER returns a direct-mode
    config unless 'direct' was explicitly recorded at send_phone_code time."""
    op_id = str(op_row.get("operation_id") or "")
    mode = str(op_row.get("proxy_mode") or "").strip().lower()
    confirmed = int(op_row.get("proxy_confirmed") or 0) == 1
    if not confirmed or mode not in ("direct", "proxy"):
        return None, _replacement_result(
            False, "proxy_state_missing", "Состояние proxy для операции не сохранено.",
            operation_id=op_id, retryable=True, next_step="configure_proxy",
        )
    if mode == "direct":
        return {}, None
    ob = onboarding_row or {}
    host = str(ob.get("proxy_host") or "").strip()
    port = ob.get("proxy_port")
    if str(ob.get("proxy_mode") or "") != "proxy" or not host or not port:
        return None, _replacement_result(
            False, "proxy_reentry_required", "Требуется повторный ввод данных proxy.",
            operation_id=op_id, retryable=True, next_step="configure_proxy",
        )
    cfg = {
        "proxy_enabled": 1,
        "proxy_mode": "proxy",
        "proxy_type": ob.get("proxy_type") or "socks5",
        "proxy_host": host,
        "proxy_port": port,
        "proxy_username": ob.get("proxy_username") or "",
        "proxy_password": ob.get("proxy_password") or "",
        "proxy_bypass_allowed": ob.get("proxy_bypass_allowed") or 0,
    }
    return cfg, None


# ---------------------------------------------------------------------------
# Mutual exclusion with relogin (read-only predicates; relogin's own code is
# NOT modified in this stage -- these exist for relogin's future integration
# and for replacement_start's own pre-check).
# ---------------------------------------------------------------------------

async def _replacement_relogin_active(old_manager_key: str) -> bool:
    """True if ANY admin currently has a non-expired relogin_* onboarding row
    for old_manager_key. Read-only mirror of _manager_relogin_active_owner's
    own scan (no cleanup side effects here -- that stays relogin's job)."""
    key = registry_normalize_manager_key(old_manager_key or "")
    try:
        rows = await manager_list_pending()
    except Exception:
        return False
    now = _now_utc_iso()
    for row in rows:
        if str(row.get("step") or "") not in _RELOGIN_STEPS:
            continue
        if registry_normalize_manager_key(row.get("manager_key") or "") != key:
            continue
        expires_at = str(row.get("expires_at") or "")
        if expires_at and expires_at < now:
            continue
        return True
    return False


async def replacement_active_for_old_key(old_manager_key: str, *, db_path: Optional[str] = None) -> bool:
    """True if old_manager_key has a non-terminal replacement operation --
    exposed as a reusable predicate for relogin's OWN mutual-exclusion check
    in a later stage; relogin's existing functions are not edited here."""
    row = _repl_storage.replacement_get_active_for_old_key(
        registry_normalize_manager_key(old_manager_key or ""), db_path=db_path
    )
    return row is not None


async def _replacement_tg_user_conflict(tg_user_id: int, *, db_path: Optional[str] = None) -> Optional[str]:
    """Read-only: returns the conflicting manager_key if tg_user_id already
    belongs to an existing non-archived manager row, else None. Plain
    parameterized SELECT against the shared managers table (no schema
    change -- managers.tg_user_id already exists)."""
    uid = int(tg_user_id or 0)
    if uid <= 0:
        return None
    path = str(db_path or TPILOT_DB_PATH)
    try:
        async with aiosqlite.connect(path) as db:
            cur = await db.execute(
                "SELECT manager_key FROM managers WHERE tg_user_id=? AND COALESCE(status,'')<>'archived' LIMIT 1",
                (uid,),
            )
            row = await cur.fetchone()
            return str(row[0]) if row else None
    except Exception:
        return None


async def _replacement_username_conflict(new_username: str, exclude_operation_id: str, *,
                                          db_path: Optional[str] = None) -> bool:
    """Read-only, best-effort cross-operation identity check: True if some
    OTHER non-terminal replacement operation already recorded this exact
    Telegram username. Kept as a secondary signal alongside the database-
    backed _replacement_tgid_reserved_by_other (Stage 2 fix R3) below, which
    catches username-less accounts that this check cannot."""
    uname = str(new_username or "").strip()
    if not uname:
        return False
    path = str(db_path or TPILOT_DB_PATH)
    try:
        async with aiosqlite.connect(path) as db:
            cur = await db.execute(
                "SELECT 1 FROM manager_replacements WHERE new_username=? AND operation_id<>?"
                " AND status NOT IN ('done','failed','cancelled') LIMIT 1",
                (uname, str(exclude_operation_id or "")),
            )
            row = await cur.fetchone()
            return bool(row)
    except Exception:
        return False


async def _replacement_tgid_reserved_by_other(tg_user_id: int, exclude_operation_id: str, *,
                                                db_path: Optional[str] = None) -> Optional[str]:
    """Stage 2 fix R3: database-backed cross-operation identity check against
    manager_replacements.new_tg_user_id (not just username, which misses
    username-less Telegram accounts). Read-only pre-check for a friendlier
    error message; ux_repl_new_tgid is the actual race-safe backstop applied
    inside replacement_advance itself. Returns the conflicting operation_id,
    or None."""
    uid = int(tg_user_id or 0)
    if uid <= 0:
        return None
    path = str(db_path or TPILOT_DB_PATH)
    try:
        async with aiosqlite.connect(path) as db:
            cur = await db.execute(
                "SELECT operation_id FROM manager_replacements WHERE new_tg_user_id=? AND operation_id<>?"
                " AND status NOT IN ('failed','cancelled') LIMIT 1",
                (uid, str(exclude_operation_id or "")),
            )
            row = await cur.fetchone()
            return str(row[0]) if row else None
    except Exception:
        return None


# ---------------------------------------------------------------------------
# Fatal-failure / cancellation cleanup
# ---------------------------------------------------------------------------

async def _replacement_fail(operation_id: str, stage: str, error_text: str, *,
                             db_path: Optional[str] = None, base_dir: Optional[Path] = None,
                             new_manager_key: str = "", owner_user_id: int = 0,
                             rollback_stage: str = "") -> None:
    """THE one Stage 2 fatal-failure path. Marks the operation failed (bounded
    stage/text via storage.replacement_fail's own truncation), removes ONLY
    this operation's temp session files, and clears the initiating admin's
    onboarding scratch row. Idempotent: replacement_fail's CAS returns False
    on an already-terminal operation (harmless), and file/onboarding cleanup
    are no-ops when there is nothing left to clean. rollback_stage (TPILOT C
    20260718) is optional -- non-empty only when this failure followed the
    committing/links_pending/links_ready automatic-rollback path, blank for
    plain pre-commit auth-stage failures (nothing to compensate)."""
    key = registry_normalize_manager_key(new_manager_key or "")
    if key:
        _replacement_cleanup_temp_files(key, base_dir=base_dir)
    _repl_storage.replacement_fail(operation_id, stage, error_text, rollback_stage=rollback_stage, db_path=db_path)
    if owner_user_id:
        try:
            await manager_delete_onboarding(int(owner_user_id))
        except Exception:
            pass


# ---------------------------------------------------------------------------
# 1. Start a replacement operation (draft)
# ---------------------------------------------------------------------------

async def replacement_start(
    old_manager_key: str, created_by_user_id: int, *,
    target_date: str = "", operation_id: str = "", db_path: Optional[str] = None,
    relogin_active_fn=None, operation_id_fn=None,
) -> Dict[str, Any]:
    """Creates the durable draft row for a new replacement operation. Never
    mutates the old manager row. Never creates a new managers row. Snapshots
    old identity (display name, username, source_key) immutably onto the new
    operation via Stage 1's replacement_create."""
    ok_key, err_key, old_key = validate_manager_key(old_manager_key)
    if not ok_key:
        return _replacement_result(False, "invalid_old_key", err_key or "Некорректный manager_key.")
    uid = int(created_by_user_id or 0)
    if uid <= 0:
        return _replacement_result(False, "invalid_user", "Некорректный инициатор операции.")

    row = await manager_get(old_key)
    if not row:
        return _replacement_result(False, "old_not_found", f"Менеджер не найден: {old_key}")
    status = str(row.get("status") or "").strip().lower()
    if status in ("archived", "deleted"):
        return _replacement_result(False, "old_archived", f"Менеджер архивирован/удалён: {old_key}")

    gen_op_id = operation_id_fn or (lambda: __import__("uuid").uuid4().hex)
    op_id = str(operation_id or "").strip() or str(gen_op_id())

    # The active-replacement conflict check must not reject a retry that
    # supplies the SAME operation_id as the already-active row -- that is
    # the normal idempotent-retry case (e.g. a network hiccup after the
    # first call already succeeded), not a genuine second operation.
    existing_active = _repl_storage.replacement_get_active_for_old_key(old_key, db_path=db_path)
    if existing_active and str(existing_active.get("operation_id") or "") != op_id:
        return _replacement_result(
            False, "already_active", f"Для {old_key} уже выполняется замена аккаунта.",
            operation_id=str(existing_active.get("operation_id") or ""),
        )

    relogin_check = relogin_active_fn or _replacement_relogin_active
    if await relogin_check(old_key):
        return _replacement_result(False, "relogin_active", f"Для {old_key} сейчас выполняется повторный вход. Замена недоступна.")

    old_display_name = str(row.get("display_name") or "").strip()
    old_username = str(row.get("telegram_username") or "").strip()
    src_key = ""
    try:
        src_key = await _partner_source_key_for_manager(old_key) or ""
    except Exception:
        src_key = ""

    created_row = _repl_storage.replacement_create(
        op_id, old_key, source_key=src_key, old_display_name=old_display_name,
        old_username=old_username, created_by_user_id=uid, target_date=str(target_date or ""),
        db_path=db_path,
    )
    if not created_row:
        return _replacement_result(False, "create_conflict", f"Не удалось создать операцию замены для {old_key} (конфликт).")
    return _replacement_result(
        True, "draft_created", "Операция замены создана.", operation_id=op_id,
        next_step="reserve_key", old_display_name=old_display_name, old_username=old_username,
        source_key=src_key, status=str(created_row.get("status") or ""),
    )


# ---------------------------------------------------------------------------
# 2. Reserve the new manager_key (pure validation -- no DB write to
#    manager_replacements here; the reserved key is persisted atomically
#    together with the draft->auth_phone transition inside
#    replacement_send_phone_code, where Stage 1's ux_repl_new_key gives the
#    final, race-safe answer).
# ---------------------------------------------------------------------------

async def replacement_reserve_key(
    operation_id: str, new_manager_key: str, *, db_path: Optional[str] = None, base_dir: Optional[Path] = None,
) -> Dict[str, Any]:
    op = str(operation_id or "").strip()
    if not op:
        return _replacement_result(False, "missing_operation", "Операция не найдена.")
    op_row = _repl_storage.replacement_get(op, db_path=db_path)
    if not op_row:
        return _replacement_result(False, "missing_operation", "Операция не найдена.", operation_id=op)
    if str(op_row.get("status")) in _repl_storage.REPLACEMENT_TERMINAL_STATUSES:
        return _replacement_result(False, "operation_terminal", "Операция уже завершена.", operation_id=op)

    ok_key, err_key, key = validate_manager_key(new_manager_key)
    if not ok_key:
        return _replacement_result(False, "invalid_key", err_key or "Некорректный ключ.", operation_id=op)

    old_key = registry_normalize_manager_key(op_row.get("old_manager_key") or "")
    if key == old_key:
        return _replacement_result(False, "same_as_old", "Новый ключ должен отличаться от старого.", operation_id=op)

    existing_row = await manager_get(key)
    if existing_row:
        return _replacement_result(False, "key_exists", f"Менеджер с ключом {key} уже существует.", operation_id=op)
    try:
        tombstoned = _repl_storage.manager_stats_tombstone_get(key, db_path=db_path) is not None
    except Exception:
        tombstoned = False
    if tombstoned:
        return _replacement_result(False, "key_tombstoned", f"Ключ {key} закреплён за удалённым менеджером (архив статистики).", operation_id=op)

    # DB-level ownership check FIRST -- this is what tells apart "this same
    # operation already reserved this key" (idempotent -- its own earlier
    # progress may have already created the runtime dir/temp session, which
    # must NOT be reported as a foreign conflict) from "a genuinely different
    # operation holds this key" (a real conflict, reported without even
    # consulting the filesystem).
    other = _repl_storage.replacement_get_by_new_key(key, db_path=db_path)
    if other and str(other.get("status")) not in _repl_storage.REPLACEMENT_TERMINAL_STATUSES:
        if str(other.get("operation_id")) != op:
            return _replacement_result(False, "key_reserved_elsewhere", f"Ключ {key} уже зарезервирован другой операцией замены.", operation_id=op)
        return _replacement_result(True, "key_reserved", f"Ключ {key} зарезервирован.", operation_id=op, next_step="send_phone_code", new_manager_key=key)

    # No operation (this one or another) currently claims this key in the DB
    # -- any directory/session found on disk now is genuinely orphaned/
    # foreign (e.g. a hand-placed file, or leftovers from a terminal/failed
    # attempt that never got cleaned up), not this operation's own prior
    # progress. session_exists is checked before runtime_dir_exists since a
    # session file's mere presence is the more specific/severe signal (its
    # parent directory necessarily also exists).
    base = base_dir if base_dir is not None else BASE_DIR
    paths = build_manager_paths(str(base), key)
    if os.path.exists(paths["session_path"]):
        return _replacement_result(False, "session_exists", f"Session-файл для {key} уже существует.", operation_id=op)
    if os.path.isdir(paths["root"]):
        return _replacement_result(False, "runtime_dir_exists", f"Runtime-папка для {key} уже существует.", operation_id=op)

    return _replacement_result(True, "key_available", f"Ключ {key} доступен.", operation_id=op, next_step="send_phone_code", new_manager_key=key)


# ---------------------------------------------------------------------------
# 3. Proxy configuration (pure; reuses the EXISTING resolver unchanged)
# ---------------------------------------------------------------------------

def replacement_describe_proxy(proxy_config: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    """proxy_config: a plain dict shaped exactly like a managers-table row's
    proxy_* columns (proxy_type, proxy_host, proxy_port, proxy_username,
    proxy_password, proxy_enabled, proxy_bypass_allowed, proxy_mode) -- the
    output shape the EXISTING pool-selection/purchase-confirmation/manual-
    entry routes already produce. Reuses _resolve_manager_telethon_proxy /
    _manager_auth_proxy_mode UNCHANGED -- no second proxy parser is built
    here. Returns a NON-SECRET status descriptor only; credentials are never
    included in the returned dict and never reach any persisted state."""
    cfg = dict(proxy_config or {})
    try:
        telethon_proxy = _resolve_manager_telethon_proxy(cfg)
    except RuntimeError:
        return _replacement_result(False, "proxy_invalid", "Некорректная конфигурация proxy для авторизации.")
    mode = _manager_auth_proxy_mode(cfg)
    return _replacement_result(
        True, "proxy_ok", "Proxy настроен." if telethon_proxy else "Прямое подключение (без proxy).",
        proxy_mode=mode, proxy_configured=bool(telethon_proxy),
    )


# ---------------------------------------------------------------------------
# 4. Fresh Telegram login: phone -> code request
# ---------------------------------------------------------------------------

async def replacement_send_phone_code(
    operation_id: str, new_display_name: str, new_manager_key: str, phone: str,
    proxy_config: Optional[Dict[str, Any]], *, proxy_source: str = "",
    db_path: Optional[str] = None, base_dir: Optional[Path] = None,
    client_factory=None, now_fn=None,
) -> Dict[str, Any]:
    """Stage 2 fix B1/R2: accepts 'draft' (first call) OR 'auth_phone' (an
    explicit safe retry/re-request). draft->auth_phone is CAS'd BEFORE any
    network call, together with the durable proxy route (proxy_mode/
    proxy_ref/proxy_confirmed) -- a crash at any point after this is always
    resumable at continue_phone with the SAME route, never a silent
    fallback to direct. auth_code is entered ONLY after the onboarding
    scratch row carrying phone_code_hash is durably saved -- see the
    reconciliation branch below for the crash-after-success case.

    Stage 2 fix REQ-1: an auth_phone RETRY must never diverge from the
    durable identity/route this operation already committed to. A different
    new_manager_key is rejected (key_mismatch_on_retry) before ANY
    filesystem/onboarding/network side effect; the durable proxy_mode/
    proxy_ref/proxy_confirmed recorded at the draft CAS are always reused
    via _replacement_resolve_durable_proxy -- a caller-resupplied
    proxy_config on retry is accepted for call-shape compatibility but never
    used to change the connection route (a draft=direct operation can never
    retry through a proxy, and vice versa)."""
    op = str(operation_id or "").strip()
    op_row = _repl_storage.replacement_get(op, db_path=db_path)
    if not op_row:
        return _replacement_result(False, "missing_operation", "Операция не найдена.", operation_id=op)
    status = str(op_row.get("status") or "")
    if status not in ("draft", "auth_phone"):
        return _replacement_result(
            False, "wrong_state", "Операция не ожидает запрос кода.", operation_id=op,
            next_step=_replacement_next_step_for_status(status),
        )

    name = str(new_display_name or "").strip()
    if not name:
        return _replacement_result(False, "empty_display_name", "Введите отображаемое имя.", operation_id=op)

    durable_key = registry_normalize_manager_key(op_row.get("new_manager_key") or "")
    if status == "auth_phone" and durable_key:
        ok_key, _err_key, candidate_key = validate_manager_key(new_manager_key)
        if not ok_key or candidate_key != durable_key:
            return _replacement_result(
                False, "key_mismatch_on_retry",
                f"Операция уже привязана к ключу {durable_key}; повтор с другим ключом не допускается.",
                operation_id=op, next_step="continue_phone",
            )

    reserve = await replacement_reserve_key(op, new_manager_key, db_path=db_path, base_dir=base_dir)
    if not reserve.get("ok"):
        return reserve
    key = str(reserve.get("new_manager_key") or "")

    phone_s = str(phone or "").strip()
    if not phone_s:
        return _replacement_result(False, "empty_phone", "Введите номер телефона.", operation_id=op)

    base = base_dir if base_dir is not None else BASE_DIR
    owner_uid = int(op_row.get("created_by_user_id") or 0)
    future_iso = now_fn or _future_iso

    if status == "draft":
        proxy_status = replacement_describe_proxy(proxy_config)
        if not proxy_status.get("ok"):
            return proxy_status
        proxy_mode = str(proxy_status.get("proxy_mode") or "direct")
        proxy_ref = str(proxy_source or "").strip().lower() or ("direct" if proxy_mode == "direct" else "manual")
        proxy_fields = _replacement_onboarding_proxy_fields(proxy_config, proxy_mode)
        effective_proxy_config = proxy_config

        ensure_manager_dirs(str(base), key)
        temp_path = _replacement_temp_session_path(key, base_dir=base)
        try:
            ok_adv = _repl_storage.replacement_advance(
                op, "draft", "auth_phone", stage="phone_requested",
                fields={
                    "new_manager_key": key, "new_display_name": name,
                    "proxy_mode": proxy_mode, "proxy_ref": proxy_ref, "proxy_confirmed": 1,
                },
                db_path=db_path,
            )
        except _repl_storage.ReplacementConflict:
            _replacement_cleanup_temp_files(key, base_dir=base)
            return _replacement_result(False, "key_conflict", f"Ключ {key} только что занят другой операцией.", operation_id=op)
        if not ok_adv:
            return _replacement_result(False, "stale_state", "Операция изменилась, начните заново.", operation_id=op)
    else:
        # status == "auth_phone": explicit retry, key already verified ==
        # durable_key above. ensure_manager_dirs/temp_path are for THIS
        # operation's own key -- never a different one.
        ensure_manager_dirs(str(base), key)
        temp_path = _replacement_temp_session_path(key, base_dir=base)

        onboarding = await manager_get_onboarding(owner_uid)
        onboarding_matches = bool(
            onboarding and registry_normalize_manager_key(onboarding.get("manager_key") or "") == key
        )

        # If a valid code request is ALREADY durably on disk for this exact
        # operation (onboarding row step=CODE with a non-empty hash),
        # reconcile forward instead of inducing a duplicate
        # send_code_request/possible FloodWait -- this is exactly the
        # "crash after Telegram success, before our own CAS" window, and it
        # is always safely resumable this way, with NO network call.
        if (onboarding_matches and str(onboarding.get("step") or "") == _REPLACE_STEP_CODE
                and str(onboarding.get("phone_code_hash") or "").strip()):
            if not _repl_storage.replacement_advance(op, "auth_phone", "auth_code", stage="code_accepted_reconciled", db_path=db_path):
                return _replacement_result(False, "stale_state", "Операция изменилась, начните заново.", operation_id=op)
            return _replacement_result(
                True, "code_accepted_reconciled", "Код уже был отправлен ранее. Введите код Telegram.",
                operation_id=op, next_step="submit_code", new_manager_key=key,
            )

        # Plain resend: reuse the DURABLE proxy route ONLY -- a fresh
        # caller-supplied proxy_config is never used to change the
        # connection route once the draft CAS has already committed to one.
        # Missing/unresolvable durable proxy state fails closed (returns
        # proxy_state_missing/proxy_reentry_required) rather than silently
        # falling back to direct or accepting the caller's route instead.
        resolved_proxy, proxy_err = _replacement_resolve_durable_proxy(
            op_row, onboarding if onboarding_matches else None,
        )
        if proxy_err:
            return proxy_err
        effective_proxy_config = resolved_proxy
        proxy_mode = str(op_row.get("proxy_mode") or "direct")
        proxy_fields = _replacement_onboarding_proxy_fields(resolved_proxy, proxy_mode)

    # Durable "requesting code" scratch row FIRST -- proxy credentials (if
    # any) and phone are on disk before any network attempt.
    await manager_save_onboarding(
        owner_uid, manager_key=key, step=_REPLACE_STEP_PHONE,
        phone=phone_s, phone_code_hash="", tmp_session_path=temp_path,
        expires_at=future_iso(MANAGER_ONBOARD_TIMEOUT_SEC),
        **proxy_fields,
    )

    build_client = client_factory or (lambda session_path, cfg: _replacement_build_client(session_path, cfg))
    _manager_auth_audit_log("replacement_send_code_start", key, phone_masked=mask_phone(phone_s), admin_user_id=owner_uid)
    temp_client = None
    try:
        temp_client = build_client(temp_path, effective_proxy_config)
        await temp_client.connect()
        sent = await temp_client.send_code_request(phone_s)
        phone_code_hash = str(getattr(sent, "phone_code_hash", "") or "")
        if not phone_code_hash:
            raise RuntimeError("empty_phone_code_hash")
    except Exception as e:
        if _manager_is_rate_limit_error(e):
            wait_sec = _manager_extract_wait_seconds(e, MANAGER_PHONE_COOLDOWN_SEC)
            _manager_auth_audit_log("replacement_send_code_finish", key, ok=0, error_class=e.__class__.__name__, rate_limited=1)
            return _replacement_result(
                False, "flood_wait", f"Telegram временно ограничил запросы кода. Повторите через {wait_sec} сек.",
                operation_id=op, retryable=True, wait_seconds=wait_sec,
            )
        is_banned = isinstance(e, PhoneNumberBannedError) or "phonenumberbanned" in e.__class__.__name__.lower()
        _manager_auth_audit_log("replacement_send_code_finish", key, ok=0, error_class=e.__class__.__name__)
        if is_banned:
            await _replacement_fail(op, "auth_phone", "phone_banned", db_path=db_path, base_dir=base,
                                     new_manager_key=key, owner_user_id=owner_uid)
            return _replacement_result(False, "phone_banned", "Этот номер телефона заблокирован в Telegram.", operation_id=op)
        return _replacement_result(False, "send_code_failed", _map_send_code_error(e), operation_id=op, retryable=True)
    finally:
        if temp_client is not None:
            try:
                await temp_client.disconnect()
            except Exception:
                pass

    # Save the REAL hash durably FIRST -- only once the onboarding row that
    # submit_code needs is on disk do we advance the durable status, so
    # there is never a durable auth_code without the state needed to submit
    # the code (and never a dead-end auth_phone with a hash nowhere saved).
    await manager_save_onboarding(
        owner_uid, manager_key=key, step=_REPLACE_STEP_CODE,
        phone=phone_s, phone_code_hash=phone_code_hash, tmp_session_path=temp_path,
        expires_at=future_iso(MANAGER_ONBOARD_TIMEOUT_SEC),
        **proxy_fields,
    )
    if not _repl_storage.replacement_advance(op, "auth_phone", "auth_code", stage="code_accepted", db_path=db_path):
        # The onboarding row is already durably saved (reconciliation above
        # will pick it up on the next call) -- do NOT delete the temp
        # session or the row just written; this operation may still be
        # legitimately resumable.
        return _replacement_result(False, "stale_state", "Операция изменилась, начните заново.", operation_id=op)

    _manager_auth_audit_log("replacement_send_code_finish", key, ok=1)
    return _replacement_result(True, "code_sent", "Код отправлен. Введите код Telegram.", operation_id=op,
                                next_step="submit_code", new_manager_key=key)


# ---------------------------------------------------------------------------
# 4b. QR counterpart of the phone/code request above (TPILOT AUTH SAFETY
# 20260809, Ф3, D-QR). Reuses replacement_reserve_key / replacement_describe_
# proxy / _replacement_onboarding_proxy_fields -- the SAME primitives
# replacement_send_phone_code itself uses -- for the draft -> auth_phone CAS
# (key reservation, display name, proxy route). Never calls
# send_code_request; opens NO Telegram client itself -- the caller (a future
# Ф4 UI entry point, or a selftest) opens the QR client at the returned
# temp_session_path and registers it in _MANAGER_QR_SESSIONS with
# context="replace" so _manager_qr_wait_task can dispatch into
# _replacement_after_signin on success (see main.py's QR section near
# _panel_manager_qr_start_command).
# ---------------------------------------------------------------------------

async def replacement_send_qr_start(
    operation_id: str, new_display_name: str, new_manager_key: str,
    proxy_config: Optional[Dict[str, Any]], *, proxy_source: str = "",
    db_path: Optional[str] = None, base_dir: Optional[Path] = None,
) -> Dict[str, Any]:
    """Durable draft -> auth_phone transition for a QR-based replacement --
    no phone number, no send_code_request. Only the 'draft' status is
    accepted here (an 'auth_phone' retry means a QR wait is already/still in
    progress for this operation; callers should poll status instead of
    calling this again -- unlike the phone flow, there is no idempotent
    resend to reconcile because no network request was made yet)."""
    op = str(operation_id or "").strip()
    op_row = _repl_storage.replacement_get(op, db_path=db_path)
    if not op_row:
        return _replacement_result(False, "missing_operation", "Операция не найдена.", operation_id=op)
    status = str(op_row.get("status") or "")
    if status != "draft":
        return _replacement_result(
            False, "wrong_state", "Операция уже не в состоянии черновика.", operation_id=op,
            next_step=_replacement_next_step_for_status(status),
        )

    name = str(new_display_name or "").strip()
    if not name:
        return _replacement_result(False, "empty_display_name", "Введите отображаемое имя.", operation_id=op)

    reserve = await replacement_reserve_key(op, new_manager_key, db_path=db_path, base_dir=base_dir)
    if not reserve.get("ok"):
        return reserve
    key = str(reserve.get("new_manager_key") or "")

    base = base_dir if base_dir is not None else BASE_DIR
    proxy_status = replacement_describe_proxy(proxy_config)
    if not proxy_status.get("ok"):
        return proxy_status
    proxy_mode = str(proxy_status.get("proxy_mode") or "direct")
    proxy_ref = str(proxy_source or "").strip().lower() or ("direct" if proxy_mode == "direct" else "manual")

    ensure_manager_dirs(str(base), key)
    temp_path = _replacement_temp_session_path(key, base_dir=base)

    try:
        ok_adv = _repl_storage.replacement_advance(
            op, "draft", "auth_phone", stage="qr_requested",
            fields={
                "new_manager_key": key, "new_display_name": name,
                "proxy_mode": proxy_mode, "proxy_ref": proxy_ref, "proxy_confirmed": 1,
            },
            db_path=db_path,
        )
    except _repl_storage.ReplacementConflict:
        _replacement_cleanup_temp_files(key, base_dir=base)
        return _replacement_result(False, "key_conflict", f"Ключ {key} только что занят другой операцией.", operation_id=op)
    if not ok_adv:
        return _replacement_result(False, "stale_state", "Операция изменилась, начните заново.", operation_id=op)

    _manager_auth_audit_log("replacement_qr_reserve", key, ok=1, admin_user_id=int(op_row.get("created_by_user_id") or 0))
    return _replacement_result(
        True, "auth_phone_ready", "Готово к входу по QR.", operation_id=op,
        next_step="await_qr", new_manager_key=key, temp_session_path=temp_path,
    )


# ---------------------------------------------------------------------------
# 4c. QR/Session/TData counterpart of the phone/code request above (TPILOT
# AUTH SAFETY 20260809, Ф4). Session/TData replacement is a TWO-STEP flow,
# mirroring QR's own shape (open, then a separate confirm): step 1 below only
# runs tdata_import.service.start_import -- UNMODIFIED, identity verification
# only, nothing installed anywhere live/permanent -- targeting a synthetic
# (not-yet-a-real-managers-row) proxy row for the reserved new_manager_key.
# Step 2 (replacement_confirm_tdimport_install, right below it) is what
# actually installs into the replacement TEMP path and advances
# auth_phone -> identity_ok, reusing the exact same identity-conflict guards
# _replacement_after_signin already uses for QR/phone. No new session-file
# install primitive, no new state-machine transition, no new conflict-check
# logic -- only a new ORCHESTRATION that wires existing, unmodified pieces
# together for this one additional entry method.
# ---------------------------------------------------------------------------

async def replacement_send_tdimport_start(
    operation_id: str, new_display_name: str, new_manager_key: str,
    proxy_config: Optional[Dict[str, Any]], archive_path: str, *,
    proxy_source: str = "", db_path: Optional[str] = None, base_dir: Optional[Path] = None,
    proxy_prober=None,
) -> Dict[str, Any]:
    """Durable draft -> auth_phone transition (identical CAS to replacement_
    send_qr_start/replacement_send_phone_code), then runs tdata_import.
    service.start_import to completion (identity verification only). On
    success the verified identity + validated session sit in tdata_import_ops
    at Stage.IDENTITY_VERIFIED -- nothing about the replacement operation
    itself, the OLD manager, or any live/permanent session file has been
    touched. The caller must separately call
    replacement_confirm_tdimport_install() to actually commit."""
    op = str(operation_id or "").strip()
    op_row = _repl_storage.replacement_get(op, db_path=db_path)
    if not op_row:
        return _replacement_result(False, "missing_operation", "Операция не найдена.", operation_id=op)
    status = str(op_row.get("status") or "")
    if status != "draft":
        return _replacement_result(
            False, "wrong_state", "Операция уже не в состоянии черновика.", operation_id=op,
            next_step=_replacement_next_step_for_status(status),
        )

    name = str(new_display_name or "").strip()
    if not name:
        return _replacement_result(False, "empty_display_name", "Введите отображаемое имя.", operation_id=op)

    reserve = await replacement_reserve_key(op, new_manager_key, db_path=db_path, base_dir=base_dir)
    if not reserve.get("ok"):
        return reserve
    key = str(reserve.get("new_manager_key") or "")

    base = base_dir if base_dir is not None else BASE_DIR
    proxy_status = replacement_describe_proxy(proxy_config)
    if not proxy_status.get("ok"):
        return proxy_status
    proxy_mode = str(proxy_status.get("proxy_mode") or "direct")
    proxy_ref = str(proxy_source or "").strip().lower() or ("direct" if proxy_mode == "direct" else "manual")

    ensure_manager_dirs(str(base), key)

    try:
        ok_adv = _repl_storage.replacement_advance(
            op, "draft", "auth_phone", stage="tdimport_requested",
            fields={
                "new_manager_key": key, "new_display_name": name,
                "proxy_mode": proxy_mode, "proxy_ref": proxy_ref, "proxy_confirmed": 1,
            },
            db_path=db_path,
        )
    except _repl_storage.ReplacementConflict:
        return _replacement_result(False, "key_conflict", f"Ключ {key} только что занят другой операцией.", operation_id=op)
    if not ok_adv:
        return _replacement_result(False, "stale_state", "Операция изменилась, начните заново.", operation_id=op)

    # Synthetic row: this manager_key has NO real managers row yet (Stage 2
    # never creates one) -- only the proxy_* fields _build_manager_telegram_
    # client_from_row actually reads are projected here, from the FRESH
    # caller-supplied proxy_config (this is the first connection attempt for
    # this operation, so there is no "durable reconnect" case to resolve).
    synthetic_row = {"manager_key": key, **_replacement_onboarding_proxy_fields(proxy_config, proxy_mode)}

    async def _client_factory(session_path: str):
        return await _tdimport_client_factory_for(synthetic_row, session_path)

    def _dup_check(tg_id: int):
        return _repl_storage.tdata_import_tg_user_conflict(tg_id, db_path=db_path or TPILOT_DB_PATH)

    def _reserved_check(tg_id: int):
        return _repl_storage.tdata_import_tgid_reserved_by_other(tg_id, op, db_path=db_path or TPILOT_DB_PATH)

    tdi_operation_id = _tdimport_new_operation_id(f"repl_{key}")
    work_root = str(Path(str(base)) / "runtime" / "tdata_import" / tdi_operation_id)
    proxy_row = {
        "proxy_mode": proxy_mode, "proxy_lease_id": None,
        "proxy_host": synthetic_row.get("proxy_host") or "",
        "proxy_port": synthetic_row.get("proxy_port") or 0,
        "proxy_username": synthetic_row.get("proxy_username") or "",
        "proxy_password": synthetic_row.get("proxy_password") or "",
    }

    result = await _tdimport_service.start_import(
        operation_id=tdi_operation_id, manager_key=key, archive_path=archive_path,
        work_root=work_root, proxy_row=proxy_row, client_factory=_client_factory,
        owner_user_id=int(op_row.get("created_by_user_id") or 0), source_key="",
        expires_at=_future_iso(3600),
        known_session_paths=[_replacement_permanent_session_path(key, base_dir=base)],
        proxy_prober=proxy_prober or _tdimport_real_prober, duplicate_check=_dup_check, reserved_check=_reserved_check,
        db_path=db_path,
    )
    if not result.get("ok"):
        return _replacement_result(
            False, "tdimport_failed", str(result.get("error_text") or "Не удалось обработать архив."),
            operation_id=op, retryable=bool(result.get("retryable")),
            tdimport_error_class=str(result.get("error_class") or ""),
        )
    _manager_auth_audit_log("replacement_tdimport_verified", key, ok=1, admin_user_id=int(op_row.get("created_by_user_id") or 0))
    return _replacement_result(
        True, "identity_verified", "Личность подтверждена, подтвердите установку.", operation_id=op,
        next_step="confirm_tdimport", tdimport_operation_id=tdi_operation_id,
    )


async def replacement_confirm_tdimport_install(
    operation_id: str, tdimport_operation_id: str, *,
    db_path: Optional[str] = None, base_dir: Optional[Path] = None,
) -> Dict[str, Any]:
    """Commits a verified Session/TData identity (from replacement_send_
    tdimport_start) into the replacement's TEMPORARY session path and
    advances auth_phone -> identity_ok -- the SAME transition edge, and the
    SAME identity-conflict guards (same-as-old / tg_user_id_conflict /
    reserved-elsewhere / username_conflict), _replacement_after_signin
    already uses for QR/phone. Idempotent (Stage 2 fix R4 pattern): a second
    call after identity_ok short-circuits. Never touches the OLD manager's
    live session. Never spawns any runtime -- that only happens much later,
    at the existing ready_commit -> ... -> _repl4_promote_session cutover,
    exactly like every other replacement path."""
    op = str(operation_id or "").strip()
    op_row = _repl_storage.replacement_get(op, db_path=db_path)
    if not op_row:
        return _replacement_result(False, "missing_operation", "Операция не найдена.", operation_id=op)
    status = str(op_row.get("status") or "")
    if status in ("identity_ok", "ready_commit"):
        return _replacement_result(
            True, "identity_verified", "Личность уже подтверждена.", operation_id=op,
            next_step="ready_commit" if status == "identity_ok" else "confirm_commit",
            tg_username=str(op_row.get("new_username") or ""),
        )
    key = registry_normalize_manager_key(op_row.get("new_manager_key") or "")
    owner_uid = int(op_row.get("created_by_user_id") or 0)

    tdi_row = _repl_storage.tdata_import_get(str(tdimport_operation_id or ""), db_path=db_path)
    if not tdi_row or str(tdi_row.get("stage") or "") != str(_tdimport_service.Stage.IDENTITY_VERIFIED):
        return _replacement_result(False, "not_verified", "Личность ещё не подтверждена. Повторите загрузку.",
                                    operation_id=op, retryable=True)
    # TPILOT AUTH SAFETY 20260809 (Ф4 checkpoint correction): tdata_import_get
    # is a bare primary-key lookup with no owner scoping -- without this check
    # an admin-supplied tdimport_operation_id from a DIFFERENT replacement
    # operation (or from the unrelated standalone /manager_tdimport_start
    # flow) could be fed into this operation's confirm call and attach the
    # wrong-but-individually-valid identity to this row. The identity-conflict
    # guards below do not catch this class of bug -- a mismatch here isn't a
    # duplicate, it's a correctly-verified identity bound to the wrong
    # operation. Reject before touching anything.
    if registry_normalize_manager_key(str(tdi_row.get("manager_key") or "")) != key:
        return _replacement_result(False, "tdimport_mismatch",
                                    "Импортированная сессия принадлежит другой операции.", operation_id=op)
    if int(tdi_row.get("owner_user_id") or 0) != owner_uid:
        return _replacement_result(False, "tdimport_mismatch",
                                    "Импортированная сессия принадлежит другой операции.", operation_id=op)

    actual_user_id = int(tdi_row.get("tg_user_id") or 0)
    actual_username = str(tdi_row.get("username") or "")
    session_source_path = ""
    tdi_work_root = ""
    try:
        import json as _rcti_json
        result_json = _rcti_json.loads(str(tdi_row.get("result_json") or "{}"))
        session_source_path = str(result_json.get("session_source_path") or "")
        tdi_work_root = str(result_json.get("work_root") or "")
    except Exception:
        pass

    if actual_user_id <= 0 or not session_source_path or not os.path.isfile(session_source_path):
        return _replacement_result(False, "missing_identity", "Не удалось получить подтверждённую сессию.", operation_id=op)

    old_key = registry_normalize_manager_key(op_row.get("old_manager_key") or "")
    old_row = await manager_get(old_key)
    old_tg_user_id = int((old_row or {}).get("tg_user_id") or 0)
    if old_tg_user_id and old_tg_user_id == actual_user_id:
        await _replacement_fail(op, "identity", "same_as_old_identity", db_path=db_path, base_dir=base_dir,
                                 new_manager_key=key, owner_user_id=owner_uid)
        return _replacement_result(False, "same_identity", "Новый аккаунт совпадает со старым.", operation_id=op)

    conflict_key = await _replacement_tg_user_conflict(actual_user_id, db_path=db_path)
    if conflict_key and conflict_key != key:
        await _replacement_fail(op, "identity", "tg_user_id_conflict", db_path=db_path, base_dir=base_dir,
                                 new_manager_key=key, owner_user_id=owner_uid)
        return _replacement_result(False, "identity_conflict", f"Этот Telegram-аккаунт уже привязан к менеджеру {conflict_key}.", operation_id=op)

    other_op = await _replacement_tgid_reserved_by_other(actual_user_id, op, db_path=db_path)
    if other_op:
        await _replacement_fail(op, "identity", "tg_user_id_reserved_elsewhere", db_path=db_path, base_dir=base_dir,
                                 new_manager_key=key, owner_user_id=owner_uid)
        return _replacement_result(False, "identity_conflict", "Этот Telegram-аккаунт уже используется в другой операции замены.", operation_id=op)

    if actual_username and await _replacement_username_conflict(actual_username, op, db_path=db_path):
        await _replacement_fail(op, "identity", "username_conflict", db_path=db_path, base_dir=base_dir,
                                 new_manager_key=key, owner_user_id=owner_uid)
        return _replacement_result(False, "identity_conflict", "Этот Telegram-аккаунт уже используется в другой операции замены.", operation_id=op)

    base = base_dir if base_dir is not None else BASE_DIR
    temp_path = _replacement_temp_session_path(key, base_dir=base)
    try:
        install_result = _tdimport_service.installer.install_session(session_source_path, temp_path)
    except Exception as e:
        return _replacement_result(False, "session_install_failed", f"Не удалось установить сессию: {e.__class__.__name__}",
                                    operation_id=op, retryable=True)

    try:
        ok_adv = _repl_storage.replacement_advance(
            op, "auth_phone", "identity_ok", stage="identity_verified",
            fields={"new_username": actual_username, "new_tg_user_id": actual_user_id}, db_path=db_path,
        )
    except _repl_storage.ReplacementConflict:
        try:
            _tdimport_service.installer.rollback_install(install_result)
        except Exception:
            pass
        return _replacement_result(False, "identity_conflict", "Этот Telegram-аккаунт уже используется в другой операции замены.", operation_id=op)
    if not ok_adv:
        try:
            _tdimport_service.installer.rollback_install(install_result)
        except Exception:
            pass
        return _replacement_result(False, "stale_state", "Операция изменилась, начните заново.", operation_id=op)

    if tdi_work_root:
        try:
            _tdimport_service.cleanup.cleanup_work_root(tdi_work_root)
        except Exception:
            pass

    _manager_auth_audit_log("replacement_tdimport_commit", key, ok=1, admin_user_id=owner_uid)
    return _replacement_result(
        True, "identity_verified", "Личность подтверждена.", operation_id=op, next_step="ready_commit",
        tg_username=actual_username,
    )


# ---------------------------------------------------------------------------
# 5/6. Code + 2FA password submission, shared post-sign_in identity handling
# ---------------------------------------------------------------------------

async def _replacement_after_signin(
    operation_id: str, temp_client, *, db_path: Optional[str] = None, base_dir: Optional[Path] = None,
) -> Dict[str, Any]:
    """Shared post-sign_in handling for both the code and 2FA paths: verifies
    the temp session is genuinely authorized, fetches Telegram identity,
    checks every required conflict, then advances auth_code/auth_pass ->
    identity_ok (persisting new_tg_user_id -- Stage 2 fix R3 -- alongside
    new_username). Never creates a managers row. Never calls
    _manager_finalize_login. Always disconnects temp_client."""
    op_row = _repl_storage.replacement_get(operation_id, db_path=db_path)
    if not op_row:
        try:
            await temp_client.disconnect()
        except Exception:
            pass
        return _replacement_result(False, "missing_operation", "Операция не найдена.", operation_id=operation_id)

    status = str(op_row.get("status") or "")
    key = registry_normalize_manager_key(op_row.get("new_manager_key") or "")
    owner_uid = int(op_row.get("created_by_user_id") or 0)

    # Stage 2 fix R4: idempotent re-call -- identity was already verified and
    # persisted by an earlier call (e.g. a crash-then-retry that reconnects
    # to an already-authorized session and reaches here a second time).
    # identity_ok/ready_commit have no self-loop in the transition graph, so
    # this MUST short-circuit before ever calling replacement_advance again.
    if status in ("identity_ok", "ready_commit"):
        try:
            await temp_client.disconnect()
        except Exception:
            pass
        return _replacement_result(
            True, "identity_verified", "Личность уже подтверждена.", operation_id=operation_id,
            next_step="ready_commit" if status == "identity_ok" else "confirm_commit",
            tg_username=str(op_row.get("new_username") or ""),
        )

    try:
        authorized = await temp_client.is_user_authorized()
        me = await temp_client.get_me() if authorized else None
    except Exception:
        try:
            await temp_client.disconnect()
        except Exception:
            pass
        return _replacement_result(False, "verify_failed", "Ошибка проверки входа.", operation_id=operation_id, retryable=True)
    try:
        await temp_client.disconnect()
    except Exception:
        pass
    if not authorized or me is None:
        return _replacement_result(False, "not_authorized", "Временная сессия не авторизована.", operation_id=operation_id, retryable=True)

    actual_user_id = int(getattr(me, "id", 0) or 0)
    actual_username = str(getattr(me, "username", None) or "")
    actual_first = str(getattr(me, "first_name", None) or "")
    actual_last = str(getattr(me, "last_name", None) or "")

    if actual_user_id <= 0:
        await _replacement_fail(operation_id, "identity", "missing_tg_user_id", db_path=db_path, base_dir=base_dir,
                                 new_manager_key=key, owner_user_id=owner_uid)
        return _replacement_result(False, "missing_identity", "Telegram не вернул идентификатор аккаунта.", operation_id=operation_id)

    old_key = registry_normalize_manager_key(op_row.get("old_manager_key") or "")
    old_row = await manager_get(old_key)
    old_tg_user_id = int((old_row or {}).get("tg_user_id") or 0)
    if old_tg_user_id and old_tg_user_id == actual_user_id:
        await _replacement_fail(operation_id, "identity", "same_as_old_identity", db_path=db_path, base_dir=base_dir,
                                 new_manager_key=key, owner_user_id=owner_uid)
        return _replacement_result(False, "same_identity", "Новый аккаунт совпадает со старым.", operation_id=operation_id)

    conflict_key = await _replacement_tg_user_conflict(actual_user_id, db_path=db_path)
    if conflict_key and conflict_key != key:
        await _replacement_fail(operation_id, "identity", "tg_user_id_conflict", db_path=db_path, base_dir=base_dir,
                                 new_manager_key=key, owner_user_id=owner_uid)
        return _replacement_result(False, "identity_conflict", f"Этот Telegram-аккаунт уже привязан к менеджеру {conflict_key}.", operation_id=operation_id)

    # Stage 2 fix R3: database-backed cross-operation check on the durable
    # new_tg_user_id column (catches username-less accounts the
    # username-only check below cannot).
    other_op = await _replacement_tgid_reserved_by_other(actual_user_id, operation_id, db_path=db_path)
    if other_op:
        await _replacement_fail(operation_id, "identity", "tg_user_id_reserved_elsewhere", db_path=db_path, base_dir=base_dir,
                                 new_manager_key=key, owner_user_id=owner_uid)
        return _replacement_result(False, "identity_conflict", "Этот Telegram-аккаунт уже используется в другой операции замены.", operation_id=operation_id)

    if actual_username and await _replacement_username_conflict(actual_username, operation_id, db_path=db_path):
        await _replacement_fail(operation_id, "identity", "username_conflict", db_path=db_path, base_dir=base_dir,
                                 new_manager_key=key, owner_user_id=owner_uid)
        return _replacement_result(False, "identity_conflict", "Этот Telegram-аккаунт уже используется в другой операции замены.", operation_id=operation_id)

    # TPILOT AUTH SAFETY 20260809 (Ф3, D-QR): 'auth_phone' is a legal prior status
    # here too -- the QR replacement path (replacement_send_qr_start) never passes
    # through auth_code at all (no phone/code exchange), so it calls this same
    # function directly from 'auth_phone'. The existing phone-flow statuses
    # ('auth_code'/'auth_pass') are completely unaffected by this addition.
    if status == "auth_pass":
        from_status = "auth_pass"
    elif status == "auth_phone":
        from_status = "auth_phone"
    else:
        from_status = "auth_code"
    try:
        ok_adv = _repl_storage.replacement_advance(
            operation_id, from_status, "identity_ok", stage="identity_verified",
            fields={"new_username": actual_username, "new_tg_user_id": actual_user_id}, db_path=db_path,
        )
    except _repl_storage.ReplacementConflict:
        return _replacement_result(False, "identity_conflict", "Этот Telegram-аккаунт уже используется в другой операции замены.", operation_id=operation_id)
    if not ok_adv:
        return _replacement_result(False, "stale_state", "Операция изменилась, начните заново.", operation_id=operation_id)

    return _replacement_result(
        True, "identity_verified", "Личность подтверждена.", operation_id=operation_id, next_step="ready_commit",
        tg_username=actual_username, tg_first_name=actual_first, tg_last_name=actual_last,
    )


async def replacement_submit_code(
    operation_id: str, code: str, proxy_config: Optional[Dict[str, Any]] = None, *,
    db_path: Optional[str] = None, base_dir: Optional[Path] = None, client_factory=None,
) -> Dict[str, Any]:
    """Stage 2 fix B1: requires the DURABLE 'auth_code' status (set by
    replacement_send_phone_code only after Telegram genuinely accepted the
    code request) -- never 'auth_phone'. A correct code performs exactly ONE
    CAS transition (auth_code -> identity_ok, inside _replacement_after_
    signin); 2FA-required performs exactly ONE CAS transition (auth_code ->
    auth_pass). No public call ever double-advances through a transient
    marker.

    proxy_config is accepted for backward compatibility but IGNORED (Stage 2
    fix R2) -- the durable proxy route/credentials saved at send_phone_code
    time are always used instead, so a reconnect can never silently fall
    back to direct just because the caller didn't resupply it."""
    op = str(operation_id or "").strip()
    op_row = _repl_storage.replacement_get(op, db_path=db_path)
    if not op_row:
        return _replacement_result(False, "missing_operation", "Операция не найдена.", operation_id=op)
    if str(op_row.get("status")) != "auth_code":
        return _replacement_result(
            False, "wrong_state", "Операция не ожидает код.", operation_id=op,
            next_step=_replacement_next_step_for_status(str(op_row.get("status"))),
        )
    key = registry_normalize_manager_key(op_row.get("new_manager_key") or "")
    owner_uid = int(op_row.get("created_by_user_id") or 0)
    code_s = re.sub(r"\D+", "", str(code or "").strip())
    if not code_s:
        return _replacement_result(False, "empty_code", "Введите код Telegram цифрами.", operation_id=op)

    onboarding = await manager_get_onboarding(owner_uid)
    if (not onboarding or registry_normalize_manager_key(onboarding.get("manager_key") or "") != key
            or str(onboarding.get("step") or "") != _REPLACE_STEP_CODE):
        return _replacement_result(False, "no_pending_code", "Нет ожидающего кода. Начните заново.", operation_id=op)
    phone = str(onboarding.get("phone") or "").strip()
    phone_code_hash = str(onboarding.get("phone_code_hash") or "").strip()
    temp_path = str(onboarding.get("tmp_session_path") or "") or _replacement_temp_session_path(key, base_dir=base_dir)

    resolved_proxy, proxy_err = _replacement_resolve_durable_proxy(op_row, onboarding)
    if proxy_err:
        return proxy_err

    build_client = client_factory or (lambda session_path, cfg: _replacement_build_client(session_path, cfg))
    temp_client = None
    try:
        temp_client = build_client(temp_path, resolved_proxy)
        await temp_client.connect()
        # Stage 2 fix R4: Telegram may have already accepted the code on a
        # prior attempt that crashed before our own DB transition -- never
        # call sign_in a second time against an already-authorized session.
        if await temp_client.is_user_authorized():
            return await _replacement_after_signin(op, temp_client, db_path=db_path, base_dir=base_dir)
        await temp_client.sign_in(phone=phone, code=code_s, phone_code_hash=phone_code_hash)
    except SessionPasswordNeededError:
        try:
            await temp_client.disconnect()
        except Exception:
            pass
        # Code accepted by Telegram (sign_in didn't reject it) -- 2FA is
        # additionally required. Exactly one CAS transition.
        if not _repl_storage.replacement_advance(op, "auth_code", "auth_pass", stage="password_required", db_path=db_path):
            return _replacement_result(False, "stale_state", "Операция изменилась, начните заново.", operation_id=op)
        await manager_save_onboarding(
            owner_uid, manager_key=key, step=_REPLACE_STEP_PASS,
            phone=phone, phone_code_hash=phone_code_hash, tmp_session_path=temp_path,
            expires_at=_future_iso(MANAGER_ONBOARD_TIMEOUT_SEC),
            **_replacement_onboarding_proxy_fields(resolved_proxy, str(op_row.get("proxy_mode") or "direct")),
        )
        return _replacement_result(True, "password_required", "Нужен пароль 2FA.", operation_id=op, next_step="submit_password")
    except (PhoneCodeInvalidError, PhoneCodeExpiredError):
        try:
            await temp_client.disconnect()
        except Exception:
            pass
        # Retryable: status stays auth_code, temp session is NOT deleted --
        # the caller simply resubmits a corrected code against the same
        # pending request.
        return _replacement_result(False, "invalid_code", "Код неверный или истёк. Запросите новый код.", operation_id=op, retryable=True)
    except Exception as e:
        try:
            await temp_client.disconnect()
        except Exception:
            pass
        await _replacement_fail(op, "auth_code", e.__class__.__name__, db_path=db_path, base_dir=base_dir,
                                 new_manager_key=key, owner_user_id=owner_uid)
        return _replacement_result(False, "fatal_error", "Ошибка входа по коду.", operation_id=op)

    # sign_in succeeded fully (code valid, no 2FA needed) -- single CAS
    # (auth_code -> identity_ok) happens inside _replacement_after_signin.
    return await _replacement_after_signin(op, temp_client, db_path=db_path, base_dir=base_dir)


async def replacement_submit_password(
    operation_id: str, password: str, proxy_config: Optional[Dict[str, Any]] = None, *,
    db_path: Optional[str] = None, base_dir: Optional[Path] = None, client_factory=None,
) -> Dict[str, Any]:
    """proxy_config is accepted for backward compatibility but IGNORED (Stage
    2 fix R2) -- see replacement_submit_code's docstring; the durable proxy
    route/credentials saved at send_phone_code time are always used
    instead."""
    op = str(operation_id or "").strip()
    op_row = _repl_storage.replacement_get(op, db_path=db_path)
    if not op_row:
        return _replacement_result(False, "missing_operation", "Операция не найдена.", operation_id=op)
    if str(op_row.get("status")) != "auth_pass":
        return _replacement_result(
            False, "wrong_state", "Операция не ожидает пароль 2FA.", operation_id=op,
            next_step=_replacement_next_step_for_status(str(op_row.get("status"))),
        )
    key = registry_normalize_manager_key(op_row.get("new_manager_key") or "")
    owner_uid = int(op_row.get("created_by_user_id") or 0)
    pw = str(password or "")  # local only -- never persisted, never logged, never in any result/exception text
    if not pw:
        return _replacement_result(False, "empty_password", "Введите пароль 2FA.", operation_id=op)

    onboarding = await manager_get_onboarding(owner_uid)
    if (not onboarding or registry_normalize_manager_key(onboarding.get("manager_key") or "") != key
            or str(onboarding.get("step") or "") != _REPLACE_STEP_PASS):
        return _replacement_result(False, "no_pending_password", "Нет ожидающего запроса пароля. Начните заново.", operation_id=op)
    temp_path = str(onboarding.get("tmp_session_path") or "") or _replacement_temp_session_path(key, base_dir=base_dir)

    resolved_proxy, proxy_err = _replacement_resolve_durable_proxy(op_row, onboarding)
    if proxy_err:
        return proxy_err

    build_client = client_factory or (lambda session_path, cfg: _replacement_build_client(session_path, cfg))
    temp_client = None
    try:
        temp_client = build_client(temp_path, resolved_proxy)
        await temp_client.connect()
        # Stage 2 fix R4: Telegram may have already accepted the password on
        # a prior attempt that crashed before our own DB transition -- never
        # call sign_in a second time against an already-authorized session.
        if await temp_client.is_user_authorized():
            return await _replacement_after_signin(op, temp_client, db_path=db_path, base_dir=base_dir)
        await temp_client.sign_in(password=pw)
    except PasswordHashInvalidError:
        try:
            await temp_client.disconnect()
        except Exception:
            pass
        return _replacement_result(False, "wrong_password", "Неверный пароль 2FA.", operation_id=op, retryable=True)
    except Exception as e:
        try:
            await temp_client.disconnect()
        except Exception:
            pass
        await _replacement_fail(op, "auth_pass", e.__class__.__name__, db_path=db_path, base_dir=base_dir,
                                 new_manager_key=key, owner_user_id=owner_uid)
        return _replacement_result(False, "fatal_error", "Ошибка входа по 2FA.", operation_id=op)
    finally:
        pw = None

    return await _replacement_after_signin(op, temp_client, db_path=db_path, base_dir=base_dir)


# ---------------------------------------------------------------------------
# 7. Ready-to-commit: identity_ok -> ready_commit + safe preview
# ---------------------------------------------------------------------------

def _replacement_build_preview(op_row: Dict[str, Any]) -> Dict[str, Any]:
    """Only the fields explicitly approved for exposure -- never phone, code,
    password, proxy password, session path, manager DB path, or tg_user_id."""
    return _replacement_result(
        True, "ready_commit", "Готово к финальному подтверждению.",
        operation_id=str(op_row.get("operation_id") or ""), next_step="confirm_commit",
        preview={
            "old_display_name": op_row.get("old_display_name") or "",
            "old_username": op_row.get("old_username") or "",
            "new_display_name": op_row.get("new_display_name") or "",
            "new_username": op_row.get("new_username") or "",
            "source_key": op_row.get("source_key") or "",
            "target_date": op_row.get("target_date") or "",
            "session_status": "authorized",
            "status": op_row.get("status") or "",
        },
    )


async def replacement_ready_commit_preview(
    operation_id: str, *, db_path: Optional[str] = None, base_dir: Optional[Path] = None,
) -> Dict[str, Any]:
    op = str(operation_id or "").strip()
    op_row = _repl_storage.replacement_get(op, db_path=db_path)
    if not op_row:
        return _replacement_result(False, "missing_operation", "Операция не найдена.", operation_id=op)
    status = str(op_row.get("status") or "")
    if status == "ready_commit":
        return _replacement_build_preview(op_row)
    if status != "identity_ok":
        return _replacement_result(
            False, "wrong_state", "Операция ещё не готова к финальной проверке.", operation_id=op,
            next_step=_replacement_next_step_for_status(status),
        )

    key = registry_normalize_manager_key(op_row.get("new_manager_key") or "")
    if not key:
        return _replacement_result(False, "missing_key", "Не выбран новый ключ.", operation_id=op)
    if not str(op_row.get("new_display_name") or "").strip():
        return _replacement_result(False, "missing_display_name", "Не задано отображаемое имя.", operation_id=op)
    if int(op_row.get("new_tg_user_id") or 0) <= 0:
        return _replacement_result(False, "missing_identity", "Telegram-идентификатор не сохранён.", operation_id=op)

    base = base_dir if base_dir is not None else BASE_DIR
    temp_path = _replacement_temp_session_path(key, base_dir=base)
    if not os.path.exists(temp_path):
        return _replacement_result(False, "missing_temp_session", "Временная сессия не найдена.", operation_id=op)
    perm_path = _replacement_permanent_session_path(key, base_dir=base)
    if os.path.exists(perm_path):
        return _replacement_result(False, "permanent_session_conflict", "Постоянная session для нового ключа уже существует.", operation_id=op)

    old_key = registry_normalize_manager_key(op_row.get("old_manager_key") or "")
    old_row = await manager_get(old_key)
    if not old_row:
        return _replacement_result(False, "old_manager_missing", f"Старый менеджер {old_key} не найден.", operation_id=op)
    old_status = str(old_row.get("status") or "").strip().lower()
    if old_status in ("archived", "deleted"):
        return _replacement_result(False, "old_manager_gone", f"Старый менеджер {old_key} архивирован/удалён.", operation_id=op)

    if await _replacement_relogin_active(old_key):
        return _replacement_result(False, "relogin_active", "Для старого менеджера сейчас выполняется повторный вход.", operation_id=op)

    conflict_row = await manager_get(key)
    if conflict_row:
        return _replacement_result(False, "key_exists", f"Менеджер {key} уже существует.", operation_id=op)
    other = _repl_storage.replacement_get_by_new_key(key, db_path=db_path)
    if (other and str(other.get("operation_id")) != op
            and str(other.get("status")) not in _repl_storage.REPLACEMENT_TERMINAL_STATUSES):
        return _replacement_result(False, "key_conflict", f"Ключ {key} за��ят другой операцией.", operation_id=op)

    ok_adv = _repl_storage.replacement_advance(op, "identity_ok", "ready_commit", stage="ready_for_commit", db_path=db_path)
    if not ok_adv:
        return _replacement_result(False, "stale_state", "Операция изменилась, начните заново.", operation_id=op)
    op_row2 = _repl_storage.replacement_get(op, db_path=db_path)
    return _replacement_build_preview(op_row2)


# ---------------------------------------------------------------------------
# 8. Cancellation (pre-commit only -- storage.replacement_cancel enforces
#    the exact same rule Stage 1 already applies: never past 'committing').
# ---------------------------------------------------------------------------

async def _replacement_cancel_cleanup(
    op_row: Dict[str, Any], key: str, base: Path, client_factory, *, db_path: Optional[str] = None,
) -> None:
    """Best-effort cleanup for an operation that is ALREADY durably
    cancelled (Stage 2 fix R1: never called before that). Resolves the same
    durable proxy route every other Stage 2 reconnect uses (Stage 2 fix R2)
    for the logout attempt; never raises."""
    owner = int(op_row.get("created_by_user_id") or 0)
    onboarding = None
    if owner:
        try:
            onboarding = await manager_get_onboarding(owner)
        except Exception:
            onboarding = None

    if key:
        temp_path = _replacement_temp_session_path(key, base_dir=base)
        if os.path.exists(temp_path):
            resolved_proxy, _err = _replacement_resolve_durable_proxy(op_row, onboarding)
            build_client = client_factory or (lambda session_path, cfg: _replacement_build_client(session_path, cfg))
            temp_client = None
            try:
                temp_client = build_client(temp_path, resolved_proxy if resolved_proxy is not None else {})
                await temp_client.connect()
                if await temp_client.is_user_authorized():
                    try:
                        await temp_client.log_out()
                    except Exception:
                        pass
            except Exception:
                pass
            finally:
                if temp_client is not None:
                    try:
                        await temp_client.disconnect()
                    except Exception:
                        pass
        _replacement_cleanup_temp_files(key, base_dir=base)

    if owner and onboarding and registry_normalize_manager_key(onboarding.get("manager_key") or "") == key:
        try:
            await manager_delete_onboarding(owner)
        except Exception:
            pass


async def replacement_cancel(
    operation_id: str, proxy_config: Optional[Dict[str, Any]] = None, *,
    db_path: Optional[str] = None, base_dir: Optional[Path] = None, client_factory=None,
) -> Dict[str, Any]:
    """Stage 2 fix R1: cancellation persists 'cancelled' FIRST (Stage 1's
    CAS, restricted to the pre-commit statuses), and only THEN performs the
    destructive cleanup (best-effort logout + temp file deletion) -- the
    durable cancelled state is never lost even if cleanup itself fails. A
    non-cancellable operation (committing/links_pending/links_ready/
    cutover_done/notified/done) gets ZERO side effects: no logout, no
    disconnect, no file deletion, no onboarding mutation, no DB write --
    'done' in particular must never have a session that may have become the
    permanent manager session touched. 'failed' allows a bounded cleanup
    retry (this operation's own temp files only, no logout, no CAS -- it is
    already terminal) in case the original failure's own cleanup partially
    failed (e.g. a disk error).

    proxy_config is accepted for backward compatibility but IGNORED (Stage 2
    fix R2) -- cleanup resolves the durable proxy route instead."""
    op = str(operation_id or "").strip()
    op_row = _repl_storage.replacement_get(op, db_path=db_path)
    if not op_row:
        return _replacement_result(False, "missing_operation", "Операция не найдена.", operation_id=op)

    status = str(op_row.get("status") or "")
    key = registry_normalize_manager_key(op_row.get("new_manager_key") or "")
    base = base_dir if base_dir is not None else BASE_DIR

    if status == "cancelled":
        await _replacement_cancel_cleanup(op_row, key, base, client_factory, db_path=db_path)
        return _replacement_result(True, "already_cancelled", "Операция уже отменена.", operation_id=op)

    if status == "failed":
        if key:
            _replacement_cleanup_temp_files(key, base_dir=base)
        owner = int(op_row.get("created_by_user_id") or 0)
        if owner:
            try:
                onboarding = await manager_get_onboarding(owner)
                if onboarding and registry_normalize_manager_key(onboarding.get("manager_key") or "") == key:
                    await manager_delete_onboarding(owner)
            except Exception:
                pass
        return _replacement_result(False, "cannot_cancel", "Операция уже завершена с ошибкой.", operation_id=op)

    if status not in _repl_storage._REPLACEMENT_PRE_COMMIT_STATUSES:
        return _replacement_result(False, "cancellation_not_allowed", "Операцию нельзя отменить в текущем состоянии.", operation_id=op)

    # Pre-commit and genuinely cancellable: persist 'cancelled' FIRST.
    ok = _repl_storage.replacement_cancel(op, db_path=db_path)
    if not ok:
        # Race: status moved on between our read above and this CAS.
        row_after = _repl_storage.replacement_get(op, db_path=db_path)
        if row_after and str(row_after.get("status")) == "cancelled":
            await _replacement_cancel_cleanup(row_after, key, base, client_factory, db_path=db_path)
            return _replacement_result(True, "already_cancelled", "Операция уже отменена.", operation_id=op)
        return _replacement_result(False, "cannot_cancel", "Операцию нельзя отменить в текущем состоянии.", operation_id=op)

    # Cancellation is now durable regardless of what happens below.
    await _replacement_cancel_cleanup(op_row, key, base, client_factory, db_path=db_path)
    return _replacement_result(True, "cancelled", "Операция замены отменена. Старый менеджер не изменён.", operation_id=op)


# ---------------------------------------------------------------------------
# 9. Restart-safe recovery / inspection (no automatic Telegram reconnect)
# ---------------------------------------------------------------------------

async def replacement_recover(
    operation_id: str, *, db_path: Optional[str] = None, base_dir: Optional[Path] = None,
) -> Dict[str, Any]:
    op = str(operation_id or "").strip()
    op_row = _repl_storage.replacement_get(op, db_path=db_path)
    if not op_row:
        return _replacement_result(False, "missing_operation", "Операция не найде��а.", operation_id=op, next_step="unknown")

    status = str(op_row.get("status") or "")
    key = registry_normalize_manager_key(op_row.get("new_manager_key") or "")
    base = base_dir if base_dir is not None else BASE_DIR

    temp_exists = False
    perm_exists = False
    if key:
        try:
            temp_exists = os.path.exists(_replacement_temp_session_path(key, base_dir=base))
            perm_exists = os.path.exists(_replacement_permanent_session_path(key, base_dir=base))
        except ValueError:
            pass

    old_key = registry_normalize_manager_key(op_row.get("old_manager_key") or "")
    old_row = await manager_get(old_key)
    old_exists = old_row is not None

    key_conflict = False
    if key:
        conflict_row = await manager_get(key)
        key_conflict = conflict_row is not None

    next_step = _replacement_next_step_for_status(status)
    # auth_phone deliberately excluded (Stage 2 fix B1): it can be durably
    # entered BEFORE any Telegram connect() ever happens (the CAS now runs
    # before the network call), so a missing temp session there is normal
    # and simply means "call replacement_send_phone_code again" -- never a
    # dead end requiring cleanup. auth_code/auth_pass are only ever reached
    # AFTER a successful connect(), so a missing temp session there is a
    # genuine inconsistency.
    if status in ("auth_code", "auth_pass") and not temp_exists:
        next_step = "cleanup_required"
    if perm_exists and status != "done":
        next_step = "cleanup_required"

    return _replacement_result(
        True, "recovered", "Состояние операции получено.", operation_id=op, next_step=next_step,
        status=status, temp_session_exists=temp_exists, permanent_session_exists=perm_exists,
        old_manager_exists=old_exists, key_conflict=key_conflict,
    )
# --- TPILOT MANAGER REPLACEMENT STAGE2 20260715 END ---


# --- TPILOT MANAGER REPLACEMENT STAGE3 ADMINBOT 20260716 START ---
# AdminBot wizard wiring for the Stage 2 fresh-session replacement backend
# (accepted 100%, 2026-07-15). panel_bot.py and this controller run as
# SEPARATE PROCESSES that only talk through the panel_commands queue (see
# _submit_and_wait / _panel_command_loop) -- there is no direct import path,
# so every /manager_replace_* command below is a thin, ownership-checked
# adapter that decodes the small number of base64-wrapped free-text/JSON
# arguments panel_bot.py must pass through the single-line panel_commands
# text channel, and calls the REAL, unmodified Stage 2 replacement_*
# functions. Never creates a managers row, never calls replacement_finalize --
# Stage 2's own guarantees are unchanged by this block; it only exposes them.
# COMMIT WIRING 20260716: /manager_replace_commit (added after the Stage 4
# engine was accepted) is the ONE command that goes past ready_commit -- and
# it too is a thin adapter: all cutover logic lives in replacement_commit.

import base64 as _repl3_base64
import json as _repl3_json


def _repl3_b64_encode(text: str) -> str:
    return _repl3_base64.urlsafe_b64encode(str(text or "").encode("utf-8")).decode("ascii")


def _repl3_b64_decode(token: str) -> str:
    try:
        return _repl3_base64.urlsafe_b64decode(str(token or "").encode("ascii")).decode("utf-8")
    except Exception:
        return ""


def _repl3_json_result(payload: Dict[str, Any]) -> str:
    """Every /manager_replace_* command returns a JSON-encoded Stage 2
    result dict as result_text -- panel_bot.py branches on ok/code/
    next_step, never parses the Russian message prose (matches
    _replacement_result's own documented contract)."""
    try:
        return _repl3_json.dumps(payload, ensure_ascii=False)
    except Exception:
        return _repl3_json.dumps(_replacement_result(False, "internal_error", "Внутренняя ошибка."), ensure_ascii=False)


async def _repl3_owned_op_or_error(operation_id: str, requested_by: int) -> Tuple[bool, Optional[Dict[str, Any]], str]:
    """Single ownership choke-point for every /manager_replace_* command
    except start/recover_for_old_key: loads the operation and verifies
    requested_by is its initiating admin. Returns the SAME missing_
    operation-shaped error for both a nonexistent and a foreign operation_id
    so a forged/guessed id can never distinguish the two, and no other admin
    can ever continue/cancel/mutate someone else's replacement."""
    op = str(operation_id or "").strip()
    row = _repl_storage.replacement_get(op) if op else None
    if not row or int(row.get("created_by_user_id") or 0) != int(requested_by or 0):
        return False, None, _repl3_json_result(
            _replacement_result(False, "missing_operation", "Операция не найдена.", operation_id=op)
        )
    return True, row, ""


async def _panel_manager_replace_start_command(args: str, *, requested_by: int = 0) -> str:
    """AdminBot re-taps '🔄 Заменить аккаунт'/'▶️ Начать замену' on every
    entry, with no durable token to resupply yet -- so this command must
    reproduce replacement_start's own idempotency itself: if a non-terminal
    operation for old_key already exists AND belongs to THIS admin, pass ITS
    operation_id through explicitly (otherwise replacement_start's
    existing_active check, comparing against a FRESH random uuid every
    call, would reject the admin's own second tap as 'already_active').
    An operation owned by a DIFFERENT admin must NEVER be passed through --
    replacement_create()'s own operation_id-idempotency would otherwise
    silently hand back a foreign operation as if it were newly created."""
    old_key = registry_normalize_manager_key(str(args or "").strip())
    if not old_key:
        return _repl3_json_result(_replacement_result(False, "invalid_old_key", "Некорректный manager_key."))
    existing = _repl_storage.replacement_get_active_for_old_key(old_key)
    op_id = ""
    if existing and int(existing.get("created_by_user_id") or 0) == int(requested_by or 0):
        op_id = str(existing.get("operation_id") or "")
    res = await replacement_start(old_key, int(requested_by or 0), operation_id=op_id)
    return _repl3_json_result(res)


async def _panel_manager_replace_recover_for_old_key_command(args: str, *, requested_by: int = 0) -> str:
    """Read-only: does old_key have a non-terminal replacement operation,
    and if so, is it owned by the CURRENT admin? No network, no mutation --
    used by the manager card to decide whether to show '🔄 Продолжить
    замену' (only ever for the operation's own owner; Stage 3 forbids
    cross-admin continuation)."""
    old_key = registry_normalize_manager_key(str(args or "").strip())
    if not old_key:
        return _repl3_json_result({"ok": True, "active": False})
    row = _repl_storage.replacement_get_active_for_old_key(old_key)
    if not row:
        return _repl3_json_result({"ok": True, "active": False})
    owner = int(row.get("created_by_user_id") or 0)
    return _repl3_json_result({
        "ok": True, "active": True, "operation_id": str(row.get("operation_id") or ""),
        "status": str(row.get("status") or ""), "owned_by_caller": owner == int(requested_by or 0),
    })


