async def _panel_manager_replace_proxy_pool_pick_command(args: str, *, requested_by: int = 0) -> str:
    """Read-only pool-lease credential fetch -- NEVER assigns/mutates the
    lease. Stage 3 creates no managers row, so /proxy_pool_assign's real
    assignment bookkeeping is intentionally deferred to the (future) commit
    stage; this command only reports the lease's connection fields plus
    whether it already has an owner, so panel_bot.py can show a multi-use
    confirmation before folding it into the wizard's pending proxy_config."""
    from storage import proxy_lease_get as _repl3_lease_get, proxy_lease_to_manager_proxy_fields as _repl3_lease_to_fields
    parts = str(args or "").strip().split(None, 1)
    op_id = parts[0] if parts else ""
    lease_id_raw = parts[1] if len(parts) > 1 else ""
    ok, _row, err = await _repl3_owned_op_or_error(op_id, requested_by)
    if not ok:
        return err
    try:
        lease_id = int(lease_id_raw)
    except Exception:
        return _repl3_json_result(_replacement_result(False, "bad_request", "Некорректный proxy.", operation_id=op_id))
    lease = await _repl3_lease_get(lease_id)
    if not lease:
        return _repl3_json_result(_replacement_result(False, "lease_not_found", "Прокси не найден в пуле.", operation_id=op_id))
    fields = _repl3_lease_to_fields(lease)
    already_used = bool(str(lease.get("manager_key") or "").strip())
    return _repl3_json_result(_replacement_result(
        True, "lease_ok", "Прокси найден.", operation_id=op_id,
        already_used=already_used, used_by=str(lease.get("manager_key") or ""),
        proxy_config=fields,
    ))


async def _panel_manager_replace_proxy_manual_command(args: str, *, requested_by: int = 0) -> str:
    """Validates a manually-pasted proxy LINE with the SAME parser the
    existing add-manager manual-proxy step uses (proxy_parser.parse_proxy_
    line) and returns the resolved proxy_config -- does NOT persist
    anything (Stage 2 only ever commits durable proxy state inside
    replacement_send_phone_code's own draft->auth_phone CAS)."""
    parts = str(args or "").strip().split(None, 1)
    op_id = parts[0] if parts else ""
    line_b64 = parts[1] if len(parts) > 1 else ""
    ok, _row, err = await _repl3_owned_op_or_error(op_id, requested_by)
    if not ok:
        return err
    line = _repl3_b64_decode(line_b64)
    parsed = proxy_parser.parse_proxy_line(line)
    if not parsed:
        return _repl3_json_result(_replacement_result(False, "proxy_parse_failed", "Не удалось распознать proxy.", operation_id=op_id))
    valid, verr = proxy_parser.validate_proxy_fields(parsed.get("host"), parsed.get("port"), parsed.get("scheme") or "socks5")
    if not valid:
        return _repl3_json_result(_replacement_result(False, "proxy_invalid", verr or "Некорректный proxy.", operation_id=op_id))
    proxy_config = {
        "proxy_enabled": 1, "proxy_mode": "proxy",
        "proxy_type": parsed.get("scheme") or "socks5",
        "proxy_host": parsed.get("host") or "",
        "proxy_port": parsed.get("port"),
        "proxy_username": parsed.get("login") or "",
        "proxy_password": parsed.get("password") or "",
    }
    return _repl3_json_result(_replacement_result(True, "proxy_ok", "Proxy распознан.", operation_id=op_id, proxy_config=proxy_config))


async def _panel_manager_replace_commit_command(args: str, *, requested_by: int = 0) -> str:
    """COMMIT WIRING 20260716: the final-confirm adapter. Thin by design --
    ALL commit/cutover logic stays in the Stage 4 replacement_commit engine
    (defined later in this module; resolved at call time, so the dispatch
    table below can reference this handler safely at import time).

    Ownership goes through the same _repl3_owned_op_or_error choke-point as
    every other op-scoped command (forged/foreign operation_id -> the
    indistinguishable missing_operation error). Only the operation_id is
    accepted from the caller -- old/new manager keys, phase state and every
    other decision input come exclusively from the durable operation row,
    never from panel-supplied text. Statuses outside
    ready_commit/committing/links_pending/links_ready/cutover_done/notified/
    done are rejected here with wrong_state (the engine would reject them
    too -- this pre-check just avoids entering the engine for auth-stage
    operations at all). Duplicate/repeated calls are safe: the engine
    re-enters at the CURRENT durable status (resume) and returns
    already_cutover for cutover_done/notified/done, never starting a second
    replacement. The engine result dict is already secret-free
    (_repl4_result's own contract); it is passed through verbatim."""
    op_id = str(args or "").strip()
    ok, row, err = await _repl3_owned_op_or_error(op_id, requested_by)
    if not ok:
        return err
    status = str((row or {}).get("status") or "")
    commit_reachable = ("ready_commit", "committing", "links_pending", "links_ready",
                        "cutover_done", "notified", "done")
    if status not in commit_reachable:
        return _repl3_json_result(_repl4_result(
            False, "wrong_state", "Операция не готова к переключению.", op_id, row,
            next_step=_replacement_next_step_for_status(status),
        ))
    try:
        res = await replacement_commit(op_id, created_by_user_id=int(requested_by or 0))
    except Exception as exc:
        # Bounded diagnostics only -- no SQL/exception text reaches the panel.
        try:
            print(f"[replace-commit] engine error op={op_id[:12]} err={exc.__class__.__name__}")
        except Exception:
            pass
        res = _repl4_result(False, "internal_error", "Внутренняя ошибка при переключении. Повторите позже.",
                            op_id, row, retryable=True)
    return _repl3_json_result(res)


_REPL3_PREV_PANEL_EXEC = globals().get("_panel_execute_command_text")

_REPL3_DISPATCH = {
    "/manager_replace_start": _panel_manager_replace_start_command,
    "/manager_replace_recover_for_old_key": _panel_manager_replace_recover_for_old_key_command,
    "/manager_replace_key_check": _panel_manager_replace_key_check_command,
    "/manager_replace_send_phone": _panel_manager_replace_send_phone_command,
    "/manager_replace_submit_code": _panel_manager_replace_submit_code_command,
    "/manager_replace_submit_password": _panel_manager_replace_submit_password_command,
    "/manager_replace_ready_preview": _panel_manager_replace_ready_preview_command,
    "/manager_replace_cancel": _panel_manager_replace_cancel_command,
    "/manager_replace_recover": _panel_manager_replace_recover_command,
    "/manager_replace_proxy_pool_pick": _panel_manager_replace_proxy_pool_pick_command,
    "/manager_replace_proxy_manual": _panel_manager_replace_proxy_manual_command,
    "/manager_replace_commit": _panel_manager_replace_commit_command,
}


async def _panel_execute_command_text(  # type: ignore[override]
    command_text: str, *, requested_by: int = 0, source_chat_id: int = 0, response_chat_id: int = 0
) -> Dict[str, Any]:
    cmd, args = _parse_cmd(str(command_text or ""))
    handler = _REPL3_DISPATCH.get(cmd)
    if handler is not None:
        return {"ok": True, "result_text": await handler(args, requested_by=requested_by)}
    if callable(_REPL3_PREV_PANEL_EXEC):
        try:
            return await _REPL3_PREV_PANEL_EXEC(command_text, requested_by=requested_by, source_chat_id=source_chat_id, response_chat_id=response_chat_id)
        except TypeError:
            try:
                return await _REPL3_PREV_PANEL_EXEC(command_text, requested_by=requested_by)
            except TypeError:
                return await _REPL3_PREV_PANEL_EXEC(command_text)
    return {"ok": False, "result_text": f"Команда не поддерживается: {cmd}"}
# --- TPILOT MANAGER REPLACEMENT STAGE3 ADMINBOT 20260716 END ---


# ---------------------------------------------------------------------------
# --- TPILOT MANAGER REPLACEMENT STAGE4 COMMIT ENGINE 20260716 START ---
#
# Implements the atomic commit/cutover engine: ready_commit -> committing ->
# links_pending -> links_ready -> cutover_done. Deliberately stops there --
# notified/done belong to a later stage (PartnerBot notification, then the
# already-existing guarded storage.replacement_finalize()).
#
# Restart-safety model: every substep re-verifies LIVE DB/filesystem state
# before acting (idempotent primitives) rather than trusting a stored flag.
# _repl_storage.replacement_set_stage() (new, storage.py) records a short
# diagnostic marker for progress reporting/observability only -- it is never
# the sole guard against redoing a destructive step.
#
# Reused, unmodified production primitives: _manager_finalize_login,
# manager_add, manager_set_fields, manager_get, manager_get_onboarding,
# _spawn_manager_process, _stop_manager_process, _manager_process_running,
# _manager_delete_full_core (newly extracted below from
# _panel_manager_delete_full_command -- identical logic, just callable
# without an admin's plaintext danger-password), _queue_bizlink_create_n_for_manager,
# build_manager_paths, ensure_manager_dirs, _replacement_temp_session_path,
# _replacement_permanent_session_path, _replacement_cleanup_temp_files,
# _replacement_build_client, _replacement_resolve_durable_proxy,
# _replacement_tg_user_conflict, _replacement_tgid_reserved_by_other,
# _replacement_relogin_active, _replacement_next_step_for_status,
# _replacement_result, _kyiv_now, registry_normalize_manager_key.
# New storage.py additions (additive only, no schema change):
# replacement_set_stage, reserve_pairs_reassign_primary.
# ---------------------------------------------------------------------------

_REPL4_COMMIT_PHASE_STATUSES = ("committing", "links_pending", "links_ready")

# TPILOT C/F 20260718: bounded backstop for the whole pre-cutover commit
# window (spawn + full readiness + 15 link creates + retries). A background
# sweeper (task F) auto-rolls-back any op still in _REPL4_COMMIT_PHASE_STATUSES
# past commit_deadline_at -- this is the "link failure beyond retry policy" /
# "commit-deadline expiry" trigger from plan §16-C, distinct from a single
# manager_runtime_ready() call's own much shorter internal poll deadline.
_REPL4_COMMIT_DEADLINE_SEC = 1800

# TPILOT FIX-4 20260718b: durable cutover point-of-no-return. Once the
# durable 'stage' column (still status='links_ready') reaches one of these
# values, cutover has begun mutating the old manager and MUST NEVER be
# rolled back -- _repl4_rollback refuses (see its guard), the deadline
# sweeper's own SQL excludes these stages, and replacement_commit skips
# _repl4_final_revalidate on resume (its old_manager_missing check would
# otherwise strand a resumed cutover -- the exact stranding bug this fixes).
# "cutover_started" is persisted BEFORE the first irreversible mutation
# (old manager disable); "old_manager_retired" after the old manager is
# confirmed gone -- both are forward-only, idempotent resume markers.
_REPL_CUTOVER_IRREVERSIBLE_STAGES = ("cutover_started", "old_manager_retired")


def _repl4_progress(op_row: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "stage": str((op_row or {}).get("stage") or ""),
        "links_ready": int((op_row or {}).get("ready_links") or 0),
        "links_required": int((op_row or {}).get("required_links") or 0),
    }


def _repl4_result(ok: bool, code: str, message: str, operation_id: str, op_row: Optional[Dict[str, Any]] = None,
                   *, next_step: str = "", retryable: bool = False,
                   manual_recovery_required: bool = False, **extra: Any) -> Dict[str, Any]:
    """The one structured-result shape every Stage 4 function returns.
    Never includes phone/code/2FA password/proxy credentials/session paths/
    DB paths/tg_user_id/raw SQL errors -- only safe, pre-bounded fields."""
    out = _replacement_result(ok, code, message, operation_id=str(operation_id or ""),
                               next_step=next_step, retryable=retryable)
    out["status"] = str((op_row or {}).get("status") or "")
    out["manual_recovery_required"] = bool(manual_recovery_required)
    out["progress"] = _repl4_progress(op_row or {})
    out.update(extra)
    return out


async def _repl4_links_ready_count(new_key: str, target_date: str) -> int:
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        try:
            cur = await db.execute(
                "SELECT COUNT(*) FROM bizlinks WHERE manager_key=? AND target_date=? AND status='created' AND link_url<>''",
                (new_key, target_date),
            )
            row = await cur.fetchone()
        except Exception:
            # bizlinks is created by the (separate, pre-existing) business-
            # link subsystem on first real use -- a brand-new deployment
            # where it hasn't run yet must fail closed (0 ready), never
            # raise or false-positive "ready".
            return 0
        return int(row[0] or 0) if row else 0


async def _repl4_transfer_settings(old_key: str, new_key: str) -> None:
    """Copies only the approved current operational settings this project
    actually models on top of what manager_add already sets (owner_user_id,
    which the caller passes at row-creation time): source assignment and
    per-manager screenshot reminder preferences. Never touches historical
    data, old Telegram identity, or deletion/tombstone state. Idempotent
    UPSERT -- safe to call repeatedly."""
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        cur = await db.execute("SELECT source_key FROM manager_source_links WHERE manager_key=?", (old_key,))
        src_row = await cur.fetchone()
        source_key = str(src_row[0] or "") if src_row else ""
        now = _now_utc_iso()
        if source_key:
            await db.execute(
                "INSERT INTO manager_source_links(manager_key, source_key, created_at, updated_at) VALUES(?,?,?,?)"
                " ON CONFLICT(manager_key) DO UPDATE SET source_key=excluded.source_key, updated_at=excluded.updated_at",
                (new_key, source_key, now, now),
            )
        # Same schema _tp_finalize_screenshots_on already creates -- CREATE
        # TABLE IF NOT EXISTS here is safe/idempotent regardless of whether
        # that function has run yet for the new manager.
        await db.execute(
            "CREATE TABLE IF NOT EXISTS manager_screenshot_config("
            "manager_key TEXT PRIMARY KEY, require_screenshots INTEGER NOT NULL DEFAULT 0,"
            " mode TEXT NOT NULL DEFAULT 'off', reminder_enabled INTEGER NOT NULL DEFAULT 1,"
            " reminder_time TEXT NOT NULL DEFAULT '16:50', last_reminder_date TEXT NOT NULL DEFAULT '',"
            " updated_at TEXT NOT NULL DEFAULT '')"
        )
        cur2 = await db.execute(
            "SELECT reminder_enabled, reminder_time FROM manager_screenshot_config WHERE manager_key=?", (old_key,)
        )
        srow = await cur2.fetchone()
        reminder_enabled = int(srow[0]) if srow and srow[0] is not None else 1
        reminder_time = str(srow[1] or "16:50") if srow else "16:50"
        await db.execute(
            "INSERT INTO manager_screenshot_config(manager_key, require_screenshots, mode, reminder_enabled, reminder_time, updated_at)"
            " VALUES(?,1,'instant',?,?,?)"
            " ON CONFLICT(manager_key) DO UPDATE SET reminder_enabled=excluded.reminder_enabled,"
            " reminder_time=excluded.reminder_time, updated_at=excluded.updated_at",
            (new_key, reminder_enabled, reminder_time, now),
        )
        await db.commit()


async def _repl4_transfer_schedule(old_key: str, new_key: str, target_date: str) -> int:
    """Copies today+future explicit schedule rows (work_date >= target_date)
    from old_key to new_key. Historical rows (work_date < target_date) are
    NEVER touched or copied -- they remain attached to old_manager_key
    exactly as required. Idempotent UPSERT keyed on (manager_key, work_date)
    -- repeated execution never duplicates rows."""
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        cur = await db.execute(
            "SELECT work_date, is_working, source FROM manager_work_schedule_days"
            " WHERE manager_key=? AND work_date>=?", (old_key, str(target_date)),
        )
        rows = await cur.fetchall()
        now = _now_utc_iso()
        for work_date, is_working, source in rows:
            await db.execute(
                "INSERT INTO manager_work_schedule_days(manager_key, work_date, is_working, source, updated_at)"
                " VALUES(?,?,?,?,?)"
                " ON CONFLICT(manager_key, work_date) DO UPDATE SET is_working=excluded.is_working,"
                " source=excluded.source, updated_at=excluded.updated_at",
                (new_key, work_date, int(is_working or 0), str(source or ""), now),
            )
        await db.commit()
        return len(rows)


async def _repl4_transfer_access_groups(old_key: str, new_key: str) -> None:
    """Copies current group memberships (manager_group_members) and
    non-revoked ManagerBot access grants (manager_bot_access) from old_key
    to new_key. INSERT OR IGNORE on both -- repeated execution never
    duplicates a row; unrelated managers/groups are never touched.
    event_cutoff_id is deliberately NOT copied (reset to 0 via the column
    default) -- it tracks stats-event pagination for the OLD manager's own
    history, which does not apply to a manager with no events yet."""
    async with aiosqlite.connect(TPILOT_DB_PATH) as db:
        cur = await db.execute("SELECT group_key FROM manager_group_members WHERE manager_key=?", (old_key,))
        groups = [r[0] for r in await cur.fetchall()]
        now = _now_utc_iso()
        for group_key in groups:
            await db.execute(
                "INSERT OR IGNORE INTO manager_group_members(group_key, manager_key, created_at) VALUES(?,?,?)",
                (group_key, new_key, now),
            )
        try:
            cur2 = await db.execute(
                "SELECT tg_user_id, can_receive_cards, can_set_status, can_view_stats, stats_format,"
                " allow_custom_period, auto_granted, granted_by FROM manager_bot_access"
                " WHERE manager_key=? AND revoked=0", (old_key,),
            )
            access_rows = await cur2.fetchall()
        except Exception:
            access_rows = []
        for (tg_user_id, can_cards, can_status, can_stats, stats_format, allow_custom, auto_granted, granted_by) in access_rows:
            try:
                await db.execute(
                    "INSERT OR IGNORE INTO manager_bot_access"
                    "(tg_user_id, manager_key, can_receive_cards, can_set_status, can_view_stats, stats_format,"
                    " allow_custom_period, auto_granted, granted_by, granted_at, revoked, event_cutoff_id, created_at)"
                    " VALUES(?,?,?,?,?,?,?,?,?,?,0,0,?)",
                    (tg_user_id, new_key, can_cards, can_status, can_stats, stats_format,
                     allow_custom, auto_granted, granted_by, now, now),
                )
            except Exception:
                pass
        await db.commit()


async def _repl4_assign_proxy(op_row: Dict[str, Any], new_key: str) -> Optional[Dict[str, Any]]:
    """Uses the exact durable proxy route Stage 2 resolved and confirmed
    (never the old manager's own proxy, never a caller-resupplied value).
    Idempotent -- if the new manager's row already carries this exact
    host/port, no-op. Direct mode assigns nothing (correct -- 'direct' means
    no proxy). Best-effort links the pool lease (if proxy_ref is a lease id)
    so the pool's own usage bookkeeping stays accurate; never a real
    provider call, never a new allow_spend=True."""
    op = str(op_row.get("operation_id") or "")
    owner_uid = int(op_row.get("created_by_user_id") or 0)
    onboarding = await manager_get_onboarding(owner_uid) if owner_uid else None
    resolved_proxy, proxy_err = _replacement_resolve_durable_proxy(op_row, onboarding)
    if proxy_err:
        return proxy_err
    if not resolved_proxy:
        return None  # direct mode -- nothing to assign
    current = await manager_get(new_key) or {}
    if (str(current.get("proxy_host") or "") == str(resolved_proxy.get("proxy_host") or "")
            and current.get("proxy_port") == resolved_proxy.get("proxy_port")
            and int(current.get("proxy_enabled") or 0) == 1):
        return None  # already assigned (idempotent resume)
    fields = dict(resolved_proxy)
    fields["proxy_required"] = 1
    await manager_set_fields(new_key, **fields)
    proxy_ref = str(op_row.get("proxy_ref") or "").strip()
    if proxy_ref.isdigit():
        try:
            await _repl_storage.proxy_lease_assign_to_manager(int(proxy_ref), new_key)
        except Exception:
            pass
    return None


async def _repl4_promote_session(op_row: Dict[str, Any], old_row: Dict[str, Any], new_key: str, base: Path,
                                  *, client_factory=None) -> Optional[Dict[str, Any]]:
    """Idempotent: if the permanent session already exists, this is a no-op
    (already promoted by an earlier attempt) -- os.replace is a single
    atomic syscall on the same filesystem, so there is no partial-move state
    to detect: either the permanent path exists (done) or it doesn't
    (never attempted / needs retry), never both/neither ambiguously."""
    op = str(op_row.get("operation_id") or "")
    perm_path = _replacement_permanent_session_path(new_key, base_dir=base)
    if os.path.exists(perm_path):
        return None
    temp_path = _replacement_temp_session_path(new_key, base_dir=base)
    if not os.path.exists(temp_path):
        return _repl4_result(False, "missing_temp_session", "Временная сессия не найдена.", op, op_row)
    if os.path.abspath(temp_path) == os.path.abspath(perm_path):
        return _repl4_result(False, "session_path_conflict", "Временный и постоянный путь сессии совпадают.", op, op_row, manual_recovery_required=True)
    old_session_path = str(old_row.get("session_path") or "")
    if old_session_path and os.path.abspath(old_session_path) in (os.path.abspath(temp_path), os.path.abspath(perm_path)):
        return _repl4_result(False, "session_path_conflict", "Путь сессии совпадает со старой сессией.", op, op_row, manual_recovery_required=True)

    owner_uid = int(op_row.get("created_by_user_id") or 0)
    onboarding = await manager_get_onboarding(owner_uid) if owner_uid else None
    resolved_proxy, proxy_err = _replacement_resolve_durable_proxy(op_row, onboarding)
    if proxy_err:
        return proxy_err

    build_client = client_factory or (lambda session_path, cfg: _replacement_build_client(session_path, cfg))
    temp_client = None
    me = None
    authorized = False
    try:
        temp_client = build_client(temp_path, resolved_proxy)
        await temp_client.connect()
        authorized = await temp_client.is_user_authorized()
        me = await temp_client.get_me() if authorized else None
    except Exception:
        me = None
        authorized = False
    finally:
        if temp_client is not None:
            try:
                await temp_client.disconnect()
            except Exception:
                pass
    if not authorized or me is None:
        return _repl4_result(False, "not_authorized", "Временная сессия не авторизована.", op, op_row, retryable=True)

    actual_id = int(getattr(me, "id", 0) or 0)
    expected_id = int(op_row.get("new_tg_user_id") or 0)
    if actual_id <= 0 or actual_id != expected_id:
        return _repl4_result(False, "identity_mismatch", "Личность временной сессии не совпадает с операцией.", op, op_row, manual_recovery_required=True)

    try:
        for suffix in ("", "-journal", "-wal", "-shm"):
            src = temp_path + suffix
            if os.path.exists(src):
                dst = perm_path + suffix
                if os.path.exists(dst):
                    return _repl4_result(False, "permanent_session_conflict", "Постоянная session уже существует.", op, op_row, manual_recovery_required=True)
                os.replace(src, dst)
    except Exception as e:
        return _repl4_result(False, "session_move_failed", f"Не удалось перенести файл сессии: {e.__class__.__name__}", op, op_row, retryable=True)
    return None


async def _repl4_create_new_manager(op_row: Dict[str, Any], old_row: Dict[str, Any], new_key: str,
                                     created_by_user_id: int, base: Path, *, client_factory=None) -> Optional[Dict[str, Any]]:
    """Creates the new managers row via the real manager_add() primitive
    (never a wholesale clone of old_row -- no historical stats, no old
    Telegram identity, no old session, no deletion state copied), then
    writes identity fields via _manager_finalize_login (spawn_after_login=
    False -- Stage 4 controls runtime start separately, in the runtime-
    validation phase). Idempotent: if a matching row already exists AND is
    durably reserved to THIS operation (proven via ux_repl_new_key through
    replacement_get_by_new_key), this is a no-op."""
    op = str(op_row.get("operation_id") or "")
    existing = await manager_get(new_key)
    if existing:
        other = _repl_storage.replacement_get_by_new_key(new_key)
        if not other or str(other.get("operation_id")) != op:
            return _repl4_result(False, "key_exists", f"Ключ {new_key} занят другим менеджером.", op, op_row, manual_recovery_required=True)
        expected_tgid = int(op_row.get("new_tg_user_id") or 0)
        if existing.get("tg_user_id") and expected_tgid and int(existing["tg_user_id"]) != expected_tgid:
            return _repl4_result(False, "identity_mismatch", "Идентификатор нового менеджера не совпадает с операцией.", op, op_row, manual_recovery_required=True)
        return None  # already created (+ finalized, best-effort)

    paths = build_manager_paths(str(base), new_key)
    os.makedirs(paths["root"], exist_ok=True)
    display_name = str(op_row.get("new_display_name") or "").strip() or new_key

    # TPILOT RUNTIME AUTH SESSION-REUSE FIX 20260718: fetch the onboarding
    # scratch row BEFORE manager_add so the operator-entered phone
    # (durably saved by replacement_send_phone_code -> manager_save_onboarding,
    # see main.py ~32951) can be persisted on the new manager row instead of
    # "". An empty managers.phone is exactly what made the new manager's
    # runtime unable to start (client.start(phone=None) trips Telethon's
    # own "No phone number or bot token provided" guard before it ever
    # reaches its authorized-session-reuse path) -- persisting the real
    # phone here is defense-in-depth alongside the connect()+
    # is_user_authorized() fix in main(), not a replacement for it.
    owner_uid = int(op_row.get("created_by_user_id") or 0)
    onboarding = await manager_get_onboarding(owner_uid) if owner_uid else None
    # TPILOT FIX-7 20260718b: re-verify the onboarding row still belongs to
    # THIS replacement's manager_key before trusting its phone (mirrors
    # _repl4_entry_guards' own binding check -- the only other reader of
    # this row). manager_onboarding is keyed by owner_user_id alone and
    # upserts on any new onboarding/login flow for that owner, so on a
    # resume-after-crash the admin could in principle have started a
    # DIFFERENT flow in between; treating a manager_key mismatch as "no
    # usable onboarding" degrades to the safe empty-phone case (still
    # startable thanks to the connect()+is_user_authorized() session-reuse
    # fix), never silently uses a phone belonging to a different manager.
    if onboarding and registry_normalize_manager_key(onboarding.get("manager_key") or "") != new_key:
        onboarding = None
    entered_phone = str((onboarding or {}).get("phone") or "").strip()

    try:
        await manager_add(
            manager_key=new_key, display_name=display_name, phone=entered_phone, status="active",
            session_path=paths["session_path"], db_path=paths["db_path"], workdir=paths["root"],
            log_path=paths["log_path"], is_enabled=1, owner_user_id=old_row.get("owner_user_id"),
            role=old_row.get("role"),
        )
    except Exception:
        existing2 = await manager_get(new_key)
        if not existing2:
            return _repl4_result(False, "manager_create_failed", "Не удалось создать нового менеджера.", op, op_row, retryable=True)

    perm_path = _replacement_permanent_session_path(new_key, base_dir=base)
    build_client = client_factory or (lambda session_path, cfg: _replacement_build_client(session_path, cfg))
    resolved_proxy, proxy_err = _replacement_resolve_durable_proxy(op_row, onboarding)
    me = None
    client = None
    try:
        client = build_client(perm_path, resolved_proxy if proxy_err is None else {})
        await client.connect()
        if await client.is_user_authorized():
            me = await client.get_me()
    except Exception:
        me = None
    finally:
        if client is not None:
            try:
                await client.disconnect()
            except Exception:
                pass

    if me is not None and int(getattr(me, "id", 0) or 0) == int(op_row.get("new_tg_user_id") or 0):
        # entered_phone (not "") -- _manager_finalize_login writes its phone
        # arg unconditionally via manager_set_fields, so passing "" here
        # would silently erase the phone manager_add just wrote above.
        await _manager_finalize_login(
            created_by_user_id, new_key, entered_phone, me,
            preserve_owner_user_id=True, preserve_runtime_state=True, spawn_after_login=False,
        )
    else:
        # Best-effort fallback: identity can't be safely refreshed from a
        # live connection right now, but new_tg_user_id/new_username are
        # already durable -- write them directly so the row is never left
        # with a blank identity.
        # TPILOT IDENTITY RECONCILE 20260809 (F4, corrected after independent
        # checkpoint review): an EARLIER version of this comment claimed
        # first_name/last_name were simply "not available" here and passed
        # new_display_name into the canonical
        # storage.manager_sync_telegram_profile_in_db(...)'s `first_name` kwarg
        # to avoid that function's own display_name-recompute clobbering the
        # business name manager_add() just set. That was wrong on two counts:
        # (1) new_display_name is a BUSINESS/admin-entered alias -- traced to
        # replacement_send_phone_code's `new_display_name` parameter, validated
        # non-empty at main.py's replacement_send_phone_code BEFORE any Telegram
        # phone/code/sign-in step even starts (see that function, ~line 35228)
        # -- it is never Telegram-derived, so writing it into the `first_name`
        # column would mix business identity with Telegram identity in exactly
        # the column this whole patch exists to keep accurate. (2) the
        # canonical function was designed for a caller that HAS real Telegram
        # first_name/last_name (from a live get_me()) -- this branch, by
        # definition, does not (me is None or its id didn't match), so there is
        # no genuine Telegram first_name to write at all; leaving it blank is
        # the honest representation of "unknown", not a defect. manager_set_fields
        # (used below, same as before this patch touched this branch) already
        # auto-bumps updated_at on every call (storage.py:985) and never
        # recomputes display_name -- so the business display_name manager_add()
        # just set survives untouched, exactly like the live-me success branch
        # above (_manager_finalize_login also only OVERWRITES display_name when
        # it is empty or equals the key; a real display_name is always
        # preserved there too, via its own check, not via display_name_source).
        # The next successful runtime startup's own identity sync
        # (manager_sync_telegram_profile_in_db call inside main(), ~line 5330)
        # will fill in real first_name/last_name once this manager actually
        # authenticates.
        await manager_set_fields(
            new_key,
            tg_user_id=int(op_row.get("new_tg_user_id") or 0) or None,
            telegram_username=str(op_row.get("new_username") or ""),
        )
        # TPILOT MANAGERBOT ACCESS AUTO-GRANT 20260727: this fallback branch
        # does NOT call _manager_finalize_login (identity couldn't be
        # refreshed from a live connection), so that call site's grant never
        # fires here -- and _repl4_transfer_access_groups (below, copies
        # manager_bot_access from old_key) never creates an access_targets
        # row for new_key either. Without this, the new account has no
        # working ManagerBot access until its own next /start. Best-effort:
        # a failure here must never fail the replacement commit.
        try:
            _mbgrant_result = manager_bot_access_ensure_sync(
                tg_user_id=int(op_row.get("new_tg_user_id") or 0) or None,
                manager_key=new_key,
                display_name=display_name,
                username=str(op_row.get("new_username") or ""),
                db_path=TPILOT_DB_PATH,
            )
            if _mbgrant_result.get("status") == "error":
                print(f"[replacement] ManagerBot access grant error for {new_key}: {_mbgrant_result.get('error')}")
        except Exception as e:
            print(f"[replacement] ManagerBot access grant failed for {new_key}: {e!r}")
    return None


async def _repl4_run_links_phase(op_row: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Progressively creates business links for the new manager via the
    real, idempotent _queue_bizlink_create_n_for_manager (never a
    duplicated link-generation implementation), tracks progress via
    replacement_update_links, and advances links_pending -> links_ready only
    once ready_links reaches required_links. 14/15 (or a provider failure
    leaving fewer than required) never advances -- the caller simply
    retries replacement_commit later; old manager is never touched from
    this phase. Existing links for the manager/date are reused/counted, not
    duplicated -- matches the underlying primitive's own idempotency."""
    op = str(op_row.get("operation_id") or "")
    new_key = registry_normalize_manager_key(op_row.get("new_manager_key") or "")
    target_date = str(op_row.get("target_date") or "") or _kyiv_now().date().isoformat()
    required = int(op_row.get("required_links") or 0) or 15

    ready = await _repl4_links_ready_count(new_key, target_date)
    if ready < required:
        try:
            await _queue_bizlink_create_n_for_manager(
                new_key, target_date, required, user_id=int(op_row.get("created_by_user_id") or 0),
            )
        except Exception:
            pass
        ready = await _repl4_links_ready_count(new_key, target_date)

    updated = _repl_storage.replacement_update_links(op, ready, required_links=required)
    if ready < required:
        op_row2 = updated or op_row
        return _repl4_result(False, "links_pending", f"Ссылки создаются: {ready}/{required}.", op, op_row2,
                              retryable=True, next_step="retry_commit")

    if not _repl_storage.replacement_advance(op, "links_pending", "links_ready", stage="links_ready"):
        fresh = _repl_storage.replacement_get(op)
        if not fresh or str(fresh.get("status")) != "links_ready":
            return _repl4_result(False, "stale_state", "Операция изменилась.", op, fresh or op_row)
    return None


# --- TPILOT RUNTIME READINESS 20260718 START (manager_runtime_ready) ---
# RUNTIME READINESS RC 20260805 (wave L2): this threshold is DERIVED from the
# cadence of the writer it reads, never hand-set. manager_telegram_health.
# last_check_at is refreshed by _tp_hg_periodic_self_check_loop() once every
# TP_HG_CHECK_INTERVAL_SEC (1200 s), and that loop sleeps AFTER each pass, so
# the true period is >1200 s. The previous hand-set 900 s was BELOW one single
# writer cycle, which made a perfectly alive runtime deterministically
# "stale" for the last >=5 minutes of every 20-minute cycle -- >=25 % of
# wall-clock time. That is the confirmed root cause of panel_commands id 2173
# (/bizlink_create_n dwanders0 15 2026-08-06 force, rejected in 1 second with
# "рантайм не запущен или ещё не готов" while pid 4628 was alive and
# start_status.phase=running). Two full cycles plus 5 minutes of slack means a
# single missed health pass can never be mistaken for a dead runtime.
_RUNTIME_READY_HEARTBEAT_MAX_AGE_SEC = max(900, TP_HG_CHECK_INTERVAL_SEC * 2 + 300)


async def _manager_health_heartbeat_ok(key: str, *, max_age_sec: int = _RUNTIME_READY_HEARTBEAT_MAX_AGE_SEC) -> Tuple[bool, bool, str]:
    """Readiness signal #9: health heartbeat present, not blocked, not stale.
    Read-only -- never triggers a new health check from a readiness probe.

    Returns (ok, hard, detail). RUNTIME READINESS RC 20260805 (wave L2) added
    the middle `hard` flag so the caller can tell the two very different kinds
    of negative apart:

      hard=True  -- health_status is BLOCKED. An explicit, current, positive
                    statement that this account must not be used. Always fatal,
                    in every mode.
      hard=False -- absent / unparseable / stale / unreadable heartbeat. These
                    say nothing about the runtime itself, only about a
                    BACKGROUND bookkeeping row: the health loop may simply not
                    have come round yet, or the read may have lost a race for
                    the SQLite write lock (OperationalError('database is
                    locked') is confirmed in this project). Treating those as
                    proof of death is what rejected a live runtime.

    LIMITED / cooldown / warning are deliberately NOT interpreted here -- their
    semantics belong to Telegram Health and are unchanged by this wave.
    """
    try:
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute(
                "SELECT health_status, last_check_at FROM manager_telegram_health WHERE manager_key=?",
                (key,),
            )
            row = await cur.fetchone()
    except Exception as e:
        # Transient by nature (lock contention, momentary I/O) -- never a hard no.
        return False, False, f"heartbeat read error: {type(e).__name__}"
    if not row:
        return False, False, "no heartbeat yet"
    status = str(row["health_status"] or "").strip().lower()
    if status == TP_HG_STATUS_BLOCKED:
        return False, True, "health blocked"
    last_check = str(row["last_check_at"] or "")
    if not last_check:
        return False, False, "no last_check_at"
    try:
        parsed = datetime.fromisoformat(last_check.replace("Z", "+00:00"))
        age = (datetime.now(timezone.utc) - parsed).total_seconds() if parsed.tzinfo else (_tp_utc_now() - parsed).total_seconds()
    except Exception:
        return False, False, "bad last_check_at"
    if age > max_age_sec:
        return False, False, f"heartbeat stale ({int(age)}s)"
    return True, False, "ok"


async def _manager_runtime_ready_once(
    key: str,
    *,
    expected_tgid: int = 0,
    start_status_max_age_sec: int = 120,
    ping_timeout_sec: int = 20,
    heartbeat_advisory: bool = False,
) -> Dict[str, Any]:
    """Single (non-polling) pass over the full 10-signal readiness contract
    (plan §15). Never opens a second Telethon client -- signals #3/#7/#10
    (connected/authorized/get_me) come from the ALREADY-RUNNING runtime's own
    runtime_ping command, not a local probe. Returns the exact failing signal's
    error_class so callers/tests can assert on the precise cause.

    heartbeat_advisory (RUNTIME READINESS RC 20260805, wave L2) -- OPT-IN, and
    the default MUST stay False. When True, a merely absent/stale/unreadable
    background heartbeat (signal #9) no longer blocks; the live runtime_ping
    round trip below stays the authoritative connected/authorized/identity
    proof and decides on its own. A BLOCKED health status is still fatal in
    this mode, as are every other signal. This is for ordinary commands aimed
    at an already-running runtime. The replacement/onboarding paths must keep
    calling with the strict default -- there the whole point is to refuse a
    runtime that has not fully proven itself yet.
    """
    import json as _rr_json

    def _fail(error_class: str, detail: str, signal: str) -> Dict[str, Any]:
        return {"ok": False, "error_class": error_class, "detail": detail, "signal": signal, "manager_key": key}

    key = registry_normalize_manager_key(key or "")
    if not key:
        return _fail("runtime_not_running", "Пустой ключ менеджера.", "process")

    # Signal 1: OS process exists.
    if not await _manager_process_running(key):
        return _fail("runtime_not_running", "Процесс менеджера не запущен.", "process")

    # Signal 2: start_status phase connected/running -- checked regardless
    # of freshness (TPILOT FIX-1 20260718b): a healthy runtime's "running"
    # mark is written ONCE (never refreshed) and is expected to be old for
    # any long-lived process, so age alone must never fail it here. Any
    # phase outside {connected,running} (starting/exited/unknown) fails
    # unconditionally, however recent the file is -- this is unchanged and
    # is what still catches a truly dead/crashed runtime.
    status = _manager_recovery_read_start_status(key)
    phase = str(status.get("phase") or "")
    if phase not in ("connected", "running"):
        reason = str(status.get("reason_class") or "")
        if reason == "session_unauthorized":
            return _fail("session_unauthorized", str(status.get("error") or "Сессия не авторизована."), "start_status")
        if reason == "telegram_identity_mismatch":
            return _fail("telegram_identity_mismatch", str(status.get("error") or "Telegram id не совпадает."), "start_status")
        return _fail("runtime_not_ready", f"start_status.phase={phase or 'unknown'}", "start_status")
    if phase == "connected":
        # "connected" is a TRANSIENT pre-running marker (Telethon handshake
        # in progress, main() has not yet reached "running") -- lingering
        # here stale means startup is likely stuck, so freshness IS still
        # required for this one phase. "running" (the steady state, reached
        # once and never rewritten) has no freshness requirement -- signals
        # 3/7/10 below (the live runtime_ping round-trip) are the
        # authoritative liveness proof for a long-running process, never
        # this timestamp alone.
        updated_at = str(status.get("updated_at") or "")
        age = None
        try:
            parsed = datetime.fromisoformat(updated_at.replace("Z", "+00:00"))
            age = (datetime.now(timezone.utc) - parsed).total_seconds() if parsed.tzinfo else (_tp_utc_now() - parsed).total_seconds()
        except Exception:
            age = None
        if age is None or age > start_status_max_age_sec:
            return _fail("runtime_not_ready", "start_status.json застрял на connected (не дошёл до running).", "start_status")

    # Signal 4 (registry half): managers.tg_user_id vs expected new_tg_user_id.
    row = await manager_get(key)
    if not row:
        return _fail("runtime_not_ready", "Менеджер не найден в реестре.", "registry")
    stored_tgid = int(row.get("tg_user_id") or 0)
    if expected_tgid and stored_tgid and stored_tgid != expected_tgid:
        return _fail("telegram_identity_mismatch", f"В реестре {stored_tgid}, ожидалось {expected_tgid}.", "registry")

    # Signal 5: Auth Guard (reused, never weakened).
    try:
        guard_ok, guard_msg = await _tpag_run_guard(key, source="runtime_ready")
    except Exception as e:
        return _fail("proxy_connect_error", f"Auth Guard error: {e!r}", "auth_guard")
    if not guard_ok:
        return _fail("proxy_connect_error", str(guard_msg or "")[:300], "auth_guard")

    # Signal 9: health heartbeat fresh, not blocked.
    # RUNTIME READINESS RC 20260805 (wave L2): a hard negative (BLOCKED) always
    # stops here. A soft negative -- stale/missing/unparseable/unreadable --
    # stops here ONLY in strict mode; under heartbeat_advisory it is recorded
    # and deferred to the live runtime_ping below, which is the authoritative
    # liveness proof. A background bookkeeping row that is merely behind must
    # never outvote the runtime answering for itself.
    hb_ok, hb_hard, hb_detail = await _manager_health_heartbeat_ok(key)
    heartbeat_advisory_detail = ""
    if not hb_ok:
        if hb_hard or not heartbeat_advisory:
            return _fail("runtime_not_ready", f"heartbeat: {hb_detail}", "heartbeat")
        heartbeat_advisory_detail = str(hb_detail or "")

    # Signals 3/7/10: harmless runtime_ping smoke test served by the
    # already-running process itself.
    try:
        from storage import manager_queue_put as _rrp_put, manager_queue_get as _rrp_get
    except Exception as e:
        return _fail("runtime_not_ready", f"queue import error: {e!r}", "ping")
    try:
        nonce = await _rrp_put(
            target_key=key,
            command="runtime_ping",
            created_by="runtime_ready",
            expires_at=_future_iso(int(ping_timeout_sec) + 30),
            db_path=TPILOT_DB_PATH,
        )
    except Exception as e:
        return _fail("runtime_not_ready", f"ping enqueue error: {e!r}", "ping")

    ping_deadline = time.monotonic() + max(1, int(ping_timeout_sec))
    ping_row: Optional[Dict[str, Any]] = None
    while True:
        ping_row = await _rrp_get(nonce, db_path=TPILOT_DB_PATH)
        st = str((ping_row or {}).get("status") or "")
        if st in ("done", "error", "timeout"):
            break
        if time.monotonic() >= ping_deadline:
            break
        await asyncio.sleep(0.5)

    st = str((ping_row or {}).get("status") or "")
    if st not in ("done", "error"):
        return _fail("command_timeout", "runtime_ping не ответил вовремя.", "ping")
    try:
        ping_data = _rr_json.loads(str((ping_row or {}).get("result_json") or "{}"))
    except Exception:
        ping_data = {}

    # TPILOT FIX-8 20260718b: treat the ping response as untrusted
    # structured data -- verify worker_key and response freshness before
    # trusting connected/authorized/tg_user_id at all. The nonce itself
    # already scopes manager_queue_get to exactly this attempt's row (a
    # stale/earlier attempt's answer can never be read here), but a
    # misrouted or forged row (wrong worker_key, or an implausibly old
    # checked_at suggesting a stale cached response) must still be caught.
    ping_worker_key = registry_normalize_manager_key(str(ping_data.get("worker_key") or ""))
    if ping_worker_key != key:
        return _fail("runtime_not_ready", f"runtime_ping ответил от чужого worker_key: {ping_worker_key or 'пусто'} != {key}.", "ping")
    ping_checked_at = str(ping_data.get("checked_at") or "")
    try:
        parsed_ping = datetime.fromisoformat(ping_checked_at.replace("Z", "+00:00"))
        ping_age = (datetime.now(timezone.utc) - parsed_ping).total_seconds() if parsed_ping.tzinfo else (_tp_utc_now() - parsed_ping).total_seconds()
    except Exception:
        ping_age = None
    if ping_age is None or ping_age > max(60, int(ping_timeout_sec) * 3):
        return _fail("command_timeout", "runtime_ping вернул устаревший ответ (checked_at вне окна попытки).", "ping")

    if not bool(ping_data.get("connected")):
        return _fail("telegram_disconnected", str(ping_data.get("error") or "Рантайм не подключён к Telegram."), "ping")
    if not bool(ping_data.get("authorized")):
        return _fail("session_unauthorized", str(ping_data.get("error") or "Сессия не авторизована."), "ping")
    ping_tgid = int(ping_data.get("tg_user_id") or 0)
    if not ping_tgid:
        return _fail("session_unauthorized", "runtime_ping не вернул Telegram id.", "ping")
    if stored_tgid and ping_tgid != stored_tgid:
        return _fail("telegram_identity_mismatch", f"runtime_ping id {ping_tgid} != ��еестр {stored_tgid}.", "ping")
    if expected_tgid and ping_tgid != expected_tgid:
        return _fail("telegram_identity_mismatch", f"runtime_ping id {ping_tgid} != ожидаемый {expected_tgid}.", "ping")

    return {
        "ok": True, "error_class": "", "detail": "OK", "signal": "",
        "manager_key": key, "tg_user_id": ping_tgid, "checked_at": _now_utc_iso(),
        # Non-empty when advisory mode let a soft heartbeat negative through and
        # the live ping then vouched for the runtime. Purely diagnostic.
        "heartbeat_advisory_detail": heartbeat_advisory_detail,
    }


async def manager_runtime_ready(
    key: str,
    *,
    expected_tgid: int = 0,
    deadline_sec: int = 90,
    poll_interval_sec: float = 3.0,
    start_status_max_age_sec: int = 120,
    ping_timeout_sec: int = 20,
    heartbeat_advisory: bool = False,
) -> Dict[str, Any]:
    """TPILOT RUNTIME READINESS CONTRACT 20260718 (plan §15/§16-D). The general,
    reusable deterministic gate: polls _manager_runtime_ready_once up to
    deadline_sec and returns the LAST failure's exact error_class/detail (not a
    generic timeout) so callers -- including replacement's B/C phases and
    tests -- see the precise signal that failed. Bounded: never polls forever.

    heartbeat_advisory is forwarded verbatim and keeps the same strict default
    (RUNTIME READINESS RC 20260805, wave L2) -- the replacement/onboarding
    callers below pass nothing and therefore stay strict."""
    key = registry_normalize_manager_key(key or "")
    deadline = time.monotonic() + max(1, int(deadline_sec))
    last: Dict[str, Any] = {"ok": False, "error_class": "runtime_not_running", "detail": "Менеджер не запущен.", "signal": "process", "manager_key": key}
    while True:
        result = await _manager_runtime_ready_once(
            key,
            expected_tgid=expected_tgid,
            start_status_max_age_sec=start_status_max_age_sec,
            ping_timeout_sec=ping_timeout_sec,
            heartbeat_advisory=heartbeat_advisory,
        )
        if result.get("ok"):
            return result
        last = result
        if time.monotonic() >= deadline:
            return last
        await asyncio.sleep(max(0.5, float(poll_interval_sec)))
# --- TPILOT RUNTIME READINESS 20260718 END (manager_runtime_ready) ---


async def _repl4_validate_new_runtime(op_row: Dict[str, Any], new_key: str) -> Optional[Dict[str, Any]]:
    """Re-checks identity/session/proxy validity, starts the new manager's
    runtime ONLY through the project-native _spawn_manager_process (never a
    full project restart) if it isn't already running, then BLOCKS (bounded)
    until the full 10-signal readiness contract (manager_runtime_ready)
    passes -- no longer spawn-and-forget (TPILOT B/D 20260718: this function
    now runs BEFORE any transfer/link-creation phase, not after). Never
    touches the old manager. If validation fails, the old manager is left
    completely untouched (this function never mutates old_key)."""
    op = str(op_row.get("operation_id") or "")
    row = await manager_get(new_key)
    if not row:
        return _repl4_result(False, "manager_create_failed", "Новый менеджер не найден.", op, op_row)
    perm_path = str(row.get("session_path") or "")
    if not perm_path or not os.path.exists(perm_path):
        return _repl4_result(False, "missing_permanent_session", "Постоянная сессия не найдена.", op, op_row, manual_recovery_required=True)
    if int(row.get("tg_user_id") or 0) != int(op_row.get("new_tg_user_id") or 0):
        return _repl4_result(False, "identity_mismatch", "Идентификатор нового мене��жера не совпадает.", op, op_row, manual_recovery_required=True)
    conflict_key = await _replacement_tg_user_conflict(int(row.get("tg_user_id") or 0))
    if conflict_key and conflict_key != new_key:
        return _repl4_result(False, "identity_conflict", "Конфликт Telegram-идентификатора.", op, op_row, manual_recovery_required=True)
    old_key = registry_normalize_manager_key(op_row.get("old_manager_key") or "")
    if await _replacement_relogin_active(old_key):
        return _repl4_result(False, "relogin_active", "Для старого менеджера выполняется повторный вход.", op, op_row, retryable=True)

    if not await _manager_process_running(new_key):
        ok_spawn, msg_spawn = await _spawn_manager_process(new_key)
        if not ok_spawn:
            return _repl4_result(False, "runtime_start_failed", "Не удалось запустить новый рантайм.", op, op_row, retryable=True)

    ready = await manager_runtime_ready(new_key, expected_tgid=int(op_row.get("new_tg_user_id") or 0))
    if not ready.get("ok"):
        error_class = str(ready.get("error_class") or "runtime_not_ready")
        detail = str(ready.get("detail") or "Рантайм не готов.")
        manual_recovery = error_class == "telegram_identity_mismatch"
        return _repl4_result(False, error_class, detail, op, op_row,
                              retryable=not manual_recovery, manual_recovery_required=manual_recovery)
    return None


async def _repl4_final_revalidate(op_row: Dict[str, Any], old_key: str, new_key: str,
                                   target_date: str, required: int) -> Optional[Dict[str, Any]]:
    """The short, guarded re-check immediately before old-manager mutation
    (spec: 'Final pre-cutover revalidation'). Re-reads the operation fresh
    and re-verifies every critical precondition one more time -- links
    count, new manager existence/identity, permanent session presence, temp
    session absence, identity conflicts, relogin, old manager presence,
    and that no newer replacement has superseded this one for old_key."""
    op = str(op_row.get("operation_id") or "")
    fresh = _repl_storage.replacement_get(op)
    if not fresh or str(fresh.get("status")) != "links_ready":
        return _repl4_result(False, "stale_state", "Операция изменилась.", op, fresh or op_row)
    ready = await _repl4_links_ready_count(new_key, target_date)
    if ready < required:
        return _repl4_result(False, "links_regressed", f"Ссылки регрессировали: {ready}/{required}.", op, fresh, retryable=True)
    new_row = await manager_get(new_key)
    if not new_row:
        return _repl4_result(False, "manager_create_failed", "Новый менеджер исчез.", op, fresh, manual_recovery_required=True)
    if int(new_row.get("tg_user_id") or 0) != int(fresh.get("new_tg_user_id") or 0):
        return _repl4_result(False, "identity_mismatch", "Идентификатор не совпадает.", op, fresh, manual_recovery_required=True)
    perm_path = str(new_row.get("session_path") or "")
    if not perm_path or not os.path.exists(perm_path):
        return _repl4_result(False, "missing_permanent_session", "Постоянная сессия исчезла.", op, fresh, manual_recovery_required=True)
    if os.path.exists(_replacement_temp_session_path(new_key)):
        return _repl4_result(False, "stale_temp_session", "Временная сессия всё ещё существует.", op, fresh, manual_recovery_required=True)
    conflict_key = await _replacement_tg_user_conflict(int(new_row.get("tg_user_id") or 0))
    if conflict_key and conflict_key != new_key:
        return _repl4_result(False, "identity_conflict", "Конфликт идентификатора перед переключением.", op, fresh, manual_recovery_required=True)
    if await _replacement_relogin_active(old_key):
        return _repl4_result(False, "relogin_active", "Повторный вход старого менеджера активен.", op, fresh, retryable=True)
    old_row = await manager_get(old_key)
    if not old_row:
        return _repl4_result(False, "old_manager_missing", "Старый менеджер уже отсутствует.", op, fresh, manual_recovery_required=True)
    active = _repl_storage.replacement_get_active_for_old_key(old_key)
    if not active or str(active.get("operation_id")) != op:
        return _repl4_result(False, "superseded", "Операция больше не активна для старого менеджера.", op, fresh, manual_recovery_required=True)
    return None


async def _repl4_cutover_old_manager(op_row: Dict[str, Any], old_key: str, new_key: str) -> Optional[Dict[str, Any]]:
    """Disables + stops the old manager, reassigns its reserve pairs (if
    any) to the new primary, then deletes/archives it through the EXISTING
    production delete primitive (_manager_delete_full_core -- never a
    duplicated SQL/filesystem implementation), which also creates the
    tombstone and preserves historical statistics/schedule (both are keyed
    by old_manager_key, never touched by this replacement feature). Reserve
    reassignment happens BEFORE delete specifically so
    reserve_pair_release_for_primary (called inside the delete primitive)
    finds nothing left pointing at old_key to retire. Idempotent: if
    old_key is already gone, this is a no-op (prior attempt already
    finished this step).

    TPILOT FIX-R1 20260718c: defense-in-depth entry guard -- re-reads the
    durable operation row (never trusts the possibly-stale op_row parameter
    for this decision) and refuses to mutate the old manager AT ALL unless
    the operation is durably PAST the point of no return (status ==
    'links_ready' and stage in _REPL_CUTOVER_IRREVERSIBLE_STAGES), or
    already fully completed (in which case this is a no-op success). This
    closes the same sweeper-race window as replacement_commit's own
    CAS-result check, one layer deeper -- even a caller that somehow
    reaches this function without having won the cutover_started CAS can
    never disable/delete the old manager."""
    op = str(op_row.get("operation_id") or "")
    guard_row = _repl_storage.replacement_get(op)
    guard_status = str((guard_row or {}).get("status") or "")
    guard_stage = str((guard_row or {}).get("stage") or "")
    if guard_status in ("cutover_done", "notified", "done"):
        return None  # already fully completed -- idempotent success, no mutation
    if guard_status != "links_ready" or guard_stage not in _REPL_CUTOVER_IRREVERSIBLE_STAGES:
        return _repl4_result(
            False, "stale_state",
            "Операция не находится за точкой необратимого переключения -- cutover отклонён.",
            op, guard_row or op_row, retryable=True,
        )
    op_row = guard_row

    old_row = await manager_get(old_key)
    if not old_row:
        pass  # already deleted by a prior attempt -- fall through to the advance below
    else:
        # Disable first (defense-in-depth window before the row is deleted
        # moments later) -- the actual process stop is NOT duplicated here:
        # _manager_delete_full_core already calls _stop_manager_process
        # itself as its own first step, so calling it again here would just
        # be redundant, not an additional safety measure.
        await manager_set_fields(old_key, is_enabled=0, manual_stopped=1)
        try:
            _repl_storage.reserve_pairs_reassign_primary(old_key, new_key)
        except Exception:
            pass
        await _manager_delete_full_core(old_key, requested_by=int(op_row.get("created_by_user_id") or 0))
        if await manager_get(old_key):
            return _repl4_result(False, "cutover_delete_failed", "Не удалось удалить старого менеджера.", op, op_row, manual_recovery_required=True)

    # TPILOT FIX-4 20260718b: forward-only progress marker -- old manager is
    # now confirmed gone (either just now, or on a prior attempt). Written
    # unconditionally on this path (idempotent, same value every time) so a
    # resume always sees the durable evidence that this irreversible step
    # already completed, never re-derives it from old_row's absence alone.
    _repl_storage.replacement_set_stage(op, "old_manager_retired", expected_statuses=("links_ready",))

    new_row = await manager_get(new_key)
    if not new_row or str(new_row.get("status") or "") != "active" or int(new_row.get("is_enabled") or 0) != 1:
        return _repl4_result(False, "new_manager_not_active", "Новый менеджер не активен после переключения.", op, op_row, manual_recovery_required=True)

    if not _repl_storage.replacement_advance(op, "links_ready", "cutover_done", stage="cutover_done"):
        fresh = _repl_storage.replacement_get(op)
        if not fresh or str(fresh.get("status")) != "cutover_done":
            return _repl4_result(False, "manual_recovery_required", "Переключение завершено, но статус не подтверждён.", op, op_row, manual_recovery_required=True)
    return None


# --- TPILOT C AUTOMATIC ROLLBACK 20260718 START ---
async def _repl4_rollback(op_row: Dict[str, Any], rollback_stage: str, error_class: str, error_text: str) -> Dict[str, Any]:
    """Plan §14/§16-C: idempotent, best-effort, oldest-mutation-first
    compensation for a failed PRE-CUTOVER commit (committing/links_pending/
    links_ready only -- NEVER once cutover has begun mutating the old
    manager; that is a deliberate point of no return with its own
    manual_recovery_required path, never auto-reversed here). Safe to call
    repeatedly (retries/restarts/duplicate triggers) -- every step re-checks
    live state before acting. NEVER deletes the new manager's session file,
    only stops/disables the process."""
    op = str(op_row.get("operation_id") or "")

    # TPILOT FIX-4 20260718b: hard boundary -- re-reads the CURRENT durable
    # row (never trusts the possibly-stale op_row parameter) and refuses if
    # cutover has already begun (stage in _REPL_CUTOVER_IRREVERSIBLE_STAGES)
    # or the operation is already past cutover. This is what closes the
    # deadline-sweeper race found by the independent audit (F4): a sweep
    # firing exactly as cutover starts must never disable the (by then
    # fully validated) new manager or re-route to an old manager that may
    # already be gone.
    fresh_for_guard = _repl_storage.replacement_get(op) or op_row
    fresh_stage = str(fresh_for_guard.get("stage") or "")
    fresh_status = str(fresh_for_guard.get("status") or "")
    if fresh_stage in _REPL_CUTOVER_IRREVERSIBLE_STAGES or fresh_status in ("cutover_done", "notified", "done"):
        return _repl4_result(
            False, "rollback_forbidden_post_cutover",
            "Операция уже прошла точку необратимого переключения -- откат невозможен, требуется продолжение вперёд.",
            op, fresh_for_guard, manual_recovery_required=True,
        )

    old_key = registry_normalize_manager_key(op_row.get("old_manager_key") or "")
    new_key = registry_normalize_manager_key(op_row.get("new_manager_key") or "")

    # Step 1: stop/disable the incomplete new manager. Session file kept.
    try:
        if new_key and await _manager_process_running(new_key):
            await _stop_manager_process(new_key, silent=True)
    except Exception:
        pass
    try:
        if new_key and await manager_get(new_key):
            await manager_set_fields(new_key, is_enabled=0, manual_stopped=1)
    except Exception:
        pass

    # Step 2: restore source routing to the old manager if the transfer step
    # already switched it to new_key (no-op if it never ran -- the common
    # case now that the readiness gate runs BEFORE transfers).
    try:
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            now = _now_utc_iso()
            cur = await db.execute("SELECT source_key FROM manager_source_links WHERE manager_key=?", (old_key,))
            old_src_row = await cur.fetchone()
            old_has_source = bool(old_src_row and str(old_src_row[0] or ""))
            if not old_has_source and new_key:
                cur2 = await db.execute("SELECT source_key FROM manager_source_links WHERE manager_key=?", (new_key,))
                new_src_row = await cur2.fetchone()
                if new_src_row and str(new_src_row[0] or ""):
                    await db.execute(
                        "INSERT INTO manager_source_links(manager_key, source_key, created_at, updated_at) VALUES(?,?,?,?)"
                        " ON CONFLICT(manager_key) DO UPDATE SET source_key=excluded.source_key, updated_at=excluded.updated_at",
                        (old_key, str(new_src_row[0]), now, now),
                    )
            if new_key:
                await db.execute("DELETE FROM manager_source_links WHERE manager_key=?", (new_key,))
            await db.commit()
    except Exception:
        pass

    # Step 3: restore proxy lease ownership -- only a lease this operation's
    # own assign step moved (proxy_leases.manager_key currently == new_key).
    try:
        if new_key and old_key:
            lease = await _repl_storage.proxy_lease_get_for_manager(new_key)
            if lease and str(lease.get("manager_key") or "") == new_key:
                await _repl_storage.proxy_lease_assign_to_manager(int(lease["id"]), old_key)
    except Exception:
        pass

    # Step 4: ensure the old manager stays/becomes active -- it must never
    # have been cut over (cutover only runs after full readiness + final
    # revalidation), so normally this is a no-op reaffirmation.
    try:
        old_row = await manager_get(old_key)
        if old_row and (int(old_row.get("is_enabled") or 0) != 1 or str(old_row.get("status") or "") != "active"):
            await manager_set_fields(old_key, is_enabled=1, manual_stopped=0, status="active")
    except Exception:
        pass

    # Step 5: finalize any commands still queued for the new manager so they
    # can never be silently consumed after a later manual restart.
    try:
        if new_key:
            from storage import manager_queue_finalize_all_for_manager as _rrb_finalize
            await _rrb_finalize(new_key, error_text=f"replacement_rollback:{rollback_stage}", db_path=TPILOT_DB_PATH)
    except Exception:
        pass

    # Step 6: durable terminal state with the exact stage/reason (reuses the
    # one Stage 2 fatal-failure path -- never a duplicated CAS/cleanup here).
    await _replacement_fail(op, error_class, str(error_text or "")[:500], new_manager_key=new_key,
                             owner_user_id=int(op_row.get("created_by_user_id") or 0), rollback_stage=rollback_stage)

    fresh = _repl_storage.replacement_get(op) or op_row
    return _repl4_result(False, error_class, str(error_text or "Операция отменена, изменения откачены.")[:500],
                          op, fresh, rollback_stage=rollback_stage, manual_recovery_required=False)
# --- TPILOT C AUTOMATIC ROLLBACK 20260718 END ---


# --- TPILOT F EXPIRED-COMMAND + COMMIT-DEADLINE SWEEPER 20260718 START ---
_REPL_SWEEP_INTERVAL_SEC = 60
_REPL_SWEEP_CLEANUP_RETENTION_SEC = 86400


async def _repl_commit_deadline_sweep_once() -> int:
    """One pass: auto-rolls-back every replacement stuck in a pre-cutover
    commit phase (committing/links_pending/links_ready) past its
    commit_deadline_at -- plan §16-C's "commit-deadline expiry" trigger and
    §16-F's "link failure beyond retry policy" backstop (a link phase that
    keeps returning links_pending retryable=True forever is exactly what
    this deadline bounds). Idempotent: _repl4_rollback re-checks live state
    and replacement_fail's CAS is a no-op on an already-terminal row, so an
    operation picked up by two overlapping sweeps converges safely."""
    now_iso = _now_utc_iso()
    try:
        stuck = _repl_storage.replacement_list_commit_phase_past_deadline(now_iso)
    except Exception as e:
        print(f"commit deadline sweep read error: {e!r}")
        return 0
    handled = 0
    for op_row in stuck:
        try:
            await _repl4_rollback(op_row, "commit_deadline", "command_timeout",
                                   "Операция превысила лимит времени на переключение (commit_deadline_at).")
            handled += 1
        except Exception as e:
            print(f"commit deadline sweep rollback error op={op_row.get('operation_id')}: {e!r}")
    return handled


async def _manager_command_sweep_loop() -> None:
    """Controller-only background loop (plan §16-F). Periodically:
    (1) finalizes manager_commands rows past their own expires_at to
    'timeout' -- manager_queue_mark_timeouts previously had exactly one
    caller (preflight_check.py's give-up branch, self-labelled "cosmetic
    queue hygiene only"), so a command for a manager that never rode a
    preflight sweep stayed 'new'/'processing' forever;
    (2) prunes old finished commands via manager_queue_cleanup_finished
    (previously orphaned, no live caller);
    (3) auto-rolls-back any replacement stuck past commit_deadline_at.
    Never crashes the controller; each step is independently try/except'd
    so one failing step never blocks the others."""
    if not CONTROLLER_MODE:
        return
    try:
        from storage import manager_queue_mark_timeouts as _sweep_mark_timeouts, manager_queue_cleanup_finished as _sweep_cleanup
    except Exception as e:
        print(f"manager command sweeper import error: {e!r}")
        return
    await asyncio.sleep(30)
    while True:
        try:
            n_timeout = await _sweep_mark_timeouts(db_path=TPILOT_DB_PATH)
            if n_timeout:
                print(f"[sweeper] manager_commands expired -> timeout: {n_timeout}")
        except Exception as e:
            print(f"manager_queue_mark_timeouts error: {e!r}")
        try:
            await _sweep_cleanup(older_than_sec=_REPL_SWEEP_CLEANUP_RETENTION_SEC, db_path=TPILOT_DB_PATH)
        except Exception as e:
            print(f"manager_queue_cleanup_finished error: {e!r}")
        try:
            n_rolled_back = await _repl_commit_deadline_sweep_once()
            if n_rolled_back:
                print(f"[sweeper] replacement commit_deadline rollbacks: {n_rolled_back}")
        except Exception as e:
            print(f"commit deadline sweep error: {e!r}")
        await asyncio.sleep(_REPL_SWEEP_INTERVAL_SEC)
# --- TPILOT F EXPIRED-COMMAND + COMMIT-DEADLINE SWEEPER 20260718 END ---


async def _repl4_entry_guards(op_row: Dict[str, Any], created_by_user_id: int, base: Path) -> Optional[Dict[str, Any]]:
    """All guards required before the FIRST ready_commit -> committing CAS.
    Only invoked when status is still 'ready_commit' -- a resumed/duplicate
    call that finds status already committing/links_pending/links_ready
    skips straight to the matching phase runner, since every phase step
    re-verifies its own narrower slice of live state independently anyway."""
    op = str(op_row.get("operation_id") or "")
    if int(op_row.get("created_by_user_id") or 0) != int(created_by_user_id or 0):
        return _repl4_result(False, "missing_operation", "Операция не найдена.", op, op_row)

    old_key = registry_normalize_manager_key(op_row.get("old_manager_key") or "")
    new_key = registry_normalize_manager_key(op_row.get("new_manager_key") or "")
    if not new_key:
        return _repl4_result(False, "missing_key", "Не выбран новый ключ.", op, op_row)
    if not str(op_row.get("new_display_name") or "").strip():
        return _repl4_result(False, "missing_display_name", "Не задано отображаемое имя.", op, op_row)

    old_row = await manager_get(old_key)
    if not old_row:
        return _repl4_result(False, "old_manager_missing", f"Старый менеджер {old_key} не найден.", op, op_row)
    if str(old_row.get("status") or "").strip().lower() in ("archived", "deleted"):
        return _repl4_result(False, "old_manager_gone", f"Старый менеджер {old_key} архивирован/удалён.", op, op_row)

    conflict_row = await manager_get(new_key)
    if conflict_row:
        return _repl4_result(False, "key_exists", f"Менеджер {new_key} уже существует.", op, op_row)

    other = _repl_storage.replacement_get_by_new_key(new_key)
    if (other and str(other.get("operation_id")) != op
            and str(other.get("status")) not in _repl_storage.REPLACEMENT_TERMINAL_STATUSES):
        return _repl4_result(False, "key_conflict", f"Ключ {new_key} занят другой операцией.", op, op_row)

    new_tg_user_id = int(op_row.get("new_tg_user_id") or 0)
    if new_tg_user_id <= 0:
        return _repl4_result(False, "missing_identity", "Telegram-идентификатор не сохранён.", op, op_row)
    conflict_key = await _replacement_tg_user_conflict(new_tg_user_id)
    if conflict_key and conflict_key != new_key:
        return _repl4_result(False, "identity_conflict", f"Этот Telegram-аккаунт уже привязан к менеджеру {conflict_key}.", op, op_row)
    other_op = await _replacement_tgid_reserved_by_other(new_tg_user_id, op)
    if other_op:
        return _repl4_result(False, "identity_conflict", "Этот Telegram-аккаунт используется в другой операции замены.", op, op_row)

    if await _replacement_relogin_active(old_key):
        return _repl4_result(False, "relogin_active", "Для старого менеджера выполняется повторный вход.", op, op_row)

    active = _repl_storage.replacement_get_active_for_old_key(old_key)
    if not active or str(active.get("operation_id")) != op:
        return _repl4_result(False, "superseded", "Эта операция больше не активна для старого менеджера.", op, op_row)

    owner_uid = int(op_row.get("created_by_user_id") or 0)
    onboarding = await manager_get_onboarding(owner_uid) if owner_uid else None
    if not onboarding or registry_normalize_manager_key(onboarding.get("manager_key") or "") != new_key:
        return _repl4_result(False, "no_pending_session", "Нет активной сессии для завершения. Начните заново.", op, op_row)

    resolved_proxy, proxy_err = _replacement_resolve_durable_proxy(op_row, onboarding)
    if proxy_err:
        return proxy_err

    temp_path = _replacement_temp_session_path(new_key, base_dir=base)
    if not os.path.exists(temp_path):
        return _repl4_result(False, "missing_temp_session", "Временная сессия не найдена.", op, op_row)
    perm_path = _replacement_permanent_session_path(new_key, base_dir=base)
    if os.path.exists(perm_path):
        return _repl4_result(False, "permanent_session_conflict", "Постоянная session для нового ключа уже существует.", op, op_row)

    # Reserve semantics: old manager itself being a reserve for some other
    # primary has NO existing project precedent anywhere in the reserve
    # schema (verified by direct code inspection -- only primary-side
    # deletion has a release helper; nothing repoints a reserve-side key
    # when ITS OWN row is being replaced). Refuse explicitly rather than
    # invent cutover behavior for an undefined case (per spec: "define and
    # preserve current project semantics; do not guess ... or report an
    # owner-decision blocker").
    reserve_of = _repl_storage.reserve_pair_get_by_reserve(old_key)
    if reserve_of and str(reserve_of.get("status") or "") == "linked":
        return _repl4_result(
            False, "old_manager_is_reserve_unsupported",
            f"Менеджер {old_key} сам является резервом для {reserve_of.get('primary_key')} -- "
            "замена резервного аккаунта не реализована, требуется решение владельца.",
            op, op_row, manual_recovery_required=True,
        )
    return None


async def replacement_commit(
    operation_id: str, *, created_by_user_id: int, db_path: Optional[str] = None,
    base_dir: Optional[Path] = None, client_factory=None,
) -> Dict[str, Any]:
    """Public commit entry: advances a ready_commit operation through
    committing -> links_pending -> links_ready -> cutover_done. Safe to call
    repeatedly (duplicate clicks, process restarts) -- every phase re-enters
    at the operation's CURRENT durable status and re-verifies live state
    before acting, so two overlapping calls converge on the same real
    result rather than starting two commits or redoing a destructive step.
    Never advances past cutover_done (notified/done are a later stage)."""
    op = str(operation_id or "").strip()
    base = base_dir if base_dir is not None else BASE_DIR
    op_row = _repl_storage.replacement_get(op, db_path=db_path)
    if not op_row or int(op_row.get("created_by_user_id") or 0) != int(created_by_user_id or 0):
        return _repl4_result(False, "missing_operation", "Операция не найдена.", op, None)

    status = str(op_row.get("status") or "")
    if status in _repl_storage.REPLACEMENT_TERMINAL_STATUSES:
        return _repl4_result(False, "cancellation_not_allowed" if status == "cancelled" else "already_terminal",
                              "Операция уже завершена/отменена.", op, op_row)
    if status in ("cutover_done", "notified", "done"):
        return _repl4_result(True, "already_cutover", "Переключение уже выполнено.", op, op_row, next_step="notify")

    if status == "ready_commit":
        guard_err = await _repl4_entry_guards(op_row, created_by_user_id, base)
        if guard_err:
            return guard_err
        deadline_fields = {"commit_deadline_at": _future_iso(_REPL4_COMMIT_DEADLINE_SEC)}
        if _repl_storage.replacement_advance(op, "ready_commit", "committing", stage="commit_started",
                                              fields=deadline_fields, db_path=db_path):
            op_row = _repl_storage.replacement_get(op, db_path=db_path) or op_row
        else:
            fresh = _repl_storage.replacement_get(op, db_path=db_path)
            if not fresh or str(fresh.get("status")) not in _REPL4_COMMIT_PHASE_STATUSES:
                return _repl4_result(False, "stale_state", "Операция изменилась.", op, fresh or op_row)
            op_row = fresh
        status = str(op_row.get("status") or "")
    elif status not in _REPL4_COMMIT_PHASE_STATUSES:
        return _repl4_result(False, "wrong_state", "Операция не готова к переключению.", op, op_row,
                              next_step=_replacement_next_step_for_status(status))

    old_key = registry_normalize_manager_key(op_row.get("old_manager_key") or "")
    new_key = registry_normalize_manager_key(op_row.get("new_manager_key") or "")
    target_date = str(op_row.get("target_date") or "") or _kyiv_now().date().isoformat()
    required = int(op_row.get("required_links") or 0) or 15

    if status == "committing":
        old_row = await manager_get(old_key)
        if not old_row:
            return _repl4_result(False, "old_manager_missing", f"Старый менеджер {old_key} не найден.", op, op_row)

        try:
            err = await _repl4_promote_session(op_row, old_row, new_key, base, client_factory=client_factory)
            if err:
                return err
            _repl_storage.replacement_set_stage(op, "session_promoted", expected_statuses=("committing",), db_path=db_path)

            err = await _repl4_create_new_manager(op_row, old_row, new_key, created_by_user_id, base, client_factory=client_factory)
            if err:
                return err
            _repl_storage.replacement_set_stage(op, "manager_created", expected_statuses=("committing",), db_path=db_path)

            # TPILOT FIX-2 20260718b: assign proxy BEFORE starting the new
            # runtime. Previously the runtime was spawned+validated FIRST
            # and proxy assigned afterward with no restart -- a fresh
            # replacement account with proxy_mode=="proxy" would connect to
            # Telegram DIRECT from the server IP (the row had no proxy
            # fields yet), and Auth Guard would then trivially pass via its
            # own "direct" branch instead of validating the intended proxy
            # route. The runtime is never restarted after this point, so
            # proxy must be fully applied to the row before spawn.
            err = await _repl4_assign_proxy(op_row, new_key)
            if err:
                return await _repl4_rollback(op_row, "proxy_assign", str(err.get("code") or "transfer_failed"),
                                              str(err.get("message") or "Не удалось назначить proxy."))
            if str(op_row.get("proxy_mode") or "").strip().lower() != "direct":
                proxy_verify_row = await manager_get(new_key)
                if not proxy_verify_row or not str(proxy_verify_row.get("proxy_host") or "").strip():
                    return await _repl4_rollback(
                        op_row, "proxy_assign", "proxy_connect_error",
                        "Proxy обязателен для этой замены, но не применён к менеджеру перед запуском рантайма.",
                    )
            _repl_storage.replacement_set_stage(op, "proxy_assigned", expected_statuses=("committing",), db_path=db_path)

            # TPILOT B/D REORDER 20260718 (order relative to transfers
            # unchanged; TPILOT FIX-2 20260718b moved this AFTER proxy
            # assignment above): start + fully validate the new runtime
            # BEFORE any source/schedule/access transfer and before link
            # creation is ever enqueued. Previously the runtime was only
            # spawned (and only spawn-and-forget, never confirmed to
            # survive) in the LATER links_ready phase -- one phase too late,
            # so links could never be created (0/15) and traffic was routed
            # to a manager whose runtime had never been confirmed to even
            # start (root cause of the valeria1/valery_onn stuck
            # replacement).
            err = await _repl4_validate_new_runtime(op_row, new_key)
            if err:
                # TPILOT C 20260718: the readiness gate already exhausted
                # its own bounded internal poll (manager_runtime_ready's
                # deadline_sec) -- a further caller-level retry-from-scratch
                # would just repeat that same wait, so this is treated as
                # terminal and auto-rolled back rather than left
                # retryable=True forever. Covers plan §16-C's runtime-start
                # failure / readiness timeout / identity mismatch / Auth
                # Guard failure / stale heartbeat / ping failure --
                # manager_runtime_ready() surfaces all of these as this one
                # failure point.
                return await _repl4_rollback(op_row, "runtime_validation", str(err.get("code") or "runtime_not_ready"),
                                              str(err.get("message") or "Рантайм нового менеджера не готов."))
            _repl_storage.replacement_set_stage(op, "runtime_validated", expected_statuses=("committing",), db_path=db_path)

            await _repl4_transfer_settings(old_key, new_key)
            await _repl4_transfer_schedule(old_key, new_key, target_date)
            await _repl4_transfer_access_groups(old_key, new_key)
            _repl_storage.replacement_set_stage(op, "settings_transferred", expected_statuses=("committing",), db_path=db_path)
        except Exception as e:
            # TPILOT C 20260718: any unexpected exception during the
            # committing phase (plan §16-C). promote_session/
            # create_new_manager's OWN expected failures are structured
            # returns (handled above via `if err: return err`) and never
            # reach this except -- this only catches genuine bugs/DB errors.
            # Rollback is safe/idempotent even when almost nothing was
            # mutated yet (e.g. an exception right after promote_session).
            return await _repl4_rollback(op_row, "committing", "unexpected_exception", f"{e.__class__.__name__}: {e}")

        if _repl_storage.replacement_advance(op, "committing", "links_pending", stage="links_creating", db_path=db_path):
            op_row = _repl_storage.replacement_get(op, db_path=db_path) or op_row
        else:
            fresh = _repl_storage.replacement_get(op, db_path=db_path)
            if not fresh or str(fresh.get("status")) not in ("links_pending", "links_ready"):
                return _repl4_result(False, "stale_state", "Операция изменилась.", op, fresh or op_row)
            op_row = fresh
        status = str(op_row.get("status") or "")

    if status == "links_pending":
        try:
            err = await _repl4_run_links_phase(op_row)
        except Exception as e:
            return await _repl4_rollback(op_row, "links_pending", "unexpected_exception", f"{e.__class__.__name__}: {e}")
        if err:
            return err
        op_row = _repl_storage.replacement_get(op, db_path=db_path) or op_row
        status = str(op_row.get("status") or "")

    if status == "links_ready":
        stage_now = str(op_row.get("stage") or "")
        if stage_now not in _REPL_CUTOVER_IRREVERSIBLE_STAGES:
            # Runtime start + full readiness validation already happened
            # before links were created (see the "committing" phase above,
            # TPILOT B/D REORDER 20260718) -- this phase only does the final
            # pre-cutover re-check of state that could have drifted since
            # (link count, identity, session presence, superseding
            # operations). Only reachable BEFORE the point of no return --
            # once stage is cutover_started/old_manager_retired (a resumed
            # cutover), this whole block is skipped (TPILOT FIX-4
            # 20260718b): re-running it would see the old manager already
            # gone and wrongly report old_manager_missing, stranding an
            # operation that in reality already succeeded.
            try:
                err = await _repl4_final_revalidate(op_row, old_key, new_key, target_date, required)
            except Exception as e:
                return await _repl4_rollback(op_row, "final_revalidate", "unexpected_exception", f"{e.__class__.__name__}: {e}")
            if err:
                return err
            _repl_storage.replacement_set_stage(op, "revalidated", expected_statuses=("links_ready",), db_path=db_path)

            # DURABLE POINT OF NO RETURN (TPILOT FIX-4 20260718b): persisted
            # BEFORE any irreversible mutation. From here on, cutover is
            # forward-only -- _repl4_rollback refuses to run once it sees
            # this stage, and the deadline sweeper excludes it at the SQL
            # level (storage.replacement_list_commit_phase_past_deadline).
            #
            # TPILOT FIX-R1 20260718c: the CAS result is now checked. A
            # narrow race exists between _repl4_final_revalidate's awaits
            # above and the deadline sweeper: if the sweeper's own LEGAL
            # pre-PONR rollback wins first (op moves to status='failed', new
            # manager disabled, old manager restored), this CAS silently
            # no-ops (its WHERE status='links_ready' no longer matches).
            # Proceeding into cutover unconditionally in that case would
            # delete the just-restored old manager while the new manager
            # stays disabled from the rollback -- both dead. So: re-read the
            # fresh row and only fall through into cutover if the operation
            # is durably PAST the point of no return; any other outcome
            # (terminal, or still pre-cutover) returns here and never calls
            # _repl4_cutover_old_manager.
            cas_ok = _repl_storage.replacement_set_stage(op, "cutover_started", expected_statuses=("links_ready",), db_path=db_path)
            if not cas_ok:
                fresh = _repl_storage.replacement_get(op, db_path=db_path)
                fresh_status = str((fresh or {}).get("status") or "")
                fresh_stage = str((fresh or {}).get("stage") or "")
                if fresh_status in _repl_storage.REPLACEMENT_TERMINAL_STATUSES:
                    return _repl4_result(False, "stale_state", "Операция уже завершена/отменена (гонка с sweeper'ом отката).", op, fresh or op_row)
                if not (fresh_status == "links_ready" and fresh_stage in _REPL_CUTOVER_IRREVERSIBLE_STAGES):
                    return _repl4_result(False, "stale_state", "Операция изменилась, точка необратимого переключения не подтверждена.", op, fresh or op_row, retryable=True)
                # Benign re-entry: another concurrent attempt already won
                # this CAS (or a prior attempt already progressed this
                # far) -- fall through into cutover exactly like the
                # stage_now-already-set branch above.
                op_row = fresh

        # TPILOT C 20260718: deliberately NOT wrapped in the rollback
        # try/except -- cutover starts deleting the old manager
        # (_manager_delete_full_core), a point of no return. An unexpected
        # exception here must surface as-is (never auto-"rolled back",
        # which could re-enable an old manager mid-delete and cause worse
        # damage); its own structured failures already carry
        # manual_recovery_required=True. Idempotent: safe to re-enter at any
        # sub-step (old already gone, new already active, CAS already done).
        err = await _repl4_cutover_old_manager(op_row, old_key, new_key)
        if err:
            return err

    final_row = _repl_storage.replacement_get(op, db_path=db_path) or op_row
    return _repl4_result(True, "cutover_done", "Переключение завершено.", op, final_row, next_step="notify")

# --- TPILOT MANAGER REPLACEMENT STAGE4 COMMIT ENGINE 20260716 END ---


# ---------------------------------------------------------------------------
# --- TPILOT TDATA/SESSION IMPORT ADMINBOT WIRING 20260719 START ---
#
# Thin controller-command layer for the third AdminBot authorization method
# ("[UP] Через tdata / session"). All real backend logic (safe archive
# extraction, offline .session validation, the vendored tdata reader, the
# durable import state machine) lives in the isolated tdata_import\ package
# -- this block only wires the project's OWN existing primitives into that
# package's injectable service functions, exactly per
# tdata_import/service.py's own docstring contract. Nothing here duplicates
# proxy resolution, client construction, or process management logic that
# already exists elsewhere in this file.
#
# Commands: /manager_tdimport_start | status | confirm | cancel
#
# Owner decisions enforced here:
#   #5 -- direct-mode managers are rejected before ANY archive/Telegram work
#        (tdata_import.proxy_gate.assert_proxy_mode_allowed, called inside
#        service.start_import before archive extraction even begins).
#   #6 -- the imported/generated session is used ONLY via
#        _build_manager_telegram_client_from_row(row, path,
#        source="tdata_import") -- forces the MAIN API_ID/API_HASH (never
#        ONBOARD_*), and _resolve_manager_telethon_proxy inside that same
#        factory is a second, independent enforcement of proxy-mandatory
#        (defense in depth on top of tdata_import.proxy_gate's own gate).
#
# Reused, unmodified production primitives: manager_get,
# registry_normalize_manager_key, _manager_auth_proxy_mode,
# _build_manager_telegram_client_from_row, _tpag_v4_proxy_geo_via_socks,
# _spawn_manager_process, _stop_manager_process, manager_runtime_ready,
# build_manager_paths, ensure_manager_dirs, TPILOT_DB_PATH, BASE_DIR,
# _future_iso, _parse_cmd, the _REPL3_DISPATCH-style JSON result convention
# (_repl3_json_result).
#
# allow_spend is never referenced anywhere in this block or in the
# tdata_import package -- this flow never touches the proxy provider API.
# ---------------------------------------------------------------------------

from tdata_import import service as _tdimport_service
import storage as _tdimport_storage


def _tdimport_new_operation_id(manager_key: str) -> str:
    """Deterministic-enough, collision-safe operation id. Pure/testable via
    AST extraction (no telethon/DB touched)."""
    import uuid as _tdi_uuid
    key = registry_normalize_manager_key(manager_key or "")
    return f"tdi_{key}_{_tdi_uuid.uuid4().hex[:12]}"


def _tdimport_proxy_row_from_manager(row: Dict[str, Any]) -> Dict[str, Any]:
    """Project a managers row down to exactly what tdata_import.proxy_gate
    needs, using the SAME proxy-mode classification the rest of the project
    uses (_manager_auth_proxy_mode) -- never a bespoke direct/proxy check."""
    r = row or {}
    return {
        "proxy_mode": _manager_auth_proxy_mode(r),
        "proxy_lease_id": r.get("proxy_lease_id"),
        "proxy_host": r.get("proxy_host") or "",
        "proxy_port": r.get("proxy_port") or 0,
        "proxy_username": r.get("proxy_username") or "",
        "proxy_password": r.get("proxy_password") or "",
    }


def _tdimport_real_prober(host: str, port: int, username: str, password: str, rdns: bool):
    """Adapts this project's own real SOCKS5 probe
    (_tpag_v4_proxy_geo_via_socks) to tdata_import.proxy_gate's injectable
    prober contract. A probe failure is always ProxyUnavailable -- the caller
    (tdata_import.proxy_gate.verify_proxy) only ever retries with the OTHER
    proxy DNS mode (socks5h/socks5), never without a proxy."""
    from tdata_import.errors import ProxyUnavailable as _TdiProxyUnavailable
    from tdata_import.proxy_gate import ProxyVerification as _TdiProxyVerification
    try:
        geo, _ms = _tpag_v4_proxy_geo_via_socks(host, port, username, password, rdns=rdns)
    except Exception as exc:
        raise _TdiProxyUnavailable(f"proxy probe failed: {type(exc).__name__}")
    ip = str((geo or {}).get("ip") or "").strip()
    if not ip:
        raise _TdiProxyUnavailable("proxy external IP not detected")
    return _TdiProxyVerification(ip=ip, method="socks5h" if rdns else "socks5")


async def _tdimport_client_factory_for(row: Dict[str, Any], session_path: str):
    """Builds+connects a Telethon client for the FIRST (and only) network use
    of the imported/generated session. source="tdata_import" forces the fixed
    Telegram Desktop API/device profile (TDIMPORT_API_ID/TDIMPORT_API_HASH, see
    _api_profile_for) -- opentele UseCurrentSession reuses the session's EXISTING
    auth_key, which is only valid under the API app it was originally authorized
    with. The SAME _resolve_manager_telethon_proxy enforcement every other manager
    client goes through applies here too."""
    client = _build_manager_telegram_client_from_row(row, session_path, source="tdata_import")
    await client.connect()
    return client


async def _tdimport_spawn_runtime(manager_key: str) -> None:
    # TPILOT TDATA/SESSION IMPORT AUTH PROFILE 20260719: mark this manager's
    # auth_profile='tdesktop' BEFORE spawning the runtime subprocess. The child
    # process reads its registry row (incl. auth_profile) ONCE at startup, so this
    # write must land in the DB before _spawn_manager_process launches it -- writing
    # it after would race the child's first read and risk it starting under the
    # wrong (project) API profile, which opentele UseCurrentSession would reject.
    await manager_set_fields(manager_key, auth_profile="tdesktop")
    ok, msg = await _spawn_manager_process(manager_key)
    if not ok:
        raise RuntimeError(msg or "spawn failed")


async def _tdimport_stop_runtime(manager_key: str) -> None:
    await _stop_manager_process(manager_key, silent=True)


async def _tdimport_is_runtime_running(manager_key: str) -> bool:
    # TPILOT AUTH SAFETY 20260809 (Ф3, D-INSTALL): real process check, wired into
    # confirm_install's is_runtime_running -- lets it stop-before-install and
    # confirm the stop for an EXISTING manager's session import (relogin/replace
    # via tdata/.session, not just fresh add-manager onboarding).
    return await _manager_process_running(manager_key)


async def _tdimport_wait_runtime_ready(manager_key: str) -> bool:
    result = await manager_runtime_ready(manager_key, deadline_sec=90, poll_interval_sec=3.0)
    return bool(result.get("ok"))


_TDIMPORT_STALE_SWEEP_INTERVAL_SEC = 60


async def _tdimport_stale_sweep_loop() -> None:
    """Controller-only background sweep for abandoned/interrupted tdata-import
    operations. Without it, an import that reaches identity_verified but whose
    admin never taps confirm/cancel (server restart, distraction) would (a)
    leave a decrypted full-account session under runtime\\tdata_import\\<op>\\
    forever, and (b) permanently hold the one-active-per-manager lock, making
    that manager impossible to re-import. Each stale op past its expires_at is
    scrubbed + moved to status='error' by tdata_import.service.sweep_stale
    (which never touches an op mid-install/cutover). Never crashes the
    controller; the sweep is fully self-contained and offline."""
    if not CONTROLLER_MODE:
        return
    await asyncio.sleep(45)
    while True:
        try:
            n = _tdimport_service.sweep_stale(db_path=TPILOT_DB_PATH)
            if n:
                print(f"[sweeper] tdata_import stale operations scrubbed -> error: {n}")
        except Exception as e:  # noqa: BLE001
            print(f"tdata_import stale sweep error: {e!r}")
        await asyncio.sleep(_TDIMPORT_STALE_SWEEP_INTERVAL_SEC)


async def _panel_manager_tdimport_start_command(args: str, *, requested_by: int = 0) -> str:
    """/manager_tdimport_start <manager_key> <archive_path>

    archive_path is a local filesystem path that panel_bot.py's OWN document
    handler has already downloaded the uploaded ZIP to (never the admin's raw
    Telegram-supplied filename -- panel_bot.py picks a clean, collision-safe
    scratch path, so this command never needs to defend against exotic
    characters in a user-supplied filename). Proxy must already be verified
    for this manager (the wizard's existing, unchanged proxy step) before
    this authorization-method branch is even offered.

    Runs everything up to (and including) identity verification. Nothing is
    installed onto the manager's live session yet -- fully reversible on any
    failure (only scratch files under runtime\\tdata_import\\<op>\\ exist)."""
    parts = (args or "").strip().split(maxsplit=1)
    if len(parts) < 2:
        return _repl3_json_result({
            "ok": False, "error_class": "invalid_archive",
            "error_text": "usage: /manager_tdimport_start <manager_key> <archive_path>",
        })
    manager_key = registry_normalize_manager_key(parts[0])
    archive_path = parts[1].strip()

    row = await manager_get(manager_key)
    if not row:
        return _repl3_json_result({"ok": False, "error_class": "stale_operation", "error_text": "manager not found"})

    # TPILOT PREPARED ACCOUNTS PHASE 4: fail closed BEFORE any proxy/network
    # work. This online pipeline's remaining steps (proxy re-verification,
    # client_factory, identity_probe, confirm_install, runtime spawn) are
    # exactly what the prepared-accounts architecture forbids for Session/
    # TData prepare (SESSION_PREPARE_NETWORK_CALLS=0 /
    # TDATA_PREPARE_NETWORK_CALLS=0) -- a future offline importer (Phase 5)
    # is the only sanctioned path for a status='prepared' manager. This
    # guard does not modify tdata_import/* at all; it simply never calls
    # into it for a prepared target.
    if str(row.get("status") or "").strip().lower() == "prepared":
        return _repl3_json_result({
            "ok": False, "error_class": "prepared_online_import_blocked",
            "error_text": "Онлайн-импорт запрещён для подготовленного аккаунта. Требуется офлайн-подготовка.",
        })

    proxy_row = _tdimport_proxy_row_from_manager(row)
    operation_id = _tdimport_new_operation_id(manager_key)
    work_root = str(BASE_DIR / "runtime" / "tdata_import" / operation_id)

    live_paths = ensure_manager_dirs(str(BASE_DIR), manager_key)
    known_session_paths = [live_paths.get("session_path")]

    # PROBE-WIRING FIX 20260719: session_path is the REAL validated candidate
    # service.py just selected/converted (session_inspector already passed it) --
    # NEVER a separate/blank decoy file. The previous hardcoded
    # `work_root/probe.session` was never written to, so Telethon silently
    # opened an empty session and minted a fresh, unauthorized auth_key on
    # connect: the probe leg "succeeded" up to connect() but get_me() then
    # always returned None -> session_unauthorized, regardless of whether the
    # source tdata/.session was actually valid. See tdata_import/service.py's
    # start_import (client_factory(session_source_path) call) for the other
    # half of this fix.
    async def _client_factory(session_path: str):
        return await _tdimport_client_factory_for(row, session_path)

    def _dup_check(tg_id: int):
        return _tdimport_storage.tdata_import_tg_user_conflict(tg_id, db_path=TPILOT_DB_PATH)

    def _reserved_check(tg_id: int):
        return _tdimport_storage.tdata_import_tgid_reserved_by_other(tg_id, operation_id, db_path=TPILOT_DB_PATH)

    result = await _tdimport_service.start_import(
        operation_id=operation_id, manager_key=manager_key, archive_path=archive_path,
        work_root=work_root, proxy_row=proxy_row, client_factory=_client_factory,
        owner_user_id=int(requested_by or 0), source_key=str(row.get("source_key") or row.get("source") or ""),
        expires_at=_future_iso(3600),
        known_session_paths=known_session_paths, proxy_prober=_tdimport_real_prober,
        duplicate_check=_dup_check, reserved_check=_reserved_check,
        db_path=TPILOT_DB_PATH,
    )
    return _repl3_json_result(result)


async def _panel_manager_tdimport_status_command(args: str, *, requested_by: int = 0) -> str:
    """/manager_tdimport_status <operation_id>"""
    operation_id = (args or "").strip().split(maxsplit=1)[0] if (args or "").strip() else ""
    if not operation_id:
        return _repl3_json_result({"ok": False, "error_class": "stale_operation", "error_text": "usage: <operation_id>"})
    result = _tdimport_service.get_status(operation_id=operation_id, db_path=TPILOT_DB_PATH)
    return _repl3_json_result(result)


async def _panel_manager_tdimport_confirm_command(args: str, *, requested_by: int = 0) -> str:
    """/manager_tdimport_confirm <operation_id>

    Crosses the point of no return: re-verifies the proxy fresh, atomically
    installs the validated session, starts the runtime, blocks on the full
    readiness contract. Any failure here rolls back the install and leaves
    the target manager exactly as it was before this call."""
    operation_id = (args or "").strip().split(maxsplit=1)[0] if (args or "").strip() else ""
    if not operation_id:
        return _repl3_json_result({"ok": False, "error_class": "stale_operation", "error_text": "usage: <operation_id>"})

    status_row = _tdimport_service.get_status(operation_id=operation_id, db_path=TPILOT_DB_PATH)
    if not status_row.get("ok"):
        return _repl3_json_result(status_row)

    manager_key = status_row.get("manager_key") or ""
    mrow = await manager_get(manager_key)
    if not mrow:
        return _repl3_json_result({"ok": False, "error_class": "stale_operation", "error_text": "manager not found"})

    proxy_row = _tdimport_proxy_row_from_manager(mrow)
    result = await _tdimport_service.confirm_install(
        operation_id=operation_id, base_dir=str(BASE_DIR), proxy_row=proxy_row,
        spawn_runtime=_tdimport_spawn_runtime, wait_runtime_ready=_tdimport_wait_runtime_ready,
        stop_runtime=_tdimport_stop_runtime, is_runtime_running=_tdimport_is_runtime_running,
        proxy_prober=_tdimport_real_prober,
        db_path=TPILOT_DB_PATH,
    )
    # TPILOT TDATA ONBOARDING CONVERGENCE 20260719 (Part D): converge onto the
    # SAME screenshots-on + source-pick primitives phone/QR/relogin/replacement
    # already use via _manager_finalize_login -- WITHOUT calling that finalize
    # directly (it owns phone/ownership/runtime-state semantics for a fresh
    # project-API sign_in and would clobber this already-installed imported
    # manager's state). Applied unconditionally on every successful install
    # (new manager OR relogin/replacement of an existing one), mirroring
    # _manager_finalize_login's own "every successful login/re-login" rule for
    # screenshots; the already-linked check is what makes this a no-op for an
    # existing manager that already has a source (Part D-4: no duplicate link,
    # no forced reselection).
    if result.get("ok"):
        try:
            await _tp_finalize_screenshots_on(manager_key)
        except Exception as e:
            print(f"[tdimport] screenshot config force-on failed for {manager_key}: {e!r}")
        try:
            already_linked = bool(await _partner_source_key_for_manager(manager_key))
        except Exception:
            already_linked = True  # fail closed: never nag an already-working setup
        result["source_pick_needed"] = not already_linked
    return _repl3_json_result(result)


async def _panel_manager_tdimport_cancel_command(args: str, *, requested_by: int = 0) -> str:
    """/manager_tdimport_cancel <operation_id>"""
    operation_id = (args or "").strip().split(maxsplit=1)[0] if (args or "").strip() else ""
    if not operation_id:
        return _repl3_json_result({"ok": False, "error_class": "stale_operation", "error_text": "usage: <operation_id>"})
    result = _tdimport_service.cancel_import(operation_id=operation_id, db_path=TPILOT_DB_PATH)
    return _repl3_json_result(result)


_TDIMPORT_PREV_PANEL_EXEC = globals().get("_panel_execute_command_text")

_TDIMPORT_DISPATCH = {
    "/manager_tdimport_start": _panel_manager_tdimport_start_command,
    "/manager_tdimport_status": _panel_manager_tdimport_status_command,
    "/manager_tdimport_confirm": _panel_manager_tdimport_confirm_command,
    "/manager_tdimport_cancel": _panel_manager_tdimport_cancel_command,
}


async def _panel_execute_command_text(  # type: ignore[override]
    command_text: str, *, requested_by: int = 0, source_chat_id: int = 0, response_chat_id: int = 0
) -> Dict[str, Any]:
    cmd, args = _parse_cmd(str(command_text or ""))
    handler = _TDIMPORT_DISPATCH.get(cmd)
    if handler is not None:
        return {"ok": True, "result_text": await handler(args, requested_by=requested_by)}
    if callable(_TDIMPORT_PREV_PANEL_EXEC):
        try:
            return await _TDIMPORT_PREV_PANEL_EXEC(command_text, requested_by=requested_by, source_chat_id=source_chat_id, response_chat_id=response_chat_id)
        except TypeError:
            try:
                return await _TDIMPORT_PREV_PANEL_EXEC(command_text, requested_by=requested_by)
            except TypeError:
                return await _TDIMPORT_PREV_PANEL_EXEC(command_text)
    return {"ok": False, "result_text": f"Команда не поддерживается: {cmd}"}
# --- TPILOT TDATA/SESSION IMPORT ADMINBOT WIRING 20260719 END ---


# --- TPILOT DEVICE-LOGIN (connect Telegram on another device) BEGIN ---
# Feature: AdminBot "🔐 Подключить Telegram на устройстве" -- helps an admin log
# an already-managed TPilot account into ANOTHER official Telegram client.
# TPilot never calls auth.sendCode; the external official client initiates
# login and Telegram delivers the code as a message from its service peer
# (777000) to the manager's own already-authorized session. This module only
# LISTENS for that message, validates its source strictly, extracts the code,
# and hands it to AdminBot over a local one-shot 127.0.0.1 loopback bridge --
# see login_code_parser.py and storage.py's manager_device_login_ops for the
# durable safe-metadata side.
#
# SECURITY INVARIANT (do not weaken): the OTP and the plaintext capability
# token are NEVER written to any SQLite table, panel_commands,
# manager_commands, result_json/result_text/error_text, or logged. See
# storage.py's _DEVLOGIN_MUTABLE_FIELDS -- there is no column for either
# value. The OTP is re-read from Telegram on demand at fetch time and
# returned directly over the loopback socket; it is never cached in a
# runtime-side RAM map between capture and fetch.
import hashlib as _devlogin_hashlib
import hmac as _devlogin_hmac
import json as _devlogin_json
import secrets as _devlogin_secrets
import struct as _devlogin_struct
import storage as _devlogin_storage
from login_code_parser import parse_login_code as _devlogin_parse_code

DEVLOGIN_SERVICE_PEER_ID = 777000
DEVLOGIN_REQUEST_TTL_SEC = 180
DEVLOGIN_MESSAGE_MAX_LEN = 512
DEVLOGIN_CLOCK_SKEW_SEC = 5
DEVLOGIN_CATCHUP_LIMIT = 5
DEVLOGIN_RESCAN_INTERVAL_SEC = 15
DEVLOGIN_SWEEP_INTERVAL_SEC = 20
DEVLOGIN_COOLDOWN_SEC = 30
DEVLOGIN_BRIDGE_IO_TIMEOUT_SEC = 2.0
DEVLOGIN_BRIDGE_MAX_REQUEST_BYTES = 256
DEVLOGIN_BRIDGE_MAX_RESPONSE_BYTES = 64
DEVLOGIN_BRIDGE_MAX_CONNECTIONS = 4

# Manager-runtime-local state (one process per manager -- a module-level dict
# is safe here, never shared across processes). Keyed by request_id. Holds
# only the asyncio server/lock/connection-count -- NEVER an OTP.
_DEVLOGIN_BRIDGES: Dict[str, Dict[str, Any]] = {}


def _devlogin_iso_to_dt(iso_str: str):
    try:
        dt = datetime.fromisoformat(str(iso_str))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt
    except Exception:
        return None


async def _devlogin_validate_and_parse(row: Dict[str, Any], message) -> Optional[str]:
    """Shared strict validation gate + parser call, used by BOTH the live
    on_new_message capture and the bounded catch-up scan. Returns the 5-digit
    code STRING when `message` is a genuine, fresh, well-formed login-code
    service message for this exact request; else None. The returned code is
    used ONLY to prove one exists (gating waiting->received) -- callers must
    discard it immediately, never persist it."""
    try:
        if message is None:
            return None
        if bool(getattr(message, "out", False)):
            return None
        text = getattr(message, "message", None) or getattr(message, "raw_text", None) or ""
        if not text or len(text) > DEVLOGIN_MESSAGE_MAX_LEN:
            return None
        msg_id = int(getattr(message, "id", 0) or 0)
        if msg_id <= 0:
            return None
        started_dt = _devlogin_iso_to_dt(row.get("started_at") or "")
        msg_date = getattr(message, "date", None)
        if started_dt is not None and msg_date is not None:
            try:
                if msg_date < (started_dt - timedelta(seconds=DEVLOGIN_CLOCK_SKEW_SEC)):
                    return None
            except Exception:
                pass
        entities = getattr(message, "entities", None)
        return _devlogin_parse_code(text, entities=entities)
    except Exception:
        return None


async def _devlogin_try_capture_message(row: Dict[str, Any], message) -> bool:
    """CAS waiting->received on a validated match. Records ONLY
    telegram_message_id + received_at -- the OTP itself is discarded the
    instant this function proves one exists. Dedup via devlogin_seen_msg
    guards against the live handler and a concurrent catch-up scan racing on
    the SAME message."""
    request_id = str(row.get("request_id") or "")
    if not request_id:
        return False
    msg_id = int(getattr(message, "id", 0) or 0)
    if msg_id <= 0:
        return False
    code = await _devlogin_validate_and_parse(row, message)
    if not code:
        return False
    code = None  # noqa: F841 -- explicit wipe; only proved existence, never stored
    if not _devlogin_storage.devlogin_seen_mark_once(request_id, msg_id, db_path=TPILOT_DB_PATH):
        return False
    moved = _devlogin_storage.devlogin_transition(
        request_id, "waiting", "received",
        fields={"telegram_message_id": msg_id, "received_at": _now_utc_iso()},
        db_path=TPILOT_DB_PATH,
    )
    return bool(moved)


async def _devlogin_maybe_capture(event) -> bool:
    """Runtime-only live intercept, called from on_new_message BEFORE
    _record_incoming_from_manager -- returns True (consuming the event, so it
    never becomes a "lead") iff `event` is a valid 777000 login-code service
    message matching this manager's active waiting devlogin request."""
    if CONTROLLER_MODE or not MANAGER_RUNTIME_KEY:
        return False
    try:
        sender_id = int(getattr(event, "sender_id", 0) or 0)
    except (TypeError, ValueError):
        return False
    if sender_id != DEVLOGIN_SERVICE_PEER_ID:
        return False
    try:
        if bool(getattr(event, "out", False)):
            return False
        if not bool(getattr(event, "is_private", True)):
            return False
        row = _devlogin_storage.devlogin_get_active_for_manager(MANAGER_RUNTIME_KEY, db_path=TPILOT_DB_PATH)
        if not row or row.get("status") != "waiting":
            return False
        expires_at = str(row.get("expires_at") or "")
        if expires_at and expires_at <= _now_utc_iso():
            return False
        return await _devlogin_try_capture_message(row, event.message)
    except Exception as e:  # noqa: BLE001 -- must never break lead processing
        print(f"devlogin capture error: {type(e).__name__}")
        return False


async def _devlogin_scan_once(request_id: str) -> Dict[str, Any]:
    """Bounded catch-up: inspect ONLY the last DEVLOGIN_CATCHUP_LIMIT messages
    from the service peer, never a full history scan, and only while this
    exact request is still 'waiting'. Same validation/parse/dedup/CAS path as
    the live handler."""
    if CONTROLLER_MODE or not MANAGER_RUNTIME_KEY:
        return {"ok": False, "error_class": "not_runtime"}
    row = _devlogin_storage.devlogin_get(request_id, db_path=TPILOT_DB_PATH)
    if not row or row.get("manager_key") != MANAGER_RUNTIME_KEY or row.get("status") != "waiting":
        return {"ok": True, "captured": False}
    try:
        async for msg in client.iter_messages(DEVLOGIN_SERVICE_PEER_ID, limit=DEVLOGIN_CATCHUP_LIMIT):
            if await _devlogin_try_capture_message(row, msg):
                return {"ok": True, "captured": True}
    except Exception as e:
        return {"ok": False, "error_class": "scan_failed", "error_text": type(e).__name__}
    return {"ok": True, "captured": False}


async def _devlogin_bridge_read_frame(reader, max_bytes: int) -> Optional[bytes]:
    try:
        header = await reader.readexactly(4)
    except Exception:
        return None
    (length,) = _devlogin_struct.unpack(">I", header)
    if length <= 0 or length > max_bytes:
        return None
    try:
        return await reader.readexactly(length)
    except Exception:
        return None


async def _devlogin_bridge_write_frame(writer, payload: bytes) -> None:
    writer.write(_devlogin_struct.pack(">I", len(payload)) + payload)
    await writer.drain()


async def _devlogin_bridge_reject(writer) -> None:
    body = b'{"ok":false,"reason":"unavailable"}'
    try:
        await _devlogin_bridge_write_frame(writer, body)
    except Exception:
        pass


async def _devlogin_bridge_serve_one(request_id: str, state: Dict[str, Any], reader, writer) -> None:
    """ATOMIC one-shot delivery sequence (runtime side), executed under the
    per-request lock in `state`:
      1. read+parse the bounded request frame;
      2. validate request_id/manager_key/status='received'/expiry/message_id;
      3. hmac.compare_digest(sha256(presented_token), token_hash);
      4. CAS received->delivered BEFORE reading the OTP (devlogin_claim_for_
         delivery) -- ONLY the CAS winner proceeds;
      5. winner re-reads the exact 777000 message by id, parses again, returns
         the code;
      6. a losing/repeated/concurrent fetch always gets a generic reject,
         never a stale/duplicate code.
    """
    body = await _devlogin_bridge_read_frame(reader, DEVLOGIN_BRIDGE_MAX_REQUEST_BYTES)
    if body is None:
        await _devlogin_bridge_reject(writer)
        return
    try:
        req = _devlogin_json.loads(body.decode("utf-8"))
    except Exception:
        await _devlogin_bridge_reject(writer)
        return
    presented_rid = str(req.get("request_id") or "")
    presented_token = str(req.get("token") or "")
    if presented_rid != request_id or not presented_token:
        await _devlogin_bridge_reject(writer)
        return

    lock = state.get("lock")
    async with lock:
        row = _devlogin_storage.devlogin_get(request_id, db_path=TPILOT_DB_PATH)
        if not row or row.get("status") != "received":
            await _devlogin_bridge_reject(writer)
            return
        expires_at = str(row.get("expires_at") or "")
        if expires_at and expires_at <= _now_utc_iso():
            await _devlogin_bridge_reject(writer)
            return
        token_hash = str(row.get("token_hash") or "")
        presented_hash = _devlogin_hashlib.sha256(presented_token.encode("utf-8")).hexdigest()
        if not token_hash or not _devlogin_hmac.compare_digest(presented_hash, token_hash):
            await _devlogin_bridge_reject(writer)
            return
        message_id = int(row.get("telegram_message_id") or 0)
        if message_id <= 0:
            await _devlogin_bridge_reject(writer)
            return
        # ATOMIC one-shot claim BEFORE reading the OTP -- the CAS winner (and
        # only the winner) proceeds to re-read/parse/return the code. A
        # second, concurrent connection sees rowcount==0 here and rejects.
        won = _devlogin_storage.devlogin_claim_for_delivery(request_id, db_path=TPILOT_DB_PATH)
        if not won:
            await _devlogin_bridge_reject(writer)
            return

    # Re-read outside the lock (the claim above already serialized who "won";
    # Telegram network I/O does not need to hold the request lock).
    code = None
    try:
        msg = await client.get_messages(DEVLOGIN_SERVICE_PEER_ID, ids=message_id)
        if msg is not None:
            code = _devlogin_parse_code(getattr(msg, "message", "") or "", entities=getattr(msg, "entities", None))
    except Exception:
        code = None
    if not code:
        await _devlogin_bridge_reject(writer)
        return
    resp = _devlogin_json.dumps({"ok": True, "code": code}).encode("utf-8")
    code = None  # noqa: F841 -- explicit wipe of the local reference
    if len(resp) > DEVLOGIN_BRIDGE_MAX_RESPONSE_BYTES:
        await _devlogin_bridge_reject(writer)
        return
    await _devlogin_bridge_write_frame(writer, resp)


async def _devlogin_bridge_connection(request_id: str, reader, writer) -> None:
    state = _DEVLOGIN_BRIDGES.get(request_id)
    try:
        if state is None:
            await _devlogin_bridge_reject(writer)
            return
        if int(state.get("connections") or 0) >= DEVLOGIN_BRIDGE_MAX_CONNECTIONS:
            await _devlogin_bridge_reject(writer)
            return
        state["connections"] = int(state.get("connections") or 0) + 1
        try:
            await asyncio.wait_for(
                _devlogin_bridge_serve_one(request_id, state, reader, writer),
                timeout=DEVLOGIN_BRIDGE_IO_TIMEOUT_SEC,
            )
        finally:
            state["connections"] = max(0, int(state.get("connections") or 0) - 1)
    except Exception:
        try:
            await _devlogin_bridge_reject(writer)
        except Exception:
            pass
    finally:
        try:
            writer.close()
        except Exception:
            pass


async def _devlogin_start_bridge(request_id: str, manager_key: str) -> None:
    """Idempotent: (re)use an already-running bridge for this request, or
    start one. Binds STRICTLY 127.0.0.1 on an ephemeral port -- the actual
    bound address is verified before the bridge is considered usable. Writes
    ONLY bridge_host/bridge_port (safe metadata) into the durable row; never a
    token or code."""
    if CONTROLLER_MODE or not MANAGER_RUNTIME_KEY:
        return
    if request_id in _DEVLOGIN_BRIDGES:
        return
    state: Dict[str, Any] = {
        "request_id": request_id, "manager_key": manager_key,
        "lock": asyncio.Lock(), "server": None, "connections": 0,
    }
    _DEVLOGIN_BRIDGES[request_id] = state

    async def _handler(reader, writer):
        await _devlogin_bridge_connection(request_id, reader, writer)

    try:
        server = await asyncio.start_server(_handler, host="127.0.0.1", port=0)
    except Exception as e:
        _DEVLOGIN_BRIDGES.pop(request_id, None)
        print(f"devlogin bridge start error: {type(e).__name__}")
        return
    sockets = server.sockets or []
    bound_host, bound_port = "", 0
    if sockets:
        sockname = sockets[0].getsockname()
        bound_host, bound_port = sockname[0], sockname[1]
    if bound_host != "127.0.0.1":
        # Defense in depth: never keep a bridge that isn't strictly loopback.
        try:
            server.close()
        except Exception:
            pass
        _DEVLOGIN_BRIDGES.pop(request_id, None)
        return
    state["server"] = server
    _devlogin_storage.devlogin_set_fields(
        request_id, {"bridge_host": bound_host, "bridge_port": int(bound_port)}, db_path=TPILOT_DB_PATH,
    )


async def _devlogin_close_bridge(request_id: str) -> None:
    state = _DEVLOGIN_BRIDGES.pop(request_id, None)
    if not state:
        return
    server = state.get("server")
    if server is not None:
        try:
            server.close()
            await server.wait_closed()
        except Exception:
            pass


def _devlogin_new_request_id() -> str:
    return f"dl_{_devlogin_secrets.token_hex(4)}"


async def _panel_manager_devlogin_start_command(args: str, *, requested_by: int = 0) -> str:
    """/manager_devlogin_start <manager_key> <requested_by_user_id> <token_hash>

    token_hash MUST be the SHA-256 hex digest of a capability token AdminBot
    generated and keeps in its OWN RAM -- the plaintext token itself never
    reaches this command, this queue, or any DB column."""
    parts = (args or "").strip().split()
    if len(parts) < 3:
        return _repl3_json_result({"ok": False, "error_class": "invalid_archive",
                                   "error_text": "usage: <manager_key> <requested_by_user_id> <token_hash>"})
    manager_key = registry_normalize_manager_key(parts[0])
    try:
        requester_id = int(parts[1])
    except ValueError:
        return _repl3_json_result({"ok": False, "error_class": "invalid_archive", "error_text": "bad requested_by_user_id"})
    token_hash = parts[2].strip().lower()
    if len(token_hash) != 64 or any(c not in "0123456789abcdef" for c in token_hash):
        return _repl3_json_result({"ok": False, "error_class": "invalid_archive", "error_text": "bad token_hash"})

    row = await manager_get(manager_key)
    if not row:
        return _repl3_json_result({"ok": False, "error_class": "stale_operation", "error_text": "manager not found"})
    # TPILOT DEVICE-LOGIN PHONE 20260719 (Part B): managers.phone is now
    # self-healed from the LIVE session's me.phone on every runtime start
    # (see the runtime startup phone-resolution block) -- reading it here
    # already reflects that. Empty ONLY when Telegram itself never exposed a
    # phone for this account (a legitimate, rare case) -- the ONE remaining
    # legitimate phone-blocking case: creating a device-login request with no
    # phone to show would be a request the admin can never practically use.
    if not str(row.get("phone") or "").strip():
        return _repl3_json_result({
            "ok": False, "error_class": "phone_unavailable",
            "error_text": "Telegram-сессия не передала номер телефона. "
                          "Подключение на другом устройстве по номеру сейчас невозможно.",
        })
    if int(row.get("is_enabled") or 0) != 1 or str(row.get("status") or "") != "active":
        return _repl3_json_result({"ok": False, "error_class": "invalid_archive", "error_text": "manager runtime not active"})

    request_id = _devlogin_new_request_id()
    started_at = _now_utc_iso()
    expires_at = _future_iso(DEVLOGIN_REQUEST_TTL_SEC)
    # TPILOT DEVICE-LOGIN COOLDOWN 20260719: race-safe (single BEGIN IMMEDIATE
    # transaction, storage.py) enforcement of BOTH one-active-per-manager AND
    # a minimum DEVLOGIN_COOLDOWN_SEC since this manager's most recent
    # terminal (consumed/cancelled/expired/error) request -- server-side
    # durable timestamps only, never AdminBot RAM. See
    # storage.devlogin_create_with_cooldown's own docstring for the exact
    # atomicity guarantee.
    outcome = _devlogin_storage.devlogin_create_with_cooldown(
        request_id, manager_key, requested_by_user_id=requester_id,
        token_hash=token_hash, started_at=started_at, expires_at=expires_at,
        cooldown_sec=DEVLOGIN_COOLDOWN_SEC, db_path=TPILOT_DB_PATH,
    )
    if not outcome.get("ok"):
        reason = str(outcome.get("reason") or "")
        if reason == "cooldown":
            # The ONLY detail ever surfaced for a cooldown block: the number
            # of seconds remaining. Never a secret, never internal state.
            retry_after = int(outcome.get("retry_after_sec") or 0)
            return _repl3_json_result({
                "ok": False, "error_class": "cooldown_active", "retry_after_sec": retry_after,
                "error_text": f"подождите {retry_after} сек. перед повторным запросом",
            })
        return _repl3_json_result({"ok": False, "error_class": "concurrent_operation",
                                   "error_text": "another active device-login request already exists for this manager"})
    created = outcome.get("row") or {}
    if created.get("request_id") != request_id:
        return _repl3_json_result({"ok": False, "error_class": "runtime_failed",
                                   "error_text": "internal error creating the device-login request"})

    try:
        await _devlogin_storage.manager_queue_put(
            target_key=manager_key, command="devlogin_arm", created_by=str(requested_by or "panel"),
            payload_json=_devlogin_json.dumps({"request_id": request_id, "started_at": started_at}),
            expires_at=expires_at, db_path=TPILOT_DB_PATH,
        )
    except Exception as e:
        return _repl3_json_result({"ok": False, "error_class": "runtime_failed", "error_text": f"arm failed: {type(e).__name__}"})

    return _repl3_json_result({
        "ok": True, "request_id": request_id, "manager_key": manager_key,
        "status": "waiting", "expires_at": expires_at, "ttl_sec": DEVLOGIN_REQUEST_TTL_SEC,
    })


async def _panel_manager_devlogin_cancel_command(args: str, *, requested_by: int = 0) -> str:
    """/manager_devlogin_cancel <request_id> -- metadata-only CAS to
    'cancelled' + best-effort signal to the runtime to close its bridge. No
    OTP handling."""
    request_id = (args or "").strip().split(maxsplit=1)[0] if (args or "").strip() else ""
    if not request_id:
        return _repl3_json_result({"ok": False, "error_class": "stale_operation", "error_text": "usage: <request_id>"})
    row = _devlogin_storage.devlogin_get(request_id, db_path=TPILOT_DB_PATH)
    if not row:
        return _repl3_json_result({"ok": False, "error_class": "stale_operation", "error_text": "request not found"})
    ok = _devlogin_storage.devlogin_cancel(request_id, db_path=TPILOT_DB_PATH)
    if ok:
        try:
            await _devlogin_storage.manager_queue_put(
                target_key=str(row.get("manager_key") or ""), command="devlogin_close",
                created_by=str(requested_by or "panel"),
                payload_json=_devlogin_json.dumps({"request_id": request_id}),
                expires_at=_future_iso(60), db_path=TPILOT_DB_PATH,
            )
        except Exception:
            pass
    return _repl3_json_result({"ok": bool(ok), "request_id": request_id})


async def _panel_manager_devlogin_consume_command(args: str, *, requested_by: int = 0) -> str:
    """/manager_devlogin_consume <request_id> -- AdminBot calls this ONLY
    after it has already sent (or attempted to send) the code DM, purely to
    flip the durable status marker delivered->consumed and release the
    manager's active-request slot. Carries no code/token."""
    request_id = (args or "").strip().split(maxsplit=1)[0] if (args or "").strip() else ""
    if not request_id:
        return _repl3_json_result({"ok": False, "error_class": "stale_operation", "error_text": "usage: <request_id>"})
    ok = _devlogin_storage.devlogin_transition(
        request_id, "delivered", "consumed",
        fields={"consumed_at": _now_utc_iso()}, db_path=TPILOT_DB_PATH,
    )
    row = _devlogin_storage.devlogin_get(request_id, db_path=TPILOT_DB_PATH)
    if row:
        try:
            await _devlogin_storage.manager_queue_put(
                target_key=str(row.get("manager_key") or ""), command="devlogin_close",
                created_by=str(requested_by or "panel"),
                payload_json=_devlogin_json.dumps({"request_id": request_id}),
                expires_at=_future_iso(60), db_path=TPILOT_DB_PATH,
            )
        except Exception:
            pass
    return _repl3_json_result({"ok": bool(ok), "request_id": request_id})


async def _devlogin_sweep_loop() -> None:
    """Controller-only background sweep for abandoned/expired device-login
    requests. Moves any request past its expires_at (in waiting/received/
    delivered) to 'expired' -- releasing the one-active-per-manager slot --
    and best-effort signals the owning runtime to close its bridge. Never
    touches the OTP (there isn't one to touch here). Exception-safe;
    registered exactly once, only in CONTROLLER_MODE."""
    if not CONTROLLER_MODE:
        return
    await asyncio.sleep(30)
    while True:
        try:
            now = _now_utc_iso()
            stale = _devlogin_storage.devlogin_list_stale(now, db_path=TPILOT_DB_PATH)
            for row in stale:
                request_id = str(row.get("request_id") or "")
                if not request_id:
                    continue
                if _devlogin_storage.devlogin_expire(request_id, db_path=TPILOT_DB_PATH):
                    try:
                        await _devlogin_storage.manager_queue_put(
                            target_key=str(row.get("manager_key") or ""), command="devlogin_close",
                            created_by="sweeper",
                            payload_json=_devlogin_json.dumps({"request_id": request_id}),
                            expires_at=_future_iso(60), db_path=TPILOT_DB_PATH,
                        )
                    except Exception:
                        pass
        except Exception as e:  # noqa: BLE001
            print(f"devlogin sweep error: {e!r}")
        await asyncio.sleep(DEVLOGIN_SWEEP_INTERVAL_SEC)


async def _devlogin_rescan_loop() -> None:
    """Controller-only periodic bounded catch-up arm: for every request still
    'waiting', enqueue one lightweight devlogin_scan manager command (never
    floods -- one row per active manager per tick, and each scan itself is
    capped at DEVLOGIN_CATCHUP_LIMIT messages). Never carries an OTP."""
    if not CONTROLLER_MODE:
        return
    await asyncio.sleep(20)
    while True:
        try:
            active = _devlogin_storage.devlogin_list_stale("9999-12-31T23:59:59", db_path=TPILOT_DB_PATH)
            # list_stale(now) with a far-future "now" returns every currently
            # active (non-terminal) row regardless of individual expiry --
            # reused here purely as an "active rows" reader (its own
            # docstring: rows with expires_at < cutoff), avoiding a new
            # accessor for a read-only, non-secret rescan signal.
            for row in active:
                if str(row.get("status") or "") != "waiting":
                    continue
                request_id = str(row.get("request_id") or "")
                manager_key = str(row.get("manager_key") or "")
                if not request_id or not manager_key:
                    continue
                try:
                    await _devlogin_storage.manager_queue_put(
                        target_key=manager_key, command="devlogin_scan", created_by="rescan",
                        payload_json=_devlogin_json.dumps({"request_id": request_id}),
                        expires_at=_future_iso(30), db_path=TPILOT_DB_PATH,
                    )
                except Exception:
                    pass
        except Exception as e:  # noqa: BLE001
            print(f"devlogin rescan error: {e!r}")
        await asyncio.sleep(DEVLOGIN_RESCAN_INTERVAL_SEC)


_DEVLOGIN_PREV_PANEL_EXEC = globals().get("_panel_execute_command_text")

_DEVLOGIN_DISPATCH = {
    "/manager_devlogin_start": _panel_manager_devlogin_start_command,
    "/manager_devlogin_cancel": _panel_manager_devlogin_cancel_command,
    "/manager_devlogin_consume": _panel_manager_devlogin_consume_command,
}


async def _panel_execute_command_text(  # type: ignore[override]
    command_text: str, *, requested_by: int = 0, source_chat_id: int = 0, response_chat_id: int = 0
) -> Dict[str, Any]:
    cmd, args = _parse_cmd(str(command_text or ""))
    handler = _DEVLOGIN_DISPATCH.get(cmd)
    if handler is not None:
        return {"ok": True, "result_text": await handler(args, requested_by=requested_by)}
    if callable(_DEVLOGIN_PREV_PANEL_EXEC):
        try:
            return await _DEVLOGIN_PREV_PANEL_EXEC(command_text, requested_by=requested_by, source_chat_id=source_chat_id, response_chat_id=response_chat_id)
        except TypeError:
            try:
                return await _DEVLOGIN_PREV_PANEL_EXEC(command_text, requested_by=requested_by)
            except TypeError:
                return await _DEVLOGIN_PREV_PANEL_EXEC(command_text)
    return {"ok": False, "result_text": f"Команда не поддерживается: {cmd}"}
# --- TPILOT DEVICE-LOGIN (connect Telegram on another device) END ---


# --- TPILOT PROXY LIFECYCLE SYNC 20260721 BEGIN ---
# Bidirectional desired-vs-observed provider auto_renew reconciliation.
# Proxy-Seller has NO API to set auto_renew (verified against provider docs +
# proxy_provider.py: only order/make, prolong/make, proxy/comment/set exist)
# -- this block NEVER invents a provider mutation. It only: (1) computes the
# DESIRED state from live manager health/usage (proxy_lifecycle.compute_desired,
# shared-proxy protection built in), (2) compares against the OBSERVED state
# read from proxy/list (Phase 2's auto_renew field), (3) raises an explicit,
# deduplicated AdminBot action (ENABLE REQUIRED / DISABLE REQUIRED / CONFIRMED
# ON / CONFIRMED OFF) for a human to act on in the Proxy-Seller cabinet, and
# (4) once a provider read agrees with desired, advances the durable
# lifecycle_status and (for CONFIRMED_OFF) drops the lease from the active
# pool while retaining full history. Never calls order/make or prolong/make;
# never passes allow_spend=True (audited: this block adds ZERO allow_spend
# call sites -- the project-wide count stays exactly 2).
import proxy_lifecycle as _plc

_PLC_TERMINAL_GRACE_SEC = 1800  # 30 min: a manager must stay health_status='blocked'
                                 # this long before an admin is even offered the
                                 # "confirm terminal" button -- a single transient
                                 # failure never reaches this (manager_telegram_health
                                 # only enters 'blocked' via the durable _AUTH_MARKS
                                 # classifier, not per-probe warnings/limits).
_PLC_TERMINAL_REVIEW_SIGNATURE = "proxy_terminal_review"  # health_incidents dedupe key


async def _plc_manager_health_signal(manager_key: str) -> Dict[str, Any]:
    """Read-only: current manager_telegram_health row + grace-window verdict
    for one manager. Never writes. grace_elapsed is computed from
    first_seen_at, which manager_telegram_health already resets to '' the
    moment health_status changes away from the current value or returns to
    'ok' -- so first_seen_at IS the durable "since when has this been
    continuously blocked" timestamp, no new tracking table needed."""
    key = registry_normalize_manager_key(manager_key or "")
    if not key:
        return {"health_status": "", "grace_elapsed": False}
    try:
        async with aiosqlite.connect(TPILOT_DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute("SELECT * FROM manager_telegram_health WHERE manager_key=?", (key,))
            row = await cur.fetchone()
            health_row = dict(row) if row else {}
    except Exception:
        health_row = {}
    health_status = str(health_row.get("health_status") or "")
    grace_elapsed = False
    if health_status == "blocked":
        dt0 = _tp_hg_parse_iso(health_row.get("first_seen_at"))
        if dt0 is not None:
            grace_elapsed = (_tp_utc_now() - dt0).total_seconds() >= _PLC_TERMINAL_GRACE_SEC
    return {"health_status": health_status, "grace_elapsed": grace_elapsed}


async def _plc_scan_and_notify_terminal_candidates() -> int:
    """Proactively surface managers that look durably dead (blocked past the
    grace window) among CURRENTLY proxy-enabled managers, so an admin can
    review and confirm. Read-only against manager state; the only write is
    the health_incidents open-once dedupe marker (so this never re-notifies
    for the same still-unconfirmed manager on every tick) plus the
    notification row itself. NEVER touches proxy fields, NEVER unassigns --
    that only happens after an explicit admin confirm
    (_handle_proxy_lifecycle_terminal_confirm_command). Manual stop
    (is_enabled=0/manual_stopped=1) is NOT a candidate -- only a durable
    health_status='blocked' verdict is. Returns the number of new prompts sent."""
    import storage as _plc_storage
    usage_map = await _ppool_manager_usage_map()
    seen_managers: set = set()
    for entries in usage_map.values():
        for u in entries:
            seen_managers.add(str(u.get("manager_key") or ""))
    sent = 0
    for mk in sorted(m for m in seen_managers if m):
        sig = await _plc_manager_health_signal(mk)
        if sig["health_status"] != "blocked" or not sig["grace_elapsed"]:
            continue
        try:
            _plc_storage.ensure_health_incidents_table(TPILOT_DB_PATH)
            existing = _plc_storage.health_incident_get(mk, _PLC_TERMINAL_REVIEW_SIGNATURE, db_path=TPILOT_DB_PATH)
            was_open = bool(existing and str(existing.get("status") or "") == "open")
            _plc_storage.health_incident_upsert_open(mk, _PLC_TERMINAL_REVIEW_SIGNATURE, db_path=TPILOT_DB_PATH)
            if was_open:
                continue  # already prompted, still unconfirmed -- don't re-notify every tick
            _plc_storage.health_incident_mark_notified(mk, _PLC_TERMINAL_REVIEW_SIGNATURE, db_path=TPILOT_DB_PATH)
        except Exception:
            continue
        title = f"⛔ {mk}: аккаунт похож на окончательно недоступный"
        body = (
            f"{title}\n\nМенеджер: {mk}\nСтатус: заблокирован (durable), без восстановления "
            f"дольше {_PLC_TERMINAL_GRACE_SEC // 60} мин.\n\n"
            "Если аккаунт действительно мёртв — подтвердите, чтобы снять с него привязку "
            "прокси (другие менеджеры на том же прокси не пострадают, если он общий).\n"
            f"Подтвердить: /proxy_lifecycle_terminal_confirm {mk}"
        )
        await _create_panel_notification("proxy_lifecycle_terminal_review", title, body)
        sent += 1
    return sent


async def _handle_proxy_lifecycle_terminal_confirm_command(args: str) -> str:
    """/proxy_lifecycle_terminal_confirm <manager_key> -- the ONLY path that
    actually removes a still-existing (not hard-deleted) manager's proxy
    assignment. Re-verifies health_status='blocked' LIVE (never trusts a
    stale button/notification body) before doing anything. Stops the
    runtime, clears the manager's proxy fields, unassigns its lease (lease
    row retained), resolves the review-incident dedupe marker, then runs one
    targeted reconcile pass so a shared proxy correctly stays desired='Y' if
    another healthy manager still uses it, or flips to disable_required if
    not. Idempotent: confirming an already-confirmed/absent manager is a
    safe no-op."""
    key = registry_normalize_manager_key((args or "").strip())
    if not key:
        return _pbuy_json.dumps({"ok": False, "error": "bad_args", "message": "Формат: /proxy_lifecycle_terminal_confirm <manager_key>"}, ensure_ascii=False)
    row = await manager_get(key)
    if not row:
        return _pbuy_json.dumps({"ok": True, "already_gone": True, "manager_key": key}, ensure_ascii=False)
    sig = await _plc_manager_health_signal(key)
    if sig["health_status"] != "blocked" or not sig["grace_elapsed"]:
        return _pbuy_json.dumps({
            "ok": False, "error": "not_confirmed_terminal",
            "message": "Текущий статус менеджера не подтверждён как окончательно мёртвый (health не 'blocked' "
                       "дольше окна ожидания). Действие отклонено -- не рискуем живым аккаунтом.",
        }, ensure_ascii=False)

    await _stop_manager_process(key, silent=True)
    await _ppool_disable_manager_proxy_fields(key)
    import storage as _plc_storage
    lease = await _plc_storage.proxy_lease_get_for_manager(key, db_path=TPILOT_DB_PATH)
    if lease:
        await _plc_storage.proxy_lease_unassign(int(lease["id"]), db_path=TPILOT_DB_PATH)
        await _plc_storage.proxy_lifecycle_event_add(
            int(lease["id"]), "terminal_confirmed", provider_proxy_id=lease.get("provider_proxy_id"),
            actor="admin_confirm", detail=f"manager_key={key}", db_path=TPILOT_DB_PATH,
        )
    try:
        _plc_storage.health_incident_resolve(key, _PLC_TERMINAL_REVIEW_SIGNATURE, db_path=TPILOT_DB_PATH)
    except Exception:
        pass

    return _pbuy_json.dumps({
        "ok": True, "manager_key": key,
        "lease_unassigned": bool(lease), "lease_id": int(lease["id"]) if lease else None,
    }, ensure_ascii=False)


async def _plc_reconcile_all(provider_entries: List[Dict[str, Any]]) -> Dict[str, Any]:
    """TPILOT-MANAGED RENEWAL 20260721: the renewal-desire reconcile pass,
    called from _handle_proxy_pool_sync_command with the SAME provider entries
    that sync just read (no second provider call). For every active
    proxy_seller lease: renewal-desired is computed from the LIVE usage map
    (a hard-deleted or admin-confirmed-terminal manager has already had
    proxy_enabled cleared, so it no longer appears here -- no separate terminal
    check needed). The provider website `observed` value is captured for the
    informational card ONLY -- it NEVER drives an action anymore (website
    Auto-renewal is expected OFF everywhere; ENABLE/DISABLE REQUIRED are
    retired). The pass:
      1. records observed (informational) + desired on the lease;
      2. drives the local proxy_leases.auto_renew_enabled flag from the
         renewal desire (1 when TPilot should renew, 0 when free/terminal) --
         this is the SINGLE source of truth the renewal scheduler gates on;
      3. advances lifecycle_status (CONFIRMED_ON / released_off_confirmed) via
         CAS, only on an actual change, with one dedup'd informational
         notification.
    Never calls the provider; NEVER spends (no prolong/make here)."""
    import storage as _plc_storage
    observed_by_pid: Dict[str, str] = {}
    for e in provider_entries or []:
        pid = e.get("provider_proxy_id")
        if pid is not None:
            observed_by_pid[str(pid)] = str(e.get("auto_renew") or "")

    usage_map = await _ppool_manager_usage_map()
    leases = await _prenew_collect_active_seller_leases()

    summary: Dict[str, Any] = {
        _plc.CONFIRMED_ON: 0, _plc.CONFIRMED_OFF: 0, _plc.NO_ACTION: 0,
        "transitions": 0, "renew_flag_updates": 0, "provider_anomalies": 0,
    }
    for lease in leases:
        pid = str(lease.get("provider_proxy_id") or "")
        if not pid:
            continue
        usage_key = _ppool_usage_key(lease.get("host"), lease.get("port"))
        users = usage_map.get(usage_key, []) if usage_key else []
        desired = _plc.compute_renewal_desired([{"terminal": False} for _ in users])
        observed = observed_by_pid.get(pid, "")
        plan = _plc.reconcile_lease(lease, desired, observed)
        summary[plan["action"]] = summary.get(plan["action"], 0) + 1
        if plan.get("provider_anomaly"):
            summary["provider_anomalies"] += 1
        # (1) record observed (informational) + desired.
        await _plc_storage.proxy_lease_set_provider_state(
            int(lease["id"]), desired=plan["renewal_desired"],
            observed=plan["observed"] or None, provider_sync_at=_now_utc_iso(),
            db_path=TPILOT_DB_PATH,
        )
        # (2) drive the local TPilot-renewal flag from the renewal desire. This
        # is the ONLY thing the renewal scheduler reads. Idempotent: only write
        # when it actually differs, so a steady state is a no-op.
        want_flag = 1 if plan["renewal_desired"] == "Y" else 0
        cur_flag = int(lease.get("auto_renew_enabled") or 0)
        if plan["renewal_desired"] in ("Y", "N") and want_flag != cur_flag:
            await _plc_storage.proxy_lease_set_auto_renew(int(lease["id"]), bool(want_flag), db_path=TPILOT_DB_PATH)
            summary["renew_flag_updates"] += 1
            await _plc_storage.proxy_lifecycle_event_add(
                int(lease["id"]), "renewal_flag_set", provider_proxy_id=pid, actor="sync",
                desired=plan["renewal_desired"], observed=plan["observed"],
                detail=f"auto_renew_enabled={want_flag}", db_path=TPILOT_DB_PATH,
            )
        # (3) advance lifecycle_status on an actual change only.
        if not plan["changed"]:
            continue
        ok = await _plc_storage.proxy_lease_set_lifecycle(
            int(lease["id"]), plan["current_lifecycle_status"] or None, plan["target_lifecycle_status"],
            desired=plan["renewal_desired"], observed=plan["observed"],
            released_at=_now_utc_iso() if plan["release"] else None,
            release_reason="no_healthy_user" if plan["release"] else None,
            db_path=TPILOT_DB_PATH,
        )
        if not ok:
            continue  # lost the CAS race to a concurrent reconcile -- safe no-op
        summary["transitions"] += 1
        await _plc_storage.proxy_lifecycle_event_add(
            int(lease["id"]), plan["action"], provider_proxy_id=pid, actor="sync",
            desired=plan["renewal_desired"], observed=plan["observed"], db_path=TPILOT_DB_PATH,
        )
        # Informational notification ONLY (no ENABLE/DISABLE REQUIRED anymore).
        title = _plc.action_title(plan["action"])
        body = _plc.build_confirmation_text(plan["action"], lease)
        kind = "proxy_lifecycle_confirmed_on" if plan["action"] == _plc.CONFIRMED_ON else "proxy_lifecycle_confirmed_off"
        await _create_panel_notification(kind, title, body)
    return summary


async def _handle_proxy_lifecycle_status_command(args: str) -> str:
    """/proxy_lifecycle_status -- read-only list of every lease currently in
    an actionable mismatch state (enable_required/disable_required), with
    desired/observed/lifecycle_status. Never touches the provider."""
    import storage as _plc_storage
    rows = await _plc_storage.proxy_lifecycle_list_actionable(db_path=TPILOT_DB_PATH)
    items = [{
        "lease_id": r.get("id"), "provider_proxy_id": r.get("provider_proxy_id"),
        "host": r.get("host"), "port": r.get("port"),
        "lifecycle_status": r.get("lifecycle_status"),
        "desired": r.get("desired_provider_auto_renew"),
        "observed": r.get("observed_provider_auto_renew"),
        "provider_sync_at": r.get("provider_sync_at"),
    } for r in rows]
    return _pbuy_json.dumps({"ok": True, "actionable": items, "count": len(items)}, ensure_ascii=False)


async def _handle_proxy_lifecycle_cleanup_plan_command(args: str) -> str:
    """/proxy_lifecycle_cleanup_plan <provider_proxy_id...> -- read-only
    preview for an explicit allowlist (e.g. the confirmed-unused proxies):
    which targets are genuinely still unused (desired recomputes to 'N') vs.
    aborted because they became used or have no known lease. Never mutates
    anything -- purely a report; the actual DISABLE REQUIRED flagging happens
    automatically via the regular /proxy_pool_sync reconcile for ANY lease
    with desired='N', not a special cleanup action."""
    target_ids = [t.strip() for t in (args or "").split() if t.strip()]
    if not target_ids:
        return _pbuy_json.dumps({"ok": False, "error": "bad_args", "message": "Формат: /proxy_lifecycle_cleanup_plan <provider_proxy_id...>"}, ensure_ascii=False)
    import storage as _plc_storage
    usage_map = await _ppool_manager_usage_map()
    leases = await _prenew_collect_active_seller_leases()
    leases_by_pid = {str(l.get("provider_proxy_id") or ""): l for l in leases}
    desired_by_pid: Dict[str, str] = {}
    for pid, lease in leases_by_pid.items():
        usage_key = _ppool_usage_key(lease.get("host"), lease.get("port"))
        users = usage_map.get(usage_key, []) if usage_key else []
        desired_by_pid[pid] = _plc.compute_desired([{"terminal": False} for _ in users])
    plan = _plc.build_cleanup_plan(target_ids, leases_by_pid, desired_by_pid)
    return _pbuy_json.dumps({
        "ok": True,
        "include": [{"provider_proxy_id": l.get("provider_proxy_id"), "host": l.get("host"), "port": l.get("port")} for l in plan["include"]],
        "aborted": plan["aborted"],
    }, ensure_ascii=False)


async def _plc_reconcile_loop() -> None:
    """Periodic proactive tick: scans for newly-durably-blocked managers to
    prompt for terminal confirmation, then runs one read-only provider list +
    the same bidirectional reconcile as /proxy_pool_sync -- so ENABLE/DISABLE
    REQUIRED mismatches surface even if no admin happens to click sync.
    CONTROLLER_MODE only. Never spends; every provider call here is the
    existing read-only list_proxies. A single failed tick is logged and
    retried next tick -- never treated as terminal for anything.

    R5c (Proxy Renewal Reliability, 20260808): the SAME list_proxies read
    now also feeds _ppool_sync_entries_to_pool -- previously only a manual
    /proxy_pool_sync tap refreshed proxy_leases.expires_at/host/port from
    the provider's own state; a lease that fell out of sync (e.g. an
    unverified renewal) had no other path back to a correct expires_at.
    Still never touches manager_key/status (upsert_from_provider's own
    contract), so this cannot silently reassign or disable anything."""
    if CONTROLLER_MODE is False:
        return
    await asyncio.sleep(120)
    while True:
        try:
            await _plc_scan_and_notify_terminal_candidates()
        except Exception as e:
            print(f"[proxy_lifecycle] terminal-scan tick error: {e!r}")
        try:
            provider = _pbuy_provider()
            if provider is not None:
                lst = await _pbuy_call(provider.list_proxies, _PBUY_PROXY_TYPE)
                from proxy_provider import extract_proxy_entries as _plc_extract
                entries = _plc_extract(lst)
                await _ppool_sync_entries_to_pool(entries)
                await _plc_reconcile_all(entries)
        except Exception as e:
            print(f"[proxy_lifecycle] reconcile tick error: {e!r}")
        await asyncio.sleep(1800)  # 30 min -- generous cadence, avoids hammering the provider API


_PLC_PREV_PANEL_EXEC = globals().get("_panel_execute_command_text")

_PLC_DISPATCH = {
    "/proxy_lifecycle_terminal_confirm": _handle_proxy_lifecycle_terminal_confirm_command,
    "/proxy_lifecycle_status": _handle_proxy_lifecycle_status_command,
    "/proxy_lifecycle_cleanup_plan": _handle_proxy_lifecycle_cleanup_plan_command,
}


async def _panel_execute_command_text(  # type: ignore[override]
    command_text: str, *, requested_by: int = 0, source_chat_id: int = 0, response_chat_id: int = 0
) -> Dict[str, Any]:
    cmd, _, args = str(command_text or "").strip().partition(" ")
    handler = _PLC_DISPATCH.get(cmd)
    if handler is not None:
        try:
            result_text = await handler(args.strip())
        except Exception as exc:
            result_text = _pbuy_json.dumps({"ok": False, "error": "internal_error", "message": _pbuy_safe_error(exc)}, ensure_ascii=False)
        return {"ok": True, "result_text": result_text}
    if callable(_PLC_PREV_PANEL_EXEC):
        try:
            return await _PLC_PREV_PANEL_EXEC(command_text, requested_by=requested_by, source_chat_id=source_chat_id, response_chat_id=response_chat_id)
        except TypeError:
            try:
                return await _PLC_PREV_PANEL_EXEC(command_text, requested_by=requested_by)
            except TypeError:
                return await _PLC_PREV_PANEL_EXEC(command_text)
    return {"ok": False, "result_text": f"Команда не поддерживается: {cmd}"}
# --- TPILOT PROXY LIFECYCLE SYNC 20260721 END ---


# --- TPILOT PROXY RENEWAL (TPilot-managed prolong) 20260721 BEGIN ---
# Website provider Auto-renewal stays OFF permanently; TPilot renews the
# proxies it needs (auto_renew_enabled=1) itself via prolong/make. This block
# adds: idempotent op wrapping around the SINGLE existing spend executor
# (_prenew_execute_renewal), a no-spend calc preview, a lead-window scheduler
# (default 2 days, admin-configurable), guarded UNATTENDED automation
# (default OFF), restart reconcile, and the manual/config commands. It NEVER
# introduces a new allow_spend=True call -- every spend still funnels through
# _prenew_execute_renewal (line ~31009), so the project-wide allow_spend=True
# count stays EXACTLY 2.
_PRENEW_LEAD_DAYS_DEFAULT = 2

# Low-balance AdminBot alert (2026-07-21): read-only balance/get poll, no
# spend, never blocks bots/renewal on a read failure. Alerts immediately on
# crossing below the threshold, then at most once per 24h while still below,
# resets once the balance recovers.
_PRENEW_BALANCE_ALERT_THRESHOLD_USD = 20.0
_PRENEW_BALANCE_ALERT_COOLDOWN_SEC = 24 * 3600
_PRENEW_BALANCE_REFILL_URL = "https://proxy-seller.me/personal/balance"
_PRENEW_BALANCE_CHECK_INTERVAL_SEC = 1800  # 30 min -- matches _plc_reconcile_loop's cadence, avoids hammering the provider API

# Forward-fix P2 (post-incident review 2026-07-26): the scheduled tick below
# is already effectively single-flight (its only caller is the sequential
# _renewal_balance_alert_loop while-loop), but this lock makes that an
# explicit, enforced property rather than an incidental one -- wraps the
# WHOLE tick (fetch, snapshot-persist, threshold check, alert send/reset),
# so no future caller can ever overlap two ticks. Never wraps a provider
# spend call (_renewal_balance is read-only).
_PRENEW_BALANCE_TICK_LOCK = asyncio.Lock()


def _renewal_kyiv_today_str() -> str:
    return _kyiv_now().strftime("%Y-%m-%d")


_RENEWAL_ELIGIBLE_MIN_DELTA_DAYS = -1  # R5b: one day of catch-up grace, never unbounded-past


async def _renewal_eligible_leases(lead_days: int) -> List[Dict[str, Any]]:
    """Leases TPilot should renew now: auto_renew_enabled=1, status active,
    proxy_seller, provider_proxy_id present, and expiring within lead_days
    (Kyiv calendar-day math via the existing _ppool_parse_expires_at).
    Compares .date() to .date() -- same convention already used by
    _prenew_warn_eligible/_prenew_autorenew_gates_ok -- never subtracts full
    datetimes, so it is immune to the naive (parsed expiry) vs aware
    (_kyiv_now()) TypeError. Read-only.

    R5b (Proxy Renewal Reliability, 20260808): delta_days now also has a
    LOWER bound (_RENEWAL_ELIGIBLE_MIN_DELTA_DAYS). Previously a lease that
    expired months ago (delta_days e.g. -90) stayed permanently "due" and
    was retried by this engine's tick forever; one day of catch-up grace is
    kept (a lease that JUST expired may still be worth one retry), but
    genuinely stale expiries are excluded -- the normal cleanup/lifecycle
    path (not this scheduler) is what should deal with those."""
    leases = await _prenew_collect_active_seller_leases()
    out: List[Dict[str, Any]] = []
    today = _kyiv_now().date()
    for l in leases:
        if int(l.get("auto_renew_enabled") or 0) != 1:
            continue
        if not str(l.get("provider_proxy_id") or "").strip():
            continue
        exp = _ppool_parse_expires_at(l.get("expires_at"))
        if exp is None:
            continue  # unknown expiry -> never guess, skip
        delta_days = (exp.date() - today).days
        if _RENEWAL_ELIGIBLE_MIN_DELTA_DAYS <= delta_days <= int(lead_days):
            out.append(dict(l, _delta_days=delta_days))
    return out


async def _renewal_calc_preview(lease: Dict[str, Any]) -> Dict[str, Any]:
    """No-spend prolong/calc preview for ONE lease -- price/total/currency.
    prolong_calc never spends and is not allow_spend-gated. Never raises.

    BL-2 follow-up fix (independent re-review correction, 20260809): every
    failure branch now also carries error_category/reason/action (same shape
    as _prenew_preflight_check/_prenew_execute_renewal/_handle_proxy_renew_
    calc_command) -- this is the shared calc helper behind /proxy_renewal_calc
    (prn: UI) and both auto-renew engines, and its `message` field is only a
    best-effort _pbuy_safe_error scrub of the provider's own exception text
    (can still carry provider errors[]/customData), never a guaranteed-safe
    user-facing string. Callers must show reason/action, never message."""
    provider = _pbuy_provider()
    if provider is None:
        cat = _prenew_classify_provider_error(error_code="not_configured")
        return {
            "ok": False, "error": "not_configured", "message": "Proxy-Seller API key не настроен",
            "error_category": cat["category"], "reason": cat["reason"], "action": cat["action"],
        }
    provider_proxy_id = lease.get("provider_proxy_id")
    if not provider_proxy_id:
        return {
            "ok": False, "error": "missing_provider_proxy_id",
            "message": "У этого прокси нет provider_proxy_id — расчёт продления невозможен.",
            "reason": "У прокси нет привязки к провайдеру.", "action": "Обратитесь к провайдеру вручную.",
        }
    try:
        from proxy_provider import find_period_id, extract_renewal_info
        ref = await _pbuy_call(provider.reference_list, _PRENEW_PROXY_TYPE)
        period_id = find_period_id(ref, preferred_id=_PBUY_PERIOD_ID, preferred_name=_PBUY_PERIOD_NAME)
        if period_id is None:
            cat = _prenew_classify_provider_error(error_code="period_not_found")
            return {
                "ok": False, "error": "period_not_found", "message": "Период не найден в справочнике провайдера.",
                "error_category": cat["category"], "reason": cat["reason"], "action": cat["action"],
            }
        calc = await _pbuy_call(provider.prolong_calc, _PRENEW_PROXY_TYPE, [provider_proxy_id], period_id, _PRENEW_PAYMENT_ID)
        info = extract_renewal_info(calc)
        return {
            "ok": True, "lease_id": lease.get("id"), "provider_proxy_id": provider_proxy_id,
            "period_id": period_id, "price": info.get("price"), "total": info.get("total"),
            "currency": info.get("currency"),
        }
    except Exception as e:
        try:
            import traceback
            print(f"[proxy_renewal] calc_failed lease_id={lease.get('id')!r}:\n{provider._scrub_text(traceback.format_exc())}", flush=True)
        except Exception:
            pass
        err_text = _pbuy_safe_error(e)
        cat = _prenew_classify_provider_error(message=err_text, kind=getattr(e, "kind", None))
        return {
            "ok": False, "error": "calc_failed", "message": err_text,
            "error_category": cat["category"], "reason": cat["reason"], "action": cat["action"],
        }


async def _renewal_balance() -> Optional[float]:
    """Best-effort read of provider balance (read-only). None if unavailable."""
    provider = _pbuy_provider()
    if provider is None:
        return None
    try:
        data = await _pbuy_call(provider.balance)
        raw = data.get("summ") if isinstance(data, dict) else None
        return float(str(raw).replace(",", ".").strip()) if raw not in (None, "") else None
    except Exception:
        return None


async def _renewal_balance_alert_tick() -> None:
    """Read-only Proxy-Seller balance/get poll (via _renewal_balance -- no
    spend, no other provider call). Sends an AdminBot alert the moment the
    balance crosses below _PRENEW_BALANCE_ALERT_THRESHOLD_USD, then at most
    once per 24h while it stays below, and resets the dedup state once the
    balance recovers to the threshold or above. A read/DB failure is logged
    and this tick is skipped -- it can never stop a bot or block renewal.
    Never includes login/password/API key."""
    if not CONTROLLER_MODE:
        return
    async with _PRENEW_BALANCE_TICK_LOCK:
        try:
            balance = await _renewal_balance()
        except Exception as e:
            print(f"[proxy_renewal] balance alert check error: {e!r}")
            return
        if balance is None:
            print("[proxy_renewal] balance alert check: balance unavailable, skipping")
            return
        import storage as _rn_storage
        # Forward-fix P2 (post-incident review 2026-07-26): persist the
        # last-KNOWN-GOOD balance snapshot on EVERY successful read, before
        # the threshold/alert branching below -- the AdminBot root header
        # reads this snapshot directly and must never lose the last real
        # value just because a later fetch fails or the process restarts.
        # A write failure here is logged and never blocks the alert logic.
        try:
            await _rn_storage.proxy_balance_snapshot_write(value=balance, db_path=TPILOT_DB_PATH)
        except Exception as e:
            print(f"[proxy_renewal] balance snapshot write error: {e!r}")
        try:
            state = await _rn_storage.proxy_balance_alert_state_get(db_path=TPILOT_DB_PATH)
        except Exception as e:
            print(f"[proxy_renewal] balance alert state read error: {e!r}")
            return
        was_below = int(state.get("below_threshold") or 0) == 1
        if balance < _PRENEW_BALANCE_ALERT_THRESHOLD_USD:
            send = not was_below
            if was_below:
                last_at = state.get("last_alert_at")
                try:
                    elapsed = (_tp_utc_now() - datetime.fromisoformat(str(last_at))).total_seconds() if last_at else None
                except Exception:
                    elapsed = None
                send = elapsed is None or elapsed >= _PRENEW_BALANCE_ALERT_COOLDOWN_SEC
            if send:
                await _create_panel_notification(
                    "proxy_balance_low", "⚠️ Низкий баланс Proxy-Seller",
                    f"⚠️ Баланс Proxy-Seller ниже {int(_PRENEW_BALANCE_ALERT_THRESHOLD_USD)} $. Пополните баланс.\n\n"
                    f"Текущий баланс: {balance:.2f} $\n\n"
                    f"Пополнить: {_PRENEW_BALANCE_REFILL_URL}",
                )
                try:
                    await _rn_storage.proxy_balance_alert_state_set(
                        below_threshold=1, last_alert_at=_now_utc_iso(), db_path=TPILOT_DB_PATH,
                    )
                except Exception as e:
                    print(f"[proxy_renewal] balance alert state write error: {e!r}")
        elif was_below:
            try:
                await _rn_storage.proxy_balance_alert_state_set(
                    below_threshold=0, last_alert_at=None, db_path=TPILOT_DB_PATH,
                )
            except Exception as e:
                print(f"[proxy_renewal] balance alert state reset error: {e!r}")


async def _renewal_balance_alert_loop() -> None:
    """Dedicated low-cadence loop (independent of automation on/off, and of
    _renewal_loop's 6h tick) for the low-balance AdminBot alert -- a single
    lightweight read-only balance/get call every _PRENEW_BALANCE_CHECK_
    INTERVAL_SEC. CONTROLLER_MODE only; never spends."""
    if CONTROLLER_MODE is False:
        return
    await asyncio.sleep(60)
    while True:
        try:
            await _renewal_balance_alert_tick()
        except Exception as e:
            print(f"[proxy_renewal] balance alert loop error: {e!r}")
        await asyncio.sleep(_PRENEW_BALANCE_CHECK_INTERVAL_SEC)


async def _renewal_wrapped_execute(lease: Dict[str, Any], *, source: str, actor_user_id: Optional[int] = None) -> Dict[str, Any]:
    """Idempotent wrapper around the SINGLE spend executor _prenew_execute_
    renewal. Creates a proxy_renewal_ops row (RESERVED/'pending') under the
    CAS one-active-op-per-lease + unique idempotency_key guard BEFORE
    spending, so a scheduler double-fire, a concurrent run, or a restart can
    NEVER call prolong/make twice for the same renewal target. On skip (op
    already in flight) returns {ok:False, skipped:True} WITHOUT spending.
    Never adds a new allow_spend site -- delegates to _prenew_execute_renewal.

    BL-1 fix (Proxy Renewal Reliability review, 20260808): the PRE-SPEND /
    SPEND-ATTEMPTED boundary is drawn HERE. _prenew_preflight_check (provider
    configured / reference_list / period lookup -- all safe reads) now runs
    BEFORE proxy_renewal_op_create. A preflight failure returns immediately
    WITHOUT ever creating an op row, so the idempotency_key is never burned
    and the exact same lease/expires_at can be retried on the very next tick
    or the next manual tap -- Telegram's own outcome_notify dedupe (per
    error_category, see _prenew_autorenew_one) is the ONLY thing limiting how
    often the admin is told about it, never this idempotency layer.

    Crash-window fix (independent re-review correction, 20260809): op_create
    now writes status='pending' (RESERVED -- the idempotency_key is claimed,
    but prolong_make has NOT been called yet; a crash here is DEFINITELY
    not-spent) instead of the old 'make_pending' (which used to claim
    SPEND_STARTED from the moment of creation, before the spend attempt had
    even begun -- a crash in that narrow window between op_create's commit
    and the actual provider call permanently burned the idempotency_key for
    zero spend, with no recovery path). The explicit RESERVED -> SPEND_
    STARTED transition now happens inside _prenew_execute_renewal, atomically,
    immediately before prolong_make (see that function's own docstring). If
    that marker write never lands, _prenew_execute_renewal returns
    error='spend_marker_failed' WITHOUT ever calling the provider, and this
    wrapper frees the still-'pending' row (proven pre-spend) via
    proxy_renewal_op_delete_pending instead of the ordinary success/failed
    advance -- an audit trail is written first via proxy_lifecycle_event_add
    so the reservation-and-release is not silently invisible. Once the marker
    DOES land (the overwhelmingly common case), status is 'make_pending' by
    the time prolong_make runs, and everything below this point behaves
    exactly as before: a make_failed/unverified/any-other outcome can never
    silently re-spend for the same renewal cycle, and _renewal_reconcile_
    pending_on_start's existing provider-refresh reconcile still owns
    resolving a 'make_pending' row found after a restart.

    Money-safety correction (independent re-review, 20260809, second pass):
    an earlier version of this fix additionally freed the idempotency_key
    (via a CAS DELETE) whenever _prenew_execute_renewal's prolong_make
    except-block reported error_category kind PROVIDER_ERRORS or AUTH,
    reasoning that proxy_provider.py's own errors[]-before-HTTP-status
    check made those kinds structural proof the spend never happened. That
    reasoning was found unsound: _request() checks errors[] on EVERY
    response body regardless of HTTP status, so a 500/502/429 response
    that also carries a JSON errors[] list -- an ordinary shape for a
    provider-side failure -- produces the identical kind=PROVIDER_ERRORS a
    clean pre-billing rejection would, and ProxyProviderError carries no
    HTTP status or separate no-spend signal to tell them apart. That
    "provably no-spend" branch and its storage helper
    (proxy_renewal_op_delete_no_spend_failed) have been REMOVED: EVERY
    make_failed outcome, regardless of error_category/kind, now falls
    through to the SAME terminal 'failed' advance as an ambiguous
    transport/HTTP/response_shape failure always did -- idempotency_key
    stays burned, no automatic or manual second spend, resolved only by a
    later provider-refresh reconcile (_plc_reconcile_loop /
    _renewal_reconcile_pending_on_start) confirming the expiry actually
    advanced. See _prenew_classify_provider_error's docstring for the
    UI-text-only implication (post_spend action text is honest, but was
    never itself a money-safety signal)."""
    import storage as _rn_storage
    lease_id = int(lease.get("id"))
    provider_proxy_id = lease.get("provider_proxy_id")
    period_id = _PBUY_PERIOD_ID

    # CORRECTION B 20260810: this is the ONE choke point every renewal-spend
    # path funnels through (both auto-renew engines AND both manual confirm
    # commands -- see the 4 call sites of this function) -- so the orphan
    # gate goes HERE, before even the safe preflight read, to guarantee a
    # lease with no real current manager assignment can never reach
    # _prenew_execute_renewal (the sole allow_spend=True call site) no
    # matter which caller reached this function or whether that caller's
    # OWN gate (if any) was bypassed/missed.
    if await _prenew_lease_is_orphan(lease, context=f"wrapped_execute:{source}"):
        return {
            "ok": False, "skipped": True, "error": "orphan_lease",
            "message": "У этого прокси нет реального назначенного менеджера — автопродление и списание не выполняются.",
            "reason": "Прокси не привязан к активному менеджеру (orphan lease).",
            "action": "Проверьте привязку прокси в пуле (синхронизация/переназначение).",
        }

    # PRE-SPEND stage: safe read/precheck only, no op row, freely retryable.
    pre = await _prenew_preflight_check(lease)
    if not pre.get("ok"):
        return pre

    # RESERVED stage starts here: from this line on, a real op row exists
    # (status='pending') and the idempotency_key for this cycle is claimed --
    # but spend has NOT started yet (see _prenew_execute_renewal's own
    # atomic 'pending' -> 'make_pending' marker write, immediately before
    # prolong_make).
    idem = _rn_storage.proxy_renewal_idempotency_key(provider_proxy_id, lease.get("expires_at"), period_id)
    op_id = await _rn_storage.proxy_renewal_op_create(
        lease_id=lease_id, provider_proxy_id=provider_proxy_id, idempotency_key=idem,
        source=source, status="pending", period_id=period_id,
        expires_before=lease.get("expires_at"), actor_user_id=actor_user_id, db_path=TPILOT_DB_PATH,
    )
    if op_id is None:
        # BLOCKER-1 fix (retry-policy correction, 20260809): op_create
        # returns None for TWO structurally different reasons that share
        # the same IntegrityError path -- (a) a genuinely in-flight op
        # (partial-unique active-lease index: pending/calc_done/confirmed/
        # make_pending) that will resolve within seconds/minutes on its
        # own, benign; or (b) a TERMINAL 'failed' row for this exact
        # (provider_proxy_id, expires_before, period) triple already
        # occupying the GLOBAL idempotency_key index -- this lease is
        # durably stuck (the ambiguous-post-spend case this fix exists
        # for) and the admin needs to be told, not left in silence.
        # proxy_renewal_op_active_for_lease only ever matches the active-
        # state set, so a None result here proves it's case (b).
        active = await _rn_storage.proxy_renewal_op_active_for_lease(lease_id, db_path=TPILOT_DB_PATH)
        if active is not None:
            return {
                "ok": False, "skipped": True, "error": "already_in_flight",
                "message": "Продление для этого прокси уже выполняется (дедуп).",
                "reason": "Продление для этого прокси уже выполняется.",
                "action": "Дождитесь завершения текущей попытки и проверьте карточку прокси.",
            }
        return {
            "ok": False, "skipped": True, "error": "blocked_unresolved",
            "message": "Предыдущая попытка продления не подтверждена — повторное списание автоматически не выполняется.",
            "reason": "Предыдущая попытка продления не подтверждена.",
            "action": "Синхронизируйте пул и проверьте прокси.",
        }
    # THE spend (single allow_spend site, inside _prenew_execute_renewal).
    # Reuses the preflight's already-fetched provider/period_id/before_dt --
    # never repeats reference_list between the two stages. _op_id lets
    # _prenew_execute_renewal write the RESERVED -> SPEND_STARTED marker
    # atomically, immediately before the actual provider call.
    result = await _prenew_execute_renewal(lease, source=source, _preflight=pre, _op_id=op_id)
    now = _now_utc_iso()
    if result.get("error") == "spend_marker_failed":
        # The op never left 'pending' -- provably pre-spend. Free it (a
        # DELETE, since proxy_renewal_ops_idem_idx is a GLOBAL unique index,
        # not scoped to active statuses -- a mere status change would leave
        # the idempotency_key burned forever). Audit trail first, since the
        # row itself won't exist afterward.
        try:
            await _rn_storage.proxy_lifecycle_event_add(
                lease_id, "renewal_reservation_released", provider_proxy_id=provider_proxy_id,
                actor=source, detail=f"op_id={op_id} idempotency_key={idem} reason=spend_marker_failed",
                db_path=TPILOT_DB_PATH,
            )
        except Exception as exc:
            print(f"[proxy_renewal] reservation-release audit-log error op_id={op_id}: {exc!r}")
        try:
            await _rn_storage.proxy_renewal_op_delete_pending(op_id, db_path=TPILOT_DB_PATH)
        except Exception as exc:
            print(f"[proxy_renewal] pending op cleanup error op_id={op_id}: {exc!r}")
    elif result.get("ok"):
        await _rn_storage.proxy_renewal_op_advance(
            op_id, "success", from_status="make_pending", make_at=now,
            calc_total=result.get("total"), currency=result.get("currency"),
            expires_after=result.get("expires_at"), db_path=TPILOT_DB_PATH,
        )
    else:
        # Ambiguous (unverified, OR any make_failed regardless of
        # error_category/kind -- money-safety correction, independent
        # re-review, 20260809 second pass: kind alone is not sufficient
        # structural proof that prolong_make's charge didn't go through,
        # even for PROVIDER_ERRORS/AUTH -- see this function's own
        # docstring). Money MAY have moved. Terminal 'failed';
        # idempotency_key stays burned; no automatic OR manual second
        # spend for this cycle. Resolved only by a later provider-refresh
        # reconcile (_renewal_reconcile_pending_on_start / the periodic
        # proxy-lifecycle sync) confirming the expiry actually advanced.
        await _rn_storage.proxy_renewal_op_advance(
            op_id, "failed", from_status="make_pending", make_at=now,
            last_error=str(result.get("message") or result.get("error") or "renew_failed"),
            bump_retry=True, db_path=TPILOT_DB_PATH,
        )
    result["op_id"] = op_id
    return result


async def _renewal_reconcile_pending_on_start() -> None:
    """Restart safety for BOTH op stages the crash-window fix (independent
    re-review correction, 20260809) now distinguishes:

    - 'pending' (RESERVED, spend DEFINITELY not started -- the process died
      between proxy_renewal_op_create's commit and the atomic 'pending' ->
      'make_pending' marker write inside _prenew_execute_renewal, which is
      written immediately before prolong_make). No provider call is needed
      or made to resolve these: they are freed outright via proxy_renewal_op_
      delete_pending (a CAS DELETE that only ever touches a row still in
      'pending'), after an audit trail is written first (the row itself is
      gone afterward). This is what actually closes the crash-window blocker
      -- before this fix, an op created in 'make_pending' from the moment of
      creation looked identical to a genuinely-attempted spend to this same
      function, and was marked 'failed' while permanently keeping the
      idempotency_key burned for zero spend.

    - 'make_pending' (SPEND_STARTED, outcome unknown -- process died AFTER
      the marker write, so prolong_make may or may not have actually reached
      the provider) is reconciled exactly as before this fix: RE-READING the
      provider's current expiry, never by blindly re-calling prolong/make.
      If the provider's date_end advanced past the op's expires_before, the
      renewal actually succeeded -> mark success; otherwise mark failed --
      the op stays 'failed' permanently and its idempotency_key stays
      consumed, so a retry for this exact pre-renewal expiry is intentionally
      blocked (same fail-safe convention as an ordinary post-spend failure/
      unverified outcome; only a subsequent real renewal, which changes
      expires_at, produces a new key). Read-only provider call; never spends.
    """
    if not CONTROLLER_MODE:
        return
    import storage as _rn_storage

    # --- Stage 1: 'pending' (RESERVED) -- provably pre-spend, no provider
    # call needed. Audit first (DELETE below removes the row itself).
    reserved = await _rn_storage.proxy_renewal_ops_by_status(["pending"], db_path=TPILOT_DB_PATH)
    for op in reserved:
        op_id = op.get("id")
        try:
            await _rn_storage.proxy_lifecycle_event_add(
                op.get("lease_id"), "renewal_reservation_released", provider_proxy_id=op.get("provider_proxy_id"),
                actor="restart_reconcile", detail=f"op_id={op_id} idempotency_key={op.get('idempotency_key')} reason=orphaned_pending_at_startup",
                db_path=TPILOT_DB_PATH,
            )
        except Exception as exc:
            print(f"[proxy_renewal] restart reconcile reservation-release audit-log error op_id={op_id}: {exc!r}")
        try:
            await _rn_storage.proxy_renewal_op_delete_pending(op_id, db_path=TPILOT_DB_PATH)
        except Exception as exc:
            print(f"[proxy_renewal] restart reconcile pending-op cleanup error op_id={op_id}: {exc!r}")

    # --- Stage 2: 'make_pending' (SPEND_STARTED, outcome unknown) -- unchanged
    # provider-refresh reconcile.
    pending = await _rn_storage.proxy_renewal_ops_by_status(["make_pending"], db_path=TPILOT_DB_PATH)
    if not pending:
        return
    provider = _pbuy_provider()
    observed: Dict[str, Any] = {}
    if provider is not None:
        try:
            from proxy_provider import extract_proxy_entries
            lst = await _pbuy_call(provider.list_proxies, _PRENEW_PROXY_TYPE)
            for e in extract_proxy_entries(lst):
                pid = e.get("provider_proxy_id")
                if pid is not None:
                    observed[str(pid)] = e.get("expires_at")
        except Exception as e:
            print(f"[proxy_renewal] restart reconcile list error: {e!r}")
            return
    for op in pending:
        pid = str(op.get("provider_proxy_id") or "")
        before = _ppool_parse_expires_at(op.get("expires_before"))
        after_raw = observed.get(pid)
        after = _ppool_parse_expires_at(after_raw)
        if before is not None and after is not None and after > before:
            await _rn_storage.proxy_renewal_op_advance(
                op["id"], "success", from_status="make_pending",
                make_at=_now_utc_iso(), expires_after=str(after_raw), db_path=TPILOT_DB_PATH,
            )
            # Retry-policy fix (BLOCKER-1 correction, 20260809): the op row
            # alone confirming 'success' never used to reach proxy_leases --
            # the lease's own expires_at stayed frozen at the OLD
            # pre-renewal date, so nothing downstream (autorenew gating,
            # warn slots, the manager/pool cards) ever learned the renewal
            # actually went through. Write it through the same helper
            # _prenew_execute_renewal itself uses on a normal (non-crash)
            # success path, so a crash-recovered success and a live one are
            # indistinguishable to every other reader.
            try:
                from storage import proxy_lease_update_renew as _reconcile_update_renew
                await _reconcile_update_renew(
                    op.get("lease_id"), status_text="renew_ok", new_expires_at=str(after_raw), db_path=TPILOT_DB_PATH,
                )
            except Exception as exc:
                print(f"[proxy_renewal] restart reconcile lease-update error op_id={op.get('id')}: {exc!r}")
        else:
            await _rn_storage.proxy_renewal_op_advance(
                op["id"], "failed", from_status="make_pending",
                last_error="restart_reconcile: outcome unknown, provider expiry unchanged",
                bump_retry=True, db_path=TPILOT_DB_PATH,
            )


def _renewal_float(v: Any) -> Optional[float]:
    try:
        return float(str(v).replace(",", ".").strip())
    except Exception:
        return None


async def _renewal_guard_check(cfg: Dict[str, Any], calc_total: Any, day_str: str) -> Optional[str]:
    """Return a human-safe reason string if a guard BLOCKS this spend, else
    None (allowed). Checked BEFORE any spend. emergency_stop/paused > per-op
    cap > daily budget > balance."""
    if int(cfg.get("emergency_stop") or 0) == 1:
        return "аварийная остановка автопродления включена (emergency stop)"
    if int(cfg.get("paused") or 0) == 1:
        return "автопродление на паузе"
    total = _renewal_float(calc_total)
    cap = _renewal_float(cfg.get("max_amount_per_op"))
    if cap is not None and total is not None and total > cap:
        return f"сумма операции {total} превышает лимит на операцию {cap}"
    budget = _renewal_float(cfg.get("max_daily_spend"))
    if budget is not None and total is not None:
        import storage as _rn_storage
        spent = await _rn_storage.proxy_renewal_daily_spend_total(day_str, db_path=TPILOT_DB_PATH)
        if spent + total > budget:
            return f"дневной бюджет {budget} будет превышен (уже потрачено {spent}, операция {total})"
    min_bal = _renewal_float(cfg.get("min_balance_warn"))
    if min_bal is not None:
        bal = await _renewal_balance()
        if bal is not None and bal < min_bal:
            return f"баланс провайдера {bal} ниже порога {min_bal}"
    return None


async def _renewal_auto_tick_report_outcome(lease: Dict[str, Any], result: Dict[str, Any]) -> None:
    """Post-spend outcome reporting for the (dormant-by-default) TPilot-managed
    engine's auto tick -- brought to parity with _prenew_autorenew_one (BL-2/
    second-engine-UX follow-up fix, independent re-review correction,
    20260809). SUCCESS is SILENT (audit event only, NO ACTION REQUIRED = NO
    ALERT, same convention as _prenew_autorenew_one's R5 fix) -- the previous
    noisy per-lease 'Продлеваю автоматически...' / '✅ Продлено' pair sent two
    Telegram messages per renewal and, worse, the failure branch rendered
    result['message'] verbatim (a possibly-raw provider error string). A
    non-success outcome is now a SINGLE classified reason/action card, deduped
    per (lease, day, error_category) via the SAME proxy_renew_notify_mark_once
    key scheme _prenew_autorenew_one already uses ('outcome_notify:<category>')
    -- a category already reported by EITHER engine today for this lease is
    not repeated by this one. Reuses the SAME builders/kinds engine 1 already
    has wired in panel_bot.py (_create_panel_notification with kinds
    proxy_autorenew_unverified/_blocked/_failed, proxy_lifecycle_event_add) --
    no new notification framework. Never shows raw provider text."""
    import storage as _rat_storage
    lease_id = lease.get("id")
    # CORRECTION B 20260810: defensive barrier -- the primary gate is in the
    # caller (_renewal_auto_tick, before this is ever invoked for a blocked/
    # unresolved outcome) and inside _renewal_wrapped_execute itself (before
    # any result this function could receive is even produced), but this
    # function is also reachable with a hand-built {"ok": False, "error":
    # "blocked", ...} dict straight from the caller's own guard-check branch
    # -- re-checking here with the SAME classifier (not a second definition)
    # means a future caller can never reintroduce an orphan alert by simply
    # forgetting its own gate.
    if await _prenew_lease_is_orphan(lease, context="auto_tick_report"):
        return
    if result.get("ok"):
        try:
            total = result.get("total")
            price = result.get("price")
            currency = str(result.get("currency") or "").strip()
            amount_text = f"{total} {currency}".strip() if total is not None else (f"{price} {currency}".strip() if price is not None else "")
            await _rat_storage.proxy_lifecycle_event_add(
                lease_id, "renew_ok", provider_proxy_id=result.get("provider_proxy_id"),
                actor="auto", detail=f"old={result.get('old_expires_at')} new={result.get('expires_at')} amount={amount_text}".strip(),
                db_path=TPILOT_DB_PATH,
            )
        except Exception as exc:
            print(f"[proxy_renewal] auto-tick success audit-log error: {exc!r}")
        return

    error_code = str(result.get("error") or "")
    if error_code == "unverified":
        notify_category = "unverified"
    elif error_code == "blocked":
        notify_category = "blocked"
    elif error_code == "blocked_unresolved":
        notify_category = "blocked_unresolved"
    else:
        notify_category = str(result.get("error_category") or "unknown")
    day_str = _renewal_kyiv_today_str()
    should_notify = await _rat_storage.proxy_renew_notify_mark_once(
        lease_id, day_str, f"outcome_notify:{notify_category}", db_path=TPILOT_DB_PATH,
    )
    if not should_notify:
        return

    header = [
        f"Менеджер: {await _prenew_manager_identity_line(str(lease.get('manager_key') or ''))}",
        f"Ключ: {lease.get('manager_key') or '_'}",
        f"Прокси: {lease.get('host') or '_'}:{lease.get('port') or '_'}",
        f"Действует до: {_prenew_format_expires_display(lease.get('expires_at'))}",
    ]

    if error_code == "unverified":
        title = "⚠️ Продление прокси не подтверждено"
        lines = [title, "", *header, "",
                 "Списание могло пройти, но Proxy-Seller пока не подтвердил новый срок.",
                 "Повторное списание автоматически не выполняется.",
                 "",
                 "Что делать: синхронизируйте пул и проверьте прокси.",
                 "", f"lease_id: {lease_id}"]
        kind = "proxy_autorenew_unverified"
    elif error_code == "blocked_unresolved":
        # BLOCKER-1 fix (retry-policy correction, 20260809): parity with
        # _prenew_autorenew_one -- see that function's matching branch for
        # the full rationale. NO spend button.
        title = "⚠️ Продление прокси требует проверки"
        lines = [title, "", *header, "",
                 "Причина: предыдущая попытка продления не подтверждена.",
                 "Повторное списание автоматически не выполняется.",
                 "",
                 "Что делать: синхронизируйте пул и проверьте прокси.",
                 "", f"lease_id: {lease_id}"]
        kind = "proxy_autorenew_unverified"
    elif error_code == "blocked":
        title = "⛔ Автопродление заблокировано"
        lines = [title, "", *header, "",
                 f"Причина: {result.get('reason') or result.get('message') or 'автопродление заблокировано настройками'}",
                 "Что делать: проверьте настройки автопродления (лимиты/баланс/пауза).",
                 "", f"lease_id: {lease_id}"]
        kind = "proxy_autorenew_blocked"
    else:
        title = "⚠️ Не удалось продлить прокси"
        reason = result.get("reason") or "Не удалось определить причину ошибки провайдера."
        action = result.get("action") or "Откройте карточку прокси и проверьте вручную."
        lines = [title, "", *header, "",
                 f"Причина: {reason}",
                 f"Что делать: {action}",
                 "", f"lease_id: {lease_id}"]
        kind = "proxy_autorenew_failed"

    body = "\n".join(lines)
    try:
        await _create_panel_notification(kind, title, body)
    except Exception as exc:
        print(f"[proxy_renewal] auto-tick {kind} notify error: {exc!r}")


async def _renewal_auto_tick() -> None:
    """One guarded UNATTENDED automatic-renewal tick. Does NOTHING unless
    automation_enabled=1 (one-time admin consent) AND not paused/emergency.
    For each eligible lease within the guards: wrapped-execute (idempotent
    single-spend), then _renewal_auto_tick_report_outcome (silent success,
    classified single failure/unverified/blocked card). When automation is
    OFF this is a pure no-op (the scheduler still notifies 'due' separately).

    Second-engine-UX follow-up fix (independent re-review correction,
    20260809): the old noisy 'notify before, wrapped-execute, notify after'
    shape (two Telegram messages per renewal, the after-message showing raw
    result['message'] on failure) is gone -- both the guard-blocked case and
    the wrapped-execute outcome now go through the SAME classified/deduped
    reporting helper engine 1 (_prenew_autorenew_one) already uses."""
    if not CONTROLLER_MODE:
        return
    import storage as _rn_storage
    cfg = await _rn_storage.proxy_renewal_config_get(db_path=TPILOT_DB_PATH)
    if int(cfg.get("automation_enabled") or 0) != 1:
        return
    if int(cfg.get("paused") or 0) == 1 or int(cfg.get("emergency_stop") or 0) == 1:
        return
    lead_days = int(cfg.get("lead_days") or _PRENEW_LEAD_DAYS_DEFAULT)
    day_str = _renewal_kyiv_today_str()
    eligible = await _renewal_eligible_leases(lead_days)
    usage_map = await _ppool_manager_usage_map()  # once per tick, same pattern engine 1 uses
    for lease in eligible:
        # CORRECTION B 20260810: parity with engine 1 (_prenew_autorenew_loop),
        # which already gates on role BEFORE calling _renewal_guard_check/
        # reporting anything -- engine 2 had no such gate at all. Placed
        # before the guard-check/report call (not just relying on
        # _renewal_wrapped_execute's own gate further down) so an orphan
        # lease that also happens to be config-blocked does not even produce
        # a "⚠️ Автопродление заблокировано" card -- zero alerts, not just
        # zero spend, per the defensive-barrier requirement.
        if await _prenew_lease_is_orphan(lease, usage_map, context="auto_tick"):
            continue
        # skip if an op for this lease is already active (dedup) or already
        # renewed today (idempotency_key collision handled inside the wrapper).
        active = await _rn_storage.proxy_renewal_op_active_for_lease(int(lease["id"]), db_path=TPILOT_DB_PATH)
        if active:
            continue
        preview = await _renewal_calc_preview(lease)
        calc_total = preview.get("total") if preview.get("ok") else None
        block = await _renewal_guard_check(cfg, calc_total, day_str)
        if block:
            await _renewal_auto_tick_report_outcome(
                lease, {"ok": False, "error": "blocked", "message": block, "reason": block},
            )
            continue
        result = await _renewal_wrapped_execute(lease, source="auto", actor_user_id=None)
        if result.get("skipped") and result.get("error") != "blocked_unresolved":
            # Genuinely in-flight (another attempt just started) -- benign.
            continue
        # BLOCKER-1 fix (retry-policy correction, 20260809): a
        # 'blocked_unresolved' skip means a durably-stuck ambiguous op is
        # occupying this lease's idempotency_key -- fall through to the
        # SAME reporting helper as any other outcome so the admin is told
        # (parity with _prenew_autorenew_one; see that function for the
        # full rationale).
        await _renewal_auto_tick_report_outcome(lease, result)


async def _renewal_loop() -> None:
    """Daily-cadence renewal scheduler. On startup reconciles any make_pending
    op (restart safety), then every ~6h runs one automatic tick (a no-op when
    automation is OFF) -- 6h is dense enough that the daily 7-day-lead window
    always gets multiple shots to survive a transient provider/balance issue,
    without hammering the API. CONTROLLER_MODE only; never spends when
    automation is OFF."""
    if CONTROLLER_MODE is False:
        return
    await asyncio.sleep(90)
    try:
        await _renewal_reconcile_pending_on_start()
    except Exception as e:
        print(f"[proxy_renewal] startup reconcile error: {e!r}")
    while True:
        try:
            await _renewal_auto_tick()
        except Exception as e:
            print(f"[proxy_renewal] auto tick error: {e!r}")
        await asyncio.sleep(6 * 3600)


async def _handle_proxy_renewal_backfill_command(args: str) -> str:
    """/proxy_renewal_backfill -- one-time migration: set proxy_leases.auto_
    renew_enabled from the CURRENT lifecycle usage state (1 for a proxy with
    >=1 healthy user, 0 for free/terminal) WITHOUT any provider call and
    WITHOUT spending. Idempotent; writes only the local flag + an audit row.
    Never renews."""
    import storage as _rn_storage
    usage_map = await _ppool_manager_usage_map()
    leases = await _prenew_collect_active_seller_leases()
    set_on = 0
    set_off = 0
    for lease in leases:
        usage_key = _ppool_usage_key(lease.get("host"), lease.get("port"))
        users = usage_map.get(usage_key, []) if usage_key else []
        want = 1 if _plc.compute_renewal_desired([{"terminal": False} for _ in users]) == "Y" else 0
        cur = int(lease.get("auto_renew_enabled") or 0)
        if want == cur:
            continue
        await _rn_storage.proxy_lease_set_auto_renew(int(lease["id"]), bool(want), db_path=TPILOT_DB_PATH)
        await _rn_storage.proxy_lifecycle_event_add(
            int(lease["id"]), "renewal_flag_backfill", provider_proxy_id=lease.get("provider_proxy_id"),
            actor="backfill", detail=f"auto_renew_enabled={want}", db_path=TPILOT_DB_PATH,
        )
        if want:
            set_on += 1
        else:
            set_off += 1
    return _pbuy_json.dumps({"ok": True, "set_on": set_on, "set_off": set_off, "total_leases": len(leases)}, ensure_ascii=False)


async def _handle_proxy_renewal_status_command(args: str) -> str:
    """/proxy_renewal_status -- read-only summary: eligible/due, config,
    recent failed ops. Never spends."""
    import storage as _rn_storage
    cfg = await _rn_storage.proxy_renewal_config_get(db_path=TPILOT_DB_PATH)
    lead_days = int(cfg.get("lead_days") or _PRENEW_LEAD_DAYS_DEFAULT)
    eligible = await _renewal_eligible_leases(lead_days)
    failed = await _rn_storage.proxy_renewal_ops_by_status(["failed"], db_path=TPILOT_DB_PATH)
    balance = await _renewal_balance()
    return _pbuy_json.dumps({
        "ok": True,
        "automation_enabled": int(cfg.get("automation_enabled") or 0),
        "paused": int(cfg.get("paused") or 0),
        "emergency_stop": int(cfg.get("emergency_stop") or 0),
        "lead_days": lead_days,
        "due_count": len(eligible),
        "due": [{"lease_id": l.get("id"), "provider_proxy_id": l.get("provider_proxy_id"),
                 "host": l.get("host"), "port": l.get("port"), "expires_at": l.get("expires_at"),
                 "days_left": l.get("_delta_days")} for l in eligible[:50]],
        "failed_count": len(failed),
        "balance": balance,
    }, ensure_ascii=False)


async def _handle_proxy_renewal_calc_command(args: str) -> str:
    """/proxy_renewal_calc <lease_id> -- no-spend prolong/calc preview for one
    lease (cost/currency)."""
    import storage as _rn_storage
    try:
        lease_id = int(str(args or "").strip().split()[0])
    except Exception:
        return _pbuy_json.dumps({"ok": False, "error": "bad_args", "message": "Формат: /proxy_renewal_calc <lease_id>"}, ensure_ascii=False)
    lease = await _rn_storage.proxy_lease_get(lease_id, db_path=TPILOT_DB_PATH)
    if not lease:
        return _pbuy_json.dumps({"ok": False, "error": "lease_not_found", "message": f"Lease не найден: {lease_id}"}, ensure_ascii=False)
    preview = await _renewal_calc_preview(lease)
    return _pbuy_json.dumps(preview, ensure_ascii=False)


async def _handle_proxy_renewal_confirm_command(args: str) -> str:
    """/proxy_renewal_confirm <lease_id> [actor_user_id] -- MANUAL renewal:
    the admin has already seen the /proxy_renewal_calc preview and tapped
    confirm. Runs the idempotent wrapped single-spend execute. This is the
    manual-batch counterpart of the automatic tick; same single allow_spend
    site.

    Second-engine-manual-guard fix (independent re-review correction,
    20260809): this path previously called _renewal_wrapped_execute directly,
    bypassing _renewal_guard_check entirely -- emergency stop / pause / per-op
    cap / daily budget / min balance had NO effect on this button, unlike
    every other real spend path (_prenew_autorenew_one, _renewal_auto_tick,
    and the OTHER engine's own manual confirm _handle_proxy_renew_confirm_
    command, which already gates on this same guard). Now calls the SAME
    _renewal_guard_check (no duplicated guard logic) BEFORE _renewal_wrapped_
    execute, mirroring _handle_proxy_renew_confirm_command's exact shape; a
    block never creates an op row / never spends (pure pre-spend read, same
    as a preflight failure). Also mirrors that sibling's active-lease check --
    this button reaching a non-'active' lease is treated as lease_not_found,
    not silently spent against."""
    import storage as _rn_storage
    parts = str(args or "").strip().split()
    try:
        lease_id = int(parts[0])
    except Exception:
        return _pbuy_json.dumps({"ok": False, "error": "bad_args", "message": "Формат: /proxy_renewal_confirm <lease_id>"}, ensure_ascii=False)
    actor = None
    if len(parts) >= 2:
        try:
            actor = int(parts[1])
        except Exception:
            actor = None
    lease = await _rn_storage.proxy_lease_get(lease_id, db_path=TPILOT_DB_PATH)
    if not lease or str(lease.get("status") or "") != "active":
        return _pbuy_json.dumps({"ok": False, "error": "lease_not_found", "message": f"Активный lease не найден: {lease_id}"}, ensure_ascii=False)

    # CORRECTION B checkpoint follow-up 20260810: see the identical comment
    # in the sibling _handle_proxy_renew_confirm_command -- gate before ANY
    # provider interaction (including the no-spend calc preview below), not
    # just before spend.
    if await _prenew_lease_is_orphan(lease, context="manual_renewal_confirm_entry"):
        return _pbuy_json.dumps({
            "ok": False, "skipped": True, "error": "orphan_lease",
            "message": "У этого прокси нет реального назначенного менеджера — автопродление и списание не выполняются.",
            "reason": "Прокси не привязан к активному менеджеру (orphan lease).",
            "action": "Проверьте привязку прокси в пуле (синхронизация/переназначение).",
        }, ensure_ascii=False)

    cfg = await _rn_storage.proxy_renewal_config_get(db_path=TPILOT_DB_PATH)
    day_str = _renewal_kyiv_today_str()
    preview = await _renewal_calc_preview(lease)
    calc_total = preview.get("total") if preview.get("ok") else None
    block = await _renewal_guard_check(cfg, calc_total, day_str)
    if block:
        return _pbuy_json.dumps({
            "ok": False, "error": "blocked", "message": block,
            "reason": block, "action": "Проверьте настройки автопродления (лимиты/баланс/пауза).",
        }, ensure_ascii=False)

    result = await _renewal_wrapped_execute(lease, source="manual", actor_user_id=actor)
    return _pbuy_json.dumps(result, ensure_ascii=False)


async def _handle_proxy_renewal_config_command(args: str) -> str:
    """/proxy_renewal_config <key> <value> -- set one guard/config field.
    Config only; never spends. Enabling automation requires the explicit
    'enable_auto <user_id>' form (records consent)."""
    import storage as _rn_storage
    parts = str(args or "").strip().split()
    if not parts:
        cfg = await _rn_storage.proxy_renewal_config_get(db_path=TPILOT_DB_PATH)
        return _pbuy_json.dumps({"ok": True, "config": cfg}, ensure_ascii=False)
    key = parts[0].lower()
    if key == "enable_auto":
        user_id = int(parts[1]) if len(parts) >= 2 and parts[1].isdigit() else 0
        await _rn_storage.proxy_renewal_config_set(
            automation_enabled=1, enabled_by_user_id=user_id, enabled_at=_now_utc_iso(),
            paused=0, emergency_stop=0, db_path=TPILOT_DB_PATH,
        )
        return _pbuy_json.dumps({"ok": True, "automation_enabled": 1, "enabled_by_user_id": user_id}, ensure_ascii=False)
    if key == "disable_auto":
        await _rn_storage.proxy_renewal_config_set(automation_enabled=0, db_path=TPILOT_DB_PATH)
        return _pbuy_json.dumps({"ok": True, "automation_enabled": 0}, ensure_ascii=False)
    if key in ("pause", "resume", "emergency_stop", "clear_emergency"):
        fields = {
            "pause": {"paused": 1}, "resume": {"paused": 0},
            "emergency_stop": {"emergency_stop": 1}, "clear_emergency": {"emergency_stop": 0},
        }[key]
        await _rn_storage.proxy_renewal_config_set(db_path=TPILOT_DB_PATH, **fields)
        return _pbuy_json.dumps({"ok": True, **fields}, ensure_ascii=False)
    _settable = {"max_amount_per_op", "max_daily_spend", "min_balance_warn", "renewal_period_id", "lead_days"}
    if key in _settable and len(parts) >= 2:
        val: Any = parts[1]
        if key == "lead_days":
            try:
                val = int(parts[1])
            except Exception:
                return _pbuy_json.dumps({"ok": False, "error": "bad_args", "message": "lead_days должен быть целым числом"}, ensure_ascii=False)
        await _rn_storage.proxy_renewal_config_set(db_path=TPILOT_DB_PATH, **{key: val})
        return _pbuy_json.dumps({"ok": True, key: val}, ensure_ascii=False)
    return _pbuy_json.dumps({"ok": False, "error": "bad_args", "message": "Неизвестный ключ конфигурации."}, ensure_ascii=False)


_RENEWAL_PREV_PANEL_EXEC = globals().get("_panel_execute_command_text")

_RENEWAL_DISPATCH = {
    "/proxy_renewal_backfill": _handle_proxy_renewal_backfill_command,
    "/proxy_renewal_status": _handle_proxy_renewal_status_command,
    "/proxy_renewal_calc": _handle_proxy_renewal_calc_command,
    "/proxy_renewal_confirm": _handle_proxy_renewal_confirm_command,
    "/proxy_renewal_config": _handle_proxy_renewal_config_command,
}


async def _panel_execute_command_text(  # type: ignore[override]
    command_text: str, *, requested_by: int = 0, source_chat_id: int = 0, response_chat_id: int = 0
) -> Dict[str, Any]:
    cmd, _, args = str(command_text or "").strip().partition(" ")
    handler = _RENEWAL_DISPATCH.get(cmd)
    if handler is not None:
        try:
            result_text = await handler(args.strip())
        except Exception as exc:
            try:
                import traceback
                tb_text = traceback.format_exc()
                if PROXY_SELLER_API_KEY and PROXY_SELLER_API_KEY in tb_text:
                    tb_text = tb_text.replace(PROXY_SELLER_API_KEY, "***API_KEY***")
                print(f"[proxy_renewal] dispatcher error cmd={cmd!r}:\n{tb_text}", flush=True)
            except Exception:
                pass
            result_text = _pbuy_json.dumps({"ok": False, "error": "internal_error", "message": _pbuy_safe_error(exc)}, ensure_ascii=False)
        return {"ok": True, "result_text": result_text}
    if callable(_RENEWAL_PREV_PANEL_EXEC):
        try:
            return await _RENEWAL_PREV_PANEL_EXEC(command_text, requested_by=requested_by, source_chat_id=source_chat_id, response_chat_id=response_chat_id)
        except TypeError:
            try:
                return await _RENEWAL_PREV_PANEL_EXEC(command_text, requested_by=requested_by)
            except TypeError:
                return await _RENEWAL_PREV_PANEL_EXEC(command_text)
    return {"ok": False, "result_text": f"Команда не поддерживается: {cmd}"}
# --- TPILOT PROXY RENEWAL (TPilot-managed prolong) 20260721 END ---


# --- TPILOT HEALTH NOTIFICATION V2 20260807 START ---
# Root-cause classifier + persistent incident state machine for the health
# aggregator. Reuses the existing observation producers (manager_telegram_
# health / managers.auth_guard_* / start_status.json / manager_auto_
# recovery.log) and the existing health_incidents table (storage.py,
# additive HNV2 columns) -- adds NO new observation writers. See the
# approved plan (tpilot-health-notification-golden-wigderson.md) for the
# full design; this block implements it phase by phase via in-place
# appends, never a stacked override of any name the PeerFlood fail-closed
# selftest or the health_incident lifecycle selftest locks to an exact def
# count (_tp_hg_send_allowed, _send_manager_private,
# _process_profile_reminders_once, _process_post_manual_followups_once,
# _health_incident_handle, _health_incident_notify,
# _manager_recovery_classify, _manager_recovery_open_auth_incident,
# _manager_recovery_resolve_auth_incident, _m212a_write_start_status).

HNV2_ENABLED                      = (os.getenv("HNV2_ENABLED", "1") or "1").strip().lower() in ("1", "true", "yes", "on")
HNV2_ACCOUNT_MAX_AGE_SEC          = int(os.getenv("HNV2_ACCOUNT_MAX_AGE_SEC") or str(TP_HG_CHECK_INTERVAL_SEC * 3))
HNV2_PROXY_MAX_AGE_SEC            = int(os.getenv("HNV2_PROXY_MAX_AGE_SEC") or str(TPAG_V2_MONITOR_INTERVAL_SEC * 4))
HNV2_STUCK_STARTING_SEC           = int(os.getenv("HNV2_STUCK_STARTING_SEC") or "300")
HNV2_CONNECTED_MAX_AGE_SEC        = int(os.getenv("HNV2_CONNECTED_MAX_AGE_SEC") or "120")
HNV2_EXIT_EVIDENCE_MAX_AGE_SEC    = int(os.getenv("HNV2_EXIT_EVIDENCE_MAX_AGE_SEC") or "86400")
HNV2_STABLE_SEC                   = int(os.getenv("HNV2_STABLE_SEC") or "900")
HNV2_STABLE_SEC_SQLITE_LOCK       = int(os.getenv("HNV2_STABLE_SEC_SQLITE_LOCK") or "1800")
HNV2_SPAWN_VERIFY_DELAY_SEC       = int(os.getenv("HNV2_SPAWN_VERIFY_DELAY_SEC") or "45")
HNV2_READY_PROBE_MIN_INTERVAL_SEC = int(os.getenv("HNV2_READY_PROBE_MIN_INTERVAL_SEC") or "300")
HNV2_DAILY_PROBLEM_CAP            = int(os.getenv("HNV2_DAILY_PROBLEM_CAP") or "3")
HNV2_UNKNOWN_CONFIRM_SEC          = int(os.getenv("HNV2_UNKNOWN_CONFIRM_SEC") or "900")
HNV2_UNKNOWN_MIN_OBSERVATIONS     = int(os.getenv("HNV2_UNKNOWN_MIN_OBSERVATIONS") or "5")

# Root-cause family constants -- the canonical vocabulary this classifier
# returns. Deliberately distinct names from the existing _HAGG_*/TP_HG_
# STATUS_* vocabularies (main.py, health aggregator / telegram health
# guard) -- HNV2 does not replace either, it sits ABOVE them as an
# authoritative root-cause layer.
HNV2_FAMILY_SESSION_UNAUTHORIZED  = "session_unauthorized"
HNV2_FAMILY_ACCOUNT_BLOCKED       = "account_blocked"
HNV2_FAMILY_PEERFLOOD             = "telegram_limited_peerflood"
HNV2_FAMILY_FLOODWAIT             = "floodwait"
HNV2_FAMILY_PROXY_AUTH_FAILED     = "proxy_auth_failed"
HNV2_FAMILY_PROXY_UNAVAILABLE     = "proxy_unavailable"
HNV2_FAMILY_SQLITE_LOCK           = "sqlite_lock"
HNV2_FAMILY_NETWORK_TIMEOUT       = "network_timeout"
HNV2_FAMILY_WORKER_STUCK_STARTING = "worker_stuck_starting"
HNV2_FAMILY_WORKER_CRASH          = "worker_crash"
HNV2_FAMILY_RECOVERY_FLAP         = "recovery_flap"
HNV2_FAMILY_HEALTH_MISSING_STALE  = "health_missing_stale"
HNV2_FAMILY_OK                    = "ok"
HNV2_FAMILY_UNKNOWN               = "unknown"

# Evidence-text marker sets, each scoped to exactly the one classifier rule
# that uses it -- deliberately NOT the same tuples _tp_hg_classify_exception
# (main.py) uses for TP_HG's OWN status, since HNV2 asks a different
# question (root cause, not send-allowed/deny) even where the underlying
# Telegram error text overlaps.
_HNV2_SESSION_MARKS = (
    "authkeyunregistered", "auth_key_unregistered", "authkeyduplicated",
    "sessionrevoked", "sessionexpired", "sessionpasswordneeded",
    "session password needed", "session invalid", "authkeyerror",
    "unauthorized", "not authorized", "not authorised",
    # CORRECTION A 20260810: an identity mismatch discovered by live
    # verification (_tp_hg_verify_account_live) is written with
    # error_class="telegram_identity_mismatch" -- already grouped with
    # session_unauthorized/auth_session at the ss_reason_class signal path
    # above (see exit_rc_is_session / the ss_reason_class check just below),
    # this extends the SAME equivalence to the account_cls (manager_
    # telegram_health.error_class) signal path so Rule 1 catches it too,
    # routing to the same unified relogin/recovery chooser -- never treated
    # as a confirmed ban.
    "telegram_identity_mismatch",
)
_HNV2_ACCOUNT_BLOCKED_MARKS = (
    "userdeactivated", "userdeactivatedban", "phonenumberbanned", "banned",
    "frozen", "account deleted",
    # CORRECTION A 20260810: bare "deactivated" -- already used by panel_bot's
    # _PB_STATUS_BANNED_MARKS -- so a verified AccountDeactivatedConfirmed
    # error_class (written by _tp_hg_verify_account_live after live
    # confirmation) gets 'certain' confidence here too, not just 'probable'.
    "deactivated",
)
_HNV2_PROXY_AUTH_MARKS = (
    "407", "proxy authentication", "authentication required",
    "socks authentication", "bad credentials", "auth failed",
)
_HNV2_NETWORK_TIMEOUT_MARKS = (
    "timed out", "timeout", "connection reset", "server closed the connection",
    "0 bytes read", "disconnected",
)
_HNV2_SQLITE_LOCK_MARKS = ("database is locked", "database table is locked")
_HNV2_SQLITE_MALFORMED_MARKS = ("malformed", "corrupt")
# HNV2 F-1 fix: same three-token check TP_HG itself uses (~20695/21984) --
# real Telethon FloodWaitError.__str__() never contains the literal word
# "floodwait", only "A wait of {seconds} seconds is required (...)".
_HNV2_FLOODWAIT_TEXT_MARKS = ("floodwait", "flood wait", "wait of")


async def _hnv2_process_state(manager_key: str) -> str:
    """Tri-state wrapper around the SAME process-existence probe
    _manager_process_running (main.py:_manager_process_running) uses, but
    never collapses a probe FAILURE into 'absent' the way that function's
    own `except Exception: return False` does (2824/2829) -- that collapse
    is exactly what would let a PowerShell/CIM outage manufacture a false
    worker_crash classification. Returns 'running' | 'absent' |
    'probe_error'. Never raises."""
    key = registry_normalize_manager_key(manager_key or "")
    if not key:
        return "probe_error"
    if sys.platform.startswith("win"):
        script = (
            "$k='%s'; "
            "$p = Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -like ('*main.py*--manager*' + $k + '*') }; "
            "if ($p) { Write-Output '1' }"
        ) % key
        try:
            cp = subprocess.run(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", script], cwd=str(BASE_DIR), capture_output=True, text=True)
        except Exception:
            return "probe_error"
        if cp.returncode != 0:
            return "probe_error"
        return "running" if (cp.stdout or "").strip() else "absent"
    try:
        cp = subprocess.run(["pgrep", "-f", f"main.py --manager {key}"], cwd=str(BASE_DIR), capture_output=True, text=True)
    except Exception:
        return "probe_error"
    if cp.returncode not in (0, 1):
        # pgrep: 0 = matched, 1 = no match (a valid, successful "absent"
        # result), >=2 = a real pgrep error.
        return "probe_error"
    return "running" if (cp.stdout or "").strip() else "absent"


def _hnv2_collect_evidence(key: str, mrow: dict, hrow: dict, ss: dict, proc: str, flap_new: int, last_verify: str) -> dict:
    """Pure dict assembly -- no I/O of its own. All I/O (reading mrow/hrow/
    ss, probing proc, counting flap_new, resolving last_verify) is done by
    the caller and passed in, so this function -- and therefore the
    classifier that consumes its output -- is trivially unit-testable
    without a real DB, filesystem, or subprocess."""
    now = _tp_utc_now()
    mrow = mrow or {}
    hrow = hrow or {}
    ss = ss or {}

    def _age(ts_raw):
        dt = _tp_hg_parse_iso(ts_raw)
        if dt is None:
            return None
        try:
            return (now - dt).total_seconds()
        except Exception:
            return None

    return {
        "mrow": mrow, "hrow": hrow, "ss": ss,
        "proc": str(proc or "probe_error"),
        "flap_new": int(flap_new or 0),
        "last_verify": str(last_verify or "none"),
        "now": now,
        "age_account": _age(hrow.get("last_check_at")),
        "age_proxy": _age(mrow.get("auth_guard_last_ok_at") or mrow.get("auth_guard_checked_at")),
        "age_ss": _age(ss.get("updated_at")),
        "age_exit": _age(ss.get("last_exit_at")),
    }


def _hnv2_result(
    family: str, *, confidence: str, alertable: bool, deferred_to: str = "",
    evidence_source: str = "", evidence_field: str = "", evidence_value: str = "",
    detail: str = "", evidence_key: str = "",
) -> dict:
    return {
        "family": family, "confidence": confidence, "alertable": bool(alertable),
        "deferred_to": deferred_to, "evidence_source": evidence_source,
        "evidence_field": evidence_field, "evidence_value": str(evidence_value or "")[:200],
        "detail": str(detail or "")[:200], "evidence_key": evidence_key,
    }


def _hnv2_classify_root_cause(ev: dict) -> dict:
    """Single authoritative root-cause classifier. Deterministic priority,
    first match wins -- see the approved plan section C for the full
    per-rule rationale table. `ev` is the dict built by
    _hnv2_collect_evidence. Returns a dict with keys: family, confidence
    ('certain'|'probable'|'none'), alertable (bool), deferred_to (non-empty
    only for families TP_HG owns and HNV2 must never independently open/
    resolve), evidence_source/evidence_field/evidence_value, detail,
    evidence_key (the canonical signature component -- see
    _hnv2_signature). Pure function: no I/O, never raises (any lookup
    failure inside falls through toward 'unknown', never upward as an
    exception -- a classifier that can crash the aggregator tick is worse
    than one that occasionally says 'unknown')."""
    try:
        mrow = ev.get("mrow") or {}
        hrow = ev.get("hrow") or {}
        ss = ev.get("ss") or {}
        proc = str(ev.get("proc") or "probe_error")
        flap_new = int(ev.get("flap_new") or 0)
        last_verify = str(ev.get("last_verify") or "none")
        age_account = ev.get("age_account")
        age_proxy = ev.get("age_proxy")
        age_ss = ev.get("age_ss")
        age_exit = ev.get("age_exit")

        account_status = str(hrow.get("health_status") or "").strip().lower()
        account_cls = str(hrow.get("error_class") or "").strip()
        account_cls_l = account_cls.lower()
        account_text = str(hrow.get("error_text") or "").strip()
        account_text_l = account_text.lower()
        proxy_state = str(mrow.get("auth_guard_state") or "").strip().lower()
        proxy_err = str(mrow.get("auth_guard_error") or mrow.get("auth_guard_last_fail_reason") or "").strip()
        proxy_err_l = proxy_err.lower()
        ss_phase = str(ss.get("phase") or "").strip().lower()
        ss_reason_class = str(ss.get("reason_class") or "").strip().lower()
        ss_error_l = str(ss.get("error") or "").strip().lower()
        last_exit_rc = str(ss.get("last_exit_reason_class") or "").strip().lower()
        last_exit_err = str(ss.get("last_exit_error") or "")
        last_exit_err_l = last_exit_err.lower()

        exit_evidence_fresh = age_exit is not None and age_exit <= HNV2_EXIT_EVIDENCE_MAX_AGE_SEC
        exit_rc_is_session = last_exit_rc in ("session_unauthorized", "auth_session", "telegram_identity_mismatch")
        # HNV2 F-1 fix: FloodWait can arrive labeled reason_class='auth_session'
        # by the pre-existing (untouched) _m212a_classify_exit_reason (D12) --
        # the ONLY reliable signal that a given exit was actually a FloodWait
        # is the associated error TEXT, never the reason_class string itself
        # (always one of a small fixed set of labels, never "floodwait").
        # Real Telethon FloodWaitError.__str__ is "A wait of {seconds} seconds
        # is required (caused by ...)" -- it does NOT contain the literal word
        # "floodwait" -- so a bare "floodwait" substring check misses the real
        # runtime text entirely. Reuse the SAME three-token check TP_HG itself
        # already relies on for this exact problem (main.py _tp_hg_classify_
        # exception-style helpers, ~20695/21984: "floodwait"/"flood wait"/
        # "wait of"), applied to every text field that can carry that error,
        # current tick AND sticky (D1), since ss.error/reason_class reset to
        # '' on every non-'exited' write while last_exit_error/
        # last_exit_reason_class stay sticky.
        any_floodwait_text = (
            any(m in last_exit_err_l for m in _HNV2_FLOODWAIT_TEXT_MARKS)
            or any(m in ss_error_l for m in _HNV2_FLOODWAIT_TEXT_MARKS)
        )

        # --- Rule 1: session_unauthorized ---
        if exit_rc_is_session and not any_floodwait_text and exit_evidence_fresh:
            return _hnv2_result(
                HNV2_FAMILY_SESSION_UNAUTHORIZED, confidence="certain", alertable=True,
                evidence_source="start_status", evidence_field="last_exit_reason_class",
                evidence_value=last_exit_rc, detail=last_exit_rc, evidence_key=last_exit_rc or "session_unauthorized",
            )
        if ss_reason_class in ("session_unauthorized", "auth_session", "telegram_identity_mismatch") and not any_floodwait_text:
            return _hnv2_result(
                HNV2_FAMILY_SESSION_UNAUTHORIZED, confidence="certain", alertable=True,
                evidence_source="start_status", evidence_field="reason_class",
                evidence_value=ss_reason_class, detail=ss_reason_class, evidence_key=ss_reason_class,
            )
        if account_cls and any(m in account_cls_l for m in _HNV2_SESSION_MARKS):
            return _hnv2_result(
                HNV2_FAMILY_SESSION_UNAUTHORIZED, confidence="certain", alertable=True,
                evidence_source="manager_telegram_health", evidence_field="error_class",
                evidence_value=account_cls, detail=account_cls, evidence_key=account_cls_l,
            )

        # --- Rule 2: account_blocked (never age-gated -- a sticky negative
        # does not expire) ---
        if account_status == "blocked":
            has_hard_marker = any(m in account_cls_l or m in account_text_l for m in _HNV2_ACCOUNT_BLOCKED_MARKS)
            return _hnv2_result(
                HNV2_FAMILY_ACCOUNT_BLOCKED, confidence=("certain" if has_hard_marker else "probable"), alertable=True,
                evidence_source="manager_telegram_health", evidence_field="health_status",
                evidence_value="blocked", detail=(account_cls or account_text), evidence_key=(account_cls_l or "blocked"),
            )

        # --- Rule 3/4: telegram_limited_peerflood / floodwait -- classified
        # for priority + button purposes, but NEVER opened/resolved by
        # HNV2 (TP_HG owns them entirely, see _tp_hg_notify_if_needed). ---
        if account_status == "limited":
            fam = _tp_hg_restriction_family(status=account_status, error_class=account_cls)
            if fam == _TP_HG_FAMILY_PEERFLOOD:
                return _hnv2_result(
                    HNV2_FAMILY_PEERFLOOD, confidence="certain", alertable=False, deferred_to="tg_health",
                    evidence_source="manager_telegram_health", evidence_field="health_status",
                    evidence_value="limited", detail="peerflood", evidence_key="peerflood",
                )
            if fam == _TP_HG_FAMILY_FLOODWAIT:
                return _hnv2_result(
                    HNV2_FAMILY_FLOODWAIT, confidence="certain", alertable=False, deferred_to="tg_health",
                    evidence_source="manager_telegram_health", evidence_field="health_status",
                    evidence_value="limited", detail="floodwait", evidence_key="floodwait",
                )
        if any_floodwait_text:
            fw_value = last_exit_err if "floodwait" in last_exit_err_l else str(ss.get("error") or "")
            fw_field = "last_exit_error" if "floodwait" in last_exit_err_l else "error"
            return _hnv2_result(
                HNV2_FAMILY_FLOODWAIT, confidence="certain", alertable=False, deferred_to="tg_health",
                evidence_source="start_status", evidence_field=fw_field,
                evidence_value=fw_value, detail="floodwait", evidence_key="floodwait",
            )

        # --- Rule 5: proxy_auth_failed ---
        if proxy_state == "blocked" and any(m in proxy_err_l for m in _HNV2_PROXY_AUTH_MARKS):
            return _hnv2_result(
                HNV2_FAMILY_PROXY_AUTH_FAILED, confidence="certain", alertable=True,
                evidence_source="managers", evidence_field="auth_guard_error",
                evidence_value=proxy_err, detail=proxy_err, evidence_key="auth",
            )

        # --- Rule 6: proxy_unavailable ---
        if proxy_state == "blocked":
            return _hnv2_result(
                HNV2_FAMILY_PROXY_UNAVAILABLE, confidence="certain", alertable=True,
                evidence_source="managers", evidence_field="auth_guard_state",
                evidence_value="blocked", detail=proxy_err, evidence_key="unreachable",
            )
        if last_exit_rc == "proxy_timeout":
            return _hnv2_result(
                HNV2_FAMILY_PROXY_UNAVAILABLE, confidence="certain", alertable=True,
                evidence_source="start_status", evidence_field="last_exit_reason_class",
                evidence_value=last_exit_rc, detail=last_exit_err, evidence_key="unreachable",
            )
        if last_exit_rc == "process_exited" and proxy_state in ("blocked", "degraded"):
            # HNV2 D11 fix: the runtime-start proxy-guard gate (main.py,
            # the CONTROLLER_MODE/MANAGER_ARG_USED wrapper) returns
            # normally on a failed guard, so the entrypoint writes
            # reason_class='process_exited' -- pre-HNV2 this was classified
            # RECOVERABLE by _manager_recovery_classify and respawned in a
            # loop, which is exactly what manufactured recovery_flap for a
            # permanently dead proxy. HNV2 checks the proxy state directly
            # instead of trusting the generic exit reason.
            return _hnv2_result(
                HNV2_FAMILY_PROXY_UNAVAILABLE, confidence="certain", alertable=True,
                evidence_source="start_status+managers", evidence_field="last_exit_reason_class+auth_guard_state",
                evidence_value=f"process_exited+{proxy_state}", detail="proxy_guard_start_block", evidence_key="unreachable",
            )
        if proxy_state == "degraded" and age_proxy is not None and age_proxy <= HNV2_PROXY_MAX_AGE_SEC:
            return _hnv2_result(
                HNV2_FAMILY_PROXY_UNAVAILABLE, confidence="probable", alertable=True,
                evidence_source="managers", evidence_field="auth_guard_state",
                evidence_value="degraded", detail=proxy_err, evidence_key="unreachable",
            )

        # --- Rule 7: sqlite_lock (malformed/corrupt deliberately excluded --
        # falls through to worker_crash with detail='db_malformed') ---
        # N-5 correction (post-independent-review): ss.last_exit_error is
        # STICKY (D1) -- without a freshness gate here, a worker that fully
        # recovered from a transient lock and never exits again would keep
        # being RE-diagnosed as sqlite_lock forever (this rule would win
        # every single tick, starving PASS 2 of the chance to even evaluate
        # recovery for the OLDER incident, since PASS 2 skips any signature
        # PASS 1 already re-confirmed this tick). Gated by the SAME
        # exit_evidence_fresh window rule 1 already uses for exactly this
        # class of problem -- reused, not reinvented. hrow.error_text is
        # NOT gated the same way: it is TP_HG's own periodically-refreshed
        # field (~20min self-check cadence, main.py TP_HG_CHECK_INTERVAL_SEC),
        # not subject to D1's worker-exit stickiness.
        lock_text_ss = last_exit_err_l if exit_evidence_fresh else ""
        lock_text = f"{lock_text_ss} {account_text_l}"
        is_malformed = any(m in lock_text for m in _HNV2_SQLITE_MALFORMED_MARKS)
        if not is_malformed and any(m in lock_text for m in _HNV2_SQLITE_LOCK_MARKS):
            return _hnv2_result(
                HNV2_FAMILY_SQLITE_LOCK, confidence="certain", alertable=True,
                evidence_source="start_status", evidence_field="last_exit_error",
                evidence_value=last_exit_err, detail=last_exit_err, evidence_key="locked",
            )

        # --- Rule 8: network_timeout ---
        if last_exit_rc == "connection_error" and proxy_state in ("ok", "direct"):
            return _hnv2_result(
                HNV2_FAMILY_NETWORK_TIMEOUT, confidence="certain", alertable=True,
                evidence_source="start_status", evidence_field="last_exit_reason_class",
                evidence_value=last_exit_rc, detail=last_exit_err, evidence_key="timeout",
            )
        if proxy_state in ("ok", "direct") and any(m in last_exit_err_l for m in _HNV2_NETWORK_TIMEOUT_MARKS):
            return _hnv2_result(
                HNV2_FAMILY_NETWORK_TIMEOUT, confidence="certain", alertable=True,
                evidence_source="start_status", evidence_field="last_exit_error",
                evidence_value=last_exit_err, detail=last_exit_err, evidence_key="timeout",
            )

        # --- Rule 9: worker_stuck_starting (D5) -- phase='running' is
        # NEVER age-gated (main.py's own documented invariant for
        # _manager_runtime_ready_once). ---
        if ss_phase == "starting" and age_ss is not None and age_ss >= HNV2_STUCK_STARTING_SEC and proc == "running":
            return _hnv2_result(
                HNV2_FAMILY_WORKER_STUCK_STARTING, confidence="certain", alertable=True,
                evidence_source="start_status", evidence_field="phase",
                evidence_value="starting", detail=f"stuck_starting_{int(age_ss)}s", evidence_key="starting",
            )
        if ss_phase == "connected" and age_ss is not None and age_ss >= HNV2_CONNECTED_MAX_AGE_SEC and proc == "running":
            return _hnv2_result(
                HNV2_FAMILY_WORKER_STUCK_STARTING, confidence="certain", alertable=True,
                evidence_source="start_status", evidence_field="phase",
                evidence_value="connected", detail=f"stuck_connected_{int(age_ss)}s", evidence_key="connected",
            )

        # --- Rule 10: worker_crash ---
        if proc == "absent" and ss_phase == "exited" and last_exit_rc in ("process_exited", "unknown", ""):
            detail = "db_malformed" if is_malformed else (last_exit_rc or "process_exited")
            return _hnv2_result(
                HNV2_FAMILY_WORKER_CRASH, confidence="certain", alertable=True,
                evidence_source="start_status", evidence_field="last_exit_reason_class",
                evidence_value=last_exit_rc, detail=detail, evidence_key=detail,
            )
        if proc == "absent" and ss_phase in ("running", "connected", "starting"):
            return _hnv2_result(
                HNV2_FAMILY_WORKER_CRASH, confidence="certain", alertable=True,
                evidence_source="start_status+proc", evidence_field="phase",
                evidence_value=ss_phase, detail="no_exit_record", evidence_key="no_exit_record",
            )

        # --- Rule 11: recovery_flap -- deliberately the lowest-priority
        # concrete family. Reaching here means no specific cause was
        # identifiable from any authoritative evidence source above. ---
        if flap_new >= HEALTH_AGG_RECOVERY_FLAP_THRESHOLD and last_verify != "ok":
            return _hnv2_result(
                HNV2_FAMILY_RECOVERY_FLAP, confidence="certain", alertable=True,
                evidence_source="manager_auto_recovery.log", evidence_field="flap_new",
                evidence_value=str(flap_new), detail=f"flap_new={flap_new}_last_verify={last_verify}", evidence_key="flap",
            )

        # --- Rule 12: health_missing_stale (D4) ---
        if not hrow and not proxy_state:
            return _hnv2_result(
                HNV2_FAMILY_HEALTH_MISSING_STALE, confidence="certain", alertable=True,
                evidence_source="manager_telegram_health+managers", evidence_field="(absent)",
                evidence_value="", detail="no_health_data", evidence_key="both",
            )
        account_stale = account_status == "ok" and age_account is not None and age_account > HNV2_ACCOUNT_MAX_AGE_SEC
        proxy_stale = proxy_state in ("ok", "direct") and age_proxy is not None and age_proxy > HNV2_PROXY_MAX_AGE_SEC
        if account_stale and proxy_stale:
            return _hnv2_result(
                HNV2_FAMILY_HEALTH_MISSING_STALE, confidence="certain", alertable=True,
                evidence_source="manager_telegram_health+managers", evidence_field="last_check_at+auth_guard_last_ok_at",
                evidence_value=f"{age_account:.0f}s+{age_proxy:.0f}s", detail="both_stale", evidence_key="both",
            )
        if account_stale:
            return _hnv2_result(
                HNV2_FAMILY_HEALTH_MISSING_STALE, confidence="certain", alertable=True,
                evidence_source="manager_telegram_health", evidence_field="last_check_at",
                evidence_value=f"{age_account:.0f}s", detail="account_stale", evidence_key="account",
            )
        if proxy_stale:
            return _hnv2_result(
                HNV2_FAMILY_HEALTH_MISSING_STALE, confidence="certain", alertable=True,
                evidence_source="managers", evidence_field="auth_guard_last_ok_at",
                evidence_value=f"{age_proxy:.0f}s", detail="proxy_stale", evidence_key="proxy",
            )

        # --- Rule 13: ok (not an incident) ---
        proxy_ok_fresh = proxy_state in ("ok", "direct") and age_proxy is not None and age_proxy <= HNV2_PROXY_MAX_AGE_SEC
        account_ok_fresh = account_status == "ok" and age_account is not None and age_account <= HNV2_ACCOUNT_MAX_AGE_SEC
        account_ok_via_running_proc = (not hrow) and proc == "running" and ss_phase == "running"
        if proxy_ok_fresh and (account_ok_fresh or account_ok_via_running_proc) and flap_new == 0:
            return _hnv2_result(HNV2_FAMILY_OK, confidence="certain", alertable=False, evidence_key="ok")

        # --- Rule 14: unknown -- safe fallback. confidence is NEVER raised
        # above 'none' here; a probe_error can only ever reach this rule
        # (never worker_crash -- rule 10 requires proc=='absent', a
        # probe_error is neither 'absent' nor 'running'). The "wait for
        # HNV2_UNKNOWN_CONFIRM_SEC / HNV2_UNKNOWN_MIN_OBSERVATIONS before
        # actually notifying" requirement is enforced by the state machine's
        # generic OBSERVED-phase confirm gate (CONFIRM_SEC/CONFIRM_TICKS
        # per family, Phase 6), not here -- a single per-tick classifier
        # call has no history to judge "continuous" against; alertable=True
        # here only marks this family as ELIGIBLE to eventually open an
        # incident once the state machine's own confirmation window (the
        # same mechanism every other family uses) has elapsed.
        return _hnv2_result(
            HNV2_FAMILY_UNKNOWN, confidence="none", alertable=True,
            evidence_source="none", evidence_field="", evidence_value="",
            detail=f"proc={proc} phase={ss_phase or '_'} account={account_status or '_'} proxy={proxy_state or '_'}",
            evidence_key="unknown",
        )
    except Exception:
        # A classifier that can crash the aggregator tick is strictly worse
        # than one that occasionally reports UNKNOWN. Never raises upward.
        return _hnv2_result(
            HNV2_FAMILY_UNKNOWN, confidence="none", alertable=False,
            detail="classifier_exception", evidence_key="unknown",
        )


def _hnv2_normalize_sig_component(raw: Any) -> str:
    """Coarse, stable normalization for a signature component: reuses
    _tp_hg_stable_error_text (main.py) to strip volatile digits/"(caused by
    ...)"/collapse whitespace, then lowercases and replaces ':' so the
    result can never collide with the signature's own ':'-delimited
    structure. Capped at 48 chars so the full 'hv2:<family>:<key>'
    signature stays well under SQLite TEXT PK practicality and the 64-byte
    callback_data budget with room for the 'hv2:' prefix and separators."""
    t = _tp_hg_stable_error_text(raw)
    t = t.lower().replace(":", "_")
    t = re.sub(r"\s+", "_", t).strip("_")
    return t[:48]


def _hnv2_signature(family: str, evidence_key: str) -> str:
    """Canonical incident identity: 'hv2:<family>:<evidence_key>'. Stable
    across PID/retry-number/timestamp/cooldown-seconds/variable exception
    text -- see the approved plan section K.3 for the full stability
    proof obligations. The 'hv2:' namespace never collides with the
    existing 'limited:*'/'blocked:*'/'recovery_flap'/'no_health_data'/
    'auth_action_required'/'proxy_terminal_review' signature namespaces
    already sharing storage.health_incidents, and is deliberately excluded
    from health_incident_resolve_all_for_manager's 'limited:%'/'blocked:%'
    sweep filter (storage.py) -- a Telegram-health recovery can never close
    a V2 incident."""
    fam = _hnv2_normalize_sig_component(family)
    key = _hnv2_normalize_sig_component(evidence_key)
    return f"hv2:{fam}:{key}"[:80]


# --- HNV2 Phase 5: flap watermark, re-arm, spawn verification ---

import json as _hnv2_json  # noqa: E402


def _hnv2_count_new_recovery_events(manager_key: str, watermark: str) -> Tuple[int, str]:
    """Counts genuinely NEW auto-recovery spawn events for manager_key since
    `watermark` (a JSON string '{"ts": "<iso>", "n": <count-of-records-at-
    that-exact-ts-already-consumed>}'), bounded by the SAME
    HEALTH_AGG_RECOVERY_WINDOW_MIN rolling window _health_agg_tail_recovery_
    log (main.py) already uses -- same 256 KB tail-read technique,
    line-for-line. Returns (new_count, current_tip_watermark). The second
    element is a snapshot of the log's current tip for this manager (max
    time_utc seen among ALL matching records in this read, and how many
    share it) -- unfiltered by the OLD watermark or the rolling window, so
    it always reflects "everything currently visible in the log" for this
    manager. The CALLER persists this ONLY at the RECOVERY_PENDING->
    RESOLVED transition (approved plan section F) -- never on every tick,
    or a still-open flap would keep resetting its own baseline and could
    never be proven to have genuinely new post-resolve events. Never
    raises; returns (0, watermark) on any error, preserving rather than
    losing the existing watermark."""
    try:
        wm_ts, wm_n = "", 0
        if watermark:
            try:
                wm = _hnv2_json.loads(watermark)
                wm_ts = str(wm.get("ts") or "")
                wm_n = int(wm.get("n") or 0)
            except Exception:
                wm_ts, wm_n = "", 0

        log_path = BASE_DIR / "runtime" / "manager_auto_recovery.log"
        if not log_path.is_file():
            return 0, (watermark or "")

        now_utc = datetime.now(timezone.utc)
        cutoff_iso = (now_utc - timedelta(minutes=HEALTH_AGG_RECOVERY_WINDOW_MIN)).replace(microsecond=0).isoformat()
        max_bytes = 256 * 1024
        size = log_path.stat().st_size
        offset = max(0, size - max_bytes)

        new_count = 0
        seen_at_wm_ts = 0
        max_ts_seen = ""
        count_at_max_ts = 0

        with open(log_path, "r", encoding="utf-8", errors="replace") as _f:
            if offset:
                _f.seek(offset)
                _f.readline()   # skip partial first line after seek
            for line in _f:
                line = line.strip()
                if not line:
                    continue
                try:
                    rec = _hnv2_json.loads(line)
                except Exception:
                    continue
                if str(rec.get("manager_key") or "") != str(manager_key or ""):
                    continue
                if str(rec.get("action") or "") != "spawn":
                    continue
                if str(rec.get("result") or "") != "ok":
                    continue
                ts = str(rec.get("time_utc") or "")
                if not ts:
                    continue

                # Current-tip tracking (unfiltered) -- for the caller's
                # possible new watermark.
                if ts > max_ts_seen:
                    max_ts_seen = ts
                    count_at_max_ts = 1
                elif ts == max_ts_seen:
                    count_at_max_ts += 1

                # New-since-watermark tracking, additionally bounded by the
                # rolling window.
                if ts < cutoff_iso:
                    continue
                if wm_ts and ts < wm_ts:
                    continue
                if wm_ts and ts == wm_ts:
                    seen_at_wm_ts += 1
                    if seen_at_wm_ts <= wm_n:
                        continue
                new_count += 1

        new_watermark = _hnv2_json.dumps({"ts": max_ts_seen, "n": count_at_max_ts}) if max_ts_seen else (watermark or "")
        return new_count, new_watermark
    except Exception:
        return 0, (watermark or "")


async def _hnv2_verify_spawn(manager_key: str, spawn_ts: str) -> None:
    """Waits HNV2_SPAWN_VERIFY_DELAY_SEC after a recovery-supervisor spawn
    (deliberately < MANAGER_RECOVERY_INTERVAL_SEC, so this verification
    lands before the supervisor's next tick), then appends a SECOND JSONL
    record (action='spawn_verify') proving -- or disproving -- that the
    spawn actually produced a healthy, connected manager. Never touches the
    existing action='spawn' record's own 'result' field -- every existing
    reader of manager_auto_recovery.log (preflight_check.py,
    soft_watchdog_pinger.py, _health_agg_tail_recovery_log) keeps parsing
    that field unchanged (D2 fix, approved plan section I.3).

    Evidence required for result='ok', ALL three, in order:
      1. _hnv2_process_state(key) == 'running'
      2. start_status.phase in {'connected','running'} AND
         start_status.updated_at > spawn_ts -- proves THIS spawn, not a
         stale file left by a previous run.
      3. _manager_runtime_ready_once(key, heartbeat_advisory=True) is ok --
         the project's existing 10-signal readiness contract. Does NOT wait
         on the 1200s manager_telegram_health heartbeat cadence; its
         connected/authorized/get_me signals come from a live runtime_ping
         round-trip over the already-running manager's own command queue.

    Never raises -- an exception here must never crash the recovery
    supervisor loop that scheduled this as a fire-and-forget background
    task."""
    try:
        await asyncio.sleep(max(0, HNV2_SPAWN_VERIFY_DELAY_SEC))
        key = registry_normalize_manager_key(manager_key or "")
        if not key:
            return

        proc = await _hnv2_process_state(key)
        ss = _manager_recovery_read_start_status(key)
        phase = str(ss.get("phase") or "").strip().lower()
        updated_at = str(ss.get("updated_at") or "")

        pid = None
        if proc == "running":
            if phase in ("connected", "running") and updated_at and spawn_ts and updated_at > spawn_ts:
                try:
                    ready = await _manager_runtime_ready_once(key, heartbeat_advisory=True, ping_timeout_sec=15)
                except Exception:
                    ready = {"ok": False, "error_class": "verify_exception"}
                if ready.get("ok"):
                    result = "ok"
                    pid = ss.get("pid")
                else:
                    result = f"failed:{ready.get('error_class') or 'not_ready'}"
            else:
                result = "failed:stale_or_wrong_phase"
        elif proc == "probe_error":
            result = "failed:probe_error"
        else:
            result = "failed:process_absent"

        _manager_recovery_log({
            "time_utc": datetime.now(timezone.utc).replace(microsecond=0).isoformat(),
            "manager_key": key, "action": "spawn_verify", "result": result,
            "new_pid": pid, "verified_for_spawn_at": spawn_ts,
        })
    except Exception:
        pass


def _hnv2_recovery_log_len() -> int:
    """Current byte size of manager_auto_recovery.log, 0 if absent. Never
    raises."""
    try:
        log_path = BASE_DIR / "runtime" / "manager_auto_recovery.log"
        return log_path.stat().st_size if log_path.is_file() else 0
    except Exception:
        return 0


def _hnv2_spawns_appended_since(before_size: int) -> list:
    """Reads ONLY the bytes appended to manager_auto_recovery.log since
    `before_size`, returns [(manager_key, time_utc), ...] for every
    action=='spawn' record found there -- used to schedule exactly one
    _hnv2_verify_spawn per genuinely new spawn this tick, without
    re-tailing the whole file. Never raises; returns [] on any error."""
    out: list = []
    try:
        log_path = BASE_DIR / "runtime" / "manager_auto_recovery.log"
        if not log_path.is_file():
            return out
        with open(log_path, "r", encoding="utf-8", errors="replace") as _f:
            _f.seek(max(0, int(before_size or 0)))
            for line in _f:
                line = line.strip()
                if not line:
                    continue
                try:
                    rec = _hnv2_json.loads(line)
                except Exception:
                    continue
                if str(rec.get("action") or "") != "spawn":
                    continue
                mk = str(rec.get("manager_key") or "")
                ts = str(rec.get("time_utc") or "")
                if mk and ts:
                    out.append((mk, ts))
    except Exception:
        pass
    return out


_HNV2_PREV_RECOVERY_ONCE = globals().get("_manager_recovery_once")


async def _manager_recovery_once() -> None:   # type: ignore[override]
    """HNV2 D2 wrapper: delegates to the ORIGINAL _manager_recovery_once
    (main.py, unchanged) first -- every existing behavior (cooldowns,
    attempt caps, global throttle, the 'spawn'/result='ok' JSONL record
    itself) is preserved byte-for-byte -- then schedules exactly one
    _hnv2_verify_spawn per spawn record the original call just appended.
    Resolvable by global-name lookup (Python's normal late-binding), so
    _manager_recovery_loop's existing `await _manager_recovery_once()`
    call picks up this definition automatically -- no change to the loop
    itself. Two defs of this name is fine: unlike _health_incident_handle/
    _manager_recovery_classify/etc., no selftest locks its def count to 1
    (verified against tools/health_incident_selftest.py's own static
    check, which covers _manager_recovery_classify/_manager_recovery_
    open_auth_incident/_manager_recovery_resolve_auth_incident but
    deliberately not this name)."""
    before = _hnv2_recovery_log_len()
    if callable(_HNV2_PREV_RECOVERY_ONCE):
        await _HNV2_PREV_RECOVERY_ONCE()
    if not HNV2_ENABLED:
        return
    for key, ts in _hnv2_spawns_appended_since(before):
        try:
            asyncio.create_task(_hnv2_verify_spawn(key, ts))
        except Exception:
            pass


# --- HNV2 Phase 6: state machine, quota, recovery ownership, bootstrap ---

# CONFIRM_SEC/CONFIRM_TICKS per family (approved plan section D). Aggregator
# tick cadence is HEALTH_AGG_INTERVAL_SEC (60s by default).
_HNV2_CONFIRM_TABLE = {
    HNV2_FAMILY_SESSION_UNAUTHORIZED: (0, 1),
    HNV2_FAMILY_ACCOUNT_BLOCKED: (0, 1),
    HNV2_FAMILY_PROXY_AUTH_FAILED: (120, 2),
    HNV2_FAMILY_WORKER_CRASH: (180, 3),
    HNV2_FAMILY_PROXY_UNAVAILABLE: (300, 4),
    HNV2_FAMILY_NETWORK_TIMEOUT: (300, 4),
    HNV2_FAMILY_SQLITE_LOCK: (300, 4),
    HNV2_FAMILY_WORKER_STUCK_STARTING: (0, 1),
    HNV2_FAMILY_RECOVERY_FLAP: (0, 1),
    HNV2_FAMILY_HEALTH_MISSING_STALE: (900, 10),
    HNV2_FAMILY_UNKNOWN: (900, 5),
}

# Recommended-action text per family (approved plan section I.2, owner
# spec 2026-08-07). Every non-OK family has a non-empty entry; families
# with no safe automatic action (account_blocked, sqlite_lock) name the
# manual route explicitly rather than implying a button that doesn't
# exist. telegram_limited_peerflood/floodwait are deliberately absent --
# HNV2 never notifies for them (TP_HG owns that channel entirely).
_HNV2_RECOMMENDED_ACTION = {
    HNV2_FAMILY_SESSION_UNAUTHORIZED: "Перелогиниться: Перезайти / Войти по QR / Вход на устройстве.",
    HNV2_FAMILY_PROXY_AUTH_FAILED: "Исправить данные прокси и проверить.",
    HNV2_FAMILY_WORKER_CRASH: "Перезапустить менеджера.",
    HNV2_FAMILY_HEALTH_MISSING_STALE: "Провести health-check и проверить п��окси.",
    HNV2_FAMILY_ACCOUNT_BLOCKED: (
        "Не перезапускать и не перелогинивать. Проверить подтверждённую "
        "блокировку и при необходимости заменить аккаунт через карточку."
    ),
    HNV2_FAMILY_SQLITE_LOCK: (
        "Открыть диагностику и определить источник блокировки. "
        "Автоматического рестарта нет."
    ),
    HNV2_FAMILY_UNKNOWN: "Провести безопасную диагностику.",
    HNV2_FAMILY_PROXY_UNAVAILABLE: "Проверить прокси; при живом прокси — перезапустить.",
    HNV2_FAMILY_WORKER_STUCK_STARTING: "Перезапустить; проверить прокси.",
    HNV2_FAMILY_NETWORK_TIMEOUT: "Проверить прокси/сеть, затем перезапустить.",
    HNV2_FAMILY_RECOVERY_FLAP: (
        "Не перезапускать — перезапуск и есть то, что флапает. "
        "Глубокая проверка + прокси."
    ),
}


def _hnv2_stable_sec_for_family(family: str) -> int:
    """Stability window before RECOVERY_PENDING -> RESOLVED. sqlite_lock
    gets a longer window (approved plan I.2.2) because its only
    affirmative evidence -- an advanced last_check_at with no fresh lock
    marker -- is narrower than every other family's."""
    if family == HNV2_FAMILY_SQLITE_LOCK:
        return HNV2_STABLE_SEC_SQLITE_LOCK
    return HNV2_STABLE_SEC


_hnv2_last_ready_probe: Dict[str, Any] = {}


async def _hnv2_rate_limited_ready_probe(key: str) -> bool:
    """Rate-limited (HNV2_READY_PROBE_MIN_INTERVAL_SEC per manager) call to
    _manager_runtime_ready_once(heartbeat_advisory=True) -- the readiness
    round-trip costs up to ~15s over the manager's own command queue, so
    this is deliberately NOT called on the general per-manager-per-tick
    path; only from the recovery-ownership evaluation below, and even
    there at most once per manager per HNV2_READY_PROBE_MIN_INTERVAL_SEC.
    Caches the LAST outcome (not just the call), so a manager re-evaluated
    every 60s tick reuses the same verdict until the window elapses.
    Fails toward 'not ready' (False) on any error or when never yet
    probed -- never toward a false recovery."""
    try:
        now_mono = time.monotonic()
        cached = _hnv2_last_ready_probe.get(key)
        if cached is not None and (now_mono - cached[0]) < HNV2_READY_PROBE_MIN_INTERVAL_SEC:
            return bool(cached[1])
        try:
            r = await _manager_runtime_ready_once(key, heartbeat_advisory=True, ping_timeout_sec=15)
            ok = bool(r.get("ok"))
        except Exception:
            ok = False
        _hnv2_last_ready_probe[key] = (now_mono, ok)
        return ok
    except Exception:
        return False


def _hnv2_last_spawn_verify(manager_key: str) -> str:
    """Returns 'ok' | 'failed' | 'none' -- the outcome of the NEWEST
    action=='spawn_verify' record for manager_key within the 256 KB tail
    of manager_auto_recovery.log. 'none' means no spawn_verify record was
    found at all. Never raises."""
    try:
        log_path = BASE_DIR / "runtime" / "manager_auto_recovery.log"
        if not log_path.is_file():
            return "none"
        max_bytes = 256 * 1024
        size = log_path.stat().st_size
        offset = max(0, size - max_bytes)
        newest_ts = ""
        newest_result = "none"
        with open(log_path, "r", encoding="utf-8", errors="replace") as _f:
            if offset:
                _f.seek(offset)
                _f.readline()
            for line in _f:
                line = line.strip()
                if not line:
                    continue
                try:
                    rec = _hnv2_json.loads(line)
                except Exception:
                    continue
                if str(rec.get("manager_key") or "") != str(manager_key or ""):
                    continue
                if str(rec.get("action") or "") != "spawn_verify":
                    continue
                ts = str(rec.get("time_utc") or "")
                if ts >= newest_ts:
                    newest_ts = ts
                    newest_result = "ok" if str(rec.get("result") or "") == "ok" else "failed"
        return newest_result
    except Exception:
        return "none"


async def _hnv2_family_recovery_evidence(family: str, evidence_key: str, ev: dict, opened_at: str, key: str, *, current_family: str = "") -> bool:
    """RECOVERY OWNERSHIP MATRIX (approved plan section I.2.2). For each
    family, the ONE specific authoritative positive-recovery evidence
    required -- always compared against `opened_at` (the incident's OWN
    open timestamp, never "now"). Generic runtime readiness NEVER resolves
    a family by itself; it is only ever a SECONDARY confirmation layered
    on top of the family's own authoritative signal, exactly where this
    matrix says so, and is entirely ABSENT for families where the matrix
    forbids it (sqlite_lock) or doesn't require it (network_timeout,
    health_missing_stale, recovery_flap). telegram_limited_peerflood/
    floodwait/ok/unknown are never passed here -- callers handle those
    separately (TP_HG owns the first two; 'unknown' recovers only via the
    classifier's OWN current-tick result, not via this function; 'ok' is
    not an incident family at all).

    `current_family` (HNV2 N-4 correction, post-independent-review): the
    SAME tick's fresh _hnv2_classify_root_cause(ev) result for this
    manager -- needed specifically by worker_stuck_starting (plan I.2.2:
    "...и только при условии, что ни одна более приоритетная непочиняемая
    причина сейчас не активна"). Without this, a worker that reaches
    phase='running' at the exact moment a NEW higher-priority cause begins
    (e.g. proxy just went blocked) could spuriously resolve the OLDER
    worker_stuck_starting incident while the account is actively failing
    for a different reason PASS 1 already opened/holds open separately."""
    try:
        mrow = ev.get("mrow") or {}
        hrow = ev.get("hrow") or {}
        ss = ev.get("ss") or {}
        proc = str(ev.get("proc") or "probe_error")
        opened_at = str(opened_at or "")

        def _newer(ts_raw: Any) -> bool:
            # N-6 correction (post-independent-review): raw string
            # comparison is unsafe across this codebase's two ISO-8601
            # writer conventions -- storage.py/_tp_hg_now_iso write naive
            # timestamps ("...T16:36:03"), while _m212a_write_start_status
            # writes tz-aware ones ("...T16:36:03+00:00"). For the exact
            # same real-world instant, the tz-aware string is lexically
            # LONGER (the naive one is a strict prefix of it), so plain
            # string '>' would report the tz-aware one as "newer" even
            # though they are the SAME moment -- a same-second false
            # positive. Parsed via the same _tp_hg_parse_iso normalization
            # (tz-aware -> naive UTC) already used everywhere else in this
            # file for exactly this reason. Fails CLOSED (never "newer") on
            # anything unparseable -- this does not loosen the `> opened_at`
            # requirement, only makes it format-safe.
            ts = str(ts_raw or "")
            if not ts or not opened_at:
                return False
            ts_dt = _tp_hg_parse_iso(ts)
            opened_dt = _tp_hg_parse_iso(opened_at)
            if ts_dt is None or opened_dt is None:
                return False
            return ts_dt > opened_dt

        if family == HNV2_FAMILY_SESSION_UNAUTHORIZED:
            last_connected_at = str(ss.get("last_connected_at") or "")
            last_exit_rc = str(ss.get("last_exit_reason_class") or "")
            last_exit_at = str(ss.get("last_exit_at") or "")
            # last_exit_reason_class must be empty, OR strictly older than
            # the fresh successful connect -- never a stale auth failure
            # masquerading as recovered just because the worker connected
            # once since.
            evidence_ok = (not last_exit_rc) or (last_exit_at and last_connected_at and last_exit_at < last_connected_at)
            cheap = (
                _newer(last_connected_at)
                and str(ss.get("phase") or "").lower() in ("connected", "running")
                and evidence_ok
            )
            if not cheap:
                return False
            return await _hnv2_rate_limited_ready_probe(key)

        if family == HNV2_FAMILY_ACCOUNT_BLOCKED:
            # Authoritative owner: Telegram Health / TP_HG. Only a NEW
            # health_status=='ok' write (which _tp_hg_update_status only
            # ever produces via an allow_recover=True path -- deep-check,
            # manual /tghealth reset, or a genuine FloodWait-cooldown
            # retry success; the ordinary sticky-downgrade guard NEVER
            # advances last_ok_at while BLOCKED) proves TP_HG itself
            # cleared the block. A merely-live process can never satisfy
            # this alone.
            last_ok_at = str(hrow.get("last_ok_at") or "")
            cheap = str(hrow.get("health_status") or "").lower() == "ok" and _newer(last_ok_at)
            if not cheap:
                return False
            return await _hnv2_rate_limited_ready_probe(key)

        if family in (HNV2_FAMILY_PROXY_AUTH_FAILED, HNV2_FAMILY_PROXY_UNAVAILABLE):
            state = str(mrow.get("auth_guard_state") or "").lower()
            last_ok_at = str(mrow.get("auth_guard_last_ok_at") or "")
            age = ev.get("age_proxy")
            cheap = state in ("ok", "direct") and _newer(last_ok_at) and age is not None and age <= HNV2_PROXY_MAX_AGE_SEC
            if not cheap:
                return False
            return await _hnv2_rate_limited_ready_probe(key)

        if family == HNV2_FAMILY_WORKER_CRASH:
            phase = str(ss.get("phase") or "").lower()
            updated_at = str(ss.get("updated_at") or "")
            cheap = proc == "running" and phase == "running" and _newer(updated_at)
            if not cheap:
                return False
            return await _hnv2_rate_limited_ready_probe(key)

        if family == HNV2_FAMILY_WORKER_STUCK_STARTING:
            phase = str(ss.get("phase") or "").lower()
            updated_at = str(ss.get("updated_at") or "")
            # N-4: no higher-priority, currently-unresolved cause may be
            # active right now -- HNV2_FAMILY_OK/WORKER_STUCK_STARTING/
            # UNKNOWN are all acceptable (this incident's own family
            # reappearing, or an inconclusive tick, is not a "different,
            # more severe, currently-active cause").
            no_higher_priority_cause = current_family in ("", HNV2_FAMILY_OK, HNV2_FAMILY_WORKER_STUCK_STARTING, HNV2_FAMILY_UNKNOWN)
            cheap = phase == "running" and _newer(updated_at) and no_higher_priority_cause
            if not cheap:
                return False
            return await _hnv2_rate_limited_ready_probe(key)

        if family == HNV2_FAMILY_NETWORK_TIMEOUT:
            state = str(mrow.get("auth_guard_state") or "").lower()
            checked_or_ok_at = str(mrow.get("auth_guard_checked_at") or mrow.get("auth_guard_last_ok_at") or "")
            age = ev.get("age_proxy")
            return bool(
                state in ("ok", "direct") and _newer(checked_or_ok_at)
                and age is not None and age <= HNV2_PROXY_MAX_AGE_SEC
            )

        if family == HNV2_FAMILY_SQLITE_LOCK:
            # runtime_ready is FORBIDDEN as the sole basis here, and is not
            # consulted for this family AT ALL -- there is no persistent
            # SQLite-lock health source in the current architecture (only
            # inline retry-on-"database is locked" at the write sites).
            # The only affirmative evidence available: a write to the
            # central DB has visibly succeeded SINCE the incident opened
            # (last_check_at advanced past opened_at), AND no fresh lock
            # marker is present anywhere in the current tick's evidence.
            #
            # N-5 correction (post-independent-review): ss.last_exit_error
            # is STICKY (D1) -- it stays "database is locked" forever after
            # the ORIGINAL exit that opened THIS incident, even once the
            # worker has recovered and run indefinitely without exiting
            # again (nothing ever overwrites it except a NEW 'exited'
            # write). Without a freshness check, has_fresh_lock_marker would
            # incorrectly stay True forever, permanently blocking recovery
            # even after last_check_at genuinely advances -- exactly the
            # "stale negative evidence incorrectly persisting forever"
            # failure mode this family must avoid. A lock marker only
            # counts as a CURRENTLY-blocking signal if its own timestamp
            # (last_exit_at) is strictly newer than opened_at -- i.e. a NEW
            # lock-causing exit happened SINCE this incident opened, not
            # the same historical exit that caused it to open. This does
            # NOT fail open: if no fresh evidence exists either way (no new
            # exit, last_check_at hasn't advanced), the incident correctly
            # stays OPEN.
            last_check_at = str(hrow.get("last_check_at") or "")
            last_exit_at = str(ss.get("last_exit_at") or "")
            lock_text = f"{str(ss.get('last_exit_error') or '').lower()} {str(hrow.get('error_text') or '').lower()}"
            has_lock_text = any(m in lock_text for m in _HNV2_SQLITE_LOCK_MARKS)
            has_fresh_lock_marker = has_lock_text and _newer(last_exit_at)
            return bool(_newer(last_check_at)) and not has_fresh_lock_marker

        if family == HNV2_FAMILY_HEALTH_MISSING_STALE:
            acc_fresh = _newer(hrow.get("last_check_at")) and (ev.get("age_account") is not None and ev.get("age_account") <= HNV2_ACCOUNT_MAX_AGE_SEC)
            prox_fresh = _newer(mrow.get("auth_guard_last_ok_at")) and (ev.get("age_proxy") is not None and ev.get("age_proxy") <= HNV2_PROXY_MAX_AGE_SEC)
            if evidence_key == "account":
                return acc_fresh
            if evidence_key == "proxy":
                return prox_fresh
            return acc_fresh and prox_fresh  # 'both' -- updating only ONE source is not enough

        if family == HNV2_FAMILY_RECOVERY_FLAP:
            return int(ev.get("flap_new") or 0) == 0 and str(ev.get("last_verify") or "none") == "ok"

        return False
    except Exception:
        return False


async def _hnv2_notify(key: str, sig: str, family: str, detail: str, *, is_reminder: bool, is_recovery: bool = False, confidence: str = "certain") -> None:
    """Writes ONE panel_notifications row (kind='health_agg' -- the SAME
    kind the legacy aggregator already used; Phase 7's button-wiring keys
    off this kind, so no schema change is needed to attach action
    buttons). Body always carries the 'manager: {key}' / 'family: {family}'
    machine-readable lines the button builder parses (approved plan I.4),
    plus (HNV2 N-2 correction, post-independent-review) a 'confidence:'
    line -- panel_bot.py's button builder reads it to strip restart/
    relogin/auth-changing buttons whenever confidence != 'certain' (plan
    section I.2.1). Never raises -- a failed notify must never block the
    incident-state transition that already persisted by the time this is
    called."""
    try:
        conf = str(confidence or "certain")
        if is_recovery:
            title = f"✅ Health V2: {key} восстановлен"
            body_lines = [title, f"manager: {key}", f"family: {family}", f"Инцидент закрыт: {sig}"]
        else:
            base_title = f"\U0001fa7a Health V2: {key} — {family}"
            title = f"🔁 {base_title} (повтор)" if is_reminder else base_title
            action = _HNV2_RECOMMENDED_ACTION.get(family, "Провести безопасную диагностику.")
            body_lines = [
                title,
                f"manager: {key}",
                f"family: {family}",
                f"confidence: {conf}",
                f"Причина: {detail or family}",
                "Что делать:",
                action,
            ]
        body = "\n".join(filter(None, body_lines)).rstrip()
        now_iso = _health_agg_utc_now_iso()
        async with aiosqlite.connect(TPILOT_DB_PATH) as _db:
            await _db.execute(
                "INSERT INTO panel_notifications(kind,title,body,status,created_at,updated_at) "
                "VALUES(?,?,?,?,?,?)",
                ("health_agg", str(title or ""), str(body or ""), "new", now_iso, now_iso),
            )
            await _db.commit()
    except Exception:
        pass


async def _hnv2_maybe_notify(key: str, sig: str, family: str, detail: str, *, is_reminder: bool, confidence: str = "certain") -> None:
    """Daily-cap quota claim BEFORE the incident notify-claim (approved plan
    section E) -- if the incident claim ran first and quota then denied,
    last_notified_at would already be burned, pushing the next legitimate
    alert 6 hours out. Refunds the quota unit if the incident claim then
    loses its own race. FAILS CLOSED on a timezone resolution error (never
    falls back to OS-local -- storage.w3_business_date raises rather than
    silently drifting)."""
    try:
        try:
            kyiv_date = _repl_storage.w3_business_date("Europe/Kyiv")
        except Exception:
            _health_agg_append_log({"event": "hnv2_quota_tz_error", "manager_key": key, "signature": sig})
            return
        granted, sent_today = _repl_storage.health_notify_quota_claim(
            key, sig, kyiv_date, max_per_day=HNV2_DAILY_PROBLEM_CAP, db_path=TPILOT_DB_PATH,
        )
        if not granted:
            _health_agg_append_log({"event": "hnv2_suppressed_daily_cap", "manager_key": key, "signature": sig, "sent_today": sent_today})
            return
        claim = _repl_storage.health_incident_claim_notify(
            key, sig, repeat_after_sec=HEALTH_INCIDENT_REMINDER_INTERVAL_SEC, db_path=TPILOT_DB_PATH,
        )
        if claim is None:
            try:
                _repl_storage.health_notify_quota_refund(key, sig, kyiv_date, db_path=TPILOT_DB_PATH)
            except Exception:
                pass
            return
        await _hnv2_notify(key, sig, family, detail, is_reminder=(claim == "reminder"), is_recovery=False, confidence=confidence)
    except Exception:
        pass


async def _hnv2_drive_observed_open(key: str, sig: str, family: str, detail: str, confidence: str = "certain") -> None:
    """OBSERVED -> PENDING_CONFIRMATION -> OPEN -> OPEN_REMINDER (approved
    plan section D). Reads the row's CURRENT status FIRST and branches
    explicitly -- calling health_incident_v2_observe on an already-'open'
    row would incorrectly reset it back to 'observed' (that storage
    primitive's own fresh-vs-repeat detection only distinguishes
    status!='observed', which 'open' also satisfies).

    `confidence` (HNV2 N-2 correction, post-independent-review): the
    CURRENT classifier confidence for this tick, threaded through to
    _hnv2_notify so the notification body carries a 'confidence:' line the
    AdminBot button builder (panel_bot.py) reads to degrade unsafe
    action buttons per the approved plan's confidence-degradation
    invariant (section I.2.1) -- e.g. a 'probable' proxy_unavailable must
    never offer 🔁 Перезапустить."""
    try:
        _repl_storage.ensure_health_incidents_v2_columns(TPILOT_DB_PATH)
        existing = _repl_storage.health_incident_v2_get(key, sig, db_path=TPILOT_DB_PATH)
        existing_status = str((existing or {}).get("status") or "")

        if existing_status == "open":
            await _hnv2_maybe_notify(key, sig, family, detail, is_reminder=True, confidence=confidence)
            return

        if existing_status == "recovery_pending":
            # The SAME family/signature reappeared before stability
            # elapsed -- flap back to OPEN WITHOUT touching
            # last_notified_at (plan D: no new notification here -- this
            # is the anti-flap-spam core of the whole state machine).
            _repl_storage.health_incident_v2_set_state(key, sig, status="open", db_path=TPILOT_DB_PATH, recovery_pending_since="")
            return

        # existing_status in ('', 'resolved', 'observed') -- safe to
        # observe/accumulate toward confirmation.
        confirm_sec, confirm_ticks = _HNV2_CONFIRM_TABLE.get(family, (0, 1))
        row = _repl_storage.health_incident_v2_observe(key, sig, family=family, detail=detail, confirm_sec=confirm_sec, db_path=TPILOT_DB_PATH)
        observed_count = int(row.get("observed_count") or 0)
        confirm_due_at = str(row.get("confirm_due_at") or "")
        now_iso = datetime.now(timezone.utc).replace(microsecond=0).isoformat()
        confirmed = observed_count >= confirm_ticks and (not confirm_due_at or now_iso >= confirm_due_at)
        if not confirmed:
            return
        _repl_storage.health_incident_upsert_open(key, sig, db_path=TPILOT_DB_PATH)
        await _hnv2_maybe_notify(key, sig, family, detail, is_reminder=False, confidence=confidence)
    except Exception:
        pass


async def _hnv2_advance_recovery(key: str, sig: str, family: str, status: str, positive: bool, current_tip_watermark: str) -> None:
    """OPEN/OPEN_REMINDER -> RECOVERY_PENDING -> RESOLVED->REARMED, or a
    flap back to OPEN if `positive` turns False again mid-window (approved
    plan section D). `positive` is the OWNERSHIP-MATRIX verdict for this
    SPECIFIC family/signature -- callers must never pass a generic
    "classifier says something else now" as `positive`."""
    try:
        stable_sec = _hnv2_stable_sec_for_family(family)
        now_iso = datetime.now(timezone.utc).replace(microsecond=0).isoformat()

        if status == "open":
            if not positive:
                return
            _repl_storage.health_incident_v2_set_state(key, sig, status="recovery_pending", db_path=TPILOT_DB_PATH, recovery_pending_since=now_iso)
            return

        if status == "recovery_pending":
            if not positive:
                _repl_storage.health_incident_v2_set_state(key, sig, status="open", db_path=TPILOT_DB_PATH, recovery_pending_since="")
                return
            row = _repl_storage.health_incident_v2_get(key, sig, db_path=TPILOT_DB_PATH)
            since = str((row or {}).get("recovery_pending_since") or "")
            if not since:
                _repl_storage.health_incident_v2_set_state(key, sig, status="recovery_pending", db_path=TPILOT_DB_PATH, recovery_pending_since=now_iso)
                return
            since_dt = _tp_hg_parse_iso(since)
            elapsed = (_tp_utc_now() - since_dt).total_seconds() if since_dt is not None else None
            if elapsed is not None and elapsed >= stable_sec:
                resolved = _repl_storage.health_incident_v2_resolve_from_recovery_pending(key, sig, db_path=TPILOT_DB_PATH)
                if resolved:
                    if family == HNV2_FAMILY_RECOVERY_FLAP and current_tip_watermark:
                        try:
                            _repl_storage.health_incident_v2_set_watermark(key, sig, current_tip_watermark, db_path=TPILOT_DB_PATH)
                        except Exception:
                            pass
                    await _hnv2_notify(key, sig, family, "", is_reminder=False, is_recovery=True)
            return
    except Exception:
        pass


async def _hnv2_incident_step(key: str, mrow: dict, hrow: dict) -> None:
    """One manager's HNV2 tick: collect evidence, classify the CURRENT
    root cause, drive that family's OBSERVED->OPEN progression (PASS 1),
    then independently re-evaluate EVERY OTHER currently active hv2:*
    incident for this manager against its OWN family's authoritative
    recovery evidence (PASS 2 -- the Recovery Ownership Matrix, approved
    plan I.2.2). Never raises -- an exception here must never abort the
    aggregator's per-manager loop for OTHER managers (isolation, plan
    invariant: one manager's health state must never affect another's)."""
    try:
        key = registry_normalize_manager_key(key or "")
        if not key:
            return

        ss = _manager_recovery_read_start_status(key)
        ss_phase = str(ss.get("phase") or "").strip().lower()

        # Flap watermark: read-or-bootstrap the canonical recovery_flap
        # row's watermark, count new events since it.
        flap_sig = _hnv2_signature(HNV2_FAMILY_RECOVERY_FLAP, "flap")
        try:
            _repl_storage.ensure_health_incidents_v2_columns(TPILOT_DB_PATH)
            flap_row = _repl_storage.health_incident_v2_get(key, flap_sig, db_path=TPILOT_DB_PATH)
        except Exception:
            flap_row = None
        watermark = str((flap_row or {}).get("rearm_watermark") or "")
        flap_new, current_tip_watermark = _hnv2_count_new_recovery_events(key, watermark)
        if flap_row is None:
            # First-ever HNV2 tick for this manager -- establish the
            # watermark at the CURRENT tip (never 0), so pre-existing log
            # history can never manufacture a burst on first tick.
            try:
                _repl_storage.health_incident_v2_set_watermark(key, flap_sig, current_tip_watermark, db_path=TPILOT_DB_PATH)
            except Exception:
                pass
            flap_new = 0

        last_verify = _hnv2_last_spawn_verify(key)

        # proc: only probed when cheap evidence is inconclusive (perf
        # note, approved plan section G) -- phase in {starting, connected,
        # exited}, or an hv2:* incident is currently active for this
        # manager (needed to evaluate recovery in PASS 2 below). Otherwise
        # defaults to 'running' -- the steady-state case, where a genuinely
        # dead process would still eventually surface via the OTHER
        # evidence sources going stale (health_missing_stale).
        try:
            any_active = _repl_storage.health_incident_any_open_v2(key, db_path=TPILOT_DB_PATH)
        except Exception:
            any_active = False
        need_proc_probe = ss_phase in ("starting", "connected", "exited") or any_active
        proc = await _hnv2_process_state(key) if need_proc_probe else "running"

        ev = _hnv2_collect_evidence(key, mrow, hrow, ss, proc, flap_new, last_verify)
        cr = _hnv2_classify_root_cause(ev)

        current_sig = ""
        if cr.get("alertable") and not cr.get("deferred_to"):
            current_sig = _hnv2_signature(cr["family"], cr["evidence_key"])
            await _hnv2_drive_observed_open(key, current_sig, cr["family"], cr["detail"], cr.get("confidence") or "certain")

        try:
            active_rows = _repl_storage.health_incident_v2_list_active(key, db_path=TPILOT_DB_PATH)
        except Exception:
            active_rows = []
        for row in active_rows:
            sig = str(row.get("signature") or "")
            if not sig or sig == current_sig:
                continue   # already handled by PASS 1 this tick
            fam = str(row.get("family") or "") or (sig.split(":")[1] if sig.count(":") >= 2 else "")
            ekey = sig.split(":")[-1] if sig.count(":") >= 2 else ""
            opened_at = str(row.get("opened_at") or "")
            status = str(row.get("status") or "")
            if fam == HNV2_FAMILY_UNKNOWN:
                positive = (cr.get("family") == HNV2_FAMILY_OK)
            else:
                positive = await _hnv2_family_recovery_evidence(fam, ekey, ev, opened_at, key, current_family=cr.get("family"))
            await _hnv2_advance_recovery(key, sig, fam, status, positive, current_tip_watermark)
    except Exception:
        pass


_HNV2_BOOTSTRAP_DONE = False


async def _hnv2_bootstrap_once() -> None:
    """Runs exactly once per controller process lifetime (approved plan
    section K.4, step 2): silently resolves any PRE-EXISTING open legacy
    'recovery_flap'/'no_health_data' incidents -- the escalation call that
    used to open/re-open them (_health_incident_handle, invoked from the
    ORIGINAL _health_agg_once) is no longer reached from the HNV2 override
    below, so without this one-time cleanup a pre-deploy-open legacy row
    would sit open forever, never resolving. No recovery notification is
    sent for this -- it is a migration, not an observed recovery. The
    per-manager recovery_flap WATERMARK bootstrap (step 3) is handled
    lazily, per-manager, inside _hnv2_incident_step itself (its own
    `if flap_row is None` branch) -- not duplicated here."""
    global _HNV2_BOOTSTRAP_DONE
    if _HNV2_BOOTSTRAP_DONE:
        return
    _HNV2_BOOTSTRAP_DONE = True
    try:
        proxy_rows = await _health_agg_read_proxy_rows()
    except Exception:
        proxy_rows = []
    for row in proxy_rows:
        key = registry_normalize_manager_key(row.get("manager_key") or "")
        if not key:
            continue
        for legacy_sig in ("recovery_flap", "no_health_data"):
            try:
                _repl_storage.health_incident_resolve(key, legacy_sig, db_path=TPILOT_DB_PATH)
            except Exception:
                pass


_HNV2_PREV_AGG_ONCE = globals().get("_health_agg_once")


async def _health_agg_once() -> None:   # type: ignore[override]
    """HNV2 override (NOT a thin delegate) -- replicates every OTHER
    side effect of the original _health_agg_once (unified-status mapping,
    runtime/proxy_account_health.json + .log -- both still consumed by
    panel_bot's own health rendering and MUST stay byte-identical) via the
    SAME still-existing, untouched helper functions
    (_health_agg_read_proxy_rows/_health_agg_read_account_rows/
    _health_agg_map_status/_health_agg_tail_recovery_log/
    _health_agg_tail_catchup_log/_health_agg_append_log/
    _health_agg_write_json_summary/_HAGG_BUCKET_MAP), but REPLACES the one
    escalation/notify decision (the original's single
    `await _health_incident_handle(...)` call) with the HNV2 root-cause
    classifier + persistent state machine. This is deliberate, not an
    oversight: delegating wholesale to the original implementation would
    keep producing the exact misleading legacy recovery_flap/no_health_data
    alerts HNV2 exists to replace, running in parallel with HNV2's own --
    see _hnv2_bootstrap_once's docstring for the one-time migration this
    implies for any incident already open at deploy time.

    _health_incident_handle/_health_incident_notify themselves are NEVER
    called or redefined anywhere in the HNV2 block (health_incident_
    selftest.py's own static check continues to prove both remain
    singly-defined and untouched)."""
    if not HNV2_ENABLED:
        if callable(_HNV2_PREV_AGG_ONCE):
            await _HNV2_PREV_AGG_ONCE()
        return

    await _hnv2_bootstrap_once()

    now_utc = _health_agg_utc_now_iso()
    proxy_rows = await _health_agg_read_proxy_rows()
    account_map = await _health_agg_read_account_rows()

    summary_counts: Dict[str, int] = {
        "ok": 0, "warning": 0, "bad_proxy": 0,
        "auth_session": 0, "limit_floodwait": 0, "unknown": 0,
    }
    managers_summary: Dict[str, Any] = {}

    for row in proxy_rows:
        key = registry_normalize_manager_key(row.get("manager_key") or "")
        if not key:
            continue

        account_row = account_map.get(key) or {}
        start_status = _manager_recovery_read_start_status(key)
        recoveries = _health_agg_tail_recovery_log(key, HEALTH_AGG_RECOVERY_WINDOW_MIN)
        catchup = _health_agg_tail_catchup_log(key)

        unified = _health_agg_map_status(row, account_row, start_status, recoveries)

        proxy_state = str(row.get("auth_guard_state") or "").strip()
        proxy_error = str(row.get("auth_guard_error") or row.get("auth_guard_last_fail_reason") or "").strip()[:200]
        account_state = str(account_row.get("health_status") or "").strip()
        acct_err_class = str(account_row.get("error_class") or "").strip()
        acct_err_text = str(account_row.get("error_text") or "").strip()[:200]
        start_phase = str(start_status.get("phase") or "").strip()
        start_rc = str(start_status.get("reason_class") or "").strip()
        last_proxy_ok = str(row.get("auth_guard_last_ok_at") or "").strip()
        last_acct_ok = str(account_row.get("last_ok_at") or "").strip()
        last_check = str(account_row.get("last_check_at") or "").strip()

        _health_agg_append_log({
            "time_utc": now_utc, "manager_key": key, "unified_status": unified,
            "proxy_state": proxy_state, "proxy_error": proxy_error,
            "account_state": account_state, "account_error_class": acct_err_class,
            "account_error_text": acct_err_text, "recoveries_in_window": recoveries,
            "recovery_window_minutes": HEALTH_AGG_RECOVERY_WINDOW_MIN,
            "start_phase": start_phase, "start_reason_class": start_rc,
            "last_proxy_ok_at": last_proxy_ok, "last_account_ok_at": last_acct_ok,
            "last_check_at": last_check,
            "escalated": None, "notify_skipped_reason": "hnv2_owns_escalation",
        })

        reason_line = (proxy_error or acct_err_text or acct_err_class or start_rc or "").strip()[:120]
        managers_summary[key] = {
            "unified_status": unified, "proxy_state": proxy_state, "account_state": account_state,
            "recoveries_in_window": recoveries, "start_phase": start_phase,
            "last_proxy_ok_at": last_proxy_ok, "last_account_ok_at": last_acct_ok,
            "reason": reason_line, "catchup": catchup,
        }

        bucket_key = _HAGG_BUCKET_MAP.get(unified, "unknown")
        summary_counts[bucket_key] = summary_counts.get(bucket_key, 0) + 1

        try:
            await _hnv2_incident_step(key, row, account_row)
        except Exception:
            continue

    overall_ok = (
        summary_counts.get("bad_proxy", 0) == 0
        and summary_counts.get("auth_session", 0) == 0
        and summary_counts.get("limit_floodwait", 0) == 0
    )
    _health_agg_write_json_summary({
        "time_utc": now_utc, "ok": overall_ok, "summary": summary_counts, "managers": managers_summary,
    })


# --- HNV2 Phase 7: family label for TP_HG alerts + read-only /hnv2_diag ---

def _hnv2_tg_health_family(status: str, error_class: str) -> str:
    """Derives an HNV2 family label for a telegram_health-kind alert body
    (approved plan section I.4) -- these alerts are built and owned
    entirely by _tp_hg_build_alert_text/TP_HG, not by HNV2's own
    classifier/state machine; this is purely a DISPLAY label so the
    AdminBot button builder (Phase 7, panel_bot.py) can pick the right
    button set for a kind='telegram_health' notification without a new DB
    read. Reuses the existing _tp_hg_restriction_family (main.py) --
    introduces no new classification logic of its own."""
    try:
        fam = _tp_hg_restriction_family(status=status, error_class=error_class)
    except Exception:
        return HNV2_FAMILY_UNKNOWN
    return {
        _TP_HG_FAMILY_PEERFLOOD: HNV2_FAMILY_PEERFLOOD,
        _TP_HG_FAMILY_FLOODWAIT: HNV2_FAMILY_FLOODWAIT,
        _TP_HG_FAMILY_BLOCKED: HNV2_FAMILY_ACCOUNT_BLOCKED,
    }.get(fam, HNV2_FAMILY_UNKNOWN)


_HNV2_DIAG_SECRET_PATTERNS = (
    re.compile(r"://[^/\s@]+:[^/\s@]+@", re.IGNORECASE),   # scheme://user:pass@
    # HNV2 F-6 correction (post-independent-review): the original pattern
    # set covered generic key=value forms but MISSED TPilot's own native
    # proxy string formats (proxy_parser.py's supported inputs), so a raw
    # "1.2.3.4:1080:login:password" or "login:password@1.2.3.4:1080"
    # embedded in an exception message (auth_guard_error/error_text/
    # last_exit_error) passed through unredacted. Anchored on an IPv4-shaped
    # host (TPilot proxies are always IP-based) so this cannot false-positive
    # on ordinary hostnames/timestamps/version strings the way a bare
    # colon-count heuristic would. Whole matched credential token is
    # replaced, not just the password half (host:port kept, so the report is
    # still useful for narrowing down which proxy is implicated).
    re.compile(r"\b(?:\d{1,3}\.){3}\d{1,3}:\d{2,5}:[^\s:]+:[^\s@]+"),  # host:port:login:password
    # login:password@host:port (no scheme). \S+ (greedy, whitespace-bounded)
    # rather than an explicit [^@]+ credential class: a password MAY itself
    # contain '@' (e.g. "P@ssw0rd!"), and greedy backtracking naturally finds
    # the RIGHTMOST '@' immediately before a valid host:port -- the same
    # right-anchored strategy proxy_parser.py's own mask_proxy() uses via
    # body.rsplit("@", 1) for exactly this reason.
    re.compile(r"\S+@(?:\d{1,3}\.){3}\d{1,3}:\d{2,5}\b"),
    re.compile(r"(?i)\bpassword\s*[:=]\s*\S+"),
    re.compile(r"(?i)\btoken\s*[:=]\s*\S+"),
    re.compile(r"(?i)\bapi[_-]?key\s*[:=]\s*\S+"),
    re.compile(r"(?i)\bsecret\s*[:=]\s*\S+"),
    re.compile(r"(?i)\b(?:login[_ ]?code|auth[_ ]?code|confirmation[_ ]?code|pin)\s*[:=]?\s*\d{3,8}\b"),
)


def _hnv2_diag_scrub(text: Any) -> str:
    """Defense-in-depth redaction for /hnv2_diag output. Every field this
    command surfaces already comes from sources the project's own hard
    invariants guarantee never carry a raw secret (manager_telegram_
    health.error_text/error_class, managers.auth_guard_error, start_
    status.json's reason_class/error -- none of these paths are ever fed a
    raw proxy password or API key; see CLAUDE.md's own invariant list).
    This scrub exists purely as a second layer, not the primary control."""
    t = str(text or "")
    for pat in _HNV2_DIAG_SECRET_PATTERNS:
        t = pat.sub("[scrubbed]", t)
    return t[:400]


def _hnv2_diag_row(raw: Any) -> tuple:
    """HNV2 N-1 correction (post-independent-review): normalizes a
    *_readonly() storage result into (row_or_None, schema_missing: bool).
    The readonly getters signal an absent table/columns with the sentinel
    {'_schema_missing': True} instead of creating them -- this unwraps that
    sentinel so the rest of _hnv2_diag_text never has to special-case it."""
    if isinstance(raw, dict) and raw.get("_schema_missing"):
        return None, True
    return raw, False


async def _hnv2_diag_text(manager_key: str) -> str:
    """STRICTLY READ-ONLY. No DB write, no network call, no Telegram
    operation, no process spawn/stop, no restart, and -- HNV2 N-1 correction
    (post-independent-review) -- no schema ensure/migration helper either
    (health_incident_v2_get_readonly/health_notify_quota_get_readonly, NEVER
    the ensure_*-calling variants nor health_notify_quota_claim). Only reads
    already-collected evidence via the SAME functions the aggregator tick
    itself uses (_health_agg_read_proxy_rows/_health_agg_read_account_rows/
    _manager_recovery_read_start_status) and the classifier -- and formats
    it for an operator. Never raises; returns a diagnostic-safe error string
    on any failure. If the HNV2 DB schema has never been migrated yet (a
    brand-new/pre-first-tick DB), reports that plainly instead of creating
    it."""
    try:
        key = registry_normalize_manager_key(manager_key or "")
        if not key:
            return "Пустой ключ менеджера."

        proxy_rows = await _health_agg_read_proxy_rows()
        mrow = next((r for r in proxy_rows if registry_normalize_manager_key(r.get("manager_key") or "") == key), {})
        account_map = await _health_agg_read_account_rows()
        hrow = account_map.get(key) or {}
        ss = _manager_recovery_read_start_status(key)

        proc = await _hnv2_process_state(key)
        flap_sig = _hnv2_signature(HNV2_FAMILY_RECOVERY_FLAP, "flap")
        schema_missing = False
        try:
            flap_row, sm = _hnv2_diag_row(_repl_storage.health_incident_v2_get_readonly(key, flap_sig, db_path=TPILOT_DB_PATH))
            schema_missing = schema_missing or sm
        except Exception:
            flap_row = None
        watermark = str((flap_row or {}).get("rearm_watermark") or "")
        flap_new, _tip = _hnv2_count_new_recovery_events(key, watermark)
        last_verify = _hnv2_last_spawn_verify(key)

        ev = _hnv2_collect_evidence(key, mrow, hrow, ss, proc, flap_new, last_verify)
        cr = _hnv2_classify_root_cause(ev)
        sig = _hnv2_signature(cr["family"], cr["evidence_key"])

        try:
            incident, sm = _hnv2_diag_row(_repl_storage.health_incident_v2_get_readonly(key, sig, db_path=TPILOT_DB_PATH))
            schema_missing = schema_missing or sm
        except Exception:
            incident = None

        try:
            kyiv_date = _repl_storage.w3_business_date("Europe/Kyiv")
            quota_row, sm = _hnv2_diag_row(_repl_storage.health_notify_quota_get_readonly(key, sig, kyiv_date, db_path=TPILOT_DB_PATH))
            schema_missing = schema_missing or sm
        except Exception:
            kyiv_date, quota_row = "", None

        def _age_str(seconds: Any) -> str:
            if seconds is None:
                return "n/a"
            try:
                return f"{float(seconds):.0f}s"
            except Exception:
                return "n/a"

        lines = [
            "🧪 HNV2 diag (read-only)",
            f"manager: {key}",
            "",
            "-- start_status.json --",
            f"phase: {ss.get('phase') or '_'}  updated_at: {ss.get('updated_at') or '_'}",
            f"respawn_seq: {ss.get('respawn_seq') or 0}  pid: {ss.get('pid') or '_'}",
            f"last_exit_reason_class: {ss.get('last_exit_reason_class') or '_'}",
            f"last_exit_error: {_hnv2_diag_scrub(ss.get('last_exit_error'))}",
            "",
            "-- process probe --",
            f"proc: {proc}",
            "",
            "-- manager_telegram_health --",
            f"health_status: {hrow.get('health_status') or '_'}  age(last_check_at): {_age_str(ev.get('age_account'))}",
            f"error_class: {_hnv2_diag_scrub(hrow.get('error_class'))}",
            f"error_text: {_hnv2_diag_scrub(hrow.get('error_text'))}",
            "",
            "-- managers.auth_guard_* --",
            f"auth_guard_state: {mrow.get('auth_guard_state') or '_'}  age(last_ok_at): {_age_str(ev.get('age_proxy'))}",
            f"auth_guard_error: {_hnv2_diag_scrub(mrow.get('auth_guard_error') or mrow.get('auth_guard_last_fail_reason'))}",
            "",
            "-- recovery flap --",
            f"flap_new (post-watermark, {HEALTH_AGG_RECOVERY_WINDOW_MIN}min window): {flap_new}",
            f"last_spawn_verify: {last_verify}",
            "",
            "-- classification --",
            f"family: {cr['family']}  confidence: {cr['confidence']}  alertable: {cr['alertable']}",
            f"deferred_to: {cr.get('deferred_to') or '_'}",
            f"detail: {_hnv2_diag_scrub(cr.get('detail'))}",
            f"signature: {sig}",
            "",
            "-- incident state --",
        ]
        if schema_missing:
            # HNV2 N-1 correction: the read-only getters never create the
            # HNV2 schema themselves -- report the fact plainly instead.
            lines.append("health V2 schema unavailable / not initialized (no write has happened yet -- диагностика ничего не создаёт)")
        elif incident:
            lines.append(f"status: {incident.get('status')}  observed_count: {incident.get('observed_count')}  opened_at: {incident.get('opened_at') or '_'}")
            lines.append(f"recovery_pending_since: {incident.get('recovery_pending_since') or '_'}  reminder_count: {incident.get('reminder_count')}")
        else:
            lines.append("нет активного/предыдущего hv2:-инцидента для этой сигнатуры")
        lines.append("")
        lines.append(f"-- quota (Kyiv {kyiv_date or '_'}) --")
        if schema_missing:
            lines.append(f"sent_today: n/a (schema not initialized) / {HNV2_DAILY_PROBLEM_CAP}")
        elif quota_row:
            lines.append(f"sent_today: {quota_row.get('sent_count')} / {HNV2_DAILY_PROBLEM_CAP}")
        else:
            lines.append(f"sent_today: 0 / {HNV2_DAILY_PROBLEM_CAP} (no quota row yet)")
        return "\n".join(lines).rstrip()
    except Exception as exc:
        return f"Диагностика не удалась: {type(exc).__name__}"


_HNV2_PREV_PANEL_EXEC = globals().get("_panel_execute_command_text")


async def _panel_execute_command_text(
    command_text: str, *, requested_by: int = 0, source_chat_id: int = 0, response_chat_id: int = 0
) -> Dict[str, Any]:
    cmd, _, args = str(command_text or "").strip().partition(" ")
    if cmd == "/hnv2_diag":
        key = args.strip()
        if not key:
            return {"ok": False, "result_text": "Использование: /hnv2_diag <manager_key>"}
        text = await _hnv2_diag_text(key)
        return {"ok": True, "result_text": text}
    if callable(_HNV2_PREV_PANEL_EXEC):
        try:
            return await _HNV2_PREV_PANEL_EXEC(command_text, requested_by=requested_by, source_chat_id=source_chat_id, response_chat_id=response_chat_id)
        except TypeError:
            try:
                return await _HNV2_PREV_PANEL_EXEC(command_text, requested_by=requested_by)
            except TypeError:
                return await _HNV2_PREV_PANEL_EXEC(command_text)
    return {"ok": False, "result_text": f"Команда не поддерживается: {cmd}"}

