async def _panel_prepared_card_command(args: str, *, requested_by: int = 0) -> str:
    """/prepared_card <key> -- READ-ONLY. repository.get_prepared already
    excludes proxy_username/proxy_password from its view model."""
    key = registry_normalize_manager_key(str(args or "").strip())
    if not key:
        return _repl3_json_result({"ok": False, "error_class": "bad_args", "error_text": "usage: /prepared_card <key>"})
    row = _prepared_accounts_repository.get_prepared(key)
    if not row:
        return _repl3_json_result({"ok": False, "error_class": "not_found", "error_text": f"Подготовленный аккаунт не найден: {key}"})
    return _repl3_json_result({"ok": True, "item": row})


async def _panel_prepared_delete_command(args: str, *, requested_by: int = 0) -> str:
    """/prepared_delete <key> -- delegates to service.delete_prepared, which
    itself only calls the injected _manager_delete_full_core (the SAME
    canonical delete every other manager uses, incl. Phase 4's
    prepared_accounts side-row cleanup) -- no new delete engine."""
    key = registry_normalize_manager_key(str(args or "").strip())
    if not key:
        return _repl3_json_result({"ok": False, "error_class": "bad_args", "error_text": "usage: /prepared_delete <key>"})
    prep_service = _prepared_accounts_pkg.get_service()
    result = await prep_service.delete_prepared(key, requested_by=int(requested_by or 0), get_manager_row=_prep_get_manager_row, delete_manager=_manager_delete_full_core)
    return _repl3_json_result(result)
